# PASS 0 browser lifecycle.
#
# Successful NVR / Discreet / Dome import browsers are intentionally retained
# after the final Import confirmation. PASS 0 waits until ALL requested imports
# are submitted, keeps all those browser windows open for 10 more seconds, then
# closes every retained browser together before starting the 50-second
# processing/reboot wait.
PASS0_IMPORT_BROWSER_REGISTRY_LOCK = threading.Lock()
PASS0_IMPORT_BROWSER_REGISTRY = []


def retain_pass0_import_browser(driver, ip, source_sheet):
    """Keep one successful PASS 0 Edge session alive until the shared barrier."""
    if driver is None:
        return

    with PASS0_IMPORT_BROWSER_REGISTRY_LOCK:
        PASS0_IMPORT_BROWSER_REGISTRY.append(
            {
                "driver": driver,
                "ip": str(ip),
                "source_sheet": str(source_sheet),
            }
        )

    print(
        f"[PASS 0 BROWSER] Retaining Edge for {ip} ({source_sheet}) "
        "through the shared 150-second processing/reboot wait; all retained Edge browsers will then be closed before readiness checks."
    )


def close_all_pass0_import_browsers():
    """Close every PASS 0 browser retained after a successful import."""
    with PASS0_IMPORT_BROWSER_REGISTRY_LOCK:
        retained = list(PASS0_IMPORT_BROWSER_REGISTRY)
        PASS0_IMPORT_BROWSER_REGISTRY.clear()

    if not retained:
        print("[PASS 0 BROWSER] No retained PASS 0 browsers to close.")
        return 0

    print(
        f"[PASS 0 BROWSER] Closing {len(retained)} retained PASS 0 "
        "browser window(s) now."
    )

    closed = 0

    for item in retained:
        driver = item.get("driver")
        ip = item.get("ip", "")
        source_sheet = item.get("source_sheet", "")

        try:
            driver.quit()
            closed += 1
            print(
                f"[PASS 0 BROWSER] Closed Edge for {ip} ({source_sheet})."
            )
        except Exception as error:
            # A device may already be rebooting, which can also tear down the
            # browser session. That is acceptable after the 10-second grace.
            print(
                f"[PASS 0 BROWSER WARNING] Could not cleanly close Edge for "
                f"{ip} ({source_sheet}): {error}"
            )

    return closed


class DeviceParameterImportFailedError(RuntimeError):
    """Raised only when the Hikvision UI explicitly reports Import Failed."""


class CameraConfigTransientImportError(RuntimeError):
    """Retryable browser/file-picker failure during PASS 0 camera import."""


def is_transient_camera_config_import_error(error):
    """
    Return True for temporary camera PASS 0 UI/file-picker failures that should
    be retried from a fresh Edge session.

    These are NOT treated as final device/configuration errors.
    """
    message = str(error or "").strip().lower()

    retryable_patterns = [
        "camera file picker opened, but the configuration file could not be assigned",
        "camera configuration file could not be assigned",
        "native windows file open dialog",
        "windows open dialog",
        "device parameter browse/folder control",
        "device parameter browse",
        "file picker",
        "file selection",
        "import button did not become enabled",
        "device parameter import button did not become enabled",
        "stale element reference",
        "element click intercepted",
        "element not interactable",
        "detached shadow root",
        "target window already closed",
        "no such window",
    ]

    return any(
        pattern in message
        for pattern in retryable_patterns
    )


def _device_config_import_failure_text_matches(value):
    normalized = re.sub(
        r"\s+",
        " ",
        str(value or ""),
    ).strip().lower()

    if not normalized:
        return False

    patterns = [
        "import failed",
        "import failure",
        "failed to import",
        "importing failed",
        "failed import",
        "configuration import failed",
        "config import failed",
        "device parameter import failed",
        "device parameters import failed",
        "parameter import failed",
        "file import failed",
    ]

    return any(
        pattern in normalized
        for pattern in patterns
    )


def find_visible_device_config_import_failure(
    driver,
    max_depth=5,
):
    """
    Find a visible Device Parameter Import Failed response.

    Supports:
      - NVR old UI,
      - Discreet old Angular UI,
      - Dome Element/Vue UI,
      - top document,
      - nested iframe/frame documents,
      - toast/dialog/table/div based messages.

    If found inside a frame, Selenium is left inside that frame so the caller
    can click the real popup action.
    """
    try:
        driver.switch_to.default_content()
    except Exception:
        pass

    search_script = r"""
        function visible(element) {
            if (!element || !element.isConnected) return false;

            const style = window.getComputedStyle(element);
            const rect = element.getBoundingClientRect();

            return (
                style.display !== "none" &&
                style.visibility !== "hidden" &&
                Number(style.opacity || "1") !== 0 &&
                rect.width > 0 &&
                rect.height > 0
            );
        }

        function normalize(value) {
            return String(value || "")
                .replace(/\s+/g, " ")
                .trim()
                .toLowerCase();
        }

        function importFailed(value) {
            const text = normalize(value);

            const patterns = [
                "import failed",
                "import failure",
                "failed to import",
                "importing failed",
                "failed import",
                "configuration import failed",
                "config import failed",
                "device parameter import failed",
                "device parameters import failed",
                "parameter import failed",
                "file import failed"
            ];

            return patterns.some(
                (pattern) => text.includes(pattern)
            );
        }

        const selectors = [
            ".el-message-box",
            ".el-message",
            ".el-notification",
            ".el-dialog",
            ".el-drawer",
            ".modal",
            ".modal-dialog",
            ".aui_dialog",
            ".ui-dialog",
            ".layui-layer",
            ".dialog",
            ".window",
            ".popup",
            ".popbox",
            ".msgbox",
            ".message-box",
            "[role='dialog']",
            "[role='alert']",
            "table",
            "tbody",
            "tr",
            "td",
            "body > div",
            "div",
            "span",
            "p"
        ];

        const candidates = [];

        for (
            const element of document.querySelectorAll(
                selectors.join(",")
            )
        ) {
            if (!visible(element)) continue;

            const text = normalize(
                element.innerText ||
                element.textContent
            );

            if (!importFailed(text)) continue;

            const rect =
                element.getBoundingClientRect();

            candidates.push({
                element: element,
                text: text,
                area: rect.width * rect.height
            });
        }

        if (!candidates.length) {
            return null;
        }

        candidates.sort(
            (a, b) => a.area - b.area
        );

        return candidates[0];
    """

    def search(depth):
        try:
            result = driver.execute_script(
                search_script
            )
        except Exception:
            result = None

        if result:
            return result

        if depth >= max_depth:
            return None

        try:
            frames = driver.find_elements(
                By.CSS_SELECTOR,
                "iframe,frame",
            )
        except Exception:
            frames = []

        for frame_index in range(
            len(frames)
        ):
            try:
                current_frames = (
                    driver.find_elements(
                        By.CSS_SELECTOR,
                        "iframe,frame",
                    )
                )

                if (
                    frame_index
                    >= len(current_frames)
                ):
                    continue

                driver.switch_to.frame(
                    current_frames[
                        frame_index
                    ]
                )
            except Exception:
                continue

            found = search(
                depth + 1
            )

            if found:
                return found

            try:
                driver.switch_to.parent_frame()
            except Exception:
                try:
                    driver.switch_to.default_content()
                except Exception:
                    pass

        return None

    result = search(0)

    if result is None:
        try:
            driver.switch_to.default_content()
        except Exception:
            pass

    return result


def detect_and_dismiss_device_config_import_failure(
    driver,
    label="Device Parameter import",
):
    """
    Detect an explicit Hikvision Import Failed response.

    Returns:
        None -> no import-failure response visible.
        str  -> detected failure text.

    OK / Confirm / Close is clicked when present.
    """
    # Native browser alert.
    try:
        alert = driver.switch_to.alert
        alert_text = str(
            alert.text or ""
        )

        if _device_config_import_failure_text_matches(
            alert_text
        ):
            try:
                alert.accept()
            except Exception:
                pass

            normalized_alert = re.sub(
                r"\s+",
                " ",
                alert_text,
            ).strip()

            print(
                f"[IMPORT FAILED DETECTED] "
                f"{label}: "
                f"{normalized_alert}"
            )

            return alert_text

    except Exception:
        pass

    result = (
        find_visible_device_config_import_failure(
            driver
        )
    )

    if not result:
        return None

    failure_element = result.get(
        "element"
    )

    failure_text = str(
        result.get(
            "text",
            "",
        )
    ).strip()

    print(
        f"[IMPORT FAILED DETECTED] "
        f"{label}: "
        f"{failure_text or 'Import Failed'}"
    )

    # Find an action inside the failure popup or a parent modal.
    try:
        action = driver.execute_script(
            r"""
            const original =
                arguments[0];

            function visible(element) {
                if (
                    !element ||
                    !element.isConnected
                ) {
                    return false;
                }

                const style =
                    window.getComputedStyle(
                        element
                    );

                const rect =
                    element.getBoundingClientRect();

                return (
                    !element.disabled &&
                    style.display !== "none" &&
                    style.visibility !== "hidden" &&
                    Number(
                        style.opacity || "1"
                    ) !== 0 &&
                    rect.width > 0 &&
                    rect.height > 0
                );
            }

            function normalize(value) {
                return String(value || "")
                    .replace(/\s+/g, " ")
                    .trim()
                    .toLowerCase();
            }

            function usable(element) {
                if (!visible(element)) {
                    return false;
                }

                const text = normalize(
                    element.innerText ||
                    element.value ||
                    element.textContent
                );

                return [
                    "ok",
                    "confirm",
                    "close"
                ].includes(text);
            }

            function findInside(container) {
                if (!container) {
                    return null;
                }

                return Array.from(
                    container.querySelectorAll(
                        "button," +
                        "input[type='button']," +
                        "input[type='submit']," +
                        "a,[role='button']," +
                        "[ng-click],.btn," +
                        ".el-button,.button"
                    )
                ).find(usable) || null;
            }

            let action =
                findInside(original);

            if (action) {
                return action;
            }

            let parent = original;

            for (
                let depth = 0;
                depth < 12 && parent;
                depth++
            ) {
                parent =
                    parent.parentElement;

                if (!parent) {
                    break;
                }

                action =
                    findInside(parent);

                if (action) {
                    return action;
                }
            }

            return null;
            """,
            failure_element,
        )
    except Exception:
        action = None

    if action is not None:
        clicked = False

        try:
            action.click()
            clicked = True
        except Exception:
            pass

        if not clicked:
            try:
                coords = driver.execute_script(
                    """
                    const r =
                        arguments[0]
                        .getBoundingClientRect();

                    return {
                        x:
                            r.left +
                            r.width / 2,
                        y:
                            r.top +
                            r.height / 2
                    };
                    """,
                    action,
                )

                x = float(
                    coords["x"]
                )
                y = float(
                    coords["y"]
                )

                driver.execute_cdp_cmd(
                    "Input.dispatchMouseEvent",
                    {
                        "type": "mouseMoved",
                        "x": x,
                        "y": y,
                    },
                )

                driver.execute_cdp_cmd(
                    "Input.dispatchMouseEvent",
                    {
                        "type": "mousePressed",
                        "x": x,
                        "y": y,
                        "button": "left",
                        "clickCount": 1,
                    },
                )

                driver.execute_cdp_cmd(
                    "Input.dispatchMouseEvent",
                    {
                        "type": "mouseReleased",
                        "x": x,
                        "y": y,
                        "button": "left",
                        "clickCount": 1,
                    },
                )

                clicked = True
            except Exception:
                pass

        if clicked:
            print(
                f"[IMPORT FAILED DETECTED] "
                f"{label}: failure popup "
                "dismissed."
            )

    try:
        driver.switch_to.default_content()
    except Exception:
        pass

    return (
        failure_text
        or "Import Failed"
    )


def scan_retained_pass0_import_browsers_for_failures():
    """
    Inspect retained PASS 0 browsers during the shared 10-second grace.

    A browser that reports Import Failed is removed from the registry and
    closed so the caller can automatically re-import that device.
    """
    with PASS0_IMPORT_BROWSER_REGISTRY_LOCK:
        snapshot = list(
            PASS0_IMPORT_BROWSER_REGISTRY
        )

    failures = []

    for item in snapshot:
        driver = item.get(
            "driver"
        )

        ip = str(
            item.get(
                "ip",
                "",
            )
        )

        source_sheet = str(
            item.get(
                "source_sheet",
                "",
            )
        )

        if driver is None:
            continue

        try:
            failure_text = (
                detect_and_dismiss_device_config_import_failure(
                    driver,
                    label=(
                        f"{ip} "
                        f"{source_sheet}"
                    ),
                )
            )
        except Exception:
            failure_text = None

        if not failure_text:
            continue

        with PASS0_IMPORT_BROWSER_REGISTRY_LOCK:
            PASS0_IMPORT_BROWSER_REGISTRY[:] = [
                existing
                for existing
                in PASS0_IMPORT_BROWSER_REGISTRY
                if (
                    existing.get(
                        "driver"
                    )
                    is not driver
                )
            ]

        try:
            driver.quit()
        except Exception:
            pass

        failures.append(
            {
                "ip": ip,
                "source_sheet": source_sheet,
                "detail": failure_text,
            }
        )

    return failures


