# Captured and confirmed endpoint family:
#   /ISAPI/ContentMgmt/StreamingProxy/channels/101
#   /ISAPI/ContentMgmt/StreamingProxy/channels/201
#   /ISAPI/ContentMgmt/StreamingProxy/channels/301
#   /ISAPI/ContentMgmt/StreamingProxy/channels/401
NVR_STREAMING_PROXY_ENDPOINT_BASE = (
    "/ISAPI/ContentMgmt/StreamingProxy/channels"
)

# Hikvision uses frame-rate values multiplied by 100 in the XML payload.
NVR_STREAM_FRAME_RATE_MULTIPLIER = 100

# =============================================================================
# CAPTURED DS-E08NI-Q2 STREAMINGPROXY PUT FORMAT
# =============================================================================
# Latest confirmed browser captures from the affected NVR include:
#   D1 Main 101 -> channelName=101, id=101, dynVideoInputChannelID=1
#   D1 Sub  102 -> channelName=102, id=102, dynVideoInputChannelID=1
#   D2 Main 201 -> channelName=201, id=201, dynVideoInputChannelID=2
#   D2 Sub  202 -> channelName=202, id=202, dynVideoInputChannelID=2
#
# Important firmware-specific details:
#   - root StreamingChannel keeps the ISAPI namespace
#   - <id> and <Video> may explicitly use xmlns="" in browser PUT bodies
#   - channelName follows the actual StreamingProxy stream ID
#   - dynVideoInputChannelID follows the physical NVR input number
#   - D1 browser payload exposes disabled G.711alaw Audio; D2 omits Audio
#   - main stream includes SmartCodec when H.265+ is OFF
#   - browser sends raw XML using:
#       Content-Type: application/x-www-form-urlencoded; charset=UTF-8
#   - HTTP 200 + statusCode=1 is success; riskPassword is advisory only
NVR_CAPTURED_MAIN_STREAM_AUDIO_ENABLED = "false"
NVR_CAPTURED_MAIN_STREAM_AUDIO_CODEC = "G.711alaw"

# Successful NVR web-UI StreamingProxy PUTs use Hikvision WebSession/session
# authentication. PASS 6 therefore creates a SessionLogin-v4 requests.Session
# and reuses it for StreamingProxy GET/PUT requests.
NVR_STREAM_USE_SESSIONLOGIN_V4 = True

# dynVideoInputChannelID is owned/normalized by the NVR. It is NOT an
# Excel-controlled video setting. Example: stream 201/301/401 can legitimately
# read back dynVideoInputChannelID 2/3/4. Keep this diagnostic validation OFF
# so normal NVR binding does not become a false stream-configuration failure.
NVR_STREAM_VALIDATE_DYNAMIC_BINDING = False

# If the NVR StreamingProxy endpoint rejects the request with notSupport or
# badXmlContent, fall back to the physical camera Streaming endpoint.
NVR_STREAM_ENABLE_DIRECT_CAMERA_FALLBACK = True
