FINAL_CAMERA_STREAM_VERIFY_WAIT_SECONDS = 2.0
FINAL_CAMERA_STREAM_SETTLE_VERIFY_SECONDS = 2.0

# If the physical camera is correct but the NVR proxy/UI still reports a
# different frame-rate value such as "Full Frame Rate", repair the NVR proxy
# again from a fresh GET of that exact channel XML.
NVR_PROXY_EXPLICIT_FPS_REPAIR_ENABLED = True
NVR_PROXY_EXPLICIT_FPS_REPAIR_MAX_ATTEMPTS = 2
NVR_PROXY_EXPLICIT_FPS_REPAIR_WAIT_SECONDS = 1.0

# Exact legacy Content-Type observed in the working browser request. The body
# is still RAW XML; it is not URL-encoded.
NVR_STREAM_BROWSER_CONTENT_TYPE = (
    "application/x-www-form-urlencoded; charset=UTF-8"
)

# Final NVR StreamingProxy recovery path.  If requests/SessionLogin-v4 still
