# v122: Camera Management is a hard dependency of StreamingProxy.
# Keep InputProxy writes bounded and wait for real runtime channel binding
# before PASS 6. This prevents a busy NVR from hanging for 120 seconds and
# prevents 201/202/301/... notSupport cascades while cameras are offline.
NVR_INPUTPROXY_WRITE_CONNECT_TIMEOUT_SECONDS = 5.0
NVR_INPUTPROXY_WRITE_READ_TIMEOUT_SECONDS = 8.0
NVR_INPUTPROXY_RUNTIME_INITIAL_GRACE_SECONDS = 8.0
NVR_INPUTPROXY_RUNTIME_RECOVERY_TIMEOUT_SECONDS = 30.0
NVR_INPUTPROXY_RUNTIME_POLL_SECONDS = 2.0
NVR_INPUTPROXY_RUNTIME_REAPPLY_ONCE = True

# =============================================================================
# BASIC HELPERS
# =============================================================================

def get_value(row, *names):
    for name in names:
        if name in row and row[name] is not None:
            return str(row[name]).strip()
    return ""


def sanitize_credential_boundary(
    value,
    label,
    *,
    secret=True,
):
    """
    Remove leading/trailing whitespace and invisible boundary characters from
    usernames/passwords while preserving the credential content itself.

    Internal spaces are NOT removed.

    This protects NVR Camera Management and User Management from Excel values
    such as:
        " ServiceAccount"
        "password "
        <NBSP>password
        password<zero-width-space>

    Secret values are never printed.
    """
    raw = (
        ""
        if value is None
        else str(value)
    )

    # Python strip() handles normal whitespace and NBSP. The explicit
    # zero-width/BOM characters below are common copy/paste artifacts that
    # strip() does not always remove.
    boundary_invisible = (
        "\u200b"
        "\u200c"
        "\u200d"
        "\ufeff"
    )

    cleaned = raw.strip()

    previous = None

    while cleaned != previous:
        previous = cleaned
        cleaned = cleaned.strip(
            boundary_invisible
        ).strip()

    if cleaned != raw:
        if secret:
            print(
                f"[CREDENTIAL SANITIZE] {label}: "
                "leading/trailing whitespace/invisible characters removed; "
                "value remains hidden."
            )
        else:
            print(
                f"[CREDENTIAL SANITIZE] {label}: "
                "leading/trailing whitespace/invisible characters removed."
            )

    if cleaned and (
        cleaned[0].isspace()
        or cleaned[-1].isspace()
        or cleaned[0] in boundary_invisible
        or cleaned[-1] in boundary_invisible
    ):
        raise RuntimeError(
            f"{label}: credential still contains a leading/trailing "
            "whitespace character after sanitization."
        )

    return cleaned


def sanitize_device_row_credentials(
    row,
):
    """
    Sanitize the administrator Username/Password loaded from a device row.
    """
    source_sheet = get_value(
        row,
        "Source Sheet",
    )

    ip = get_value(
        row,
        "Current IP",
        "current_ip",
    )

    if "Username" in row:
        row["Username"] = sanitize_credential_boundary(
            row.get("Username"),
            f"{source_sheet} {ip} administrator username",
            secret=False,
        )

    if "Password" in row:
        row["Password"] = sanitize_credential_boundary(
            row.get("Password"),
            f"{source_sheet} {ip} administrator password",
            secret=True,
        )

    return row


def is_blank(value):
    if value is None:
        return True

    value = str(value).strip()

    return value == "" or value.lower() in [
        "nan",
        "none",
        "null",
        "na",
        "n/a",
    ]

def is_camera_device(row):
    source_sheet = get_value(row, "Source Sheet")
    camera_type = get_value(row, "Camera Type")

    return not (
        source_sheet == "NVR_Settings"
        or "NVR" in camera_type.upper()
    )


def get_camera_nvr_ip(row):
    """
    Return the NVR Current IP resolved from NVR_Settings by Site ID.

    Priority:
      1. Resolved NVR Current IP
      2. Explicit Log Server IP
      3. Explicit NVR IP
      4. Camera NTP IP / NTP Server IP as compatibility fallback

    Security Audit Log should normally use the matching NVR Current IP,
    not merely assume that the camera NTP IP is the NVR.
    """
    nvr_ip = get_value(
        row,
        "Resolved NVR Current IP",
        "Log Server IP",
        "NVR IP",
        "NTP IP",
        "NTP Server IP"
    )

    if is_blank(nvr_ip):
        return ""

    return nvr_ip.strip()


def yes_no(value, default=True):
    if is_blank(value):
        return default

    value = str(value).strip().lower()

    if value in ["yes", "y", "true", "1", "enable", "enabled"]:
        return True

    if value in ["no", "n", "false", "0", "disable", "disabled"]:
        return False

    return default


def safe_filename(value):
    value = str(value).strip()
    value = value.replace(".", "_")
    value = value.replace("/", "_")
    value = value.replace("\\", "_")
    value = value.replace(":", "_")
    value = value.replace(" ", "_")
    return value


def current_computer_time_iso():
    """
    Uses the laptop/computer local time.
    Example:
    2026-07-08T13:05:58+08:00
    """
    return datetime.now().astimezone().isoformat(timespec="seconds")


def resolve_workflow_start_mode():
    configured_mode = str(
        WORKFLOW_START_MODE or "ASK"
    ).strip().upper()

    aliases = {
        "1": "START_FROM_SCRATCH",
        "START": "START_FROM_SCRATCH",
        "START_FROM_SCRATCH": "START_FROM_SCRATCH",

        "2": "SKIP_CONFIG_IMPORT",
        "SKIP": "SKIP_CONFIG_IMPORT",
        "SKIP_CONFIG_IMPORT": "SKIP_CONFIG_IMPORT",

        "3": "CREATE_USER_MANAGEMENT",
        "USER": "CREATE_USER_MANAGEMENT",
        "USERS": "CREATE_USER_MANAGEMENT",
        "CREATE_USER_MANAGEMENT": "CREATE_USER_MANAGEMENT",

        "4": "EXIT",
        "EXIT": "EXIT",
        "QUIT": "EXIT",
        "Q": "EXIT",
    }

    if configured_mode != "ASK":
        resolved = aliases.get(configured_mode)

        if resolved is None:
            raise ValueError(
                "Invalid WORKFLOW_START_MODE."
            )

        print("=" * 100)
        print("WORKFLOW START MODE")
        print("=" * 100)
        print(f"[WORKFLOW] Fixed mode: {resolved}")
        print("=" * 100)
        return resolved

    while True:
        print("=" * 100)
        print("SELECT WORKFLOW START MODE")
        print("=" * 100)
        print("")
        print("1. START FROM SCRATCH")
        print("   Description:")
        print("   - Run the complete configuration workflow from PASS 0 onward.")
        print("   - Import Device Parameter Config for rows enabled in Excel.")
        print("   - Wait for imported devices to reboot/become ready.")
        print("   - Continue camera/NVR settings, then Account Security Settings.")
        print("   - After Account Security succeeds, continue directly to User Management in the SAME Edge session.")
        print("   - Run User Management BEFORE NVR Camera Management so ServiceAccount exists first.")
        print("   - Then complete NVR Camera Management and stream settings.")
        print("   - User Management runs automatically")
        print("     for every device row where User Management Creation = Yes.")
        print("   - User Management uses camera rights from User Management Permissions")
        print("     and exact NVR rights from NVR User Rights.")
        print("   - Account Security + User Management use the same authenticated Edge session per selected device.")
        print("")
        print("2. SKIP CONFIG FILE IMPORT")
        print("   Description:")
        print("   - Skip PASS 0 Device Parameter Config import completely.")
        print("   - Do not run the 150-second post-import wait.")
        print("   - Start directly from the normal configuration passes.")
        print("   - Account Security Settings still runs for all loaded devices.")
        print("   - For rows where User Management Creation = Yes, continue directly")
        print("     from Account Security to User Management in the SAME Edge session.")
        print("   - Use this when Device Parameter Config has already been imported.")
        print("")
        print("3. CREATE USER MANAGEMENT")
        print("   Description:")
        print("   - Account Security Settings is NOT configured in Option 3.")
        print("   - Create User Management directly on ALL loaded NVR/Discreet/Dome devices.")
        print("   - Navigation is Configuration > System > User Management.")
        print("   - All other normal configuration passes are skipped.")
        print("   - Read usernames/passwords from User Management Account.")
        print("   - Camera rights: ServiceAccount/MM/ME only from User Management Permissions.")
        print("   - NVR rights: read exact local/remote values from NVR User Rights.")
        print("   - ServiceAccount: create with final password; no login verification afterward.")
        print("   - L2VA exists only on NVR; it is never created on Discreet/Dome cameras.")
        print("   - MaintenanceManager / MaintenanceEngineer:")
        print("       create with Testing password, then change directly to Actual password.")
        print("   - L2VA: created only on device types allowed by the Excel scope (default NVR Only).")
        print("   - Multiple selected devices can run concurrently in separate Edge windows.")
        print("")
        print("4. EXIT")
        print("   Description:")
        print("   - Exit the script without changing any device.")
        print("")
        print("=" * 100)

        try:
            selected = input(
                "Select option [1/2/3/4]: "
            ).strip()
        except (EOFError, KeyboardInterrupt):
            return "START_FROM_SCRATCH"

        resolved = aliases.get(selected.upper())

        if resolved:
            print("=" * 100)
            print(f"[WORKFLOW SELECTED] {resolved}")
            print("=" * 100)
            return resolved

        print("[WORKFLOW] Invalid selection. Please enter 1, 2, 3, or 4.")


# =============================================================================
# EXCEL READER
# =============================================================================


def ensure_worksheet_dimensions(sheet):
    """
    Ensure read-only openpyxl worksheets have max_row/max_column populated.

    Some generated .xlsx files omit the worksheet <dimension> tag. In
    read_only=True mode, openpyxl can then report sheet.max_row=None until
    calculate_dimension(force=True) is called.
    """
    try:
        if getattr(sheet, "max_row", None) is None:
            sheet.calculate_dimension(force=True)
    except Exception:
        pass

    return sheet


def read_excel_devices(excel_path):
    workbook = load_workbook(excel_path, data_only=True)

    all_rows = []

    for sheet_name in TARGET_SHEETS:
        if sheet_name not in workbook.sheetnames:
            print(f"[WARNING] Sheet not found: {sheet_name}")
            continue

        sheet = workbook[sheet_name]
        ensure_worksheet_dimensions(sheet)

        print("=" * 100)
        print(f"Checking sheet: {sheet_name}")

        header_row_number = None
        headers = []

        # Search first 20 rows to find the real header row
        for row_index in range(1, min(sheet.max_row, 20) + 1):
            row_values = [
                str(cell.value).strip() if cell.value is not None else ""
                for cell in sheet[row_index]
            ]

            if "Current IP" in row_values and "Username" in row_values and "Password" in row_values:
                header_row_number = row_index
                headers = row_values
                break

        if header_row_number is None:
            print(f"[WARNING] Cannot find header row in sheet: {sheet_name}")
            continue

        print(f"[OK] Header row found at row {header_row_number}")
        print(f"Headers: {headers}")

        # Read device rows after the header row
        for row_values in sheet.iter_rows(
            min_row=header_row_number + 1,
            max_row=sheet.max_row,
            values_only=True
        ):
            row_dict = {}

            for header, value in zip(headers, row_values):
                if header:
                    row_dict[header] = "" if value is None else str(value).strip()

            current_ip = get_value(row_dict, "Current IP", "current_ip")

            if is_blank(current_ip):
                continue

            row_dict["Source Sheet"] = sheet_name

            sanitize_device_row_credentials(
                row_dict
            )

            all_rows.append(row_dict)

            print(f"[LOADED] {sheet_name} - {current_ip}")

    return all_rows


def read_nvr_camera_stream_profiles(excel_path):
    """
    Read editable NVR camera stream settings from Excel.

    Expected sheet:
        NVR Camera Stream Settings

    The script supports multiple named profiles. If the NVR row does not
    contain a "Camera Stream Profile" column, the profile named "Default" is
    used.
    """
    workbook = load_workbook(
        excel_path,
        data_only=True,
        read_only=True,
    )

    if NVR_CAMERA_STREAM_SETTINGS_SHEET not in workbook.sheetnames:
        print(
            f"[WARNING] Sheet not found: "
            f"{NVR_CAMERA_STREAM_SETTINGS_SHEET}"
        )
        return {}

    sheet = workbook[NVR_CAMERA_STREAM_SETTINGS_SHEET]
    ensure_worksheet_dimensions(sheet)

    header_row_number = None
    headers = []

    required_headers = {
        "Profile Name",
        "Enabled",
        "Stream Channel Suffix",
        "Resolution Width",
        "Resolution Height",
        "Bitrate Type",
        "Frame Rate (fps)",
        "Max Bitrate (Kbps)",
        "Video Encoding",
        "H.265+",
        "I Frame Interval",
    }

    for row_index in range(
        1,
        min(sheet.max_row, 30) + 1,
    ):
        row_values = [
            str(cell.value).strip()
            if cell.value is not None
            else ""
            for cell in sheet[row_index]
        ]

        if required_headers.issubset(set(row_values)):
            header_row_number = row_index
            headers = row_values
            break

    if header_row_number is None:
        print(
            f"[WARNING] Cannot find stream-settings header row in "
            f"{NVR_CAMERA_STREAM_SETTINGS_SHEET}"
        )
        return {}

    profiles = {}

    for row_values in sheet.iter_rows(
        min_row=header_row_number + 1,
        max_row=sheet.max_row,
        values_only=True,
    ):
        row = {}

        for header, value in zip(headers, row_values):
            if header:
                row[header] = (
                    ""
                    if value is None
                    else str(value).strip()
                )

        profile_name = get_value(
            row,
            "Profile Name",
            "Profile",
        )

        if is_blank(profile_name):
            continue

        # Ignore merged instruction/note rows below the profile table.
        if (
            is_blank(get_value(row, "Stream Channel Suffix"))
            and is_blank(get_value(row, "Resolution Width"))
            and is_blank(get_value(row, "Resolution Height"))
            and is_blank(get_value(row, "Max Bitrate (Kbps)"))
        ):
            continue

        profiles[profile_name.strip().lower()] = row

    print(
        f"[NVR STREAM] Loaded {len(profiles)} stream profile(s) "
        f"from Excel."
    )

    for profile_name, profile in profiles.items():
        print(
            f"[NVR STREAM] Profile={get_value(profile, 'Profile Name')}; "
            f"Enabled={get_value(profile, 'Enabled')}; "
            f"Resolution={get_value(profile, 'Resolution Width')}x"
            f"{get_value(profile, 'Resolution Height')}; "
            f"FPS={get_value(profile, 'Frame Rate (fps)')}; "
            f"Bitrate={get_value(profile, 'Max Bitrate (Kbps)')} Kbps; "
            f"Codec={get_value(profile, 'Video Encoding')}"
        )

    return profiles


def get_nvr_camera_stream_profile(
    row,
    stream_profiles,
):
    requested_profile = get_value(
        row,
        "Camera Stream Profile",
        "NVR Camera Stream Profile",
        "Stream Profile",
    )

    if is_blank(requested_profile):
        requested_profile = DEFAULT_NVR_CAMERA_STREAM_PROFILE

    profile = stream_profiles.get(
        requested_profile.strip().lower()
    )

    if profile:
        return profile

    # If the requested/default profile is missing but exactly one profile
    # exists, use it rather than silently doing nothing.
    if len(stream_profiles) == 1:
        return next(iter(stream_profiles.values()))

    return None



def get_nvr_camera_sub_stream_profile(
    row,
    stream_profiles,
):
    """
    Resolve the editable Sub-Stream profile.

    If the NVR row uses Camera Stream Profile="Default", the script looks for
    "Default Sub". For a custom base profile such as "SiteA", it first looks
    for "SiteA Sub", then falls back to the global "Default Sub".
    """
    requested_profile = get_value(
        row,
        "Camera Stream Profile",
        "NVR Camera Stream Profile",
        "Stream Profile",
    )

    if is_blank(requested_profile):
        requested_profile = DEFAULT_NVR_CAMERA_STREAM_PROFILE

    requested_profile = requested_profile.strip()

    candidates = [
        f"{requested_profile} Sub",
        f"{requested_profile} Sub-Stream",
        DEFAULT_NVR_CAMERA_SUB_STREAM_PROFILE,
        "Sub-Stream",
        "Sub Stream",
    ]

    seen = set()

    for candidate in candidates:
        key = candidate.strip().lower()

        if not key or key in seen:
            continue

        seen.add(key)

        profile = stream_profiles.get(key)

        if profile:
            return profile

    return None


def normalize_stream_channel_suffix(value):
    value = str(value or "").strip()

    if not value:
        return "01"

    digits = re.sub(r"\D", "", value)

    if not digits:
        raise ValueError(
            f"Invalid Stream Channel Suffix: {value}"
        )

    suffix_number = int(digits)

    if suffix_number < 0 or suffix_number > 99:
        raise ValueError(
            f"Stream Channel Suffix must be 00..99: {value}"
        )

    return f"{suffix_number:02d}"


def excel_int(value, field_name, minimum=None):
    if is_blank(value):
        raise ValueError(
            f"Excel setting is blank: {field_name}"
        )

    try:
        number = int(float(str(value).strip()))
    except Exception as error:
        raise ValueError(
            f"Invalid integer for {field_name}: {value}"
        ) from error

    if minimum is not None and number < minimum:
        raise ValueError(
            f"{field_name} must be >= {minimum}: {value}"
        )

    return number


def excel_float(value, field_name, minimum=None):
    if is_blank(value):
        raise ValueError(
            f"Excel setting is blank: {field_name}"
        )

    try:
        number = float(str(value).strip())
    except Exception as error:
        raise ValueError(
            f"Invalid number for {field_name}: {value}"
        ) from error

    if minimum is not None and number < minimum:
        raise ValueError(
            f"{field_name} must be >= {minimum}: {value}"
        )

    return number


def normalize_site_id(value):
    """
    Return a stable Site ID string.

    Excel may store codes as numbers, text, or values ending in .0.
    """
    if is_blank(value):
        return ""

    code = str(value).strip()

    if code.endswith(".0") and code[:-2].isdigit():
        code = code[:-2]

    digits = re.sub(r"\D", "", code)

    if digits:
        return digits

    return code.upper()


def find_header_row(sheet, required_header_groups, search_rows=30):
    ensure_worksheet_dimensions(sheet)

    """
    Find a header row where every required group has at least one match.

    Example:
        [
            ["SA Username", "Service Account Username"],
            ["SA Password", "Service Account Password"],
        ]
    """
    for row_index in range(
        1,
        min(sheet.max_row, search_rows) + 1
    ):
        values = [
            str(cell.value).strip()
            if cell.value is not None
            else ""
            for cell in sheet[row_index]
        ]

        values_lower = {
            value.lower()
            for value in values
            if value
        }

        all_groups_found = True

        for header_group in required_header_groups:
            if not any(
                str(header).strip().lower() in values_lower
                for header in header_group
            ):
                all_groups_found = False
                break

        if all_groups_found:
            return row_index, values

    return None, []


def get_first_matching_value(row, possible_headers):
    for header in possible_headers:
        if header in row and not is_blank(row[header]):
            return str(row[header]).strip()

    header_map = {
        str(key).strip().lower(): key
        for key in row.keys()
    }

    for header in possible_headers:
        actual = header_map.get(str(header).strip().lower())

        if actual and not is_blank(row[actual]):
            return str(row[actual]).strip()

    return ""


def read_service_account_configuration(excel_path):
    """
    Read ServiceAccount credentials from the User Management Account sheet.

    Supports:
    - one global account row;
    - optional Site ID-specific account rows.

    Passwords are never printed.
    """
    workbook = load_workbook(
        excel_path,
        data_only=True,
        read_only=True
    )

    matching_sheet = None

    preferred_names = [
        USER_MANAGEMENT_ACCOUNT_SHEET,
        "User Management Accounts",
        "User_Management_Account",
        "UserManagementAccount",
    ]

    for preferred_name in preferred_names:
        for sheet_name in workbook.sheetnames:
            if (
                sheet_name.strip().lower()
                == preferred_name.strip().lower()
            ):
                matching_sheet = workbook[sheet_name]
                break

        if matching_sheet is not None:
            break

    if matching_sheet is None:
        print(
            "[WARNING] User Management Account sheet not found. "
            "NVR Camera Management sync will be skipped."
        )

        return {
            "default": None,
            "by_site": {},
        }

    header_row, headers = find_header_row(
        matching_sheet,
        [
            SERVICE_ACCOUNT_USERNAME_HEADERS,
            SERVICE_ACCOUNT_PASSWORD_HEADERS,
        ],
    )

    if header_row is None:
        print(
            "[WARNING] Cannot find SA Username / SA Password headers "
            f"in sheet: {matching_sheet.title}"
        )

        return {
            "default": None,
            "by_site": {},
        }

    default_account = None
    accounts_by_site = {}

    for values in matching_sheet.iter_rows(
        min_row=header_row + 1,
        max_row=matching_sheet.max_row,
        values_only=True,
    ):
        row = {}

        for header, value in zip(headers, values):
            if header:
                row[header] = (
                    ""
                    if value is None
                    else str(value).strip()
                )

        sa_username = sanitize_credential_boundary(
            get_first_matching_value(
                row,
                SERVICE_ACCOUNT_USERNAME_HEADERS,
            ),
            "NVR Camera Management ServiceAccount username",
            secret=False,
        )

        sa_password = sanitize_credential_boundary(
            get_first_matching_value(
                row,
                SERVICE_ACCOUNT_PASSWORD_HEADERS,
            ),
            "NVR Camera Management ServiceAccount password",
            secret=True,
        )

        if is_blank(sa_username) or is_blank(sa_password):
            continue

        account = {
            "username": sa_username,
            "password": sa_password,
        }

        site = normalize_site_id(
            get_value(
                row,
                "Site ID",
                "SiteCode",
                "Site Code",
                "Site",
            )
        )

        if site:
            accounts_by_site[site] = account

        if default_account is None:
            default_account = account

    if default_account:
        print(
            "[OK] ServiceAccount configuration loaded. "
            f"Username: {default_account['username']}"
        )
        print("[OK] ServiceAccount password loaded from Excel.")
    else:
        print(
            "[WARNING] No completed SA Username / SA Password row "
            f"found in sheet: {matching_sheet.title}"
        )

    return {
        "default": default_account,
        "by_site": accounts_by_site,
    }



def user_management_creation_requested(row):
    return yes_no(
        get_first_matching_value(
            row,
            USER_MANAGEMENT_CREATION_HEADERS,
        ),
        default=False,
    )


def read_user_management_accounts(excel_path):
    workbook = load_workbook(
        excel_path,
        data_only=True,
        read_only=True,
    )

    if USER_MANAGEMENT_ACCOUNT_SHEET not in workbook.sheetnames:
        raise RuntimeError(
            f"Sheet not found: {USER_MANAGEMENT_ACCOUNT_SHEET}"
        )

    sheet = workbook[USER_MANAGEMENT_ACCOUNT_SHEET]

    header_row, headers = find_header_row(
        sheet,
        [
            SERVICE_ACCOUNT_USERNAME_HEADERS,
            SERVICE_ACCOUNT_PASSWORD_HEADERS,
            MM_USERNAME_HEADERS,
            MM_TESTING_PASSWORD_HEADERS,
            MM_ACTUAL_PASSWORD_HEADERS,
            ME_USERNAME_HEADERS,
            ME_TESTING_PASSWORD_HEADERS,
            ME_ACTUAL_PASSWORD_HEADERS,
            L2VA_USERNAME_HEADERS,
            L2VA_PASSWORD_HEADERS,
        ],
    )

    if header_row is None:
        raise RuntimeError(
            "User Management Account headers were not found. "
            "Use the generated v12 workbook."
        )

    source = None

    for values in sheet.iter_rows(
        min_row=header_row + 1,
        max_row=sheet.max_row,
        values_only=True,
    ):
        row = {}

        for header, value in zip(headers, values):
            if header:
                row[header] = (
                    ""
                    if value is None
                    else str(value).strip()
                )

        if not is_blank(
            get_first_matching_value(
                row,
                SERVICE_ACCOUNT_USERNAME_HEADERS,
            )
        ):
            source = row
            break

    if source is None:
        raise RuntimeError(
            "No User Management Account data row was found."
        )

    accounts = [
        {
            "role": "ServiceAccount",
            "username": get_first_matching_value(
                source,
                SERVICE_ACCOUNT_USERNAME_HEADERS,
            ),
            "initial_password": get_first_matching_value(
                source,
                SERVICE_ACCOUNT_PASSWORD_HEADERS,
            ),
            "actual_password": get_first_matching_value(
                source,
                SERVICE_ACCOUNT_PASSWORD_HEADERS,
            ),
            "rotate": False,
            "select_all": True,
        },
        {
            "role": "MaintenanceManager",
            "username": get_first_matching_value(
                source,
                MM_USERNAME_HEADERS,
            ),
            "initial_password": get_first_matching_value(
                source,
                MM_TESTING_PASSWORD_HEADERS,
            ),
            "actual_password": get_first_matching_value(
                source,
                MM_ACTUAL_PASSWORD_HEADERS,
            ),
            "rotate": True,
            "select_all": False,
        },
        {
            "role": "MaintenanceEngineer",
            "username": get_first_matching_value(
                source,
                ME_USERNAME_HEADERS,
            ),
            "initial_password": get_first_matching_value(
                source,
                ME_TESTING_PASSWORD_HEADERS,
            ),
            "actual_password": get_first_matching_value(
                source,
                ME_ACTUAL_PASSWORD_HEADERS,
            ),
            "rotate": True,
            "select_all": False,
        },
        {
            "role": "L2VA",
            "username": get_first_matching_value(
                source,
                L2VA_USERNAME_HEADERS,
            ),
            "initial_password": get_first_matching_value(
                source,
                L2VA_PASSWORD_HEADERS,
            ),
            "actual_password": get_first_matching_value(
                source,
                L2VA_PASSWORD_HEADERS,
            ),
            "rotate": False,
            "select_all": False,
        },
    ]

    for account in accounts:
        account["username"] = sanitize_credential_boundary(
            account.get(
                "username",
                "",
            ),
            f"{account['role']} username",
            secret=False,
        )

        account["initial_password"] = sanitize_credential_boundary(
            account.get(
                "initial_password",
                "",
            ),
            f"{account['role']} initial/testing password",
            secret=True,
        )

        account["actual_password"] = sanitize_credential_boundary(
            account.get(
                "actual_password",
                "",
            ),
            f"{account['role']} actual/final password",
            secret=True,
        )

        if is_blank(account["username"]):
            raise RuntimeError(
                f"{account['role']} username is blank."
            )

        if is_blank(account["initial_password"]):
            raise RuntimeError(
                f"{account['role']} initial/testing password is blank."
            )

        if is_blank(account["actual_password"]):
            raise RuntimeError(
                f"{account['role']} actual password is blank."
            )

        if (
            account["rotate"]
            and account["initial_password"]
            == account["actual_password"]
        ):
            raise RuntimeError(
                f"{account['role']} Testing password must differ "
                "from Actual password."
            )

    print(
        f"[USER MANAGEMENT] Loaded {len(accounts)} accounts. "
        "Password values are hidden."
    )

    return accounts



def read_user_management_permission_profiles(excel_path):
    """
    Read role scope / Select All / individual permission rights from
    'User Management Permissions'.

    The Excel permission label may be a prefix (for example
    'Remote: Log Search / Interrogate') so it can match firmware text that is
    truncated visually in the old web UI.
    """
    workbook = load_workbook(
        excel_path,
        data_only=True,
        read_only=True,
    )

    if USER_MANAGEMENT_PERMISSION_SHEET not in workbook.sheetnames:
        raise RuntimeError(
            f"Sheet not found: {USER_MANAGEMENT_PERMISSION_SHEET}"
        )

    sheet = workbook[USER_MANAGEMENT_PERMISSION_SHEET]

    role_header_row = None
    permission_header_row = None

    for row_number in range(1, sheet.max_row + 1):
        values = [
            str(sheet.cell(row_number, col).value or "").strip()
            for col in range(1, min(sheet.max_column, 10) + 1)
        ]

        normalized = [
            value.lower()
            for value in values
        ]

        if (
            role_header_row is None
            and "role" in normalized
            and "create scope" in normalized
            and "select all" in normalized
        ):
            role_header_row = row_number

        if (
            permission_header_row is None
            and any(
                value.lower() == "permission label / prefix"
                for value in values
            )
        ):
            permission_header_row = row_number

    if role_header_row is None:
        raise RuntimeError(
            "Role setup table was not found in "
            f"{USER_MANAGEMENT_PERMISSION_SHEET}."
        )

    if permission_header_row is None:
        raise RuntimeError(
            "Permission matrix was not found in "
            f"{USER_MANAGEMENT_PERMISSION_SHEET}."
        )

    role_headers = [
        str(
            sheet.cell(
                role_header_row,
                col,
            ).value
            or ""
        ).strip()
        for col in range(1, sheet.max_column + 1)
    ]

    profiles = {}

    for row_number in range(
        role_header_row + 1,
        permission_header_row,
    ):
        values = {
            header: (
                ""
                if sheet.cell(row_number, col_index + 1).value is None
                else str(
                    sheet.cell(
                        row_number,
                        col_index + 1,
                    ).value
                ).strip()
            )
            for col_index, header in enumerate(role_headers)
            if header
        }

        role = values.get("Role", "").strip()

        if not role:
            continue

        profiles[role] = {
            "role": role,
            "level": (
                values.get("Level", "")
                or USER_MANAGEMENT_DEFAULT_LEVEL
            ),
            "scope": (
                values.get("Create Scope", "")
                or "All Devices"
            ),
            "select_all": yes_no(
                values.get("Select All", ""),
                default=False,
            ),
            "permissions": {},
        }

    permission_headers = [
        str(
            sheet.cell(
                permission_header_row,
                col,
            ).value
            or ""
        ).strip()
        for col in range(1, sheet.max_column + 1)
    ]

    try:
        label_col = permission_headers.index(
            "Permission Label / Prefix"
        ) + 1
    except ValueError:
        raise RuntimeError(
            "Permission Label / Prefix column is missing."
        )

    role_columns = {}

    for role in profiles:
        try:
            role_columns[role] = (
                permission_headers.index(role) + 1
            )
        except ValueError:
            raise RuntimeError(
                f"Permission column for role {role} is missing."
            )

    for row_number in range(
        permission_header_row + 1,
        sheet.max_row + 1,
    ):
        label = str(
            sheet.cell(
                row_number,
                label_col,
            ).value
            or ""
        ).strip()

        if not label:
            continue

        for role, col_number in role_columns.items():
            value = str(
                sheet.cell(
                    row_number,
                    col_number,
                ).value
                or ""
            ).strip()

            if value:
                profiles[role]["permissions"][label] = (
                    yes_no(
                        value,
                        default=False,
                    )
                )

    print(
        f"[USER MANAGEMENT] Loaded permission profiles for "
        f"{len(profiles)} roles from {USER_MANAGEMENT_PERMISSION_SHEET}."
    )

    return profiles



def read_nvr_user_rights_profiles(excel_path):
    """
    Read exact NVR UserPermission rights from the NVR User Rights sheet.

    Return:
        {
            "ServiceAccount": {
                ("Local", "backup", "Root"): True,
                ...
            },
            ...
        }
    """
    workbook = load_workbook(
        excel_path,
        data_only=True,
        read_only=True,
    )

    if USER_MANAGEMENT_NVR_RIGHTS_SHEET not in workbook.sheetnames:
        raise RuntimeError(
            f"Sheet not found: {USER_MANAGEMENT_NVR_RIGHTS_SHEET}"
        )

    sheet = workbook[
        USER_MANAGEMENT_NVR_RIGHTS_SHEET
    ]

    header_row = None
    headers = []

    for row_number in range(
        1,
        sheet.max_row + 1,
    ):
        values = [
            str(
                sheet.cell(
                    row_number,
                    col,
                ).value
                or ""
            ).strip()
            for col in range(
                1,
                sheet.max_column + 1,
            )
        ]

        normalized = [
            value.lower()
            for value in values
        ]

        if (
            "permission scope" in normalized
            and "isapi field" in normalized
            and "channel field type" in normalized
        ):
            header_row = row_number
            headers = values
            break

    if header_row is None:
        raise RuntimeError(
            f"NVR rights header was not found in "
            f"{USER_MANAGEMENT_NVR_RIGHTS_SHEET}."
        )

    role_names = [
        "ServiceAccount",
        "MaintenanceManager",
        "MaintenanceEngineer",
        "L2VA",
    ]

    role_columns = {}

    for role in role_names:
        try:
            role_columns[role] = (
                headers.index(role) + 1
            )
        except ValueError:
            raise RuntimeError(
                f"NVR rights column missing for role {role}."
            )

    try:
        scope_col = (
            headers.index(
                "Permission Scope"
            ) + 1
        )
        field_col = (
            headers.index(
                "ISAPI Field"
            ) + 1
        )
        channel_type_col = (
            headers.index(
                "Channel Field Type"
            ) + 1
        )
    except ValueError as error:
        raise RuntimeError(
            "NVR rights sheet is missing required columns."
        ) from error

    profiles = {
        role: {}
        for role in role_names
    }

    for row_number in range(
        header_row + 1,
        sheet.max_row + 1,
    ):
        permission_scope = str(
            sheet.cell(
                row_number,
                scope_col,
            ).value
            or ""
        ).strip()

        field_name = str(
            sheet.cell(
                row_number,
                field_col,
            ).value
            or ""
        ).strip()

        channel_type = str(
            sheet.cell(
                row_number,
                channel_type_col,
            ).value
            or ""
        ).strip()

        if (
            not permission_scope
            or not field_name
            or not channel_type
        ):
            continue

        key = (
            permission_scope,
            field_name,
            channel_type,
        )

        for role, col_number in (
            role_columns.items()
        ):
            value = str(
                sheet.cell(
                    row_number,
                    col_number,
                ).value
                or ""
            ).strip()

            if not value:
                raise RuntimeError(
                    f"NVR rights value is blank: "
                    f"role={role}; key={key}"
                )

            profiles[role][key] = yes_no(
                value,
                default=False,
            )

    for role, profile in profiles.items():
        if not profile:
            raise RuntimeError(
                f"NVR rights profile is empty for {role}."
            )

    print(
        f"[NVR USER RIGHTS] Loaded exact NVR permission profiles "
        f"for {len(profiles)} roles from "
        f"{USER_MANAGEMENT_NVR_RIGHTS_SHEET}."
    )

    return profiles



def read_nvr_user_ui_permission_profiles(excel_path):
    """Read NVR Add User checkbox rights from NVR User Rights sheet.

    Only Root rows map to one visible checkbox in the NVR Add User dialog.
    Per-channel rights are applied later through UserPermission ISAPI.
    """
    workbook = load_workbook(excel_path, data_only=True, read_only=True)
    if USER_MANAGEMENT_NVR_RIGHTS_SHEET not in workbook.sheetnames:
        raise RuntimeError(f"Sheet not found: {USER_MANAGEMENT_NVR_RIGHTS_SHEET}")
    sheet = workbook[USER_MANAGEMENT_NVR_RIGHTS_SHEET]

    header_row = None
    headers = []
    for row_number in range(1, sheet.max_row + 1):
        values = [str(sheet.cell(row_number, col).value or "").strip()
                  for col in range(1, sheet.max_column + 1)]
        lowered = [v.lower() for v in values]
        if ("ui permission label" in lowered and
                "channel field type" in lowered and
                "serviceaccount" in lowered):
            header_row = row_number
            headers = values
            break
    if header_row is None:
        raise RuntimeError("NVR UI permission header not found in NVR User Rights.")

    try:
        label_col = headers.index("UI Permission Label") + 1
        channel_type_col = headers.index("Channel Field Type") + 1
    except ValueError as e:
        raise RuntimeError("NVR User Rights missing UI Permission Label / Channel Field Type.") from e

    roles = ["ServiceAccount", "MaintenanceManager", "MaintenanceEngineer", "L2VA"]
    role_cols = {}
    for role in roles:
        try:
            role_cols[role] = headers.index(role) + 1
        except ValueError as e:
            raise RuntimeError(f"NVR User Rights missing role column {role}.") from e

    profiles = {role: {"select_all": False, "permissions": {}} for role in roles}
    for row_number in range(header_row + 1, sheet.max_row + 1):
        label = str(sheet.cell(row_number, label_col).value or "").strip()
        channel_type = str(sheet.cell(row_number, channel_type_col).value or "").strip()
        if not label or channel_type.lower() != "root":
            continue
        for role, col in role_cols.items():
            raw = str(sheet.cell(row_number, col).value or "").strip()
            if not raw:
                raise RuntimeError(f"Blank NVR UI right: role={role}; label={label}")
            profiles[role]["permissions"][label] = yes_no(raw, default=False)

    # Supplied NVR screenshots show ServiceAccount uses Select All.
    profiles["ServiceAccount"]["select_all"] = True

    print(f"[NVR USER RIGHTS] Loaded UI checkbox profiles for {len(profiles)} roles.")
    for role, profile in profiles.items():
        yes_count = sum(1 for v in profile["permissions"].values() if v)
        no_count = sum(1 for v in profile["permissions"].values() if not v)
        print(f"[NVR USER RIGHTS] {role}: SelectAll={profile['select_all']}; Yes={yes_count}; No={no_count}.")
    return profiles

def user_account_login_verification_required(
    row,
    account,
):
    """
    Workflow-specific login verification policy.

    - ServiceAccount: never login/relogin for verification.
    - NVR L2VA: never login/relogin for verification.
    - MM / ME: keep Testing->Actual rotation and final Actual login verification.
    """
    role = str(
        account.get(
            "role",
            "",
        )
    ).strip()

    if role == "ServiceAccount":
        # Intentionally no interactive ServiceAccount login verification.
        # Exact browser input and NVR InputProxy payload values are verified
        # instead.
        return False

    if (
        user_management_device_kind(row) == "NVR"
        and role == "L2VA"
    ):
        return False

    return True


def attach_user_management_profiles(
    accounts,
    profiles,
):
    """
    Attach the camera/global role profile.

    L2VA is intentionally absent from the camera User Management Permissions
    sheet. Its only valid scope is NVR Only and its actual NVR rights are read
    from the dedicated NVR User Rights sheet.
    """
    for account in accounts:
        role = account["role"]

        if role == "L2VA":
            account["level"] = USER_MANAGEMENT_DEFAULT_LEVEL
            account["scope"] = "NVR Only"
            account["select_all"] = False
            account["permissions"] = {}

            print(
                "[USER MANAGEMENT] L2VA is NVR-only. "
                "No camera permission profile will be loaded."
            )
            continue

        if role not in profiles:
            raise RuntimeError(
                f"No camera/global permission profile found for role {role}."
            )

        profile = profiles[role]

        account["level"] = profile["level"]
        account["scope"] = profile["scope"]
        account["select_all"] = profile["select_all"]
        account["permissions"] = dict(
            profile["permissions"]
        )

    return accounts


def user_role_applies_to_device(
    account,
    device_kind,
):
    scope = str(
        account.get("scope", "All Devices")
    ).strip().lower()

    if scope in {
        "",
        "all",
        "all devices",
    }:
        return True

    if scope in {
        "nvr",
        "nvr only",
    }:
        return device_kind == "NVR"

    if scope in {
        "camera",
        "cameras",
        "cameras only",
    }:
        return device_kind in {
            "DISCREET",
            "DOME",
        }

    raise RuntimeError(
        f"Unsupported Create Scope '{account.get('scope')}' "
        f"for role {account['role']}."
    )


def read_account_security_settings(excel_path):
    """
    Read device security questions and answers from:
        Account Security Settings

    Expected columns:
        Source Sheet
        Enabled
        Question 1 ID
        Question 1
        Answer 1
        Question 2 ID
        Question 2
        Answer 2
        Question 3 ID
        Question 3
        Answer 3
        Reserved Email

    Answers are intentionally not printed.
    """
    workbook = load_workbook(
        excel_path,
        data_only=True,
        read_only=True
    )

    matching_sheet = None

    for sheet_name in workbook.sheetnames:
        if (
            sheet_name.strip().lower()
            == ACCOUNT_SECURITY_SETTINGS_SHEET.lower()
        ):
            matching_sheet = workbook[sheet_name]
            break

    if matching_sheet is None:
        print(
            f"[WARNING] Excel sheet not found: "
            f"{ACCOUNT_SECURITY_SETTINGS_SHEET}"
        )
        return {}

    # Workbooks exported by some Excel libraries may leave a read-only
    # worksheet "unsized" until dimensions are calculated explicitly.
    try:
        matching_sheet.calculate_dimension(force=True)
    except Exception:
        pass

    header_row, headers = find_header_row(
        matching_sheet,
        [
            ["Source Sheet", "Device Type"],
            ["Question 1"],
            ["Answer 1"],
            ["Question 2"],
            ["Answer 2"],
            ["Question 3"],
            ["Answer 3"],
        ],
    )

    if header_row is None:
        print(
            f"[WARNING] Required Account Security Settings headers "
            f"were not found in {matching_sheet.title}"
        )
        return {}

    configurations = {}

    for values in matching_sheet.iter_rows(
        min_row=header_row + 1,
        max_row=matching_sheet.max_row,
        values_only=True,
    ):
        row = {}

        for header, value in zip(headers, values):
            if header:
                row[header] = (
                    ""
                    if value is None
                    else str(value).strip()
                )

        source_sheet = get_value(
            row,
            "Source Sheet",
            "Device Type",
        )

        if is_blank(source_sheet):
            continue

        enabled = yes_no(
            get_value(row, "Enabled", "Enable"),
            default=True,
        )

        question_entries = []

        for index in range(1, 4):
            question_id = get_value(
                row,
                f"Question {index} ID",
                f"Question{index} ID",
            )

            question_text = get_value(
                row,
                f"Question {index}",
                f"Security Question {index}",
            )

            answer = get_value(
                row,
                f"Answer {index}",
                f"Security Answer {index}",
            )

            question_entries.append({
                "id": question_id,
                "question": question_text,
                "answer": answer,
            })

        configurations[source_sheet.strip().lower()] = {
            "source_sheet": source_sheet,
            "enabled": enabled,
            "questions": question_entries,
            "reserved_email": get_value(
                row,
                "Reserved Email",
                "Recovery Email",
                "Email",
            ),
        }

    print(
        "[ACCOUNT SECURITY] Configuration rows loaded: "
        f"{len(configurations)}"
    )

    for configuration in configurations.values():
        question_summary = ", ".join(
            (
                f"Q{index} ID="
                f"{question.get('id') or 'N/A'}"
            )
            for index, question in enumerate(
                configuration["questions"],
                start=1,
            )
        )

        print(
            "[ACCOUNT SECURITY] "
            f"{configuration['source_sheet']}: "
            f"Enabled={configuration['enabled']}; "
            f"{question_summary}; answers loaded from Excel"
        )

    return configurations


def get_account_security_settings_for_row(
    row,
    configurations,
):
    source_sheet = get_value(
        row,
        "Source Sheet",
    ).strip().lower()

    configuration = configurations.get(source_sheet)

    if configuration:
        return configuration

    camera_type = get_value(
        row,
        "Camera Type",
    ).upper()

    if (
        source_sheet == "nvr_settings"
        or "NVR" in camera_type
    ):
        return configurations.get("nvr_settings")

    if "DISCREET" in camera_type or "DIS" in camera_type:
        return configurations.get("discreet_settings")

    if "DOME" in camera_type or "CAM" in camera_type:
        return configurations.get("dome_settings")

    return None


def get_service_account_for_site(
    account_configuration,
    site_id,
):
    site_id = normalize_site_id(site_id)

    account = (
        account_configuration
        .get("by_site", {})
        .get(site_id)
    )

    if account:
        return account

    return account_configuration.get("default")


def is_nvr_device_row(row):
    source_sheet = get_value(row, "Source Sheet")
    camera_type = get_value(row, "Camera Type")
    device_group = get_value(row, "Device Group")

    return (
        source_sheet == "NVR_Settings"
        or "NVR" in camera_type.upper()
        or "NVR" in device_group.upper()
    )


def camera_sequence_number(row):
    combined = " ".join([
        get_value(row, "Camera Type"),
        get_value(row, "Hostname"),
        get_value(row, "Device Group"),
    ])

    numbers = re.findall(r"(\d+)", combined)

    if not numbers:
        return 999

    try:
        return int(numbers[-1])
    except ValueError:
        return 999


def nvr_camera_sort_key(row):
    source_sheet = get_value(row, "Source Sheet")
    device_group = get_value(row, "Device Group").upper()
    camera_type = get_value(row, "Camera Type").upper()

    if (
        source_sheet == "Discreet_Settings"
        or "DISCREET" in device_group
        or "DIS" in camera_type
    ):
        group_order = 0
    else:
        group_order = 1

    ip_text = get_value(row, "Current IP")

    try:
        ip_order = int(ipaddress.ip_address(ip_text))
    except Exception:
        ip_order = 0

    return (
        group_order,
        camera_sequence_number(row),
        ip_order,
        get_value(row, "Hostname"),
    )


def build_expected_camera_map(devices):
    """
    Group Discreet/Dome camera rows by Site ID.

    Ordering:
      1. Discreet camera(s)
      2. Dome camera(s) by camera sequence
    """
    camera_map = {}

    for row in devices:
        if is_nvr_device_row(row):
            continue

        site = normalize_site_id(
            get_value(row, "Site ID")
        )
        camera_ip = get_value(row, "Current IP")

        if not site or is_blank(camera_ip):
            continue

        camera_map.setdefault(site, []).append(row)

    for site, rows in camera_map.items():
        rows.sort(key=nvr_camera_sort_key)

    return camera_map


def build_nvr_current_ip_map(devices):
    """
    Map each Site ID to the Current IP from NVR_Settings.

    Raises no exception for incomplete rows, but reports duplicate NVR rows
    that disagree on Current IP.
    """
    nvr_ip_map = {}
    conflicts = {}

    for row in devices:
        if not is_nvr_device_row(row):
            continue

        site = normalize_site_id(
            get_value(row, "Site ID")
        )
        nvr_ip = get_value(
            row,
            "Current IP",
            "current_ip"
        )

        if not site or is_blank(nvr_ip):
            continue

        existing = nvr_ip_map.get(site)

        if existing and existing != nvr_ip:
            conflicts.setdefault(
                site,
                {existing}
            ).add(nvr_ip)
            continue

        nvr_ip_map[site] = nvr_ip

    if conflicts:
        for site, values in conflicts.items():
            print(
                f"[WARNING] Multiple NVR Current IP values found for "
                f"Site {site}: {', '.join(sorted(values))}"
            )

    return nvr_ip_map


def attach_resolved_nvr_current_ip(
    devices,
    nvr_ip_map,
    results
):
    """
    Add the matching NVR Current IP to every Discreet/Dome camera row.

    It also reports when the camera NTP IP differs from the NVR Current IP,
    because the Security Audit Log will still use the NVR Current IP.
    """
    resolved_count = 0

    for row in devices:
        if is_nvr_device_row(row):
            continue

        camera_ip = get_value(
            row,
            "Current IP",
            "current_ip"
        )
        site = normalize_site_id(
            get_value(row, "Site ID")
        )

        resolved_nvr_ip = nvr_ip_map.get(
            site,
            ""
        )

        row["Resolved NVR Current IP"] = resolved_nvr_ip

        if is_blank(resolved_nvr_ip):
            print(
                f"[WARNING] Camera {camera_ip}: no matching NVR Current IP "
                f"found for Site {site}."
            )

            add_result(
                results,
                camera_ip,
                "Resolve Security Log NVR IP",
                "NVR_Settings",
                "",
                "WARNING",
                (
                    f"No NVR Current IP found for Site {site}; "
                    "compatibility fallback may be used"
                )
            )
            continue

        resolved_count += 1

        camera_ntp_ip = get_value(
            row,
            "NTP IP",
            "NTP Server IP"
        )

        if (
            not is_blank(camera_ntp_ip)
            and camera_ntp_ip != resolved_nvr_ip
        ):
            print(
                f"[WARNING] Camera {camera_ip}: NTP IP={camera_ntp_ip} "
                f"does not match NVR Current IP={resolved_nvr_ip}. "
                "Security Audit Log will use NVR Current IP."
            )

            add_result(
                results,
                camera_ip,
                "Resolve Security Log NVR IP",
                "NVR_Settings",
                "",
                "WARNING",
                (
                    f"Site={site}; "
                    f"NTP IP={camera_ntp_ip}; "
                    f"NVR Current IP={resolved_nvr_ip}; "
                    "Security Log uses NVR Current IP"
                )
            )
        else:
            add_result(
                results,
                camera_ip,
                "Resolve Security Log NVR IP",
                "NVR_Settings",
                200,
                "OK",
                (
                    f"Site={site}; "
                    f"NVR Current IP={resolved_nvr_ip}"
                )
            )

    print(
        f"[SECURITY LOG] Camera rows resolved to NVR Current IP: "
        f"{resolved_count}"
    )


# =============================================================================
# HIKVISION SHA-384 DIGEST AUTH
# =============================================================================

def parse_www_authenticate(header):
    if header.lower().startswith("digest "):
        header = header[7:]

    pattern = re.compile(r'(\w+)=("([^"]*)"|([^,]*))')
    result = {}

    for match in pattern.finditer(header):
        key = match.group(1)
        value = match.group(3) if match.group(3) is not None else match.group(4).strip()
        result[key] = value

    return result


def build_digest_header(method, url, username, password, challenge):
    algorithm = challenge.get("algorithm", "MD5").upper()
    realm = challenge["realm"]
    nonce = challenge["nonce"]
    qop = challenge.get("qop", "auth").split(",")[0].strip()

    parsed = urlparse(url)
    uri = parsed.path

    if parsed.query:
        uri += "?" + parsed.query

    is_sess = algorithm.endswith("-SESS")
    base_algorithm = algorithm.replace("-SESS", "")

    hash_map = {
        "MD5": hashlib.md5,
        "SHA": hashlib.sha1,
        "SHA-1": hashlib.sha1,
        "SHA-256": hashlib.sha256,
        "SHA-384": hashlib.sha384,
        "SHA-512": hashlib.sha512,
    }

    if base_algorithm not in hash_map:
        raise ValueError(f"Unsupported digest algorithm: {algorithm}")

    hash_func = hash_map[base_algorithm]

    def H(value):
        return hash_func(value.encode("utf-8")).hexdigest()

    nc = "00000001"
    cnonce = secrets.token_hex(8)

    ha1_initial = H(f"{username}:{realm}:{password}")

    if is_sess:
        ha1 = H(f"{ha1_initial}:{nonce}:{cnonce}")
    else:
        ha1 = ha1_initial

    ha2 = H(f"{method}:{uri}")
    response = H(f"{ha1}:{nonce}:{nc}:{cnonce}:{qop}:{ha2}")

    auth_header = (
        f'Digest username="{username}", '
        f'realm="{realm}", '
        f'nonce="{nonce}", '
        f'uri="{uri}", '
        f'algorithm={algorithm}, '
        f'response="{response}", '
        f'qop={qop}, '
        f'nc={nc}, '
        f'cnonce="{cnonce}"'
    )

    return auth_header


def build_basic_header(username, password):
    token = base64.b64encode(f"{username}:{password}".encode("utf-8")).decode("utf-8")
    return f"Basic {token}"


# ============================================================
# REQUEST TIMEOUT SETTINGS
# ============================================================
def isapi_request(
    method,
    ip,
    username,
    password,
    endpoint,
    data=None,
    extra_headers=None,
    timeout_override=None,
):
    """
    Universal Hikvision ISAPI request function.

    Supports:
      - GET
      - PUT XML / JSON
      - POST XML
      - DELETE
      - SHA-384 Digest authentication

    Important old-firmware handling:
      Some Discreet Hikvision firmware parses an empty unauthenticated PUT
      before returning the Digest challenge. The previous implementation sent
      the FIRST PUT without its XML/JSON body, so the camera could reply with:

          Device Error
          badXmlContent
          badPort

      before authentication was even attempted.

      This implementation sends the REAL request body on the first request.
      If firmware still returns an application error instead of 401, it obtains
      a Digest challenge with a safe GET /ISAPI/System/deviceInfo probe and
      retries the original request with Authorization + the real body.
    """

    method = str(method).upper()
    url = f"https://{ip}{endpoint}"

    if timeout_override is not None:
        if (
            isinstance(timeout_override, (tuple, list))
            and len(timeout_override) == 2
        ):
            request_timeout = (
                float(timeout_override[0]),
                float(timeout_override[1]),
            )
        else:
            request_timeout = (
                CONNECT_TIMEOUT,
                float(timeout_override),
            )
    elif (
        "/ISAPI/Security/serverCertificate" in endpoint
        or "/ISAPI/Security/certificate" in endpoint
        or "/ISAPI/System/logServer" in endpoint
        or "/ISAPI/ContentMgmt/InputProxy" in endpoint
        or "/ISAPI/System/configurationData" in endpoint
    ):
        request_timeout = (
            CONNECT_TIMEOUT,
            READ_TIMEOUT_CERT,
        )
    else:
        request_timeout = (
            CONNECT_TIMEOUT,
            READ_TIMEOUT_NORMAL,
        )

    headers = {
        "Connection": "close",
        "Accept": "*/*",
    }

    if extra_headers:
        headers.update(extra_headers)

    if (
        data is not None
        and "Content-Type" not in headers
    ):
        headers["Content-Type"] = "application/xml"

    request_data = (
        data.encode("utf-8")
        if isinstance(data, str)
        else data
    )

    def send_target(
        authorization=None,
    ):
        request_headers = dict(headers)

        if authorization:
            request_headers[
                "Authorization"
            ] = authorization

        return requests.request(
            method,
            url,
            data=request_data,
            timeout=request_timeout,
            verify=False,
            headers=request_headers,
        )

    def challenge_from_response(response):
        www_auth = response.headers.get(
            "WWW-Authenticate",
            "",
        )

        if "Digest" not in www_auth:
            return None

        try:
            return parse_www_authenticate(
                www_auth
            )
        except Exception:
            return None

    # -------------------------------------------------------------
    # 1. First request:
    #    send the actual body even before Authorization.
    # -------------------------------------------------------------
    r1 = send_target()

    if r1.status_code == 401:
        challenge = challenge_from_response(
            r1
        )

        if challenge is None:
            return (
                r1.status_code,
                r1.text,
                r1.headers,
            )

        authorization = build_digest_header(
            method,
            url,
            username,
            password,
            challenge,
        )

        r2 = send_target(
            authorization=authorization,
        )

        return (
            r2.status_code,
            r2.text,
            r2.headers,
        )

    # -------------------------------------------------------------
    # 2. Old-firmware fallback:
    #    if a write/delete request returned an application error instead
    #    of a Digest challenge, obtain a challenge using a harmless GET
    #    and resend the ORIGINAL target request authenticated.
    # -------------------------------------------------------------
    needs_digest_fallback = (
        method != "GET"
        and r1.status_code in {
            400,
            403,
            405,
            409,
            423,
            500,
            501,
            502,
            503,
            504,
        }
    )

    if needs_digest_fallback:
        challenge_url = (
            f"https://{ip}"
            "/ISAPI/System/deviceInfo"
        )

        challenge_headers = {
            "Connection": "close",
            "Accept": "application/xml, text/xml, */*",
        }

        try:
            # v123: honour the caller's resolved timeout budget here too.
            # Without this, a bounded InputProxy write (e.g. 5s/8s) could
            # fall back to the global 10s/30s authentication probe after an
            # initial 503 and stall far longer than intended.
            challenge_response = requests.get(
                challenge_url,
                timeout=request_timeout,
                verify=False,
                headers=challenge_headers,
            )
        except Exception:
            challenge_response = None

        if (
            challenge_response is not None
            and challenge_response.status_code == 401
        ):
            challenge = challenge_from_response(
                challenge_response
            )

            if challenge is not None:
                authorization = build_digest_header(
                    method,
                    url,
                    username,
                    password,
                    challenge,
                )

                print(
                    f"[DIGEST FALLBACK] {ip} {method} {endpoint}: "
                    f"initial HTTP {r1.status_code} returned before Digest "
                    "challenge; retrying authenticated request using "
                    "/ISAPI/System/deviceInfo challenge."
                )

                r2 = send_target(
                    authorization=authorization,
                )

                return (
                    r2.status_code,
                    r2.text,
                    r2.headers,
                )

    # No challenge was required / available.
    return (
        r1.status_code,
        r1.text,
        r1.headers,
    )


def get_xml(ip, username, password, endpoint):
    status, response, headers = isapi_request(
        "GET",
        ip,
        username,
        password,
        endpoint
    )

    return status, response


def get_xml_with_timeout(
    ip,
    username,
    password,
    endpoint,
    read_timeout_seconds,
):
    """GET helper with an explicit bounded read timeout."""
    status, response, headers = isapi_request(
        "GET",
        ip,
        username,
        password,
        endpoint,
        timeout_override=(
            CONNECT_TIMEOUT,
            float(read_timeout_seconds),
        ),
    )

    return status, response


def put_xml_with_timeout(
    ip,
    username,
    password,
    endpoint,
    xml_text,
    read_timeout_seconds,
    connect_timeout_seconds=None,
):
    """PUT XML with an explicit bounded timeout."""
    connect_timeout_seconds = (
        CONNECT_TIMEOUT
        if connect_timeout_seconds is None
        else float(connect_timeout_seconds)
    )

    status, response, headers = isapi_request(
        "PUT",
        ip,
        username,
        password,
        endpoint,
        data=xml_text,
        extra_headers={
            "Content-Type": "application/xml",
            "Accept": "application/xml, text/xml, */*",
        },
        timeout_override=(
            connect_timeout_seconds,
            float(read_timeout_seconds),
        ),
    )
    return status, response


