# =============================================================================
# NVR DEVICE PARAMETER CONFIG IMPORT
# =============================================================================

def parse_response_status_fields(response_text):
    """Return statusCode/statusString/subStatusCode from XML when present."""
    result = {
        "status_code": "",
        "status_string": "",
        "sub_status_code": "",
        "sub_status_string": "",
    }

    try:
        root = ET.fromstring(response_text)

        for element in root.iter():
            name = element.tag.split("}")[-1]
            value = (element.text or "").strip()

            if name == "statusCode":
                result["status_code"] = value
            elif name == "statusString":
                result["status_string"] = value
            elif name == "subStatusCode":
                result["sub_status_code"] = value
            elif name == "subStatusString":
                result["sub_status_string"] = value
    except Exception:
        pass

    return result


def resolve_config_import_file_path(raw_path, excel_path):
    """Resolve environment variables and relative paths from the Excel folder."""
    if is_blank(raw_path):
        return None

    expanded = os.path.expandvars(
        os.path.expanduser(str(raw_path).strip().strip('"'))
    )

    candidate = Path(expanded)

    if not candidate.is_absolute():
        candidate = Path(excel_path).resolve().parent / candidate

    return candidate


def get_nvr_config_import_token(ip, username, password):
    """
    Mirror the token request observed in the NVR web UI.

    The returned token is intentionally not printed. The documented binary
    configuration import endpoint does not require it, but fetching it verifies
    that this firmware exposes the same import-related security flow.
    """
    status, response = get_json(
        ip,
        username,
        password,
        NVR_CONFIG_TOKEN_ENDPOINT,
    )

    if status != 200:
        return status, ""

    try:
        payload = json.loads(response)
        token = str(
            payload.get("Token", {}).get("value", "")
            or payload.get("value", "")
        ).strip()
        return status, token
    except Exception:
        return status, ""


def put_nvr_device_parameter_config(
    ip,
    username,
    password,
    config_bytes,
):
    """Import an opaque Hikvision device-parameter configuration file."""
    return isapi_request(
        "PUT",
        ip,
        username,
        password,
        NVR_CONFIG_IMPORT_ENDPOINT,
        data=config_bytes,
        extra_headers={
            "Content-Type": "application/octet-stream",
            "Accept": "application/xml, text/xml, */*",
            "X-Requested-With": "XMLHttpRequest",
        },
    )


def wait_for_nvr_after_config_import(ip, username, password):
    """
    Wait for the Hikvision NVR configuration import to finish.

    Observed workflow for these NVRs:
        Import submitted
        -> NVR shows "Importing..."
        -> configuration processing takes about 3 minutes
        -> NVR reboots
        -> HTTPS / ISAPI comes back

    Do not try to judge the import during the first 3 minutes. The device can
    still be online for part of that period and then reboot later, so an early
    HTTP 200 is not proof that the import has finished.

    v52 behavior:
        1. Fixed 180-second processing/reboot wait.
        2. After that, poll authenticated /ISAPI/System/deviceInfo.
        3. Require 3 consecutive authenticated HTTP 200 responses.
        4. Only then allow PASS 1 to start.
    """

    fixed_wait = int(
        NVR_CONFIG_IMPORT_PROCESS_WAIT_SECONDS
    )

    print(
        "[NVR CONFIG IMPORT] Import submitted successfully."
    )
    print(
        f"[NVR CONFIG IMPORT] Waiting {fixed_wait} seconds "
        "for the NVR to process the configuration and reboot."
    )
    print(
        "[NVR CONFIG IMPORT] No immediate upload/reboot detection is "
        "required during this processing period."
    )

    wait_started = time_module.monotonic()
    next_progress = 30

    while True:
        elapsed = int(
            time_module.monotonic()
            - wait_started
        )

        if elapsed >= fixed_wait:
            break

        if elapsed >= next_progress:
            remaining = max(
                0,
                fixed_wait - elapsed,
            )

            print(
                f"[NVR CONFIG IMPORT] Processing/reboot wait: "
                f"{elapsed}/{fixed_wait}s elapsed, "
                f"about {remaining}s remaining."
            )

            next_progress += 30

        time_module.sleep(
            1
        )

    print(
        "[NVR CONFIG IMPORT] 3-minute processing window completed. "
        "Checking whether the NVR is fully back online."
    )

    ready_deadline = (
        time_module.monotonic()
        + NVR_CONFIG_IMPORT_POST_WAIT_TIMEOUT_SECONDS
    )

    consecutive_ready = 0
    attempt = 0
    last_status = None
    last_error = ""

    while time_module.monotonic() < ready_deadline:
        attempt += 1

        try:
            status, response = get_xml(
                ip,
                username,
                password,
                "/ISAPI/System/deviceInfo",
            )

            last_status = status
            last_error = ""

            if status == 200:
                consecutive_ready += 1

                print(
                    f"[NVR CONFIG IMPORT] Authenticated post-import probe "
                    f"{consecutive_ready}/"
                    f"{NVR_CONFIG_IMPORT_REQUIRED_READY_PROBES} succeeded."
                )

                if (
                    consecutive_ready
                    >= NVR_CONFIG_IMPORT_REQUIRED_READY_PROBES
                ):
                    print(
                        f"[OK] NVR {ip} is fully online and authenticated "
                        "after configuration import/reboot. PASS 1 may start."
                    )

                    return True, ""

            elif status in {401, 403}:
                return (
                    False,
                    "NVR is online after configuration import, but the "
                    "Excel admin credentials were rejected. The imported "
                    "configuration may have changed the credentials.",
                )

            else:
                consecutive_ready = 0

                print(
                    f"[NVR CONFIG IMPORT] NVR responded with HTTP {status}; "
                    "waiting for full readiness."
                )

        except Exception as error:
            consecutive_ready = 0
            last_error = str(error)

            print(
                f"[NVR CONFIG IMPORT] NVR not ready yet "
                f"(probe {attempt}). Waiting..."
            )

        time_module.sleep(
            max(
                2,
                NVR_CONFIG_IMPORT_RECONNECT_INTERVAL_SECONDS,
            )
        )

    return (
        False,
        f"NVR did not become stably authenticated at {ip} within "
        f"{NVR_CONFIG_IMPORT_POST_WAIT_TIMEOUT_SECONDS} seconds after the "
        f"fixed {fixed_wait}-second import/reboot wait. "
        f"last_status={last_status}; last_error={last_error}",
    )



def create_nvr_config_import_edge_driver():
    """
    Dedicated Edge session for PASS 0.

    Performance logging lets the script observe the actual network request
    generated by Hikvision's own Import button. This means we do not have to
    guess the firmware-specific file-upload endpoint.
    """
    if not SELENIUM_AVAILABLE:
        raise RuntimeError(
            "Selenium is not installed. Run: python -m pip install selenium"
        )

    options = webdriver.EdgeOptions()
    options.set_capability("acceptInsecureCerts", True)
    options.set_capability(
        "goog:loggingPrefs",
        {"performance": "ALL"},
    )

    options.add_argument("--ignore-certificate-errors")
    options.add_argument("--start-maximized")
    options.add_argument("--disable-notifications")
    options.add_argument("--disable-popup-blocking")

    if EDGE_HEADLESS:
        options.add_argument("--headless=new")
        options.add_argument("--window-size=1600,1000")

    driver = webdriver.Edge(options=options)
    driver.set_page_load_timeout(EDGE_PAGE_LOAD_TIMEOUT)
    driver.set_script_timeout(EDGE_UI_WAIT_TIMEOUT)

    return driver


def nvr_maintenance_import_page_ready(driver):
    try:
        return bool(
            driver.execute_script(
                """
                function visible(element) {
                    if (!element) return false;
                    const style = window.getComputedStyle(element);
                    const rect = element.getBoundingClientRect();

                    return (
                        style.display !== "none" &&
                        style.visibility !== "hidden" &&
                        Number(style.opacity || "1") !== 0 &&
                        rect.width > 0 &&
                        rect.height > 0
                    );
                }

                function normalize(value) {
                    return String(value || "")
                        .replace(/\\s+/g, " ")
                        .trim()
                        .toLowerCase();
                }

                const texts = Array.from(
                    document.querySelectorAll(
                        "body *"
                    )
                )
                    .filter(visible)
                    .map((element) => normalize(
                        element.innerText ||
                        element.textContent
                    ));

                return (
                    texts.some((text) =>
                        text === "upgrade & maintenance" ||
                        text.includes("upgrade & maintenance")
                    ) &&
                    texts.some((text) =>
                        text === "import config. file" ||
                        text.includes("import config. file")
                    ) &&
                    texts.some((text) =>
                        text === "device parameters" ||
                        text.includes("device parameters")
                    )
                );
                """
            )
        )
    except Exception:
        return False


def open_nvr_maintenance_import_page(
    driver,
    ip,
    username,
    password,
):
    """
    Open:
        Configuration -> System -> Maintenance -> Upgrade & Maintenance
    """
    config_url = f"https://{ip}/doc/page/config.asp"

    print(
        f"[NVR CONFIG IMPORT WEB] Opening NVR Configuration page: "
        f"{config_url}"
    )

    driver.get(config_url)
    time_module.sleep(2)

    hikvision_web_login_if_needed(
        driver,
        username,
        password,
    )

    time_module.sleep(2)

    # We may already be on Configuration because config.asp is used directly.
    # If not, click Configuration first.
    try:
        if "config.asp" not in str(driver.current_url).lower():
            click_visible_exact_text(
                driver,
                ["Configuration"],
                "NVR Configuration",
                timeout=10,
            )
            time_module.sleep(1)
    except Exception:
        pass

    # If Maintenance is already visible, don't toggle System unnecessarily.
    maintenance_visible = driver.execute_script(
        """
        function visible(element) {
            if (!element) return false;
            const style = window.getComputedStyle(element);
            const rect = element.getBoundingClientRect();

            return (
                style.display !== "none" &&
                style.visibility !== "hidden" &&
                Number(style.opacity || "1") !== 0 &&
                rect.width > 0 &&
                rect.height > 0
            );
        }

        function normalize(value) {
            return String(value || "")
                .replace(/\\s+/g, " ")
                .trim()
                .toLowerCase();
        }

        return Array.from(
            document.querySelectorAll(
                "a,button,li,div,span,p,[role='menuitem']"
            )
        ).some((element) => (
            visible(element) &&
            normalize(
                element.innerText ||
                element.textContent
            ) === "maintenance"
        ));
        """
    )

    if not maintenance_visible:
        print(
            "[NVR CONFIG IMPORT WEB] Expanding System menu."
        )

        try:
            click_visible_exact_text(
                driver,
                ["System"],
                "NVR System",
                timeout=10,
            )
        except Exception:
            click_old_ui_menu_item_robust(
                driver,
                "System",
                "NVR System",
            )

        time_module.sleep(1)

    print(
        "[NVR CONFIG IMPORT WEB] Opening Maintenance."
    )

    try:
        click_visible_exact_text(
            driver,
            ["Maintenance"],
            "NVR Maintenance",
            timeout=12,
        )
    except Exception:
        click_old_ui_menu_item_robust(
            driver,
            "Maintenance",
            "NVR Maintenance",
        )

    WebDriverWait(
        driver,
        20,
    ).until(
        lambda current_driver: (
            nvr_maintenance_import_page_ready(
                current_driver
            )
        )
    )

    print(
        "[NVR CONFIG IMPORT WEB] Maintenance import page ready."
    )


def find_file_input_in_current_frame(driver):
    """
    Find input[type=file] in the current browsing context.
    """
    try:
        elements = driver.find_elements(
            By.CSS_SELECTOR,
            "input[type='file']",
        )

        if elements:
            return elements[0]
    except Exception:
        pass

    return None


def find_file_input_recursive(driver, max_depth=5):
    """
    Search the top document and nested iframes for a file input.

    Returns:
        (element, frame_path)

    frame_path contains the frame indexes that must be entered to reach the
    element. The driver is restored to default_content before returning.
    """
    driver.switch_to.default_content()

    def search(depth, path):
        file_input = find_file_input_in_current_frame(
            driver
        )

        if file_input is not None:
            return file_input, list(path)

        if depth >= max_depth:
            return None

        frames = driver.find_elements(
            By.CSS_SELECTOR,
            "iframe,frame",
        )

        for index, frame in enumerate(frames):
            try:
                driver.switch_to.frame(frame)
            except Exception:
                continue

            found = search(
                depth + 1,
                path + [index],
            )

            if found is not None:
                return found

            driver.switch_to.parent_frame()

        return None

    found = search(0, [])

    driver.switch_to.default_content()

    return found


def switch_to_frame_path(driver, frame_path):
    """
    Enter a previously discovered iframe/frame index path.
    """
    driver.switch_to.default_content()

    for frame_index in frame_path:
        frames = driver.find_elements(
            By.CSS_SELECTOR,
            "iframe,frame",
        )

        if frame_index >= len(frames):
            raise RuntimeError(
                "The page iframe structure changed before file selection."
            )

        driver.switch_to.frame(
            frames[frame_index]
        )


def find_nvr_device_parameter_browse_button(driver):
    """
    Locate the FIRST visible enabled Browse control.

    The first Browse row is:
        Import Config. File -> Device Parameters

    The second Browse row is:
        IP Camera Parameters
    """
    driver.switch_to.default_content()

    buttons = driver.execute_script(
        """
        function visible(element) {
            if (!element) return false;

            const style =
                window.getComputedStyle(element);
            const rect =
                element.getBoundingClientRect();

            return (
                !element.disabled &&
                style.display !== "none" &&
                style.visibility !== "hidden" &&
                Number(style.opacity || "1") !== 0 &&
                rect.width > 0 &&
                rect.height > 0
            );
        }

        function normalize(value) {
            return String(value || "")
                .replace(/\\s+/g, " ")
                .trim()
                .toLowerCase();
        }

        return Array.from(
            document.querySelectorAll(
                "button,input[type='button']," +
                "input[type='submit'],a,[role='button']"
            )
        ).filter((element) => (
            visible(element) &&
            normalize(
                element.innerText ||
                element.value ||
                element.textContent
            ) === "browse"
        ));
        """
    )

    if not buttons:
        raise RuntimeError(
            "No visible Browse button was found on the NVR Maintenance page."
        )

    print(
        f"[NVR CONFIG IMPORT WEB] Browse button(s) detected: "
        f"{len(buttons)}. Using the first one for Device Parameters."
    )

    return buttons[0]


def wait_for_cdp_file_chooser_event(
    driver,
    timeout=10,
):
    """
    Wait for Page.fileChooserOpened from Edge/Chromium performance logs.
    """
    deadline = (
        time_module.monotonic()
        + max(1.0, float(timeout))
    )

    while time_module.monotonic() < deadline:
        try:
            entries = driver.get_log(
                "performance"
            )
        except Exception:
            entries = []

        for entry in entries:
            try:
                outer = json.loads(
                    entry.get("message", "{}")
                )
                message = outer.get(
                    "message",
                    {},
                )

                if (
                    message.get("method")
                    != "Page.fileChooserOpened"
                ):
                    continue

                params = message.get(
                    "params",
                    {},
                )

                return {
                    "backendNodeId": params.get(
                        "backendNodeId"
                    ),
                    "frameId": params.get(
                        "frameId"
                    ),
                    "mode": params.get(
                        "mode"
                    ),
                }

            except Exception:
                continue

        time_module.sleep(0.15)

    return None


def select_file_in_windows_open_dialog(config_path, timeout=15):
    """
    Select the NVR configuration file in the native Windows Open dialog.

    This implementation does NOT rely on keyboard Unicode SendInput for the
    file path.  On newer Windows 11 common-file dialogs that can fail even
    though the dialog itself is detected.

    Preferred flow:
      1. Find the top-level Windows Open dialog (#32770).
      2. Recursively enumerate child controls.
      3. Locate the lower, wide Edit control used by the "File name" field.
      4. Set the complete path directly with WM_SETTEXT / SetWindowTextW.
      5. Verify that the field now contains the expected path.
      6. Click the real Open button with BM_CLICK.  If it cannot be located,
         submit the dialog with WM_COMMAND / IDOK.
      7. Return True only after the Open dialog closes.

    A clipboard/keyboard fallback is retained for Windows builds where the
    filename Edit control is not exposed in the usual shell hierarchy.
    """

    if os.name != "nt":
        return False

    import ctypes
    from ctypes import wintypes

    user32 = ctypes.windll.user32
    kernel32 = ctypes.windll.kernel32

    # ------------------------------------------------------------------
    # Win32 constants
    # ------------------------------------------------------------------
    WM_SETTEXT = 0x000C
    WM_GETTEXT = 0x000D
    WM_GETTEXTLENGTH = 0x000E
    WM_COMMAND = 0x0111
    BM_CLICK = 0x00F5
    IDOK = 1

    SW_RESTORE = 9

    VK_MENU = 0x12       # ALT
    VK_CONTROL = 0x11
    VK_N = 0x4E
    VK_V = 0x56
    VK_A = 0x41
    VK_RETURN = 0x0D

    KEYEVENTF_KEYUP = 0x0002

    CF_UNICODETEXT = 13
    GMEM_MOVEABLE = 0x0002

    absolute_path = str(Path(config_path).resolve())

    # ------------------------------------------------------------------
    # ctypes signatures.  Explicit arg/restype definitions are important on
    # 64-bit Windows so HWND values are not truncated.
    # ------------------------------------------------------------------
    user32.IsWindow.argtypes = [wintypes.HWND]
    user32.IsWindow.restype = wintypes.BOOL
    user32.IsWindowVisible.argtypes = [wintypes.HWND]
    user32.IsWindowVisible.restype = wintypes.BOOL
    user32.IsWindowEnabled.argtypes = [wintypes.HWND]
    user32.IsWindowEnabled.restype = wintypes.BOOL
    user32.SetForegroundWindow.argtypes = [wintypes.HWND]
    user32.SetForegroundWindow.restype = wintypes.BOOL
    user32.ShowWindow.argtypes = [wintypes.HWND, ctypes.c_int]
    user32.ShowWindow.restype = wintypes.BOOL
    user32.SetFocus.argtypes = [wintypes.HWND]
    user32.SetFocus.restype = wintypes.HWND
    user32.GetDlgItem.argtypes = [wintypes.HWND, ctypes.c_int]
    user32.GetDlgItem.restype = wintypes.HWND
    user32.GetDlgCtrlID.argtypes = [wintypes.HWND]
    user32.GetDlgCtrlID.restype = ctypes.c_int
    user32.GetParent.argtypes = [wintypes.HWND]
    user32.GetParent.restype = wintypes.HWND
    # Python 3.13 on Windows does not expose wintypes.LRESULT on every build.
    # LRESULT/LPARAM are pointer-sized signed integers and WPARAM is a
    # pointer-sized unsigned integer. Define them explicitly for compatibility.
    LRESULT_T = ctypes.c_ssize_t
    LPARAM_T = ctypes.c_ssize_t
    WPARAM_T = ctypes.c_size_t

    user32.SendMessageW.argtypes = [
        wintypes.HWND,
        wintypes.UINT,
        WPARAM_T,
        LPARAM_T,
    ]
    user32.SendMessageW.restype = LRESULT_T
    user32.PostMessageW.argtypes = [
        wintypes.HWND,
        wintypes.UINT,
        WPARAM_T,
        LPARAM_T,
    ]
    user32.PostMessageW.restype = wintypes.BOOL

    class RECT(ctypes.Structure):
        _fields_ = [
            ("left", wintypes.LONG),
            ("top", wintypes.LONG),
            ("right", wintypes.LONG),
            ("bottom", wintypes.LONG),
        ]

    user32.GetWindowRect.argtypes = [wintypes.HWND, ctypes.POINTER(RECT)]
    user32.GetWindowRect.restype = wintypes.BOOL

    # ------------------------------------------------------------------
    # Generic helpers
    # ------------------------------------------------------------------
    def get_class_name(hwnd):
        buffer = ctypes.create_unicode_buffer(256)
        user32.GetClassNameW(hwnd, buffer, len(buffer))
        return buffer.value

    def get_window_text(hwnd):
        try:
            length = int(user32.SendMessageW(hwnd, WM_GETTEXTLENGTH, 0, 0))
        except Exception:
            length = 0

        # GetWindowTextW works for normal top-level controls.  WM_GETTEXT is
        # more reliable for an Edit control belonging to another process.
        if length > 0:
            buffer = ctypes.create_unicode_buffer(length + 2)
            user32.SendMessageW(
                hwnd,
                WM_GETTEXT,
                length + 2,
                ctypes.cast(buffer, ctypes.c_void_p).value,
            )
            if buffer.value:
                return buffer.value

        try:
            length2 = user32.GetWindowTextLengthW(hwnd)
            buffer2 = ctypes.create_unicode_buffer(max(2, length2 + 2))
            user32.GetWindowTextW(hwnd, buffer2, len(buffer2))
            return buffer2.value
        except Exception:
            return ""

    def get_rect(hwnd):
        rect = RECT()
        if not user32.GetWindowRect(hwnd, ctypes.byref(rect)):
            return None

        return {
            "left": int(rect.left),
            "top": int(rect.top),
            "right": int(rect.right),
            "bottom": int(rect.bottom),
            "width": max(0, int(rect.right - rect.left)),
            "height": max(0, int(rect.bottom - rect.top)),
            "center_y": (int(rect.top) + int(rect.bottom)) / 2.0,
        }

    def key_down(vk):
        user32.keybd_event(vk, 0, 0, 0)

    def key_up(vk):
        user32.keybd_event(vk, 0, KEYEVENTF_KEYUP, 0)

    def press_key(vk):
        key_down(vk)
        time_module.sleep(0.03)
        key_up(vk)

    def hotkey(modifier, key):
        key_down(modifier)
        time_module.sleep(0.03)
        key_down(key)
        time_module.sleep(0.03)
        key_up(key)
        time_module.sleep(0.03)
        key_up(modifier)

    # ------------------------------------------------------------------
    # Find the native Open dialog.
    # ------------------------------------------------------------------
    EnumWindowsProc = ctypes.WINFUNCTYPE(
        wintypes.BOOL,
        wintypes.HWND,
        LPARAM_T,
    )

    def find_open_dialog():
        candidates = []

        @EnumWindowsProc
        def enum_windows(hwnd, lparam):
            try:
                if not user32.IsWindowVisible(hwnd):
                    return True

                if get_class_name(hwnd) != "#32770":
                    return True

                title = get_window_text(hwnd).strip()
                title_lower = title.lower()

                if title_lower == "open" or "open" in title_lower:
                    rect = get_rect(hwnd) or {}
                    candidates.append((hwnd, rect.get("width", 0) * rect.get("height", 0)))
            except Exception:
                pass

            return True

        user32.EnumWindows(enum_windows, 0)

        if not candidates:
            return None

        # Prefer the largest visible Open dialog.  This avoids accidentally
        # selecting a small secondary #32770 dialog from another application.
        candidates.sort(key=lambda item: item[1], reverse=True)
        return candidates[0][0]

    deadline = time_module.monotonic() + max(1.0, float(timeout))
    dialog_hwnd = None

    while time_module.monotonic() < deadline:
        dialog_hwnd = find_open_dialog()
        if dialog_hwnd:
            break
        time_module.sleep(0.15)

    if not dialog_hwnd:
        return False

    print(
        "[WINDOWS CONFIG FILE PICKER] "
        "Native Windows Open dialog detected."
    )

    try:
        user32.ShowWindow(dialog_hwnd, SW_RESTORE)
    except Exception:
        pass

    try:
        user32.SetForegroundWindow(dialog_hwnd)
    except Exception:
        pass

    time_module.sleep(0.4)

    # ------------------------------------------------------------------
    # Recursively enumerate all descendants.  The Windows 11 File name field
    # is usually an Edit nested under ComboBox/ComboBoxEx32, not a direct child
    # of the #32770 dialog.
    # ------------------------------------------------------------------
    EnumChildProc = ctypes.WINFUNCTYPE(
        wintypes.BOOL,
        wintypes.HWND,
        LPARAM_T,
    )

    def enumerate_descendants(parent_hwnd):
        descendants = []

        @EnumChildProc
        def enum_child(hwnd, lparam):
            try:
                descendants.append(hwnd)
            except Exception:
                pass
            return True

        # EnumChildWindows recursively enumerates descendants, not only direct
        # children, which is exactly what we need for the modern shell dialog.
        user32.EnumChildWindows(parent_hwnd, enum_child, 0)
        return descendants

    descendants = enumerate_descendants(dialog_hwnd)
    dialog_rect = get_rect(dialog_hwnd)

    # ------------------------------------------------------------------
    # Find the File name Edit control.
    # ------------------------------------------------------------------
    edit_candidates = []

    for hwnd in descendants:
        try:
            if get_class_name(hwnd).lower() != "edit":
                continue
            if not user32.IsWindowVisible(hwnd):
                continue
            if not user32.IsWindowEnabled(hwnd):
                continue

            rect = get_rect(hwnd)
            if not rect:
                continue

            # Ignore tiny edits.  File name and Search are both wide, but the
            # File name box is near the bottom of the Open dialog.
            if rect["width"] < 120 or rect["height"] < 15:
                continue

            relative_y = 0.0
            if dialog_rect and dialog_rect["height"] > 0:
                relative_y = (
                    rect["center_y"] - dialog_rect["top"]
                ) / float(dialog_rect["height"])

            score = 0.0
            score += min(rect["width"], 1200) / 10.0
            score += relative_y * 1000.0

            # A file-name box is normally in the lower third of the dialog.
            if relative_y >= 0.65:
                score += 1000.0
            elif relative_y >= 0.50:
                score += 400.0

            # Search boxes typically contain placeholder/search text and sit
            # at the top.  Penalise them when the text exposes that clue.
            current_text = get_window_text(hwnd).strip().lower()
            if "search" in current_text:
                score -= 2000.0

            edit_candidates.append((score, hwnd, rect, current_text))
        except Exception:
            continue

    edit_candidates.sort(key=lambda item: item[0], reverse=True)

    file_name_edit = edit_candidates[0][1] if edit_candidates else None

    if file_name_edit:
        chosen_rect = edit_candidates[0][2]
        print(
            "[WINDOWS CONFIG FILE PICKER] "
            "Windows File name Edit control located: "
            f"x={chosen_rect['left']}, y={chosen_rect['top']}, "
            f"w={chosen_rect['width']}, h={chosen_rect['height']}."
        )

        try:
            user32.SetFocus(file_name_edit)
        except Exception:
            pass

        # Directly set the path in the actual Edit control.  WM_SETTEXT is
        # marshalled by Windows for standard controls and avoids SendInput/UIPI
        # keyboard issues.
        path_buffer = ctypes.create_unicode_buffer(absolute_path)
        result = user32.SendMessageW(
            file_name_edit,
            WM_SETTEXT,
            0,
            ctypes.cast(path_buffer, ctypes.c_void_p).value,
        )

        time_module.sleep(0.3)

        entered_text = get_window_text(file_name_edit)

        if entered_text != absolute_path:
            # SetWindowTextW is a useful second method for a few shell builds.
            try:
                user32.SetWindowTextW(file_name_edit, absolute_path)
            except Exception:
                pass

            time_module.sleep(0.3)
            entered_text = get_window_text(file_name_edit)

        if entered_text == absolute_path:
            print(
                "[WINDOWS CONFIG FILE PICKER] "
                "Config file path entered into Windows File name field."
            )
        else:
            print(
                "[NVR CONFIG IMPORT WEB WARNING] "
                "Direct WM_SETTEXT did not verify; trying clipboard paste."
            )
            file_name_edit = None

    # ------------------------------------------------------------------
    # Clipboard/keyboard fallback if the shell does not expose a usable Edit.
    # This is much more reliable than sending the full path one Unicode
    # character at a time.
    # ------------------------------------------------------------------
    def set_clipboard_unicode(text):
        if not user32.OpenClipboard(None):
            return False

        memory_handle = None
        try:
            user32.EmptyClipboard()

            encoded = (str(text) + "\0").encode("utf-16-le")
            memory_handle = kernel32.GlobalAlloc(GMEM_MOVEABLE, len(encoded))
            if not memory_handle:
                return False

            pointer = kernel32.GlobalLock(memory_handle)
            if not pointer:
                kernel32.GlobalFree(memory_handle)
                return False

            ctypes.memmove(pointer, encoded, len(encoded))
            kernel32.GlobalUnlock(memory_handle)

            if not user32.SetClipboardData(CF_UNICODETEXT, memory_handle):
                kernel32.GlobalFree(memory_handle)
                return False

            # Ownership transfers to the clipboard after SetClipboardData.
            memory_handle = None
            return True
        finally:
            user32.CloseClipboard()
            if memory_handle:
                try:
                    kernel32.GlobalFree(memory_handle)
                except Exception:
                    pass

    if file_name_edit is None:
        try:
            user32.SetForegroundWindow(dialog_hwnd)
        except Exception:
            pass

        time_module.sleep(0.2)

        # Alt+N is the standard File name accelerator on the English Windows
        # common dialog shown in the user's screenshot.
        hotkey(VK_MENU, VK_N)
        time_module.sleep(0.2)
        hotkey(VK_CONTROL, VK_A)
        time_module.sleep(0.1)

        if not set_clipboard_unicode(absolute_path):
            raise RuntimeError(
                "Unable to place the config file path on the Windows clipboard."
            )

        hotkey(VK_CONTROL, VK_V)
        time_module.sleep(0.5)

        print(
            "[WINDOWS CONFIG FILE PICKER] "
            "Config file path pasted into Windows File name field."
        )

    # ------------------------------------------------------------------
    # Click the real Open button.
    # ------------------------------------------------------------------
    open_button = None

    # IDOK is usually the actual Open split/default button.
    try:
        candidate = user32.GetDlgItem(dialog_hwnd, IDOK)
        if candidate and user32.IsWindow(candidate):
            open_button = candidate
    except Exception:
        pass

    if open_button is None:
        for hwnd in descendants:
            try:
                if get_class_name(hwnd).lower() != "button":
                    continue
                if not user32.IsWindowVisible(hwnd) or not user32.IsWindowEnabled(hwnd):
                    continue

                text = get_window_text(hwnd).replace("&", "").strip().lower()
                if text == "open" or text.startswith("open"):
                    open_button = hwnd
                    break
            except Exception:
                continue

    if open_button is not None:
        try:
            user32.SetForegroundWindow(dialog_hwnd)
        except Exception:
            pass

        time_module.sleep(0.15)

        user32.SendMessageW(open_button, BM_CLICK, 0, 0)

        print(
            "[WINDOWS CONFIG FILE PICKER] "
            "Windows Open button clicked."
        )
    else:
        # Fallback to the dialog's default OK/Open command.
        user32.PostMessageW(dialog_hwnd, WM_COMMAND, IDOK, 0)

        print(
            "[WINDOWS CONFIG FILE PICKER] "
            "Windows Open submitted through IDOK."
        )

    # ------------------------------------------------------------------
    # Wait for the native dialog to close.  Only then return success so the
    # Selenium code can continue to the Hikvision Import button.
    # ------------------------------------------------------------------
    close_deadline = time_module.monotonic() + 10.0

    while time_module.monotonic() < close_deadline:
        if (
            not user32.IsWindow(dialog_hwnd)
            or not user32.IsWindowVisible(dialog_hwnd)
        ):
            print(
                "[WINDOWS CONFIG FILE PICKER] "
                "Windows Open dialog closed successfully."
            )
            return True

        time_module.sleep(0.2)

    # One final foreground + Enter fallback.  This also handles a split Open
    # button that did not react to BM_CLICK.
    try:
        user32.SetForegroundWindow(dialog_hwnd)
    except Exception:
        pass

    press_key(VK_RETURN)
    time_module.sleep(1.0)

    if (
        not user32.IsWindow(dialog_hwnd)
        or not user32.IsWindowVisible(dialog_hwnd)
    ):
        print(
            "[WINDOWS CONFIG FILE PICKER] "
            "Windows Open dialog closed after final Enter."
        )
        return True

    raise RuntimeError(
        "The config path was entered, but the Windows Open dialog did not "
        "close after clicking Open. Check whether Windows displayed a file "
        "validation/error message inside the Open dialog."
    )

def select_nvr_device_parameter_config_file(
    driver,
    config_path,
):
    """
    Select the local NVR Device Parameters configuration file.

    Selection order:

        1. Use an existing input[type=file], if the firmware exposes one.

        2. For the older Hikvision NVR UI:
           - Click the FIRST Browse button under Device Parameters.
           - Handle the real Windows Open dialog.
           - Enter the complete config-file path.
           - Click/activate Open.
           - Return after the Windows dialog closes.

        3. If no native Windows dialog appears:
           - Try Chromium CDP file chooser interception.

        4. Final fallback:
           - Search again for a dynamically-created input[type=file].

    IMPORTANT:
        Do NOT enable Page.setInterceptFileChooserDialog before the first
        Browse click. This NVR firmware opens a native Windows File Open
        dialog instead of exposing a normal Chromium chooser event.
    """

    absolute_path = str(
        Path(config_path).resolve()
    )

    # ================================================================
    # Validate config file first
    # ================================================================

    if not Path(absolute_path).exists():
        raise FileNotFoundError(
            f"NVR configuration file does not exist: "
            f"{absolute_path}"
        )

    if not Path(absolute_path).is_file():
        raise RuntimeError(
            f"NVR configuration path is not a file: "
            f"{absolute_path}"
        )

    print(
        "[NVR CONFIG IMPORT WEB] "
        f"Preparing config file: {absolute_path}"
    )

    # ================================================================
    # METHOD 1
    # Existing input[type=file]
    # ================================================================

    found = find_file_input_recursive(
        driver
    )

    if found is not None:

        file_input, frame_path = found

        print(
            "[NVR CONFIG IMPORT WEB] "
            "Existing input[type=file] detected."
        )

        switch_to_frame_path(
            driver,
            frame_path,
        )

        try:
            file_input.send_keys(
                absolute_path
            )

            time_module.sleep(
                1
            )

            print(
                "[NVR CONFIG IMPORT WEB] "
                "Device Parameters file selected through "
                "existing input[type=file]."
            )

            return True

        except Exception as error:

            print(
                "[NVR CONFIG IMPORT WEB WARNING] "
                "Existing input[type=file] could not be used: "
                f"{error}"
            )

        finally:

            driver.switch_to.default_content()

    # ================================================================
    # METHOD 2
    # Native Windows File Open dialog
    # ================================================================

    driver.switch_to.default_content()

    print(
        "[NVR CONFIG IMPORT WEB] "
        "No usable persistent input[type=file] exists. "
        "Using native Windows File Open dialog."
    )

    # Clear old browser performance events.
    #
    # We do NOT enable Page.setInterceptFileChooserDialog here.
    try:
        driver.get_log(
            "performance"
        )
    except Exception:
        pass

    # ------------------------------------------------------------
    # Locate FIRST Browse button:
    #
    # Import Config. File
    #     Device Parameters      [Browse] [Import]
    #
    # NOT:
    #     IP Camera Parameters   [Browse] [Import]
    # ------------------------------------------------------------

    browse_button = (
        find_nvr_device_parameter_browse_button(
            driver
        )
    )

    if browse_button is None:
        raise RuntimeError(
            "Device Parameters Browse button was not found."
        )

    # ------------------------------------------------------------
    # Bring Browse button into view
    # ------------------------------------------------------------

    try:
        driver.execute_script(
            """
            arguments[0].scrollIntoView({
                block: "center",
                inline: "center"
            });
            """,
            browse_button,
        )
    except Exception:
        pass

    time_module.sleep(
        0.3
    )

    # ------------------------------------------------------------
    # Click Browse
    # ------------------------------------------------------------

    browse_clicked = False

    try:
        browse_button.click()

        browse_clicked = True

        print(
            "[NVR CONFIG IMPORT WEB] "
            "Device Parameters Browse clicked."
        )

    except Exception as click_error:

        print(
            "[NVR CONFIG IMPORT WEB WARNING] "
            "Normal Browse click failed; trying JavaScript click. "
            f"Detail: {click_error}"
        )

    if not browse_clicked:

        try:
            driver.execute_script(
                "arguments[0].click();",
                browse_button,
            )

            browse_clicked = True

            print(
                "[NVR CONFIG IMPORT WEB] "
                "Device Parameters Browse clicked "
                "using JavaScript."
            )

        except Exception as js_error:

            print(
                "[NVR CONFIG IMPORT WEB WARNING] "
                "JavaScript Browse click failed; "
                "trying trusted CDP mouse click. "
                f"Detail: {js_error}"
            )

    # ------------------------------------------------------------
    # Trusted mouse-click fallback
    # ------------------------------------------------------------

    if not browse_clicked:

        coordinates = driver.execute_script(
            """
            const element = arguments[0];

            element.scrollIntoView({
                block: "center",
                inline: "center"
            });

            const rect =
                element.getBoundingClientRect();

            return {
                x: rect.left + rect.width / 2,
                y: rect.top + rect.height / 2
            };
            """,
            browse_button,
        )

        click_x = float(
            coordinates["x"]
        )

        click_y = float(
            coordinates["y"]
        )

        for event_type, button_name in [
            ("mouseMoved", "none"),
            ("mousePressed", "left"),
            ("mouseReleased", "left"),
        ]:

            event_payload = {
                "type": event_type,
                "x": click_x,
                "y": click_y,
                "button": button_name,
            }

            if event_type != "mouseMoved":
                event_payload[
                    "clickCount"
                ] = 1

            driver.execute_cdp_cmd(
                "Input.dispatchMouseEvent",
                event_payload,
            )

        browse_clicked = True

        print(
            "[NVR CONFIG IMPORT WEB] "
            "Device Parameters Browse clicked "
            "using trusted CDP mouse event."
        )

    if not browse_clicked:
        raise RuntimeError(
            "Unable to click Device Parameters Browse."
        )

    # Give Windows time to create the Open dialog.
    time_module.sleep(
        0.5
    )

    # ------------------------------------------------------------
    # Handle Windows Open dialog
    # ------------------------------------------------------------

    try:

        native_selected = (
            select_file_in_windows_open_dialog(
                config_path,
                timeout=15,
            )
        )

    except Exception as native_error:

        # If Windows dialog was found but couldn't be completed,
        # do NOT silently continue because a modal Open window
        # may still be blocking Edge.
        raise RuntimeError(
            "Native Windows File Open dialog was detected "
            "but file selection/Open failed: "
            f"{native_error}"
        ) from native_error

    if native_selected:

        time_module.sleep(
            1.5
        )

        print(
            "[NVR CONFIG IMPORT WEB] "
            "Device Parameters file selected through "
            "native Windows File Open dialog."
        )

        return True

    # ================================================================
    # METHOD 3
    # Chromium CDP chooser fallback
    #
    # Only reach here if no native Windows Open dialog was detected.
    # ================================================================

    print(
        "[NVR CONFIG IMPORT WEB] "
        "Native Windows File Open dialog was not detected. "
        "Trying Chromium CDP file chooser fallback."
    )

    cdp_interception_enabled = False

    try:

        driver.execute_cdp_cmd(
            "Page.setInterceptFileChooserDialog",
            {
                "enabled": True
            },
        )

        cdp_interception_enabled = True

        # Clear previous events.
        try:
            driver.get_log(
                "performance"
            )
        except Exception:
            pass

        # --------------------------------------------------------
        # Click Browse again now that CDP interception is enabled
        # --------------------------------------------------------

        browse_button = (
            find_nvr_device_parameter_browse_button(
                driver
            )
        )

        try:
            browse_button.click()

        except Exception:

            driver.execute_script(
                "arguments[0].click();",
                browse_button,
            )

        print(
            "[NVR CONFIG IMPORT WEB] "
            "Device Parameters Browse clicked "
            "for CDP chooser fallback."
        )

        # --------------------------------------------------------
        # Wait for Page.fileChooserOpened
        # --------------------------------------------------------

        chooser = (
            wait_for_cdp_file_chooser_event(
                driver,
                timeout=6,
            )
        )

        if chooser is not None:

            backend_node_id = (
                chooser.get(
                    "backendNodeId"
                )
            )

            if backend_node_id:

                driver.execute_cdp_cmd(
                    "DOM.setFileInputFiles",
                    {
                        "files": [
                            absolute_path
                        ],
                        "backendNodeId": int(
                            backend_node_id
                        ),
                    },
                )

                print(
                    "[NVR CONFIG IMPORT WEB] "
                    "Local config file assigned through "
                    "CDP DOM.setFileInputFiles."
                )

                time_module.sleep(
                    1
                )

                return True

    except Exception as cdp_error:

        print(
            "[NVR CONFIG IMPORT WEB WARNING] "
            "CDP file chooser fallback failed: "
            f"{cdp_error}"
        )

    finally:

        if cdp_interception_enabled:

            try:
                driver.execute_cdp_cmd(
                    "Page.setInterceptFileChooserDialog",
                    {
                        "enabled": False
                    },
                )
            except Exception:
                pass

    # ================================================================
    # METHOD 4
    # Final fallback:
    # Browse may have dynamically created input[type=file]
    # ================================================================

    print(
        "[NVR CONFIG IMPORT WEB] "
        "Checking for dynamically-created input[type=file]."
    )

    time_module.sleep(
        0.5
    )

    found_after_browse = (
        find_file_input_recursive(
            driver
        )
    )

    if found_after_browse is not None:

        file_input, frame_path = (
            found_after_browse
        )

        switch_to_frame_path(
            driver,
            frame_path,
        )

        try:

            file_input.send_keys(
                absolute_path
            )

            time_module.sleep(
                1
            )

            print(
                "[NVR CONFIG IMPORT WEB] "
                "Local config file assigned through "
                "dynamically-created input[type=file]."
            )

            return True

        finally:

            driver.switch_to.default_content()

    # ================================================================
    # Nothing worked
    # ================================================================

    driver.switch_to.default_content()

    raise RuntimeError(
        "Unable to select the NVR Device Parameters configuration file. "
        "The script tried an existing HTML file input, the native Windows "
        "Open dialog, Chromium CDP file chooser interception, and a "
        "dynamically-created HTML file input."
    )



def find_nvr_device_parameter_import_button(
    driver,
    timeout=25,
):
    """
    Wait for the NVR Device Parameters Import button to become enabled.

    On the old NVR UI the file path can already be visible immediately after
    Windows Open closes, while the Import button remains disabled for a short
    period as the page processes the selected file. The previous one-shot
    lookup could therefore fail even though file selection succeeded.
    """
    deadline = time_module.monotonic() + timeout
    last_state = None

    while time_module.monotonic() < deadline:
        try:
            state = driver.execute_script(
                """
                function visible(element) {
                    if (!element) return false;

                    const style = window.getComputedStyle(element);
                    const rect = element.getBoundingClientRect();

                    return (
                        style.display !== "none" &&
                        style.visibility !== "hidden" &&
                        Number(style.opacity || "1") !== 0 &&
                        rect.width > 0 &&
                        rect.height > 0
                    );
                }

                function normalize(value) {
                    return String(value || "")
                        .replace(/\\s+/g, " ")
                        .trim()
                        .toLowerCase();
                }

                function isDisabled(element) {
                    const ariaDisabled = normalize(
                        element.getAttribute("aria-disabled")
                    );

                    const className = normalize(
                        element.className
                    );

                    return (
                        Boolean(element.disabled) ||
                        ariaDisabled === "true" ||
                        className.includes("disabled") ||
                        className.includes("is-disabled")
                    );
                }

                const imports = Array.from(
                    document.querySelectorAll(
                        "button,input[type='button'],input[type='submit']," +
                        "a,[role='button']"
                    )
                ).filter((element) => (
                    visible(element) &&
                    normalize(
                        element.innerText ||
                        element.value ||
                        element.textContent
                    ) === "import"
                ));

                const labels = Array.from(
                    document.querySelectorAll(
                        "label,div,span,p,td"
                    )
                ).filter((element) => {
                    if (!visible(element)) return false;

                    const text = normalize(
                        element.innerText ||
                        element.textContent
                    );

                    return (
                        text === "device parameters" ||
                        text === "device parameter"
                    );
                });

                let best = null;
                let bestScore = Infinity;

                for (const button of imports) {
                    const br = button.getBoundingClientRect();

                    for (const label of labels) {
                        const lr = label.getBoundingClientRect();

                        const vertical = Math.abs(
                            (br.top + br.height / 2) -
                            (lr.top + lr.height / 2)
                        );

                        if (vertical > 120) continue;

                        const score = (
                            vertical * 20 +
                            Math.abs(br.left - lr.right)
                        );

                        if (score < bestScore) {
                            best = button;
                            bestScore = score;
                        }
                    }
                }

                // Old NVR page normally has two Import buttons:
                // Device Parameters first, IP Camera Parameters second.
                // If geometry could not identify it, prefer the first visible
                // Import button rather than failing immediately.
                if (!best && imports.length) {
                    best = imports[0];
                }

                if (!best) {
                    return {
                        found: false,
                        totalImports: imports.length,
                        labelCount: labels.length
                    };
                }

                const rect = best.getBoundingClientRect();

                return {
                    found: true,
                    enabled: !isDisabled(best),
                    element: best,
                    text: normalize(
                        best.innerText ||
                        best.value ||
                        best.textContent
                    ),
                    tag: best.tagName,
                    className: String(best.className || ""),
                    disabledProperty: Boolean(best.disabled),
                    ariaDisabled: best.getAttribute("aria-disabled") || "",
                    x: rect.x,
                    y: rect.y,
                    width: rect.width,
                    height: rect.height,
                    totalImports: imports.length,
                    labelCount: labels.length
                };
                """
            )

            last_state = state

            if state and state.get("found"):
                if state.get("enabled"):
                    print(
                        "[NVR CONFIG IMPORT WEB] Device Parameters Import "
                        f"button enabled: {state}"
                    )
                    return state.get("element")

                print(
                    "[NVR CONFIG IMPORT WEB] Device Parameters Import button "
                    "is present but still disabled; waiting for NVR web UI "
                    f"to register the selected file. detail={state}"
                )

        except Exception as error:
            last_state = str(error)

        time_module.sleep(0.75)

    raise RuntimeError(
        "Device Parameters Import button did not become enabled within "
        f"{timeout} seconds after file selection. Last state: {last_state}"
    )



def click_nvr_import_confirmation_if_present(driver):
    """
    Some firmware shows a confirmation modal after Import is clicked.
    Click only an OK/Yes/Confirm button inside a visible dialog-like element.
    """
    try:
        confirmation = driver.execute_script(
            """
            function visible(element) {
                if (!element) return false;

                const style = window.getComputedStyle(element);
                const rect = element.getBoundingClientRect();

                return (
                    style.display !== "none" &&
                    style.visibility !== "hidden" &&
                    Number(style.opacity || "1") !== 0 &&
                    rect.width > 0 &&
                    rect.height > 0
                );
            }

            function normalize(value) {
                return String(value || "")
                    .replace(/\\s+/g, " ")
                    .trim()
                    .toLowerCase();
            }

            const dialogs = Array.from(
                document.querySelectorAll(
                    "[role='dialog'],.dialog,.modal,.window," +
                    ".aui_dialog,.el-message-box"
                )
            ).filter(visible);

            for (const dialog of dialogs) {
                const text = normalize(
                    dialog.innerText ||
                    dialog.textContent
                );

                if (
                    !text.includes("import") &&
                    !text.includes("configuration") &&
                    !text.includes("parameter")
                ) {
                    continue;
                }

                const action = Array.from(
                    dialog.querySelectorAll(
                        "button,input[type='button']," +
                        "input[type='submit'],a,[role='button']"
                    )
                ).find((element) => {
                    if (!visible(element) || element.disabled) {
                        return false;
                    }

                    const value = normalize(
                        element.innerText ||
                        element.value ||
                        element.textContent
                    );

                    return [
                        "ok",
                        "yes",
                        "confirm",
                        "continue"
                    ].includes(value);
                });

                if (action) {
                    return action;
                }
            }

            return null;
            """
        )

        if confirmation is not None:
            try:
                confirmation.click()
            except Exception:
                driver.execute_script(
                    "arguments[0].click();",
                    confirmation,
                )

            print(
                "[NVR CONFIG IMPORT WEB] Import confirmation accepted."
            )

            return True
    except Exception:
        pass

    return False



def find_nvr_file_decryption_dialog(driver):
    """
    Return the visible Hikvision 'File Decryption' dialog element.
    """
    try:
        return driver.execute_script(
            """
            function visible(element) {
                if (!element) return false;

                const style =
                    window.getComputedStyle(element);
                const rect =
                    element.getBoundingClientRect();

                return (
                    style.display !== "none" &&
                    style.visibility !== "hidden" &&
                    Number(style.opacity || "1") !== 0 &&
                    rect.width > 0 &&
                    rect.height > 0
                );
            }

            function normalize(value) {
                return String(value || "")
                    .replace(/\\s+/g, " ")
                    .trim()
                    .toLowerCase();
            }

            const containers = Array.from(
                document.querySelectorAll(
                    "[role='dialog'],.dialog,.modal,.window," +
                    ".aui_dialog,.ui-dialog,.layui-layer," +
                    "div"
                )
            ).filter(visible);

            const matches = containers.filter(
                (element) => {
                    const text = normalize(
                        element.innerText ||
                        element.textContent
                    );

                    return (
                        text.includes("file decryption") &&
                        text.includes("password")
                    );
                }
            );

            if (!matches.length) {
                return null;
            }

            matches.sort((first, second) => {
                const a =
                    first.getBoundingClientRect();
                const b =
                    second.getBoundingClientRect();

                return (
                    (a.width * a.height)
                    - (b.width * b.height)
                );
            });

            return matches[0];
            """
        )
    except Exception:
        return None


def submit_nvr_config_decryption_password(
    driver,
    import_password,
    timeout=15,
):
    """
    Enter the configuration-file decryption password and click OK.

    Returns:
        True  -> File Decryption popup appeared and was submitted.
        False -> No File Decryption popup appeared.
    """
    try:
        dialog = WebDriverWait(
            driver,
            timeout,
        ).until(
            lambda current_driver: (
                find_nvr_file_decryption_dialog(
                    current_driver
                )
                or False
            )
        )
    except Exception:
        return False

    if is_blank(import_password):
        raise RuntimeError(
            "The device displayed File Decryption, but "
            "'Device Parameter Config Password' is blank for this Excel row. "
            f"Workbook: {DEVICES_EXCEL}"
        )

    inputs = dialog.find_elements(
        By.CSS_SELECTOR,
        "input:not([type='button']):not([type='submit']):not([type='hidden'])",
    )

    visible_inputs = []

    for element in inputs:
        try:
            if element.is_displayed() and element.is_enabled():
                visible_inputs.append(
                    element
                )
        except Exception:
            pass

    if not visible_inputs:
        raise RuntimeError(
            "File Decryption dialog opened, but its password input "
            "could not be located."
        )

    password_input = None

    for element in visible_inputs:
        try:
            if (
                str(
                    element.get_attribute(
                        "type"
                    )
                    or ""
                ).lower()
                == "password"
            ):
                password_input = element
                break
        except Exception:
            pass

    if password_input is None:
        password_input = visible_inputs[0]

    try:
        password_input.clear()
    except Exception:
        pass

    password_input.send_keys(
        str(import_password)
    )

    print(
        "[NVR CONFIG IMPORT WEB] File Decryption password entered "
        "from Excel."
    )

    ok_button = driver.execute_script(
        """
        const dialog = arguments[0];

        function visible(element) {
            if (!element) return false;

            const style =
                window.getComputedStyle(element);
            const rect =
                element.getBoundingClientRect();

            return (
                !element.disabled &&
                style.display !== "none" &&
                style.visibility !== "hidden" &&
                Number(style.opacity || "1") !== 0 &&
                rect.width > 0 &&
                rect.height > 0
            );
        }

        function normalize(value) {
            return String(value || "")
                .replace(/\\s+/g, " ")
                .trim()
                .toLowerCase();
        }

        return Array.from(
            dialog.querySelectorAll(
                "button,input[type='button']," +
                "input[type='submit'],a,[role='button']"
            )
        ).find((element) => (
            visible(element) &&
            normalize(
                element.innerText ||
                element.value ||
                element.textContent
            ) === "ok"
        )) || null;
        """,
        dialog,
    )

    if ok_button is None:
        raise RuntimeError(
            "File Decryption dialog OK button was not found."
        )

    try:
        ok_button.click()

        click_method = "native Selenium click"

    except Exception:
        coords = driver.execute_script(
            """
            const element = arguments[0];
            element.scrollIntoView({
                block: "center",
                inline: "center"
            });

            const rect =
                element.getBoundingClientRect();

            return {
                x: rect.left + rect.width / 2,
                y: rect.top + rect.height / 2
            };
            """,
            ok_button,
        )

        click_x = float(
            coords["x"]
        )
        click_y = float(
            coords["y"]
        )

        for event_type, button_name in [
            ("mouseMoved", "none"),
            ("mousePressed", "left"),
            ("mouseReleased", "left"),
        ]:
            event = {
                "type": event_type,
                "x": click_x,
                "y": click_y,
                "button": button_name,
            }

            if event_type != "mouseMoved":
                event["clickCount"] = 1

            driver.execute_cdp_cmd(
                "Input.dispatchMouseEvent",
                event,
            )

        click_method = "trusted CDP mouse click"

    print(
        f"[NVR CONFIG IMPORT WEB] File Decryption OK clicked "
        f"using {click_method}."
    )

    # Wait for the popup to disappear. The NVR may start importing
    # immediately after this.
    try:
        WebDriverWait(
            driver,
            15,
        ).until(
            lambda current_driver: (
                find_nvr_file_decryption_dialog(
                    current_driver
                )
                is None
            )
        )
    except Exception:
        # Do not immediately fail: some firmware keeps the overlay for a few
        # seconds while the upload request begins. Network capture below will
        # determine whether a real upload was generated.
        print(
            "[NVR CONFIG IMPORT WEB WARNING] File Decryption dialog "
            "did not disappear immediately; checking network activity."
        )

    return True



def nvr_config_importing_state_visible(driver):
    """
    Return True when the Hikvision Maintenance UI visibly shows that the
    configuration file is being processed, normally as:

        Note
        Importing...

    On this NVR firmware this UI state is a reliable indication that the file
    and decryption password were accepted, even when Edge does not expose the
    underlying upload request in performance logs.
    """
    try:
        return bool(
            driver.execute_script(
                """
                function visible(element) {
                    if (!element) return false;

                    const style = window.getComputedStyle(element);
                    const rect = element.getBoundingClientRect();

                    return (
                        style.display !== "none" &&
                        style.visibility !== "hidden" &&
                        Number(style.opacity || "1") !== 0 &&
                        rect.width > 0 &&
                        rect.height > 0
                    );
                }

                function normalize(value) {
                    return String(value || "")
                        .replace(/\\s+/g, " ")
                        .trim()
                        .toLowerCase();
                }

                return Array.from(
                    document.querySelectorAll("body *")
                )
                .filter(visible)
                .some((element) => {
                    const text = normalize(
                        element.innerText ||
                        element.textContent
                    );

                    return (
                        text === "importing..." ||
                        text === "importing" ||
                        text.includes("importing...")
                    );
                });
                """
            )
        )
    except Exception:
        return False


def wait_for_nvr_config_importing_state(driver, timeout=8):
    """Wait briefly for the Hikvision 'Importing...' state."""
    deadline = (
        time_module.monotonic()
        + max(1.0, float(timeout))
    )

    while time_module.monotonic() < deadline:
        if nvr_config_importing_state_visible(driver):
            print(
                "[NVR CONFIG IMPORT WEB] Hikvision UI entered "
                "'Importing...' state. Import request accepted."
            )
            return True

        time_module.sleep(0.25)

    return False


def collect_nvr_config_import_network_events(
    driver,
    capture_seconds,
):
    """
    Capture the actual requests produced by the Hikvision UI.

    This is diagnostic and also prevents the script from claiming success when
    the Import button did not generate any upload request.
    """
    deadline = (
        time_module.monotonic()
        + max(1, float(capture_seconds))
    )

    requests_seen = {}
    responses_seen = {}

    while time_module.monotonic() < deadline:
        try:
            log_entries = driver.get_log(
                "performance"
            )
        except Exception:
            log_entries = []

        for entry in log_entries:
            try:
                outer = json.loads(
                    entry.get("message", "{}")
                )
                message = outer.get("message", {})
                method = message.get("method", "")
                params = message.get("params", {})

                if method == "Network.requestWillBeSent":
                    request = params.get("request", {})
                    url = str(
                        request.get("url", "")
                    )

                    if "/ISAPI/" not in url:
                        continue

                    request_id = str(
                        params.get("requestId", "")
                    )

                    requests_seen[request_id] = {
                        "url": url,
                        "method": str(
                            request.get("method", "")
                        ).upper(),
                    }

                elif method == "Network.responseReceived":
                    response = params.get(
                        "response",
                        {},
                    )
                    url = str(
                        response.get("url", "")
                    )

                    if "/ISAPI/" not in url:
                        continue

                    request_id = str(
                        params.get("requestId", "")
                    )

                    responses_seen[request_id] = {
                        "url": url,
                        "status": int(
                            response.get("status", 0)
                            or 0
                        ),
                    }

            except Exception:
                continue

        # If we already captured the token request and a likely upload request,
        # give the response a short chance to arrive rather than waiting the
        # entire diagnostic window.
        likely_uploads = []

        for request_id, request_info in requests_seen.items():
            url_lower = request_info[
                "url"
            ].lower()

            method_upper = request_info[
                "method"
            ]

            if (
                method_upper in {"POST", "PUT"}
                and "/isapi/security/token" not in url_lower
            ):
                likely_uploads.append(
                    request_id
                )

        if likely_uploads:
            if any(
                request_id in responses_seen
                for request_id in likely_uploads
            ):
                break

        time_module.sleep(0.5)

    events = []

    for request_id, request_info in requests_seen.items():
        response_info = responses_seen.get(
            request_id,
            {},
        )

        events.append({
            "request_id": request_id,
            "url": request_info["url"],
            "method": request_info["method"],
            "status": response_info.get(
                "status",
                0,
            ),
        })

    return events


def summarize_nvr_import_network_events(events):
    """
    Return token requests, likely upload requests, and a safe printable summary.
    Query strings are not printed so token/security material is not exposed.
    """
    from urllib.parse import urlsplit

    token_events = []
    upload_events = []

    for event in events:
        url = str(event.get("url", ""))
        method = str(
            event.get("method", "")
        ).upper()

        parsed = urlsplit(url)
        path_lower = parsed.path.lower()

        safe_event = {
            "path": parsed.path,
            "method": method,
            "status": int(
                event.get("status", 0)
                or 0
            ),
        }

        if (
            path_lower
            == "/isapi/security/token"
        ):
            token_events.append(
                safe_event
            )

        elif (
            method in {"PUT", "POST"}
            and "/isapi/" in path_lower
        ):
            upload_events.append(
                safe_event
            )

    return token_events, upload_events




# =============================================================================
# DIRECT GWEBPLUGINSERVICE CONFIG IMPORT ENGINE
# =============================================================================

def now_ms() -> int:
    return int(time.time() * 1000)


def safe_preview(value: Any, limit: int = 500) -> str:
    text = str(value or "").replace("\r", " ").replace("\n", " ").strip()
    if len(text) > limit:
        return text[:limit] + "..."
    return text


def local_name(tag: str) -> str:
    return str(tag).split("}")[-1]


def xml_find_text(root: ET.Element, wanted_name: str, default: str = "") -> str:
    wanted = wanted_name.lower()
    for element in root.iter():
        if local_name(element.tag).lower() == wanted:
            return (element.text or "").strip()
    return default


def xml_find_bool(root: ET.Element, wanted_name: str, default: bool = False) -> bool:
    value = xml_find_text(root, wanted_name, "")
    if not value:
        return default
    return value.strip().lower() in {"true", "1", "yes", "on", "enabled"}


def xml_find_int(root: ET.Element, wanted_name: str, default: int = 0) -> int:
    value = xml_find_text(root, wanted_name, "")
    try:
        return int(value)
    except Exception:
        return default


def parse_xml(text: str, label: str) -> ET.Element:
    try:
        return ET.fromstring(text)
    except Exception as error:
        raise RuntimeError(
            f"{label} did not return valid XML. "
            f"Response preview: {safe_preview(text)}"
        ) from error


def xml_escape_text(value: str) -> str:
    """
    XML text escaping used for Hikvision encodeString-style fields.

    The important config-password case is normally ASCII. For passwords
    containing XML-sensitive characters this mirrors the usual Hikvision
    string escaping before Base64/AES.
    """
    return (
        str(value)
        .replace("&", "&amp;")
        .replace("<", "&lt;")
        .replace(">", "&gt;")
        .replace('"', "&quot;")
        .replace("'", "&apos;")
    )


def pkcs7_pad(data: bytes, block_size: int = 16) -> bytes:
    pad_len = block_size - (len(data) % block_size)
    return data + bytes([pad_len]) * pad_len


def aes_cbc_pkcs7_encrypt_hex(plaintext: str, key_hex: str, iv_hex: str) -> str:
    if not AES_BACKEND:
        raise RuntimeError(
            "No AES library is installed. Install one of:\n"
            "    py -m pip install pycryptodome\n"
            "or:\n"
            "    py -m pip install cryptography"
        )

    try:
        key = bytes.fromhex(key_hex)
        iv = bytes.fromhex(iv_hex)
    except ValueError as error:
        raise RuntimeError("Derived AES key/IV was not valid hexadecimal.") from error

    if len(key) not in {16, 24, 32}:
        raise RuntimeError(
            f"Unexpected AES key length: {len(key)} bytes. "
            "Expected 16/24/32 bytes."
        )

    if len(iv) != 16:
        raise RuntimeError(
            f"Unexpected AES IV length: {len(iv)} bytes. Expected 16 bytes."
        )

    padded = pkcs7_pad(plaintext.encode("utf-8"), 16)

    if AES_BACKEND == "pycryptodome":
        cipher = CryptoAES.new(key, CryptoAES.MODE_CBC, iv)
        encrypted = cipher.encrypt(padded)
    else:
        encryptor = Cipher(
            algorithms.AES(key),
            modes.CBC(iv),
        ).encryptor()
        encrypted = encryptor.update(padded) + encryptor.finalize()

    return encrypted.hex()


def pbkdf2_sha384_hex(password: str, salt: str) -> str:
    return hashlib.pbkdf2_hmac(
        "sha384",
        str(password).encode("utf-8"),
        str(salt).encode("utf-8"),
        PBKDF2_ITERATIONS,
        dklen=PBKDF2_DKLEN,
    ).hex()


def hikvision_encode_login_password(
    password: str,
    salt: str,
    challenge: str,
    iterations: int,
) -> str:
    """
    Mirror camera JS encodePwd():

        value = PBKDF2-SHA384(password, salt, 10000, 48 bytes).hex()
        value = SHA384(value + challenge).hex()
        for i = 2; i < iterations; i++:
            value = SHA384(value).hex()
    """
    if iterations <= 0:
        raise RuntimeError(
            f"Invalid SessionLogin iteration count returned by camera: {iterations}"
        )

    value = pbkdf2_sha384_hex(password, salt)
    value = hashlib.sha384(
        (value + str(challenge)).encode("utf-8")
    ).hexdigest()

    for _index in range(2, iterations):
        value = hashlib.sha384(value.encode("utf-8")).hexdigest()

    return value


def make_session_random() -> str:
    """
    Mirror the SessionLogin v4 JavaScript:
        md5(Date.now()).substring(0,8)
        -> parse hex to integer
        -> decimal string.substring(0,8)
    """
    first8 = hashlib.md5(str(now_ms()).encode("utf-8")).hexdigest()[:8]

    try:
        decimal = str(int(first8, 16))
    except Exception:
        decimal = str(now_ms())

    return decimal[:8]


class HikvisionSession:
    """
    Browser-style Hikvision SessionLogin v4 client.

    This is used instead of reusing Edge cookies/tokens.
    """

    def __init__(self, ip: str, username: str, password: str):
        self.ip = str(ip).strip()
        self.username = str(username)
        self.password = str(password)
        self.base_url = f"https://{self.ip}"
        self.session = requests.Session()
        self.session.verify = False
        self.session_tag = ""
        self.support_session_tag = False
        self.logged_in = False

    def request(
        self,
        method: str,
        endpoint: str,
        *,
        data: Optional[bytes | str] = None,
        accept: str = "*/*",
        content_type: Optional[str] = None,
        timeout: Optional[Tuple[int, int]] = None,
    ) -> requests.Response:
        headers = {
            "Accept": accept,
            "Connection": "close",
            "X-Requested-With": "XMLHttpRequest",
        }

        if content_type:
            headers["Content-Type"] = content_type

        if self.session_tag:
            headers["SessionTag"] = self.session_tag

        if timeout is None:
            timeout = (
                HTTP_CONNECT_TIMEOUT_SECONDS,
                HTTP_READ_TIMEOUT_SECONDS,
            )

        url = f"{self.base_url}{endpoint}"

        return self.session.request(
            str(method).upper(),
            url,
            data=data,
            headers=headers,
            timeout=timeout,
            verify=False,
        )

    def login(
        self,
        *,
        validate_device_info: bool = True,
    ) -> Dict[str, Any]:
        random_value = make_session_random()

        params = {
            "username": self.username,
            "random": random_value,
        }

        capabilities_url = (
            f"{self.base_url}/ISAPI/Security/sessionLogin/capabilities"
            f"?{urlencode(params)}"
        )

        print("[AUTH] Requesting Hikvision SessionLogin capabilities...")

        response = self.session.get(
            capabilities_url,
            headers={
                "Accept": "application/xml, text/xml, */*",
                "Connection": "close",
                "X-Requested-With": "XMLHttpRequest",
            },
            timeout=(
                HTTP_CONNECT_TIMEOUT_SECONDS,
                HTTP_READ_TIMEOUT_SECONDS,
            ),
            verify=False,
        )

        if response.status_code != 200:
            raise RuntimeError(
                "SessionLogin capabilities request failed: "
                f"HTTP {response.status_code}; "
                f"response={safe_preview(response.text)}"
            )

        root = parse_xml(response.text, "SessionLogin capabilities")

        session_id = xml_find_text(root, "sessionID")
        challenge = xml_find_text(root, "challenge")
        iterations = xml_find_int(root, "iterations", 0)
        salt = xml_find_text(root, "salt")
        session_id_version = xml_find_text(root, "sessionIDVersion")
        valid_long_term = xml_find_text(
            root,
            "isSessionIDValidLongTerm",
            "false",
        )
        self.support_session_tag = xml_find_bool(
            root,
            "isSupportSessionTag",
            False,
        )

        missing = []

        if not session_id:
            missing.append("sessionID")
        if not challenge:
            missing.append("challenge")
        if not salt:
            missing.append("salt")
        if not session_id_version:
            missing.append("sessionIDVersion")
        if iterations <= 0:
            missing.append("iterations")

        if missing:
            raise RuntimeError(
                "SessionLogin capabilities are missing required field(s): "
                + ", ".join(missing)
            )

        encoded_password = hikvision_encode_login_password(
            self.password,
            salt,
            challenge,
            iterations,
        )

        xml_parts = [
            "<SessionLogin>",
            f"<userName>{xml_escape_text(self.username)}</userName>",
            f"<password>{encoded_password}</password>",
            f"<sessionID>{xml_escape_text(session_id)}</sessionID>",
            (
                "<isSessionIDValidLongTerm>"
                f"{xml_escape_text(valid_long_term)}"
                "</isSessionIDValidLongTerm>"
            ),
            (
                "<sessionIDVersion>"
                f"{xml_escape_text(session_id_version)}"
                "</sessionIDVersion>"
            ),
        ]

        if self.support_session_tag:
            xml_parts.append("<isNeedSessionTag>true</isNeedSessionTag>")

        xml_parts.append("</SessionLogin>")

        login_xml = "".join(xml_parts)
        login_endpoint = (
            f"/ISAPI/Security/sessionLogin?timeStamp={now_ms()}"
        )

        print("[AUTH] Submitting Hikvision SessionLogin v4 credentials...")

        login_response = self.request(
            "POST",
            login_endpoint,
            data=login_xml,
            accept="application/xml, text/xml, */*",
            content_type="application/xml; charset=UTF-8",
        )

        if login_response.status_code != 200:
            raise RuntimeError(
                "Hikvision SessionLogin failed: "
                f"HTTP {login_response.status_code}; "
                f"response={safe_preview(login_response.text)}"
            )

        login_root = parse_xml(login_response.text, "SessionLogin response")

        status_code = xml_find_text(login_root, "statusCode")
        status_string = xml_find_text(login_root, "statusString")
        sub_status_code = xml_find_text(login_root, "subStatusCode")

        # SessionLogin success responses can be SessionLogin XML rather than
        # ResponseStatus. Only reject an explicit non-success status.
        if status_code and status_code not in {"1"}:
            raise RuntimeError(
                "Hikvision SessionLogin was rejected: "
                f"statusCode={status_code}; "
                f"statusString={status_string}; "
                f"subStatusCode={sub_status_code}"
            )

        self.session_tag = xml_find_text(login_root, "sessionTag", "")
        self.logged_in = True

        # Administrator sessions are normally validated with DeviceInfo.
        # Newly-created Operator accounts can be in Hikvision's restricted
        # first-login state ("Please change your login password").  In that
        # state SessionLogin itself succeeds but /ISAPI/System/deviceInfo may
        # legitimately return HTTP 401 until the password is changed.  Do not
        # misclassify that restricted-but-authenticated session as bad login.
        model = ""
        firmware = ""
        device_name = ""

        if validate_device_info:
            validation = self.request(
                "GET",
                "/ISAPI/System/deviceInfo",
                accept="application/xml, text/xml, */*",
            )

            if validation.status_code != 200:
                raise RuntimeError(
                    "SessionLogin returned HTTP 200, but authenticated "
                    "/ISAPI/System/deviceInfo validation failed: "
                    f"HTTP {validation.status_code}; "
                    f"response={safe_preview(validation.text)}"
                )

            device_root = parse_xml(validation.text, "DeviceInfo")
            model = xml_find_text(device_root, "model", "")
            firmware = xml_find_text(device_root, "firmwareVersion", "")
            device_name = xml_find_text(device_root, "deviceName", "")
        else:
            print(
                "[AUTH] SessionLogin HTTP 200 accepted without DeviceInfo "
                "validation because this is a limited/new user credential check."
            )

        print("[OK] Hikvision SessionLogin authenticated successfully.")
        print(f"[DEVICE] IP       : {self.ip}")
        if device_name:
            print(f"[DEVICE] Name     : {device_name}")
        if model:
            print(f"[DEVICE] Model    : {model}")
        if firmware:
            print(f"[DEVICE] Firmware : {firmware}")

        return {
            "model": model,
            "firmware": firmware,
            "device_name": device_name,
            "session_tag_supported": self.support_session_tag,
            "session_tag_received": bool(self.session_tag),
            "device_info_validated": bool(validate_device_info),
        }

    def get_security_capabilities(self) -> Dict[str, Any]:
        if not self.logged_in:
            raise RuntimeError("Camera session is not logged in.")

        endpoint = (
            "/ISAPI/Security/capabilities?"
            + urlencode({"username": self.username})
        )

        response = self.request(
            "GET",
            endpoint,
            accept="application/xml, text/xml, */*",
        )

        if response.status_code != 200:
            raise RuntimeError(
                "Security capabilities request failed: "
                f"HTTP {response.status_code}; "
                f"response={safe_preview(response.text)}"
            )

        root = parse_xml(response.text, "Security capabilities")

        key_iterate_num = xml_find_int(root, "keyIterateNum", 0)
        is_irreversible = xml_find_bool(root, "isIrreversible", False)
        salt = xml_find_text(root, "salt", "")

        return {
            "key_iterate_num": key_iterate_num,
            "is_irreversible": is_irreversible,
            "salt": salt,
        }

    def get_plugin_token(self) -> str:
        response = self.request(
            "GET",
            "/ISAPI/Security/token?format=json",
            accept="application/json, text/plain, */*",
        )

        if response.status_code != 200:
            raise RuntimeError(
                "Plugin token request failed: "
                f"HTTP {response.status_code}; "
                f"response={safe_preview(response.text)}"
            )

        try:
            payload = response.json()
        except Exception as error:
            raise RuntimeError(
                "Plugin token endpoint did not return valid JSON. "
                f"Response={safe_preview(response.text)}"
            ) from error

        token = str(
            payload.get("Token", {}).get("value", "")
            or payload.get("value", "")
        ).strip()

        if not token:
            raise RuntimeError(
                "Plugin token response did not contain Token.value."
            )

        return token

    def reboot(self) -> Tuple[bool, str]:
        """
        Match the Dome UI's final PUT /ISAPI/System/reboot.
        """
        try:
            response = self.request(
                "PUT",
                "/ISAPI/System/reboot",
                accept="application/xml, text/xml, */*",
                timeout=(
                    HTTP_CONNECT_TIMEOUT_SECONDS,
                    15,
                ),
            )
        except requests.RequestException as error:
            # The camera can close HTTPS immediately when reboot begins.
            return (
                False,
                "Connection changed while submitting reboot: "
                f"{error}",
            )

        if response.status_code != 200:
            return (
                False,
                f"HTTP {response.status_code}; "
                f"response={safe_preview(response.text)}",
            )

        fields = parse_status_fields(response.text)

        if fields["status_code"] and fields["status_code"] not in {"1"}:
            return (
                False,
                (
                    f"statusCode={fields['status_code']}; "
                    f"statusString={fields['status_string']}; "
                    f"subStatusCode={fields['sub_status_code']}"
                ),
            )

        return True, "HTTP 200 / reboot accepted"


def hikvision_xml_text_encode(value: str) -> str:
    """
    Conservative XML text-node escaping candidate:
      &  <  >
    """
    return (
        str(value)
        .replace("&", "&amp;")
        .replace("<", "&lt;")
        .replace(">", "&gt;")
    )


def derive_hikvision_aes_key_variant(
    admin_password: str,
    capabilities: Dict[str, Any],
    mode: str,
) -> str:
    """
    Build the same AES key family while allowing one controlled compatibility
    alternative for diagnostics.

    mode:
      capability  -> obey isIrreversible from the camera (normal/exact path)
      plain       -> skip PBKDF2 before SHA-384 chain
      pbkdf2      -> force PBKDF2 before SHA-384 chain
    """
    key_iterate_num = int(
        capabilities.get("key_iterate_num", 0) or 0
    )
    salt = str(capabilities.get("salt", "") or "")

    if key_iterate_num <= 0:
        raise RuntimeError(
            "keyIterateNum <= 0; cannot derive Hikvision AES key."
        )

    if mode == "capability":
        use_pbkdf2 = bool(
            capabilities.get("is_irreversible", False)
        )
    elif mode == "plain":
        use_pbkdf2 = False
    elif mode == "pbkdf2":
        use_pbkdf2 = True
    else:
        raise ValueError(f"Unknown AES key mode: {mode}")

    source = str(admin_password)

    if use_pbkdf2:
        if not salt:
            raise RuntimeError(
                "PBKDF2 AES-key mode requested but camera salt is blank."
            )
        source = pbkdf2_sha384_hex(
            admin_password,
            salt,
        )

    if not AES_KEY_DERIVATION_SUFFIX:
        raise RuntimeError(
            "HIKVISION_IMPORT_KDF_SUFFIX is not configured. "
            "Supply your authorized deployment value locally before direct config import."
        )

    value = hashlib.sha384(
        (source + AES_KEY_DERIVATION_SUFFIX).encode("utf-8")
    ).hexdigest()

    for _index in range(1, key_iterate_num):
        value = hashlib.sha384(
            value.encode("utf-8")
        ).hexdigest()

    return value[:32]


def make_secretkey_attempt_candidates(
    admin_password: str,
    config_password: str,
    capabilities: Dict[str, Any],
) -> list[Dict[str, str]]:
    """
    Exact Dome JavaScript algorithm only.

    importDeviceParamByEncrypt:
        encodeString(config_password)
        -> encodeBase64(...)
        -> encodeAES(..., oAuthInfo.szAESKey, iv)

    _strToAESKey:
        obey keyIterateNum / isIrreversible / salt returned by
        /ISAPI/Security/capabilities.

    No unsupported alternate key modes are generated.
    """
    key_hex = derive_hikvision_aes_key_variant(
        admin_password,
        capabilities,
        "capability",
    )

    # For normal ASCII passwords, all sensible XML text encoders are identical.
    # Hikvision's encodeString is used for XML text-node safety. The exact
    # observed utility behavior for password values does not alter ordinary
    # alphanumeric/symbol-safe strings.
    encoded_value = hikvision_xml_text_encode(
        config_password
    )

    plaintext_for_aes = base64.b64encode(
        encoded_value.encode("utf-8")
    ).decode("ascii")

    return [{
        "key_mode": "capability",
        "encoder": "hikvision_xml_text",
        "key_hex": key_hex,
        "aes_plaintext": plaintext_for_aes,
    }]


def build_config_upload_url_from_candidate(
    ip: str,
    candidate: Dict[str, str],
) -> str:
    base_url = (
        f"https://{ip}:{DIRECT_CONFIG_IMPORT_HTTPS_PORT}"
        "/ISAPI/System/configurationData"
    )

    iv_hex = hashlib.md5(
        str(now_ms()).encode("utf-8")
    ).hexdigest()

    secretkey_hex = aes_cbc_pkcs7_encrypt_hex(
        candidate["aes_plaintext"],
        candidate["key_hex"],
        iv_hex,
    )

    return (
        f"{base_url}"
        f"?secretkey={secretkey_hex}"
        f"&security={CONFIG_IMPORT_SECURITY_VERSION}"
        f"&iv={iv_hex}"
    )


def build_plugin_auth(token: str) -> str:
    # Exact Auth Type 4 format recovered from the Dome JavaScript.
    raw = f":::4:{token}".encode("utf-8")
    return base64.b64encode(raw).decode("ascii")


class LocalWebSocket:
    """
    Minimal WebSocket client sufficient for ws://127.0.0.1:34010.

    Client-to-server frames are masked as required by RFC 6455.
    """

    GUID = "258EAFA5-E914-47DA-95CA-C5AB0DC85B11"

    def __init__(
        self,
        host: str,
        port: int,
        origin: str,
        connect_timeout: int = 8,
    ):
        self.host = str(host)
        self.port = int(port)
        self.origin = str(origin)
        self.connect_timeout = int(connect_timeout)
        self.sock: Optional[socket.socket] = None
        self.buffer = bytearray()

    def connect(self) -> None:
        self.sock = socket.create_connection(
            (self.host, self.port),
            timeout=self.connect_timeout,
        )
        self.sock.settimeout(self.connect_timeout)

        sec_key = base64.b64encode(
            os.urandom(16)
        ).decode("ascii")

        request = (
            "GET / HTTP/1.1\r\n"
            f"Host: {self.host}:{self.port}\r\n"
            "Upgrade: websocket\r\n"
            "Connection: Upgrade\r\n"
            f"Sec-WebSocket-Key: {sec_key}\r\n"
            "Sec-WebSocket-Version: 13\r\n"
            f"Origin: {self.origin}\r\n"
            "User-Agent: Mozilla/5.0\r\n"
            "\r\n"
        ).encode("ascii")

        self.sock.sendall(request)

        raw = bytearray()

        deadline = time.monotonic() + self.connect_timeout

        while b"\r\n\r\n" not in raw:
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                raise TimeoutError(
                    "Timed out waiting for local WebSocket handshake."
                )

            self.sock.settimeout(max(0.2, remaining))
            chunk = self.sock.recv(4096)

            if not chunk:
                raise ConnectionError(
                    "Local plugin service closed during WebSocket handshake."
                )

            raw.extend(chunk)

            if len(raw) > 65536:
                raise RuntimeError(
                    "Local WebSocket handshake response was unexpectedly large."
                )

        header_bytes, leftover = raw.split(b"\r\n\r\n", 1)
        self.buffer.extend(leftover)

        header_text = header_bytes.decode("iso-8859-1", errors="replace")
        lines = header_text.split("\r\n")

        if not lines or " 101 " not in f" {lines[0]} ":
            raise RuntimeError(
                "Local plugin service did not accept the WebSocket upgrade. "
                f"Response: {safe_preview(header_text)}"
            )

        response_headers: Dict[str, str] = {}

        for line in lines[1:]:
            if ":" not in line:
                continue
            key, value = line.split(":", 1)
            response_headers[key.strip().lower()] = value.strip()

        expected_accept = base64.b64encode(
            hashlib.sha1(
                (sec_key + self.GUID).encode("ascii")
            ).digest()
        ).decode("ascii")

        actual_accept = response_headers.get(
            "sec-websocket-accept",
            "",
        )

        if actual_accept and actual_accept != expected_accept:
            raise RuntimeError(
                "Local WebSocket Sec-WebSocket-Accept validation failed."
            )

        self.sock.settimeout(LOCAL_WS_REQUEST_TIMEOUT_SECONDS)

    def _recv_exact(self, length: int) -> bytes:
        if length <= 0:
            return b""

        while len(self.buffer) < length:
            if self.sock is None:
                raise ConnectionError("WebSocket is not connected.")

            chunk = self.sock.recv(max(4096, length - len(self.buffer)))

            if not chunk:
                raise ConnectionError("WebSocket connection closed.")

            self.buffer.extend(chunk)

        result = bytes(self.buffer[:length])
        del self.buffer[:length]
        return result

    def _send_frame(self, payload: bytes, opcode: int = 0x1) -> None:
        if self.sock is None:
            raise ConnectionError("WebSocket is not connected.")

        fin_opcode = 0x80 | (opcode & 0x0F)
        payload_len = len(payload)

        mask_key = os.urandom(4)

        if payload_len < 126:
            header = bytes([
                fin_opcode,
                0x80 | payload_len,
            ])
        elif payload_len <= 0xFFFF:
            header = bytes([
                fin_opcode,
                0x80 | 126,
            ]) + struct.pack("!H", payload_len)
        else:
            header = bytes([
                fin_opcode,
                0x80 | 127,
            ]) + struct.pack("!Q", payload_len)

        masked = bytes(
            byte ^ mask_key[index % 4]
            for index, byte in enumerate(payload)
        )

        self.sock.sendall(
            header + mask_key + masked
        )

    def send_text(self, text: str) -> None:
        self._send_frame(
            str(text).encode("utf-8"),
            opcode=0x1,
        )

    def send_json(self, payload: Dict[str, Any]) -> None:
        self.send_text(
            json.dumps(
                payload,
                separators=(",", ":"),
                ensure_ascii=False,
            )
        )

    def _recv_frame(self) -> Tuple[bool, int, bytes]:
        first2 = self._recv_exact(2)

        b1 = first2[0]
        b2 = first2[1]

        fin = bool(b1 & 0x80)
        opcode = b1 & 0x0F
        masked = bool(b2 & 0x80)
        length = b2 & 0x7F

        if length == 126:
            length = struct.unpack(
                "!H",
                self._recv_exact(2),
            )[0]
        elif length == 127:
            length = struct.unpack(
                "!Q",
                self._recv_exact(8),
            )[0]

        mask_key = self._recv_exact(4) if masked else b""
        payload = self._recv_exact(length)

        if masked:
            payload = bytes(
                byte ^ mask_key[index % 4]
                for index, byte in enumerate(payload)
            )

        return fin, opcode, payload

    def recv_text(self, timeout: int = 15) -> str:
        if self.sock is None:
            raise ConnectionError("WebSocket is not connected.")

        deadline = time.monotonic() + float(timeout)
        fragments = bytearray()
        data_opcode: Optional[int] = None

        while True:
            remaining = deadline - time.monotonic()

            if remaining <= 0:
                raise TimeoutError(
                    "Timed out waiting for local plugin WebSocket response."
                )

            self.sock.settimeout(max(0.2, remaining))

            fin, opcode, payload = self._recv_frame()

            if opcode == 0x8:
                raise ConnectionError(
                    "Local plugin service sent WebSocket Close."
                )

            if opcode == 0x9:
                # Ping -> masked Pong from client.
                self._send_frame(payload, opcode=0xA)
                continue

            if opcode == 0xA:
                continue

            if opcode in {0x1, 0x2}:
                data_opcode = opcode
                fragments.extend(payload)

                if fin:
                    break

                continue

            if opcode == 0x0:
                if data_opcode is None:
                    continue

                fragments.extend(payload)

                if fin:
                    break

                continue

            # Ignore unsupported control/extension frames.

        if data_opcode == 0x2:
            return bytes(fragments).decode(
                "utf-8",
                errors="replace",
            )

        return bytes(fragments).decode(
            "utf-8",
            errors="replace",
        )

    def close(self) -> None:
        if self.sock is None:
            return

        try:
            self._send_frame(b"", opcode=0x8)
        except Exception:
            pass

        try:
            self.sock.close()
        except Exception:
            pass

        self.sock = None


class HikvisionPluginClient:
    """
    Direct client for GWebPluginService.exe's local WebSocket RPC.
    """

    def __init__(
        self,
        host: str,
        port: int,
        camera_ip: str,
    ):
        self.host = host
        self.port = int(port)
        self.camera_ip = camera_ip
        self.ws = LocalWebSocket(
            host,
            port,
            origin=f"https://{camera_ip}",
            connect_timeout=LOCAL_WS_CONNECT_TIMEOUT_SECONDS,
        )
        self.service_uuid = ""
        self.service_version = ""

    def connect(self) -> None:
        self.ws.connect()

        connect_sequence = str(uuid.uuid4())

        # Exact initial command from Hikvision WebSocketRequest.init().
        self.ws.send_json({
            "sequence": connect_sequence,
            "cmd": "system.webconnect",
        })

        deadline = (
            time.monotonic()
            + LOCAL_WS_REQUEST_TIMEOUT_SECONDS
        )

        while time.monotonic() < deadline:
            remaining = max(
                1,
                int(deadline - time.monotonic()),
            )

            raw = self.ws.recv_text(timeout=remaining)

            try:
                message = json.loads(raw)
            except Exception:
                continue

            if (
                isinstance(message, dict)
                and not message.get("sequence")
                and not message.get("cmd")
                and message.get("uuid")
            ):
                self.service_uuid = str(
                    message.get("uuid", "")
                )
                self.service_version = str(
                    message.get("version", "")
                )
                break

        if not self.service_uuid:
            raise RuntimeError(
                "Connected to local WebSocket, but GWebPluginService did not "
                "return its webconnect UUID."
            )

        print("[OK] Connected to GWebPluginService local WebSocket.")
        if self.service_version:
            print(
                f"[PLUGIN] Service version: {self.service_version}"
            )

    def request(
        self,
        command: str,
        *,
        timeout_seconds: Optional[int] = None,
        **fields: Any,
    ) -> Dict[str, Any]:
        if not self.service_uuid:
            raise RuntimeError(
                "GWebPluginService webconnect handshake has not completed."
            )

        sequence = str(uuid.uuid4())

        payload: Dict[str, Any] = {
            "cmd": command,
        }
        payload.update(fields)

        payload["sequence"] = sequence
        payload["uuid"] = self.service_uuid
        payload["timestamp"] = str(now_ms())

        self.ws.send_json(payload)

        effective_timeout = int(
            timeout_seconds
            if timeout_seconds is not None
            else LOCAL_WS_REQUEST_TIMEOUT_SECONDS
        )

        deadline = (
            time.monotonic()
            + effective_timeout
        )

        while time.monotonic() < deadline:
            remaining = max(
                1,
                int(deadline - time.monotonic()),
            )

            raw = self.ws.recv_text(timeout=remaining)

            try:
                message = json.loads(raw)
            except Exception:
                continue

            if not isinstance(message, dict):
                continue

            if str(message.get("sequence", "")) != sequence:
                # Ignore unrelated asynchronous messages.
                continue

            error_code_raw = message.get("errorCode", 0)

            try:
                error_code = int(error_code_raw or 0)
            except Exception:
                error_code = -1

            if error_code != 0:
                raise RuntimeError(
                    f"GWebPluginService command {command} failed: "
                    f"errorCode={error_code_raw}; "
                    f"errorModule={message.get('errorModule', '')}"
                )

            return message

        raise TimeoutError(
            f"Timed out waiting for GWebPluginService response to {command}."
        )

    def initialize_for_file_operations(self) -> None:
        """
        Mirror the useful part of JSVideoPlugin onConnectSuccess.

        Hikvision's wrapper calls JS_GetLocalConfig immediately after the local
        service connects.  This is a benign read and makes our fresh WebSocket
        session closer to the browser-created plugin session.
        """
        if not INITIALIZE_PLUGIN_LOCAL_CONFIG:
            return

        try:
            response = self.request("video.getLocalConfig")
            local_config = response.get("localConfig")

            if isinstance(local_config, dict):
                protocol_type = local_config.get("protocolType", "")
                print(
                    "[PLUGIN INIT] video.getLocalConfig succeeded"
                    + (
                        f" (protocolType={protocol_type})."
                        if str(protocol_type) != ""
                        else "."
                    )
                )
            else:
                print("[PLUGIN INIT] video.getLocalConfig succeeded.")

        except Exception as error:
            # The browser treats several visual/plugin initialization calls as
            # non-fatal.  Keep this read diagnostic non-fatal as well; the file
            # authorization step below is the decisive requirement.
            print(
                "[PLUGIN INIT WARNING] video.getLocalConfig did not complete "
                f"cleanly: {error}"
            )

    def browse_file_path(
        self,
        mode: int = 1,
        file_type: str = "",
    ) -> Dict[str, Any]:
        return self.request(
            "video.browseFilePath",
            timeout_seconds=PLUGIN_FILE_BROWSER_RESPONSE_TIMEOUT_SECONDS,
            mode=int(mode),
            fileType=str(file_type),
        )

    def stop_upload(self, ignore_errors: bool = True) -> None:
        try:
            self.request("video.stopAsynUpload")
        except Exception as error:
            if not ignore_errors:
                raise

            print(
                "[PLUGIN WARNING] stopAsynUpload did not return cleanly: "
                f"{error}"
            )

    def start_upload(
        self,
        upload_url: str,
        plugin_auth: str,
        config_path: str,
    ) -> Dict[str, Any]:
        return self.request(
            "video.startAsynUpload",
            uploadUrl=upload_url,
            statusUrl="",
            auth=plugin_auth,
            filepath=config_path,
        )

    def get_upload_error_info(self) -> Dict[str, Any]:
        return self.request(
            "video.getUploadErrorInfo"
        )

    def close(self) -> None:
        self.ws.close()


def parse_status_fields(text: str) -> Dict[str, str]:
    result = {
        "status_code": "",
        "status_string": "",
        "sub_status_code": "",
        "sub_status_string": "",
    }

    if not text:
        return result

    stripped = str(text).strip()

    # Hikvision uploader accepts either JSON or XML.
    if stripped.startswith("{"):
        try:
            payload = json.loads(stripped)
            result["status_code"] = str(
                payload.get("statusCode", "")
            )
            result["status_string"] = str(
                payload.get("statusString", "")
            )
            result["sub_status_code"] = str(
                payload.get("subStatusCode", "")
            )
            result["sub_status_string"] = str(
                payload.get("subStatusString", "")
            )
            return result
        except Exception:
            pass

    try:
        root = ET.fromstring(stripped)
    except Exception:
        return result

    result["status_code"] = xml_find_text(
        root,
        "statusCode",
    )
    result["status_string"] = xml_find_text(
        root,
        "statusString",
    )
    result["sub_status_code"] = xml_find_text(
        root,
        "subStatusCode",
    )
    result["sub_status_string"] = xml_find_text(
        root,
        "subStatusString",
    )

    return result


def poll_upload_until_complete(
    plugin: HikvisionPluginClient,
    *,
    return_secretkey_error: bool = False,
    poll_seconds: Optional[float] = None,
) -> Dict[str, str]:
    """
    Mirror Hikvision startUploadFile():
      - poll JS_GetUploadErrorInfo every 3 seconds
      - an empty errorInfo means still uploading
      - statusCode 1 or 7 is success
      - anything else is failure
    """
    started = time.monotonic()
    next_progress_log = 15

    while True:
        elapsed = int(time.monotonic() - started)

        if elapsed >= UPLOAD_STATUS_TIMEOUT_SECONDS:
            raise TimeoutError(
                "Dome configuration upload did not return a final status "
                f"within {UPLOAD_STATUS_TIMEOUT_SECONDS} seconds."
            )

        sleep_seconds = (
            float(poll_seconds)
            if poll_seconds is not None
            else float(UPLOAD_STATUS_POLL_SECONDS)
        )
        time.sleep(max(0.5, sleep_seconds))

        response = plugin.get_upload_error_info()

        error_info = response.get("errorInfo", "")

        if isinstance(error_info, (dict, list)):
            error_info_text = json.dumps(
                error_info,
                separators=(",", ":"),
            )
        else:
            error_info_text = str(error_info or "")

        if not error_info_text.strip():
            if elapsed >= next_progress_log:
                print(
                    f"[UPLOAD] Still processing: about {elapsed}s elapsed."
                )
                next_progress_log += 15
            continue

        fields = parse_status_fields(error_info_text)

        status_code = fields["status_code"]
        status_string = fields["status_string"]
        sub_status_code = fields["sub_status_code"]

        print(
            "[UPLOAD RESULT] "
            f"statusCode={status_code or 'unknown'}; "
            f"statusString={status_string or 'unknown'}; "
            f"subStatusCode={sub_status_code or 'unknown'}"
        )

        if status_code in {"1", "7"}:
            return fields

        if (
            return_secretkey_error
            and sub_status_code == "cfgFileSecretKeyError"
        ):
            return fields

        raise RuntimeError(
            "Hikvision configuration import failed: "
            f"statusCode={status_code or 'unknown'}; "
            f"statusString={status_string or 'unknown'}; "
            f"subStatusCode={sub_status_code or 'unknown'}; "
            f"response={safe_preview(error_info_text)}"
        )


def authorize_plugin_filepath_direct(
    plugin,
    config_path,
):
    """
    Ask GWebPluginService to authorize the local config file through
    video.browseFilePath, while serializing the global native Windows Open
    dialog so concurrent NVR/Discreet/Dome workers cannot cross-select files.
    """
    result_holder = {}
    error_holder = {}

    def browse_worker():
        try:
            result_holder["response"] = plugin.browse_file_path(
                mode=PLUGIN_FILE_BROWSER_MODE,
                file_type=PLUGIN_FILE_BROWSER_TYPE,
            )
        except BaseException as error:
            error_holder["error"] = error

    with DEVICE_CONFIG_IMPORT_FILE_DIALOG_LOCK:
        worker = threading.Thread(
            target=browse_worker,
            name="GWebPluginService-browseFilePath",
            daemon=True,
        )

        print(
            "[DIRECT CONFIG IMPORT] Requesting video.browseFilePath "
            "to authorize the Excel config file..."
        )

        worker.start()

        selected = select_file_in_windows_open_dialog(
            config_path,
            timeout=PLUGIN_FILE_DIALOG_TIMEOUT_SECONDS,
        )

        if not selected:
            raise RuntimeError(
                "GWebPluginService browseFilePath was requested, but the "
                "native Windows Open dialog could not select the Excel "
                "Device Parameter Config Path."
            )

        worker.join(
            timeout=PLUGIN_FILE_BROWSER_RESPONSE_TIMEOUT_SECONDS
        )

        if worker.is_alive():
            raise TimeoutError(
                "Native file selection completed, but GWebPluginService did "
                "not return the browseFilePath response in time."
            )

    if "error" in error_holder:
        raise RuntimeError(
            "GWebPluginService video.browseFilePath failed: "
            f"{error_holder['error']}"
        )

    response = result_holder.get("response", {})

    if not isinstance(response, dict):
        raise RuntimeError(
            "GWebPluginService browseFilePath returned an unexpected response."
        )

    selected_path = str(
        response.get("filepath", "")
        or ""
    ).strip()

    if not selected_path:
        raise RuntimeError(
            "GWebPluginService browseFilePath completed but returned no filepath."
        )

    expected = os.path.normcase(
        os.path.abspath(str(config_path))
    )
    actual = os.path.normcase(
        os.path.abspath(selected_path)
    )

    if expected != actual:
        raise RuntimeError(
            "GWebPluginService returned a different filepath from the Excel "
            "Device Parameter Config Path. Refusing to upload the wrong file."
        )

    print(
        "[DIRECT CONFIG IMPORT] GWebPluginService authorized the exact "
        "Excel config filepath."
    )

    return selected_path



def direct_config_import_profile(row):
    """Return the confirmed direct-import timings for this Excel source sheet."""
    source_sheet = get_value(
        row,
        "Source Sheet",
    )

    if source_sheet == "Discreet_Settings":
        return {
            "label": "DISCREET",
            "poll_seconds": 5,
        }

    if source_sheet == "Dome_Settings":
        return {
            "label": "DOME",
            "poll_seconds": 3,
        }

    if source_sheet == "NVR_Settings":
        return {
            "label": "NVR",
            "poll_seconds": 3,
        }

    raise RuntimeError(
        f"Unsupported Source Sheet for direct Device Parameter import: "
        f"{source_sheet}"
    )


def import_device_parameter_config_direct(
    row,
    results,
    excel_path,
):
    """
    Direct PASS 0 Device Parameter config import for NVR, Discreet and Dome.

    Confirmed common protocol:
      - browser-style Hikvision SessionLogin v4
      - /ISAPI/Security/capabilities for AES-key derivation
      - /ISAPI/Security/token?format=json
      - plugin auth Base64(":::4:" + token)
      - encrypted upload URL:
          /ISAPI/System/configurationData
            ?secretkey=<AES-CBC-PKCS7 ciphertext>
            &security=1
            &iv=<MD5 timestamp>
      - GWebPluginService local WebSocket on 127.0.0.1:34010
      - video.browseFilePath -> authorized filepath
      - video.startAsynUpload / video.getUploadErrorInfo
      - statusCode 1 or 7 accepted
      - PUT /ISAPI/System/reboot when upload is accepted

    Device admin password, config file path, and config-file password are all
    pulled from the current Excel row. No secrets are printed.
    """
    profile = direct_config_import_profile(row)

    ip = get_value(
        row,
        "Current IP",
        "current_ip",
    )
    username = get_value(
        row,
        "Username",
        "username",
    ) or "admin"
    admin_password = get_value(
        row,
        "Password",
        "password",
    )

    source_sheet = get_value(
        row,
        "Source Sheet",
    )

    raw_config_path = get_value(
        row,
        *NVR_CONFIG_IMPORT_PATH_HEADERS,
    )
    config_password = get_value(
        row,
        *NVR_CONFIG_IMPORT_PASSWORD_HEADERS,
    )

    config_path = resolve_config_import_file_path(
        raw_config_path,
        excel_path,
    )

    label = profile["label"]
    action_name = (
        f"Direct Import {label} Device Parameter Config"
    )

    print("=" * 100)
    print(
        f"[DIRECT CONFIG IMPORT] Device       : {label}"
    )
    print(
        f"[DIRECT CONFIG IMPORT] Source Sheet : {source_sheet}"
    )
    print(
        f"[DIRECT CONFIG IMPORT] Current IP   : {ip}"
    )
    print(
        f"[DIRECT CONFIG IMPORT] Config file  : {config_path}"
    )
    print(
        "[DIRECT CONFIG IMPORT] Admin password/config password: "
        "loaded from Excel (values not printed)"
    )

    if is_blank(ip):
        detail = "Current IP is blank."
        print(f"[FAILED] {detail}")
        add_result(
            results,
            ip,
            action_name,
            NVR_CONFIG_IMPORT_ENDPOINT,
            "",
            "FAILED",
            detail,
        )
        return False

    if is_blank(admin_password):
        detail = "Device Password is blank in Excel."
        print(f"[FAILED] {ip}: {detail}")
        add_result(
            results,
            ip,
            action_name,
            NVR_CONFIG_IMPORT_ENDPOINT,
            "",
            "FAILED",
            detail,
        )
        return False

    if config_path is None:
        detail = "Device Parameter Config Path is blank in Excel."
        print(f"[FAILED] {ip}: {detail}")
        add_result(
            results,
            ip,
            action_name,
            NVR_CONFIG_IMPORT_ENDPOINT,
            "",
            "FAILED",
            detail,
        )
        return False

    if not config_path.is_file():
        detail = (
            f"Configuration file does not exist: {config_path}"
        )
        print(f"[FAILED] {ip}: {detail}")
        add_result(
            results,
            ip,
            action_name,
            NVR_CONFIG_IMPORT_ENDPOINT,
            "",
            "FAILED",
            detail,
        )
        return False

    file_size = config_path.stat().st_size

    if file_size <= 0:
        detail = (
            f"Configuration file is empty: {config_path}"
        )
        print(f"[FAILED] {ip}: {detail}")
        add_result(
            results,
            ip,
            action_name,
            NVR_CONFIG_IMPORT_ENDPOINT,
            "",
            "FAILED",
            detail,
        )
        return False

    if is_blank(config_password):
        detail = (
            "Device Parameter Config Password is blank in Excel. "
            "The confirmed NVR/Discreet/Dome import methods are encrypted."
        )
        print(f"[FAILED] {ip}: {detail}")
        add_result(
            results,
            ip,
            action_name,
            NVR_CONFIG_IMPORT_ENDPOINT,
            "",
            "FAILED",
            detail,
        )
        return False

    print(
        f"[DIRECT CONFIG IMPORT] File size    : {file_size:,} bytes"
    )

    try:
        file_sha256 = hashlib.sha256(
            config_path.read_bytes()
        ).hexdigest()
        print(
            f"[DIRECT CONFIG IMPORT] File SHA-256 : {file_sha256}"
        )
    except Exception as hash_error:
        print(
            f"[DIRECT CONFIG IMPORT WARNING] Could not calculate "
            f"file SHA-256: {hash_error}"
        )

    if DRY_RUN:
        detail = (
            f"Would direct-import {config_path} ({file_size} bytes) using "
            "encrypted Auth Type 4 GWebPluginService workflow."
        )
        print(
            f"[DRY RUN] {ip}: {detail}"
        )
        add_result(
            results,
            ip,
            action_name,
            NVR_CONFIG_IMPORT_ENDPOINT,
            "DRY_RUN",
            "SKIPPED",
            detail,
        )
        return True

    if not AES_BACKEND:
        detail = (
            "Password-protected direct config import needs an AES backend. "
            "Install pycryptodome or cryptography."
        )
        print(f"[FAILED] {ip}: {detail}")
        add_result(
            results,
            ip,
            action_name,
            NVR_CONFIG_IMPORT_ENDPOINT,
            "",
            "FAILED",
            detail,
        )
        return False

    try:
        with socket.create_connection(
            (LOCAL_PLUGIN_HOST, LOCAL_PLUGIN_PORT),
            timeout=3,
        ):
            pass
    except Exception as error:
        detail = (
            f"Cannot connect to GWebPluginService at "
            f"{LOCAL_PLUGIN_HOST}:{LOCAL_PLUGIN_PORT}: {error}"
        )
        print(f"[FAILED] {ip}: {detail}")
        add_result(
            results,
            ip,
            action_name,
            "GWebPluginService",
            "",
            "FAILED",
            detail,
        )
        return False

    plugin = None
    upload_started = False

    try:
        camera = HikvisionSession(
            ip,
            username,
            admin_password,
        )

        camera.login()

        security_cap = (
            camera.get_security_capabilities()
        )

        print(
            f"[DIRECT CONFIG IMPORT] {ip} security capabilities: "
            f"keyIterateNum={security_cap.get('key_iterate_num', 0)}, "
            f"isIrreversible={security_cap.get('is_irreversible', False)}, "
            f"saltPresent={bool(security_cap.get('salt', ''))}"
        )

        exact_candidate = (
            make_secretkey_attempt_candidates(
                admin_password,
                config_password,
                security_cap,
            )[0]
        )

        key_fingerprint = hashlib.sha256(
            exact_candidate["key_hex"].encode("ascii")
        ).hexdigest()[:12]

        print(
            f"[DIRECT CONFIG IMPORT] {ip} AES-key fingerprint: "
            f"{key_fingerprint} (diagnostic only; key not printed)"
        )

        upload_result = None
        last_result = None

        for attempt_number in range(
            1,
            DIRECT_CONFIG_IMPORT_MAX_ATTEMPTS + 1,
        ):
            print(
                f"[DIRECT CONFIG IMPORT] {ip} upload attempt "
                f"{attempt_number}/{DIRECT_CONFIG_IMPORT_MAX_ATTEMPTS}."
            )
            print(
                f"[DIRECT CONFIG IMPORT] {ip} waiting for the single "
                "GWebPluginService async-upload slot..."
            )

            result = None
            attempt_error = None

            # SessionLogin/security/AES work above remains parallel. Only the
            # local GWebPluginService upload transaction is serialized.
            with DIRECT_CONFIG_IMPORT_PLUGIN_UPLOAD_LOCK:
                print(
                    f"[DIRECT CONFIG IMPORT] {ip} acquired the "
                    "GWebPluginService async-upload slot."
                )

                plugin = None
                upload_started = False
                token = ""
                plugin_auth = ""
                upload_url = ""

                try:
                    plugin = HikvisionPluginClient(
                        LOCAL_PLUGIN_HOST,
                        LOCAL_PLUGIN_PORT,
                        ip,
                    )

                    plugin.connect()
                    plugin.initialize_for_file_operations()

                    authorized_config_path = (
                        authorize_plugin_filepath_direct(
                            plugin,
                            config_path,
                        )
                    )

                    print(
                        f"[DIRECT CONFIG IMPORT] {ip} requesting fresh "
                        "Auth Type 4 token."
                    )

                    token = camera.get_plugin_token()
                    plugin_auth = build_plugin_auth(token)

                    upload_url = (
                        build_config_upload_url_from_candidate(
                            ip,
                            exact_candidate,
                        )
                    )

                    # Clear only while this worker owns the global plugin slot.
                    plugin.stop_upload(
                        ignore_errors=True
                    )

                    start_response = plugin.start_upload(
                        upload_url=upload_url,
                        plugin_auth=plugin_auth,
                        config_path=authorized_config_path,
                    )
                    upload_started = True

                    print(
                        f"[DIRECT CONFIG IMPORT] {ip} "
                        "GWebPluginService accepted video.startAsynUpload "
                        f"(uploadID={start_response.get('uploadID', '')})."
                    )

                    result = poll_upload_until_complete(
                        plugin,
                        return_secretkey_error=True,
                        poll_seconds=profile["poll_seconds"],
                    )
                    last_result = result

                except Exception as error:
                    attempt_error = error

                finally:
                    # Cleanup MUST happen before releasing the global plugin
                    # slot. A stopAsynUpload issued after another worker starts
                    # would terminate/corrupt the next worker's upload.
                    if plugin is not None:
                        if upload_started:
                            try:
                                plugin.stop_upload(
                                    ignore_errors=True
                                )
                            except Exception:
                                pass

                        try:
                            plugin.close()
                        except Exception:
                            pass

                    plugin = None
                    upload_started = False
                    token = ""
                    plugin_auth = ""
                    upload_url = ""

                    if DIRECT_CONFIG_IMPORT_PLUGIN_COOLDOWN_SECONDS > 0:
                        print(
                            f"[DIRECT CONFIG IMPORT] {ip} allowing "
                            "GWebPluginService to reset for "
                            f"{DIRECT_CONFIG_IMPORT_PLUGIN_COOLDOWN_SECONDS}s "
                            "before the next device."
                        )
                        time_module.sleep(
                            DIRECT_CONFIG_IMPORT_PLUGIN_COOLDOWN_SECONDS
                        )

                print(
                    f"[DIRECT CONFIG IMPORT] {ip} released the "
                    "GWebPluginService async-upload slot."
                )

            if attempt_error is not None:
                error_text = str(attempt_error)

                # errorCode=6/errorModule=1 was the exact failure seen when
                # local-plugin upload states overlapped. With serialization it
                # should disappear, but retry once with a completely fresh
                # plugin session if the local service is still settling.
                error_text_lower = error_text.lower()

                transient_plugin_error = (
                    (
                        "errorCode=6" in error_text
                        and "errorModule=1" in error_text
                    )
                    or (
                        "errorCode=-1" in error_text
                        and "errorModule=1" in error_text
                    )
                    or (
                        "browsefilepath was requested" in error_text_lower
                    )
                    or (
                        "native windows open dialog" in error_text_lower
                    )
                    or (
                        "could not select the excel device parameter config path"
                        in error_text_lower
                    )
                    or (
                        "did not return the browsefilepath response"
                        in error_text_lower
                    )
                    or (
                        "video.browsefilepath failed" in error_text_lower
                    )
                    or (
                        "browsefilepath completed but returned no filepath"
                        in error_text_lower
                    )
                )

                if (
                    transient_plugin_error
                    and attempt_number
                    < DIRECT_CONFIG_IMPORT_MAX_ATTEMPTS
                ):
                    print(
                        f"[DIRECT CONFIG IMPORT RETRY] {ip} encountered a "
                        f"transient local-plugin/file-picker error: {error_text}"
                    )
                    print(
                        f"[DIRECT CONFIG IMPORT RETRY] {ip} will retry with "
                        "a fresh GWebPluginService WebSocket after the delay."
                    )
                    time_module.sleep(
                        DIRECT_CONFIG_IMPORT_RETRY_DELAY_SECONDS
                    )
                    continue

                raise attempt_error

            if result is None:
                raise RuntimeError(
                    "GWebPluginService upload attempt ended without a final "
                    "upload result."
                )

            if result.get("status_code") in {"1", "7"}:
                upload_result = result
                break

            if (
                result.get("sub_status_code")
                == "cfgFileSecretKeyError"
                and attempt_number
                < DIRECT_CONFIG_IMPORT_MAX_ATTEMPTS
            ):
                print(
                    f"[DIRECT CONFIG IMPORT] {ip} config-file key was "
                    "rejected. Retrying with a fresh plugin session, token "
                    "and IV."
                )
                time_module.sleep(
                    DIRECT_CONFIG_IMPORT_RETRY_DELAY_SECONDS
                )
                continue

            detail = (
                f"Configuration import failed: "
                f"statusCode={result.get('status_code', '')}; "
                f"statusString={result.get('status_string', '')}; "
                f"subStatusCode={result.get('sub_status_code', '')}"
            )
            raise RuntimeError(detail)

        if upload_result is None:
            detail = (
                "Direct configuration import did not produce a successful "
                "statusCode 1/7."
            )

            if last_result:
                detail += (
                    f" Last result: statusCode="
                    f"{last_result.get('status_code', '')}; "
                    f"statusString={last_result.get('status_string', '')}; "
                    f"subStatusCode={last_result.get('sub_status_code', '')}."
                )

            raise RuntimeError(detail)

        print(
            f"[DIRECT CONFIG IMPORT] {ip} upload accepted: "
            f"statusCode={upload_result.get('status_code', '')}; "
            f"statusString={upload_result.get('status_string', '')}; "
            f"subStatusCode={upload_result.get('sub_status_code', '')}."
        )

        # The confirmed browser workflow returns Reboot Required. Submit the
        # same reboot request before the shared PASS 0 wait starts.
        reboot_ok, reboot_detail = camera.reboot()

        if reboot_ok:
            print(
                f"[DIRECT CONFIG IMPORT] {ip} reboot request accepted."
            )
        else:
            print(
                f"[DIRECT CONFIG IMPORT WARNING] {ip} reboot response was "
                f"not fully confirmed: {reboot_detail}"
            )
            print(
                f"[DIRECT CONFIG IMPORT WARNING] {ip} will continue to the "
                "shared reboot/readiness barrier because the camera/NVR can "
                "close HTTPS immediately when reboot begins."
            )

        add_result(
            results,
            ip,
            action_name,
            NVR_CONFIG_IMPORT_ENDPOINT,
            upload_result.get("status_code", ""),
            "OK",
            (
                f"Direct encrypted Auth Type 4 import accepted. "
                f"statusString={upload_result.get('status_string', '')}; "
                f"subStatusCode={upload_result.get('sub_status_code', '')}; "
                f"file={config_path}; size={file_size} bytes. "
                "Reboot submitted; shared PASS 0 wait/readiness follows."
            ),
        )

        return True

    except Exception as error:
        detail = str(error)

        print(
            f"[FAILED] Direct Device Parameter import for {ip}: {detail}"
        )

        add_result(
            results,
            ip,
            action_name,
            NVR_CONFIG_IMPORT_ENDPOINT,
            "",
            "FAILED",
            detail,
        )

        return False

    finally:
        if plugin is not None:
            if upload_started:
                try:
                    plugin.stop_upload(
                        ignore_errors=True
                    )
                except Exception:
                    pass

            try:
                plugin.close()
            except Exception:
                pass


def device_parameter_config_import_requested(row):
    """Return True when this Excel row explicitly requests a config import."""
    enabled_text = get_value(
        row,
        *NVR_CONFIG_IMPORT_ENABLED_HEADERS,
    )
    raw_path = get_value(
        row,
        *NVR_CONFIG_IMPORT_PATH_HEADERS,
    )

    enabled = (
        str(enabled_text).strip().lower()
        in {"yes", "y", "true", "1", "enable", "enabled"}
    )

    return bool(enabled and not is_blank(raw_path))


def camera_maintenance_import_page_ready(driver):
    """Recognize old Discreet and new Dome Device Parameter import pages."""
    try:
        return bool(
            driver.execute_script(
                """
                function visible(element) {
                    if (!element) return false;
                    const style = window.getComputedStyle(element);
                    const rect = element.getBoundingClientRect();
                    return (
                        style.display !== "none" &&
                        style.visibility !== "hidden" &&
                        Number(style.opacity || "1") !== 0 &&
                        rect.width > 0 &&
                        rect.height > 0
                    );
                }

                const pageText = Array.from(
                    document.querySelectorAll("body *")
                )
                .filter(visible)
                .map((element) => String(
                    element.innerText ||
                    element.textContent ||
                    ""
                ).replace(/\\s+/g, " ").trim().toLowerCase())
                .join(" | ");

                const hasImport = (
                    pageText.includes("import config. file") ||
                    pageText.includes("import parameter") ||
                    pageText.includes("import config")
                );

                const hasDeviceParameter = (
                    pageText.includes("device parameters") ||
                    pageText.includes("device parameter")
                );

                return hasImport && hasDeviceParameter;
                """
            )
        )
    except Exception:
        return False



def click_old_hikvision_menu_text_robust(
    driver,
    wanted_text,
    step_name,
    timeout=15,
):
    """
    Robust click for the old Hikvision Angular UI.

    The old Discreet UI sometimes renders the submenu label inside nested
    span/div elements that click_visible_exact_text() cannot reliably target.
    This helper searches both exact and contains-text candidates, climbs to a
    clickable ancestor and dispatches real DOM mouse events.
    """
    deadline = time_module.monotonic() + timeout
    wanted_lower = str(wanted_text).strip().lower()
    last_debug = ""

    while time_module.monotonic() < deadline:
        try:
            result = driver.execute_script(
                """
                const wanted = arguments[0];

                function visible(element) {
                    if (!element) return false;

                    const style = window.getComputedStyle(element);
                    const rect = element.getBoundingClientRect();

                    return (
                        style.display !== "none" &&
                        style.visibility !== "hidden" &&
                        Number(style.opacity || "1") !== 0 &&
                        rect.width > 0 &&
                        rect.height > 0
                    );
                }

                function norm(value) {
                    return String(value || "")
                        .replace(/\\s+/g, " ")
                        .trim()
                        .toLowerCase();
                }

                const candidates = Array.from(
                    document.querySelectorAll(
                        "a,button,li,span,div,p,td,[role='menuitem']," +
                        "[role='tab'],.menu-item,.nav-item"
                    )
                )
                .filter((element) => {
                    if (!visible(element)) return false;

                    const text = norm(
                        element.innerText ||
                        element.textContent
                    );

                    return (
                        text === wanted ||
                        text.startsWith(wanted + " ") ||
                        text.endsWith(" " + wanted)
                    );
                })
                .sort((a, b) => {
                    const ar = a.getBoundingClientRect();
                    const br = b.getBoundingClientRect();

                    return (
                        (ar.width * ar.height) -
                        (br.width * br.height)
                    );
                });

                for (const matched of candidates) {
                    const target = (
                        matched.closest(
                            "a,button,li,[role='menuitem']," +
                            "[role='tab'],.menu-item,.nav-item"
                        ) ||
                        matched
                    );

                    if (!visible(target)) continue;

                    target.scrollIntoView({
                        block: "center",
                        inline: "nearest"
                    });

                    for (const eventName of [
                        "mouseover",
                        "mousedown",
                        "mouseup",
                        "click"
                    ]) {
                        target.dispatchEvent(
                            new MouseEvent(
                                eventName,
                                {
                                    view: window,
                                    bubbles: true,
                                    cancelable: true,
                                    buttons: 1
                                }
                            )
                        );
                    }

                    if (
                        typeof target.click === "function"
                    ) {
                        try {
                            target.click();
                        } catch (error) {
                        }
                    }

                    const rect = target.getBoundingClientRect();

                    return {
                        clicked: true,
                        tag: target.tagName,
                        className: target.className || "",
                        text: norm(
                            target.innerText ||
                            target.textContent
                        ),
                        x: rect.x,
                        y: rect.y
                    };
                }

                return {
                    clicked: false,
                    candidateCount: candidates.length
                };
                """,
                wanted_lower,
            )

            last_debug = str(result)

            if result and result.get("clicked"):
                print(
                    f"[WEB NAV] Robust clicked {step_name}: "
                    f"{wanted_text}; detail={result}"
                )
                time_module.sleep(1.5)
                return True

        except Exception as error:
            last_debug = str(error)

        time_module.sleep(0.5)

    raise RuntimeError(
        f"Could not robust-click {step_name}. Last detail: {last_debug}"
    )



def click_old_ui_menu_item_recursive(
    driver,
    label_text,
    step_name,
    timeout=15,
    max_depth=3,
):
    """
    Search the old Hikvision page and any same-origin iframes for a menu item.

    This is specifically useful for old Discreet firmware where System
    submenus may be rendered inside a nested frame/template after login.
    """
    deadline = time_module.monotonic() + timeout
    wanted = str(label_text).strip().lower()
    wanted_compact = re.sub(r"[^a-z0-9]", "", wanted)
    last_detail = ""

    def try_current_document():
        return driver.execute_script(
            """
            const wanted = arguments[0];
            const wantedCompact = arguments[1];

            function normalize(value) {
                return String(value || "")
                    .replace(/\\s+/g, " ")
                    .trim()
                    .toLowerCase();
            }

            function compact(value) {
                return normalize(value)
                    .replace(/[^a-z0-9]/g, "");
            }

            function visible(element) {
                if (!element) return false;

                const style = window.getComputedStyle(element);
                const rect = element.getBoundingClientRect();

                return (
                    style.display !== "none" &&
                    style.visibility !== "hidden" &&
                    Number(style.opacity || "1") !== 0 &&
                    rect.width > 0 &&
                    rect.height > 0
                );
            }

            const selectors = [
                "a",
                "button",
                "li",
                "div",
                "span",
                "p",
                "label",
                "[onclick]",
                "[ng-click]",
                "[href]",
                "[role='menuitem']",
                "[role='tab']"
            ];

            const candidates = [];

            for (const element of document.querySelectorAll(
                selectors.join(",")
            )) {
                const text = normalize(
                    element.innerText ||
                    element.textContent
                );

                const attrs = compact([
                    element.id,
                    element.className,
                    element.getAttribute("href"),
                    element.getAttribute("onclick"),
                    element.getAttribute("ng-click"),
                    element.getAttribute("data-menu"),
                    element.getAttribute("data-id"),
                    element.getAttribute("name")
                ].join(" "));

                let score = 999;

                if (text === wanted && visible(element)) {
                    score = 0;
                } else if (
                    compact(text) === wantedCompact &&
                    visible(element)
                ) {
                    score = 1;
                } else if (
                    text.includes(wanted) &&
                    visible(element)
                ) {
                    score = 2;
                } else if (
                    attrs.includes(wantedCompact) &&
                    visible(element)
                ) {
                    score = 3;
                } else if (text === wanted) {
                    score = 10;
                } else if (
                    compact(text) === wantedCompact
                ) {
                    score = 11;
                } else if (
                    attrs.includes(wantedCompact)
                ) {
                    score = 12;
                }

                if (score >= 999) continue;

                const target = (
                    element.closest(
                        "a,button,li,[onclick],[ng-click]," +
                        "[role='menuitem'],[role='tab']," +
                        ".menu-item,.nav-item"
                    ) ||
                    element
                );

                const rect = target.getBoundingClientRect();

                // Prefer items in the left navigation.
                let positionalPenalty = 0;
                if (rect.left > 400) positionalPenalty += 100;

                candidates.push({
                    element: target,
                    score: score + positionalPenalty,
                    visible: visible(target),
                    text: text,
                    x: rect.x,
                    y: rect.y,
                    width: rect.width,
                    height: rect.height,
                    tag: target.tagName,
                    className: String(target.className || "")
                });
            }

            candidates.sort((a, b) => (
                a.score - b.score ||
                (a.width * a.height) -
                (b.width * b.height)
            ));

            if (!candidates.length) {
                return {
                    clicked: false,
                    candidateCount: 0
                };
            }

            const selected = candidates[0];
            const target = selected.element;

            if (selected.visible) {
                target.scrollIntoView({
                    block: "center",
                    inline: "nearest"
                });
            }

            for (const eventName of [
                "mouseover",
                "mousedown",
                "mouseup",
                "click"
            ]) {
                target.dispatchEvent(
                    new MouseEvent(
                        eventName,
                        {
                            view: window,
                            bubbles: true,
                            cancelable: true,
                            buttons: 1
                        }
                    )
                );
            }

            try {
                target.click();
            } catch (error) {
            }

            return {
                clicked: true,
                candidateCount: candidates.length,
                score: selected.score,
                visible: selected.visible,
                text: selected.text,
                x: selected.x,
                y: selected.y,
                tag: selected.tag,
                className: selected.className
            };
            """,
            wanted,
            wanted_compact,
        )

    def search_frames(depth=0, path=()):
        driver.switch_to.default_content()

        for index in path:
            frames = driver.find_elements(
                By.CSS_SELECTOR,
                "iframe,frame",
            )
            if index >= len(frames):
                return None
            driver.switch_to.frame(frames[index])

        try:
            result = try_current_document()
            if result and result.get("clicked"):
                return {
                    "result": result,
                    "framePath": path,
                }
        except Exception:
            pass

        if depth >= max_depth:
            return None

        try:
            frames = driver.find_elements(
                By.CSS_SELECTOR,
                "iframe,frame",
            )
            frame_count = len(frames)
        except Exception:
            frame_count = 0

        for index in range(frame_count):
            found = search_frames(
                depth + 1,
                path + (index,),
            )
            if found is not None:
                return found

        return None

    while time_module.monotonic() < deadline:
        try:
            found = search_frames()

            if found is not None:
                last_detail = str(found)

                print(
                    f"[WEB NAV] Recursive old-UI click {step_name}: "
                    f"{found}"
                )

                driver.switch_to.default_content()
                time_module.sleep(1.5)
                return True

            last_detail = "not found in document/iframes"

        except Exception as error:
            last_detail = str(error)

        driver.switch_to.default_content()
        time_module.sleep(0.5)

    driver.switch_to.default_content()

    raise RuntimeError(
        f"Could not recursively click {step_name}. "
        f"Last detail: {last_detail}"
    )


def open_discreet_maintenance_page_robust(driver):
    """
    Reach the old Discreet camera Maintenance page.

    Uses progressively stronger fallbacks:
      1. Normal exact-text click.
      2. Existing old-UI robust menu click (supports hidden/collapsed items).
      3. Recursive document/iframe click.
      4. Attribute-oriented DOM fallback for maintain/maintenance.
    """
    if camera_maintenance_import_page_ready(driver):
        return True

    # ---------------------------------------------------------
    # Expand / open System.
    # ---------------------------------------------------------
    print(
        "[CAMERA CONFIG IMPORT WEB] Discreet: opening System menu."
    )

    system_clicked = False

    try:
        click_visible_exact_text(
            driver,
            ["System"],
            "Discreet System",
            timeout=5,
        )
        system_clicked = True
    except Exception:
        pass

    if not system_clicked:
        try:
            click_old_ui_menu_item_robust(
                driver,
                "System",
                "Discreet System",
            )
            system_clicked = True
        except Exception:
            pass

    if not system_clicked:
        click_old_ui_menu_item_recursive(
            driver,
            "System",
            "Discreet System",
            timeout=10,
        )

    time_module.sleep(1.5)

    if camera_maintenance_import_page_ready(driver):
        return True

    # ---------------------------------------------------------
    # Click Maintenance.
    # ---------------------------------------------------------
    print(
        "[CAMERA CONFIG IMPORT WEB] Discreet: opening Maintenance."
    )

    maintenance_clicked = False
    errors = []

    try:
        click_visible_exact_text(
            driver,
            ["Maintenance"],
            "Discreet Maintenance",
            timeout=4,
        )
        maintenance_clicked = True
    except Exception as error:
        errors.append(
            f"exact-text={error}"
        )

    if not maintenance_clicked:
        try:
            click_old_ui_menu_item_robust(
                driver,
                "Maintenance",
                "Discreet Maintenance",
            )
            maintenance_clicked = True
        except Exception as error:
            errors.append(
                f"old-ui-robust={error}"
            )

    if not maintenance_clicked:
        try:
            click_old_ui_menu_item_recursive(
                driver,
                "Maintenance",
                "Discreet Maintenance",
                timeout=10,
            )
            maintenance_clicked = True
        except Exception as error:
            errors.append(
                f"recursive={error}"
            )

    # Final firmware-specific fallback: old pages sometimes use attribute
    # names containing "maintain" even when no visible Maintenance label is
    # currently rendered.
    if not maintenance_clicked:
        try:
            result = driver.execute_script(
                """
                function visible(element) {
                    if (!element) return false;

                    const style = window.getComputedStyle(element);
                    const rect = element.getBoundingClientRect();

                    return (
                        style.display !== "none" &&
                        style.visibility !== "hidden" &&
                        rect.width > 0 &&
                        rect.height > 0
                    );
                }

                const candidates = Array.from(
                    document.querySelectorAll(
                        "a,button,li,div,span," +
                        "[onclick],[ng-click],[href],[id],[class]"
                    )
                ).filter((element) => {
                    const attrs = String([
                        element.id,
                        element.className,
                        element.getAttribute("href"),
                        element.getAttribute("onclick"),
                        element.getAttribute("ng-click")
                    ].join(" ")).toLowerCase();

                    return (
                        attrs.includes("maintain") ||
                        attrs.includes("maintenance")
                    );
                });

                candidates.sort((a, b) => {
                    const av = visible(a) ? 0 : 1000;
                    const bv = visible(b) ? 0 : 1000;

                    const ar = a.getBoundingClientRect();
                    const br = b.getBoundingClientRect();

                    const ap = ar.left < 400 ? 0 : 500;
                    const bp = br.left < 400 ? 0 : 500;

                    return (
                        (av + ap) -
                        (bv + bp)
                    );
                });

                if (!candidates.length) {
                    return {
                        clicked: false,
                        candidates: 0
                    };
                }

                const element = candidates[0];

                const target = (
                    element.closest(
                        "a,button,li,[onclick],[ng-click]"
                    ) ||
                    element
                );

                target.scrollIntoView({
                    block: "center",
                    inline: "nearest"
                });

                for (const eventName of [
                    "mouseover",
                    "mousedown",
                    "mouseup",
                    "click"
                ]) {
                    target.dispatchEvent(
                        new MouseEvent(
                            eventName,
                            {
                                view: window,
                                bubbles: true,
                                cancelable: true,
                                buttons: 1
                            }
                        )
                    );
                }

                try {
                    target.click();
                } catch (error) {
                }

                return {
                    clicked: true,
                    candidates: candidates.length,
                    id: target.id || "",
                    className: String(target.className || ""),
                    text: String(
                        target.innerText ||
                        target.textContent ||
                        ""
                    ).trim()
                };
                """
            )

            if result and result.get("clicked"):
                maintenance_clicked = True

                print(
                    "[WEB NAV] Discreet Maintenance attribute fallback "
                    f"clicked: {result}"
                )

                time_module.sleep(1.5)

        except Exception as error:
            errors.append(
                f"attribute-fallback={error}"
            )

    if not maintenance_clicked:
        raise RuntimeError(
            "Could not open Discreet Maintenance. Attempts: "
            + " | ".join(errors)
        )

    # ---------------------------------------------------------
    # Confirm the import page itself, not only that a menu click occurred.
    # ---------------------------------------------------------
    try:
        WebDriverWait(
            driver,
            25,
        ).until(
            lambda current_driver: (
                camera_maintenance_import_page_ready(
                    current_driver
                )
            )
        )
    except Exception:
        raise RuntimeError(
            "Discreet Maintenance was clicked, but the Device Parameters "
            "Import Config. File section did not become ready."
        )

    print(
        "[CAMERA CONFIG IMPORT WEB] Discreet Maintenance import page ready."
    )

    return True



def open_camera_maintenance_import_page(driver, row):
    """
    Open the Device Parameters import page for Discreet or Dome cameras.
    """
    ip = get_value(row, "Current IP", "current_ip")
    username = get_value(row, "Username", "username")
    password = get_value(row, "Password", "password")
    source_sheet = get_value(row, "Source Sheet")

    if source_sheet == "Discreet_Settings":
        config_url = f"https://{ip}/doc/page/config.asp"

        print(
            f"[CAMERA CONFIG IMPORT WEB] Opening Discreet Configuration: "
            f"{config_url}"
        )

        driver.get(config_url)
        time_module.sleep(2)

        hikvision_web_login_if_needed(
            driver,
            username,
            password,
        )
        time_module.sleep(2)

        if not camera_maintenance_import_page_ready(driver):
            print(
                "[CAMERA CONFIG IMPORT WEB] Navigating Discreet "
                "System > Maintenance."
            )

            open_discreet_maintenance_page_robust(
                driver
            )

    elif source_sheet == "Dome_Settings":
        base_url = f"https://{ip}/doc/index.html"
        maintenance_url = (
            f"https://{ip}/doc/index.html"
            f"#/operations/maintain/backupReset"
            f"?t={int(time_module.time() * 1000)}"
        )

        print(
            f"[CAMERA CONFIG IMPORT WEB] Opening Dome application: "
            f"{base_url}"
        )

        driver.get(base_url)
        time_module.sleep(2)

        hikvision_web_login_if_needed(
            driver,
            username,
            password,
        )
        time_module.sleep(2)

        print(
            f"[CAMERA CONFIG IMPORT WEB] Opening Dome Backup and Restore: "
            f"{maintenance_url}"
        )

        driver.get(maintenance_url)
        time_module.sleep(3)

        if not camera_maintenance_import_page_ready(driver):
            try:
                click_visible_exact_text(
                    driver,
                    ["Maintenance and Security"],
                    "Dome Maintenance and Security",
                    timeout=12,
                )
                time_module.sleep(1)
            except Exception:
                pass

            try:
                click_visible_exact_text(
                    driver,
                    ["Maintenance"],
                    "Dome Maintenance",
                    timeout=12,
                )
                time_module.sleep(1)
            except Exception:
                pass

            try:
                click_visible_exact_text(
                    driver,
                    ["Backup and Restore"],
                    "Dome Backup and Restore",
                    timeout=12,
                )
                time_module.sleep(2)
            except Exception:
                pass

    else:
        raise RuntimeError(
            f"Unsupported camera sheet for config import: {source_sheet}"
        )

    WebDriverWait(
        driver,
        25,
    ).until(
        lambda current_driver: (
            camera_maintenance_import_page_ready(
                current_driver
            )
        )
    )

    print(
        f"[CAMERA CONFIG IMPORT WEB] Import page ready for {ip}."
    )

    return True


def find_camera_device_parameter_browse_button(driver):
    """
    Old Discreet UI: normal Browse button.
    New Dome UI: folder-icon button beside the Device Parameter path field.
    """
    driver.switch_to.default_content()

    browse_buttons = driver.execute_script(
        """
        function visible(e) {
            if (!e) return false;
            const s = getComputedStyle(e);
            const r = e.getBoundingClientRect();
            return (
                !e.disabled &&
                s.display !== "none" &&
                s.visibility !== "hidden" &&
                Number(s.opacity || "1") !== 0 &&
                r.width > 0 &&
                r.height > 0
            );
        }
        function norm(v) {
            return String(v || "").replace(/\\s+/g, " ").trim().toLowerCase();
        }

        return Array.from(
            document.querySelectorAll(
                "button,input[type='button'],input[type='submit'],a,[role='button']"
            )
        ).filter((e) => (
            visible(e) &&
            norm(e.innerText || e.value || e.textContent) === "browse"
        ));
        """
    )

    if browse_buttons:
        return browse_buttons[0]

    button = driver.execute_script(
        """
        function visible(e) {
            if (!e) return false;
            const s = getComputedStyle(e);
            const r = e.getBoundingClientRect();
            return (
                !e.disabled &&
                s.display !== "none" &&
                s.visibility !== "hidden" &&
                Number(s.opacity || "1") !== 0 &&
                r.width > 0 &&
                r.height > 0
            );
        }
        function norm(v) {
            return String(v || "").replace(/\\s+/g, " ").trim().toLowerCase();
        }

        const labels = Array.from(
            document.querySelectorAll("label,div,span,p,td")
        ).filter((e) => {
            if (!visible(e)) return false;
            const t = norm(e.innerText || e.textContent);
            return t === "device parameter" || t === "device parameters";
        });

        const buttons = Array.from(
            document.querySelectorAll(
                "button,a,[role='button'],input[type='button']"
            )
        ).filter(visible);

        let best = null;
        let bestScore = Infinity;

        for (const label of labels) {
            const lr = label.getBoundingClientRect();

            for (const candidate of buttons) {
                const br = candidate.getBoundingClientRect();
                const bt = norm(
                    candidate.innerText ||
                    candidate.value ||
                    candidate.textContent
                );

                if (bt === "import" || bt === "export") continue;
                if (br.left < lr.left) continue;

                const vertical = Math.abs(
                    (br.top + br.height / 2) -
                    (lr.top + lr.height / 2)
                );

                if (vertical > 80) continue;

                const score =
                    vertical * 10 +
                    Math.max(0, br.left - lr.right);

                if (score < bestScore) {
                    best = candidate;
                    bestScore = score;
                }
            }
        }

        return best;
        """
    )

    if button is None:
        raise RuntimeError(
            "Device Parameter Browse/folder control could not be found."
        )

    return button


def select_camera_device_parameter_config_file(
    driver,
    config_path,
):
    """
    Robustly select one camera Device Parameters backup file.

    Important concurrency fix:
        The old code located the Browse button BEFORE acquiring the global
        Windows file-dialog lock. With several Dome/Discreet workers running
        together, a browser could wait behind other devices while holding an
        old/stale Browse WebElement.

        v54 acquires DEVICE_CONFIG_IMPORT_FILE_DIALOG_LOCK FIRST, then locates
        a fresh Browse/folder control immediately before clicking it.

    Recovery order per attempt:
        1. Existing input[type=file].
        2. Fresh Browse/folder control under the global native-dialog lock.
        3. Native Windows Open dialog, with a longer 25-second detection time.
        4. Dynamically-created input[type=file].
        5. Retry the file-selection operation up to 3 times.

    If all selection attempts fail, CameraConfigTransientImportError is raised
    so the OUTER camera import workflow can restart in a fresh Edge session.
    """
    absolute_path = str(
        Path(config_path).resolve()
    )

    config_file = Path(
        absolute_path
    )

    if not config_file.is_file():
        raise RuntimeError(
            "Camera configuration file does not exist: "
            f"{absolute_path}"
        )

    last_error = ""

    for selection_attempt in range(
        1,
        CAMERA_CONFIG_FILE_SELECTION_MAX_ATTEMPTS + 1,
    ):
        print(
            "[CAMERA CONFIG FILE SELECT] "
            f"Attempt {selection_attempt}/"
            f"{CAMERA_CONFIG_FILE_SELECTION_MAX_ATTEMPTS}: "
            f"{absolute_path}"
        )

        # -------------------------------------------------------------
        # METHOD 1: existing input[type=file]
        # -------------------------------------------------------------
        try:
            found = find_file_input_recursive(
                driver
            )
        except Exception:
            found = None

        if found is not None:
            file_input, frame_path = found

            try:
                switch_to_frame_path(
                    driver,
                    frame_path,
                )

                file_input.send_keys(
                    absolute_path
                )

                time_module.sleep(
                    1.0
                )

                print(
                    "[CAMERA CONFIG IMPORT WEB] "
                    "Config file assigned through "
                    "existing input[type=file]."
                )

                return True

            except Exception as error:
                last_error = (
                    "Existing input[type=file] failed: "
                    f"{error}"
                )

                print(
                    "[CAMERA CONFIG FILE SELECT WARNING] "
                    f"{last_error}"
                )

            finally:
                try:
                    driver.switch_to.default_content()
                except Exception:
                    pass

        # -------------------------------------------------------------
        # METHOD 2: Native Windows Open dialog.
        #
        # CRITICAL: Find a FRESH Browse button only AFTER this thread owns the
        # global file-dialog lock.
        # -------------------------------------------------------------
        native_selected = False

        try:
            with DEVICE_CONFIG_IMPORT_FILE_DIALOG_LOCK:
                try:
                    driver.switch_to.default_content()
                except Exception:
                    pass

                browse_button = (
                    find_camera_device_parameter_browse_button(
                        driver
                    )
                )

                try:
                    driver.execute_script(
                        """
                        arguments[0].scrollIntoView({
                            block: "center",
                            inline: "center"
                        });
                        """,
                        browse_button,
                    )
                except Exception:
                    pass

                time_module.sleep(
                    0.2
                )

                browse_clicked = False

                try:
                    browse_button.click()
                    browse_clicked = True
                except Exception:
                    pass

                if not browse_clicked:
                    try:
                        driver.execute_script(
                            "arguments[0].click();",
                            browse_button,
                        )
                        browse_clicked = True
                    except Exception:
                        pass

                if not browse_clicked:
                    try:
                        coordinates = driver.execute_script(
                            """
                            const element = arguments[0];
                            const rect =
                                element.getBoundingClientRect();

                            return {
                                x:
                                    rect.left +
                                    rect.width / 2,
                                y:
                                    rect.top +
                                    rect.height / 2
                            };
                            """,
                            browse_button,
                        )

                        click_x = float(
                            coordinates["x"]
                        )
                        click_y = float(
                            coordinates["y"]
                        )

                        driver.execute_cdp_cmd(
                            "Input.dispatchMouseEvent",
                            {
                                "type": "mouseMoved",
                                "x": click_x,
                                "y": click_y,
                            },
                        )

                        driver.execute_cdp_cmd(
                            "Input.dispatchMouseEvent",
                            {
                                "type": "mousePressed",
                                "x": click_x,
                                "y": click_y,
                                "button": "left",
                                "clickCount": 1,
                            },
                        )

                        driver.execute_cdp_cmd(
                            "Input.dispatchMouseEvent",
                            {
                                "type": "mouseReleased",
                                "x": click_x,
                                "y": click_y,
                                "button": "left",
                                "clickCount": 1,
                            },
                        )

                        browse_clicked = True

                    except Exception as error:
                        last_error = (
                            "Unable to click fresh camera "
                            f"Browse control: {error}"
                        )

                if not browse_clicked:
                    raise CameraConfigTransientImportError(
                        last_error
                        or "Unable to click Device Parameter Browse/folder control."
                    )

                print(
                    "[CAMERA CONFIG IMPORT WEB] "
                    "Fresh Device Parameter Browse/folder "
                    "control clicked while holding native "
                    "file-dialog lock."
                )

                # Windows 11 / Edge can occasionally create the native dialog
                # slowly when multiple browsers are open.
                time_module.sleep(
                    0.6
                )

                try:
                    native_selected = (
                        select_file_in_windows_open_dialog(
                            absolute_path,
                            timeout=(
                                CAMERA_CONFIG_NATIVE_FILE_DIALOG_TIMEOUT_SECONDS
                            ),
                        )
                    )
                except Exception as error:
                    last_error = (
                        "Native Windows file selection failed: "
                        f"{error}"
                    )

                    print(
                        "[CAMERA CONFIG FILE SELECT WARNING] "
                        f"{last_error}"
                    )

                    native_selected = False

                if native_selected:
                    print(
                        "[CAMERA CONFIG IMPORT WEB] "
                        "Camera configuration file selected "
                        "through Windows Open dialog."
                    )

                    # Give Angular/Vue time to consume the native file-picker
                    # result before the Import-button waiter starts.
                    time_module.sleep(
                        2.0
                    )

                    return True

        except CameraConfigTransientImportError:
            raise

        except Exception as error:
            last_error = (
                "Camera native file-picker stage failed: "
                f"{error}"
            )

            print(
                "[CAMERA CONFIG FILE SELECT WARNING] "
                f"{last_error}"
            )

        # -------------------------------------------------------------
        # METHOD 3: Some Hikvision pages create input[type=file] only AFTER
        # Browse was clicked. Search repeatedly for a few seconds.
        # -------------------------------------------------------------
        dynamic_deadline = (
            time_module.monotonic()
            + 4.0
        )

        while (
            time_module.monotonic()
            < dynamic_deadline
        ):
            try:
                found = (
                    find_file_input_recursive(
                        driver
                    )
                )
            except Exception:
                found = None

            if found is not None:
                file_input, frame_path = found

                try:
                    switch_to_frame_path(
                        driver,
                        frame_path,
                    )

                    file_input.send_keys(
                        absolute_path
                    )

                    time_module.sleep(
                        1.0
                    )

                    print(
                        "[CAMERA CONFIG IMPORT WEB] "
                        "Camera configuration file assigned "
                        "through dynamically-created "
                        "input[type=file]."
                    )

                    return True

                except Exception as error:
                    last_error = (
                        "Dynamic input[type=file] failed: "
                        f"{error}"
                    )

                finally:
                    try:
                        driver.switch_to.default_content()
                    except Exception:
                        pass

            time_module.sleep(
                0.4
            )

        if (
            selection_attempt
            < CAMERA_CONFIG_FILE_SELECTION_MAX_ATTEMPTS
        ):
            print(
                "[CAMERA CONFIG FILE SELECT RETRY] "
                f"Selection attempt {selection_attempt} "
                "did not assign the file. Waiting "
                f"{CAMERA_CONFIG_FILE_SELECTION_RETRY_DELAY_SECONDS}s "
                "and trying a fresh Browse/file-picker cycle."
            )

            time_module.sleep(
                CAMERA_CONFIG_FILE_SELECTION_RETRY_DELAY_SECONDS
            )

    raise CameraConfigTransientImportError(
        "Camera file picker opened, but the configuration file could not "
        "be assigned after "
        f"{CAMERA_CONFIG_FILE_SELECTION_MAX_ATTEMPTS} selection attempt(s). "
        f"Last detail: {last_error}"
    )

def find_camera_device_parameter_import_button(
    driver,
    timeout=None,
):
    """
    Wait for and return the Device Parameter Import button.

    Important for the new Dome UI:
      - before a file is selected, Import exists but is disabled;
      - after the native Windows file dialog closes, Vue/Element UI may need
        several seconds to copy the selected file into its component state;
      - only then does the Import button become enabled.

    The old implementation searched only for an already-enabled button once,
    which caused a false failure immediately after file selection.
    """
    if timeout is None:
        timeout = CAMERA_CONFIG_IMPORT_BUTTON_TIMEOUT_SECONDS

    deadline = time_module.monotonic() + timeout
    last_state = None

    while time_module.monotonic() < deadline:
        try:
            state = driver.execute_script(
                """
                function visible(element) {
                    if (!element) return false;

                    const style = window.getComputedStyle(element);
                    const rect = element.getBoundingClientRect();

                    return (
                        style.display !== "none" &&
                        style.visibility !== "hidden" &&
                        Number(style.opacity || "1") !== 0 &&
                        rect.width > 0 &&
                        rect.height > 0
                    );
                }

                function norm(value) {
                    return String(value || "")
                        .replace(/\\s+/g, " ")
                        .trim()
                        .toLowerCase();
                }

                function disabled(element) {
                    if (!element) return true;

                    const ariaDisabled = norm(
                        element.getAttribute("aria-disabled")
                    );

                    const className = norm(
                        element.className
                    );

                    return (
                        Boolean(element.disabled) ||
                        ariaDisabled === "true" ||
                        className.includes("is-disabled") ||
                        className.includes("disabled")
                    );
                }

                const importButtons = Array.from(
                    document.querySelectorAll(
                        "button,input[type='button'],input[type='submit']," +
                        "a,[role='button']"
                    )
                ).filter((element) => {
                    if (!visible(element)) return false;

                    const text = norm(
                        element.innerText ||
                        element.value ||
                        element.textContent
                    );

                    return (
                        text === "import" ||
                        text.startsWith("import ")
                    );
                });

                const labels = Array.from(
                    document.querySelectorAll(
                        "label,div,span,p,td"
                    )
                ).filter((element) => {
                    if (!visible(element)) return false;

                    const text = norm(
                        element.innerText ||
                        element.textContent
                    );

                    return (
                        text === "device parameter" ||
                        text === "device parameters"
                    );
                });

                let best = null;
                let bestScore = Infinity;

                // Prefer the Import control on the same horizontal row as
                // Device Parameter(s). This avoids choosing firmware-upgrade
                // or IP-camera Import buttons on old pages.
                for (const button of importButtons) {
                    const br = button.getBoundingClientRect();

                    for (const label of labels) {
                        const lr = label.getBoundingClientRect();

                        const vertical = Math.abs(
                            (br.top + br.height / 2) -
                            (lr.top + lr.height / 2)
                        );

                        if (vertical > 90) {
                            continue;
                        }

                        const horizontalPenalty = Math.abs(
                            br.left - lr.right
                        );

                        const score = (
                            vertical * 20 +
                            horizontalPenalty
                        );

                        if (score < bestScore) {
                            best = button;
                            bestScore = score;
                        }
                    }
                }

                // If only one Import exists, it is safe to use.
                if (!best && importButtons.length === 1) {
                    best = importButtons[0];
                }

                if (!best) {
                    return {
                        found: false,
                        totalImports: importButtons.length,
                        labelCount: labels.length
                    };
                }

                const rect = best.getBoundingClientRect();

                return {
                    found: true,
                    enabled: !disabled(best),
                    element: best,
                    text: norm(
                        best.innerText ||
                        best.value ||
                        best.textContent
                    ),
                    tag: best.tagName,
                    className: best.className || "",
                    disabledProperty: Boolean(best.disabled),
                    ariaDisabled: best.getAttribute("aria-disabled") || "",
                    x: rect.x,
                    y: rect.y,
                    width: rect.width,
                    height: rect.height,
                    totalImports: importButtons.length,
                    labelCount: labels.length
                };
                """
            )

            last_state = state

            if state and state.get("found"):
                if state.get("enabled"):
                    print(
                        "[CAMERA CONFIG IMPORT WEB] Device Parameter "
                        f"Import button enabled: {state}"
                    )
                    return state.get("element")

                print(
                    "[CAMERA CONFIG IMPORT WEB] Device Parameter Import "
                    "button is present but still disabled; waiting for the "
                    f"file selection to register. detail={state}"
                )

        except Exception as error:
            last_state = str(error)

        time_module.sleep(0.75)

    raise RuntimeError(
        "Device Parameter Import button did not become enabled within "
        f"{timeout} seconds after file selection. Last state: {last_state}"
    )


def click_camera_device_parameter_import_button(
    driver,
    timeout=None,
):
    """
    Wait until the correct Device Parameter Import button is enabled and click
    it using Selenium, JavaScript and DOM-event fallbacks.
    """
    button = find_camera_device_parameter_import_button(
        driver,
        timeout=timeout,
    )

    driver.execute_script(
        """
        arguments[0].scrollIntoView({
            block: "center",
            inline: "nearest"
        });
        """,
        button,
    )

    time_module.sleep(0.25)

    clicked = False

    try:
        ActionChains(driver).move_to_element(
            button
        ).pause(0.15).click(button).perform()
        clicked = True
    except Exception:
        pass

    if not clicked:
        try:
            button.click()
            clicked = True
        except Exception:
            pass

    if not clicked:
        driver.execute_script(
            """
            const element = arguments[0];

            for (const eventName of [
                "mouseover",
                "mousedown",
                "mouseup",
                "click"
            ]) {
                element.dispatchEvent(
                    new MouseEvent(
                        eventName,
                        {
                            view: window,
                            bubbles: true,
                            cancelable: true,
                            buttons: 1
                        }
                    )
                );
            }

            if (typeof element.click === "function") {
                element.click();
            }
            """,
            button,
        )
        clicked = True

    if not clicked:
        raise RuntimeError(
            "Device Parameter Import button was enabled but could not "
            "be clicked."
        )

    return True




def find_camera_import_password_dialog(driver):
    """
    Find a visible camera configuration-import password dialog.

    Supported camera UI wording includes:
      - Dome:     "Import Device Parameter" + "Password"
      - Other UI: "File Decryption" + "Password"

    The smallest visible container containing a usable input is returned so
    the page's normal Reserved Email/password fields cannot be selected by
    mistake.
    """
    try:
        return driver.execute_script(
            """
            function visible(element) {
                if (!element) return false;

                const style = window.getComputedStyle(element);
                const rect = element.getBoundingClientRect();

                return (
                    style.display !== "none" &&
                    style.visibility !== "hidden" &&
                    Number(style.opacity || "1") !== 0 &&
                    rect.width > 0 &&
                    rect.height > 0
                );
            }

            function normalize(value) {
                return String(value || "")
                    .replace(/\\s+/g, " ")
                    .trim()
                    .toLowerCase();
            }

            const containers = Array.from(
                document.querySelectorAll(
                    ".el-drawer,.el-dialog,.el-message-box,.el-popover," +
                    ".modal,.modal-dialog,.aui_dialog,.ui-dialog," +
                    ".layui-layer,.dialog,.window,body > div,div"
                )
            ).filter(visible);

            const matches = containers.filter((container) => {
                const text = normalize(
                    container.innerText || container.textContent
                );

                const wordingMatches = (
                    (
                        text.includes("import device parameter") &&
                        text.includes("password")
                    ) ||
                    (
                        text.includes("file decryption") &&
                        text.includes("password")
                    )
                );

                if (!wordingMatches) return false;

                return Array.from(
                    container.querySelectorAll(
                        "input:not([type='button']):not([type='submit']):" +
                        "not([type='hidden'])"
                    )
                ).some((input) => visible(input) && !input.disabled);
            });

            if (!matches.length) return null;

            matches.sort((a, b) => {
                const ar = a.getBoundingClientRect();
                const br = b.getBoundingClientRect();
                return (ar.width * ar.height) - (br.width * br.height);
            });

            return matches[0];
            """
        )
    except Exception:
        return None


def find_camera_import_reboot_confirmation_dialog(
    driver,
    max_depth=5,
):
    """
    Find the FINAL camera import restart/reboot confirmation.

    Confirmed project wording:

    Discreet / old UI:
        Device will reboot automatically after configuring file parameters.
        Continue?

    Dome / new UI:
        Device will restart automatically after parameters are configured.
        Continue?

    Old Discreet firmware may place the popup inside an iframe/frame or use
    legacy table/div markup without a modern dialog class. This function
    therefore searches the top document and nested frames recursively.

    If a matching popup is found inside a frame, Selenium is intentionally
    left inside that frame so click_camera_import_dialog_ok() can click its
    actual OK button. If nothing is found, the driver is restored to the top
    document.
    """

    driver.switch_to.default_content()

    find_in_current_document_script = r"""
        function visible(element) {
            if (!element || !element.isConnected) {
                return false;
            }

            const style = window.getComputedStyle(element);
            const rect = element.getBoundingClientRect();

            return (
                style.display !== "none" &&
                style.visibility !== "hidden" &&
                Number(style.opacity || "1") !== 0 &&
                rect.width > 0 &&
                rect.height > 0
            );
        }

        function normalize(value) {
            return String(value || "")
                .replace(/\s+/g, " ")
                .trim()
                .toLowerCase();
        }

        function isFinalImportConfirmationText(value) {
            const text = normalize(value);

            const hasRestartWord = (
                text.includes("reboot automatically") ||
                text.includes("restart automatically") ||
                (
                    text.includes("reboot") &&
                    text.includes("automatically")
                ) ||
                (
                    text.includes("restart") &&
                    text.includes("automatically")
                )
            );

            const hasContinue = text.includes("continue");

            const hasParameterWording = (
                text.includes("configuring file parameters") ||
                text.includes("configuration file parameters") ||
                text.includes("parameters are configured") ||
                text.includes("parameter") ||
                text.includes("configuring file") ||
                text.includes("configuration file")
            );

            return (
                hasRestartWord &&
                hasContinue &&
                hasParameterWording
            );
        }

        function exactOK(element) {
            if (!visible(element)) {
                return false;
            }

            const text = normalize(
                element.innerText ||
                element.value ||
                element.textContent
            );

            return text === "ok";
        }

        function hasUsableOK(container) {
            if (!container) {
                return false;
            }

            const controls = Array.from(
                container.querySelectorAll(
                    "button,input[type='button'],input[type='submit']," +
                    "a,[role='button'],[ng-click],.btn,.el-button," +
                    ".button,.button-wrapper"
                )
            );

            return controls.some(exactOK);
        }

        const preferredSelectors = [
            ".el-message-box",
            ".el-dialog",
            ".el-drawer",
            ".modal",
            ".modal-dialog",
            ".aui_dialog",
            ".ui-dialog",
            ".layui-layer",
            ".dialog",
            ".window",
            ".popup",
            ".popbox",
            ".msgbox",
            ".message-box",
            "[role='dialog']"
        ];

        let matches = [];

        for (const selector of preferredSelectors) {
            for (
                const container of document.querySelectorAll(selector)
            ) {
                if (!visible(container)) {
                    continue;
                }

                const text = normalize(
                    container.innerText ||
                    container.textContent
                );

                if (isFinalImportConfirmationText(text)) {
                    matches.push(container);
                }
            }
        }

        // Old Hikvision pages may use TABLE/TR/TD or generic DIV wrappers.
        if (!matches.length) {
            const legacyContainers = Array.from(
                document.querySelectorAll(
                    "table,tbody,tr,td,body > div,div,section,article"
                )
            );

            for (const container of legacyContainers) {
                if (!visible(container)) {
                    continue;
                }

                const text = normalize(
                    container.innerText ||
                    container.textContent
                );

                if (isFinalImportConfirmationText(text)) {
                    matches.push(container);
                }
            }
        }

        // Strong legacy fallback:
        // start from each exact visible OK and walk up its ancestors until
        // the reboot/restart confirmation text is found.
        if (!matches.length) {
            const okControls = Array.from(
                document.querySelectorAll(
                    "button,input[type='button'],input[type='submit']," +
                    "a,[role='button'],[ng-click],.btn,.el-button," +
                    ".button,.button-wrapper"
                )
            ).filter(exactOK);

            for (const okControl of okControls) {
                let ancestor = okControl;

                for (let depth = 0; depth < 14; depth++) {
                    if (!ancestor) {
                        break;
                    }

                    if (visible(ancestor)) {
                        const text = normalize(
                            ancestor.innerText ||
                            ancestor.textContent
                        );

                        if (isFinalImportConfirmationText(text)) {
                            matches.push(ancestor);
                            break;
                        }
                    }

                    ancestor = ancestor.parentElement;
                }
            }
        }

        if (!matches.length) {
            return null;
        }

        matches = matches.filter(
            (element, index, array) =>
                array.indexOf(element) === index
        );

        matches.sort((first, second) => {
            const firstOK = hasUsableOK(first) ? 0 : 1;
            const secondOK = hasUsableOK(second) ? 0 : 1;

            if (firstOK !== secondOK) {
                return firstOK - secondOK;
            }

            const a = first.getBoundingClientRect();
            const b = second.getBoundingClientRect();

            return (
                (a.width * a.height) -
                (b.width * b.height)
            );
        });

        return matches[0];
    """

    def search(depth):
        try:
            dialog = driver.execute_script(
                find_in_current_document_script
            )
        except Exception:
            dialog = None

        if dialog is not None:
            return dialog

        if depth >= max_depth:
            return None

        try:
            frames = driver.find_elements(
                By.CSS_SELECTOR,
                "iframe,frame",
            )
        except Exception:
            frames = []

        for frame_index in range(len(frames)):
            try:
                current_frames = driver.find_elements(
                    By.CSS_SELECTOR,
                    "iframe,frame",
                )

                if frame_index >= len(current_frames):
                    continue

                driver.switch_to.frame(
                    current_frames[frame_index]
                )
            except Exception:
                continue

            found = search(depth + 1)

            if found is not None:
                # Leave Selenium inside the document containing the popup.
                return found

            try:
                driver.switch_to.parent_frame()
            except Exception:
                driver.switch_to.default_content()

        return None

    found = search(0)

    if found is None:
        try:
            driver.switch_to.default_content()
        except Exception:
            pass

    return found


def accept_camera_import_native_confirmation_if_present(
    driver,
):
    """
    Accept a browser-native alert only if its text clearly matches the
    configuration-import restart/reboot confirmation.
    """
    try:
        alert = driver.switch_to.alert
        alert_text = str(alert.text or "")
    except Exception:
        return False, ""

    normalized = (
        alert_text
        .replace("\r", " ")
        .replace("\n", " ")
        .strip()
        .lower()
    )

    matches = (
        (
            "reboot" in normalized or
            "restart" in normalized
        )
        and
        "automatically" in normalized
        and
        "continue" in normalized
        and
        (
            "parameter" in normalized or
            "configuring file" in normalized or
            "configuration file" in normalized
        )
    )

    if not matches:
        return False, alert_text

    try:
        alert.accept()
    except Exception:
        return False, alert_text

    return True, alert_text


def click_camera_import_dialog_ok(
    driver,
    dialog,
    label,
):
    """
    Click the exact visible OK belonging to a camera import dialog.

    IMPORTANT DOME FIX:
        The Dome import-password drawer does NOT necessarily disappear after
        its OK is accepted. Instead, the next confirmation appears on top:

            Device will restart automatically after parameters are configured.
            Continue?

        Therefore the password step is considered successful when EITHER:
          1. the original password dialog closes, OR
          2. the final restart/reboot confirmation appears, OR
          3. the camera enters Importing/processing state.

        This prevents the script from incorrectly retrying the password OK
        while the final restart confirmation is already covering it.

    Click order:
      1. trusted Chromium/CDP mouse click,
      2. Selenium click,
      3. DOM mouse-event fallback.
    """

    label_lower = str(label or "").strip().lower()
    is_password_step = (
        "password" in label_lower
        or "import device parameter" in label_lower
        or "file decryption" in label_lower
    )

    def dialog_is_still_visible():
        try:
            return bool(
                driver.execute_script(
                    """
                    const element = arguments[0];

                    if (!element || !element.isConnected) {
                        return false;
                    }

                    const style = window.getComputedStyle(element);
                    const rect = element.getBoundingClientRect();

                    return (
                        style.display !== "none" &&
                        style.visibility !== "hidden" &&
                        Number(style.opacity || "1") !== 0 &&
                        rect.width > 0 &&
                        rect.height > 0
                    );
                    """,
                    dialog,
                )
            )
        except Exception:
            return False

    def stage_advanced_after_ok():
        """
        Return (completed, reason).

        For Dome password submission, the original right-side drawer can stay
        visible while a NEW centre restart-confirmation modal appears. That is
        a successful password OK, not a click failure.
        """
        if not dialog_is_still_visible():
            return True, "original dialog closed"

        if is_password_step:
            try:
                next_dialog = find_camera_import_reboot_confirmation_dialog(
                    driver
                )
            except Exception:
                next_dialog = None

            if next_dialog is not None:
                return (
                    True,
                    "final restart/reboot confirmation appeared",
                )

        try:
            if camera_config_importing_state_visible(driver):
                return True, "camera entered Importing/processing state"
        except Exception:
            pass

        return False, "dialog still waiting"

    def wait_for_stage_advance(wait_seconds=4.0):
        deadline = time_module.monotonic() + float(wait_seconds)
        last_reason = ""

        while time_module.monotonic() < deadline:
            completed, reason = stage_advanced_after_ok()
            last_reason = reason

            if completed:
                return True, reason

            time_module.sleep(0.15)

        return False, last_reason

    def locate_ok_control():
        """
        Return:
            (WebElement or None, debug_detail)
        """
        result = driver.execute_script(
            """
            const originalDialog = arguments[0];

            function visible(element) {
                if (!element || !element.isConnected) {
                    return false;
                }

                const style = window.getComputedStyle(element);
                const rect = element.getBoundingClientRect();

                return (
                    !element.disabled &&
                    style.display !== "none" &&
                    style.visibility !== "hidden" &&
                    Number(style.opacity || "1") !== 0 &&
                    rect.width > 0 &&
                    rect.height > 0
                );
            }

            function normalize(value) {
                return String(value || "")
                    .replace(/\\s+/g, " ")
                    .trim()
                    .toLowerCase();
            }

            function exactOK(element) {
                if (!visible(element)) return false;

                const text = normalize(
                    element.innerText ||
                    element.value ||
                    element.textContent
                );

                return text === "ok";
            }

            function actionableAncestor(element) {
                if (!element) return null;

                return (
                    element.closest(
                        "button,input[type='button'],input[type='submit']," +
                        "a,[role='button'],[ng-click],.btn,.el-button"
                    ) ||
                    element
                );
            }

            function collectInside(container) {
                if (!container) return [];

                const raw = Array.from(
                    container.querySelectorAll(
                        "button,input[type='button'],input[type='submit']," +
                        "a,[role='button'],[ng-click],.btn,.el-button," +
                        ".button,.button-wrapper"
                    )
                ).filter(exactOK);

                const unique = [];

                for (const candidate of raw) {
                    const target = actionableAncestor(candidate);

                    if (
                        target &&
                        visible(target) &&
                        !unique.includes(target)
                    ) {
                        unique.push(target);
                    }
                }

                return unique;
            }

            const dialogRect = (
                originalDialog &&
                originalDialog.isConnected
            )
                ? originalDialog.getBoundingClientRect()
                : {
                    left: window.innerWidth / 2 - 200,
                    top: window.innerHeight / 2 - 150,
                    width: 400,
                    height: 300
                };

            function score(element) {
                const rect = element.getBoundingClientRect();
                const cx = rect.left + rect.width / 2;
                const cy = rect.top + rect.height / 2;
                const dx = cx - (
                    dialogRect.left + dialogRect.width / 2
                );
                const dy = cy - (
                    dialogRect.top + dialogRect.height / 2
                );

                let value = Math.sqrt(dx * dx + dy * dy);

                if (
                    element.tagName === "BUTTON" ||
                    element.tagName === "INPUT"
                ) {
                    value -= 150;
                }

                if (
                    String(element.className || "")
                        .toLowerCase()
                        .includes("primary")
                ) {
                    value -= 60;
                }

                return value;
            }

            // 1. Search the detected popup itself.
            let candidates = collectInside(originalDialog);

            if (candidates.length) {
                candidates.sort((a, b) => score(a) - score(b));

                return {
                    element: candidates[0],
                    source: "dialog",
                    count: candidates.length
                };
            }

            // 2. Walk upward. Old firmware may keep text and buttons in
            // sibling containers under a common parent.
            let ancestor = originalDialog;

            for (let depth = 1; depth <= 12; depth++) {
                if (!ancestor) break;

                ancestor = ancestor.parentElement;

                if (!ancestor) break;

                candidates = collectInside(ancestor);

                if (candidates.length) {
                    candidates.sort((a, b) => score(a) - score(b));

                    return {
                        element: candidates[0],
                        source: "ancestor",
                        depth: depth,
                        count: candidates.length,
                        ancestorTag: ancestor.tagName,
                        ancestorClass: String(
                            ancestor.className || ""
                        )
                    };
                }
            }

            // 3. Global fallback: nearest exact visible OK to the popup.
            candidates = Array.from(
                document.querySelectorAll(
                    "button,input[type='button'],input[type='submit']," +
                    "a,[role='button'],[ng-click],.btn,.el-button," +
                    ".button,.button-wrapper"
                )
            )
            .filter(exactOK)
            .map(actionableAncestor)
            .filter((element, index, array) => (
                element &&
                visible(element) &&
                array.indexOf(element) === index
            ));

            if (!candidates.length) {
                return {
                    element: null,
                    source: "none",
                    count: 0
                };
            }

            candidates.sort((a, b) => score(a) - score(b));

            const chosen = candidates[0];
            const rect = chosen.getBoundingClientRect();

            return {
                element: chosen,
                source: "global-nearest",
                count: candidates.length,
                tag: chosen.tagName,
                className: String(chosen.className || ""),
                text: normalize(
                    chosen.innerText ||
                    chosen.value ||
                    chosen.textContent
                ),
                x: rect.x,
                y: rect.y,
                width: rect.width,
                height: rect.height
            };
            """,
            dialog,
        )

        if not result:
            return None, {
                "source": "script-returned-none"
            }

        return (
            result.get("element"),
            {
                key: value
                for key, value in result.items()
                if key != "element"
            },
        )

    def trusted_cdp_click(element):
        """
        Click the real element occupying the target point.
        """
        target_info = driver.execute_script(
            """
            const requested = arguments[0];

            requested.scrollIntoView({
                block: "center",
                inline: "center"
            });

            const requestedRect =
                requested.getBoundingClientRect();

            const x =
                requestedRect.left +
                requestedRect.width / 2;

            const y =
                requestedRect.top +
                requestedRect.height / 2;

            let actual =
                document.elementFromPoint(x, y);

            if (actual) {
                actual = (
                    actual.closest(
                        "button,input[type='button'],input[type='submit']," +
                        "a,[role='button'],[ng-click],.btn,.el-button"
                    ) ||
                    actual
                );
            }

            const rect = (
                actual || requested
            ).getBoundingClientRect();

            return {
                x: rect.left + rect.width / 2,
                y: rect.top + rect.height / 2,
                requestedTag: requested.tagName,
                requestedClass:
                    String(requested.className || ""),
                actualTag:
                    actual ? actual.tagName : "",
                actualClass:
                    actual ? String(actual.className || "") : "",
                actualText:
                    actual
                        ? String(
                            actual.innerText ||
                            actual.value ||
                            actual.textContent ||
                            ""
                        ).replace(/\\s+/g, " ").trim()
                        : ""
            };
            """,
            element,
        )

        x = float(target_info["x"])
        y = float(target_info["y"])

        driver.execute_cdp_cmd(
            "Input.dispatchMouseEvent",
            {
                "type": "mouseMoved",
                "x": x,
                "y": y,
            },
        )

        driver.execute_cdp_cmd(
            "Input.dispatchMouseEvent",
            {
                "type": "mousePressed",
                "x": x,
                "y": y,
                "button": "left",
                "buttons": 1,
                "clickCount": 1,
            },
        )

        driver.execute_cdp_cmd(
            "Input.dispatchMouseEvent",
            {
                "type": "mouseReleased",
                "x": x,
                "y": y,
                "button": "left",
                "buttons": 0,
                "clickCount": 1,
            },
        )

        return target_info

    last_detail = None

    for attempt in range(1, 5):
        # Before trying another click, check whether the previous click already
        # advanced the workflow to the next Dome confirmation.
        completed, reason = stage_advanced_after_ok()

        if completed:
            print(
                f"[CAMERA CONFIG IMPORT WEB] {label} already accepted: "
                f"{reason}."
            )
            return True

        ok_button, detail = locate_ok_control()
        last_detail = detail

        print(
            f"[CAMERA CONFIG IMPORT WEB] {label} OK search "
            f"attempt {attempt}/4: {detail}"
        )

        if ok_button is None:
            time_module.sleep(0.4)
            continue

        # ---------------------------------------------------------
        # Method 1: trusted browser-level click.
        # ---------------------------------------------------------
        try:
            click_detail = trusted_cdp_click(ok_button)

            print(
                f"[CAMERA CONFIG IMPORT WEB] {label} OK trusted click: "
                f"{click_detail}"
            )

            advanced, advance_reason = wait_for_stage_advance(4.0)

            if advanced:
                print(
                    f"[CAMERA CONFIG IMPORT WEB] {label} accepted after "
                    f"trusted OK click: {advance_reason}."
                )
                return True

        except Exception as error:
            print(
                f"[CAMERA CONFIG IMPORT WEB DEBUG] {label} trusted "
                f"CDP OK click failed: {error}"
            )

        # ---------------------------------------------------------
        # If Dome has already opened the next restart confirmation, DO NOT
        # attempt another click on the password drawer underneath it.
        # ---------------------------------------------------------
        completed, reason = stage_advanced_after_ok()

        if completed:
            print(
                f"[CAMERA CONFIG IMPORT WEB] {label} accepted: {reason}."
            )
            return True

        # ---------------------------------------------------------
        # Method 2: Selenium click.
        # ---------------------------------------------------------
        try:
            ok_button, detail = locate_ok_control()

            if ok_button is not None:
                ok_button.click()

                print(
                    f"[CAMERA CONFIG IMPORT WEB] {label} OK clicked "
                    "using Selenium."
                )

                advanced, advance_reason = wait_for_stage_advance(3.0)

                if advanced:
                    print(
                        f"[CAMERA CONFIG IMPORT WEB] {label} accepted after "
                        f"Selenium OK click: {advance_reason}."
                    )
                    return True

        except Exception as error:
            print(
                f"[CAMERA CONFIG IMPORT WEB DEBUG] {label} Selenium "
                f"OK click failed: {error}"
            )

        completed, reason = stage_advanced_after_ok()

        if completed:
            print(
                f"[CAMERA CONFIG IMPORT WEB] {label} accepted: {reason}."
            )
            return True

        # ---------------------------------------------------------
        # Method 3: direct DOM click/event fallback.
        # ---------------------------------------------------------
        try:
            ok_button, detail = locate_ok_control()

            if ok_button is not None:
                driver.execute_script(
                    """
                    const element = arguments[0];

                    element.focus();

                    for (const eventName of [
                        "pointerdown",
                        "mousedown",
                        "pointerup",
                        "mouseup",
                        "click"
                    ]) {
                        const EventClass = (
                            eventName.startsWith("pointer")
                                ? PointerEvent
                                : MouseEvent
                        );

                        element.dispatchEvent(
                            new EventClass(
                                eventName,
                                {
                                    view: window,
                                    bubbles: true,
                                    cancelable: true,
                                    button: 0,
                                    buttons:
                                        (
                                            eventName === "pointerdown" ||
                                            eventName === "mousedown"
                                        )
                                            ? 1
                                            : 0
                                }
                            )
                        );
                    }

                    if (typeof element.click === "function") {
                        element.click();
                    }
                    """,
                    ok_button,
                )

                print(
                    f"[CAMERA CONFIG IMPORT WEB] {label} OK clicked "
                    "using DOM events."
                )

                advanced, advance_reason = wait_for_stage_advance(3.0)

                if advanced:
                    print(
                        f"[CAMERA CONFIG IMPORT WEB] {label} accepted after "
                        f"DOM OK click: {advance_reason}."
                    )
                    return True

        except Exception as error:
            print(
                f"[CAMERA CONFIG IMPORT WEB DEBUG] {label} DOM "
                f"OK click failed: {error}"
            )

        print(
            f"[CAMERA CONFIG IMPORT WEB WARNING] {label} has not yet "
            "advanced to the next import stage; retrying with a fresh "
            "popup/button lookup."
        )

        time_module.sleep(0.5)

    raise RuntimeError(
        f"{label} dialog opened, but its OK button could not be "
        f"successfully accepted after four attempts. "
        f"Last lookup detail: {last_detail}"
    )

def submit_camera_import_password_dialog(
    driver,
    import_password,
    ip,
):
    """
    Fill Dome/other camera configuration-file import password dialog.
    """
    dialog = find_camera_import_password_dialog(driver)

    if dialog is None:
        return False

    if is_blank(import_password):
        raise RuntimeError(
            "Camera displayed an import-password prompt, but "
            "'Device Parameter Config Password' is blank in Excel."
        )

    inputs = dialog.find_elements(
        By.CSS_SELECTOR,
        "input:not([type='button']):not([type='submit']):not([type='hidden'])",
    )

    visible_inputs = []

    for element in inputs:
        try:
            if element.is_displayed() and element.is_enabled():
                visible_inputs.append(element)
        except Exception:
            pass

    if not visible_inputs:
        raise RuntimeError(
            "Camera import-password dialog opened, but its input field "
            "could not be found."
        )

    password_input = None

    for element in visible_inputs:
        try:
            if str(element.get_attribute("type") or "").lower() == "password":
                password_input = element
                break
        except Exception:
            pass

    if password_input is None:
        password_input = visible_inputs[0]

    try:
        password_input.clear()
    except Exception:
        pass

    password_input.send_keys(str(import_password))

    print(
        f"[CAMERA CONFIG IMPORT WEB] {ip} import password entered from Excel."
    )

    click_camera_import_dialog_ok(
        driver,
        dialog,
        "Import Device Parameter password",
    )

    return True


def camera_config_importing_state_visible(driver):
    """Detect a visible camera-side Importing/processing state."""
    try:
        return bool(
            driver.execute_script(
                """
                function visible(element) {
                    if (!element) return false;
                    const style = getComputedStyle(element);
                    const rect = element.getBoundingClientRect();
                    return (
                        style.display !== "none" &&
                        style.visibility !== "hidden" &&
                        Number(style.opacity || "1") !== 0 &&
                        rect.width > 0 &&
                        rect.height > 0
                    );
                }

                return Array.from(
                    document.querySelectorAll("body *")
                ).some((element) => {
                    if (!visible(element)) return false;

                    const text = String(
                        element.innerText || element.textContent || ""
                    ).replace(/\\s+/g, " ").trim().toLowerCase();

                    return (
                        text === "importing..." ||
                        text === "importing" ||
                        text.includes("importing...")
                    );
                });
                """
            )
        )
    except Exception:
        return False


def finalize_camera_device_parameter_import_submission(
    driver,
    source_sheet,
    import_password,
    ip,
    timeout=45,
):
    """
    Finish every camera-specific dialog that appears AFTER clicking Import.

    Confirmed project flow:

    Dome:
        Import
        -> Import Device Parameter password
        -> OK
        -> "Device will restart automatically after parameters are configured.
            Continue?"
        -> OK
        -> processing/restart

    Discreet:
        Import
        -> "Device will reboot automatically after configuring file parameters.
            Continue?"
        -> OK
        -> processing/reboot

    PASS 0 does NOT count the camera as submitted until the final restart /
    reboot confirmation OK has been clicked successfully.
    """
    if source_sheet == "Discreet_Settings":
        timeout = max(float(timeout), 75.0)

    deadline = time_module.monotonic() + timeout
    discreet_wait_log_at = time_module.monotonic() + 5.0

    password_submitted = False
    final_confirmation_submitted = False
    last_action_at = None
    last_detail = ""

    expected_password = source_sheet == "Dome_Settings"

    # Both camera types shown in this project require a final restart/reboot
    # confirmation. The wording differs, but the semantic step is the same.
    expected_final_confirmation = source_sheet in {
        "Dome_Settings",
        "Discreet_Settings",
    }

    while time_module.monotonic() < deadline:
        # -------------------------------------------------------------
        # Import Failed always overrides any success signal.
        # -------------------------------------------------------------
        failure_text = (
            detect_and_dismiss_device_config_import_failure(
                driver,
                label=(
                    f"{ip} camera "
                    "config import"
                ),
            )
        )

        if failure_text:
            raise DeviceParameterImportFailedError(
                failure_text
            )

        # -------------------------------------------------------------
        # Dome import password.
        # -------------------------------------------------------------
        try:
            password_dialog = find_camera_import_password_dialog(driver)
        except Exception:
            password_dialog = None

        if (
            password_dialog is not None
            and not password_submitted
        ):
            submit_camera_import_password_dialog(
                driver,
                import_password,
                ip,
            )

            password_submitted = True
            last_action_at = time_module.monotonic()
            last_detail = "import password submitted"

            print(
                f"[CAMERA CONFIG IMPORT WEB] {ip} password step completed; "
                "waiting for final restart/reboot confirmation."
            )

            time_module.sleep(0.5)
            continue

        # -------------------------------------------------------------
        # Final restart/reboot confirmation for BOTH Dome and Discreet.
        #
        # Handle browser-native alerts first, then search the top document
        # and nested iframe/frame content for an HTML confirmation.
        # -------------------------------------------------------------
        native_accepted = False

        if not final_confirmation_submitted:
            try:
                (
                    native_accepted,
                    _native_text,
                ) = accept_camera_import_native_confirmation_if_present(
                    driver
                )
            except Exception:
                native_accepted = False

        if native_accepted:
            final_confirmation_submitted = True
            last_action_at = time_module.monotonic()
            last_detail = (
                "final restart/reboot confirmation submitted "
                "through browser-native alert"
            )

            print(
                f"[CAMERA CONFIG IMPORT WEB] {ip} FINAL import "
                "confirmation accepted through browser-native alert."
            )

            time_module.sleep(0.5)
            continue

        try:
            final_dialog = find_camera_import_reboot_confirmation_dialog(
                driver
            )
        except Exception:
            final_dialog = None

        if (
            final_dialog is not None
            and not final_confirmation_submitted
        ):
            confirmation_label = (
                "Dome restart confirmation"
                if source_sheet == "Dome_Settings"
                else "Discreet reboot confirmation"
            )

            if source_sheet == "Discreet_Settings":
                print(
                    f"[CAMERA CONFIG IMPORT WEB] {ip} old-UI Discreet "
                    "reboot confirmation detected; clicking exact OK."
                )

            click_camera_import_dialog_ok(
                driver,
                final_dialog,
                confirmation_label,
            )

            final_confirmation_submitted = True
            last_action_at = time_module.monotonic()
            last_detail = (
                "final restart/reboot confirmation submitted"
            )

            print(
                f"[CAMERA CONFIG IMPORT WEB] {ip} FINAL import "
                "confirmation OK completed."
            )

            # The recursive finder may have entered an iframe. Restore the
            # main page only after the real popup OK has been clicked.
            try:
                driver.switch_to.default_content()
            except Exception:
                pass

            time_module.sleep(0.5)
            continue

        if (
            source_sheet == "Discreet_Settings"
            and
            not final_confirmation_submitted
            and
            time_module.monotonic() >= discreet_wait_log_at
        ):
            print(
                f"[CAMERA CONFIG IMPORT WEB] {ip} still waiting for "
                "Discreet reboot confirmation; checking top document "
                "and nested iframe/frame content."
            )

            discreet_wait_log_at = (
                time_module.monotonic() + 10.0
            )

        # -------------------------------------------------------------
        # Explicit Importing state is ideal proof.
        # -------------------------------------------------------------
        try:
            if camera_config_importing_state_visible(driver):
                required_done = (
                    (not expected_password or password_submitted)
                    and
                    (
                        not expected_final_confirmation
                        or final_confirmation_submitted
                    )
                )

                if required_done:
                    print(
                        f"[CAMERA CONFIG IMPORT WEB] {ip} entered "
                        "Importing... state after final confirmation."
                    )

                    return True, (
                        "Importing state detected after final camera "
                        "restart/reboot confirmation."
                    )
        except Exception:
            pass

        # -------------------------------------------------------------
        # Device may restart immediately after final OK. If Selenium loses
        # the session only AFTER all required actions, that is successful
        # submission.
        # -------------------------------------------------------------
        try:
            _ = driver.current_url
        except Exception as error:
            required_done = (
                (not expected_password or password_submitted)
                and
                (
                    not expected_final_confirmation
                    or final_confirmation_submitted
                )
            )

            if required_done:
                print(
                    f"[CAMERA CONFIG IMPORT WEB] {ip} browser/session "
                    "changed after FINAL import confirmation; treating this "
                    "as restart/reboot start."
                )

                return True, (
                    "Browser/session changed after final camera import "
                    f"confirmation: {error}"
                )

        required_done = (
            (not expected_password or password_submitted)
            and
            (
                not expected_final_confirmation
                or final_confirmation_submitted
            )
        )

        # Do not return merely because the password was accepted. For Dome,
        # the final restart confirmation can appear slightly later.
        if required_done and last_action_at is not None:
            if (
                time_module.monotonic() - last_action_at
            ) >= max(
                1.5,
                DEVICE_CONFIG_IMPORT_IMMEDIATE_FAILURE_WATCH_SECONDS,
            ):
                print(
                    f"[CAMERA CONFIG IMPORT WEB] {ip} all required "
                    f"camera import dialogs completed ({last_detail})."
                )

                return True, last_detail

        time_module.sleep(0.25)

    missing = []

    if expected_password and not password_submitted:
        missing.append(
            "Dome Import Device Parameter password/OK"
        )

    if (
        expected_final_confirmation
        and not final_confirmation_submitted
    ):
        if source_sheet == "Dome_Settings":
            missing.append(
                "Dome restart confirmation/OK"
            )
        else:
            missing.append(
                "Discreet reboot confirmation/OK"
            )

    if missing:
        raise RuntimeError(
            "Camera Import button was clicked, but the required final "
            "import dialog was not completed: "
            + ", ".join(missing)
        )

    raise RuntimeError(
        "Camera Import button was clicked, but the script could not confirm "
        "that the final import submission was accepted."
    )

def import_camera_device_parameter_config(
    row,
    results,
    excel_path,
):
    """
    Import one Discreet/Dome configuration file.

    Explicit Hikvision "Import Failed" responses are automatically retried by
    re-opening Maintenance and repeating file selection/import from the start.
    """
    ip = get_value(
        row,
        "Current IP",
        "current_ip",
    )

    source_sheet = get_value(
        row,
        "Source Sheet",
    )

    import_password = get_value(
        row,
        *NVR_CONFIG_IMPORT_PASSWORD_HEADERS,
    )

    raw_path = get_value(
        row,
        *NVR_CONFIG_IMPORT_PATH_HEADERS,
    )

    if (
        not ENABLE_CAMERA_DEVICE_PARAMETER_CONFIG_IMPORT
    ):
        return True

    if not device_parameter_config_import_requested(
        row
    ):
        return True

    config_path = (
        resolve_config_import_file_path(
            raw_path,
            excel_path,
        )
    )

    if (
        config_path is None
        or not config_path.is_file()
    ):
        detail = (
            "Camera configuration file "
            f"does not exist: {config_path}"
        )

        print(
            f"[FAILED] {ip}: {detail}"
        )

        add_result(
            results,
            ip,
            "Import Camera Device Parameter Config",
            "WEB_UI",
            "",
            "FAILED",
            detail,
        )

        return False

    print("=" * 100)
    print(
        f"[CAMERA CONFIG IMPORT] Camera IP    : "
        f"{ip}"
    )
    print(
        f"[CAMERA CONFIG IMPORT] Source Sheet : "
        f"{source_sheet}"
    )
    print(
        f"[CAMERA CONFIG IMPORT] Config file  : "
        f"{config_path}"
    )
    print(
        "[CAMERA CONFIG IMPORT] Import password: "
        + (
            "configured in Excel"
            if not is_blank(
                import_password
            )
            else "blank"
        )
    )
    print(
        "[CAMERA CONFIG IMPORT] Import Failed "
        f"auto-retry: max "
        f"{DEVICE_CONFIG_IMPORT_MAX_ATTEMPTS} "
        "attempt(s)."
    )

    if DRY_RUN:
        add_result(
            results,
            ip,
            "Import Camera Device Parameter Config",
            "WEB_UI",
            "DRY_RUN",
            "SKIPPED",
            f"Would import {config_path}.",
        )

        return True

    last_error = ""
    explicit_failure_count = 0
    transient_failure_count = 0

    for attempt in range(
        1,
        DEVICE_CONFIG_IMPORT_MAX_ATTEMPTS + 1,
    ):
        driver = None

        try:
            print(
                f"[CAMERA CONFIG IMPORT ATTEMPT] "
                f"{ip} attempt {attempt}/"
                f"{DEVICE_CONFIG_IMPORT_MAX_ATTEMPTS}"
            )

            driver = (
                create_nvr_config_import_edge_driver()
            )

            open_camera_maintenance_import_page(
                driver,
                row,
            )

            select_camera_device_parameter_config_file(
                driver,
                config_path,
            )

            click_camera_device_parameter_import_button(
                driver,
                timeout=(
                    CAMERA_CONFIG_IMPORT_BUTTON_TIMEOUT_SECONDS
                ),
            )

            print(
                f"[CAMERA CONFIG IMPORT WEB] "
                f"Import clicked for {ip}."
            )

            time_module.sleep(
                0.5
            )

            (
                submitted,
                submit_detail,
            ) = (
                finalize_camera_device_parameter_import_submission(
                    driver,
                    source_sheet,
                    import_password,
                    ip,
                    timeout=45,
                )
            )

            if not submitted:
                raise RuntimeError(
                    "Camera import final "
                    "confirmation did not complete."
                )

            # Final check before the browser enters the shared PASS 0 registry.
            failure_text = (
                detect_and_dismiss_device_config_import_failure(
                    driver,
                    label=(
                        f"{ip} camera "
                        "config import"
                    ),
                )
            )

            if failure_text:
                raise DeviceParameterImportFailedError(
                    failure_text
                )

            print(
                f"[CAMERA CONFIG IMPORT WEB] "
                f"{ip} configuration-file "
                "import submission completed: "
                f"{submit_detail}"
            )

            add_result(
                results,
                ip,
                "Submit Camera Device Parameter Config",
                "WEB_UI",
                "",
                "OK",
                (
                    f"Import succeeded on attempt "
                    f"{attempt}/"
                    f"{DEVICE_CONFIG_IMPORT_MAX_ATTEMPTS}; "
                    f"prior explicit Import Failed "
                    f"detections={explicit_failure_count}; "
                    f"prior transient file-picker/UI "
                    f"retries={transient_failure_count}; "
                    "10-second browser processing grace + "
                    "shared 50-second wait pending; "
                    f"file={config_path}; "
                    f"detail={submit_detail}"
                ),
            )

            retain_pass0_import_browser(
                driver,
                ip,
                source_sheet,
            )

            driver = None

            if attempt > 1:
                print(
                    f"[IMPORT RETRY SUCCESS] "
                    f"{ip} camera import succeeded "
                    f"on attempt {attempt}/"
                    f"{DEVICE_CONFIG_IMPORT_MAX_ATTEMPTS}."
                )

            return True

        except DeviceParameterImportFailedError as error:
            explicit_failure_count += 1
            last_error = str(
                error
            )

            print(
                f"[IMPORT FAILED AUTO-RETRY] "
                f"{ip} ({source_sheet}) "
                "explicit Import Failed detected "
                f"on attempt {attempt}/"
                f"{DEVICE_CONFIG_IMPORT_MAX_ATTEMPTS}: "
                f"{last_error}"
            )

            if driver is not None:
                try:
                    save_web_ui_debug(
                        driver,
                        ip,
                        (
                            "camera_device_parameter_"
                            "import_failed_attempt_"
                            f"{attempt}"
                        ),
                    )
                except Exception:
                    pass

            if (
                attempt
                < DEVICE_CONFIG_IMPORT_MAX_ATTEMPTS
            ):
                print(
                    f"[IMPORT FAILED AUTO-RETRY] "
                    f"{ip} will re-open Maintenance, "
                    "re-select the same Excel config "
                    "file and import again."
                )

                time_module.sleep(
                    DEVICE_CONFIG_IMPORT_RETRY_DELAY_SECONDS
                )

                continue

        except CameraConfigTransientImportError as error:
            transient_failure_count += 1
            last_error = str(
                error
            )

            print(
                f"[CAMERA IMPORT TRANSIENT AUTO-RETRY] "
                f"{ip} ({source_sheet}) temporary "
                "file-picker/UI failure on attempt "
                f"{attempt}/"
                f"{DEVICE_CONFIG_IMPORT_MAX_ATTEMPTS}: "
                f"{last_error}"
            )

            if driver is not None:
                try:
                    save_web_ui_debug(
                        driver,
                        ip,
                        (
                            "camera_device_parameter_"
                            "transient_failure_attempt_"
                            f"{attempt}"
                        ),
                    )
                except Exception:
                    pass

            if (
                ENABLE_TRANSIENT_CAMERA_IMPORT_AUTO_RETRY
                and
                attempt
                < DEVICE_CONFIG_IMPORT_MAX_ATTEMPTS
            ):
                print(
                    f"[CAMERA IMPORT TRANSIENT AUTO-RETRY] "
                    f"{ip} will close this Edge session, "
                    "open a fresh browser, return to "
                    "Maintenance and select/import the "
                    "same config file again."
                )

                time_module.sleep(
                    DEVICE_CONFIG_IMPORT_RETRY_DELAY_SECONDS
                )

                continue

            break

        except Exception as error:
            last_error = str(
                error
            )

            if driver is not None:
                try:
                    save_web_ui_debug(
                        driver,
                        ip,
                        "camera_device_parameter_import_failure",
                    )
                except Exception:
                    pass

            if (
                ENABLE_TRANSIENT_CAMERA_IMPORT_AUTO_RETRY
                and
                is_transient_camera_config_import_error(
                    error
                )
                and
                attempt
                < DEVICE_CONFIG_IMPORT_MAX_ATTEMPTS
            ):
                transient_failure_count += 1

                print(
                    f"[CAMERA IMPORT TRANSIENT AUTO-RETRY] "
                    f"{ip} detected retryable camera "
                    "import error on attempt "
                    f"{attempt}/"
                    f"{DEVICE_CONFIG_IMPORT_MAX_ATTEMPTS}: "
                    f"{last_error}"
                )

                time_module.sleep(
                    DEVICE_CONFIG_IMPORT_RETRY_DELAY_SECONDS
                )

                continue

            # Non-transient programming/navigation/device errors still stop.
            break

        finally:
            if driver is not None:
                try:
                    driver.quit()
                except Exception:
                    pass

    detail = (
        "Camera web UI config import failed. "
        f"Explicit Import Failed detections="
        f"{explicit_failure_count}. "
        f"Transient file-picker/UI failures="
        f"{transient_failure_count}. "
        f"Last detail: {last_error}"
    )

    print(
        f"[FAILED] {ip}: {detail}"
    )

    add_result(
        results,
        ip,
        "Import Camera Device Parameter Config",
        "WEB_UI",
        "",
        "FAILED",
        detail,
    )

    return False

def wait_for_device_ready_after_shared_config_import(row):
    """Check one imported device after the shared direct-import reboot wait."""
    ip = get_value(row, "Current IP", "current_ip")
    username = get_value(row, "Username", "username")
    password = get_value(row, "Password", "password")

    deadline = (
        time_module.monotonic()
        + DEVICE_CONFIG_IMPORT_READY_TIMEOUT_SECONDS
    )

    consecutive_ready = 0
    last_status = None
    last_error = ""

    while time_module.monotonic() < deadline:
        try:
            status, response = get_xml(
                ip,
                username,
                password,
                "/ISAPI/System/deviceInfo",
            )

            last_status = status
            last_error = ""

            if status == 200:
                consecutive_ready += 1

                print(
                    f"[DEVICE CONFIG IMPORT] {ip} authenticated probe "
                    f"{consecutive_ready}/"
                    f"{DEVICE_CONFIG_IMPORT_REQUIRED_READY_PROBES} OK."
                )

                if (
                    consecutive_ready
                    >= DEVICE_CONFIG_IMPORT_REQUIRED_READY_PROBES
                ):
                    if is_discreet_camera_row(row):
                        print(
                            f"[DEVICE CONFIG IMPORT] {ip} authenticated GET "
                            "probes passed for Discreet camera."
                        )
                        print(
                            f"[DEVICE CONFIG IMPORT] {ip} skipping the old "
                            "no-op DeviceInfo PUT readiness probe because this "
                            "firmware can return HTTP 500/deviceError to that "
                            "probe even when the camera is healthy."
                        )

                        if DISCREET_POST_IMPORT_EXTRA_SETTLE_SECONDS > 0:
                            print(
                                f"[DEVICE CONFIG IMPORT] {ip} waiting "
                                f"{DISCREET_POST_IMPORT_EXTRA_SETTLE_SECONDS}s "
                                "extra before PASS 1."
                            )
                            time_module.sleep(
                                DISCREET_POST_IMPORT_EXTRA_SETTLE_SECONDS
                            )

                        read_checks = [
                            "/ISAPI/System/deviceInfo",
                            "/ISAPI/System/time",
                            "/ISAPI/Streaming/channels/101",
                        ]

                        readable = 0

                        for read_endpoint in read_checks:
                            try:
                                read_status, _read_response = get_xml(
                                    ip,
                                    username,
                                    password,
                                    read_endpoint,
                                )

                                if read_status == 200:
                                    readable += 1
                            except Exception:
                                pass

                        print(
                            f"[DEVICE CONFIG IMPORT] {ip} Discreet read-only "
                            f"sanity checks: {readable}/{len(read_checks)} "
                            "endpoint(s) returned HTTP 200."
                        )

                        print(
                            f"[OK] {ip} Discreet post-import readiness "
                            "accepted from stable authenticated GETs. "
                            "PASS 1 real writes will use retry/minimal-payload "
                            "handling."
                        )

                        return True, ""

                    return True, ""

            elif status in {401, 403}:
                return (
                    False,
                    f"{ip} is online but Excel credentials were rejected "
                    "after config import.",
                )

            else:
                consecutive_ready = 0

        except Exception as error:
            consecutive_ready = 0
            last_error = str(error)

        time_module.sleep(2)

    return (
        False,
        f"{ip} did not become stably authenticated after the shared import "
        f"wait. last_status={last_status}; last_error={last_error}",
    )


def import_nvr_device_parameter_config_via_web_ui(
    ip,
    username,
    password,
    config_path,
    import_password,
):
    """
    Perform PASS 0 through the exact NVR web UI.

    The NVR's own JavaScript handles:
        GET /ISAPI/Security/token
        + the firmware-specific configuration-file upload request.

    IMPORTANT:
        When the NVR import is accepted, its Edge session is transferred to
        the shared PASS 0 browser registry instead of being closed here.

        PASS 0 will:
            1. wait until ALL NVR / Discreet / Dome imports are submitted,
            2. keep all successful import browsers OPEN,
            3. wait one shared 150 seconds (240 seconds),
            4. close ALL retained PASS 0 Edge browsers,
            5. check device readiness,
            6. continue to PASS 1 when devices are back online.
    """
    driver = None

    def retain_successful_nvr_browser():
        """
        Transfer this successful NVR Edge session to the shared PASS 0
        browser registry.

        Setting driver=None is required so the finally block below does not
        immediately call driver.quit() on a browser that PASS 0 intentionally
        needs to keep open for the shared 10-second processing grace.
        """
        nonlocal driver

        if driver is None:
            return

        retain_pass0_import_browser(
            driver,
            ip,
            "NVR_Settings",
        )

        driver = None

    try:
        driver = create_nvr_config_import_edge_driver()

        # Clear startup network noise before navigation.
        try:
            driver.get_log("performance")
        except Exception:
            pass

        open_nvr_maintenance_import_page(
            driver,
            ip,
            username,
            password,
        )

        # Clear navigation/config-page traffic. We only want requests generated
        # by selecting the file + clicking Import.
        try:
            driver.get_log("performance")
        except Exception:
            pass

        with DEVICE_CONFIG_IMPORT_FILE_DIALOG_LOCK:
            select_nvr_device_parameter_config_file(
                driver,
                config_path,
            )

        print(
            "[NVR CONFIG IMPORT WEB] Device Parameters config file "
            "selection completed."
        )

        # Let the old NVR page consume the native file-picker result before
        # checking whether its Import button has become enabled.
        time_module.sleep(1.5)

        import_button = (
            find_nvr_device_parameter_import_button(
                driver,
                timeout=25,
            )
        )

        try:
            import_button.click()
        except Exception:
            # Browser-level click fallback.
            coords = driver.execute_script(
                """
                const element = arguments[0];

                element.scrollIntoView({
                    block: "center",
                    inline: "center"
                });

                const rect =
                    element.getBoundingClientRect();

                return {
                    x: rect.left + rect.width / 2,
                    y: rect.top + rect.height / 2
                };
                """,
                import_button,
            )

            click_x = float(
                coords["x"]
            )
            click_y = float(
                coords["y"]
            )

            for event_type, button_name in [
                ("mouseMoved", "none"),
                ("mousePressed", "left"),
                ("mouseReleased", "left"),
            ]:
                payload = {
                    "type": event_type,
                    "x": click_x,
                    "y": click_y,
                    "button": button_name,
                }

                if event_type != "mouseMoved":
                    payload[
                        "clickCount"
                    ] = 1

                driver.execute_cdp_cmd(
                    "Input.dispatchMouseEvent",
                    payload,
                )

        print(
            "[NVR CONFIG IMPORT WEB] Device Parameters Import clicked."
        )

        time_module.sleep(0.5)

        decryption_submitted = (
            submit_nvr_config_decryption_password(
                driver,
                import_password,
                timeout=15,
            )
        )

        if decryption_submitted:
            print(
                "[NVR CONFIG IMPORT WEB] File Decryption step completed."
            )
        else:
            print(
                "[NVR CONFIG IMPORT WEB] No File Decryption popup "
                "was displayed."
            )

        # Some firmware may show one additional confirmation after
        # decryption/password acceptance.
        time_module.sleep(0.5)
        click_nvr_import_confirmation_if_present(
            driver
        )

        # The visible Importing... dialog is accepted as proof that the NVR
        # accepted the configuration file/password.  An explicit Import Failed
        # response has priority and triggers a complete automatic re-import.
        import_started_in_ui = False
        import_state_deadline = (
            time_module.monotonic() + 8.0
        )

        while (
            time_module.monotonic()
            < import_state_deadline
        ):
            failure_text = (
                detect_and_dismiss_device_config_import_failure(
                    driver,
                    label=f"{ip} NVR config import",
                )
            )

            if failure_text:
                raise DeviceParameterImportFailedError(
                    failure_text
                )

            if nvr_config_importing_state_visible(
                driver
            ):
                print(
                    "[NVR CONFIG IMPORT WEB] "
                    "Hikvision UI entered "
                    "'Importing...' state. "
                    "Import request accepted."
                )

                import_started_in_ui = True
                break

            time_module.sleep(
                0.25
            )

        events = collect_nvr_config_import_network_events(
            driver,
            NVR_CONFIG_IMPORT_CAPTURE_NETWORK_SECONDS,
        )

        (
            token_events,
            upload_events,
        ) = summarize_nvr_import_network_events(
            events
        )

        # Import Failed may appear while performance logs are being collected.
        failure_text = (
            detect_and_dismiss_device_config_import_failure(
                driver,
                label=f"{ip} NVR config import",
            )
        )

        if failure_text:
            raise DeviceParameterImportFailedError(
                failure_text
            )

        if token_events:
            print(
                "[NVR CONFIG IMPORT WEB] Hikvision UI generated "
                f"{len(token_events)} Security/token request(s)."
            )
        else:
            print(
                "[NVR CONFIG IMPORT WEB WARNING] No Security/token "
                "request was observed after clicking Import."
            )

        if not upload_events:
            if import_started_in_ui:
                print(
                    "[NVR CONFIG IMPORT WEB WARNING] No POST/PUT upload "
                    "request was visible in Edge performance logs, but the "
                    "Hikvision UI is showing 'Importing...'. The import is "
                    "accepted. The script will wait the configured shared processing "
                    "processing/reboot period before checking the NVR."
                )

                retain_successful_nvr_browser()

                return (
                    True,
                    "WEB_UI:IMPORTING",
                    (
                        "Hikvision UI entered Importing state. Browser "
                        "performance logging did not expose the upload request."
                    ),
                )

            # This firmware does not always expose the upload request or the
            # Importing dialog quickly enough for Selenium/performance logging
            # to observe it. If the Import button and File Decryption OK were
            # successfully submitted, do not fail PASS 0 immediately.
            if decryption_submitted:
                print(
                    "[NVR CONFIG IMPORT WEB WARNING] The Import button and "
                    "File Decryption OK were submitted successfully, but Edge "
                    "did not observe the POST/PUT upload request or the "
                    "'Importing...' state within the short detection window. "
                    "Treating the import as submitted and waiting the fixed "
                    "3-minute NVR processing/reboot period."
                )

                retain_successful_nvr_browser()

                return (
                    True,
                    "WEB_UI:SUBMITTED",
                    (
                        "Import and File Decryption were submitted. Browser "
                        "logging did not expose the firmware-specific upload "
                        "request; post-import device readiness will be checked."
                    ),
                )

            save_web_ui_debug(
                driver,
                ip,
                "nvr_device_parameter_import_no_upload_request",
            )

            return (
                False,
                "",
                (
                    "Import could not be confirmed: no Importing state, no "
                    "POST/PUT upload event, and the File Decryption step was "
                    "not submitted."
                ),
            )

        # Print actual endpoint(s) discovered from the browser without exposing
        # query-string/token values.
        for event in upload_events:
            print(
                "[NVR CONFIG IMPORT WEB] Actual upload request: "
                f"{event['method']} {event['path']} "
                f"HTTP={event['status'] or 'NO_RESPONSE_YET'}"
            )

        successful_events = [
            event
            for event in upload_events
            if 200 <= int(
                event.get("status", 0)
                or 0
            ) < 300
        ]

        if successful_events:
            selected_event = successful_events[-1]

            retain_successful_nvr_browser()

            return (
                True,
                (
                    f"{selected_event['method']} "
                    f"{selected_event['path']}"
                ),
                (
                    f"Hikvision UI upload returned "
                    f"HTTP {selected_event['status']}."
                ),
            )

        # A request was definitely issued by the correct UI workflow but Edge
        # may lose the response if the NVR immediately restarts.
        no_response_events = [
            event
            for event in upload_events
            if not int(
                event.get("status", 0)
                or 0
            )
        ]

        if no_response_events:
            selected_event = no_response_events[-1]

            retain_successful_nvr_browser()

            return (
                True,
                (
                    f"{selected_event['method']} "
                    f"{selected_event['path']}"
                ),
                (
                    "The Hikvision web UI generated the upload request, "
                    "but no HTTP response was captured before the connection "
                    "changed. Post-import NVR readiness will be checked."
                ),
            )

        # We captured an explicit non-2xx response.
        selected_event = upload_events[-1]

        return (
            False,
            (
                f"{selected_event['method']} "
                f"{selected_event['path']}"
            ),
            (
                f"Hikvision UI upload returned "
                f"HTTP {selected_event['status']}."
            ),
        )

    except DeviceParameterImportFailedError as error:
        if driver is not None:
            try:
                save_web_ui_debug(
                    driver,
                    ip,
                    "nvr_device_parameter_import_failed",
                )
            except Exception:
                pass

        return (
            False,
            "WEB_UI:IMPORT_FAILED",
            f"IMPORT_FAILED: {error}",
        )

    except Exception as error:
        if driver is not None:
            try:
                save_web_ui_debug(
                    driver,
                    ip,
                    "nvr_device_parameter_import_web_ui_failure",
                )
            except Exception:
                pass

        return (
            False,
            "",
            f"Web UI import failed: {error}",
        )

    finally:
        if driver is not None:
            try:
                driver.quit()
            except Exception:
                pass


def import_nvr_device_parameter_config(row, results, excel_path, defer_wait=False):
    """Import one NVR configuration file from the path supplied in Excel."""
    ip = get_value(row, "Current IP", "current_ip")
    username = get_value(row, "Username", "username")
    password = get_value(row, "Password", "password")

    enabled_text = get_value(
        row,
        *NVR_CONFIG_IMPORT_ENABLED_HEADERS,
    )

    raw_path = get_value(
        row,
        *NVR_CONFIG_IMPORT_PATH_HEADERS,
    )

    import_password = get_value(
        row,
        *NVR_CONFIG_IMPORT_PASSWORD_HEADERS,
    )

    enabled = (
        str(enabled_text).strip().lower()
        in {"yes", "y", "true", "1", "enable", "enabled"}
    )

    # A path itself also enables the operation so the user can simply paste a
    # file path into Excel without needing to maintain a second flag.
    if not is_blank(raw_path):
        enabled = True

    if not ENABLE_NVR_DEVICE_PARAMETER_CONFIG_IMPORT:
        add_result(
            results,
            ip,
            "Import NVR Device Parameter Config",
            NVR_CONFIG_IMPORT_ENDPOINT,
            "",
            "SKIPPED",
            "Feature disabled in Python settings.",
        )
        return True

    if not enabled:
        print(
            f"[NVR CONFIG IMPORT] {ip}: no configuration import requested."
        )
        add_result(
            results,
            ip,
            "Import NVR Device Parameter Config",
            NVR_CONFIG_IMPORT_ENDPOINT,
            "",
            "SKIPPED",
            "Excel import flag/path is blank.",
        )
        return True

    config_path = resolve_config_import_file_path(
        raw_path,
        excel_path,
    )

    if config_path is None:
        print(
            f"[NVR CONFIG IMPORT] {ip}: import is enabled but the Excel "
            "config path is blank; skipping until a path is entered."
        )
        add_result(
            results,
            ip,
            "Import NVR Device Parameter Config",
            NVR_CONFIG_IMPORT_ENDPOINT,
            "",
            "SKIPPED",
            "Import enabled but Device Parameter Config Path is blank.",
        )
        return True

    print("=" * 100)
    print(f"[NVR CONFIG IMPORT] NVR IP      : {ip}")
    print(f"[NVR CONFIG IMPORT] Config file : {config_path}")

    if not config_path.is_file():
        detail = (
            f"Configuration file does not exist: {config_path}"
        )
        print(f"[FAILED] {detail}")
        add_result(
            results,
            ip,
            "Import NVR Device Parameter Config",
            NVR_CONFIG_IMPORT_ENDPOINT,
            "",
            "FAILED",
            detail,
        )
        return False

    file_size = config_path.stat().st_size

    if file_size <= 0:
        detail = f"Configuration file is empty: {config_path}"
        print(f"[FAILED] {detail}")
        add_result(
            results,
            ip,
            "Import NVR Device Parameter Config",
            NVR_CONFIG_IMPORT_ENDPOINT,
            "",
            "FAILED",
            detail,
        )
        return False

    print(
        f"[NVR CONFIG IMPORT] File size   : {file_size:,} bytes"
    )
    print(
        "[NVR CONFIG IMPORT] Import password: "
        + (
            "configured in Excel"
            if not is_blank(import_password)
            else "blank"
        )
    )

    if is_blank(import_password):
        print(
            "[NVR CONFIG IMPORT WARNING] Import password is blank in Excel. "
            "File selection can still be tested, but if the NVR displays the "
            "File Decryption popup, PASS 0 will stop until the import-password "
            "column is populated."
        )

    if DRY_RUN:
        print(
            "[DRY RUN] NVR device parameter config file validated. "
            "The Maintenance web UI import was not executed."
        )

        add_result(
            results,
            ip,
            "Import NVR Device Parameter Config",
            "WEB_UI: Maintenance > Device Parameters > Import",
            "DRY_RUN",
            "SKIPPED",
            f"Would import {config_path} ({file_size} bytes).",
        )

        return True

    if not NVR_CONFIG_IMPORT_USE_WEB_UI:
        detail = (
            "PASS 0 direct binary upload is disabled in v45 because the "
            "/ISAPI/Security/token request alone does not identify the actual "
            "firmware-specific upload request. Enable Web UI import."
        )

        print(f"[FAILED] {detail}")

        add_result(
            results,
            ip,
            "Import NVR Device Parameter Config",
            "WEB_UI",
            "",
            "FAILED",
            detail,
        )

        return False

    print(
        "[NVR CONFIG IMPORT] Using the NVR Maintenance web UI so the "
        "device's own JavaScript performs the exact token/upload workflow."
    )

    submitted = False
    actual_upload_endpoint = ""
    submit_detail = ""
    nvr_import_failed_count = 0
    successful_attempt = 0

    for attempt in range(
        1,
        DEVICE_CONFIG_IMPORT_MAX_ATTEMPTS + 1,
    ):
        print(
            f"[NVR CONFIG IMPORT ATTEMPT] "
            f"{ip} attempt {attempt}/"
            f"{DEVICE_CONFIG_IMPORT_MAX_ATTEMPTS}"
        )

        (
            submitted,
            actual_upload_endpoint,
            submit_detail,
        ) = (
            import_nvr_device_parameter_config_via_web_ui(
                ip,
                username,
                password,
                config_path,
                import_password,
            )
        )

        if submitted:
            successful_attempt = attempt
            break

        explicit_import_failed = (
            actual_upload_endpoint
            == "WEB_UI:IMPORT_FAILED"
            or str(
                submit_detail
            ).startswith(
                "IMPORT_FAILED:"
            )
        )

        if explicit_import_failed:
            nvr_import_failed_count += 1

            print(
                f"[IMPORT FAILED AUTO-RETRY] "
                f"{ip} NVR explicit Import Failed "
                f"detected on attempt {attempt}/"
                f"{DEVICE_CONFIG_IMPORT_MAX_ATTEMPTS}: "
                f"{submit_detail}"
            )

            if (
                attempt
                < DEVICE_CONFIG_IMPORT_MAX_ATTEMPTS
            ):
                print(
                    f"[IMPORT FAILED AUTO-RETRY] "
                    f"{ip} NVR will re-open Maintenance, "
                    "re-select the same Excel config "
                    "file and import again."
                )

                time_module.sleep(
                    DEVICE_CONFIG_IMPORT_RETRY_DELAY_SECONDS
                )

                continue

        # Do not blindly retry unrelated failures.
        break

    if not submitted:
        detail = (
            f"Web UI configuration import was not submitted successfully. "
            f"{submit_detail}; file={config_path}"
        )

        print(
            f"[FAILED] NVR configuration import: {detail}"
        )

        add_result(
            results,
            ip,
            "Import NVR Device Parameter Config",
            actual_upload_endpoint or "WEB_UI",
            "",
            "FAILED",
            detail,
        )

        return False

    print(
        "[NVR CONFIG IMPORT] Hikvision web UI import submission completed."
    )

    if defer_wait:
        print(
            "[NVR CONFIG IMPORT] Shared PASS 0 mode: readiness wait is "
            "deferred until all requested NVR/camera imports are submitted."
        )
        add_result(
            results,
            ip,
            "Submit NVR Device Parameter Config",
            actual_upload_endpoint or "WEB_UI",
            "",
            "OK",
            (
                f"Import succeeded on attempt "
                f"{successful_attempt or 1}/"
                f"{DEVICE_CONFIG_IMPORT_MAX_ATTEMPTS}; "
                f"prior explicit Import Failed detections="
                f"{nvr_import_failed_count}; "
                f"shared 150-second processing/reboot wait with PASS 0 Edge kept open pending; "
                f"file={config_path}; size={file_size} bytes; {submit_detail}"
            ),
        )
        return True

    print(
        "[NVR CONFIG IMPORT] The script will now use the shared 4m30 "
        "processing/reboot wait before checking device readiness."
    )

    ready, ready_detail = wait_for_nvr_after_config_import(
        ip,
        username,
        password,
    )

    if not ready:
        detail = (
            f"Web UI import was accepted, but post-import readiness failed. "
            f"{ready_detail}; upload={actual_upload_endpoint}; "
            f"file={config_path}"
        )

        print(
            f"[FAILED] NVR configuration import post-check failed: "
            f"{ready_detail}"
        )

        add_result(
            results,
            ip,
            "Import NVR Device Parameter Config",
            actual_upload_endpoint or "WEB_UI",
            "",
            "FAILED",
            detail,
        )

        return False

    print(
        f"[OK] NVR device parameter configuration import workflow "
        f"completed before PASS 1: {config_path.name}"
    )

    add_result(
        results,
        ip,
        "Import NVR Device Parameter Config",
        actual_upload_endpoint or "WEB_UI",
        "",
        "OK",
        (
            f"Web UI import before PASS 1; file={config_path}; "
            f"size={file_size} bytes; {submit_detail}"
        ),
    )

    return True

# =============================================================================
# XML HELPERS
# =============================================================================

def register_default_namespace(root):
    if root.tag.startswith("{"):
        namespace = root.tag.split("}")[0].replace("{", "")
        ET.register_namespace("", namespace)


def set_first_xml_tag_value(xml_text, possible_tag_names, new_value):
    root = ET.fromstring(xml_text)
    register_default_namespace(root)

    for elem in root.iter():
        local_name = elem.tag.split("}")[-1]

        if local_name in possible_tag_names:
            elem.text = str(new_value)
            return ET.tostring(root, encoding="unicode")

    raise ValueError(f"Cannot find tag: {possible_tag_names}")


def set_multiple_xml_values(xml_text, value_map):
    """
    value_map example:
    {
        "timeMode": "manual",
        "localTime": "2026-07-08T13:05:58+08:00"
    }
    """
    root = ET.fromstring(xml_text)
    register_default_namespace(root)

    found = {key: False for key in value_map.keys()}

    for elem in root.iter():
        local_name = elem.tag.split("}")[-1]

        if local_name in value_map:
            elem.text = str(value_map[local_name])
            found[local_name] = True

    missing = [key for key, value in found.items() if value is False]

    if missing:
        raise ValueError(f"Cannot find tags: {missing}")

    return ET.tostring(root, encoding="unicode")


def save_backup(ip, name, xml_text):
    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    safe_ip = safe_filename(ip)

    device_dir = BACKUP_DIR / safe_ip
    device_dir.mkdir(parents=True, exist_ok=True)

    filename = device_dir / f"{safe_ip}_{name}_{timestamp}.xml"

    with open(filename, "w", encoding="utf-8") as f:
        f.write(xml_text)

    return filename


def save_cert_payload(ip, hostname, xml_text):
    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    safe_ip = safe_filename(ip)
    safe_host = safe_filename(hostname)

    filename = CERT_PAYLOAD_DIR / f"{safe_ip}_{safe_host}_self_signed_cert_payload_{timestamp}.xml"

    with open(filename, "w", encoding="utf-8") as f:
        f.write(xml_text)

    return filename


# =============================================================================
# REPORT
# =============================================================================

RESULTS_LOCK = threading.Lock()


def add_result(results, ip, task, endpoint, status, result, detail):
    record = {
        "IP": ip,
        "Task": task,
        "Endpoint": endpoint,
        "Status": status,
        "Result": result,
        "Detail": detail,
    }

    # Camera workers may append results concurrently.
    with RESULTS_LOCK:
        results.append(record)


def normalize_result_value(value):
    return str(value or "").strip().upper()


def result_is_failure(record):
    result_value = normalize_result_value(
        record.get("Result")
    )

    return (
        result_value in {"FAILED", "ERROR"}
        or result_value.startswith("FAILED")
        or result_value.startswith("ERROR")
    )


def result_is_warning(record):
    result_value = normalize_result_value(
        record.get("Result")
    )

    return (
        result_value.startswith("WARNING")
        or result_value in {"PARTIAL", "INCOMPLETE"}
    )


def get_device_result_summary(results, ip):
    with RESULTS_LOCK:
        records = [
            dict(record)
            for record in results
            if str(record.get("IP", "")).strip()
            == str(ip).strip()
        ]

    failures = [
        record
        for record in records
        if result_is_failure(record)
    ]

    warnings = [
        record
        for record in records
        if result_is_warning(record)
    ]

    return {
        "records": records,
        "failures": failures,
        "warnings": warnings,
        "success": not failures,
    }


def print_configuration_result_summary(results):
    with RESULTS_LOCK:
        snapshot = [
            dict(record)
            for record in results
        ]

    result_counts = {}

    for record in snapshot:
        result_value = normalize_result_value(
            record.get("Result")
        ) or "BLANK"

        result_counts[result_value] = (
            result_counts.get(result_value, 0) + 1
        )

    failures = [
        record
        for record in snapshot
        if result_is_failure(record)
    ]

    warnings = [
        record
        for record in snapshot
        if result_is_warning(record)
    ]

    print("=" * 100)
    print("[CONFIGURATION SUMMARY]")
    print(f"[CONFIGURATION SUMMARY] Total records: {len(snapshot)}")

    for result_value in sorted(result_counts):
        print(
            f"[CONFIGURATION SUMMARY] "
            f"{result_value}: {result_counts[result_value]}"
        )

    if failures:
        print("-" * 100)
        print(
            "[CONFIGURATION SUMMARY] Tasks not configured "
            "successfully:"
        )

        failures_by_ip = {}

        for record in failures:
            failures_by_ip.setdefault(
                record.get("IP", ""),
                [],
            ).append(record)

        for ip in sorted(failures_by_ip):
            print(f"[FAILED DEVICE] {ip}")

            for record in failures_by_ip[ip]:
                print(
                    "  - "
                    f"{record.get('Task', '')}: "
                    f"{record.get('Detail', '')}"
                )
    else:
        print(
            "[CONFIGURATION SUMMARY] No FAILED or ERROR tasks."
        )

    if warnings:
        print("-" * 100)
        print(
            "[CONFIGURATION SUMMARY] Warning tasks requiring "
            "review:"
        )

        for record in warnings:
            print(
                f"  - {record.get('IP', '')} | "
                f"{record.get('Task', '')} | "
                f"{record.get('Result', '')} | "
                f"{record.get('Detail', '')}"
            )

    print("=" * 100)


def write_report(results):
    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    report_file = (
        REPORT_DIR
        / f"bulk_excel_hikvision_config_report_{timestamp}.csv"
    )
    issues_file = (
        REPORT_DIR
        / f"bulk_excel_hikvision_config_issues_{timestamp}.csv"
    )

    fieldnames = [
        "IP",
        "Task",
        "Endpoint",
        "Status",
        "Result",
        "Detail",
    ]

    with RESULTS_LOCK:
        snapshot = [
            dict(record)
            for record in results
        ]

    with open(
        report_file,
        "w",
        newline="",
        encoding="utf-8-sig",
    ) as f:
        writer = csv.DictWriter(
            f,
            fieldnames=fieldnames,
        )
        writer.writeheader()
        writer.writerows(snapshot)

    issue_records = [
        record
        for record in snapshot
        if (
            result_is_failure(record)
            or result_is_warning(record)
        )
    ]

    with open(
        issues_file,
        "w",
        newline="",
        encoding="utf-8-sig",
    ) as f:
        writer = csv.DictWriter(
            f,
            fieldnames=fieldnames,
        )
        writer.writeheader()
        writer.writerows(issue_records)

    print_configuration_result_summary(snapshot)

    print(f"[REPORT] Full report saved: {report_file}")
    print(
        f"[REPORT] Failed/warning tasks saved: "
        f"{issues_file}"
    )



def is_discreet_camera_row(row):
    """Return True for the old-UI Discreet camera rows."""
    source_sheet = get_value(row, "Source Sheet")
    camera_type = get_value(row, "Camera Type", "camera_type")
    device_group = get_value(row, "Device Group")

    return (
        source_sheet == "Discreet_Settings"
        or "DISCREET" in str(camera_type).upper()
        or "DISCREET" in str(device_group).upper()
    )


def find_existing_xml_local_name(
    xml_text,
    possible_names,
):
    """
    Return the exact local tag name already used by the device XML.
    Matching is case-insensitive.
    """
    try:
        root = ET.fromstring(xml_text)
    except Exception:
        return ""

    wanted = {
        str(name).strip().lower()
        for name in possible_names
    }

    for element in root.iter():
        local_name = element.tag.split("}")[-1]

        if local_name.lower() in wanted:
            return local_name

    return ""


def build_minimal_isapi_xml_from_current(
    current_xml,
    value_map,
    preserve_existing_tags=(),
):
    """
    Build a minimal PUT payload while preserving the device's actual root
    element, namespace and root attributes.

    This is important for older Discreet firmware. Sending the complete XML
    returned by GET can include read-only/unsupported elements and cause
    Device Error / badXmlContent / badPort on PUT.

    value_map:
        {"deviceName": "2B..."}
        {"timeMode": "manual", "localTime": "..."}

    preserve_existing_tags:
        e.g. ("id",) for StreamingChannel / VideoInputChannel / NTPServer.
    """
    root = ET.fromstring(current_xml)

    if root.tag.startswith("{"):
        namespace = root.tag.split("}")[0][1:]
        ET.register_namespace("", namespace)
    else:
        namespace = ""

    def qname(local_name):
        return (
            f"{{{namespace}}}{local_name}"
            if namespace
            else local_name
        )

    # Preserve root attributes such as version.
    new_root = ET.Element(
        root.tag,
        dict(root.attrib),
    )

    # Map existing elements by local name so their exact case/tag can be
    # reused whenever possible.
    existing = {}

    for element in root.iter():
        local_name = element.tag.split("}")[-1]
        existing.setdefault(
            local_name.lower(),
            element,
        )

    added = set()

    for requested_name in preserve_existing_tags:
        key = str(requested_name).strip().lower()
        element = existing.get(key)

        if element is None:
            continue

        local_name = element.tag.split("}")[-1]

        child = ET.SubElement(
            new_root,
            element.tag,
        )
        child.text = (
            str(element.text)
            if element.text is not None
            else ""
        )
        added.add(local_name.lower())

    for requested_name, requested_value in value_map.items():
        key = str(requested_name).strip().lower()

        if key in added:
            continue

        existing_element = existing.get(key)

        if existing_element is not None:
            tag = existing_element.tag
        else:
            tag = qname(
                str(requested_name).strip()
            )

        child = ET.SubElement(
            new_root,
            tag,
        )
        child.text = str(requested_value)

    body = ET.tostring(
        new_root,
        encoding="unicode",
    )

    return (
        '<?xml version="1.0" encoding="UTF-8"?>'
        + body
    )


def is_transient_discreet_write_error(
    status,
    response_text,
):
    """
    Old Discreet cameras may briefly return these while still initializing
    after a configuration-file import.
    """
    parsed = parse_response_status_fields(
        response_text or ""
    )

    sub_status = str(
        parsed.get("sub_status_code", "")
    ).strip().lower()

    status_string = str(
        parsed.get("status_string", "")
    ).strip().lower()

    response_lower = str(
        response_text or ""
    ).lower()

    return (
        int(status or 0) in {400, 409, 423, 429, 500, 502, 503, 504}
        or sub_status in {
            "deviceerror",
            "badxmlcontent",
            "badxmlformat",
            "badport",
            "notready",
            "busy",
            "operationfailed",
        }
        or "device error" in response_lower
        or "deviceerror" in response_lower
        or "badxmlcontent" in response_lower
        or "badport" in response_lower
        or "busy" in status_string
    )


def put_xml_with_discreet_retry(
    row,
    endpoint,
    xml_text,
    task_label,
):
    """
    PUT XML with retry only for old Discreet cameras.

    Dome/NVR behaviour remains unchanged.
    """
    ip = get_value(row, "Current IP", "current_ip")
    username = get_value(row, "Username", "username")
    password = get_value(row, "Password", "password")

    attempts = (
        DISCREET_ISAPI_WRITE_RETRY_ATTEMPTS
        if is_discreet_camera_row(row)
        else 1
    )

    last_status = None
    last_response = ""

    for attempt in range(1, attempts + 1):
        status, response = put_xml(
            ip,
            username,
            password,
            endpoint,
            xml_text,
        )

        last_status = status
        last_response = response

        if status in [200, 204]:
            if attempt > 1:
                print(
                    f"[DISCREET RETRY OK] {ip} {task_label} "
                    f"succeeded on attempt {attempt}/{attempts}."
                )
            return status, response

        if (
            not is_discreet_camera_row(row)
            or attempt >= attempts
            or not is_transient_discreet_write_error(
                status,
                response,
            )
        ):
            return status, response

        print(
            f"[DISCREET RETRY] {ip} {task_label} returned HTTP {status}; "
            f"waiting {DISCREET_ISAPI_WRITE_RETRY_DELAY_SECONDS}s before "
            f"attempt {attempt + 1}/{attempts}."
        )

        time_module.sleep(
            DISCREET_ISAPI_WRITE_RETRY_DELAY_SECONDS
        )

    return last_status, last_response


def put_json_with_discreet_retry(
    row,
    endpoint,
    json_text,
    task_label,
):
    """PUT JSON with the same old-Discreet transient retry handling."""
    ip = get_value(row, "Current IP", "current_ip")
    username = get_value(row, "Username", "username")
    password = get_value(row, "Password", "password")

    attempts = (
        DISCREET_ISAPI_WRITE_RETRY_ATTEMPTS
        if is_discreet_camera_row(row)
        else 1
    )

    last_status = None
    last_response = ""

    for attempt in range(1, attempts + 1):
        status, response = put_json(
            ip,
            username,
            password,
            endpoint,
            json_text,
        )

        last_status = status
        last_response = response

        if status in [200, 204]:
            if attempt > 1:
                print(
                    f"[DISCREET RETRY OK] {ip} {task_label} "
                    f"succeeded on attempt {attempt}/{attempts}."
                )
            return status, response

        if (
            not is_discreet_camera_row(row)
            or attempt >= attempts
            or not is_transient_discreet_write_error(
                status,
                response,
            )
        ):
            return status, response

        print(
            f"[DISCREET RETRY] {ip} {task_label} returned HTTP {status}; "
            f"waiting {DISCREET_ISAPI_WRITE_RETRY_DELAY_SECONDS}s before "
            f"attempt {attempt + 1}/{attempts}."
        )

        time_module.sleep(
            DISCREET_ISAPI_WRITE_RETRY_DELAY_SECONDS
        )

    return last_status, last_response


def probe_discreet_write_ready_after_import(
    row,
):
    """
    Diagnostic-only Discreet post-import readiness probe.

    This old firmware can return HTTP 500/deviceError to a NO-OP
    PUT /ISAPI/System/deviceInfo even when authenticated GET is already stable.

    PASS 0 must therefore NOT use that PUT as a blocking readiness test.
    The real PASS 1 configuration writes have their own retry/minimal-payload
    handling.
    """
    if not is_discreet_camera_row(row):
        return True, ""

    ip = get_value(row, "Current IP", "current_ip")
    username = get_value(row, "Username", "username")
    password = get_value(row, "Password", "password")

    try:
        status, response = get_xml(
            ip,
            username,
            password,
            "/ISAPI/System/deviceInfo",
        )
    except Exception as error:
        return (
            False,
            f"Discreet diagnostic DeviceInfo GET failed: {error}",
        )

    if status == 200:
        return (
            True,
            "Authenticated DeviceInfo GET is stable. "
            "Blocking DeviceInfo PUT probe intentionally disabled.",
        )

    return (
        False,
        f"Discreet diagnostic DeviceInfo GET returned HTTP {status}; "
        f"response={str(response)[:300]}",
    )



def is_dome_camera_row(row):
    source_sheet = get_value(row, "Source Sheet")
    camera_type = get_value(row, "Camera Type", "camera_type")
    device_group = get_value(row, "Device Group")

    return (
        source_sheet == "Dome_Settings"
        or "DOME" in camera_type.upper()
        or "DOME" in device_group.upper()
    )


def get_xml_local_name(element):
    return element.tag.split("}")[-1]


def extract_xml_tag_text(xml_text, tag_name):
    """
    Read the first matching XML tag value without depending on namespaces.
    """
    try:
        root = ET.fromstring(xml_text)
    except Exception:
        return ""

    wanted = str(tag_name).strip().lower()

    for element in root.iter():
        if get_xml_local_name(element).lower() == wanted:
            return (
                element.text.strip()
                if element.text
                else ""
            )

    return ""


def extract_xml_opt_values(xml_text, tag_name):
    """
    Extract the comma-separated opt attribute from a capability XML tag.

    Example:
        <ShutterLevel opt="1/50,1/100,1/250">1/250</ShutterLevel>
    """
    try:
        root = ET.fromstring(xml_text)
    except Exception:
        return []

    wanted = str(tag_name).strip().lower()

    for element in root.iter():
        if get_xml_local_name(element).lower() != wanted:
            continue

        opt_text = str(element.attrib.get("opt", "")).strip()

        if not opt_text:
            return []

        return [
            value.strip()
            for value in opt_text.split(",")
            if value.strip()
        ]

    return []


def normalize_exposure_time(value):
    """
    Normalise common Excel inputs such as:
        1/250
        1 / 250
        '1/250

    The camera still receives Hikvision's expected value, e.g. 1/250.
    """
    if is_blank(value):
        return ""

    exposure_time = str(value).strip()

    if exposure_time.startswith("'"):
        exposure_time = exposure_time[1:].strip()

    exposure_time = re.sub(
        r"\s*/\s*",
        "/",
        exposure_time
    )

    return exposure_time


def build_dome_shutter_xml(exposure_time):
    return f"""<?xml version="1.0" encoding="UTF-8"?>
<Shutter>
  <ShutterLevel>{exposure_time}</ShutterLevel>
</Shutter>"""


def configure_dome_exposure_time(row, results):
    """
    Dome camera only.

    Reads Exposure Time from Dome_Settings, validates it against:
        GET /ISAPI/Image/channels/1/capabilities

    Applies it through:
        PUT /ISAPI/Image/channels/1/shutter

    Then reads the shutter endpoint again and verifies ShutterLevel.
    """
    if not is_dome_camera_row(row):
        return

    ip = get_value(row, "Current IP", "current_ip")
    username = get_value(row, "Username", "username")
    password = get_value(row, "Password", "password")

    exposure_time = normalize_exposure_time(
        get_value(
            row,
            "Exposure Time",
            "ExposureTime",
            "Shutter Level",
            "ShutterLevel",
            "Shutter Speed"
        )
    )

    task = "Configure Dome Exposure Time"
    capabilities_endpoint = (
        DOME_EXPOSURE_CAPABILITIES_ENDPOINT
    )
    shutter_endpoint = (
        DOME_EXPOSURE_SHUTTER_ENDPOINT
    )

    if not ENABLE_DOME_EXPOSURE_TIME_UPDATE:
        print(
            f"[SKIP] {ip} Dome Exposure Time update disabled."
        )

        add_result(
            results,
            ip,
            task,
            shutter_endpoint,
            "",
            "SKIPPED",
            "ENABLE_DOME_EXPOSURE_TIME_UPDATE=False"
        )
        return

    if is_blank(exposure_time):
        print(
            f"[SKIP] {ip} no Exposure Time in Dome_Settings."
        )

        add_result(
            results,
            ip,
            task,
            shutter_endpoint,
            "",
            "SKIPPED",
            "Exposure Time is blank"
        )
        return

    print(
        f"[DOME EXPOSURE] {ip} requested Exposure Time: "
        f"{exposure_time}"
    )

    # -----------------------------------------------------------------
    # 1. Read and back up image capabilities
    # -----------------------------------------------------------------
    capability_status, capability_xml = backup_endpoint(
        row,
        capabilities_endpoint,
        "dome_image_capabilities_before",
        results
    )

    supported_values = []

    if capability_status == 200:
        supported_values = extract_xml_opt_values(
            capability_xml,
            "ShutterLevel"
        )

        current_capability_value = extract_xml_tag_text(
            capability_xml,
            "ShutterLevel"
        )

        print(
            f"[DOME EXPOSURE] {ip} capability default/current "
            f"ShutterLevel: {current_capability_value or 'Unknown'}"
        )

        if supported_values:
            print(
                f"[DOME EXPOSURE] {ip} supported values: "
                f"{', '.join(supported_values)}"
            )
    elif VALIDATE_DOME_EXPOSURE_AGAINST_CAPABILITIES:
        print(
            f"[FAILED] {ip} cannot read image capabilities; "
            "Exposure Time was not changed."
        )

        add_result(
            results,
            ip,
            task,
            capabilities_endpoint,
            capability_status,
            "FAILED",
            "Capabilities GET failed; shutter update stopped"
        )
        return

    if (
        VALIDATE_DOME_EXPOSURE_AGAINST_CAPABILITIES
        and supported_values
        and exposure_time not in supported_values
    ):
        detail = (
            f"Exposure Time {exposure_time} is unsupported. "
            f"Supported values: {', '.join(supported_values)}"
        )

        print(f"[FAILED] {ip} {detail}")

        add_result(
            results,
            ip,
            task,
            capabilities_endpoint,
            capability_status,
            "FAILED",
            detail
        )
        return

    # -----------------------------------------------------------------
    # 2. Read and back up the current shutter setting
    # -----------------------------------------------------------------
    current_status, current_shutter_xml = backup_endpoint(
        row,
        shutter_endpoint,
        "dome_shutter_before",
        results
    )

    current_exposure_time = ""

    if current_status == 200:
        current_exposure_time = extract_xml_tag_text(
            current_shutter_xml,
            "ShutterLevel"
        )

        print(
            f"[DOME EXPOSURE] {ip} current Exposure Time: "
            f"{current_exposure_time or 'Unknown'}"
        )

        if current_exposure_time == exposure_time:
            print(
                f"[SKIP] {ip} Exposure Time is already "
                f"{exposure_time}."
            )

            add_result(
                results,
                ip,
                task,
                shutter_endpoint,
                current_status,
                "SKIPPED",
                f"Already configured: {exposure_time}"
            )
            return
    else:
        print(
            f"[WARNING] {ip} current shutter GET failed; "
            "the confirmed PUT will still be attempted."
        )

    shutter_xml = build_dome_shutter_xml(
        exposure_time
    )

    if DRY_RUN:
        print(
            f"[DRY RUN] Would configure Dome Exposure Time "
            f"for {ip}: {exposure_time}"
        )

        add_result(
            results,
            ip,
            task,
            shutter_endpoint,
            "",
            "DRY_RUN",
            (
                f"Current={current_exposure_time or 'Unknown'}; "
                f"Target={exposure_time}"
            )
        )
        return

    # -----------------------------------------------------------------
    # 3. Apply the confirmed shutter endpoint
    # -----------------------------------------------------------------
    status, response = put_xml(
        ip,
        username,
        password,
        shutter_endpoint,
        shutter_xml
    )

    success = status in [200, 204]

    if success and not is_blank(response):
        response_lower = response.lower()

        explicit_error = (
            "<statuscode>" in response_lower
            and "<statuscode>1</statuscode>"
            not in response_lower
        )

        if explicit_error:
            success = False

    if not success:
        print(
            f"[FAILED] Dome Exposure Time update failed "
            f"for {ip}: HTTP {status}"
        )
        print(response[:500])

        add_result(
            results,
            ip,
            task,
            shutter_endpoint,
            status,
            "FAILED",
            response[:500]
        )
        return

    print(
        f"[OK] Dome Exposure Time PUT accepted for "
        f"{ip}: {exposure_time}"
    )

    time_module.sleep(1)

    # -----------------------------------------------------------------
    # 4. Verify the applied ShutterLevel
    # -----------------------------------------------------------------
    verify_status, verify_xml = get_xml(
        ip,
        username,
        password,
        shutter_endpoint
    )

    verified_value = ""

    if verify_status == 200:
        verified_value = extract_xml_tag_text(
            verify_xml,
            "ShutterLevel"
        )

    if (
        verify_status == 200
        and verified_value == exposure_time
    ):
        print(
            f"[OK] Dome Exposure Time verified for "
            f"{ip}: {verified_value}"
        )

        add_result(
            results,
            ip,
            task,
            shutter_endpoint,
            status,
            "OK",
            (
                f"Previous={current_exposure_time or 'Unknown'}; "
                f"Configured={exposure_time}; "
                f"Verified={verified_value}"
            )
        )
    else:
        detail = (
            f"PUT accepted, but verification did not match. "
            f"Expected={exposure_time}; "
            f"GET status={verify_status}; "
            f"Actual={verified_value or 'Unknown'}"
        )

        print(f"[WARNING] {ip} {detail}")

        add_result(
            results,
            ip,
            task,
            shutter_endpoint,
            verify_status,
            "WARNING",
            detail
        )


