def backup_endpoint(row, endpoint, backup_name, results):
    ip = get_value(row, "Current IP", "current_ip")
    user = get_value(row, "Username", "username")
    password = get_value(row, "Password", "password")

    status, xml_text = get_xml(ip, user, password, endpoint)

    if status == 200:
        backup_file = save_backup(ip, backup_name, xml_text)
        print(f"[BACKUP] {ip} {endpoint} -> {backup_file}")
        add_result(results, ip, f"Backup {backup_name}", endpoint, status, "OK", str(backup_file))
        return status, xml_text

    print(f"[FAILED] {ip} GET {endpoint} failed: {status}")
    print(xml_text[:300])
    add_result(results, ip, f"Backup {backup_name}", endpoint, status, "FAILED", xml_text[:300])
    return status, xml_text


def update_hostname(row, results):
    ip = get_value(row, "Current IP", "current_ip")
    user = get_value(row, "Username", "username")
    password = get_value(row, "Password", "password")
    hostname = get_value(row, "Hostname", "hostname")

    endpoint = "/ISAPI/System/deviceInfo"

    if is_blank(hostname):
        print(f"[SKIP] {ip} no Hostname")
        add_result(results, ip, "Update Hostname", endpoint, "", "SKIPPED", "No Hostname")
        return

    status, current_xml = backup_endpoint(row, endpoint, "deviceInfo_before", results)

    if status != 200:
        print(f"[SKIP] {ip} hostname update skipped")
        add_result(results, ip, "Update Hostname", endpoint, status, "SKIPPED", "GET failed")
        return

    try:
        if is_discreet_camera_row(row):
            actual_tag = (
                find_existing_xml_local_name(
                    current_xml,
                    ["deviceName", "hostName", "hostname"],
                )
                or "deviceName"
            )

            new_xml = build_minimal_isapi_xml_from_current(
                current_xml,
                {
                    actual_tag: hostname,
                },
            )
        else:
            new_xml = set_first_xml_tag_value(
                current_xml,
                ["deviceName", "hostName", "hostname"],
                hostname
            )
    except Exception as e:
        print(f"[FAILED] {ip} prepare hostname XML failed: {e}")
        add_result(results, ip, "Update Hostname", endpoint, "", "FAILED", str(e))
        return

    if DRY_RUN:
        print(f"[DRY RUN] Would update Hostname for {ip} to {hostname}")
        add_result(results, ip, "Update Hostname", endpoint, "", "DRY_RUN", hostname)
        return

    status, response = put_xml_with_discreet_retry(
        row,
        endpoint,
        new_xml,
        "Update Hostname",
    )

    if status in [200, 204]:
        print(f"[OK] Hostname updated for {ip}: {hostname}")
        add_result(results, ip, "Update Hostname", endpoint, status, "OK", hostname)
    else:
        print(f"[FAILED] Hostname update failed for {ip}: {status}")
        print(response[:500])
        add_result(results, ip, "Update Hostname", endpoint, status, "FAILED", response[:500])


