def manual_time_sync_with_computer(row, results):
    ip = get_value(row, "Current IP", "current_ip")
    user = get_value(row, "Username", "username")
    password = get_value(row, "Password", "password")

    endpoint = "/ISAPI/System/time"

    status, current_xml = backup_endpoint(row, endpoint, "time_before_manual_sync", results)

    if status != 200:
        print(f"[SKIP] {ip} manual time sync skipped")
        add_result(results, ip, "Manual Time Sync", endpoint, status, "SKIPPED", "GET failed")
        return

    computer_time = current_computer_time_iso()

    try:
        # /ISAPI/System/time is different from several other old-Discreet
        # endpoints: this DS-2CD6B45WD/M firmware needs the complete Time
        # document returned by GET, including required companion fields such
        # as timeZone. The previous minimal payload containing only
        # timeMode/localTime was rejected with HTTP 400/badXmlContent.
        #
        # Preserve the complete current Time XML and change only the fields
        # controlled by this workflow.
        new_xml = set_multiple_xml_values(
            current_xml,
            {
                "timeMode": "manual",
                "localTime": computer_time,
            }
        )
    except Exception as e:
        print(f"[FAILED] {ip} prepare manual time XML failed: {e}")
        add_result(results, ip, "Manual Time Sync", endpoint, "", "FAILED", str(e))
        return

    if DRY_RUN:
        print(f"[DRY RUN] Would manual sync time for {ip} to computer time: {computer_time}")
        add_result(results, ip, "Manual Time Sync", endpoint, "", "DRY_RUN", computer_time)
        return

    status, response = put_xml_with_discreet_retry(
        row,
        endpoint,
        new_xml,
        "Manual Time Sync",
    )

    if status in [200, 204]:
        print(f"[OK] Manual time synced for {ip}: {computer_time}")
        add_result(results, ip, "Manual Time Sync", endpoint, status, "OK", computer_time)
    else:
        print(f"[FAILED] Manual time sync failed for {ip}: {status}")
        print(response[:500])
        add_result(results, ip, "Manual Time Sync", endpoint, status, "FAILED", response[:500])


