def get_camera_server_certificates(
    ip,
    username,
    password,
):
    """
    Read the camera certificate list.

    Returns:
        {
            "status": HTTP status,
            "certificates": list,
            "response": raw response,
            "endpoint": endpoint,
        }
    """
    endpoint = (
        "/ISAPI/Security/serverCertificate/"
        "certificates?format=json"
    )

    status, response = get_json(
        ip,
        username,
        password,
        endpoint,
    )

    certificates = []

    if status == 200:
        try:
            data = json.loads(response)

            certificates = (
                data
                .get("ServerCertificates", {})
                .get("CertificateInfoList", {})
                .get("CertificateInfo", [])
            )

            if isinstance(certificates, dict):
                certificates = [certificates]

            if not isinstance(certificates, list):
                certificates = []

        except Exception:
            certificates = []

    return {
        "status": status,
        "certificates": certificates,
        "response": response,
        "endpoint": endpoint,
    }


def camera_server_certificate_exists(
    ip,
    username,
    password,
    certificate_id,
):
    """
    Check whether the requested certificate ID already exists.
    """
    result = get_camera_server_certificates(
        ip,
        username,
        password,
    )

    requested_id = str(certificate_id).strip().lower()

    matching_certificate = None

    for certificate in result["certificates"]:
        custom_id = str(
            certificate.get("customID", "")
        ).strip().lower()

        if custom_id == requested_id:
            matching_certificate = certificate
            break

    result["exists"] = matching_certificate is not None
    result["matching_certificate"] = matching_certificate

    return result


def prepare_or_create_self_signed_cert(row, results):
    ip = get_value(row, "Current IP")
    user = get_value(row, "Username")
    password = get_value(row, "Password")
    source_sheet = get_value(row, "Source Sheet")
    camera_type = get_value(row, "Camera Type")

    is_nvr = source_sheet == "NVR_Settings" or "NVR" in camera_type.upper()

    iv = secrets.token_hex(16)

    # ============================================================
    # NVR METHOD
    # NVR does not use selfSignCert endpoint.
    # It creates CSR by certSignReq, then downloads by downloadCertSignReq.
    # ============================================================
    if is_nvr:
        hostname, cert_xml = build_nvr_cert_sign_req_xml(row)

        # ========================================================
        # SKIP IF CSR ALREADY EXISTS
        # Put this after hostname is generated
        # ========================================================
        existing_csr_file = CSR_DIR / f"{safe_filename(hostname)}.csr"

        if existing_csr_file.exists():
            print(f"[SKIP] CSR already exists for {ip}: {existing_csr_file}")

            add_result(
                results,
                ip,
                "Skip NVR Certificate Request",
                "",
                "",
                "SKIPPED",
                f"CSR already exists: {existing_csr_file}"
            )

            return

        create_endpoint = f"/ISAPI/Security/serverCertificate/certSignReq?security=1&iv={iv}"
        download_endpoint = "/ISAPI/Security/serverCertificate/downloadCertSignReq"

        task_name = "Create NVR Certificate Request"

        payload_file = save_cert_payload(ip, hostname, cert_xml)
        print(f"[CERT PAYLOAD] {ip} saved -> {payload_file}")

        if DRY_RUN:
            print(f"[DRY RUN] Would create NVR CSR for {ip}")
            print(f"[DRY RUN] PUT Endpoint: {create_endpoint}")
            print(f"[DRY RUN] GET Endpoint: {download_endpoint}")
            print(f"[DRY RUN] Hostname: {hostname}")

            add_result(
                results,
                ip,
                task_name,
                create_endpoint,
                "",
                "DRY_RUN",
                hostname
            )
            return

        # Step 1: Create NVR certificate request
        status, response = put_xml(ip, user, password, create_endpoint, cert_xml)

        if status != 200:
            print(f"[FAILED] {task_name} failed for {ip}: {status}")
            print(response[:500])

            add_result(
                results,
                ip,
                task_name,
                create_endpoint,
                status,
                "FAILED",
                response[:500]
            )
            return

        print(f"[OK] {task_name} success for {ip}: {hostname}")

        print(f"[WAIT] Waiting 5 seconds after certificate operation for {ip}")
        time_module.sleep(5)

        add_result(
            results,
            ip,
            task_name,
            create_endpoint,
            status,
            "OK",
            hostname
        )

        # Step 2: Download NVR CSR
        get_status, get_response = get_xml(ip, user, password, download_endpoint)

        if get_status != 200:
            print(f"[FAILED] NVR CSR download failed for {ip}: {get_status}")
            print(get_response[:500])

            add_result(
                results,
                ip,
                "Download NVR CSR",
                download_endpoint,
                get_status,
                "FAILED",
                get_response[:500]
            )
            return

        csr_pem = extract_csr_pem(get_response)

        if csr_pem is None:
            raw_file = CSR_DIR / f"{safe_filename(hostname)}_raw_response.txt"

            with open(raw_file, "w", encoding="utf-8", errors="ignore") as f:
                f.write(get_response)

            print(f"[FAILED] NVR CSR PEM not found in response for {ip}")
            print(f"[RAW SAVED] {raw_file}")
            print("[RAW RESPONSE PREVIEW]")
            print(get_response[:1000])

            add_result(
                results,
                ip,
                "Download NVR CSR",
                download_endpoint,
                get_status,
                "FAILED",
                f"PEM not found. Raw saved: {raw_file}"
            )
            return

        csr_file = save_csr_file(hostname, csr_pem)

        print(f"[OK] NVR CSR downloaded: {csr_file}")

        add_result(
            results,
            ip,
            "Download NVR CSR",
            download_endpoint,
            get_status,
            "OK",
            str(csr_file)
        )

        return

    # ============================================================
    # CAMERA / DISCREET / DOME METHOD
    # Use selfSignCert endpoint.
    # ============================================================
    hostname, cert_xml = build_camera_self_signed_cert_xml(row)

    # A local CSR file is NOT proof that the camera still has its configured certificate
    # certificate. PASS 0 Device Parameter import can restore/replace the
    # camera certificate store while the old CSR remains on this PC.
    #
    # Therefore always verify the certificate on the DEVICE first.
    existing_csr_file = CSR_DIR / f"{safe_filename(hostname)}.csr"

    cert_id = get_value(row, "Certificate ID")

    if is_blank(cert_id):
        cert_id = DEFAULT_HTTPS_CERT_ID

    # Check the device before creating another certificate. Hikvision often
    # returns HTTP 500 when the requested customID already exists.
    existing_certificate_check = camera_server_certificate_exists(
        ip,
        user,
        password,
        cert_id,
    )

    if (
        existing_csr_file.exists()
        and not existing_certificate_check.get("exists")
    ):
        print(
            f"[CERT RECOVERY] {ip} local CSR exists but device certificate "
            f"{cert_id} is missing after config import. Recreating the "
            "camera certificate before service selection."
        )

    if existing_certificate_check.get("exists"):
        existing_certificate = (
            existing_certificate_check.get("matching_certificate")
            or {}
        )

        print(
            f"[SKIP] Camera certificate {cert_id} already exists "
            f"for {ip}."
        )

        add_result(
            results,
            ip,
            "Create Camera Self-Signed Certificate",
            existing_certificate_check.get("endpoint", ""),
            existing_certificate_check.get("status", ""),
            "SKIPPED",
            (
                f"Certificate ID={cert_id} already exists; "
                f"status={existing_certificate.get('status', '')}; "
                f"type={existing_certificate.get('type', '')}"
            )
        )

        return

    endpoint = f"/ISAPI/Security/serverCertificate/selfSignCert?customID={cert_id}&security=1&iv={iv}"
    task_name = "Create Camera Self-Signed Certificate"

    payload_file = save_cert_payload(ip, hostname, cert_xml)
    print(f"[CERT PAYLOAD] {ip} saved -> {payload_file}")

    if DRY_RUN:
        print(f"[DRY RUN] Would run {task_name} for {ip}")
        print(f"[DRY RUN] Endpoint: {endpoint}")
        print(f"[DRY RUN] Hostname: {hostname}")

        add_result(
            results,
            ip,
            task_name,
            endpoint,
            "",
            "DRY_RUN",
            hostname
        )
        return

    status, response = put_xml(ip, user, password, endpoint, cert_xml)

    if status == 200:
        print(f"[OK] {task_name} success for {ip}: {hostname}")

        add_result(
            results,
            ip,
            task_name,
            endpoint,
            status,
            "OK",
            hostname
        )

    else:
        response_preview = response[:500]

        print(f"[WARNING] {task_name} returned {status} for {ip}")
        print(response_preview)

        # Some Hikvision camera firmware returns HTTP 500 even though the
        # certificate is created successfully. Verify the certificate list
        # before deciding whether this is a real failure.
        time_module.sleep(2)

        verification = camera_server_certificate_exists(
            ip,
            user,
            password,
            cert_id,
        )

        if verification.get("exists"):
            certificate = (
                verification.get("matching_certificate")
                or {}
            )

            print(
                f"[OK] Camera certificate {cert_id} exists after "
                f"the HTTP {status} response for {ip}."
            )

            add_result(
                results,
                ip,
                task_name,
                endpoint,
                status,
                "OK_VERIFIED",
                (
                    f"Create returned HTTP {status}, but certificate "
                    f"ID={cert_id} was verified in the certificate list; "
                    f"certificate status={certificate.get('status', '')}; "
                    f"type={certificate.get('type', '')}"
                )
            )

        else:
            print(
                "[WARNING] Certificate was not found in the certificate "
                "list after the device-error response."
            )
            print(
                "[WARNING] The script will continue to CSR creation. "
                "CSR success will provide the next validation point."
            )

            add_result(
                results,
                ip,
                task_name,
                endpoint,
                status,
                "WARNING_CONTINUE",
                (
                    f"{response_preview}; certificate ID={cert_id} "
                    "not confirmed in certificate list"
                )
            )

        # Do not return. Continue to CSR creation/download.

