# DOME CAMERA WEBSOCKETS - SELENIUM WEB UI AUTOMATION
# =============================================================================

def open_exact_dome_websockets_page(driver, ip):
    """
    Open the WebSocket(s) page directly inside the already authenticated
    Edge session.

    This does not click or pass through Multicast.
    """
    target_hash = "#/config/network/advanced/WebSocket"

    print("[WEB NAV] Opening WebSocket(s) page directly.")
    print("[WEB NAV] Multicast page will not be used.")

    driver.execute_script(
        """
        const targetHash = arguments[0];

        if (window.location.hash !== targetHash) {
            window.location.hash = targetHash;
            window.dispatchEvent(
                new HashChangeEvent("hashchange")
            );
        }
        """,
        target_hash
    )

    def exact_websockets_elements_ready(current_driver):
        return current_driver.execute_script(
            """
            const switchXPath = arguments[0];
            const saveXPath = arguments[1];

            function getByXPath(xpath) {
                return document.evaluate(
                    xpath,
                    document,
                    null,
                    XPathResult.FIRST_ORDERED_NODE_TYPE,
                    null
                ).singleNodeValue;
            }

            function visible(element) {
                if (!element) return false;

                const style = window.getComputedStyle(element);
                const rect = element.getBoundingClientRect();

                return (
                    style.display !== "none" &&
                    style.visibility !== "hidden" &&
                    Number(style.opacity || "1") !== 0 &&
                    rect.width > 0 &&
                    rect.height > 0
                );
            }

            const switchButton = getByXPath(switchXPath);
            const saveButton = getByXPath(saveXPath);

            return (
                visible(switchButton) &&
                visible(saveButton)
            );
            """,
            DOME_WEBSOCKETS_SWITCH_XPATH,
            DOME_WEBSOCKETS_SAVE_XPATH
        )

    try:
        WebDriverWait(
            driver,
            EDGE_UI_WAIT_TIMEOUT
        ).until(exact_websockets_elements_ready)

    except Exception:
        # Retry with direct URL in the same authenticated browser session.
        direct_url = (
            f"https://{ip}{DOME_WEBSOCKETS_SETTINGS_PATH}"
            f"?t={int(time_module.time() * 1000)}"
        )

        print(
            "[WEB NAV] Hash navigation did not finish. "
            f"Retrying direct authenticated URL: {direct_url}"
        )

        driver.get(direct_url)

        WebDriverWait(
            driver,
            EDGE_UI_WAIT_TIMEOUT
        ).until(exact_websockets_elements_ready)

    print(f"[WEB NAV] WebSocket(s) page ready: {driver.current_url}")
    return True


def get_exact_dome_websockets_state(driver):
    """
    Read the lower plural WebSockets checkbox through the confirmed XPath.
    """
    return driver.execute_script(
        """
        const switchXPath = arguments[0];

        const switchButton = document.evaluate(
            switchXPath,
            document,
            null,
            XPathResult.FIRST_ORDERED_NODE_TYPE,
            null
        ).singleNodeValue;

        if (!switchButton) {
            return null;
        }

        const switchLabel = switchButton.closest("label");

        if (!switchLabel) {
            return null;
        }

        const checkbox = switchLabel.querySelector(
            'input[type="checkbox"]'
        );

        if (!checkbox) {
            return null;
        }

        return Boolean(checkbox.checked);
        """,
        DOME_WEBSOCKETS_SWITCH_XPATH
    )


def run_exact_dome_websockets_console_script(driver):
    """
    Execute the confirmed WebSockets browser method without async JavaScript.

    The previous version raised:
        javascript error: Unexpected string

    because the JavaScript contained Python-style adjacent string literals.
    This version performs the same operation through small synchronous
    JavaScript calls and uses Python sleep between each browser action.

    It changes only the lower plural WebSockets switch.
    """

    # ================================================================
    # Step 1: Find the confirmed lower WebSockets switch and read state
    # ================================================================
    switch_result = driver.execute_script(
        """
        const switchXPath = arguments[0];

        function getByXPath(xpath) {
            return document.evaluate(
                xpath,
                document,
                null,
                XPathResult.FIRST_ORDERED_NODE_TYPE,
                null
            ).singleNodeValue;
        }

        const switchButton = getByXPath(switchXPath);

        if (!switchButton) {
            return {
                ok: false,
                stage: "find_switch",
                detail: "Confirmed lower WebSockets switch XPath was not found."
            };
        }

        const switchLabel = switchButton.closest("label");

        if (!switchLabel) {
            return {
                ok: false,
                stage: "find_label",
                detail: "Parent label for lower WebSockets switch was not found."
            };
        }

        const checkbox = switchLabel.querySelector(
            'input[type="checkbox"]'
        );

        if (!checkbox) {
            return {
                ok: false,
                stage: "find_checkbox",
                detail: "WebSockets checkbox input was not found."
            };
        }

        switchLabel.scrollIntoView({
            block: "center",
            inline: "center"
        });

        window.__exactDomeWebSocketsLabel = switchLabel;
        window.__exactDomeWebSocketsCheckbox = checkbox;

        return {
            ok: true,
            stage: "switch_ready",
            before: Boolean(checkbox.checked)
        };
        """,
        DOME_WEBSOCKETS_SWITCH_XPATH
    )

    if not isinstance(switch_result, dict) or not switch_result.get("ok"):
        return switch_result

    before = bool(switch_result.get("before"))

    # ================================================================
    # Step 2: Normal Element-UI click
    # ================================================================
    if not before:
        driver.execute_script(
            """
            const label = window.__exactDomeWebSocketsLabel;

            if (!label) {
                throw new Error("Stored WebSockets switch label is missing.");
            }

            label.click();
            """
        )

        time_module.sleep(1)

    after_click = driver.execute_script(
        """
        const checkbox = window.__exactDomeWebSocketsCheckbox;
        return checkbox ? Boolean(checkbox.checked) : null;
        """
    )

    # ================================================================
    # Step 3: Exact fallback confirmed in DevTools Console
    # ================================================================
    if after_click is not True:
        fallback_result = driver.execute_script(
            """
            const label = window.__exactDomeWebSocketsLabel;
            const checkbox = window.__exactDomeWebSocketsCheckbox;

            if (!label || !checkbox) {
                return {
                    ok: false,
                    detail: "Stored WebSockets switch elements are missing."
                };
            }

            const descriptor = Object.getOwnPropertyDescriptor(
                window.HTMLInputElement.prototype,
                "checked"
            );

            if (!descriptor || !descriptor.set) {
                return {
                    ok: false,
                    detail: "Native checkbox checked setter was not found."
                };
            }

            descriptor.set.call(checkbox, true);

            checkbox.dispatchEvent(
                new Event("input", {
                    bubbles: true
                })
            );

            checkbox.dispatchEvent(
                new Event("change", {
                    bubbles: true
                })
            );

            label.classList.add("is-checked");

            return {
                ok: true,
                checked: Boolean(checkbox.checked)
            };
            """
        )

        if not isinstance(fallback_result, dict) or not fallback_result.get("ok"):
            detail = (
                fallback_result.get("detail", str(fallback_result))
                if isinstance(fallback_result, dict)
                else str(fallback_result)
            )

            return {
                "ok": False,
                "stage": "fallback_enable",
                "before": before,
                "after": after_click,
                "detail": detail,
            }

        time_module.sleep(1)

    final_switch_state = driver.execute_script(
        """
        const checkbox = window.__exactDomeWebSocketsCheckbox;
        return checkbox ? Boolean(checkbox.checked) : null;
        """
    )

    if final_switch_state is not True:
        return {
            "ok": False,
            "stage": "enable_switch",
            "before": before,
            "after": final_switch_state,
            "detail": "Lower plural WebSockets switch did not enable.",
        }

    # ================================================================
    # Step 4: Find and click the confirmed Save button
    # ================================================================
    save_result = driver.execute_script(
        """
        const saveXPath = arguments[0];

        function getByXPath(xpath) {
            return document.evaluate(
                xpath,
                document,
                null,
                XPathResult.FIRST_ORDERED_NODE_TYPE,
                null
            ).singleNodeValue;
        }

        const saveButton = getByXPath(saveXPath);

        if (!saveButton) {
            return {
                ok: false,
                detail: "Confirmed WebSocket(s) Save XPath was not found."
            };
        }

        saveButton.scrollIntoView({
            block: "center",
            inline: "center"
        });

        saveButton.click();

        return {
            ok: true
        };
        """,
        DOME_WEBSOCKETS_SAVE_XPATH
    )

    if not isinstance(save_result, dict) or not save_result.get("ok"):
        detail = (
            save_result.get("detail", str(save_result))
            if isinstance(save_result, dict)
            else str(save_result)
        )

        return {
            "ok": False,
            "stage": "find_or_click_save",
            "before": before,
            "after": final_switch_state,
            "detail": detail,
        }

    time_module.sleep(2.5)

    return {
        "ok": True,
        "stage": "saved",
        "before": before,
        "after": final_switch_state,
        "saveClicked": True,
        "detail": (
            "Lower WebSockets was already enabled; Save clicked."
            if before
            else "Lower WebSockets enabled; Save clicked."
        ),
    }



def enable_and_verify_dome_websockets(
    driver,
    row,
    results
):
    """
    Continue immediately after HTTPS Browsing is verified:

        WebSocket(s)
          -> enable lower plural WebSockets
          -> Save
          -> reload exact WebSocket(s) page
          -> verify

    Multicast is not opened or clicked.
    """
    ip = get_value(row, "Current IP", "current_ip")
    task = "Enable Dome WebSockets via Web UI"
    endpoint = DOME_WEBSOCKETS_SETTINGS_PATH

    if not ENABLE_DOME_WEBSOCKETS_UI:
        print(f"[SKIP] {ip} Dome WebSockets UI automation disabled")

        add_result(
            results,
            ip,
            task,
            endpoint,
            "",
            "SKIPPED",
            "ENABLE_DOME_WEBSOCKETS_UI=False"
        )
        return True

    try:
        open_exact_dome_websockets_page(driver, ip)

        before = get_exact_dome_websockets_state(driver)

        print(
            f"[WEB UI] {ip} lower plural WebSockets "
            f"state before: {before}"
        )
        print(
            f"[WEB UI] {ip} enabling lower plural WebSockets now"
        )

        result = run_exact_dome_websockets_console_script(driver)

        if not isinstance(result, dict) or not result.get("ok"):
            stage = (
                result.get("stage", "unknown")
                if isinstance(result, dict)
                else "unknown"
            )
            detail = (
                result.get("detail", str(result))
                if isinstance(result, dict)
                else str(result)
            )

            print(
                f"[FAILED] {ip} WebSockets UI step "
                f"{stage}: {detail}"
            )

            add_result(
                results,
                ip,
                task,
                endpoint,
                "",
                "FAILED",
                f"Stage={stage}; {detail}"
            )
            return False

        print(
            f"[WEB UI] {ip} WebSockets before="
            f"{result.get('before')}, after={result.get('after')}"
        )
        print(f"[WEB UI] {ip} WebSocket(s) Save clicked")

        time_module.sleep(EDGE_SAVE_WAIT_SECONDS)

        # Reload the exact WebSocket(s) page, not Multicast.
        direct_url = (
            f"https://{ip}{DOME_WEBSOCKETS_SETTINGS_PATH}"
            f"?t={int(time_module.time() * 1000)}"
        )

        driver.get(direct_url)

        WebDriverWait(
            driver,
            EDGE_UI_WAIT_TIMEOUT
        ).until(
            lambda current_driver: (
                get_exact_dome_websockets_state(
                    current_driver
                ) is not None
            )
        )

        verified = get_exact_dome_websockets_state(driver)

        if verified is True:
            print(
                f"[OK] Dome lower plural WebSockets "
                f"enabled and verified for {ip}"
            )

            add_result(
                results,
                ip,
                task,
                endpoint,
                200,
                "OK",
                (
                    f"Before={result.get('before')}; "
                    f"After={result.get('after')}; "
                    "Verified after reload=True; "
                    "Upper singular WebSocket unchanged; "
                    "Multicast not opened"
                )
            )
            return True

        print(
            f"[FAILED] {ip} lower plural WebSockets "
            "did not remain enabled"
        )

        add_result(
            results,
            ip,
            task,
            endpoint,
            "",
            "FAILED",
            (
                f"Console result={result}; "
                f"Verified after reload={verified}"
            )
        )
        return False

    except Exception as error:
        print(
            f"[FAILED] Dome WebSockets UI automation "
            f"failed for {ip}: {error}"
        )

        save_web_ui_debug(
            driver,
            ip,
            "exact_websockets_failure"
        )

        add_result(
            results,
            ip,
            task,
            endpoint,
            "",
            "FAILED",
            str(error)
        )
        return False




