def discreet_xpath_element_visible(driver, xpath):
    """
    Return True when the supplied old-UI XPath exists and is visible.
    """
    return driver.execute_script(
        """
        const xpath = arguments[0];

        const element = document.evaluate(
            xpath,
            document,
            null,
            XPathResult.FIRST_ORDERED_NODE_TYPE,
            null
        ).singleNodeValue;

        if (!element) {
            return false;
        }

        const style = window.getComputedStyle(element);
        const rect = element.getBoundingClientRect();

        return (
            style.display !== "none" &&
            style.visibility !== "hidden" &&
            Number(style.opacity || "1") !== 0 &&
            rect.width > 0 &&
            rect.height > 0
        );
        """,
        xpath
    )


def wait_for_discreet_xpath(driver, xpath, timeout=None):
    """
    Wait for a confirmed Discreet-camera XPath.
    """
    if timeout is None:
        timeout = EDGE_UI_WAIT_TIMEOUT

    WebDriverWait(
        driver,
        timeout
    ).until(
        lambda current_driver: discreet_xpath_element_visible(
            current_driver,
            xpath
        )
    )

    return True


def open_discreet_configuration_page(
    driver,
    ip,
    username,
    password
):
    """
    Log in to the old Discreet-camera web interface and open Configuration.

    Preferred method:
      Live View -> Configuration

    Fallback:
      Open /doc/page/config.asp directly in the authenticated Edge session.
    """
    if not is_hikvision_authenticated_page(driver):
        hikvision_web_login_if_needed(
            driver,
            username,
            password
        )
        time_module.sleep(3)

    if "/doc/page/config.asp" in str(driver.current_url).lower():
        print("[DISCREET NAV] Already on Configuration page.")
        return True

    print("[DISCREET NAV] Clicking Configuration.")

    try:
        click_visible_exact_text(
            driver,
            ["Configuration"],
            "Discreet Configuration",
            timeout=20
        )
        time_module.sleep(4)
    except Exception as error:
        print(
            f"[DISCREET NAV WARNING] Configuration click failed: {error}"
        )

    if "/doc/page/config.asp" not in str(driver.current_url).lower():
        config_url = (
            f"https://{ip}{DISCREET_CONFIG_PATH}"
            f"?t={int(time_module.time() * 1000)}"
        )

        print(
            "[DISCREET NAV] Opening authenticated Configuration URL: "
            f"{config_url}"
        )

        driver.get(config_url)
        time_module.sleep(4)

    if not is_hikvision_authenticated_page(driver):
        hikvision_web_login_if_needed(
            driver,
            username,
            password
        )
        time_module.sleep(3)

        driver.get(
            f"https://{ip}{DISCREET_CONFIG_PATH}"
            f"?t={int(time_module.time() * 1000)}"
        )
        time_module.sleep(4)

    print(f"[DISCREET NAV] Configuration page ready: {driver.current_url}")
    return True


def open_discreet_advanced_network(
    driver,
    ip,
    username,
    password
):
    """
    Navigate:
      Configuration -> Network -> Advanced Settings
    """
    open_discreet_configuration_page(
        driver,
        ip,
        username,
        password
    )

    print("[DISCREET NAV] Clicking Network.")

    try:
        click_visible_exact_text(
            driver,
            ["Network"],
            "Discreet Network",
            timeout=20
        )
        time_module.sleep(2)
    except Exception as error:
        print(
            f"[DISCREET NAV WARNING] Network click failed: {error}"
        )

    print("[DISCREET NAV] Clicking Advanced Settings.")

    try:
        click_visible_exact_text(
            driver,
            ["Advanced Settings"],
            "Discreet Advanced Settings",
            timeout=12
        )
    except Exception as first_error:
        print(
            f"[DISCREET NAV WARNING] Exact Advanced Settings click failed: "
            f"{first_error}. Trying recursive old-UI navigation."
        )

        try:
            click_old_ui_menu_item_recursive(
                driver,
                "Advanced Settings",
                "Discreet Advanced Settings",
                timeout=20,
                max_depth=4,
            )
        except Exception as second_error:
            print(
                "[DISCREET NAV WARNING] Recursive Advanced Settings click "
                f"also failed: {second_error}. Reloading Configuration and "
                "retrying Network > Advanced Settings once."
            )

            driver.switch_to.default_content()
            driver.get(
                f"https://{ip}{DISCREET_CONFIG_PATH}"
                f"?t={int(time_module.time() * 1000)}"
            )
            time_module.sleep(4)

            if not is_hikvision_authenticated_page(driver):
                hikvision_web_login_if_needed(
                    driver,
                    username,
                    password,
                )
                time_module.sleep(2)

            try:
                click_old_ui_menu_item_recursive(
                    driver,
                    "Network",
                    "Discreet Network",
                    timeout=15,
                    max_depth=4,
                )
            except Exception:
                click_visible_exact_text(
                    driver,
                    ["Network"],
                    "Discreet Network",
                    timeout=15,
                )

            time_module.sleep(2)

            click_old_ui_menu_item_recursive(
                driver,
                "Advanced Settings",
                "Discreet Advanced Settings",
                timeout=20,
                max_depth=4,
            )

    time_module.sleep(3)
    return True


def open_discreet_https_page(
    driver,
    ip,
    username,
    password
):
    """
    Navigate:
      Configuration -> Network -> Advanced Settings -> HTTPS
    """
    if discreet_xpath_element_visible(
        driver,
        DISCREET_HTTPS_BROWSING_CHECKBOX_XPATH
    ):
        print("[DISCREET NAV] Already on HTTPS page.")
        return True

    open_discreet_advanced_network(
        driver,
        ip,
        username,
        password
    )

    print("[DISCREET NAV] Clicking HTTPS.")

    click_visible_exact_text(
        driver,
        ["HTTPS"],
        "Discreet HTTPS tab",
        timeout=20
    )

    wait_for_discreet_xpath(
        driver,
        DISCREET_HTTPS_BROWSING_CHECKBOX_XPATH
    )

    wait_for_discreet_xpath(
        driver,
        DISCREET_HTTPS_SAVE_XPATH
    )

