def open_discreet_network_service_page(
    driver,
    ip,
    username,
    password
):
    """
    After HTTPS Browsing verification, remain under Advanced Settings and
    directly click the Network Service tab.

    Required sequence:
        HTTPS
          -> Network Service
          -> enable lower plural WebSockets

    It does not click Network again.
    It does not click Advanced Settings again.
    It does not open Multicast.
    """
    if discreet_xpath_element_visible(
        driver,
        DISCREET_WEBSOCKETS_CHECKBOX_XPATH
    ):
        print("[DISCREET NAV] Already on Network Service page.")
        return True

    print(
        "[DISCREET NAV] Directly clicking Network Service "
        "from the current HTTPS page."
    )
    print(
        "[DISCREET NAV] Network and Advanced Settings "
        "will not be clicked again."
    )
    print("[DISCREET NAV] Multicast will not be opened.")

    try:
        click_visible_exact_text(
            driver,
            ["Network Service"],
            "Discreet Network Service tab",
            timeout=20
        )

    except Exception as error:
        save_web_ui_debug(
            driver,
            ip,
            "discreet_network_service_tab_not_found"
        )

        raise RuntimeError(
            "Could not directly click Network Service from the HTTPS page. "
            f"Current URL={driver.current_url}; error={error}"
        )

    wait_for_discreet_xpath(
        driver,
        DISCREET_WEBSOCKETS_CHECKBOX_XPATH
    )

    wait_for_discreet_xpath(
        driver,
        DISCREET_WEBSOCKETS_SAVE_XPATH
    )

    print("[DISCREET NAV] Network Service page ready.")
    return True



def get_discreet_checkbox_state(driver, checkbox_xpath):
    """
    Read a confirmed old-UI Angular checkbox state.
    """
    return driver.execute_script(
        """
        const xpath = arguments[0];

        const checkbox = document.evaluate(
            xpath,
            document,
            null,
            XPathResult.FIRST_ORDERED_NODE_TYPE,
            null
        ).singleNodeValue;

        if (!checkbox) {
            return null;
        }

        return Boolean(checkbox.checked);
        """,
        checkbox_xpath
    )


def run_discreet_checkbox_console_method(
    driver,
    checkbox_xpath,
    save_xpath,
    setting_name
):
    """
    Execute the exact DevTools Console method confirmed working on the
    Discreet camera's Angular-based interface.

    Steps:
      1. Find checkbox.
      2. Normal click.
      3. Native checked setter + input/change + Angular change fallback.
      4. Click confirmed Save button.
    """
    initial = driver.execute_script(
        """
        const checkboxXPath = arguments[0];

        const checkbox = document.evaluate(
            checkboxXPath,
            document,
            null,
            XPathResult.FIRST_ORDERED_NODE_TYPE,
            null
        ).singleNodeValue;

        if (!checkbox) {
            return {
                ok: false,
                stage: "find_checkbox",
                detail: "Confirmed checkbox XPath was not found."
            };
        }

        if (checkbox.disabled) {
            return {
                ok: false,
                stage: "checkbox_disabled",
                detail: "The checkbox is disabled."
            };
        }

        checkbox.scrollIntoView({
            block: "center",
            inline: "center"
        });

        window.__discreetTargetCheckbox = checkbox;

        return {
            ok: true,
            before: Boolean(checkbox.checked)
        };
        """,
        checkbox_xpath
    )

    if not isinstance(initial, dict) or not initial.get("ok"):
        return initial

    before = bool(initial.get("before"))

    if not before:
        driver.execute_script(
            """
            const checkbox = window.__discreetTargetCheckbox;

            if (!checkbox) {
                throw new Error("Stored checkbox is missing.");
            }

            checkbox.click();
            """
        )

        time_module.sleep(0.7)

    after_click = driver.execute_script(
        """
        const checkbox = window.__discreetTargetCheckbox;
        return checkbox ? Boolean(checkbox.checked) : null;
        """
    )

    if after_click is not True:
        fallback = driver.execute_script(
            """
            const checkbox = window.__discreetTargetCheckbox;

            if (!checkbox) {
                return {
                    ok: false,
                    detail: "Stored checkbox is missing."
                };
            }

            const descriptor = Object.getOwnPropertyDescriptor(
                window.HTMLInputElement.prototype,
                "checked"
            );

            if (!descriptor || !descriptor.set) {
                return {
                    ok: false,
                    detail: "Native checked setter was not found."
                };
            }

            descriptor.set.call(checkbox, true);

            checkbox.dispatchEvent(
                new Event("input", {
                    bubbles: true
                })
            );

            checkbox.dispatchEvent(
                new Event("change", {
                    bubbles: true
                })
            );

            if (window.angular) {
                try {
                    window.angular
                        .element(checkbox)
                        .triggerHandler("change");
                } catch (error) {
                    console.warn(
                        "Angular change warning:",
                        String(error)
                    );
                }
            }

            return {
                ok: true,
                checked: Boolean(checkbox.checked)
            };
            """
        )

        if not isinstance(fallback, dict) or not fallback.get("ok"):
            detail = (
                fallback.get("detail", str(fallback))
                if isinstance(fallback, dict)
                else str(fallback)
            )

            return {
                "ok": False,
                "stage": "fallback_enable",
                "before": before,
                "after": after_click,
                "detail": detail,
            }

        time_module.sleep(0.7)

    after = driver.execute_script(
        """
        const checkbox = window.__discreetTargetCheckbox;
        return checkbox ? Boolean(checkbox.checked) : null;
        """
    )

    if after is not True:
        return {
            "ok": False,
            "stage": "enable_checkbox",
            "before": before,
            "after": after,
            "detail": f"{setting_name} did not enable.",
        }

    save_result = driver.execute_script(
        """
        const saveXPath = arguments[0];

        const saveButton = document.evaluate(
            saveXPath,
            document,
            null,
            XPathResult.FIRST_ORDERED_NODE_TYPE,
            null
        ).singleNodeValue;

        if (!saveButton) {
            return {
                ok: false,
                detail: "Confirmed Save XPath was not found."
            };
        }

        saveButton.scrollIntoView({
            block: "center",
            inline: "center"
        });

        saveButton.click();

        return {
            ok: true
        };
        """,
        save_xpath
    )

    if not isinstance(save_result, dict) or not save_result.get("ok"):
        detail = (
            save_result.get("detail", str(save_result))
            if isinstance(save_result, dict)
            else str(save_result)
        )

        return {
            "ok": False,
            "stage": "find_or_click_save",
            "before": before,
            "after": after,
            "detail": detail,
        }

    time_module.sleep(2.5)

    return {
        "ok": True,
        "stage": "saved",
        "before": before,
        "after": after,
        "saveClicked": True,
        "detail": (
            f"{setting_name} was already enabled; Save clicked."
            if before
            else f"{setting_name} enabled; Save clicked."
        ),
    }


def enable_discreet_https_and_websockets_via_ui(
    row,
    results,
    account_security_configurations,
):
    """
    Discreet camera only:

      Configuration
        -> Network
        -> Advanced Settings
        -> HTTPS
        -> Enable HTTPS Browsing
        -> Save
        -> Network Service
        -> Enable lower plural WebSockets
        -> Save

    The upper singular WebSocket option is not modified.
    """
    ip = get_value(row, "Current IP", "current_ip")
    username = get_value(row, "Username", "username")
    password = get_value(row, "Password", "password")
    source_sheet = get_value(row, "Source Sheet")
    camera_type = get_value(row, "Camera Type", "camera_type")

    is_discreet = (
        source_sheet == "Discreet_Settings"
        or "DISCREET" in camera_type.upper()
    )

    if not is_discreet:
        return

    if not ENABLE_DISCREET_HTTPS_AND_WEBSOCKETS_UI:
        print(
            f"[SKIP] {ip} Discreet HTTPS/WebSockets "
            "UI automation disabled."
        )

        add_result(
            results,
            ip,
            "Enable Discreet HTTPS and WebSockets",
            "",
            "",
            "SKIPPED",
            "ENABLE_DISCREET_HTTPS_AND_WEBSOCKETS_UI=False"
        )
        return

    if DRY_RUN:
        print(
            f"[DRY RUN] Would enable Discreet HTTPS Browsing "
            f"and WebSockets for {ip}"
        )

        add_result(
            results,
            ip,
            "Enable Discreet HTTPS and WebSockets",
            "",
            "",
            "DRY_RUN",
            "Would use the confirmed old-UI checkbox and Save XPaths"
        )
        return

    if not SELENIUM_AVAILABLE:
        detail = "Install Selenium first: python -m pip install selenium"

        print(f"[FAILED] {ip} {detail}")

        add_result(
            results,
            ip,
            "Enable Discreet HTTPS and WebSockets",
            "",
            "",
            "FAILED",
            detail
        )
        return

    driver = None

    preview_url = (
        f"https://{ip}{DISCREET_PREVIEW_PATH}"
        f"?t={int(time_module.time() * 1000)}"
    )

    try:
        print(
            f"[DISCREET WEB UI] Opening camera: {preview_url}"
        )

        driver = create_hikvision_edge_driver()
        driver.get(preview_url)

        hikvision_web_login_if_needed(
            driver,
            username,
            password
        )

        time_module.sleep(3)

        # ============================================================
        # Step 1: Enable HTTPS Browsing
        # ============================================================
        open_discreet_https_page(
            driver,
            ip,
            username,
            password
        )

        https_before = get_discreet_checkbox_state(
            driver,
            DISCREET_HTTPS_BROWSING_CHECKBOX_XPATH
        )

        print(
            f"[DISCREET WEB UI] {ip} HTTPS Browsing "
            f"state before: {https_before}"
        )

        https_result = run_discreet_checkbox_console_method(
            driver,
            DISCREET_HTTPS_BROWSING_CHECKBOX_XPATH,
            DISCREET_HTTPS_SAVE_XPATH,
            "HTTPS Browsing"
        )

        if (
            not isinstance(https_result, dict)
            or not https_result.get("ok")
        ):
            stage = (
                https_result.get("stage", "unknown")
                if isinstance(https_result, dict)
                else "unknown"
            )

            detail = (
                https_result.get("detail", str(https_result))
                if isinstance(https_result, dict)
                else str(https_result)
            )

            raise RuntimeError(
                f"HTTPS Browsing step failed at {stage}: {detail}"
            )

        print(
            f"[OK] Discreet HTTPS Browsing enabled for {ip}; "
            "Save clicked."
        )

        add_result(
            results,
            ip,
            "Enable Discreet HTTPS Browsing",
            DISCREET_HTTPS_BROWSING_CHECKBOX_XPATH,
            200,
            "OK",
            (
                f"Before={https_result.get('before')}; "
                f"After={https_result.get('after')}; "
                "Save clicked"
            )
        )

        time_module.sleep(EDGE_SAVE_WAIT_SECONDS)

        # Verify HTTPS Browsing remains enabled.
        driver.refresh()
        time_module.sleep(4)

        open_discreet_https_page(
            driver,
            ip,
            username,
            password
        )

        https_verified = get_discreet_checkbox_state(
            driver,
            DISCREET_HTTPS_BROWSING_CHECKBOX_XPATH
        )

        if https_verified is not True:
            raise RuntimeError(
                "HTTPS Browsing did not remain enabled after refresh."
            )

        print(
            f"[OK] Discreet HTTPS Browsing verified for {ip}"
        )

        # ============================================================
        # Step 2: Enable lower plural WebSockets
        # ============================================================
        open_discreet_network_service_page(
            driver,
            ip,
            username,
            password
        )

        websockets_before = get_discreet_checkbox_state(
            driver,
            DISCREET_WEBSOCKETS_CHECKBOX_XPATH
        )

        print(
            f"[DISCREET WEB UI] {ip} lower plural WebSockets "
            f"state before: {websockets_before}"
        )

        websockets_result = run_discreet_checkbox_console_method(
            driver,
            DISCREET_WEBSOCKETS_CHECKBOX_XPATH,
            DISCREET_WEBSOCKETS_SAVE_XPATH,
            "lower plural WebSockets"
        )

        if (
            not isinstance(websockets_result, dict)
            or not websockets_result.get("ok")
        ):
            stage = (
                websockets_result.get("stage", "unknown")
                if isinstance(websockets_result, dict)
                else "unknown"
            )

            detail = (
                websockets_result.get(
                    "detail",
                    str(websockets_result)
                )
                if isinstance(websockets_result, dict)
                else str(websockets_result)
            )

            raise RuntimeError(
                f"WebSockets step failed at {stage}: {detail}"
            )

        print(
            f"[OK] Discreet lower plural WebSockets enabled "
            f"for {ip}; Save clicked."
        )

        add_result(
            results,
            ip,
            "Enable Discreet WebSockets",
            DISCREET_WEBSOCKETS_CHECKBOX_XPATH,
            200,
            "OK",
            (
                f"Before={websockets_result.get('before')}; "
                f"After={websockets_result.get('after')}; "
                "Save clicked; upper singular WebSocket unchanged"
            )
        )

        time_module.sleep(EDGE_SAVE_WAIT_SECONDS)

        # Verify lower plural WebSockets remains enabled.
        driver.refresh()
        time_module.sleep(4)

        open_discreet_network_service_page(
            driver,
            ip,
            username,
            password
        )

        websockets_verified = get_discreet_checkbox_state(
            driver,
            DISCREET_WEBSOCKETS_CHECKBOX_XPATH
        )

        if websockets_verified is not True:
            raise RuntimeError(
                "Lower plural WebSockets did not remain enabled "
                "after refresh."
            )

        print(
            f"[OK] Discreet lower plural WebSockets "
            f"verified for {ip}"
        )

        add_result(
            results,
            ip,
            "Verify Discreet HTTPS and WebSockets",
            DISCREET_CONFIG_PATH,
            200,
            "OK",
            (
                "HTTPS Browsing=True; "
                "lower plural WebSockets=True; "
                "upper singular WebSocket unchanged"
            )
        )

        print(
            "[ACCOUNT SECURITY] Discreet Account Security Settings "
            "deferred to the dedicated pre-User-Management pass."
        )

    except Exception as error:
        print(
            f"[FAILED] Discreet HTTPS/WebSockets UI automation "
            f"failed for {ip}: {error}"
        )

        if driver is not None:
            save_web_ui_debug(
                driver,
                ip,
                "discreet_https_websockets_failure"
            )

        add_result(
            results,
            ip,
            "Enable Discreet HTTPS and WebSockets",
            DISCREET_CONFIG_PATH,
            "",
            "FAILED",
            str(error)
        )

    finally:
        if driver is not None:
            try:
                driver.quit()
            except Exception:
                pass




