def find_visible_dialog_by_title(
    driver,
    title_text,
):
    """
    Return the smallest visible dialog/panel containing the requested title
    and multiple form controls.
    """
    return driver.execute_script(
        """
        const titleText = String(arguments[0] || "")
            .replace(/\\s+/g, " ")
            .trim()
            .toLowerCase();

        function normalize(value) {
            return String(value || "")
                .replace(/\\s+/g, " ")
                .trim()
                .toLowerCase();
        }

        function visible(element) {
            if (!element) return false;

            const style = window.getComputedStyle(element);
            const rect = element.getBoundingClientRect();

            return (
                style.display !== "none" &&
                style.visibility !== "hidden" &&
                Number(style.opacity || "1") !== 0 &&
                rect.width > 0 &&
                rect.height > 0
            );
        }

        const titleElements = Array.from(
            document.querySelectorAll(
                "h1,h2,h3,h4,h5,h6,div,span,strong,p"
            )
        ).filter((element) => (
            visible(element) &&
            normalize(
                element.innerText || element.textContent
            ) === titleText
        ));

        const candidates = [];

        for (const titleElement of titleElements) {
            let current = titleElement;

            for (let level = 0; level < 9 && current; level += 1) {
                const controls = Array.from(
                    current.querySelectorAll(
                        "input,select,button,[role='combobox']"
                    )
                ).filter(visible);

                if (controls.length >= 4 && visible(current)) {
                    const rect = current.getBoundingClientRect();

                    candidates.push({
                        element: current,
                        area: rect.width * rect.height,
                        controls: controls.length
                    });
                }

                current = current.parentElement;
            }
        }

        candidates.sort((a, b) => (
            a.area - b.area ||
            a.controls - b.controls
        ));

        return candidates.length
            ? candidates[0].element
            : null;
        """,
        title_text,
    )


def visible_inputs_in_container(
    driver,
    container,
):
    return driver.execute_script(
        """
        const container = arguments[0];

        function visible(element) {
            if (!element) return false;

            const style = window.getComputedStyle(element);
            const rect = element.getBoundingClientRect();

            return (
                !element.disabled &&
                style.display !== "none" &&
                style.visibility !== "hidden" &&
                Number(style.opacity || "1") !== 0 &&
                rect.width > 0 &&
                rect.height > 0
            );
        }

        return Array.from(
            container.querySelectorAll("input")
        ).filter(visible);
        """,
        container,
    )


def find_visible_button_in_container(
    driver,
    container,
    button_text,
):
    return driver.execute_script(
        """
        const container = arguments[0];
        const buttonText = String(arguments[1] || "")
            .replace(/\\s+/g, " ")
            .trim()
            .toLowerCase();

        function normalize(value) {
            return String(value || "")
                .replace(/\\s+/g, " ")
                .trim()
                .toLowerCase();
        }

        function visible(element) {
            if (!element) return false;

            const style = window.getComputedStyle(element);
            const rect = element.getBoundingClientRect();

            return (
                !element.disabled &&
                style.display !== "none" &&
                style.visibility !== "hidden" &&
                rect.width > 0 &&
                rect.height > 0
            );
        }

        return Array.from(
            container.querySelectorAll(
                "button,input[type='button']," +
                "input[type='submit'],a,[role='button']"
            )
        ).find((element) => (
            visible(element) &&
            normalize(
                element.innerText ||
                element.value ||
                element.textContent
            ) === buttonText
        )) || null;
        """,
        container,
        button_text,
    )


def wait_for_account_security_dialog(
    driver,
):
    return WebDriverWait(
        driver,
        EDGE_UI_WAIT_TIMEOUT,
    ).until(
        lambda current_driver: find_visible_dialog_by_title(
            current_driver,
            ACCOUNT_SECURITY_DIALOG_TITLE,
        )
    )


def validate_account_security_configuration(
    configuration,
):
    if not configuration:
        raise RuntimeError(
            "No Account Security Settings Excel row was found "
            "for this camera type."
        )

    if not configuration.get("enabled"):
        return False

    questions = configuration.get("questions", [])

    if len(questions) != 3:
        raise RuntimeError(
            "Exactly three Account Security questions are required."
        )

    for index, question in enumerate(
        questions,
        start=1,
    ):
        if is_blank(question.get("question")):
            raise RuntimeError(
                f"Security Question {index} is blank in Excel."
            )

        if is_blank(question.get("answer")):
            raise RuntimeError(
                f"Security Answer {index} is blank in Excel."
            )

    return True


def select_dome_question_by_text(
    driver,
    question_control,
    question_text,
    question_number,
):
    """
    Element-UI dropdown used by the newer Dome camera.
    """
    driver.execute_script(
        """
        arguments[0].scrollIntoView({
            block: "center",
            inline: "center"
        });
        """,
        question_control,
    )

    try:
        question_control.click()
    except Exception:
        driver.execute_script(
            "arguments[0].click();",
            question_control,
        )

    time_module.sleep(0.5)

    click_visible_exact_text(
        driver,
        [question_text],
        f"Dome Security Question {question_number}",
        timeout=15,
    )

    time_module.sleep(0.5)



def find_account_security_password_popup_parts(driver):
    """
    Find the actual small Admin Password popup.

    The previous geometry-only method selected the Reserved Email input because
    it searched all visible inputs on the page. This implementation first
    isolates the visible Element-UI popover containing "Admin Password", then
    searches for the input and OK action only inside that same popup.

    It also supports the older NVR/Discreet "Password Confirm" dialog.
    """
    return driver.execute_script(
        """
        function normalize(value) {
            return String(value || "")
                .replace(/\\s+/g, " ")
                .trim()
                .toLowerCase();
        }

        function visible(element) {
            if (!element) return false;

            const style = window.getComputedStyle(element);
            const rect = element.getBoundingClientRect();

            return (
                style.display !== "none" &&
                style.visibility !== "hidden" &&
                Number(style.opacity || "1") !== 0 &&
                rect.width > 0 &&
                rect.height > 0 &&
                rect.bottom > 0 &&
                rect.right > 0 &&
                rect.top < window.innerHeight &&
                rect.left < window.innerWidth
            );
        }

        function rectInfo(element) {
            const rect = element.getBoundingClientRect();

            return {
                x: Math.round(rect.left),
                y: Math.round(rect.top),
                width: Math.round(rect.width),
                height: Math.round(rect.height)
            };
        }

        function exactOkTargets(container) {
            return Array.from(
                container.querySelectorAll(
                    "button,input[type='button'],input[type='submit']," +
                    "a,[role='button'],span,div,p"
                )
            )
                .filter((element) => {
                    if (!visible(element)) return false;

                    const text = normalize(
                        element.innerText ||
                        element.value ||
                        element.textContent
                    );

                    if (text !== "ok") return false;

                    const rect = element.getBoundingClientRect();

                    return (
                        rect.width <= 220 &&
                        rect.height <= 100
                    );
                })
                .map((element) => (
                    element.closest(
                        "button,a,[role='button']," +
                        ".el-button,.ant-btn"
                    ) ||
                    element
                ))
                .filter(visible);
        }

        function candidateFromContainer(container, sourceType) {
            if (!visible(container)) {
                return null;
            }

            const containerText = normalize(
                container.innerText ||
                container.textContent
            );

            if (
                !containerText.includes("admin password") &&
                !containerText.includes("password confirm")
            ) {
                return null;
            }

            const allInputs = Array.from(
                container.querySelectorAll(
                    "input[type='password']," +
                    "input[type='text']," +
                    "input:not([type])"
                )
            ).filter((element) => (
                visible(element) &&
                !element.disabled
            ));

            if (!allInputs.length) {
                return null;
            }

            const passwordInputs = allInputs.filter(
                (element) => (
                    String(element.type || "").toLowerCase()
                    === "password"
                )
            );

            // Prefer a real password input. Otherwise select the narrowest
            // visible text input inside the small popup.
            const input = (
                passwordInputs[0] ||
                allInputs
                    .slice()
                    .sort((first, second) => (
                        first.getBoundingClientRect().width -
                        second.getBoundingClientRect().width
                    ))[0]
            );

            const okTargets = exactOkTargets(container);

            if (!okTargets.length) {
                return null;
            }

            const inputRect = input.getBoundingClientRect();

            const okTarget = okTargets
                .slice()
                .sort((first, second) => {
                    const firstRect =
                        first.getBoundingClientRect();
                    const secondRect =
                        second.getBoundingClientRect();

                    const firstDistance =
                        Math.abs(
                            (
                                firstRect.left +
                                firstRect.width / 2
                            ) -
                            (
                                inputRect.left +
                                inputRect.width / 2
                            )
                        ) +
                        Math.abs(
                            firstRect.top -
                            inputRect.bottom
                        );

                    const secondDistance =
                        Math.abs(
                            (
                                secondRect.left +
                                secondRect.width / 2
                            ) -
                            (
                                inputRect.left +
                                inputRect.width / 2
                            )
                        ) +
                        Math.abs(
                            secondRect.top -
                            inputRect.bottom
                        );

                    return firstDistance - secondDistance;
                })[0];

            const rect = container.getBoundingClientRect();
            const classText = String(
                container.className || ""
            ).toLowerCase();

            let score = rect.width * rect.height;

            if (
                classText.includes("el-popover") ||
                classText.includes("el-popper") ||
                classText.includes("message-box") ||
                classText.includes("dialog")
            ) {
                score -= 1000000;
            }

            if (
                String(input.type || "").toLowerCase()
                === "password"
            ) {
                score -= 500000;
            }

            // Reject large drawer/page containers.
            if (
                rect.width > 650 ||
                rect.height > 450
            ) {
                score += 100000000;
            }

            return {
                popup: container,
                input: input,
                okTarget: okTarget,
                score: score,
                sourceType: sourceType
            };
        }

        const candidates = [];

        // Primary method for the newer Dome interface.
        for (const container of document.querySelectorAll(
            ".el-popover,.el-popper,.ant-popover," +
            ".el-message-box,[role='tooltip'],[role='dialog']"
        )) {
            const candidate = candidateFromContainer(
                container,
                "known_popup"
            );

            if (candidate) {
                candidates.push(candidate);
            }
        }

        // Fallback for old NVR/Discreet interfaces.
        const labels = Array.from(
            document.querySelectorAll(
                "label,span,div,p,strong"
            )
        ).filter((element) => {
            if (!visible(element)) return false;

            const text = normalize(
                element.innerText ||
                element.textContent
            );

            return (
                text === "admin password" ||
                text === "admin password*" ||
                text.startsWith("admin password") ||
                text === "password confirm"
            );
        });

        for (const label of labels) {
            let current = label;

            for (
                let level = 0;
                level < 7 && current;
                level += 1
            ) {
                const rect =
                    current.getBoundingClientRect();

                if (
                    visible(current) &&
                    rect.width <= 650 &&
                    rect.height <= 450
                ) {
                    const candidate =
                        candidateFromContainer(
                            current,
                            "label_parent"
                        );

                    if (candidate) {
                        candidates.push(candidate);
                    }
                }

                current = current.parentElement;
            }
        }

        candidates.sort((first, second) => (
            first.score - second.score
        ));

        if (!candidates.length) {
            return null;
        }

        const selected = candidates[0];

        return {
            popup: selected.popup,
            input: selected.input,
            ok_target: selected.okTarget,
            meta: {
                candidate_count: candidates.length,
                source_type: selected.sourceType,
                popup_rect: rectInfo(selected.popup),
                input_rect: rectInfo(selected.input),
                ok_rect: rectInfo(selected.okTarget),
                popup_class: String(
                    selected.popup.className || ""
                ),
                input_type: String(
                    selected.input.type || ""
                ),
                input_id: String(
                    selected.input.id || ""
                ),
                input_name: String(
                    selected.input.name || ""
                ),
                input_class: String(
                    selected.input.className || ""
                ),
                input_placeholder: String(
                    selected.input.placeholder || ""
                ),
                ok_tag: selected.okTarget.tagName,
                ok_class: String(
                    selected.okTarget.className || ""
                )
            }
        };
        """
    )


def find_account_security_password_dialog(driver):
    """
    Compatibility wrapper.
    """
    parts = find_account_security_password_popup_parts(
        driver
    )

    if not isinstance(parts, dict):
        return None

    return parts.get("popup")


def complete_account_security_password_confirmation(
    driver,
    device_password,
    device_label,
):
    """
    Enter the administrator password into the input located inside the actual
    Admin Password popup, then click the OK action from the same popup using a trusted browser-level mouse event.

    The password is never printed.
    """
    print(
        f"[ACCOUNT SECURITY] Waiting for {device_label} "
        "Admin Password confirmation."
    )

    try:
        parts = WebDriverWait(
            driver,
            15,
        ).until(
            lambda current_driver: (
                find_account_security_password_popup_parts(
                    current_driver
                )
            )
        )
    except Exception:
        raise RuntimeError(
            f"{device_label} Admin Password popup was not found."
        )

    if not isinstance(parts, dict):
        raise RuntimeError(
            f"{device_label} Admin Password popup controls "
            "were not found."
        )

    meta = parts.get("meta") or {}

    print(
        f"[ACCOUNT SECURITY DEBUG] {device_label}: "
        f"source={meta.get('source_type')}; "
        f"popup={meta.get('popup_rect')}; "
        f"input={meta.get('input_rect')}; "
        f"OK={meta.get('ok_rect')}; "
        f"input_type={meta.get('input_type')}; "
        f"input_id={meta.get('input_id')}; "
        f"input_name={meta.get('input_name')}; "
        f"input_class={meta.get('input_class')}; "
        f"popup_class={meta.get('popup_class')}."
    )

    expected_length = len(
        str(device_password)
    )
    last_input_length = None
    last_click_debug = None
    last_popup_text = ""

    for attempt in range(1, 4):
        print(
            f"[ACCOUNT SECURITY] {device_label} password "
            f"confirmation attempt {attempt}/3."
        )

        parts = find_account_security_password_popup_parts(
            driver
        )

        if not isinstance(parts, dict):
            raise RuntimeError(
                f"{device_label} password popup disappeared "
                "before its OK button was submitted."
            )

        password_input = parts.get("input")
        confirm_ok = parts.get("ok_target")

        if password_input is None:
            raise RuntimeError(
                f"{device_label} password input inside popup "
                "was not found."
            )

        if confirm_ok is None:
            raise RuntimeError(
                f"{device_label} OK action inside popup "
                "was not found."
            )

        # Type only into the popup's own input.
        driver.execute_script(
            """
            const input = arguments[0];

            input.scrollIntoView({
                block: "center",
                inline: "center"
            });

            input.focus();
            input.click();
            """,
            password_input,
        )

        password_input.send_keys(
            Keys.CONTROL,
            "a"
        )
        password_input.send_keys(
            Keys.BACKSPACE
        )
        password_input.send_keys(
            str(device_password)
        )

        # Reinforce Vue/Element-UI model events.
        driver.execute_script(
            """
            const input = arguments[0];
            const value = arguments[1];

            if (String(input.value || "") !== String(value)) {
                const descriptor =
                    Object.getOwnPropertyDescriptor(
                        window.HTMLInputElement.prototype,
                        "value"
                    );

                if (descriptor && descriptor.set) {
                    descriptor.set.call(input, value);
                } else {
                    input.value = value;
                }
            }

            input.dispatchEvent(
                new Event("input", {
                    bubbles: true
                })
            );

            input.dispatchEvent(
                new Event("change", {
                    bubbles: true
                })
            );

            input.dispatchEvent(
                new FocusEvent("blur", {
                    bubbles: true
                })
            );
            """,
            password_input,
            str(device_password),
        )

        time_module.sleep(0.5)

        last_input_length = driver.execute_script(
            """
            return String(
                arguments[0].value || ""
            ).length;
            """,
            password_input,
        )

        if last_input_length != expected_length:
            raise RuntimeError(
                f"{device_label} password was not retained in "
                "the popup input. Expected characters="
                f"{expected_length}, actual={last_input_length}."
            )

        # Extra guard: the selected input must still belong to the selected
        # popup after typing.
        belongs_to_popup = driver.execute_script(
            """
            const popup = arguments[0];
            const input = arguments[1];

            return Boolean(
                popup &&
                input &&
                popup.contains(input)
            );
            """,
            parts.get("popup"),
            password_input,
        )

        if not belongs_to_popup:
            raise RuntimeError(
                f"{device_label} selected input does not belong "
                "to the Admin Password popup."
            )

        print(
            f"[ACCOUNT SECURITY] {device_label} popup password "
            f"input contains {last_input_length} characters."
        )

        # Use a real browser-level mouse click. JavaScript-generated click
        # events are untrusted and this firmware ignores them.
        click_target_info = driver.execute_script(
            """
            const target = arguments[0];

            target.scrollIntoView({
                block: "nearest",
                inline: "nearest"
            });

            const requested = (
                target.closest(
                    "button,a,[role='button']," +
                    ".el-button,.ant-btn"
                ) ||
                target
            );

            const rect =
                requested.getBoundingClientRect();

            const x = Math.min(
                window.innerWidth - 2,
                Math.max(
                    1,
                    rect.left + rect.width / 2
                )
            );

            const y = Math.min(
                window.innerHeight - 2,
                Math.max(
                    1,
                    rect.top + rect.height / 2
                )
            );

            const topElement =
                document.elementFromPoint(x, y);

            const actual = (
                topElement?.closest(
                    "button,a,[role='button']," +
                    ".el-button,.ant-btn,.button-wrapper"
                ) ||
                topElement ||
                requested
            );

            const actualRect =
                actual.getBoundingClientRect();

            return {
                requested: requested,
                actual: actual,
                x: Math.min(
                    window.innerWidth - 2,
                    Math.max(
                        1,
                        actualRect.left +
                        actualRect.width / 2
                    )
                ),
                y: Math.min(
                    window.innerHeight - 2,
                    Math.max(
                        1,
                        actualRect.top +
                        actualRect.height / 2
                    )
                ),
                requested_tag:
                    requested.tagName,
                requested_class:
                    String(
                        requested.className || ""
                    ),
                actual_tag:
                    actual.tagName,
                actual_class:
                    String(
                        actual.className || ""
                    ),
                actual_text:
                    String(
                        actual.innerText ||
                        actual.value ||
                        actual.textContent ||
                        ""
                    )
                        .replace(/\\s+/g, " ")
                        .trim()
            };
            """,
            confirm_ok,
        )

        click_x = float(click_target_info["x"])
        click_y = float(click_target_info["y"])
        actual_click_element = click_target_info.get(
            "actual"
        )

        # CDP sends a trusted physical-style click at the exact visible OK.
        driver.execute_cdp_cmd(
            "Input.dispatchMouseEvent",
            {
                "type": "mouseMoved",
                "x": click_x,
                "y": click_y,
                "button": "none",
            },
        )

        driver.execute_cdp_cmd(
            "Input.dispatchMouseEvent",
            {
                "type": "mousePressed",
                "x": click_x,
                "y": click_y,
                "button": "left",
                "clickCount": 1,
            },
        )

        driver.execute_cdp_cmd(
            "Input.dispatchMouseEvent",
            {
                "type": "mouseReleased",
                "x": click_x,
                "y": click_y,
                "button": "left",
                "clickCount": 1,
            },
        )

        last_click_debug = {
            "method": "CDP Input.dispatchMouseEvent",
            "x": round(click_x),
            "y": round(click_y),
            "requested_tag": click_target_info.get(
                "requested_tag"
            ),
            "requested_class": click_target_info.get(
                "requested_class"
            ),
            "actual_tag": click_target_info.get(
                "actual_tag"
            ),
            "actual_class": click_target_info.get(
                "actual_class"
            ),
            "actual_text": click_target_info.get(
                "actual_text"
            ),
        }

        print(
            f"[ACCOUNT SECURITY DEBUG] {device_label} "
            f"trusted popup OK click={last_click_debug}"
        )

        time_module.sleep(1)

        # Fallback 1: WebDriver native click on the exact top-most element.
        # This is still a trusted WebDriver action and does not use
        # ActionChains, so it avoids "move target out of bounds".
        if (
            find_account_security_password_popup_parts(
                driver
            )
            is not None
            and attempt >= 2
            and actual_click_element is not None
        ):
            try:
                actual_click_element.click()

                print(
                    f"[ACCOUNT SECURITY] {device_label} "
                    "native WebDriver OK fallback clicked."
                )

                time_module.sleep(1)

            except Exception as native_click_error:
                print(
                    f"[ACCOUNT SECURITY WARNING] {device_label} "
                    f"native OK fallback failed: "
                    f"{native_click_error}"
                )

        # Fallback 2: submit from the correct password input.
        if (
            find_account_security_password_popup_parts(
                driver
            )
            is not None
            and attempt >= 3
        ):
            try:
                password_input.send_keys(
                    Keys.ENTER
                )

                print(
                    f"[ACCOUNT SECURITY] {device_label} "
                    "password Enter fallback submitted."
                )

                time_module.sleep(1)

            except Exception as enter_error:
                print(
                    f"[ACCOUNT SECURITY WARNING] {device_label} "
                    f"Enter fallback failed: {enter_error}"
                )

        try:
            WebDriverWait(
                driver,
                12,
            ).until(
                lambda current_driver: (
                    find_account_security_password_popup_parts(
                        current_driver
                    )
                    is None
                )
            )

            time_module.sleep(2)

            print(
                f"[ACCOUNT SECURITY] {device_label} "
                "Admin Password confirmation accepted."
            )

            return True

        except Exception:
            current_parts = (
                find_account_security_password_popup_parts(
                    driver
                )
            )

            if isinstance(current_parts, dict):
                current_input = current_parts.get(
                    "input"
                )

                if current_input is not None:
                    last_input_length = (
                        driver.execute_script(
                            """
                            return String(
                                arguments[0].value || ""
                            ).length;
                            """,
                            current_input,
                        )
                    )

                popup = current_parts.get("popup")

                if popup is not None:
                    last_popup_text = (
                        driver.execute_script(
                            """
                            return String(
                                arguments[0].innerText ||
                                arguments[0].textContent ||
                                ""
                            )
                                .replace(/\\s+/g, " ")
                                .trim();
                            """,
                            popup,
                        )
                    )

            if attempt < 3:
                print(
                    f"[ACCOUNT SECURITY WARNING] "
                    f"{device_label} password popup remains. "
                    f"Input characters={last_input_length}. "
                    "Retrying."
                )

                time_module.sleep(1)

    raise RuntimeError(
        f"{device_label} Admin Password popup remained visible "
        "after three attempts. "
        f"Last input characters={last_input_length}; "
        f"last OK click={last_click_debug}; "
        f"popup text={last_popup_text[:300] or 'none'}"
    )



def click_old_ui_menu_item_robust(
    driver,
    label_text,
    step_name,
):
    """
    Click an old Hikvision UI menu item even when the submenu element is
    currently hidden/collapsed.

    It checks visible text first, then hidden text, href, onclick, ng-click,
    ID and class attributes.
    """
    result = driver.execute_script(
        """
        const wanted = String(arguments[0] || "")
            .replace(/\\s+/g, " ")
            .trim()
            .toLowerCase();

        const wantedCompact = wanted.replace(/[^a-z0-9]/g, "");

        function normalize(value) {
            return String(value || "")
                .replace(/\\s+/g, " ")
                .trim()
                .toLowerCase();
        }

        function compact(value) {
            return normalize(value).replace(/[^a-z0-9]/g, "");
        }

        function visible(element) {
            if (!element) return false;

            const style = window.getComputedStyle(element);
            const rect = element.getBoundingClientRect();

            return (
                style.display !== "none" &&
                style.visibility !== "hidden" &&
                Number(style.opacity || "1") !== 0 &&
                rect.width > 0 &&
                rect.height > 0
            );
        }

        const elements = Array.from(
            document.querySelectorAll(
                "a,button,li,div,span,p,label," +
                "[onclick],[ng-click],[href],[role='menuitem']"
            )
        );

        const candidates = [];

        for (const element of elements) {
            const text = normalize(
                element.innerText ||
                element.textContent
            );

            const attributeText = compact([
                element.id,
                element.className,
                element.getAttribute("href"),
                element.getAttribute("onclick"),
                element.getAttribute("ng-click"),
                element.getAttribute("data-menu"),
                element.getAttribute("data-id")
            ].join(" "));

            let score = 999;

            if (text === wanted && visible(element)) {
                score = 0;
            } else if (
                compact(text) === wantedCompact &&
                visible(element)
            ) {
                score = 1;
            } else if (
                text.includes(wanted) &&
                visible(element)
            ) {
                score = 2;
            } else if (
                attributeText.includes(wantedCompact) &&
                visible(element)
            ) {
                score = 3;
            } else if (text === wanted) {
                score = 10;
            } else if (
                compact(text) === wantedCompact
            ) {
                score = 11;
            } else if (
                attributeText.includes(wantedCompact)
            ) {
                score = 12;
            }

            if (score >= 999) {
                continue;
            }

            const target = (
                element.closest(
                    "a,button,li,[onclick],[ng-click]," +
                    "[role='menuitem'],.menu-item,.nav-item"
                ) ||
                element
            );

            const rect = target.getBoundingClientRect();

            candidates.push({
                element: element,
                target: target,
                score: score,
                area: Math.max(
                    1,
                    rect.width * rect.height
                ),
                visible: visible(target),
                text: text
            });
        }

        candidates.sort((a, b) => (
            a.score - b.score ||
            a.area - b.area
        ));

        if (!candidates.length) {
            return {
                clicked: false,
                reason: "not_found"
            };
        }

        const selected = candidates[0];
        const target = selected.target;

        if (selected.visible) {
            target.scrollIntoView({
                block: "center",
                inline: "center"
            });
        }

        for (const eventName of [
            "mouseover",
            "mousedown",
            "mouseup",
            "click"
        ]) {
            target.dispatchEvent(
                new MouseEvent(eventName, {
                    view: window,
                    bubbles: true,
                    cancelable: true,
                    buttons: 1
                })
            );
        }

        try {
            target.click();
        } catch (error) {
            // The dispatched click event may already have triggered it.
        }

        return {
            clicked: true,
            score: selected.score,
            visible: selected.visible,
            text: selected.text,
            targetTag: target.tagName,
            targetId: target.id || "",
            targetClass: String(target.className || "")
        };
        """,
        label_text,
    )

    if not isinstance(result, dict) or not result.get("clicked"):
        raise RuntimeError(
            f"Could not click {step_name}; result={result}"
        )

    print(
        f"[WEB NAV] Robust click {step_name}: "
        f"text={result.get('text')}; "
        f"visible={result.get('visible')}; "
        f"score={result.get('score')}"
    )

    time_module.sleep(2)
    return True


def dismiss_hikvision_success_note(driver, timeout=3.0, label="Hikvision success note"):
    """
    Dismiss a visible success/Note modal that blocks the page underneath.

    This specifically fixes the old NVR/Discreet sequence observed after
    Account Security Settings:

        Note
        Save succeeded.
        [OK]

    The page behind the modal can already be User Management and the Add
    button can be visible, but every trusted click is intercepted by the modal.
    Only clearly-successful messages are dismissed here; error/warning dialogs
    are intentionally left untouched.
    """
    success_phrases = (
        "save succeeded",
        "saved successfully",
        "save successful",
        "operation succeeded",
        "operation successful",
        "successfully saved",
    )

    deadline = time_module.monotonic() + max(0.1, float(timeout))
    dismissed = 0

    def find_in_current_context():
        return driver.execute_script(
            r"""
            const phrases = arguments[0];

            function visible(element) {
                if (!element || !element.isConnected) return false;
                const style = window.getComputedStyle(element);
                const rect = element.getBoundingClientRect();
                return (
                    style.display !== "none" &&
                    style.visibility !== "hidden" &&
                    Number(style.opacity || "1") !== 0 &&
                    rect.width > 0 &&
                    rect.height > 0
                );
            }

            function norm(value) {
                return String(value || "")
                    .replace(/\s+/g, " ")
                    .trim()
                    .toLowerCase();
            }

            const containers = Array.from(document.querySelectorAll(
                "[role='dialog'],.aui_dialog,.ui-dialog,.dialog,.modal,.window," +
                ".layui-layer,.el-message-box,.el-dialog,.popup,.popbox,body > div"
            )).filter(visible);

            const matches = [];

            for (const container of containers) {
                const text = norm(container.innerText || container.textContent || "");
                if (!text) continue;

                const isSuccess = phrases.some((phrase) => text.includes(phrase));
                if (!isSuccess) continue;

                // Never auto-dismiss a dialog that also looks like an error.
                if (
                    text.includes("failed") ||
                    text.includes("error") ||
                    text.includes("invalid") ||
                    text.includes("warning")
                ) {
                    continue;
                }

                const actions = Array.from(container.querySelectorAll(
                    "button,input[type='button'],input[type='submit'],a,[role='button']," +
                    ".btn,.button,.el-button"
                )).filter(visible);

                const ok = actions.find((element) => {
                    const value = norm(
                        element.innerText || element.value || element.textContent || ""
                    );
                    return value === "ok" || value === "confirm" || value === "close";
                });

                if (!ok) continue;

                const rect = container.getBoundingClientRect();
                matches.push({
                    container: container,
                    button: ok,
                    text: text,
                    area: rect.width * rect.height,
                });
            }

            if (!matches.length) return null;
            matches.sort((a, b) => a.area - b.area);
            return matches[0];
            """,
            list(success_phrases),
        )

    while time_module.monotonic() < deadline:
        try:
            driver.switch_to.default_content()
        except Exception:
            pass

        found = None
        found_frame_path = []

        def search_frames(depth=0, path=None, max_depth=5):
            nonlocal found, found_frame_path
            if path is None:
                path = []

            try:
                candidate = find_in_current_context()
            except Exception:
                candidate = None

            if candidate:
                found = candidate
                found_frame_path = list(path)
                return True

            if depth >= max_depth:
                return False

            try:
                frames = driver.find_elements(By.CSS_SELECTOR, "iframe,frame")
            except Exception:
                frames = []

            for index in range(len(frames)):
                try:
                    current = driver.find_elements(By.CSS_SELECTOR, "iframe,frame")
                    if index >= len(current):
                        continue
                    driver.switch_to.frame(current[index])
                except Exception:
                    continue

                if search_frames(depth + 1, path + [index], max_depth):
                    return True

                try:
                    driver.switch_to.parent_frame()
                except Exception:
                    try:
                        driver.switch_to.default_content()
                    except Exception:
                        pass

            return False

        search_frames()

        if not found:
            try:
                driver.switch_to.default_content()
            except Exception:
                pass
            break

        button = found.get("button") if isinstance(found, dict) else None
        text = str(found.get("text", "")) if isinstance(found, dict) else ""

        if button is None:
            break

        clicked = False

        try:
            button.click()
            clicked = True
        except Exception:
            pass

        if not clicked:
            try:
                coords = driver.execute_script(
                    """
                    const r = arguments[0].getBoundingClientRect();
                    return {x:r.left+r.width/2, y:r.top+r.height/2};
                    """,
                    button,
                )
                x = float(coords["x"])
                y = float(coords["y"])
                driver.execute_cdp_cmd("Input.dispatchMouseEvent", {
                    "type": "mouseMoved", "x": x, "y": y, "button": "none"
                })
                driver.execute_cdp_cmd("Input.dispatchMouseEvent", {
                    "type": "mousePressed", "x": x, "y": y,
                    "button": "left", "clickCount": 1
                })
                driver.execute_cdp_cmd("Input.dispatchMouseEvent", {
                    "type": "mouseReleased", "x": x, "y": y,
                    "button": "left", "clickCount": 1
                })
                clicked = True
            except Exception:
                pass

        if not clicked:
            try:
                driver.execute_script("arguments[0].click();", button)
                clicked = True
            except Exception:
                pass

        if not clicked:
            break

        dismissed += 1
        print(
            f"[USER MANAGEMENT MODAL] {label}: dismissed blocking success "
            f"dialog: {text[:160]}"
        )
        time_module.sleep(0.35)

    try:
        driver.switch_to.default_content()
    except Exception:
        pass

    return dismissed



def visible_hikvision_blocking_dialogs(driver, max_depth=6):
    """Return short visible modal/drawer texts across top document and frames.

    v115 includes ``.el-drawer`` because Dome Add User is commonly rendered as
    an Element-UI drawer rather than ``.el-dialog``.  The older diagnostic only
    inspected the top document, which is why a genuinely-open Add User drawer
    could still produce ``Last detail: Message:`` with no visibleBlockingDialogs.
    No input values are read or logged.
    """
    try:
        driver.switch_to.default_content()
    except Exception:
        pass

    script = r"""
        function visible(element) {
            if (!element || !element.isConnected) return false;
            let current = element;
            while (current && current !== document.documentElement) {
                const style = window.getComputedStyle(current);
                if (
                    style.display === 'none' ||
                    style.visibility === 'hidden' ||
                    Number(style.opacity || '1') === 0 ||
                    current.getAttribute('aria-hidden') === 'true'
                ) return false;
                current = current.parentElement;
            }
            const rect = element.getBoundingClientRect();
            return rect.width > 0 && rect.height > 0;
        }
        const selectors = [
            "[role='dialog']", ".aui_dialog", ".ui-dialog", ".dialog",
            ".modal", ".modal-dialog", ".window", ".layui-layer",
            ".el-message-box", ".el-dialog", ".el-drawer", ".popup", ".popbox"
        ];
        const result = [];
        for (const node of Array.from(document.querySelectorAll(selectors.join(',')))) {
            if (!visible(node)) continue;
            let text = String(node.innerText || node.textContent || '')
                .replace(/\s+/g, ' ').trim();
            if (!text) continue;
            if (text.length > 240) text = text.slice(0, 240);
            if (!result.includes(text)) result.push(text);
        }
        return result.slice(0, 8);
    """

    collected = []

    def search(depth):
        try:
            items = driver.execute_script(script) or []
        except Exception:
            items = []
        for item in items:
            item = str(item or '').strip()
            if item and item not in collected:
                collected.append(item)
                if len(collected) >= 8:
                    return
        if depth >= max_depth or len(collected) >= 8:
            return
        try:
            frames = driver.find_elements(By.CSS_SELECTOR, 'iframe,frame')
        except Exception:
            frames = []
        for index in range(len(frames)):
            try:
                current = driver.find_elements(By.CSS_SELECTOR, 'iframe,frame')
                if index >= len(current):
                    continue
                driver.switch_to.frame(current[index])
                search(depth + 1)
            except Exception:
                pass
            finally:
                try:
                    driver.switch_to.parent_frame()
                except Exception:
                    try:
                        driver.switch_to.default_content()
                    except Exception:
                        pass
            if len(collected) >= 8:
                break

    search(0)
    try:
        driver.switch_to.default_content()
    except Exception:
        pass
    return collected[:8]

def old_ui_user_management_ready(driver):
    """
    Strictly confirm that the old NVR/Discreet User Management content page
    has loaded.

    The previous check produced a false positive on System Settings because
    the left navigation already contained the words "User Management" and the
    top-right login name contained "admin".
    """
    try:
        return bool(
            driver.execute_script(
                """
                function normalize(value) {
                    return String(value || "")
                        .replace(/\\s+/g, " ")
                        .trim()
                        .toLowerCase();
                }

                function visible(element) {
                    if (!element) return false;

                    const style = window.getComputedStyle(element);
                    const rect = element.getBoundingClientRect();

                    return (
                        style.display !== "none" &&
                        style.visibility !== "hidden" &&
                        Number(style.opacity || "1") !== 0 &&
                        rect.width > 0 &&
                        rect.height > 0
                    );
                }

                const visibleElements = Array.from(
                    document.querySelectorAll(
                        "h1,h2,h3,h4,div,span,p,td,th"
                    )
                ).filter(visible);

                const texts = visibleElements.map((element) =>
                    normalize(element.innerText || element.textContent)
                );

                const hasUserList = texts.some(
                    (text) => text === "user list"
                );

                const hasUserNameHeader = texts.some(
                    (text) => text === "user name" || text === "username"
                );

                const hasLevelHeader = texts.some(
                    (text) => text === "level" || text === "user type"
                );

                const hasNumberHeader = texts.some(
                    (text) => text === "no." || text === "no"
                );

                // Require real content-table markers. Left-menu text alone is
                // not sufficient.
                return (
                    hasUserList &&
                    hasUserNameHeader &&
                    hasLevelHeader &&
                    hasNumberHeader
                );
                """
            )
        )
    except Exception:
        return False


def find_old_ui_user_management_menu(driver):
    """
    Locate the visible User Management item in the left System submenu.
    Prefer controls positioned in the left navigation area.
    """
    return driver.execute_script(
        """
        function normalize(value) {
            return String(value || "")
                .replace(/\\s+/g, " ")
                .trim()
                .toLowerCase();
        }

        function visible(element) {
            if (!element) return false;

            const style = window.getComputedStyle(element);
            const rect = element.getBoundingClientRect();

            return (
                style.display !== "none" &&
                style.visibility !== "hidden" &&
                Number(style.opacity || "1") !== 0 &&
                rect.width > 0 &&
                rect.height > 0
            );
        }

        const candidates = [];

        for (const element of document.querySelectorAll(
            "a,button,li,div,span,p,[onclick],[ng-click],[role='menuitem']"
        )) {
            const text = normalize(
                element.innerText || element.textContent
            );

            if (text !== "user management") {
                continue;
            }

            const target = (
                element.closest(
                    "a,button,li,[onclick],[ng-click],[role='menuitem']"
                ) || element
            );

            const rect = target.getBoundingClientRect();
            const isVisible = visible(target);

            let score = 1000;

            if (isVisible) score -= 500;
            if (rect.left < 350) score -= 300;
            if (rect.width > 40 && rect.height > 18) score -= 100;

            candidates.push({
                element: target,
                score: score,
                visible: isVisible,
                x: Math.round(rect.left),
                y: Math.round(rect.top),
                width: Math.round(rect.width),
                height: Math.round(rect.height),
                tag: target.tagName,
                className: String(target.className || "")
            });
        }

        candidates.sort((a, b) => a.score - b.score);

        if (!candidates.length) {
            return null;
        }

        const selected = candidates[0];

        return {
            element: selected.element,
            meta: {
                score: selected.score,
                visible: selected.visible,
                x: selected.x,
                y: selected.y,
                width: selected.width,
                height: selected.height,
                tag: selected.tag,
                class_name: selected.className
            }
        };
        """
    )


def click_old_ui_user_management_menu(driver, device_label):
    parts = WebDriverWait(driver, 12).until(
        lambda current_driver: find_old_ui_user_management_menu(
            current_driver
        )
    )

    if not isinstance(parts, dict):
        raise RuntimeError(
            f"{device_label} User Management menu item was not found."
        )

    element = parts.get("element")
    meta = parts.get("meta") or {}

    if element is None:
        raise RuntimeError(
            f"{device_label} User Management element was not found."
        )

    print(
        f"[WEB NAV DEBUG] {device_label} User Management menu: "
        f"visible={meta.get('visible')}; x={meta.get('x')}; "
        f"y={meta.get('y')}; size={meta.get('width')}x"
        f"{meta.get('height')}; tag={meta.get('tag')}."
    )

    try:
        element.click()
        print(
            f"[WEB NAV] Clicked {device_label} User Management "
            "using native click."
        )
    except Exception as native_error:
        print(
            f"[WEB NAV WARNING] {device_label} native User Management "
            f"click failed: {native_error}"
        )

        coordinates = driver.execute_script(
            """
            const element = arguments[0];
            element.scrollIntoView({block: "center", inline: "center"});
            const rect = element.getBoundingClientRect();
            return {
                x: rect.left + rect.width / 2,
                y: rect.top + rect.height / 2
            };
            """,
            element,
        )

        click_x = float(coordinates["x"])
        click_y = float(coordinates["y"])

        for event_type, button_name in [
            ("mouseMoved", "none"),
            ("mousePressed", "left"),
            ("mouseReleased", "left"),
        ]:
            payload = {
                "type": event_type,
                "x": click_x,
                "y": click_y,
                "button": button_name,
            }

            if event_type != "mouseMoved":
                payload["clickCount"] = 1

            driver.execute_cdp_cmd(
                "Input.dispatchMouseEvent",
                payload,
            )

        print(
            f"[WEB NAV] Clicked {device_label} User Management "
            "using trusted CDP click."
        )


def open_old_ui_user_management_page(
    driver,
    row,
    device_label,
):
    """
    Open System > User Management on old NVR/Discreet UI and verify the actual
    User List table, not merely visible menu text.
    """
    ip = get_value(row, "Current IP", "current_ip")
    username = get_value(row, "Username", "username")
    password = get_value(row, "Password", "password")

    driver.switch_to.default_content()

    open_discreet_configuration_page(
        driver,
        ip,
        username,
        password,
    )

    # Account Security on this old Hikvision UI leaves a blocking
    # "Note / Save succeeded. / OK" modal in the SAME browser session.
    # The User List and Add button are visible behind it, but trusted clicks
    # are intercepted until OK is dismissed.
    dismiss_hikvision_success_note(
        driver,
        timeout=1.5,
        label=f"{device_label} pre-User-Management",
    )

    if old_ui_user_management_ready(driver):
        print(
            f"[ACCOUNT SECURITY] {device_label}: already on "
            "User Management content page."
        )
        return True

    print(
        f"[ACCOUNT SECURITY] {device_label}: opening "
        "System > User Management."
    )

    # Expand System when User Management is missing OR only exists as a
    # hidden DOM item. This is required after leaving Network Service.
    try:
        parts = find_old_ui_user_management_menu(driver)
        menu_meta = (
            parts.get("meta", {})
            if isinstance(parts, dict)
            else {}
        )
        user_management_visible = bool(
            menu_meta.get("visible")
        )

        if not user_management_visible:
            print(
                f"[WEB NAV] {device_label} System submenu is "
                "collapsed; expanding System."
            )

            try:
                click_visible_exact_text(
                    driver,
                    ["System"],
                    f"{device_label} System",
                    timeout=10,
                )
            except Exception:
                click_old_ui_menu_item_robust(
                    driver,
                    "System",
                    f"{device_label} System",
                )

            # Do not continue until the visible User Management menu exists.
            WebDriverWait(driver, 12).until(
                lambda current_driver: (
                    isinstance(
                        find_old_ui_user_management_menu(
                            current_driver
                        ),
                        dict,
                    )
                    and bool(
                        find_old_ui_user_management_menu(
                            current_driver
                        )
                        .get("meta", {})
                        .get("visible")
                    )
                )
            )

            print(
                f"[WEB NAV] {device_label} System submenu expanded; "
                "User Management is visible."
            )

            time_module.sleep(1)

    except Exception as expand_error:
        save_web_ui_debug(
            driver,
            ip,
            f"{device_label.lower()}_system_menu_expand_failure",
        )

        raise RuntimeError(
            f"{device_label} could not expand System before "
            f"opening User Management: {expand_error}"
        )

    for attempt in range(1, 4):
        print(
            f"[WEB NAV] {device_label} User Management navigation "
            f"attempt {attempt}/3."
        )

        click_old_ui_user_management_menu(
            driver,
            device_label,
        )

        try:
            WebDriverWait(driver, 15).until(
                lambda current_driver: old_ui_user_management_ready(
                    current_driver
                )
            )

            dismiss_hikvision_success_note(
                driver,
                timeout=1.5,
                label=f"{device_label} User Management ready",
            )

            print(
                f"[ACCOUNT SECURITY] {device_label} User Management "
                "content page ready and blocking success modal cleared."
            )
            return True

        except Exception:
            if attempt < 3:
                print(
                    f"[WEB NAV WARNING] {device_label} User Management "
                    "table not ready; retrying."
                )
                time_module.sleep(2)
                continue

    save_web_ui_debug(
        driver,
        ip,
        f"{device_label.lower()}_user_management_navigation_failure",
    )

    raise RuntimeError(
        f"{device_label} could not open the User Management table from "
        f"{driver.current_url}"
    )


def find_old_ui_account_security_form_in_current_context(driver):
    """
    Return the Account Security form root in the current browsing context when
    it contains at least three question selects and three answer inputs.
    """
    return driver.execute_script(
        """
        function visible(element) {
            if (!element) return false;
            const style = window.getComputedStyle(element);
            const rect = element.getBoundingClientRect();
            return (
                !element.disabled &&
                style.display !== "none" &&
                style.visibility !== "hidden" &&
                rect.width > 0 &&
                rect.height > 0
            );
        }

        const selects = Array.from(
            document.querySelectorAll("select")
        ).filter(visible);

        const inputs = Array.from(
            document.querySelectorAll("input")
        ).filter((element) => {
            const type = String(element.type || "text").toLowerCase();
            return (
                visible(element) &&
                !["hidden", "button", "submit", "checkbox", "radio"]
                    .includes(type)
            );
        });

        if (selects.length < 3 || inputs.length < 3) {
            return null;
        }

        const bodyText = String(
            document.body?.innerText || document.body?.textContent || ""
        ).toLowerCase();

        if (
            !bodyText.includes("security question") &&
            !bodyText.includes("account security")
        ) {
            return null;
        }

        return document.body;
        """
    )


def switch_to_old_ui_account_security_form(driver):
    """
    Locate the old NVR/Discreet Account Security form.

    NVR firmware loads /doc/page/config/system/dialog/securityQA.asp inside an
    iframe. Selenium must switch into that iframe before selecting questions
    and entering answers.
    """
    driver.switch_to.default_content()

    direct_form = find_old_ui_account_security_form_in_current_context(
        driver
    )

    if direct_form is not None:
        return {
            "dialog": direct_form,
            "in_iframe": False,
            "frame_src": "",
        }

    frames = driver.find_elements(By.TAG_NAME, "iframe")

    # Prefer the known securityQA dialog frame.
    ordered_frames = sorted(
        frames,
        key=lambda frame: (
            0
            if "securityqa" in str(frame.get_attribute("src") or "").lower()
            else 1
        ),
    )

    for frame in ordered_frames:
        try:
            if not frame.is_displayed():
                continue

            frame_src = str(frame.get_attribute("src") or "")
            frame_name = str(frame.get_attribute("name") or "")
            frame_id = str(frame.get_attribute("id") or "")

            driver.switch_to.default_content()
            driver.switch_to.frame(frame)

            form = find_old_ui_account_security_form_in_current_context(
                driver
            )

            if form is not None:
                print(
                    "[ACCOUNT SECURITY] Switched into old-UI security "
                    f"question iframe: src={frame_src}; name={frame_name}; "
                    f"id={frame_id}."
                )

                return {
                    "dialog": form,
                    "in_iframe": True,
                    "frame_src": frame_src,
                }

        except Exception:
            pass
        finally:
            # Leave the successful frame selected. Otherwise reset.
            try:
                if find_old_ui_account_security_form_in_current_context(
                    driver
                ) is None:
                    driver.switch_to.default_content()
            except Exception:
                driver.switch_to.default_content()

    driver.switch_to.default_content()
    return None


def find_old_ui_account_security_button(driver):
    """
    Locate the old NVR/Discreet Account Security Settings toolbar button.

    Supported appearances include full text and truncated text such as
    "Account S...".
    """
    return driver.execute_script(
        """
        function normalize(value) {
            return String(value || "")
                .replace(/\\s+/g, " ")
                .trim()
                .toLowerCase();
        }

        function compact(value) {
            return normalize(value)
                .replace(/[^a-z0-9]/g, "");
        }

        function visible(element) {
            if (!element) return false;

            const style =
                window.getComputedStyle(element);
            const rect =
                element.getBoundingClientRect();

            return (
                !element.disabled &&
                style.display !== "none" &&
                style.visibility !== "hidden" &&
                Number(style.opacity || "1") !== 0 &&
                rect.width > 0 &&
                rect.height > 0
            );
        }

        const elements = Array.from(
            document.querySelectorAll(
                "button,input[type='button']," +
                "input[type='submit'],a,[role='button']," +
                "[onclick],[ng-click]"
            )
        ).filter(visible);

        const candidates = [];

        for (const element of elements) {
            const text = normalize(
                element.innerText ||
                element.value ||
                element.textContent
            );

            const attributeText = compact([
                element.title,
                element.getAttribute("aria-label"),
                element.getAttribute("onclick"),
                element.getAttribute("ng-click"),
                element.getAttribute("href"),
                element.id,
                element.className
            ].join(" "));

            let score = 999;

            if (text === "account security settings") {
                score = 0;
            } else if (
                text.startsWith("account security")
            ) {
                score = 1;
            } else if (
                text === "account s..." ||
                text === "account s…" ||
                text === "account s"
            ) {
                score = 2;
            } else if (
                text.startsWith("account s")
            ) {
                score = 3;
            } else if (
                attributeText.includes(
                    "accountsecurity"
                )
            ) {
                score = 4;
            } else if (
                attributeText.includes("securityqa")
            ) {
                score = 5;
            } else if (
                attributeText.includes(
                    "questionconfiguration"
                )
            ) {
                score = 6;
            }

            if (score >= 999) {
                continue;
            }

            const target = (
                element.closest(
                    "button,a,[role='button']," +
                    "input[type='button']," +
                    "input[type='submit']"
                ) ||
                element
            );

            const rect =
                target.getBoundingClientRect();

            candidates.push({
                element: target,
                score: score,
                area:
                    Math.max(1, rect.width * rect.height),
                text: text,
                tag: target.tagName,
                className:
                    String(target.className || ""),
                value:
                    String(target.value || ""),
                title:
                    String(target.title || "")
            });
        }

        candidates.sort((first, second) => (
            first.score - second.score ||
            first.area - second.area
        ));

        if (!candidates.length) {
            return null;
        }

        const selected = candidates[0];

        return {
            element: selected.element,
            meta: {
                score: selected.score,
                text: selected.text,
                tag: selected.tag,
                class_name:
                    selected.className,
                value:
                    selected.value,
                title:
                    selected.title
            }
        };
        """
    )


def click_old_ui_account_security_settings(
    driver,
    device_label,
):
    """
    Click Account Security Settings and switch into its form iframe when used
    by the NVR firmware.
    """
    driver.switch_to.default_content()

    parts = WebDriverWait(driver, 15).until(
        lambda current_driver: find_old_ui_account_security_button(
            current_driver
        )
    )

    if not isinstance(parts, dict):
        raise RuntimeError(
            f"{device_label} Account Security Settings button was not found."
        )

    button = parts.get("element")
    meta = parts.get("meta") or {}

    if button is None:
        raise RuntimeError(
            f"{device_label} Account Security Settings button element "
            "was not found."
        )

    print(
        f"[ACCOUNT SECURITY DEBUG] {device_label} button detected: "
        f"text={meta.get('text')}; value={meta.get('value')}; "
        f"title={meta.get('title')}; tag={meta.get('tag')}; "
        f"score={meta.get('score')}."
    )

    try:
        button.click()
        print(
            f"[WEB NAV] Clicked {device_label} Account Security "
            "Settings using native click."
        )
    except Exception as native_error:
        print(
            f"[ACCOUNT SECURITY WARNING] {device_label} native Account "
            f"Security click failed: {native_error}"
        )

        coordinates = driver.execute_script(
            """
            const element = arguments[0];
            element.scrollIntoView({block: "center", inline: "center"});
            const rect = element.getBoundingClientRect();
            return {
                x: rect.left + rect.width / 2,
                y: rect.top + rect.height / 2
            };
            """,
            button,
        )

        click_x = float(coordinates["x"])
        click_y = float(coordinates["y"])

        for event_type, button_name in [
            ("mouseMoved", "none"),
            ("mousePressed", "left"),
            ("mouseReleased", "left"),
        ]:
            payload = {
                "type": event_type,
                "x": click_x,
                "y": click_y,
                "button": button_name,
            }

            if event_type != "mouseMoved":
                payload["clickCount"] = 1

            driver.execute_cdp_cmd(
                "Input.dispatchMouseEvent",
                payload,
            )

        print(
            f"[WEB NAV] Clicked {device_label} Account Security "
            "Settings using trusted CDP click."
        )

    context = WebDriverWait(driver, 20).until(
        lambda current_driver: switch_to_old_ui_account_security_form(
            current_driver
        )
    )

    if not isinstance(context, dict):
        raise RuntimeError(
            f"{device_label} Account Security Settings form did not open."
        )

    print(
        f"[ACCOUNT SECURITY] {device_label} Account Security Settings "
        f"form ready; iframe={context.get('in_iframe')}."
    )

    return context



def configure_dome_account_security_in_driver(
    driver,
    row,
    configuration,
    results,
):
    """
    Dome Account Security navigation.

    This intentionally restores the proven pre-v17 navigation sequence:
      1. Start from the normal /doc/index.html page.
      2. After login, set the SPA hash to User Management.
      3. Wait for Account Security Settings.
      4. If the hash route does not load, use the original visible
         Configuration -> System -> User Management menu sequence.

    Fresh-browser retry is handled by
    configure_device_account_security_settings_via_ui().
    """
    ip = get_value(
        row,
        "Current IP",
        "current_ip",
    )

    task = "Configure Dome Account Security Settings"

    if not validate_account_security_configuration(
        configuration
    ):
        print(
            f"[SKIP] {ip} Dome Account Security Settings disabled "
            "in Excel."
        )

        add_result(
            results,
            ip,
            task,
            ACCOUNT_SECURITY_SETTINGS_SHEET,
            "",
            "SKIPPED",
            "Enabled=No",
        )

        return True

    target_hash = "#/config/system/user/userManagement"

    print(
        "[ACCOUNT SECURITY] Dome: opening "
        "System > User Management using the proven navigation flow."
    )

    # -----------------------------------------------------------------
    # Proven route used by the earlier version.
    # -----------------------------------------------------------------
    driver.execute_script(
        """
        const targetHash = arguments[0];

        if (window.location.hash !== targetHash) {
            window.location.hash = targetHash;

            try {
                window.dispatchEvent(
                    new HashChangeEvent("hashchange")
                );
            } catch (error) {
                window.dispatchEvent(
                    new Event("hashchange")
                );
            }
        }
        """,
        target_hash,
    )

    time_module.sleep(
        4
    )

    page_ready = wait_for_visible_text(
        driver,
        "Account Security Settings",
        timeout=15,
    )

    # -----------------------------------------------------------------
    # Original menu fallback. This is the method that previously allowed
    # most Dome cameras to complete successfully.
    # -----------------------------------------------------------------
    if not page_ready:
        print(
            "[ACCOUNT SECURITY] Dome direct route did not load. "
            "Restoring original visible navigation: "
            "Configuration -> System -> User Management."
        )

        click_visible_exact_text(
            driver,
            ["Configuration"],
            "Dome Configuration",
            timeout=20,
        )

        time_module.sleep(
            2
        )

        click_visible_exact_text(
            driver,
            ["System"],
            "Dome System",
            timeout=20,
        )

        time_module.sleep(
            2
        )

        click_visible_exact_text(
            driver,
            ["User Management"],
            "Dome User Management",
            timeout=20,
        )

        time_module.sleep(
            3
        )

        page_ready = wait_for_visible_text(
            driver,
            "Account Security Settings",
            timeout=15,
        )

    if not page_ready:
        raise RuntimeError(
            "Dome User Management page did not become ready after "
            "the proven hash-route + Configuration/System/User Management "
            "fallback sequence."
        )

    # Click Account Security Settings only after the User Management page
    # has definitely loaded.
    click_visible_exact_text(
        driver,
        ["Account Security Settings"],
        "Dome Account Security Settings",
        timeout=20,
    )

    dialog = wait_for_account_security_dialog(
        driver
    )

    # Three Element-UI question selectors.
    question_controls = driver.execute_script(
        """
        const dialog = arguments[0];

        function visible(element) {
            if (!element) return false;

            const style = window.getComputedStyle(element);
            const rect = element.getBoundingClientRect();

            return (
                !element.disabled &&
                style.display !== "none" &&
                style.visibility !== "hidden" &&
                rect.width > 0 &&
                rect.height > 0
            );
        }

        const controls = [];

        for (const selectBox of dialog.querySelectorAll(".el-select")) {
            const input = selectBox.querySelector(
                "input,[role='combobox']"
            );

            if (input && visible(input)) {
                controls.push(input);
            }
        }

        if (controls.length < 3) {
            for (const element of dialog.querySelectorAll(
                "input[readonly],[role='combobox']"
            )) {
                if (
                    visible(element) &&
                    !controls.includes(element)
                ) {
                    controls.push(element);
                }
            }
        }

        return controls.slice(0, 3);
        """,
        dialog,
    )

    if len(question_controls) < 3:
        raise RuntimeError(
            "Dome security-question dropdowns were not found."
        )

    for index, question in enumerate(
        configuration["questions"],
        start=1,
    ):
        select_dome_question_by_text(
            driver,
            question_controls[index - 1],
            question["question"],
            index,
        )

    # Visible editable inputs excluding the three read-only question controls.
    editable_inputs = driver.execute_script(
        """
        const dialog = arguments[0];

        function visible(element) {
            if (!element) return false;

            const style = window.getComputedStyle(element);
            const rect = element.getBoundingClientRect();

            return (
                !element.disabled &&
                !element.readOnly &&
                style.display !== "none" &&
                style.visibility !== "hidden" &&
                rect.width > 0 &&
                rect.height > 0
            );
        }

        return Array.from(
            dialog.querySelectorAll("input")
        ).filter((element) => {
            const type = String(element.type || "text")
                .toLowerCase();

            return (
                visible(element) &&
                ![
                    "hidden",
                    "button",
                    "submit",
                    "checkbox",
                    "radio"
                ].includes(type)
            );
        });
        """,
        dialog,
    )

    if len(editable_inputs) < 3:
        raise RuntimeError(
            "Dome security-answer input boxes were not found."
        )

    for index, question in enumerate(
        configuration["questions"],
        start=1,
    ):
        set_web_input(
            driver,
            editable_inputs[index - 1],
            question["answer"],
            field_name=f"Dome security answer {index}",
        )

    reserved_email = configuration.get(
        "reserved_email",
        "",
    )

    if (
        len(editable_inputs) >= 4
        and not is_blank(
            reserved_email
        )
    ):
        set_web_input(
            driver,
            editable_inputs[3],
            reserved_email,
            field_name="Dome reserved email",
        )

    ok_button = find_visible_button_in_container(
        driver,
        dialog,
        "OK",
    )

    if ok_button is None:
        raise RuntimeError(
            "Dome Account Security Settings OK button was not found."
        )

    try:
        ok_button.click()
    except Exception:
        driver.execute_script(
            "arguments[0].click();",
            ok_button,
        )

    print(
        "[ACCOUNT SECURITY] Dome main OK clicked; "
        "waiting for Admin Password confirmation."
    )

    complete_account_security_password_confirmation(
        driver,
        get_value(
            row,
            "Password",
            "password",
        ),
        "Dome",
    )

    dismissed_success_notes = dismiss_hikvision_success_note(
        driver,
        timeout=4.0,
        label="Dome Account Security save",
    )

    time_module.sleep(0.5)

    print(
        f"[OK] Dome Account Security Settings saved for {ip}; "
        f"successModalDismissed={dismissed_success_notes}"
    )

    add_result(
        results,
        ip,
        task,
        "/ISAPI/Security/questionConfiguration",
        200,
        "OK",
        (
            "Questions/answers pulled from Excel; "
            "encrypted request generated by camera web UI; "
            "Admin Password confirmed; answers not logged"
        ),
    )

    return True




def normalize_security_question_text(value):
    return (
        str(value or "")
        .replace("’", "'")
        .replace("‘", "'")
        .replace("“", '"')
        .replace("”", '"')
        .strip()
        .lower()
    )


def select_old_ui_security_question(
    select_element,
    question,
    device_label,
    question_number,
):
    """
    Select an old-UI Hikvision security question.

    Priority:
      1. Question ID from Excel, matching the native option value.
      2. Exact visible question text.
      3. Normalised visible question text.

    Using the ID first avoids failures when the displayed question is
    truncated in the browser or punctuation differs slightly by firmware.
    """
    selector = Select(select_element)

    question_id = str(
        question.get("id", "")
    ).strip()

    question_text = str(
        question.get("question", "")
    ).strip()

    if question_id:
        try:
            selector.select_by_value(question_id)

            print(
                f"[ACCOUNT SECURITY] {device_label} "
                f"Question {question_number} selected by ID "
                f"{question_id}"
            )
            return
        except Exception:
            pass

        for option in selector.options:
            option_value = str(
                option.get_attribute("value") or ""
            ).strip()

            option_id = str(
                option.get_attribute("data-id") or ""
            ).strip()

            if question_id in [
                option_value,
                option_id,
            ]:
                option.click()

                print(
                    f"[ACCOUNT SECURITY] {device_label} "
                    f"Question {question_number} selected by "
                    f"option ID {question_id}"
                )
                return

    if question_text:
        try:
            selector.select_by_visible_text(
                question_text
            )

            print(
                f"[ACCOUNT SECURITY] {device_label} "
                f"Question {question_number} selected by text"
            )
            return
        except Exception:
            pass

        wanted = normalize_security_question_text(
            question_text
        )

        for option in selector.options:
            option_text = normalize_security_question_text(
                option.text
            )

            if option_text == wanted:
                option.click()

                print(
                    f"[ACCOUNT SECURITY] {device_label} "
                    f"Question {question_number} selected by "
                    "normalised text"
                )
                return

    available = [
        (
            str(option.get_attribute("value") or ""),
            option.text,
        )
        for option in selector.options
    ]

    raise RuntimeError(
        f"{device_label} Security Question "
        f"{question_number} could not be selected. "
        f"Requested ID={question_id}; "
        f"requested text={question_text}; "
        f"available options={available}"
    )



# =============================================================================
# USER MANAGEMENT CREATION / PASSWORD ROTATION
# =============================================================================

def user_management_device_kind(row):
    source_sheet = get_value(row, "Source Sheet")

    if source_sheet == "NVR_Settings":
        return "NVR"

    if source_sheet == "Dome_Settings":
        return "DOME"

    return "DISCREET"



def handle_forced_password_change_note(
    driver,
    timeout=8,
):
    """
    Handle the old Hikvision first-login modal:

        Note
        Please change your login password.
        [OK]

    This modal appears after MM/ME successfully authenticate with the Testing
    password. Until OK is clicked it blocks all navigation, which is why the
    previous script appeared stuck on the login page.

    Returns True when the modal was found and dismissed.
    """
    deadline = (
        time_module.monotonic()
        + max(0, float(timeout))
    )

    while time_module.monotonic() < deadline:
        result = driver.execute_script(
            r"""
            function visible(element) {
                if (!element) return false;

                const style = window.getComputedStyle(element);
                const rect = element.getBoundingClientRect();

                return (
                    style.display !== "none" &&
                    style.visibility !== "hidden" &&
                    rect.width > 0 &&
                    rect.height > 0
                );
            }

            function norm(value) {
                return String(value || "")
                    .replace(/\s+/g, " ")
                    .trim()
                    .toLowerCase();
            }

            const wanted =
                "please change your login password.";

            const containers = Array.from(
                document.querySelectorAll(
                    "[role='dialog'],.dialog,.modal,.aui_dialog," +
                    ".ui-dialog,.layui-layer,body > div"
                )
            ).filter(visible);

            for (const container of containers) {
                const text = norm(
                    container.innerText ||
                    container.textContent ||
                    ""
                );

                if (!text.includes(wanted)) {
                    continue;
                }

                const buttons = Array.from(
                    container.querySelectorAll(
                        "button,input[type='button']," +
                        "input[type='submit'],a,[role='button']"
                    )
                ).filter(visible);

                const ok = buttons.find(
                    (element) => (
                        norm(
                            element.innerText ||
                            element.value ||
                            element.textContent ||
                            ""
                        ) === "ok"
                    )
                );

                if (!ok) {
                    return {
                        found: true,
                        clicked: false
                    };
                }

                ok.click();

                return {
                    found: true,
                    clicked: true
                };
            }

            return {
                found: false,
                clicked: false
            };
            """
        )

        if result.get("found"):
            if not result.get("clicked"):
                raise RuntimeError(
                    "First-login password-change Note was detected, "
                    "but its OK button could not be clicked."
                )

            print(
                "[USER MANAGEMENT LOGIN] First-login Note detected: "
                "'Please change your login password.' Clicked OK."
            )

            # Allow the old UI to finish establishing/redirecting the
            # authenticated session after modal dismissal.
            time_module.sleep(0.8)

            return True

        time_module.sleep(0.2)

    return False


def ensure_first_login_session_reaches_configuration(
    driver,
    row,
):
    """
    After MM/ME Testing-password login, dismiss the forced password-change
    Note, then explicitly load config.asp using the now-authenticated session.
    """
    ip = get_value(row, "Current IP")
    username = get_value(row, "Username")
    password = get_value(row, "Password")

    # The modal may appear immediately or shortly after the login helper
    # returns.
    handle_forced_password_change_note(
        driver,
        timeout=8,
    )

    current_url = str(
        driver.current_url
        or ""
    ).lower()

    # Even after clicking OK, some old firmware remains visually on login.asp.
    # Open config.asp explicitly; if authentication succeeded the WebSession
    # will allow access without re-entering credentials.
    if "/doc/page/config.asp" not in current_url:
        target_url = (
            f"https://{ip}/doc/page/config.asp"
            f"?t={int(time_module.time() * 1000)}"
        )

        driver.get(
            target_url
        )

        time_module.sleep(0.5)

        # A second Note can occasionally be rendered after navigation.
        handle_forced_password_change_note(
            driver,
            timeout=2,
        )

        # Only invoke the normal login helper if a real login form is still
        # present. In the normal first-login flow the session is already
        # authenticated after the Note.
        hikvision_web_login_if_needed(
            driver,
            username,
            password,
        )

        handle_forced_password_change_note(
            driver,
            timeout=2,
        )

    return True


def find_user_management_add_button(driver, max_depth=5):
    """
    Return the *actually clickable* User Management Add control.

    v116 fixes the modern Dome UI seen on example camera addresses.  Those
    pages expose a visible "+ Add" toolbar item, but the previous locator could
    return the inner label/icon rather than the ancestor that owns the Vue
    click handler.  Selenium/CDP then clicked a perfectly visible DOM node but
    the Add User component never opened.

    Selection rules:
      - exact Add / Add User / New User label wins;
      - walk upward from the label to locate the nearest real clickable
        ancestor (button/a/role=button/tabindex/cursor:pointer/click-ish class);
      - reject disabled, pointer-events:none, off-screen and non-hit-testable
        candidates;
      - prefer the candidate whose centre is actually under document.elementFromPoint;
      - retain old UI + iframe + open-shadow-root support.

    The function leaves Selenium inside the frame that owns the control.
    """
    try:
        driver.switch_to.default_content()
    except Exception:
        pass

    search_script = r"""
        function norm(v) {
            return String(v || '').replace(/\s+/g, ' ').trim().toLowerCase();
        }

        function disabled(el) {
            if (!el) return true;
            const cls = norm(el.className || '');
            return Boolean(
                el.disabled ||
                norm(el.getAttribute('aria-disabled')) === 'true' ||
                cls.includes('disabled') || cls.includes('is-disabled')
            );
        }

        function visible(el) {
            if (!el || !el.isConnected || disabled(el)) return false;
            let cur = el;
            while (cur && cur !== document.documentElement) {
                const s = window.getComputedStyle(cur);
                if (
                    s.display === 'none' || s.visibility === 'hidden' ||
                    Number(s.opacity || '1') === 0 ||
                    s.pointerEvents === 'none' ||
                    cur.getAttribute('aria-hidden') === 'true'
                ) return false;
                cur = cur.parentElement;
            }
            const r = el.getBoundingClientRect();
            if (r.width <= 0 || r.height <= 0) return false;
            // A translated/off-screen hidden component must never beat the
            // real toolbar Add control.
            if (r.right <= 0 || r.bottom <= 0 || r.left >= innerWidth || r.top >= innerHeight) return false;
            return true;
        }

        function ownText(el) {
            if (!el) return '';
            let value = '';
            for (const node of Array.from(el.childNodes || [])) {
                if (node.nodeType === Node.TEXT_NODE) value += ' ' + (node.nodeValue || '');
            }
            return norm(value);
        }

        function labelKind(el) {
            const direct = ownText(el);
            let full = norm(el.innerText || el.value || el.textContent || '');
            // Ignore giant page containers that merely contain an Add label.
            if (full.length > 50) full = '';
            const aria = norm(el.getAttribute && el.getAttribute('aria-label'));
            const title = norm(el.getAttribute && el.getAttribute('title'));
            const values = [direct, full, aria, title];
            if (values.includes('add user')) return 0;
            if (values.includes('add')) return 1;
            if (values.includes('new user')) return 2;
            return 999;
        }

        function clickish(el) {
            if (!el) return false;
            const tag = String(el.tagName || '').toLowerCase();
            const role = norm(el.getAttribute('role'));
            const cls = norm(el.className || '');
            const id = norm(el.id || '');
            const cursor = norm(window.getComputedStyle(el).cursor);
            const tabindex = el.getAttribute('tabindex');
            return (
                ['button','a'].includes(tag) || role === 'button' ||
                tabindex !== null || cursor === 'pointer' ||
                el.hasAttribute('onclick') || el.hasAttribute('ng-click') ||
                /(^|[-_\s])(add|btn|button|tool|action|operate|operation)([-_\s]|$)/.test(cls + ' ' + id) ||
                cls.includes('el-button')
            );
        }

        function hitInfo(el) {
            const r = el.getBoundingClientRect();
            const x = Math.max(0, Math.min(innerWidth - 1, r.left + r.width / 2));
            const y = Math.max(0, Math.min(innerHeight - 1, r.top + r.height / 2));
            const hit = document.elementFromPoint(x, y);
            const compatible = Boolean(hit && (hit === el || el.contains(hit) || hit.contains(el)));
            return {hit: hit, compatible: compatible, x: x, y: y};
        }

        function rootsFrom(start) {
            const queue = [start], out = [], seen = new Set();
            while (queue.length) {
                const root = queue.shift();
                if (!root || seen.has(root)) continue;
                seen.add(root); out.push(root);
                let all = [];
                try { all = Array.from(root.querySelectorAll('*')); } catch (_) {}
                for (const e of all) if (e.shadowRoot) queue.push(e.shadowRoot);
            }
            return out;
        }

        const candidates = [];
        for (const root of rootsFrom(document)) {
            let nodes = [];
            try { nodes = Array.from(root.querySelectorAll('*')); } catch (_) {}

            for (const label of nodes) {
                if (!visible(label)) continue;
                const kind = labelKind(label);
                if (kind >= 999) continue;

                // Walk from exact text/icon wrapper upward.  Modern Hikvision
                // binds @click on a surrounding toolbar div rather than the
                // inner Add text node on some firmware builds.
                let current = label;
                for (let depth = 0; depth < 10 && current; depth++) {
                    if (!visible(current)) { current = current.parentElement; continue; }
                    const r = current.getBoundingClientRect();
                    const area = Math.max(1, r.width * r.height);
                    if (area > 180000) { current = current.parentElement; continue; }

                    const hit = hitInfo(current);
                    const tag = String(current.tagName || '').toLowerCase();
                    const cursor = norm(window.getComputedStyle(current).cursor);
                    const cls = norm(current.className || '');
                    const id = norm(current.id || '');

                    let score = kind * 100 + depth * 3;
                    if (clickish(current)) score -= 25;
                    if (['button','a'].includes(tag)) score -= 15;
                    if (norm(current.getAttribute('role')) === 'button') score -= 15;
                    if (cursor === 'pointer') score -= 12;
                    if (hit.compatible) score -= 30; else score += 40;
                    if (area > 50000) score += 15;

                    candidates.push({
                        element: current,
                        score: score,
                        area: area,
                        hitCompatible: hit.compatible,
                        label: norm(label.innerText || label.textContent || ''),
                        tag: tag,
                        className: cls,
                        id: id
                    });

                    // Once we have a strongly click-like hit-tested ancestor,
                    // higher ancestors are less likely to be the intended item.
                    if (clickish(current) && hit.compatible) break;
                    current = current.parentElement;
                }
            }
        }

        if (!candidates.length) return null;
        candidates.sort((a,b) => a.score - b.score || a.area - b.area);
        return candidates[0].element;
    """

    def search(depth):
        try:
            button = driver.execute_script(search_script)
        except Exception:
            button = None

        if button is not None:
            return button
        if depth >= max_depth:
            return None

        try:
            frames = driver.find_elements(By.CSS_SELECTOR, "iframe,frame")
        except Exception:
            frames = []

        for frame_index in range(len(frames)):
            try:
                current_frames = driver.find_elements(By.CSS_SELECTOR, "iframe,frame")
                if frame_index >= len(current_frames):
                    continue
                driver.switch_to.frame(current_frames[frame_index])
            except Exception:
                continue

            found = search(depth + 1)
            if found is not None:
                return found

            try:
                driver.switch_to.parent_frame()
            except Exception:
                try:
                    driver.switch_to.default_content()
                except Exception:
                    pass
        return None

    result = search(0)
    if result is None:
        try:
            driver.switch_to.default_content()
        except Exception:
            pass
    return result


def dome_user_management_ready(driver):
    """True only when the Dome User Management page has its actual Add control."""
    try:
        return find_user_management_add_button(driver) is not None
    except Exception:
        return False


def open_user_management_page_for_account(
    driver,
    row,
    preserve_current_session=True,
):
    """
    Open Configuration > System > User Management and verify the REAL page.

    Important v104 behaviour:
      - Dome Option 3 uses the requested visible navigation sequence first:
            Configuration > System > User Management
      - Options 1/2 reuse the authenticated browser left by Account Security.
        If Account Security was opened from User Management, the script simply
        verifies that the Add control is back and continues without reopening
        Edge or reloading the login page.
      - A hash route is retained only as a same-session fallback.
      - Readiness is the actual Add/Add User button, not menu text.
    """
    kind = user_management_device_kind(row)

    ip = get_value(row, "Current IP")
    username = get_value(row, "Username")
    password = get_value(row, "Password")

    try:
        driver.switch_to.default_content()
    except Exception:
        pass

    if kind in {"NVR", "DISCREET"}:
        # The old UI helper already performs Configuration > System >
        # User Management and verifies the actual User List table.  When the
        # current driver is already authenticated, it keeps that same session.
        return open_old_ui_user_management_page(
            driver,
            row,
            kind,
        )

    # DOME -----------------------------------------------------------------
    if dome_user_management_ready(driver):
        print(
            f"[USER MANAGEMENT NAV] {ip}: already on the verified Dome "
            "User Management page in the current authenticated Edge session."
        )
        return True

    current_url = str(driver.current_url or "")

    # A new Option-3 browser starts at about:blank.  Options 1/2 normally
    # arrive here already authenticated from Account Security.
    if (
        not preserve_current_session
        or current_url.lower().startswith("about:")
        or not is_hikvision_authenticated_page(driver)
    ):
        base_url = (
            f"https://{ip}/doc/index.html"
            f"?t={int(time_module.time() * 1000)}"
        )
        print(
            f"[USER MANAGEMENT NAV] {ip}: opening Dome base page: "
            f"{base_url}"
        )
        driver.get(base_url)
        hikvision_web_login_if_needed(
            driver,
            username,
            password,
        )
        time_module.sleep(1.2)

    last_error = ""

    for attempt in range(1, USER_MANAGEMENT_PAGE_NAV_MAX_ATTEMPTS + 1):
        try:
            driver.switch_to.default_content()

            if dome_user_management_ready(driver):
                return True

            print(
                f"[USER MANAGEMENT NAV] {ip}: Dome visible navigation "
                f"attempt {attempt}/{USER_MANAGEMENT_PAGE_NAV_MAX_ATTEMPTS}: "
                "Configuration > System > User Management."
            )

            # Configuration may already be selected after Account Security.
            if "#/config/" not in str(driver.current_url or "").lower():
                click_visible_exact_text(
                    driver,
                    ["Configuration"],
                    "Dome Configuration",
                    timeout=12,
                )
                time_module.sleep(0.8)

            # System can be a submenu title.  Re-clicking it is harmless and
            # ensures User Management is exposed before the final click.
            try:
                click_visible_exact_text(
                    driver,
                    ["System"],
                    "Dome System",
                    timeout=12,
                )
            except Exception as system_error:
                # If User Management is already visible, System was already
                # expanded and no extra click is required.
                if not wait_for_visible_text(
                    driver,
                    "User Management",
                    timeout=2,
                ):
                    raise system_error

            time_module.sleep(0.6)

            click_visible_exact_text(
                driver,
                ["User Management"],
                "Dome User Management",
                timeout=15,
            )

            WebDriverWait(
                driver,
                USER_MANAGEMENT_DIALOG_WAIT_SECONDS,
            ).until(
                lambda current_driver: dome_user_management_ready(
                    current_driver
                )
            )

            print(
                f"[USER MANAGEMENT NAV] {ip}: verified Dome User "
                "Management page; Add control is visible."
            )
            return True

        except Exception as error:
            last_error = str(error)
            print(
                f"[USER MANAGEMENT NAV WARNING] {ip}: visible navigation "
                f"attempt {attempt} failed: {last_error}"
            )

            # Same-browser fallback: force the authenticated SPA route.  This
            # does NOT close/reopen Edge and does NOT re-enter credentials.
            try:
                driver.switch_to.default_content()
                driver.execute_script(
                    r"""
                    const targetHash =
                        "#/config/system/user/userManagement";
                    if (window.location.hash !== targetHash) {
                        window.location.hash = targetHash;
                        try {
                            window.dispatchEvent(
                                new HashChangeEvent("hashchange")
                            );
                        } catch (error) {
                            window.dispatchEvent(
                                new Event("hashchange")
                            );
                        }
                    }
                    """
                )

                WebDriverWait(driver, 10).until(
                    lambda current_driver: dome_user_management_ready(
                        current_driver
                    )
                )

                print(
                    f"[USER MANAGEMENT NAV] {ip}: same-session route "
                    "fallback verified; Add control is visible."
                )
                return True
            except Exception as route_error:
                last_error = (
                    f"{last_error}; route fallback={route_error}"
                )

            if attempt < USER_MANAGEMENT_PAGE_NAV_MAX_ATTEMPTS:
                # Refresh/reopen the page inside the SAME Edge session.  The
                # Hikvision WebSession cookie remains intact.
                try:
                    target_url = (
                        f"https://{ip}/doc/index.html"
                        f"?t={int(time_module.time() * 1000)}"
                    )
                    driver.get(target_url)
                    hikvision_web_login_if_needed(
                        driver,
                        username,
                        password,
                    )
                except Exception as refresh_error:
                    last_error = (
                        f"{last_error}; same-session refresh={refresh_error}"
                    )

                time_module.sleep(
                    USER_MANAGEMENT_SAME_SESSION_RETRY_WAIT_SECONDS
                )

    save_web_ui_debug(
        driver,
        ip,
        "dome_user_management_navigation_failure_v104",
    )

    raise RuntimeError(
        "Dome User Management page could not be verified after "
        "Configuration > System > User Management navigation and "
        "same-session route recovery. The required Add control never "
        f"became visible. Last detail: {last_error}"
    )


def username_visible_in_user_list(
    driver,
    username,
):
    return bool(
        driver.execute_script(
            r"""
            const wanted = String(arguments[0] || "").trim();

            function visible(element) {
                if (!element) return false;

                const style = window.getComputedStyle(element);
                const rect = element.getBoundingClientRect();

                return (
                    style.display !== "none" &&
                    style.visibility !== "hidden" &&
                    rect.width > 0 &&
                    rect.height > 0
                );
            }

            return Array.from(
                document.querySelectorAll(
                    "td,th,span,div,p,a"
                )
            ).some((element) => (
                visible(element) &&
                String(
                    element.innerText ||
                    element.textContent ||
                    ""
                ).trim() === wanted
            ));
            """,
            str(username),
        )
    )


def get_isapi_user_snapshot(row):
    """
    Read the authenticated UserList directly from the device.

    This avoids a false negative when the web UI has not refreshed its table
    after the Add User request completed.
    """
    ip = get_value(row, "Current IP")
    username = get_value(row, "Username")
    password = get_value(row, "Password")

    status, response = get_xml(
        ip,
        username,
        password,
        "/ISAPI/Security/users",
    )

    snapshot = {
        "status": status,
        "count": None,
        "usernames": [],
        "user_ids": {},
    }

    if status != 200:
        return snapshot

    try:
        root = ET.fromstring(response)
        users = [
            element
            for element in root.iter()
            if element.tag.split("}")[-1] == "User"
        ]

        snapshot["count"] = len(users)

        for user in users:
            current_user_id = ""
            current_username = ""

            for child in list(user):
                local_name = child.tag.split("}")[-1]
                value = str(child.text or "").strip()

                if local_name == "id":
                    current_user_id = value

                elif local_name == "userName":
                    current_username = value

            if current_username:
                snapshot["usernames"].append(
                    current_username
                )

                if current_user_id:
                    snapshot["user_ids"][
                        current_username
                    ] = current_user_id

    except Exception:
        pass

    return snapshot


def refresh_user_management_page(
    driver,
    row,
):
    """
    Force User Management to fetch its user list again.

    Observed failure:
      Add User dialog closed,
      but screenshot still showed only admin.
    The old code immediately treated that stale UI as a failed creation.
    """
    try:
        driver.refresh()
        time_module.sleep(2)
    except Exception:
        pass

    open_user_management_page_for_account(
        driver,
        row,
    )

    time_module.sleep(2)



def find_user_edit_dialog(driver, need_username=True, max_depth=6):
    """Find the active Hikvision Add/Modify user panel in any browsing context.

    v116 deliberately relaxes *opening* detection for the modern Dome UI.  The
    page keeps a hidden Add User component in the DOM even when closed, and
    different firmware revisions render different subsets of fields before the
    permission area finishes mounting.  Therefore an Add panel is recognized
    from a VISIBLE exact Add User title plus live form/dialog evidence; the
    later field collector still performs strict credential validation.

    Off-screen/translated hidden templates are rejected by viewport checks.
    """
    try:
        driver.switch_to.default_content()
    except Exception:
        pass

    add_script = r"""
        function norm(v){ return String(v||'').replace(/\s+/g,' ').trim().toLowerCase(); }
        function visible(el){
            if (!el || !el.isConnected) return false;
            let cur=el;
            while(cur && cur!==document.documentElement){
                const s=getComputedStyle(cur);
                if(s.display==='none'||s.visibility==='hidden'||Number(s.opacity||'1')===0||cur.getAttribute('aria-hidden')==='true') return false;
                cur=cur.parentElement;
            }
            const r=el.getBoundingClientRect();
            return r.width>0&&r.height>0&&r.right>0&&r.bottom>0&&r.left<innerWidth&&r.top<innerHeight;
        }
        function rootsFrom(start){
            const q=[start],out=[],seen=new Set();
            while(q.length){const root=q.shift(); if(!root||seen.has(root))continue; seen.add(root);out.push(root);
                let all=[];try{all=Array.from(root.querySelectorAll('*'));}catch(_){}
                for(const e of all) if(e.shadowRoot)q.push(e.shadowRoot);
            }return out;
        }
        function exactAddTitle(el){
            if(!visible(el)) return false;
            const t=norm(el.innerText||el.textContent||el.getAttribute('aria-label')||el.title||'');
            return ['add user','adduser','new user'].includes(t);
        }
        function scoreContainer(container,title){
            if(!container||!visible(container)) return null;
            const r=container.getBoundingClientRect();
            const area=Math.max(1,r.width*r.height);
            if(area<5000 || area>innerWidth*innerHeight*0.95) return null;
            const text=norm(container.innerText||container.textContent||'');
            if(text.includes('old password') && !text.includes('admin password')) return null;
            const inputs=Array.from(container.querySelectorAll('input')).filter(visible);
            const checks=inputs.filter(i=>norm(i.type)==='checkbox').length;
            const editable=inputs.filter(i=>!['hidden','checkbox','radio','button','submit','image'].includes(norm(i.type||'text'))).length;
            const buttons=Array.from(container.querySelectorAll('button,a,[role="button"],input[type="button"],input[type="submit"]')).filter(visible);
            const buttonText=buttons.map(b=>norm(b.innerText||b.value||b.textContent||'')).join(' ');
            const formEvidence=(editable>=1||checks>=1||text.includes('permission configuration')||text.includes('admin password')||text.includes('user name'));
            const actionEvidence=(buttonText.includes('ok')||buttonText.includes('cancel')||text.includes('permission configuration'));
            if(!formEvidence || !actionEvidence) return null;
            let score=0;
            if(text.includes('permission configuration')) score+=80;
            if(text.includes('admin password')) score+=60;
            if(text.includes('user name')||text.includes('username')) score+=50;
            if(text.includes('user type')||text.includes('level')) score+=30;
            if(editable>=3) score+=25;
            if(checks>=1) score+=20;
            score-=Math.min(area/100000,20);
            return {element:container,score:score,area:area,editable:editable,checks:checks};
        }

        const hits=[];
        for(const root of rootsFrom(document)){
            let titles=[];try{titles=Array.from(root.querySelectorAll('.el-drawer__title,.el-dialog__title,[role="heading"],h1,h2,h3,h4,span,div'));}catch(_){}
            for(const title of titles){
                if(!exactAddTitle(title)) continue;
                let cur=title;
                for(let depth=0;depth<20&&cur;depth++){
                    const hit=scoreContainer(cur,title);
                    if(hit){hit.depth=depth;hits.push(hit);}
                    cur=cur.parentElement;
                }
            }
        }
        if(!hits.length) return null;
        // Prefer the most semantically complete panel, then the smallest
        // qualifying ancestor so we do not return the whole page.
        hits.sort((a,b)=>b.score-a.score||a.area-b.area||a.depth-b.depth);
        return hits[0].element;
    """

    modify_script = r"""
        function visible(element) {
            if (!element || !element.isConnected) return false;
            const style = window.getComputedStyle(element);
            const rect = element.getBoundingClientRect();
            return style.display !== 'none' && style.visibility !== 'hidden' &&
                   Number(style.opacity || '1') !== 0 && rect.width > 0 && rect.height > 0;
        }
        function norm(v) { return String(v || '').replace(/\s+/g,' ').trim().toLowerCase(); }
        const candidates = Array.from(document.querySelectorAll(
            "[role='dialog'],.el-dialog,.el-drawer,.modal,.modal-dialog,.dialog,.window,.aui_dialog,.ui-dialog,.layui-layer"
        )).filter(visible);
        const matches=[];
        for (const container of candidates) {
            const inputs=Array.from(container.querySelectorAll('input')).filter(visible);
            const pw=inputs.filter((i)=>norm(i.type)==='password');
            if (pw.length < 2) continue;
            const text=norm(container.innerText || container.textContent || '');
            let score=0;
            if (text.includes('old password')) score += 100;
            if (text.includes('password confirm') || text.includes('confirm')) score += 20;
            const r=container.getBoundingClientRect();
            matches.push({element:container,score:score,area:r.width*r.height});
        }
        if (!matches.length) return null;
        matches.sort((a,b)=>b.score-a.score || a.area-b.area);
        return matches[0].element;
    """

    script = add_script if need_username else modify_script

    def search(depth):
        try:
            result = driver.execute_script(script)
        except Exception:
            result = None
        if result is not None:
            return result
        if depth >= max_depth:
            return None
        try:
            frames = driver.find_elements(By.CSS_SELECTOR, 'iframe,frame')
        except Exception:
            frames = []
        for index in range(len(frames)):
            try:
                current = driver.find_elements(By.CSS_SELECTOR, 'iframe,frame')
                if index >= len(current):
                    continue
                driver.switch_to.frame(current[index])
            except Exception:
                continue
            result = search(depth + 1)
            if result is not None:
                return result
            try:
                driver.switch_to.parent_frame()
            except Exception:
                try:
                    driver.switch_to.default_content()
                except Exception:
                    pass
        return None

    result = search(0)

    # v117 old-UI structural fallback. The diagnostics on .18/.19 showed a
    # visibly open Add user modal with 3 password fields even when the semantic
    # ancestor scorer missed it. Accept only a scoped visible dialog with the
    # complete Add-user signature.
    if result is None and need_username:
        fallback_script = r"""
            function norm(v){return String(v||'').replace(/\s+/g,' ').trim().toLowerCase();}
            function visible(el){
                if(!el||!el.isConnected)return false;
                const s=getComputedStyle(el),r=el.getBoundingClientRect();
                return s.display!=='none'&&s.visibility!=='hidden'&&Number(s.opacity||'1')!==0&&
                       r.width>0&&r.height>0&&r.right>0&&r.bottom>0&&r.left<innerWidth&&r.top<innerHeight;
            }
            const candidates=Array.from(document.querySelectorAll(
                ".aui_dialog,.ui-dialog,.el-dialog,.el-drawer,[role='dialog'],.modal,.modal-dialog,.dialog,.window"
            )).filter(visible);
            const hits=[];
            for(const d of candidates){
                const text=norm(d.innerText||d.textContent||'');
                const inputs=Array.from(d.querySelectorAll('input')).filter(visible);
                const passwords=inputs.filter(i=>norm(i.type)==='password');
                const editable=inputs.filter(i=>!['hidden','checkbox','radio','button','submit','image'].includes(norm(i.type||'text')));
                const titleEvidence=(text.includes('add user')||text.includes('adduser')||text.includes('new user'));
                const fieldEvidence=(text.includes('user name')||text.includes('username'))&&
                    (text.includes('admin password')||passwords.length>=3)&&
                    (text.includes('confirm')||passwords.length>=3);
                if(!titleEvidence||!fieldEvidence||editable.length<3||passwords.length<3)continue;
                const r=d.getBoundingClientRect();
                hits.push({element:d,area:r.width*r.height});
            }
            if(!hits.length)return null;
            hits.sort((a,b)=>a.area-b.area);
            return hits[0].element;
        """

        def fallback_search(depth):
            try:
                candidate = driver.execute_script(fallback_script)
            except Exception:
                candidate = None
            if candidate is not None:
                return candidate
            if depth >= max_depth:
                return None
            try:
                frames = driver.find_elements(By.CSS_SELECTOR, 'iframe,frame')
            except Exception:
                frames = []
            for index in range(len(frames)):
                try:
                    current = driver.find_elements(By.CSS_SELECTOR, 'iframe,frame')
                    if index >= len(current):
                        continue
                    driver.switch_to.frame(current[index])
                except Exception:
                    continue
                candidate = fallback_search(depth + 1)
                if candidate is not None:
                    return candidate
                try:
                    driver.switch_to.parent_frame()
                except Exception:
                    try:
                        driver.switch_to.default_content()
                    except Exception:
                        pass
            return None

        try:
            driver.switch_to.default_content()
        except Exception:
            pass
        result = fallback_search(0)
        if result is not None:
            print(
                "[USER MANAGEMENT ADD] v117 structural fallback accepted a "
                "visible old-UI Add user dialog with 3 password fields."
            )

    if result is None:
        try:
            driver.switch_to.default_content()
        except Exception:
            pass
    return result


def _wait_for_add_user_panel(driver, timeout=None):
    """Wait briefly for a real Add User panel, searching all frames each poll."""
    if timeout is None:
        timeout = USER_MANAGEMENT_ADD_OPEN_VERIFY_SECONDS
    deadline = time_module.monotonic() + max(0.5, float(timeout))
    while time_module.monotonic() < deadline:
        panel = find_user_edit_dialog(driver, need_username=True)
        if panel is not None:
            return panel
        time_module.sleep(0.15)
    return None


def get_add_user_open_diagnostics(driver, max_depth=5):
    """Return structural diagnostics only; never reads credential input values."""
    try:
        driver.switch_to.default_content()
    except Exception:
        pass
    snapshots = []
    script = r"""
        function norm(v){return String(v||'').replace(/\s+/g,' ').trim();}
        function visible(el){
            if(!el||!el.isConnected)return false;
            const s=getComputedStyle(el),r=el.getBoundingClientRect();
            return s.display!=='none'&&s.visibility!=='hidden'&&Number(s.opacity||'1')!==0&&r.width>0&&r.height>0&&r.right>0&&r.bottom>0&&r.left<innerWidth&&r.top<innerHeight;
        }
        function ownText(el){let t='';for(const n of Array.from(el.childNodes||[]))if(n.nodeType===Node.TEXT_NODE)t+=' '+(n.nodeValue||'');return norm(t);}
        const controls=Array.from(document.querySelectorAll("button,input[type='button'],input[type='submit'],a,[role='button']"))
          .filter(visible).map((e)=>norm(e.innerText||e.value||e.textContent||e.getAttribute('aria-label')||e.title||'')).filter(Boolean).slice(0,25);
        const addCandidates=[];
        for(const e of Array.from(document.querySelectorAll('*'))){
            if(!visible(e))continue;
            const direct=ownText(e).toLowerCase();
            const full=(norm(e.innerText||e.value||'').length<=50?norm(e.innerText||e.value||'').toLowerCase():'');
            const aria=norm(e.getAttribute&&e.getAttribute('aria-label')).toLowerCase();
            const title=norm(e.getAttribute&&e.getAttribute('title')).toLowerCase();
            if(![direct,full,aria,title].some(v=>['add','add user','new user'].includes(v)))continue;
            const r=e.getBoundingClientRect(),x=Math.max(0,Math.min(innerWidth-1,r.left+r.width/2)),y=Math.max(0,Math.min(innerHeight-1,r.top+r.height/2));
            const hit=document.elementFromPoint(x,y);
            addCandidates.push({
                tag:e.tagName,id:e.id||'',className:String(e.className||'').slice(0,160),cursor:getComputedStyle(e).cursor,
                directText:direct,fullText:full,rect:{x:Math.round(r.x),y:Math.round(r.y),w:Math.round(r.width),h:Math.round(r.height)},
                hitTag:hit?hit.tagName:'',hitId:hit?(hit.id||''):'',hitClass:hit?String(hit.className||'').slice(0,120):'',
                hitCompatible:Boolean(hit&&(hit===e||e.contains(hit)||hit.contains(e)))
            });
            if(addCandidates.length>=12)break;
        }
        const panels=Array.from(document.querySelectorAll(".el-drawer,.el-dialog,[role='dialog'],.modal,.modal-dialog,.aui_dialog,.ui-dialog,.window"))
          .filter(visible).map((d)=>({text:norm(d.innerText||d.textContent||'').slice(0,220),inputs:d.querySelectorAll('input').length,passwords:d.querySelectorAll('input[type="password"]').length,checkboxes:d.querySelectorAll('input[type="checkbox"]').length})).slice(0,8);
        const exactVisibleAddUserTitles=Array.from(document.querySelectorAll('.el-drawer__title,.el-dialog__title,[role="heading"],h1,h2,h3,h4,span,div'))
          .filter(visible).map(e=>norm(e.innerText||e.textContent||'')).filter(t=>['add user','adduser','new user'].includes(t.toLowerCase())).slice(0,10);
        return {url:String(location.href),controls:controls,addCandidates:addCandidates,exactVisibleAddUserTitles:exactVisibleAddUserTitles,panels:panels,frameCount:document.querySelectorAll('iframe,frame').length};
    """
    def walk(depth, path):
        try:
            data = driver.execute_script(script) or {}
            data['framePath'] = list(path)
            snapshots.append(data)
        except Exception as error:
            snapshots.append({'framePath': list(path), 'scriptError': str(error)})
        if depth >= max_depth:
            return
        try:
            frames = driver.find_elements(By.CSS_SELECTOR, 'iframe,frame')
        except Exception:
            frames = []
        for i in range(len(frames)):
            try:
                current = driver.find_elements(By.CSS_SELECTOR, 'iframe,frame')
                if i >= len(current):
                    continue
                driver.switch_to.frame(current[i])
                walk(depth + 1, path + [i])
            except Exception:
                pass
            finally:
                try:
                    driver.switch_to.parent_frame()
                except Exception:
                    try:
                        driver.switch_to.default_content()
                    except Exception:
                        pass
    walk(0, [])
    try:
        driver.switch_to.default_content()
    except Exception:
        pass
    return snapshots[:12]


def _click_add_control_once(driver, button, method):
    """Perform one Add click method. UI success is verified by the caller."""
    if method == 'actionchains':
        ActionChains(driver).move_to_element(button).pause(0.12).click(button).perform()
        return

    if method == 'native':
        button.click()
        return

    if method == 'hitjs':
        # Dispatch the complete pointer/mouse sequence to the *topmost* element
        # at the toolbar Add centre.  This is important on modern Dome Vue UI,
        # where the visible Add text can be a child of the handler owner.
        ok = driver.execute_script(
            r"""
            const control=arguments[0];
            control.scrollIntoView({block:'center',inline:'center'});
            const r=control.getBoundingClientRect();
            const x=Math.max(0,Math.min(innerWidth-1,r.left+r.width/2));
            const y=Math.max(0,Math.min(innerHeight-1,r.top+r.height/2));
            const target=document.elementFromPoint(x,y) || control;
            try { target.focus({preventScroll:true}); } catch (_) { try { target.focus(); } catch (_) {} }
            const common={view:window,bubbles:true,cancelable:true,composed:true,clientX:x,clientY:y,button:0};
            try { target.dispatchEvent(new PointerEvent('pointerdown',{...common,buttons:1,pointerId:1,pointerType:'mouse',isPrimary:true})); } catch (_) {}
            target.dispatchEvent(new MouseEvent('mousedown',{...common,buttons:1}));
            try { target.dispatchEvent(new PointerEvent('pointerup',{...common,buttons:0,pointerId:1,pointerType:'mouse',isPrimary:true})); } catch (_) {}
            target.dispatchEvent(new MouseEvent('mouseup',{...common,buttons:0}));
            target.dispatchEvent(new MouseEvent('click',{...common,buttons:0,detail:1}));
            return true;
            """,
            button,
        )
        if not ok:
            raise RuntimeError('hitjs event sequence could not be dispatched')
        return

    if method == 'keyboard':
        try:
            driver.execute_script("arguments[0].focus();", button)
        except Exception:
            pass
        button.send_keys(Keys.ENTER)
        return

    if method == 'javascript':
        driver.execute_script(
            r"""
            const e=arguments[0];
            // Prefer a likely Vue/toolbar handler ancestor, but never climb to
            // the full page container.
            let target=e;
            let cur=e;
            for(let i=0;i<8&&cur;i++,cur=cur.parentElement){
                const s=getComputedStyle(cur),cls=String(cur.className||'').toLowerCase(),role=String(cur.getAttribute('role')||'').toLowerCase();
                if(cur.tagName==='BUTTON'||cur.tagName==='A'||role==='button'||s.cursor==='pointer'||/add|tool|action|operate|operation|button|btn/.test(cls)) { target=cur; break; }
            }
            target.click();
            """,
            button,
        )
        return

    if method == 'vuehandler':
        invoked = driver.execute_script(
            r"""
            let cur=arguments[0];
            const evt=new MouseEvent('click',{view:window,bubbles:true,cancelable:true,composed:true,button:0});
            for(let depth=0;depth<10&&cur;depth++,cur=cur.parentElement){
                // Vue 3 stores native event invokers in _vei on the element.
                const inv=cur._vei && (cur._vei.onClick || cur._vei.click);
                if(inv){
                    try {
                        if(typeof inv==='function'){ inv(evt); return true; }
                        const value=inv.value;
                        if(typeof value==='function'){ value(evt); return true; }
                        if(Array.isArray(value)){ for(const fn of value) if(typeof fn==='function') fn(evt); return true; }
                    } catch(e) { throw e; }
                }
            }
            return false;
            """,
            button,
        )
        if not invoked:
            raise RuntimeError('no Vue click invoker found on Add control ancestor chain')
        return

    if method == 'cdp':
        coords = driver.execute_script(
            """
            const e=arguments[0]; e.scrollIntoView({block:'center',inline:'center'});
            const r=e.getBoundingClientRect();
            return {x:Math.max(0,Math.min(innerWidth-1,r.left+r.width/2)),y:Math.max(0,Math.min(innerHeight-1,r.top+r.height/2))};
            """,
            button,
        )
        x=float(coords['x']); y=float(coords['y'])
        driver.execute_cdp_cmd('Input.dispatchMouseEvent', {'type':'mouseMoved','x':x,'y':y,'button':'none'})
        driver.execute_cdp_cmd('Input.dispatchMouseEvent', {'type':'mousePressed','x':x,'y':y,'button':'left','buttons':1,'clickCount':1})
        driver.execute_cdp_cmd('Input.dispatchMouseEvent', {'type':'mouseReleased','x':x,'y':y,'button':'left','buttons':0,'clickCount':1})
        return

    raise ValueError(f'Unknown Add click method: {method}')


def click_add_user(driver, row=None):
    """Open Add User and accept a click only after the panel is verified.

    v116 retains the verified-click rule and adds modern-Dome hit-tested targeting. It also supersedes the earlier ``Last detail: Message:`` failure. Selenium can
    complete ``element.click()`` without throwing while Hikvision ignores the
    event or while the resulting drawer is rendered in another frame/context.
    The old code marked that call as clicked and then spent the full dialog
    timeout waiting, ultimately reporting an Add-button failure.

    New rule: *click-call success is not UI success*.  After every click method
    the script searches for a real Add User panel across top document, iframes
    and open shadow roots.  If the panel is absent, it re-resolves a fresh Add
    control and tries the next interaction method before any page-level retry.
    """
    last_error = ''
    last_stage = 'not_started'
    click_methods = ('cdp', 'hitjs', 'native', 'actionchains', 'keyboard', 'javascript', 'vuehandler')

    for attempt in range(1, USER_MANAGEMENT_ADD_BUTTON_MAX_ATTEMPTS + 1):
        try:
            dismiss_hikvision_success_note(driver, timeout=1.2, label='before Add User')

            existing = _wait_for_add_user_panel(driver, timeout=0.6)
            if existing is not None:
                print(
                    f'[USER MANAGEMENT ADD] Add User panel is already open; '
                    f'continuing without clicking Add again (page attempt {attempt}).'
                )
                return existing

            # Make sure the underlying User Management page is valid before
            # spending time on click methods.
            if row is not None:
                try:
                    open_user_management_page_for_account(
                        driver, row, preserve_current_session=True
                    )
                except Exception as nav_error:
                    last_stage = 'page_navigation'
                    raise RuntimeError(f'User Management page recovery failed: {nav_error}')

            for method in click_methods:
                # A previous method may actually have opened the drawer late.
                existing = _wait_for_add_user_panel(driver, timeout=0.35)
                if existing is not None:
                    print(
                        f'[USER MANAGEMENT ADD] Add User panel appeared after '
                        f'previous interaction; verified before {method} fallback.'
                    )
                    return existing

                button = find_user_management_add_button(driver)
                if button is None:
                    last_stage = f'find_add_before_{method}'
                    last_error = 'Verified User Management Add/Add User control was not found.'
                    print(
                        f'[USER MANAGEMENT ADD WARNING] page attempt {attempt}: '
                        f'Add control not found before method={method}.'
                    )
                    break

                try:
                    driver.execute_script(
                        "arguments[0].scrollIntoView({block:'center',inline:'center'});",
                        button,
                    )
                except Exception:
                    pass

                try:
                    _click_add_control_once(driver, button, method)
                    print(
                        f'[USER MANAGEMENT ADD] page attempt {attempt}: '
                        f'method={method} dispatched; verifying real Add User panel.'
                    )
                except Exception as click_error:
                    last_stage = f'click_{method}'
                    last_error = str(click_error).strip() or f'{type(click_error).__name__}: {repr(click_error)}'
                    print(
                        f'[USER MANAGEMENT ADD WARNING] method={method} raised: {last_error}'
                    )
                    continue

                panel = _wait_for_add_user_panel(
                    driver,
                    timeout=USER_MANAGEMENT_ADD_OPEN_VERIFY_SECONDS,
                )
                if panel is not None:
                    print(
                        f'[USER MANAGEMENT ADD] Add User panel verified on '
                        f'page attempt {attempt} using method={method}.'
                    )
                    return panel

                # No exception from the click is NOT enough. Continue with a
                # fresh Add control and a different interaction method.
                last_stage = f'verify_after_{method}'
                last_error = (
                    f'{method} click completed but no Add User panel was '
                    f'detected within {USER_MANAGEMENT_ADD_OPEN_VERIFY_SECONDS:.1f}s.'
                )
                print(f'[USER MANAGEMENT ADD WARNING] {last_error}')

            blockers = visible_hikvision_blocking_dialogs(driver)
            diagnostics = get_add_user_open_diagnostics(driver)
            last_error = (
                f'{last_error}; stage={last_stage}; '
                f'visibleBlockingDialogs={blockers}; structuralDiagnostics={diagnostics}'
            )

        except Exception as error:
            current = str(error).strip() or f'{type(error).__name__}: {repr(error)}'
            blockers = visible_hikvision_blocking_dialogs(driver)
            diagnostics = get_add_user_open_diagnostics(driver)
            last_error = (
                f'{current}; stage={last_stage}; '
                f'visibleBlockingDialogs={blockers}; structuralDiagnostics={diagnostics}'
            )

        print(
            f'[USER MANAGEMENT ADD WARNING] page attempt {attempt}/'
            f'{USER_MANAGEMENT_ADD_BUTTON_MAX_ATTEMPTS} failed: {last_error}'
        )

        if row is not None:
            try:
                save_web_ui_debug(
                    driver,
                    get_value(row, 'Current IP'),
                    f'user_management_add_failure_v116_attempt_{attempt}',
                )
            except Exception:
                pass

        if attempt < USER_MANAGEMENT_ADD_BUTTON_MAX_ATTEMPTS and row is not None:
            try:
                driver.switch_to.default_content()
                open_user_management_page_for_account(
                    driver,
                    row,
                    preserve_current_session=True,
                )
            except Exception as recovery_error:
                last_error += f'; pageRecovery={recovery_error}'
            time_module.sleep(0.4)

    raise RuntimeError(
        'User Management Add User panel could not be opened/verified after '
        f'{USER_MANAGEMENT_ADD_BUTTON_MAX_ATTEMPTS} same-session page attempt(s). '
        f'This is no longer reported merely because Selenium returned an empty TimeoutException. '
        f'Last detail: {last_error}'
    )

def set_operator_level(driver, dialog):
    """
    Ensure Add User -> User Type/Level is Operator.

    v105 Dome fix:
      - The Dome UI commonly renders User Type as an Element/Vue custom select.
      - The visible value (for example "Operator") is stored in a CHILD input's
        ``value`` property, not in the wrapper's innerText/textContent.
      - v104 could therefore SEE Operator on screen but still report:
            Level custom combobox was found, but Operator could not be verified.
      - v105 reads the wrapper AND every relevant descendant value/text/ARIA
        field before and after clicking the dropdown.
      - If the Dome already defaults to Operator, it is accepted immediately;
        the script does not disturb the dropdown unnecessarily.

    Supports:
      - native <select> controls,
      - radio-button Operator choices,
      - Hikvision Element/Vue custom comboboxes,
      - firmware where Operator is fixed/default and no editable level exists.
    """
    desired = str(USER_MANAGEMENT_DEFAULT_LEVEL).strip()
    desired_lower = desired.lower()

    # ---------------------------------------------------------------
    # 1. Native <select>.
    # ---------------------------------------------------------------
    for element in dialog.find_elements(By.CSS_SELECTOR, "select"):
        try:
            if not (element.is_displayed() and element.is_enabled()):
                continue

            selector = Select(element)
            option_texts = [
                str(option.text or "").strip()
                for option in selector.options
            ]
            matching = next(
                (
                    value for value in option_texts
                    if value.lower() == desired_lower
                ),
                None,
            )
            if matching is None:
                continue

            selector.select_by_visible_text(matching)
            selected_text = str(
                selector.first_selected_option.text or ""
            ).strip()

            if selected_text.lower() != desired_lower:
                raise RuntimeError(
                    f"Level native select did not remain {desired}. "
                    f"Actual={selected_text}"
                )

            print(
                f"[USER LEVEL] Selected and verified {desired} using "
                "native select."
            )
            return True
        except Exception:
            continue

    # ---------------------------------------------------------------
    # 2. Radio/label based Operator choice.
    # ---------------------------------------------------------------
    radio_state = driver.execute_script(
        r"""
        const dialog = arguments[0];
        const wanted = String(arguments[1] || "").trim().toLowerCase();

        function visible(element) {
            if (!element) return false;
            const style = window.getComputedStyle(element);
            const rect = element.getBoundingClientRect();
            return (
                style.display !== "none" &&
                style.visibility !== "hidden" &&
                rect.width > 0 &&
                rect.height > 0
            );
        }

        function norm(value) {
            return String(value || "")
                .replace(/\s+/g, " ")
                .trim()
                .toLowerCase();
        }

        for (const label of Array.from(
            dialog.querySelectorAll("label,span,div,td")
        )) {
            if (!visible(label) || norm(label.innerText || label.textContent) !== wanted) {
                continue;
            }

            const containers = [
                label.closest("label"),
                label.closest("tr"),
                label.parentElement,
                label.parentElement?.parentElement
            ].filter(Boolean);

            for (const container of containers) {
                const radio = container.querySelector("input[type='radio']");
                if (!radio || radio.disabled) continue;
                if (!radio.checked) radio.click();
                radio.dispatchEvent(new Event("change", {bubbles:true}));
                return {found:true, selected:Boolean(radio.checked)};
            }
        }

        return {found:false, selected:false};
        """,
        dialog,
        desired,
    )

    if radio_state.get("found"):
        if not radio_state.get("selected"):
            raise RuntimeError(
                f"Level radio was found but {desired} did not become selected."
            )
        print(
            f"[USER LEVEL] Selected and verified {desired} using radio control."
        )
        return True

    # ---------------------------------------------------------------
    # 3. Hikvision Element/Vue custom User Type / Level selector.
    #    Locate by label, then prefer the actual input/combobox child.
    # ---------------------------------------------------------------
    control_info = driver.execute_script(
        r"""
        const dialog = arguments[0];

        function visible(element) {
            if (!element) return false;
            const style = window.getComputedStyle(element);
            const rect = element.getBoundingClientRect();
            return (
                !element.disabled &&
                style.display !== "none" &&
                style.visibility !== "hidden" &&
                rect.width > 0 &&
                rect.height > 0
            );
        }

        function norm(value) {
            return String(value || "")
                .replace(/[:：]/g, "")
                .replace(/\s+/g, " ")
                .trim()
                .toLowerCase();
        }

        function raw(value) {
            return String(value || "")
                .replace(/\s+/g, " ")
                .trim();
        }

        function collect(root) {
            const values = [];
            const push = (value) => {
                const cleaned = raw(value);
                if (cleaned && !values.includes(cleaned)) values.push(cleaned);
            };

            if (!root) return values;

            push(root.value);
            push(root.innerText);
            push(root.textContent);
            if (root.getAttribute) {
                push(root.getAttribute("title"));
                push(root.getAttribute("aria-label"));
                push(root.getAttribute("aria-valuetext"));
                push(root.getAttribute("data-value"));
            }

            for (const child of root.querySelectorAll(
                "input,[role='combobox'],[role='option']," +
                ".el-input__inner,.el-select__selected-item," +
                ".el-select__placeholder,.selected,.is-selected,span,div"
            )) {
                if (!visible(child)) continue;
                push(child.value);
                push(child.innerText);
                push(child.textContent);
                if (child.getAttribute) {
                    push(child.getAttribute("title"));
                    push(child.getAttribute("aria-label"));
                    push(child.getAttribute("aria-valuetext"));
                    push(child.getAttribute("data-value"));
                }
            }

            return values;
        }

        const wantedLabels = new Set([
            "level",
            "user level",
            "user type",
            "type"
        ]);

        const labels = Array.from(
            dialog.querySelectorAll(
                "label,.el-form-item__label,span,div,td,th"
            )
        ).filter((element) => (
            visible(element) &&
            wantedLabels.has(norm(element.innerText || element.textContent))
        ));

        for (const label of labels) {
            const containers = [
                label.closest(".el-form-item"),
                label.closest("tr"),
                label.parentElement,
                label.parentElement?.parentElement,
                label.parentElement?.parentElement?.parentElement
            ].filter(Boolean);

            for (const container of containers) {
                // Prefer the real input/combobox because Element often stores
                // the selected text only in input.value.
                const preferred = Array.from(
                    container.querySelectorAll(
                        "input[role='combobox'],.el-select input," +
                        "input[readonly],[role='combobox']"
                    )
                ).find(visible);

                const fallback = Array.from(
                    container.querySelectorAll(".el-select,.select")
                ).find(visible);

                const combo = preferred || fallback;
                if (!combo) continue;

                return {
                    element: combo,
                    container: container,
                    values: collect(container),
                    tag: combo.tagName || "",
                    type: combo.getAttribute?.("type") || "",
                    role: combo.getAttribute?.("role") || ""
                };
            }
        }

        return null;
        """,
        dialog,
    )

    if control_info:
        control = control_info.get("element")
        initial_values = [
            str(value).strip()
            for value in (control_info.get("values") or [])
            if str(value).strip()
        ]

        # v106 repair: a visible/default "Operator" string is NOT enough.
        # On this Dome firmware Element/Vue can render Operator in the input
        # while the underlying form model is still null/undefined. Clicking OK
        # then produces the generic validation message "Required." even though
        # the screen appears filled. Always make a REAL option selection so the
        # component emits the framework change event and commits the model.
        if any(value.lower() == desired_lower for value in initial_values):
            print(
                f"[USER LEVEL] Dome User Type visually shows {desired}, but "
                "v106 will still perform a real dropdown selection to sync "
                "the Element/Vue form model."
            )

        clicked_control = False

        try:
            ActionChains(driver).move_to_element(control).pause(0.10).click(control).perform()
            clicked_control = True
        except Exception:
            pass

        if not clicked_control:
            try:
                control.click()
                clicked_control = True
            except Exception:
                pass

        if not clicked_control:
            # Element selects often listen on the wrapper rather than the input.
            try:
                wrapper = driver.execute_script(
                    "return arguments[0].closest('.el-select') || arguments[0].parentElement;",
                    control,
                )
                if wrapper is not None:
                    ActionChains(driver).move_to_element(wrapper).pause(0.10).click(wrapper).perform()
                    clicked_control = True
            except Exception:
                pass

        if not clicked_control:
            driver.execute_script("arguments[0].click();", control)

        time_module.sleep(0.5)

        option = WebDriverWait(driver, 8).until(
            lambda current_driver: current_driver.execute_script(
                r"""
                const wanted = String(arguments[0] || "").trim().toLowerCase();

                function visible(element) {
                    if (!element) return false;
                    const style = window.getComputedStyle(element);
                    const rect = element.getBoundingClientRect();
                    return (
                        !element.disabled &&
                        style.display !== "none" &&
                        style.visibility !== "hidden" &&
                        rect.width > 0 &&
                        rect.height > 0
                    );
                }

                function norm(value) {
                    return String(value || "")
                        .replace(/\s+/g, " ")
                        .trim()
                        .toLowerCase();
                }

                const selectors = [
                    ".el-select-dropdown__item",
                    "[role='option']",
                    ".dropdown-menu li",
                    ".select-options li",
                    "li"
                ];

                const matches = [];
                for (const selector of selectors) {
                    for (const element of document.querySelectorAll(selector)) {
                        if (
                            visible(element) &&
                            norm(element.innerText || element.textContent) === wanted
                        ) {
                            const rect = element.getBoundingClientRect();
                            matches.push({element, area:rect.width * rect.height});
                        }
                    }
                }

                matches.sort((a,b) => a.area - b.area);
                return matches.length ? matches[0].element : null;
                """,
                desired,
            ) or False
        )

        option_clicked = False

        try:
            ActionChains(driver).move_to_element(option).pause(0.10).click(option).perform()
            option_clicked = True
        except Exception:
            pass

        if not option_clicked:
            try:
                option.click()
                option_clicked = True
            except Exception:
                pass

        if not option_clicked:
            driver.execute_script(
                r"""
                const option = arguments[0];
                for (const eventName of ["mousedown", "mouseup", "click"]) {
                    option.dispatchEvent(new MouseEvent(eventName, {
                        bubbles: true,
                        cancelable: true,
                        view: window,
                        button: 0
                    }));
                }
                if (typeof option.click === "function") option.click();
                """,
                option,
            )

        # Explicitly emit input/change/blur from the real combobox after the
        # option click. This is harmless when Vue already handled the click and
        # fixes firmware where the display changes before the form model does.
        try:
            driver.execute_script(
                r"""
                const control = arguments[0];
                if (control) {
                    control.dispatchEvent(new Event("input", {bubbles:true}));
                    control.dispatchEvent(new Event("change", {bubbles:true}));
                    control.dispatchEvent(new Event("blur", {bubbles:true}));
                }
                """,
                control,
            )
        except Exception:
            pass

        time_module.sleep(0.6)

        verification = driver.execute_script(
            r"""
            const control = arguments[0];
            const dialog = arguments[1];
            const wanted = String(arguments[2] || "").trim().toLowerCase();

            function visible(element) {
                if (!element) return false;
                const style = window.getComputedStyle(element);
                const rect = element.getBoundingClientRect();
                return (
                    style.display !== "none" &&
                    style.visibility !== "hidden" &&
                    rect.width > 0 &&
                    rect.height > 0
                );
            }

            function norm(value) {
                return String(value || "")
                    .replace(/\s+/g, " ")
                    .trim()
                    .toLowerCase();
            }

            function add(values, value) {
                const cleaned = norm(value);
                if (cleaned && !values.includes(cleaned)) values.push(cleaned);
            }

            const values = [];
            const item = control.closest?.(".el-form-item") ||
                         control.closest?.("tr") ||
                         control.parentElement || dialog;

            for (const root of [control, item]) {
                if (!root) continue;
                add(values, root.value);
                add(values, root.innerText);
                add(values, root.textContent);
                if (root.getAttribute) {
                    add(values, root.getAttribute("title"));
                    add(values, root.getAttribute("aria-label"));
                    add(values, root.getAttribute("aria-valuetext"));
                    add(values, root.getAttribute("data-value"));
                }

                for (const child of root.querySelectorAll(
                    "input,[role='combobox'],[role='option']," +
                    ".el-input__inner,.el-select__selected-item," +
                    ".selected,.is-selected,span,div"
                )) {
                    if (!visible(child)) continue;
                    add(values, child.value);
                    add(values, child.innerText);
                    add(values, child.textContent);
                    if (child.getAttribute) {
                        add(values, child.getAttribute("title"));
                        add(values, child.getAttribute("aria-label"));
                        add(values, child.getAttribute("aria-valuetext"));
                        add(values, child.getAttribute("data-value"));
                    }
                }
            }

            return {
                ok: values.some((value) => value === wanted),
                values: values.slice(0, 30)
            };
            """,
            control,
            dialog,
            desired,
        )

        if not verification.get("ok"):
            raise RuntimeError(
                f"User Type custom control was found, but {desired} could "
                f"not be verified after selection. Observed values="
                f"{verification.get('values', [])}"
            )

        print(
            f"[USER LEVEL] Selected and verified {desired} using "
            "Hikvision custom User Type control."
        )
        return True

    # ---------------------------------------------------------------
    # 4. Old UI: no editable level control. Operator is fixed/default.
    # ---------------------------------------------------------------
    print(
        f"[USER LEVEL] No editable User Type/Level control exposed by this "
        f"firmware; using its fixed/default {desired} level."
    )
    return False


def _resolve_live_permission_checkbox(
    driver,
    permission_label,
    dialog=None,
):
    """
    Resolve one permission checkbox from the CURRENT live Add User drawer.

    Hikvision/Vue can replace parts of the drawer after each permission click.
    Therefore callers must never keep a checkbox WebElement across retries.
    Every read/click attempt comes back through this resolver.
    """
    live_dialog = find_user_edit_dialog(
        driver,
        need_username=True,
    )

    if live_dialog is None:
        live_dialog = dialog

    if live_dialog is None:
        return None

    return driver.execute_script(
        r"""
        const dialog = arguments[0];
        const wantedRaw = String(arguments[1] || "");

        if (!dialog || !dialog.isConnected) return null;

        function norm(v) {
            return String(v || "")
                .replace(/\u2026/g, "")
                .replace(/\.\.\./g, "")
                .replace(/interrogation/gi, "interrogate")
                .replace(/parameters?\s+setting/gi, "parameters settings")
                .replace(/\s*\/\s*/g, " ")
                .toLowerCase()
                .replace(/[^a-z0-9]+/g, " ")
                .replace(/\s+/g, " ")
                .trim();
        }

        function rendered(el) {
            if (!el || !el.isConnected) return false;
            const s = window.getComputedStyle(el);
            const r = el.getBoundingClientRect();
            return (
                s.display !== "none" &&
                s.visibility !== "hidden" &&
                Number(s.opacity || "1") !== 0 &&
                r.width > 0 &&
                r.height > 0
            );
        }

        function rankText(text, wanted) {
            if (!text || !wanted) return null;
            if (text === wanted) return 0;
            if (text.startsWith(wanted) || wanted.startsWith(text)) {
                return 10 + Math.abs(text.length - wanted.length);
            }
            if (text.includes(wanted) || wanted.includes(text)) {
                return 100 + Math.abs(text.length - wanted.length);
            }

            const a = new Set(text.split(" ").filter(Boolean));
            const b = new Set(wanted.split(" ").filter(Boolean));
            let common = 0;
            for (const token of b) if (a.has(token)) common++;
            const ratio = common / Math.max(1, b.size);
            if (ratio >= 0.80) {
                return 250 + Math.round((1 - ratio) * 100);
            }
            return null;
        }

        function shortTextsAround(box) {
            const values = [];
            function add(raw, source, element) {
                const cleaned = norm(raw);
                if (!cleaned) return;
                if (cleaned.length > 180) return;
                values.push({text: cleaned, raw: String(raw || "").trim(), source, element});
            }

            if (box.id) {
                try {
                    const label = dialog.querySelector(
                        `label[for="${CSS.escape(box.id)}"]`
                    );
                    if (label) {
                        add(label.innerText || label.textContent, "for-label", label);
                    }
                } catch (_) {}
            }

            const closestLabel = box.closest("label");
            if (closestLabel) {
                add(
                    closestLabel.innerText || closestLabel.textContent,
                    "closest-label",
                    closestLabel
                );
            }

            let cur = box;
            for (let depth = 0; depth < 8 && cur && cur !== dialog; depth++) {
                cur = cur.parentElement;
                if (!cur) break;
                add(cur.innerText || cur.textContent, `ancestor-${depth}`, cur);
            }

            return values;
        }

        const wanted = norm(wantedRaw);
        const boxes = Array.from(
            dialog.querySelectorAll('input[type="checkbox"]')
        );

        const candidates = [];

        for (const box of boxes) {
            const texts = shortTextsAround(box);
            let best = null;

            for (const item of texts) {
                const rank = rankText(item.text, wanted);
                if (rank === null) continue;
                if (!best || rank < best.rank || (
                    rank === best.rank && item.text.length < best.text.length
                )) {
                    best = {...item, rank};
                }
            }

            if (!best) continue;

            let proxy = null;
            const label = box.closest("label");
            if (label && rendered(label)) proxy = label;

            if (!proxy) {
                let cur = box.parentElement;
                for (let depth = 0; depth < 6 && cur && cur !== dialog; depth++) {
                    const maybe =
                        cur.querySelector?.(".el-checkbox__inner") ||
                        cur.querySelector?.(".checkbox__inner") ||
                        cur.querySelector?.("label") ||
                        null;
                    if (maybe && rendered(maybe)) {
                        proxy = maybe;
                        break;
                    }
                    cur = cur.parentElement;
                }
            }

            const clickTarget =
                (rendered(box) ? box : null) ||
                proxy ||
                (best.element && rendered(best.element) ? best.element : null);

            candidates.push({
                checkbox: box,
                proxy: proxy,
                clickTarget: clickTarget,
                row: best.element,
                rawText: best.raw,
                text: best.text,
                rank: best.rank,
                checked: Boolean(box.checked),
                disabled: Boolean(box.disabled),
                nativeVisible: rendered(box),
                proxyVisible: rendered(proxy)
            });
        }

        candidates.sort((a, b) =>
            a.rank - b.rank ||
            a.text.length - b.text.length
        );

        if (!candidates.length) return null;

        const best = candidates[0];
        return {
            dialog: dialog,
            checkbox: best.checkbox,
            proxy: best.proxy,
            clickTarget: best.clickTarget,
            row: best.row,
            rawText: best.rawText,
            text: best.text,
            rank: best.rank,
            checked: best.checked,
            disabled: best.disabled,
            nativeVisible: best.nativeVisible,
            proxyVisible: best.proxyVisible,
            candidateCount: candidates.length
        };
        """,
        live_dialog,
        str(permission_label),
    )


def _permission_checkbox_state(
    driver,
    permission_label,
    dialog=None,
):
    match = _resolve_live_permission_checkbox(
        driver,
        permission_label,
        dialog,
    )

    if not match or match.get("checkbox") is None:
        return {
            "found": False,
            "checked": None,
            "disabled": False,
            "matchedText": "",
            "candidateCount": 0,
        }

    try:
        checked = bool(
            driver.execute_script(
                "return Boolean(arguments[0].checked);",
                match["checkbox"],
            )
        )
    except Exception:
        # Vue may have replaced the element between resolve and read. Re-resolve
        # once rather than using a stale property.
        match = _resolve_live_permission_checkbox(
            driver,
            permission_label,
            dialog,
        )
        if not match or match.get("checkbox") is None:
            return {
                "found": False,
                "checked": None,
                "disabled": False,
                "matchedText": "",
                "candidateCount": 0,
            }
        checked = bool(match.get("checked"))

    return {
        "found": True,
        "checked": checked,
        "disabled": bool(match.get("disabled")),
        "matchedText": match.get("rawText") or match.get("text", ""),
        "candidateCount": match.get("candidateCount", 1),
        "match": match,
    }


def _trusted_click_permission_target(
    driver,
    target,
):
    """Perform a real Chromium mouse click at the live target coordinates."""
    if target is None:
        return False

    try:
        coords = driver.execute_script(
            r"""
            const e = arguments[0];
            if (!e || !e.isConnected) return null;
            try { e.scrollIntoView({block:'center', inline:'nearest'}); } catch (_) {}
            const r = e.getBoundingClientRect();
            if (!r || r.width <= 0 || r.height <= 0) return null;
            return {
                x: r.left + Math.min(Math.max(r.width / 2, 2), Math.max(r.width - 2, 2)),
                y: r.top + Math.min(Math.max(r.height / 2, 2), Math.max(r.height - 2, 2))
            };
            """,
            target,
        )

        if not coords:
            return False

        x = float(coords["x"])
        y = float(coords["y"])

        driver.execute_cdp_cmd(
            "Input.dispatchMouseEvent",
            {"type": "mouseMoved", "x": x, "y": y},
        )
        driver.execute_cdp_cmd(
            "Input.dispatchMouseEvent",
            {
                "type": "mousePressed",
                "x": x,
                "y": y,
                "button": "left",
                "clickCount": 1,
            },
        )
        driver.execute_cdp_cmd(
            "Input.dispatchMouseEvent",
            {
                "type": "mouseReleased",
                "x": x,
                "y": y,
                "button": "left",
                "clickCount": 1,
            },
        )
        return True
    except Exception:
        return False


def _force_native_checkbox_state(
    driver,
    checkbox,
    desired,
):
    """
    Last-resort framework-compatible checkbox assignment.

    Use the native HTMLInputElement checked setter, then emit input/change.
    Vue/Angular listeners see the same events as a user action.  We never use
    this as proof of success; the live DOM is re-resolved and verified after it.
    """
    try:
        return bool(
            driver.execute_script(
                r"""
                const box = arguments[0];
                const desired = Boolean(arguments[1]);
                if (!box || !box.isConnected || box.disabled) return false;

                const descriptor = Object.getOwnPropertyDescriptor(
                    HTMLInputElement.prototype,
                    'checked'
                );

                if (descriptor && descriptor.set) {
                    descriptor.set.call(box, desired);
                } else {
                    box.checked = desired;
                }

                box.dispatchEvent(new Event('input', {bubbles:true}));
                box.dispatchEvent(new Event('change', {bubbles:true}));
                box.dispatchEvent(new Event('blur', {bubbles:true}));
                return Boolean(box.checked) === desired;
                """,
                checkbox,
                bool(desired),
            )
        )
    except Exception:
        return False


def set_select_all(driver, dialog):
    """Compatibility wrapper retained for older call sites."""
    return set_permission_checkbox_by_label(
        driver,
        dialog,
        "Select All",
        True,
    )


def set_permission_checkbox_by_label(driver, dialog, permission_label, desired):
    """
    Set one permission checkbox using fresh live DOM nodes on every attempt.

    v114 repair for the failures seen on .210/.211/.226/.227:
      - never cache a checkbox/proxy across Vue re-renders;
      - verify after every click method before moving on;
      - use trusted CDP click, Selenium/native click, DOM click, then a native
        checked-property setter + input/change events as controlled fallbacks;
      - re-resolve the exact label after every action;
      - disabled=False rights are accepted only when already unchecked;
      - no method is considered successful until the re-read state matches
        the Excel state.
    """
    desired = bool(desired)
    last_state = None

    for attempt in range(1, USER_MANAGEMENT_PERMISSION_CLICK_RETRIES + 1):
        state = _permission_checkbox_state(
            driver,
            permission_label,
            dialog,
        )
        last_state = state

        if not state.get("found"):
            return {
                "found": False,
                "checked": None,
                "matchedText": "",
                "candidateCount": 0,
                "attempts": attempt - 1,
            }

        if bool(state.get("checked")) == desired:
            return {
                "found": True,
                "checked": desired,
                "matchedText": state.get("matchedText", ""),
                "candidateCount": state.get("candidateCount", 1),
                "attempts": attempt - 1,
                "method": "already-correct",
            }

        if state.get("disabled"):
            # Disabled permissions cannot be changed through this UI.  A disabled
            # unchecked permission already satisfies Excel=No; any other mismatch
            # remains a real error and is returned for the caller to report.
            return {
                "found": True,
                "checked": bool(state.get("checked")),
                "matchedText": state.get("matchedText", ""),
                "candidateCount": state.get("candidateCount", 1),
                "attempts": attempt - 1,
                "disabled": True,
                "method": "disabled",
            }

        match = state.get("match") or {}
        checkbox = match.get("checkbox")
        target = (
            match.get("clickTarget")
            or match.get("proxy")
            or checkbox
        )

        # Method 1: trusted Chromium mouse event on the visible/native target.
        _trusted_click_permission_target(
            driver,
            target,
        )
        time_module.sleep(USER_MANAGEMENT_PERMISSION_CLICK_WAIT_SECONDS)
        verified = _permission_checkbox_state(
            driver,
            permission_label,
            dialog,
        )
        if verified.get("found") and bool(verified.get("checked")) == desired:
            return {
                "found": True,
                "checked": desired,
                "matchedText": verified.get("matchedText", ""),
                "candidateCount": verified.get("candidateCount", 1),
                "attempts": attempt,
                "method": "trusted-cdp-click",
            }

        # Method 2: Selenium/native element click on a freshly resolved box.
        refreshed = _permission_checkbox_state(
            driver,
            permission_label,
            dialog,
        )
        if refreshed.get("found"):
            live_match = refreshed.get("match") or {}
            live_box = live_match.get("checkbox")
            try:
                if live_box is not None:
                    live_box.click()
            except Exception:
                pass

        time_module.sleep(USER_MANAGEMENT_PERMISSION_CLICK_WAIT_SECONDS)
        verified = _permission_checkbox_state(
            driver,
            permission_label,
            dialog,
        )
        if verified.get("found") and bool(verified.get("checked")) == desired:
            return {
                "found": True,
                "checked": desired,
                "matchedText": verified.get("matchedText", ""),
                "candidateCount": verified.get("candidateCount", 1),
                "attempts": attempt,
                "method": "native-click",
            }

        # Method 3: DOM click.  This fires the browser's normal click/change
        # sequence and is effective on several old Hikvision Angular controls.
        refreshed = _permission_checkbox_state(
            driver,
            permission_label,
            dialog,
        )
        if refreshed.get("found"):
            live_match = refreshed.get("match") or {}
            live_box = live_match.get("checkbox")
            try:
                driver.execute_script(
                    "if (arguments[0] && arguments[0].isConnected) arguments[0].click();",
                    live_box,
                )
            except Exception:
                pass

        time_module.sleep(USER_MANAGEMENT_PERMISSION_CLICK_WAIT_SECONDS)
        verified = _permission_checkbox_state(
            driver,
            permission_label,
            dialog,
        )
        if verified.get("found") and bool(verified.get("checked")) == desired:
            return {
                "found": True,
                "checked": desired,
                "matchedText": verified.get("matchedText", ""),
                "candidateCount": verified.get("candidateCount", 1),
                "attempts": attempt,
                "method": "dom-click",
            }

        # Method 4: explicit native checked setter + framework events.
        refreshed = _permission_checkbox_state(
            driver,
            permission_label,
            dialog,
        )
        if refreshed.get("found"):
            live_match = refreshed.get("match") or {}
            live_box = live_match.get("checkbox")
            _force_native_checkbox_state(
                driver,
                live_box,
                desired,
            )

        time_module.sleep(max(0.30, USER_MANAGEMENT_PERMISSION_CLICK_WAIT_SECONDS))
        verified = _permission_checkbox_state(
            driver,
            permission_label,
            dialog,
        )
        if verified.get("found") and bool(verified.get("checked")) == desired:
            return {
                "found": True,
                "checked": desired,
                "matchedText": verified.get("matchedText", ""),
                "candidateCount": verified.get("candidateCount", 1),
                "attempts": attempt,
                "method": "native-setter-events",
            }

        last_state = verified

    final_state = _permission_checkbox_state(
        driver,
        permission_label,
        dialog,
    )
    if final_state.get("found"):
        return {
            "found": True,
            "checked": bool(final_state.get("checked")),
            "matchedText": final_state.get("matchedText", ""),
            "candidateCount": final_state.get("candidateCount", 1),
            "attempts": USER_MANAGEMENT_PERMISSION_CLICK_RETRIES,
            "disabled": bool(final_state.get("disabled")),
            "method": "exhausted",
        }

    return {
        "found": False,
        "checked": None,
        "matchedText": "",
        "candidateCount": 0,
        "attempts": USER_MANAGEMENT_PERMISSION_CLICK_RETRIES,
        "lastState": last_state,
    }


def apply_user_permission_profile(
    driver,
    dialog,
    account,
    permission_override=None,
):
    """
    Apply and then independently re-audit every Excel permission.

    Two-phase behavior prevents one Hikvision checkbox update from silently
    changing another permission or the master Select All state.
    """
    role = account["role"]

    profile = (
        permission_override
        if permission_override is not None
        else {
            "select_all": bool(account.get("select_all", False)),
            "permissions": dict(account.get("permissions", {}) or {}),
        }
    )

    select_all = bool(profile.get("select_all", False))
    permissions = dict(profile.get("permissions", {}) or {})

    print(
        f"[USER RIGHTS] {role}: applying Excel profile before Add User OK. "
        f"SelectAll={select_all}; configured rights={len(permissions)}."
    )

    # ------------------------------------------------------------------
    # ServiceAccount / Select All profile
    # ------------------------------------------------------------------
    if select_all:
        state = set_permission_checkbox_by_label(
            driver,
            dialog,
            "Select All",
            True,
        )

        if state.get("found") and state.get("checked"):
            time_module.sleep(0.35)
            verify_master = _permission_checkbox_state(
                driver,
                "Select All",
                dialog,
            )
            if verify_master.get("found") and verify_master.get("checked"):
                print(
                    f"[USER RIGHTS] {role}: Select All=Yes "
                    f"(method={state.get('method', '')})."
                )
                return {
                    "matched": ["Select All"],
                    "unmatched": [],
                    "not_exposed_false": [],
                    "configured": len(permissions),
                    "verified": True,
                }

        # Master checkbox can be unreliable on some firmware.  If Excel also
        # provides the individual rights, enforce every one as Yes and verify
        # them.  This is functionally equivalent to Select All and is safer than
        # failing a valid account solely because the master indicator did not
        # visually latch.
        if permissions:
            false_rights = [
                label
                for label, desired in permissions.items()
                if not bool(desired)
            ]
            if false_rights:
                raise RuntimeError(
                    f"{role}: Select All=Yes conflicts with individual Excel=No "
                    f"rights: {false_rights}"
                )

            print(
                f"[USER RIGHTS REPAIR] {role}: Select All master checkbox did "
                "not latch; enforcing all individual Excel rights as Yes."
            )

            individual_errors = []
            for permission_label in permissions:
                item = set_permission_checkbox_by_label(
                    driver,
                    dialog,
                    permission_label,
                    True,
                )
                if (
                    not item.get("found")
                    or not bool(item.get("checked"))
                ):
                    individual_errors.append({
                        "permission": permission_label,
                        "actual": item.get("checked"),
                        "matchedText": item.get("matchedText", ""),
                        "disabled": item.get("disabled", False),
                    })

            if not individual_errors:
                # One last attempt to make the master indicator reflect the
                # effective all-rights state, but do not depend on it anymore.
                set_permission_checkbox_by_label(
                    driver,
                    dialog,
                    "Select All",
                    True,
                )
                print(
                    f"[USER RIGHTS] {role}: all individual Excel rights are "
                    "verified Yes; effective Select All achieved."
                )
                return {
                    "matched": list(permissions.keys()),
                    "unmatched": [],
                    "not_exposed_false": [],
                    "configured": len(permissions),
                    "verified": True,
                    "effective_select_all": True,
                }

            raise RuntimeError(
                f"{role}: Select All did not become checked and individual "
                f"all-rights fallback also failed: {individual_errors}"
            )

        raise RuntimeError(
            f"{role}: Select All did not become checked and no individual "
            "permission matrix was available for safe fallback."
        )

    # ------------------------------------------------------------------
    # Non-Select-All profiles: clear master first, then apply each right.
    # ------------------------------------------------------------------
    select_all_state = set_permission_checkbox_by_label(
        driver,
        dialog,
        "Select All",
        False,
    )

    if select_all_state.get("found") and select_all_state.get("checked"):
        raise RuntimeError(
            f"{role}: Select All could not be cleared."
        )

    matched = []
    missing_required_yes = []
    not_exposed_false = []
    first_pass_errors = []

    for permission_label, desired in permissions.items():
        desired = bool(desired)
        state = set_permission_checkbox_by_label(
            driver,
            dialog,
            permission_label,
            desired,
        )

        if not state.get("found"):
            if desired:
                missing_required_yes.append(permission_label)
                print(
                    f"[USER RIGHTS ERROR] {role}: required Excel=Yes "
                    f"permission is not exposed by this firmware: "
                    f"{permission_label}"
                )
            else:
                not_exposed_false.append(permission_label)
                print(
                    f"[USER RIGHTS] {role}: {permission_label}=No; checkbox "
                    "is not exposed by this firmware -> NOT APPLICABLE / "
                    "effectively disabled."
                )
            continue

        actual = bool(state.get("checked"))
        if actual != desired:
            first_pass_errors.append(permission_label)
            print(
                f"[USER RIGHTS REPAIR] {role}: {permission_label} first pass "
                f"ended at {'Yes' if actual else 'No'}; expected "
                f"{'Yes' if desired else 'No'}. A fresh second pass will run."
            )
        else:
            matched.append(permission_label)
            print(
                f"[USER RIGHTS] {role}: "
                f"{permission_label}={'Yes' if desired else 'No'}; "
                f"matched UI row='{state.get('matchedText', '')}'; "
                f"method={state.get('method', '')}."
            )

    if missing_required_yes:
        raise RuntimeError(
            f"{role}: {len(missing_required_yes)} required Excel=Yes "
            f"permission labels were not found in the device UI: "
            f"{missing_required_yes}"
        )

    # Allow framework watchers to finish before the independent audit.
    time_module.sleep(0.40)

    verification_errors = []

    for permission_label, desired in permissions.items():
        if permission_label in not_exposed_false:
            continue

        desired = bool(desired)
        # This second pass both audits and repairs from a completely fresh DOM
        # lookup.  It catches cross-checkbox side effects and Vue re-renders.
        state = set_permission_checkbox_by_label(
            driver,
            dialog,
            permission_label,
            desired,
        )

        if (
            not state.get("found")
            or bool(state.get("checked")) != desired
        ):
            verification_errors.append({
                "permission": permission_label,
                "expected": desired,
                "actual": state.get("checked"),
                "matchedText": state.get("matchedText", ""),
                "disabled": state.get("disabled", False),
                "method": state.get("method", ""),
            })

    # Verify the master remains OFF for a mixed permission profile.
    master_final = _permission_checkbox_state(
        driver,
        "Select All",
        dialog,
    )
    if master_final.get("found") and master_final.get("checked"):
        verification_errors.append({
            "permission": "Select All",
            "expected": False,
            "actual": True,
            "matchedText": master_final.get("matchedText", ""),
            "method": "final-master-audit",
        })

    if verification_errors:
        raise RuntimeError(
            f"{role}: final permission verification failed before "
            f"Add User OK after live-DOM repair: {verification_errors}"
        )

    print(
        f"[USER RIGHTS] {role}: final Excel rights verification PASSED. "
        f"Matched={len(permissions) - len(not_exposed_false)}; "
        f"NotApplicableNo={len(not_exposed_false)}."
    )

    return {
        "matched": [
            label for label in permissions
            if label not in not_exposed_false
        ],
        "unmatched": [],
        "not_exposed_false": not_exposed_false,
        "configured": len(permissions),
        "verified": True,
    }

def click_user_dialog_ok(driver, dialog, method="cdp"):
    """Dispatch one exact Add User footer click; backend decides success."""
    button = driver.execute_script(
        r"""
        const dialog = arguments[0];
        if (!dialog || !dialog.isConnected) return null;
        function visible(element) {
            if (!element || !element.isConnected) return false;
            const style = window.getComputedStyle(element);
            const rect = element.getBoundingClientRect();
            return style.display !== "none" && style.visibility !== "hidden" &&
                   Number(style.opacity || "1") !== 0 && rect.width > 0 && rect.height > 0;
        }
        function norm(value) { return String(value || "").replace(/\s+/g, " ").trim().toLowerCase(); }
        const candidates = Array.from(dialog.querySelectorAll(
            "button,input[type='button'],input[type='submit'],a,[role='button']"
        )).filter((element) => {
            if (!visible(element) || element.disabled) return false;
            return ["ok", "save", "confirm"].includes(norm(
                element.innerText || element.value || element.textContent || ""
            ));
        });
        if (!candidates.length) return null;
        candidates.sort((a, b) => {
            const ar = a.getBoundingClientRect();
            const br = b.getBoundingClientRect();
            return br.top - ar.top || br.left - ar.left;
        });
        return candidates[0];
        """,
        dialog,
    )
    if button is None:
        raise RuntimeError("User Management dialog OK button was not found inside the exact dialog.")
    try:
        driver.execute_script("arguments[0].scrollIntoView({block:'center',inline:'center'});", button)
        time_module.sleep(0.08)
    except Exception:
        pass

    if method == "cdp":
        coords = driver.execute_script(
            """const e=arguments[0],r=e.getBoundingClientRect(); return {x:r.left+r.width/2,y:r.top+r.height/2};""",
            button,
        )
        x=float(coords['x']); y=float(coords['y'])
        driver.execute_cdp_cmd('Input.dispatchMouseEvent', {'type':'mouseMoved','x':x,'y':y,'button':'none'})
        driver.execute_cdp_cmd('Input.dispatchMouseEvent', {'type':'mousePressed','x':x,'y':y,'button':'left','buttons':1,'clickCount':1})
        driver.execute_cdp_cmd('Input.dispatchMouseEvent', {'type':'mouseReleased','x':x,'y':y,'button':'left','buttons':0,'clickCount':1})
    elif method == "native":
        button.click()
    elif method == "actionchains":
        ActionChains(driver).move_to_element(button).pause(0.1).click(button).perform()
    elif method == "javascript":
        driver.execute_script(
            """
            const e=arguments[0],r=e.getBoundingClientRect();
            const x=r.left+r.width/2,y=r.top+r.height/2,target=document.elementFromPoint(x,y)||e;
            target.dispatchEvent(new MouseEvent('mousedown',{view:window,bubbles:true,cancelable:true,button:0,buttons:1,clientX:x,clientY:y}));
            target.dispatchEvent(new MouseEvent('mouseup',{view:window,bubbles:true,cancelable:true,button:0,buttons:0,clientX:x,clientY:y}));
            target.dispatchEvent(new MouseEvent('click',{view:window,bubbles:true,cancelable:true,button:0,detail:1,clientX:x,clientY:y}));
            """,
            button,
        )
    elif method == "keyboard":
        try:
            driver.execute_script("arguments[0].focus();", button)
        except Exception:
            pass
        button.send_keys(Keys.ENTER)
    else:
        raise ValueError(f"Unknown Add User submit click method: {method}")

    print(f"[USER MANAGEMENT SUBMIT] Add User footer dispatched using method={method}; backend verification required.")
    return True



def get_user_dialog_validation_diagnostics(driver, dialog=None):
    """
    Return ONLY validation errors that belong to the active Add User form.

    v108 explicitly ignores Old Password / generic Modify-password controls.
    Those controls are not valid Add User fields and must never drive an Add
    User retry/failure decision.
    """
    if dialog is None:
        return []

    try:
        return driver.execute_script(
            r"""
            const dialog = arguments[0];
            if (!dialog || !dialog.isConnected) return [];

            function visible(element) {
                if (!element || !element.isConnected) return false;
                const style = window.getComputedStyle(element);
                const rect = element.getBoundingClientRect();
                return (
                    style.display !== "none" &&
                    style.visibility !== "hidden" &&
                    Number(style.opacity || "1") !== 0 &&
                    rect.width > 0 &&
                    rect.height > 0
                );
            }

            function clean(value) {
                return String(value || "").replace(/\s+/g, " ").trim();
            }

            function norm(value) {
                return clean(value)
                    .replace(/[\*：:]+\s*$/, "")
                    .trim()
                    .toLowerCase();
            }

            const allowedLabels = new Set([
                "user name", "username", "user type", "level", "user level",
                "admin password", "new password", "password confirm", "confirm password", "confirm"
            ]);

            const errors = [];
            const nodes = Array.from(
                dialog.querySelectorAll(
                    ".el-form-item__error,.error-message,.error,[role='alert']"
                )
            ).filter(visible);

            for (const node of nodes) {
                const message = clean(node.innerText || node.textContent || "");
                if (!message) continue;

                const item =
                    node.closest(".el-form-item") ||
                    node.closest("tr") ||
                    node.parentElement;

                let label = "";
                if (item) {
                    const labelNode = item.querySelector(
                        ".el-form-item__label,label,.label,th,td:first-child"
                    );
                    if (labelNode) {
                        label = clean(labelNode.innerText || labelNode.textContent)
                            .replace(/[\*：:]+\s*$/, "")
                            .trim();
                    }
                }

                const normalizedLabel = norm(label);
                const itemText = norm(item ? (item.innerText || item.textContent || "") : "");

                // Never let a Modify/Change Password form contaminate Add User.
                if (
                    normalizedLabel.includes("old password") ||
                    itemText.includes("old password")
                ) {
                    continue;
                }

                if (!allowedLabels.has(normalizedLabel)) {
                    continue;
                }

                const input = item
                    ? item.querySelector("input,textarea,[role='combobox']")
                    : null;

                const type = input
                    ? String(
                        input.getAttribute("type") ||
                        input.getAttribute("role") ||
                        input.tagName || ""
                    ).toLowerCase()
                    : "";

                const hasValue = input
                    ? clean(
                        input.value ||
                        input.getAttribute("aria-valuetext") ||
                        input.getAttribute("data-value") || ""
                    ) !== ""
                    : false;

                errors.push({
                    label: label || "Unknown field",
                    message: message,
                    inputType: type,
                    hasDomValue: hasValue
                });
            }

            return errors;
            """,
            dialog,
        ) or []
    except Exception:
        return []


def get_add_user_dialog_field_state(driver, dialog):
    """Return non-secret Add User field occupancy for diagnostics only."""
    try:
        return driver.execute_script(
            r"""
            const dialog = arguments[0];
            if (!dialog || !dialog.isConnected) return {connected:false};

            function visible(element) {
                if (!element || !element.isConnected) return false;
                const style = window.getComputedStyle(element);
                const rect = element.getBoundingClientRect();
                return (
                    style.display !== 'none' &&
                    style.visibility !== 'hidden' &&
                    Number(style.opacity || '1') !== 0 &&
                    rect.width > 0 && rect.height > 0
                );
            }

            const inputs = Array.from(dialog.querySelectorAll('input')).filter(visible);
            const passwords = inputs.filter(
                (input) => String(input.type || '').toLowerCase() === 'password'
            );
            const texts = inputs.filter((input) => {
                const type = String(input.type || 'text').toLowerCase();
                return !['password','hidden','checkbox','radio','button','submit'].includes(type);
            });

            return {
                connected: true,
                usernameHasValue: Boolean(texts[0] && String(texts[0].value || '').length),
                passwordFieldCount: passwords.length,
                passwordHasValues: passwords.slice(0, 3).map(
                    (input) => Boolean(String(input.value || '').length)
                ),
                text: String(dialog.innerText || dialog.textContent || '')
                    .replace(/\s+/g, ' ').trim().slice(0, 220)
            };
            """,
            dialog,
        ) or {}
    except Exception:
        return {}


def get_visible_user_management_messages(driver, dialog=None):
    """Collect short visible non-secret UI messages outside/inside the drawer."""
    try:
        return driver.execute_script(
            r"""
            const dialog = arguments[0];
            function visible(element) {
                if (!element || !element.isConnected) return false;
                const style = window.getComputedStyle(element);
                const rect = element.getBoundingClientRect();
                return (
                    style.display !== 'none' &&
                    style.visibility !== 'hidden' &&
                    Number(style.opacity || '1') !== 0 &&
                    rect.width > 0 && rect.height > 0
                );
            }
            const selectors = [
                '.el-message','.el-notification','.el-message-box',
                '[role="alert"]','.error-message'
            ];
            const values = [];
            for (const node of document.querySelectorAll(selectors.join(','))) {
                if (!visible(node)) continue;
                const text = String(node.innerText || node.textContent || '')
                    .replace(/\s+/g, ' ').trim();
                if (!text) continue;
                if (/password/i.test(text) && /required/i.test(text) && dialog && !dialog.contains(node)) {
                    // unrelated password form outside exact Add User drawer
                    continue;
                }
                if (!values.includes(text)) values.push(text.slice(0, 240));
            }
            return values.slice(0, 8);
            """,
            dialog,
        ) or []
    except Exception:
        return []


def dismiss_stale_add_user_dialog(driver, dialog):
    """Close a stale Add User drawer only after backend confirms creation."""
    if dialog is None:
        return False
    try:
        button = driver.execute_script(
            r"""
            const dialog = arguments[0];
            if (!dialog || !dialog.isConnected) return null;
            function visible(el) {
                if (!el || !el.isConnected) return false;
                const s = window.getComputedStyle(el), r = el.getBoundingClientRect();
                return s.display !== 'none' && s.visibility !== 'hidden' && r.width > 0 && r.height > 0;
            }
            function norm(v) { return String(v || '').replace(/\s+/g,' ').trim().toLowerCase(); }
            const candidates = Array.from(dialog.querySelectorAll(
                "button,a,[role='button'],.el-drawer__close-btn,.el-dialog__headerbtn"
            )).filter(visible);
            return candidates.find((el) => ['cancel','close'].includes(norm(el.innerText || el.textContent))) ||
                   candidates.find((el) => /close|drawer__close|headerbtn/.test(String(el.className || '').toLowerCase())) ||
                   null;
            """,
            dialog,
        )
        if button is None:
            return False
        try:
            button.click()
        except Exception:
            driver.execute_script('arguments[0].click();', button)
        return True
    except Exception:
        return False

def wait_user_dialog_gone(
    driver,
    submitted_dialog=None,
    *,
    expect_add_user=False,
):
    """
    Legacy close-wait helper.

    Add User creation in v108 no longer uses this as the success authority; it
    uses wait_for_add_user_backend_result() so unrelated SPA dialogs cannot cause
    false validation failures.  This function remains for Modify-user workflows.
    """
    deadline = time_module.monotonic() + USER_MANAGEMENT_DIALOG_WAIT_SECONDS
    tracked = submitted_dialog

    while time_module.monotonic() < deadline:
        if tracked is None:
            return True

        try:
            visible = bool(
                driver.execute_script(
                    r"""
                    const el = arguments[0];
                    if (!el || !el.isConnected) return false;
                    const s = window.getComputedStyle(el), r = el.getBoundingClientRect();
                    return s.display !== 'none' && s.visibility !== 'hidden' &&
                           Number(s.opacity || '1') !== 0 && r.width > 0 && r.height > 0;
                    """,
                    tracked,
                )
            )
        except Exception:
            visible = False

        if not visible:
            return True

        if expect_add_user:
            diagnostics = get_user_dialog_validation_diagnostics(driver, tracked)
            if diagnostics:
                readable = "; ".join(
                    f"{item.get('label', 'Unknown field')}: {item.get('message', '')} "
                    f"(DOM has value={item.get('hasDomValue')})"
                    for item in diagnostics
                )
                raise RuntimeError(f"Add User validation error: {readable}")

        time_module.sleep(0.35)

    raise RuntimeError("User Management dialog did not close after clicking OK.")


def poll_add_user_backend_created(row, username, before_snapshot, timeout=3.0):
    """Poll /ISAPI/Security/users after one submit click before any re-click."""
    before_count = before_snapshot.get("count")
    deadline = time_module.monotonic() + max(0.5, float(timeout))
    last = None
    while time_module.monotonic() < deadline:
        last = get_isapi_user_snapshot(row)
        usernames = set(last.get("usernames", []))
        after_count = last.get("count")
        if username in usernames:
            return True, "ISAPI username readback", last
        if before_count is not None and after_count is not None and after_count > before_count:
            return True, f"backend user count {before_count}->{after_count}", last
        time_module.sleep(0.35)
    return False, "", last


def wait_for_add_user_backend_result(
    driver,
    row,
    account,
    before_snapshot,
    submitted_dialog,
):
    """
    v108 Add User submission authority.

    After ONE click on the exact Add User footer:
      1) poll /ISAPI/Security/users first;
      2) if username/count confirms creation -> SUCCESS immediately;
      3) inspect validation ONLY inside a strict Add User drawer;
      4) never refill/re-submit the same account in a blind loop.
    """
    username = account["username"]
    before_count = before_snapshot.get("count")
    deadline = time_module.monotonic() + max(
        USER_MANAGEMENT_ADD_SUBMIT_TIMEOUT_SECONDS,
        USER_MANAGEMENT_VERIFY_SECONDS,
    )

    last_snapshot = None
    last_dialog = submitted_dialog
    last_state = {}
    last_messages = []

    while time_module.monotonic() < deadline:
        after = get_isapi_user_snapshot(row)
        last_snapshot = after
        usernames = set(after.get("usernames", []))
        after_count = after.get("count")

        if username in usernames or (
            before_count is not None and
            after_count is not None and
            after_count > before_count
        ):
            proof = (
                "ISAPI username readback"
                if username in usernames
                else f"backend user count {before_count}->{after_count}"
            )

            # If Vue left a stale drawer open despite backend success, dismiss it
            # so the next account can be created normally.
            live = find_user_edit_dialog(driver, need_username=True)
            if live is not None:
                if dismiss_stale_add_user_dialog(driver, live):
                    print(
                        f"[USER MANAGEMENT SUBMIT] {username}: backend creation "
                        "confirmed; closed stale Add User drawer."
                    )

            # Old Hikvision firmware can show a second "Save succeeded."
            # Note after Add User.  Dismiss it before the next role starts.
            dismiss_hikvision_success_note(
                driver,
                timeout=2.0,
                label=f"Add User {username} success",
            )
            return True, proof

        # Only a STRICT Add User drawer may provide validation diagnostics.
        live = find_user_edit_dialog(driver, need_username=True)
        if live is not None:
            last_dialog = live
            diagnostics = get_user_dialog_validation_diagnostics(driver, live)
            last_state = get_add_user_dialog_field_state(driver, live)
            last_messages = get_visible_user_management_messages(driver, live)

            if diagnostics:
                readable = "; ".join(
                    f"{item.get('label', 'Unknown field')}: {item.get('message', '')} "
                    f"(DOM has value={item.get('hasDomValue')})"
                    for item in diagnostics
                )
                raise RuntimeError(
                    f"Add User validation error: {readable}. "
                    "No automatic re-entry/re-submit was performed."
                )

        time_module.sleep(0.5)

    # No backend success. Do not start another automatic same-account submit.
    after_count = last_snapshot.get("count") if last_snapshot else None
    status = last_snapshot.get("status") if last_snapshot else None
    raise RuntimeError(
        "Add User was clicked once but backend creation was not confirmed. "
        f"User={username}; beforeCount={before_count}; afterCount={after_count}; "
        f"ISAPIstatus={status}; addUserFieldState={last_state}; "
        f"visibleMessages={last_messages}. "
        "The script intentionally stopped instead of repeatedly entering the same data."
    )

def verify_login_credential(
    ip,
    username,
    password,
):
    """
    Verify the credential itself through SessionLogin.

    Do not require /ISAPI/System/deviceInfo here: newly-created Operator users
    can authenticate successfully while Hikvision temporarily restricts normal
    ISAPI resources until their forced first password change is completed.
    """
    try:
        session = HikvisionSession(
            ip,
            username,
            password,
        )
        session.login(validate_device_info=False)
        return True, ""
    except Exception as error:
        detail = str(error).strip() or repr(error)
        return False, detail



def _set_direct_permission_child(
    parent,
    field_name,
    desired,
):
    child = direct_child_by_local_name(
        parent,
        field_name,
    )

    if child is None:
        raise RuntimeError(
            f"NVR UserPermission XML missing field "
            f"{field_name} under "
            f"{parent.tag.split('}')[-1]}."
        )

    child.text = (
        "true"
        if desired
        else "false"
    )


def apply_nvr_permission_values_to_xml(
    xml_text,
    profile,
):
    """
    Modify the NVR's existing UserPermission XML in place.

    This preserves:
      - UserPermission version/schema
      - user ID/user type
      - actual number of video/PTZ channel entries
      - any firmware-specific fields not managed by this workbook
    """
    root = ET.fromstring(
        xml_text
    )

    local_permission = (
        direct_child_by_local_name(
            root,
            "localPermission",
        )
    )

    remote_permission = (
        direct_child_by_local_name(
            root,
            "remotePermission",
        )
    )

    if local_permission is None:
        raise RuntimeError(
            "NVR UserPermission XML has no localPermission."
        )

    if remote_permission is None:
        raise RuntimeError(
            "NVR UserPermission XML has no remotePermission."
        )

    sections = {
        "local": local_permission,
        "remote": remote_permission,
    }

    for (
        permission_scope,
        field_name,
        channel_type,
    ), desired in profile.items():
        section_key = str(
            permission_scope
        ).strip().lower()

        section = sections.get(
            section_key
        )

        if section is None:
            raise RuntimeError(
                f"Unsupported NVR Permission Scope: "
                f"{permission_scope}"
            )

        channel_type_normalized = str(
            channel_type
        ).strip().lower()

        if channel_type_normalized == "root":
            _set_direct_permission_child(
                section,
                field_name,
                desired,
            )
            continue

        if channel_type_normalized == "videochannel":
            container = (
                direct_child_by_local_name(
                    section,
                    "videoChannelPermissionList",
                )
            )

            if container is None:
                raise RuntimeError(
                    f"NVR UserPermission XML missing "
                    f"videoChannelPermissionList in "
                    f"{permission_scope}."
                )

            channel_nodes = [
                element
                for element in list(container)
                if (
                    element.tag.split("}")[-1]
                    == "videoChannelPermission"
                )
            ]

            if not channel_nodes:
                raise RuntimeError(
                    f"NVR UserPermission contains no video "
                    f"channel permissions in {permission_scope}."
                )

            for channel_node in channel_nodes:
                _set_direct_permission_child(
                    channel_node,
                    field_name,
                    desired,
                )

            continue

        if channel_type_normalized == "ptzchannel":
            container = (
                direct_child_by_local_name(
                    section,
                    "ptzChannelPermissionList",
                )
            )

            if container is None:
                raise RuntimeError(
                    f"NVR UserPermission XML missing "
                    f"ptzChannelPermissionList in "
                    f"{permission_scope}."
                )

            channel_nodes = [
                element
                for element in list(container)
                if (
                    element.tag.split("}")[-1]
                    == "ptzChannelPermission"
                )
            ]

            if not channel_nodes:
                raise RuntimeError(
                    f"NVR UserPermission contains no PTZ "
                    f"channel permissions in {permission_scope}."
                )

            for channel_node in channel_nodes:
                _set_direct_permission_child(
                    channel_node,
                    field_name,
                    desired,
                )

            continue

        raise RuntimeError(
            f"Unsupported NVR Channel Field Type: "
            f"{channel_type}"
        )

    register_default_namespace(
        root
    )

    return ET.tostring(
        root,
        encoding="unicode",
    )


def read_nvr_permission_values_from_xml(
    xml_text,
    profile,
):
    """
    Return verification mismatches for the workbook-controlled NVR rights.
    """
    root = ET.fromstring(
        xml_text
    )

    local_permission = (
        direct_child_by_local_name(
            root,
            "localPermission",
        )
    )

    remote_permission = (
        direct_child_by_local_name(
            root,
            "remotePermission",
        )
    )

    sections = {
        "local": local_permission,
        "remote": remote_permission,
    }

    mismatches = []

    def bool_text(element):
        return str(
            element.text
            or ""
        ).strip().lower() in {
            "true",
            "1",
            "yes",
        }

    for (
        permission_scope,
        field_name,
        channel_type,
    ), desired in profile.items():
        section = sections.get(
            str(permission_scope).strip().lower()
        )

        if section is None:
            mismatches.append(
                {
                    "scope": permission_scope,
                    "field": field_name,
                    "channelType": channel_type,
                    "error": "section missing",
                }
            )
            continue

        channel_type_normalized = str(
            channel_type
        ).strip().lower()

        if channel_type_normalized == "root":
            child = direct_child_by_local_name(
                section,
                field_name,
            )

            if child is None:
                mismatches.append(
                    {
                        "scope": permission_scope,
                        "field": field_name,
                        "channelType": channel_type,
                        "error": "field missing",
                    }
                )
            elif bool_text(child) != bool(desired):
                mismatches.append(
                    {
                        "scope": permission_scope,
                        "field": field_name,
                        "channelType": channel_type,
                        "expected": bool(desired),
                        "actual": bool_text(child),
                    }
                )

            continue

        if channel_type_normalized == "videochannel":
            container = direct_child_by_local_name(
                section,
                "videoChannelPermissionList",
            )

            nodes = (
                []
                if container is None
                else [
                    element
                    for element in list(container)
                    if (
                        element.tag.split("}")[-1]
                        == "videoChannelPermission"
                    )
                ]
            )

        elif channel_type_normalized == "ptzchannel":
            container = direct_child_by_local_name(
                section,
                "ptzChannelPermissionList",
            )

            nodes = (
                []
                if container is None
                else [
                    element
                    for element in list(container)
                    if (
                        element.tag.split("}")[-1]
                        == "ptzChannelPermission"
                    )
                ]
            )

        else:
            mismatches.append(
                {
                    "scope": permission_scope,
                    "field": field_name,
                    "channelType": channel_type,
                    "error": "unsupported channel type",
                }
            )
            continue

        if not nodes:
            mismatches.append(
                {
                    "scope": permission_scope,
                    "field": field_name,
                    "channelType": channel_type,
                    "error": "no channel nodes",
                }
            )
            continue

        for node in nodes:
            channel_id = ""
            id_node = direct_child_by_local_name(
                node,
                "id",
            )

            if id_node is not None:
                channel_id = str(
                    id_node.text
                    or ""
                ).strip()

            child = direct_child_by_local_name(
                node,
                field_name,
            )

            if child is None:
                mismatches.append(
                    {
                        "scope": permission_scope,
                        "field": field_name,
                        "channelType": channel_type,
                        "channel": channel_id,
                        "error": "field missing",
                    }
                )
                continue

            actual = bool_text(
                child
            )

            if actual != bool(desired):
                mismatches.append(
                    {
                        "scope": permission_scope,
                        "field": field_name,
                        "channelType": channel_type,
                        "channel": channel_id,
                        "expected": bool(desired),
                        "actual": actual,
                    }
                )

    return mismatches


def apply_nvr_user_permission_profile(
    row,
    account,
    nvr_rights_profiles,
):
    """
    Apply and verify one exact NVR permission profile.

    Uses administrator credentials from the NVR_Settings row.
    """
    ip = get_value(
        row,
        "Current IP",
    )

    username = get_value(
        row,
        "Username",
    )

    password = get_value(
        row,
        "Password",
    )

    role = account["role"]

    if role not in nvr_rights_profiles:
        return (
            False,
            f"NVR rights profile missing for role {role}.",
        )

    profile = nvr_rights_profiles[
        role
    ]

    user_id = resolve_user_id_for_rotation(
        row,
        account["username"],
    )

    endpoint = (
        f"/ISAPI/Security/UserPermission/{user_id}"
    )

    get_status, current_xml = get_xml(
        ip,
        username,
        password,
        endpoint,
    )

    if get_status != 200:
        return (
            False,
            (
                f"NVR UserPermission GET failed for "
                f"{role}/ID {user_id}: HTTP {get_status}; "
                f"response={safe_preview(current_xml)}"
            ),
        )

    try:
        payload = apply_nvr_permission_values_to_xml(
            current_xml,
            profile,
        )
    except Exception as error:
        return (
            False,
            f"NVR UserPermission payload build failed: {error}",
        )

    put_status, put_response = put_xml(
        ip,
        username,
        password,
        endpoint,
        payload,
    )

    if put_status not in {
        200,
        204,
    }:
        return (
            False,
            (
                f"NVR UserPermission PUT failed for "
                f"{role}/ID {user_id}: HTTP {put_status}; "
                f"response={safe_preview(put_response)}"
            ),
        )

    # Explicit non-success ResponseStatus is a failure.
    try:
        fields = parse_status_fields(
            put_response
        )

        status_code = str(
            fields.get(
                "status_code",
                "",
            )
            or ""
        ).strip()

        if (
            status_code
            and status_code != "1"
        ):
            return (
                False,
                (
                    f"NVR UserPermission PUT rejected for {role}: "
                    f"statusCode={status_code}; "
                    f"statusString={fields.get('status_string', '')}; "
                    f"subStatusCode={fields.get('sub_status_code', '')}"
                ),
            )

    except Exception:
        # Some firmware returns an empty/alternate success body after PUT.
        pass

    time_module.sleep(
        0.5
    )

    verify_status, verify_xml = get_xml(
        ip,
        username,
        password,
        endpoint,
    )

    if verify_status != 200:
        return (
            False,
            (
                f"NVR UserPermission verification GET failed for "
                f"{role}: HTTP {verify_status}; "
                f"response={safe_preview(verify_xml)}"
            ),
        )

    mismatches = (
        read_nvr_permission_values_from_xml(
            verify_xml,
            profile,
        )
    )

    if mismatches:
        return (
            False,
            (
                f"NVR UserPermission verification mismatch for "
                f"{role}: {mismatches[:12]}"
            ),
        )

    print(
        f"[OK] NVR user rights verified: {ip} / "
        f"{role} / user ID {user_id}."
    )

    return (
        True,
        (
            f"Exact NVR local/remote rights applied and verified "
            f"for user ID {user_id}."
        ),
    )


def verify_user_created(
    driver,
    row,
    account,
    before_snapshot,
):
    """
    Verify Add User primarily through the backend. This is much faster than
    refreshing/reopening Configuration after every user and avoids the stale
    User List false negative.
    """
    username = account["username"]
    before_count = before_snapshot.get("count")

    deadline = (
        time_module.monotonic()
        + USER_MANAGEMENT_VERIFY_SECONDS
    )

    last_snapshot = None
    last_login_error = ""

    while time_module.monotonic() < deadline:
        after = get_isapi_user_snapshot(
            row
        )
        last_snapshot = after

        if username in set(
            after.get(
                "usernames",
                [],
            )
        ):
            return True, "ISAPI username readback"

        after_count = after.get("count")

        if (
            before_count is not None
            and after_count is not None
            and after_count > before_count
        ):
            return (
                True,
                f"backend user count {before_count}->{after_count}",
            )

        # Credential login is only a secondary proof when workflow policy
        # allows it. ServiceAccount never uses login verification, and NVR
        # L2VA also must not be logged in/relogged for verification.
        if user_account_login_verification_required(
            row,
            account,
        ):
            login_ok, login_error = verify_login_credential(
                get_value(row, "Current IP"),
                username,
                account["initial_password"],
            )

            if login_ok:
                return True, "initial-password login"

            last_login_error = login_error

        else:
            last_login_error = (
                f"{account.get('role')} login verification "
                "intentionally skipped by workflow policy."
            )

        time_module.sleep(0.5)

    # One final UI refresh only after backend verification failed.
    try:
        refresh_user_management_page(
            driver,
            row,
        )

        if username_visible_in_user_list(
            driver,
            username,
        ):
            return True, "refreshed UI User List"
    except Exception:
        pass

    return (
        False,
        (
            f"Add User could not be confirmed. "
            f"beforeCount={before_count}; "
            f"afterCount="
            f"{last_snapshot.get('count') if last_snapshot else None}; "
            f"ISAPIstatus="
            f"{last_snapshot.get('status') if last_snapshot else None}; "
            f"loginDetail={last_login_error}"
        ),
    )


def verify_web_input_exact_value(
    driver,
    element,
    expected_value,
    field_name,
    *,
    secret=True,
):
    """
    Verify the actual browser input value exactly without printing secrets.

    This confirms:
      - no leading/trailing normal whitespace
      - no leading/trailing NBSP / zero-width / BOM
      - exact character-for-character equality with the sanitized Excel value
    """
    expected_value = sanitize_credential_boundary(
        expected_value,
        field_name,
        secret=secret,
    )

    actual_value = driver.execute_script(
        "return String(arguments[0].value || '');",
        element,
    )

    boundary_invisible = (
        "\u200b"
        "\u200c"
        "\u200d"
        "\ufeff"
    )

    if (
        actual_value
        and (
            actual_value != actual_value.strip()
            or actual_value[0] in boundary_invisible
            or actual_value[-1] in boundary_invisible
        )
    ):
        raise RuntimeError(
            f"{field_name}: browser field contains leading/trailing "
            "whitespace or invisible characters."
        )

    if actual_value != expected_value:
        raise RuntimeError(
            f"{field_name}: browser value does not exactly match the "
            f"sanitized Excel value. Expected length={len(expected_value)}, "
            f"actual length={len(actual_value)}."
        )

    if secret:
        print(
            f"[CREDENTIAL VERIFY] {field_name}: exact value verified; "
            f"length={len(expected_value)}; no boundary spacing; value hidden."
        )
    else:
        print(
            f"[CREDENTIAL VERIFY] {field_name}: exact value verified; "
            f"length={len(expected_value)}; no boundary spacing."
        )

    return True


def fill_and_verify_credential_input(
    driver,
    element,
    value,
    field_name,
    *,
    secret=True,
    max_attempts=3,
):
    """
    Sanitize -> enter -> read DOM value -> verify exact equality.

    If Hikvision/Vue mutates or drops characters, the field is cleared,
    re-entered, and verified again before the script can continue.
    """
    clean_value = sanitize_credential_boundary(
        value,
        field_name,
        secret=secret,
    )

    last_error = ""

    for attempt in range(
        1,
        max_attempts + 1,
    ):
        set_web_input(
            driver,
            element,
            clean_value,
            field_name,
        )

        try:
            verify_web_input_exact_value(
                driver,
                element,
                clean_value,
                field_name,
                secret=secret,
            )

            return clean_value

        except Exception as error:
            last_error = str(error)

            if attempt < max_attempts:
                print(
                    f"[CREDENTIAL VERIFY] {field_name}: verification "
                    f"failed on attempt {attempt}; re-entering."
                )

                try:
                    driver.execute_script(
                        """
                        const input = arguments[0];
                        const descriptor = Object.getOwnPropertyDescriptor(
                            window.HTMLInputElement.prototype,
                            "value"
                        );

                        if (descriptor && descriptor.set) {
                            descriptor.set.call(input, "");
                        } else {
                            input.value = "";
                        }

                        input.dispatchEvent(
                            new Event("input", {bubbles:true})
                        );
                        input.dispatchEvent(
                            new Event("change", {bubbles:true})
                        );
                        """,
                        element,
                    )
                except Exception:
                    pass

                time_module.sleep(0.3)

    raise RuntimeError(
        f"{field_name}: exact input verification failed after "
        f"{max_attempts} attempt(s): {last_error}"
    )


def verify_password_and_confirm_pair(
    driver,
    password_element,
    confirm_element,
    expected_password,
    role,
):
    """
    Verify Password and Confirm immediately before Add User submission.

    This is NOT a ServiceAccount login test.
    """
    clean_password = sanitize_credential_boundary(
        expected_password,
        f"{role} expected password",
        secret=True,
    )

    verify_web_input_exact_value(
        driver,
        password_element,
        clean_password,
        f"{role} Password",
        secret=True,
    )

    verify_web_input_exact_value(
        driver,
        confirm_element,
        clean_password,
        f"{role} Confirm",
        secret=True,
    )

    password_value = driver.execute_script(
        "return String(arguments[0].value || '');",
        password_element,
    )

    confirm_value = driver.execute_script(
        "return String(arguments[0].value || '');",
        confirm_element,
    )

    if password_value != confirm_value:
        raise RuntimeError(
            f"{role}: Password and Confirm do not exactly match."
        )

    print(
        f"[CREDENTIAL VERIFY] {role}: Password and Confirm match exactly; "
        f"length={len(clean_password)}; no boundary spacing; value hidden."
    )

    return clean_password


def verify_input_proxy_payload_credentials(
    xml_payload,
    expected_username,
    expected_password,
):
    """
    Verify the NVR InputProxy XML contains the exact sanitized Excel
    ServiceAccount username/password before PUT.

    No ServiceAccount login is performed and no password value is printed.
    """
    clean_username = sanitize_credential_boundary(
        expected_username,
        "NVR InputProxy expected ServiceAccount username",
        secret=False,
    )

    clean_password = sanitize_credential_boundary(
        expected_password,
        "NVR InputProxy expected ServiceAccount password",
        secret=True,
    )

    root = ET.fromstring(xml_payload)

    source_descriptor = None

    for element in root.iter():
        if xml_local_name(element.tag) == "sourceInputPortDescriptor":
            source_descriptor = element
            break

    if source_descriptor is None:
        raise RuntimeError(
            "NVR InputProxy payload has no sourceInputPortDescriptor."
        )

    payload_username = xml_find_first_text(
        source_descriptor,
        ["userName"],
    )

    payload_password = xml_find_first_text(
        source_descriptor,
        ["password"],
    )

    if payload_username != clean_username:
        raise RuntimeError(
            "NVR InputProxy ServiceAccount username does not exactly "
            "match the sanitized Excel username."
        )

    if payload_password != clean_password:
        raise RuntimeError(
            "NVR InputProxy ServiceAccount password does not exactly "
            "match the sanitized Excel password."
        )

    print(
        "[CREDENTIAL VERIFY] NVR InputProxy ServiceAccount payload: "
        "username/password exactly match sanitized Excel values; "
        "password hidden."
    )

    return True


def _collect_add_user_core_fields(dialog):
    editable = [
        element
        for element in dialog.find_elements(By.CSS_SELECTOR, "input")
        if element.is_displayed()
        and element.is_enabled()
        and not element.get_attribute("readonly")
    ]

    passwords = [
        element
        for element in editable
        if str(element.get_attribute("type") or "").lower() == "password"
    ]

    non_passwords = [
        element
        for element in editable
        if str(element.get_attribute("type") or "text").lower()
        not in {
            "password", "hidden", "checkbox", "radio", "button", "submit",
        }
    ]

    if len(non_passwords) < 1 or len(passwords) < 3:
        raise RuntimeError(
            "Add User fields not found. Expected User Name, "
            "Admin Password, Password, Confirm."
        )

    return non_passwords, passwords


def _fill_and_sync_add_user_core_fields(driver, dialog, row, account):
    """
    Fill every required Add User field and explicitly synchronize the
    Element/Vue model. Used both for the first submission and for automatic
    repair when Hikvision returns a generic Required validation error.
    """
    non_passwords, passwords = _collect_add_user_core_fields(dialog)

    clean_username = fill_and_verify_credential_input(
        driver,
        non_passwords[0],
        account["username"],
        f"{account['role']} User Name",
        secret=False,
    )

    # Always perform a REAL Operator option selection on custom Dome controls.
    set_operator_level(driver, dialog)

    admin_password = fill_and_verify_credential_input(
        driver,
        passwords[0],
        get_value(row, "Password"),
        "Admin Password",
        secret=True,
    )

    initial_password = fill_and_verify_credential_input(
        driver,
        passwords[1],
        account["initial_password"],
        f"{account['role']} Password",
        secret=True,
    )

    fill_and_verify_credential_input(
        driver,
        passwords[2],
        initial_password,
        f"{account['role']} Confirm",
        secret=True,
    )

    verify_password_and_confirm_pair(
        driver,
        passwords[1],
        passwords[2],
        initial_password,
        account["role"],
    )

    return {
        "non_passwords": non_passwords,
        "passwords": passwords,
        "username": clean_username,
        "admin_password": admin_password,
        "initial_password": initial_password,
    }


def _verify_or_repair_add_user_core_fields_once(
    driver,
    dialog,
    row,
    account,
    expected,
):
    """
    Re-acquire live Vue input nodes after permission checkbox work WITHOUT
    blindly typing every value a second time.

    v108 deliberately refilled all fields after permissions, which is why the
    user visibly saw username/password entered twice.  v109 only repairs a
    field if Vue actually cleared/replaced its value.
    """
    non_passwords, passwords = _collect_add_user_core_fields(dialog)

    expected_values = [
        (non_passwords[0], expected["username"], f"{account['role']} User Name", False),
        (passwords[0], expected["admin_password"], "Admin Password", True),
        (passwords[1], expected["initial_password"], f"{account['role']} Password", True),
        (passwords[2], expected["initial_password"], f"{account['role']} Confirm", True),
    ]

    for element, wanted, label, secret in expected_values:
        actual = str(
            driver.execute_script(
                "return String(arguments[0].value || '');",
                element,
            )
            or ""
        )
        if actual == wanted:
            print(
                f"[CREDENTIAL STABILITY] {label}: value survived permission "
                "configuration; no second typing performed."
            )
            continue

        print(
            f"[CREDENTIAL REPAIR] {label}: Vue changed/cleared the field after "
            "permission configuration; repairing this field once only."
        )
        fill_and_verify_credential_input(
            driver,
            element,
            wanted,
            label,
            secret=secret,
            max_attempts=2,
        )

    verify_password_and_confirm_pair(
        driver,
        passwords[1],
        passwords[2],
        expected["initial_password"],
        account["role"],
    )

    return {
        "non_passwords": non_passwords,
        "passwords": passwords,
        "username": expected["username"],
        "admin_password": expected["admin_password"],
        "initial_password": expected["initial_password"],
    }


def _wait_for_live_add_user_permission_dialog(driver, role):
    """
    Wait for Permission Configuration while repeatedly re-identifying the exact
    live Add User drawer.  Vue can replace the drawer node during rendering; a
    fixed Selenium element can therefore become stale or time out with an empty
    `Message:`.
    """
    deadline = time_module.monotonic() + max(5.0, float(USER_MANAGEMENT_DIALOG_WAIT_SECONDS))
    last_state = {}

    while time_module.monotonic() < deadline:
        dialog = find_user_edit_dialog(driver, need_username=True)
        if dialog is None:
            last_state = {"dialog": "not_found"}
            time_module.sleep(0.25)
            continue

        try:
            state = driver.execute_script(
                r"""
                const dialog = arguments[0];
                if (!dialog || !dialog.isConnected) {
                    return {ready:false, connected:false, boxes:0, text:''};
                }
                const text = String(
                    dialog.innerText || dialog.textContent || ''
                ).replace(/\s+/g, ' ').trim();
                const boxes = dialog.querySelectorAll('input[type="checkbox"]').length;
                const lower = text.toLowerCase();
                return {
                    ready: Boolean(
                        boxes >= 1 && (
                            lower.includes('permission configuration') ||
                            lower.includes('select all') ||
                            lower.includes('remote:')
                        )
                    ),
                    connected: true,
                    boxes: boxes,
                    text: text.slice(0, 350)
                };
                """,
                dialog,
            )
        except Exception as error:
            last_state = {
                "dialog": "stale_or_script_error",
                "error": str(error).strip() or repr(error),
            }
            time_module.sleep(0.25)
            continue

        last_state = state or {}
        if bool((state or {}).get("ready")):
            print(
                f"[USER MANAGEMENT ADD] {role}: live Permission "
                f"Configuration ready; checkboxes={(state or {}).get('boxes')}."
            )
            return dialog

        time_module.sleep(0.25)

    raise RuntimeError(
        f"{role}: Add User Permission Configuration did not become ready "
        f"within {USER_MANAGEMENT_DIALOG_WAIT_SECONDS}s. Last state={last_state}"
    )



def _reacquire_add_user_dialog_for_submit(
    driver,
    row,
    account,
    previous_dialog=None,
    timeout=5.0,
    stage="pre-submit",
):
    """
    v118: robust Add User dialog reacquisition for old Discreet + modern Dome UI.

    A permission-checkbox update can make Hikvision's UI replace/detach the
    dialog DOM node. A detector miss is therefore not proof that the form closed.
    Backend /ISAPI/Security/users remains the idempotency authority.
    """
    username = str(account.get("username", "") or "").strip()
    role = str(account.get("role", username) or username).strip()

    def backend_created():
        try:
            snapshot = get_isapi_user_snapshot(row)
            present = username in set(snapshot.get("usernames", []))
            if present:
                return True, (
                    f"backend-created; HTTP={snapshot.get('status')}; "
                    f"count={snapshot.get('count')}"
                )
        except Exception:
            pass
        return False, ""

    state_script = r"""
        const root = arguments[0];
        function norm(value) {
            return String(value || "").replace(/\s+/g, " ").trim().toLowerCase();
        }
        function cssVisible(element) {
            if (!element || !element.isConnected) return false;
            let current = element;
            while (current && current !== document.documentElement) {
                const style = window.getComputedStyle(current);
                if (
                    style.display === "none" ||
                    style.visibility === "hidden" ||
                    Number(style.opacity || "1") === 0 ||
                    current.getAttribute("aria-hidden") === "true"
                ) return false;
                current = current.parentElement;
            }
            const rect = element.getBoundingClientRect();
            return rect.width > 0 && rect.height > 0;
        }
        if (!root || !root.isConnected || !cssVisible(root)) {
            return {ready:false, connected:Boolean(root && root.isConnected), reason:"detached-or-hidden"};
        }
        const text = norm(root.innerText || root.textContent || "");
        const inputs = Array.from(root.querySelectorAll("input"))
            .filter((element) => cssVisible(element) && !element.disabled);
        const passwords = inputs.filter((element) => norm(element.type) === "password");
        const nonPasswords = inputs.filter((element) => {
            const type = norm(element.type || "text");
            return !["password","hidden","checkbox","radio","button","submit","image"].includes(type);
        });
        const checkboxes = inputs.filter((element) => norm(element.type) === "checkbox");
        const hasUserName = text.includes("user name") || text.includes("username");
        const hasAdminPassword = text.includes("admin password");
        const hasConfirm = text.includes("confirm");
        const hasPermission = (
            text.includes("permission configuration") ||
            text.includes("select all") ||
            text.includes("local:") ||
            text.includes("remote:")
        );
        const hasOldPassword = text.includes("old password");
        return {
            ready:Boolean(
                !hasOldPassword && hasUserName && hasAdminPassword && hasConfirm &&
                hasPermission && passwords.length >= 3 && nonPasswords.length >= 1
            ),
            connected:true,
            passwordCount:passwords.length,
            nonPasswordCount:nonPasswords.length,
            checkboxCount:checkboxes.length,
            hasUserName:hasUserName,
            hasAdminPassword:hasAdminPassword,
            hasConfirm:hasConfirm,
            hasPermission:hasPermission,
            hasOldPassword:hasOldPassword,
            text:text.slice(0,300)
        };
    """

    fallback_script = r"""
        function norm(value) {
            return String(value || "").replace(/\s+/g, " ").trim().toLowerCase();
        }
        function cssVisible(element) {
            if (!element || !element.isConnected) return false;
            let current = element;
            while (current && current !== document.documentElement) {
                const style = window.getComputedStyle(current);
                if (
                    style.display === "none" ||
                    style.visibility === "hidden" ||
                    Number(style.opacity || "1") === 0 ||
                    current.getAttribute("aria-hidden") === "true"
                ) return false;
                current = current.parentElement;
            }
            const rect = element.getBoundingClientRect();
            return rect.width > 0 && rect.height > 0;
        }
        function signature(container) {
            if (!container || !cssVisible(container)) return null;
            const rect = container.getBoundingClientRect();
            const area = rect.width * rect.height;
            if (area < 5000) return null;
            const text = norm(container.innerText || container.textContent || "");
            if (text.includes("old password")) return null;
            const inputs = Array.from(container.querySelectorAll("input"))
                .filter((element) => cssVisible(element) && !element.disabled);
            const passwords = inputs.filter((element) => norm(element.type) === "password");
            const nonPasswords = inputs.filter((element) => {
                const type = norm(element.type || "text");
                return !["password","hidden","checkbox","radio","button","submit","image"].includes(type);
            });
            const checkboxes = inputs.filter((element) => norm(element.type) === "checkbox");
            const hasUserName = text.includes("user name") || text.includes("username");
            const hasAdminPassword = text.includes("admin password");
            const hasConfirm = text.includes("confirm");
            const hasPermission = (
                text.includes("permission configuration") ||
                text.includes("select all") ||
                text.includes("local:") ||
                text.includes("remote:")
            );
            if (
                !hasUserName || !hasAdminPassword || !hasConfirm || !hasPermission ||
                passwords.length < 3 || nonPasswords.length < 1
            ) return null;
            let score = 0;
            if (text.includes("add user")) score += 200;
            if (text.includes("permission configuration")) score += 120;
            if (text.includes("select all")) score += 80;
            if (checkboxes.length >= 1) score += 60;
            if (passwords.length === 3) score += 40;
            score -= Math.min(area / 100000, 50);
            return {element:container, score:score, area:area};
        }
        const candidates = new Set();
        for (const container of document.querySelectorAll(
            ".el-drawer,.el-dialog,[role='dialog'],.modal,.modal-dialog,.dialog,.window," +
            ".aui_dialog,.ui-dialog,.layui-layer,.popbox,.popup,.panel"
        )) candidates.add(container);
        const passwordInputs = Array.from(document.querySelectorAll("input[type='password']"))
            .filter(cssVisible);
        for (const password of passwordInputs) {
            let current = password.parentElement;
            for (let depth = 0; depth < 14 && current; depth += 1) {
                candidates.add(current);
                if (current === document.body || current === document.documentElement) break;
                current = current.parentElement;
            }
        }
        const matches = [];
        for (const candidate of candidates) {
            const hit = signature(candidate);
            if (hit) matches.push(hit);
        }
        if (!matches.length) return null;
        matches.sort((a,b) => b.score - a.score || a.area - b.area);
        return matches[0].element;
    """

    def structural_state(element):
        if element is None:
            return {"ready": False, "connected": False, "reason": "no-element"}
        try:
            return driver.execute_script(state_script, element) or {"ready": False}
        except Exception as error:
            return {
                "ready": False,
                "connected": False,
                "reason": str(error).strip() or repr(error),
            }

    def structural_fallback_recursive(max_depth=5):
        try:
            driver.switch_to.default_content()
        except Exception:
            pass

        def search(depth):
            try:
                candidate = driver.execute_script(fallback_script)
            except Exception:
                candidate = None
            if candidate is not None:
                return candidate
            if depth >= max_depth:
                return None
            try:
                frames = driver.find_elements(By.CSS_SELECTOR, "iframe,frame")
            except Exception:
                frames = []
            for index in range(len(frames)):
                try:
                    current_frames = driver.find_elements(By.CSS_SELECTOR, "iframe,frame")
                    if index >= len(current_frames):
                        continue
                    driver.switch_to.frame(current_frames[index])
                except Exception:
                    continue
                found = search(depth + 1)
                if found is not None:
                    return found
                try:
                    driver.switch_to.parent_frame()
                except Exception:
                    try:
                        driver.switch_to.default_content()
                    except Exception:
                        pass
            return None

        result = search(0)
        if result is None:
            try:
                driver.switch_to.default_content()
            except Exception:
                pass
        return result

    created, proof = backend_created()
    if created:
        print(
            f"[USER MANAGEMENT REACQUIRE] {role}: backend already contains "
            f"{username}; stage={stage}; no UI retry required."
        )
        return None, proof

    if previous_dialog is not None:
        state = structural_state(previous_dialog)
        if state.get("ready"):
            print(
                f"[USER MANAGEMENT REACQUIRE] {role}: reusing existing live "
                f"Add User dialog at stage={stage}; passwords={state.get('passwordCount')}; "
                f"checkboxes={state.get('checkboxCount')}."
            )
            return previous_dialog, "previous-dialog-still-live"

    deadline = time_module.monotonic() + max(1.0, float(timeout))
    last_state = {}

    while time_module.monotonic() < deadline:
        try:
            live = find_user_edit_dialog(driver, need_username=True)
        except Exception as error:
            live = None
            last_state = {"semantic_error": str(error).strip() or repr(error)}

        if live is not None:
            state = structural_state(live)
            if state.get("ready"):
                print(
                    f"[USER MANAGEMENT REACQUIRE] {role}: semantic detector "
                    f"reacquired Add User at stage={stage}."
                )
                return live, "semantic-reacquire"
            last_state = state

        fallback = structural_fallback_recursive()
        if fallback is not None:
            state = structural_state(fallback)
            if state.get("ready"):
                print(
                    f"[USER MANAGEMENT REACQUIRE] {role}: structural old-UI "
                    f"fallback reacquired Add User at stage={stage}; "
                    f"passwords={state.get('passwordCount')}; "
                    f"checkboxes={state.get('checkboxCount')}."
                )
                return fallback, "structural-old-ui-reacquire"
            last_state = state

        time_module.sleep(0.20)

    created, proof = backend_created()
    if created:
        print(
            f"[USER MANAGEMENT REACQUIRE] {role}: UI panel was unavailable, "
            f"but backend now contains {username}; stage={stage}."
        )
        return None, proof

    raise RuntimeError(
        f"{role}: transient Add User panel rebind failure at stage={stage}; "
        f"backend still proves username '{username}' is absent; "
        f"lastState={last_state}"
    )


def create_user_account(
    driver,
    row,
    account,
    nvr_ui_permission_profiles,
):
    username = account["username"]

    before = get_isapi_user_snapshot(row)

    if username in set(before.get("usernames", [])):
        print(
            f"[USER MANAGEMENT] {username} already exists in backend. "
            "Skipping account creation."
        )
        if user_management_device_kind(row) in {"DISCREET", "DOME"}:
            print(
                f"[USER RIGHTS WARNING] {username}: camera account already exists, "
                "so Add User checkbox rights are not reapplied by this creation step. "
                "Use a fresh test account/device to validate creation rights."
            )
        return "EXISTS"

    if username_visible_in_user_list(driver, username):
        print(
            f"[USER MANAGEMENT] {username} already exists in UI. "
            "Skipping account creation."
        )
        if user_management_device_kind(row) in {"DISCREET", "DOME"}:
            print(
                f"[USER RIGHTS WARNING] {username}: camera account already exists, "
                "so Add User checkbox rights are not reapplied by this creation step."
            )
        return "EXISTS"

    print(
        f"[USER MANAGEMENT] Creating {account['role']} "
        f"({username}); backend count before={before.get('count')}."
    )

    dialog = click_add_user(driver, row)
    filled = _fill_and_sync_add_user_core_fields(
        driver,
        dialog,
        row,
        account,
    )

    device_kind = user_management_device_kind(row)

    # Re-identify the live drawer while Vue renders Permission Configuration.
    # This removes the stale-element / empty TimeoutException path seen on .196.
    if USER_MANAGEMENT_ENFORCE_UI_RIGHTS_DURING_CREATE:
        dialog = _wait_for_live_add_user_permission_dialog(
            driver,
            account["role"],
        )

    if USER_MANAGEMENT_ENFORCE_UI_RIGHTS_DURING_CREATE and device_kind == "NVR":
        role = account["role"]
        if role not in nvr_ui_permission_profiles:
            raise RuntimeError(f"NVR UI permission profile missing for role {role}.")
        print(
            f"[NVR USER RIGHTS] {role}: applying NVR Excel checkbox profile "
            "in Add User dialog before clicking OK."
        )
        permission_result = apply_user_permission_profile(
            driver,
            dialog,
            account,
            permission_override=nvr_ui_permission_profiles[role],
        )
    else:
        permission_result = apply_user_permission_profile(driver, dialog, account)

    # v108: submit this account ONCE.  Do not loop/re-enter the same data based
    # on generic SPA validation messages.  The exact Add User drawer and the
    # backend /ISAPI/Security/users readback are now the authority.
    # v118: permission changes can temporarily replace the Add User DOM node.
    dialog, reacquire_proof = _reacquire_add_user_dialog_for_submit(
        driver,
        row,
        account,
        previous_dialog=dialog,
        timeout=5.0,
        stage="after-permissions",
    )
    if dialog is None:
        print(
            f"[USER MANAGEMENT] {username}: account confirmed through "
            f"{reacquire_proof} while the UI was rebinding."
        )
        return "CREATED"

    # Re-acquire live fields once after permission actions.  Do NOT blindly
    # type username/password a second time; only repair an individual field if
    # Vue actually cleared or replaced its value.
    filled = _verify_or_repair_add_user_core_fields_once(
        driver,
        dialog,
        row,
        account,
        filled,
    )

    non_passwords = filled["non_passwords"]
    passwords = filled["passwords"]

    verify_web_input_exact_value(
        driver,
        non_passwords[0],
        filled["username"],
        f"{account['role']} User Name pre-OK",
        secret=False,
    )

    verify_web_input_exact_value(
        driver,
        passwords[0],
        filled["admin_password"],
        "Admin Password pre-OK",
        secret=True,
    )

    verify_password_and_confirm_pair(
        driver,
        passwords[1],
        passwords[2],
        filled["initial_password"],
        account["role"],
    )

    print(
        f"[CREDENTIAL VERIFY] {account['role']}: final pre-OK "
        "credential verification PASSED."
    )

    # Check that this is still the exact Add User drawer before clicking.
    dialog, reacquire_proof = _reacquire_add_user_dialog_for_submit(
        driver,
        row,
        account,
        previous_dialog=dialog,
        timeout=4.0,
        stage="immediately-before-OK",
    )
    if dialog is None:
        print(
            f"[USER MANAGEMENT] {username}: account confirmed through "
            f"{reacquire_proof} before the OK click."
        )
        return "CREATED"

    print(
        f"[USER MANAGEMENT SUBMIT] {username}: backend-verified click escalation enabled. "
        "A second click is allowed only while /ISAPI/Security/users still proves the account is absent."
    )

    submit_methods = ("cdp", "native", "actionchains", "javascript", "keyboard")
    submitted = False
    proof = ""
    last_submit_error = ""

    for submit_method in submit_methods:
        created, created_proof, _ = poll_add_user_backend_created(row, username, before, timeout=0.8)
        if created:
            submitted = True
            proof = created_proof
            break

        try:
            live_dialog, live_reacquire_proof = _reacquire_add_user_dialog_for_submit(
                driver,
                row,
                account,
                previous_dialog=dialog,
                timeout=2.5,
                stage=f"before-submit-method-{submit_method}",
            )
        except Exception as reacquire_error:
            last_submit_error = (
                f"method={submit_method} could not reacquire Add User: "
                f"{str(reacquire_error).strip() or repr(reacquire_error)}"
            )
            break
        if live_dialog is None:
            submitted = True
            proof = live_reacquire_proof
            break
        dialog = live_dialog

        diagnostics = get_user_dialog_validation_diagnostics(driver, live_dialog)
        if diagnostics:
            readable = "; ".join(
                f"{item.get('label', 'Unknown field')}: {item.get('message', '')} "
                f"(DOM has value={item.get('hasDomValue')})"
                for item in diagnostics
            )
            raise RuntimeError(f"Add User validation error before submit method={submit_method}: {readable}")

        try:
            click_user_dialog_ok(driver, live_dialog, method=submit_method)
        except Exception as submit_error:
            last_submit_error = f"method={submit_method} raised {str(submit_error).strip() or repr(submit_error)}"
            print(f"[USER MANAGEMENT SUBMIT WARNING] {last_submit_error}")
            continue

        created, created_proof, _ = poll_add_user_backend_created(row, username, before, timeout=2.8)
        if created:
            submitted = True
            proof = created_proof
            break

        try:
            current_dialog, current_reacquire_proof = _reacquire_add_user_dialog_for_submit(
                driver,
                row,
                account,
                previous_dialog=live_dialog,
                timeout=2.5,
                stage=f"after-submit-method-{submit_method}",
            )
        except Exception as reacquire_error:
            last_submit_error = (
                f"method={submit_method} produced no backend creation and Add User "
                f"could not be reacquired: {str(reacquire_error).strip() or repr(reacquire_error)}"
            )
            break
        if current_dialog is None:
            submitted = True
            proof = current_reacquire_proof
            break
        dialog = current_dialog

        state = get_add_user_dialog_field_state(driver, current_dialog)
        messages = get_visible_user_management_messages(driver, current_dialog)
        print(
            f"[USER MANAGEMENT SUBMIT WARNING] {username}: method={submit_method} did not create backend user; "
            f"dialog remains open; fieldState={state}; visibleMessages={messages}. "
            "Escalating only because backend still proves the username is absent."
        )
        last_submit_error = f"method={submit_method} produced no backend creation"

    if submitted:
        live = find_user_edit_dialog(driver, need_username=True)
        if live is not None:
            dismiss_stale_add_user_dialog(driver, live)
        dismiss_hikvision_success_note(driver, timeout=2.0, label=f"Add User {username} success")
        ok = True
    else:
        ok, proof = wait_for_add_user_backend_result(driver, row, account, before, dialog)

    if not ok:
        raise RuntimeError(
            f"User {username} was submitted but creation could not be confirmed: {proof}; "
            f"lastSubmitError={last_submit_error}"
        )

    print(
        f"[USER MANAGEMENT] {username}: Add User confirmed through {proof}."
    )

    print(
        f"[OK] {username} created/confirmed via {proof}; "
        f"rights matched={len(permission_result['matched'])}, "
        f"unmatched={len(permission_result['unmatched'])}. "
        "Password value not printed."
    )

    return "CREATED"


def open_modify_own_user_dialog(
    driver,
    username,
):
    """
    Robust old Hikvision workflow:
        1) select the exact username row,
        2) wait until TOP Modify button becomes enabled,
        3) click Modify,
        4) wait for Modify user dialog.

    The previous implementation returned a Selenium timeout because the JS
    row.click() did not always trigger the old table's internal selection
    handler.
    """
    wanted = str(username).strip()

    def find_user_row():
        return driver.execute_script(
            r"""
            const wanted = String(arguments[0] || "").trim();

            function visible(element) {
                if (!element) return false;

                const style = window.getComputedStyle(element);
                const rect = element.getBoundingClientRect();

                return (
                    style.display !== "none" &&
                    style.visibility !== "hidden" &&
                    rect.width > 0 &&
                    rect.height > 0
                );
            }

            const cells = Array.from(
                document.querySelectorAll(
                    "td,span,div,p,a"
                )
            ).filter((element) => (
                visible(element) &&
                String(
                    element.innerText ||
                    element.textContent ||
                    ""
                ).trim() === wanted
            ));

            for (const cell of cells) {
                const row =
                    cell.closest("tr") ||
                    cell.closest(".el-table__row");

                if (row && visible(row)) {
                    return row;
                }
            }

            return null;
            """,
            wanted,
        )

    def find_modify_button_any_state():
        return driver.execute_script(
            r"""
            function visible(element) {
                if (!element) return false;

                const style = window.getComputedStyle(element);
                const rect = element.getBoundingClientRect();

                return (
                    style.display !== "none" &&
                    style.visibility !== "hidden" &&
                    rect.width > 0 &&
                    rect.height > 0
                );
            }

            return Array.from(
                document.querySelectorAll(
                    "button,input[type='button'],input[type='submit']," +
                    "a,[role='button']"
                )
            ).find((element) => {
                if (!visible(element)) return false;

                const text = String(
                    element.innerText ||
                    element.value ||
                    element.textContent ||
                    ""
                ).trim().toLowerCase();

                return (
                    text === "modify" ||
                    text === "edit"
                );
            }) || null;
            """
        )

    row = WebDriverWait(
        driver,
        8,
    ).until(
        lambda _d: (
            find_user_row()
            or False
        )
    )


    selection_attempts = 5
    modify = None

    # Resolve the exact username cell once. On this old UI the selection
    # handler is often attached to the cell/table widget rather than only TR.
    username_cell = driver.execute_script(
        r"""
        const row = arguments[0];
        const wanted = String(arguments[1] || "").trim();

        return Array.from(
            row.querySelectorAll(
                "td,span,div,p,a"
            )
        ).find((element) => (
            String(
                element.innerText ||
                element.textContent ||
                ""
            ).trim() === wanted
        )) || row.querySelector("td") || row;
        """,
        row,
        wanted,
    )

    for attempt in range(
        1,
        selection_attempts + 1,
    ):
        try:
            driver.execute_script(
                """
                arguments[0].scrollIntoView({
                    block: "center",
                    inline: "center"
                });
                """,
                row,
            )
        except Exception:
            pass

        # Native Selenium click on the username cell first. This matches the
        # manual workflow: click/select the user entry, then top Modify.
        try:
            ActionChains(driver).move_to_element(
                username_cell
            ).click().perform()
        except Exception:
            try:
                username_cell.click()
            except Exception:
                try:
                    row.click()
                except Exception:
                    pass

        # Attempt 2+: explicitly dispatch the mouse event sequence expected by
        # many old Hikvision table controls.
        if attempt >= 2:
            try:
                driver.execute_script(
                    r"""
                    const row = arguments[0];

                    for (const eventName of [
                        "mousedown",
                        "mouseup",
                        "click"
                    ]) {
                        row.dispatchEvent(
                            new MouseEvent(
                                eventName,
                                {
                                    bubbles: true,
                                    cancelable: true,
                                    view: window,
                                    button: 0
                                }
                            )
                        );
                    }
                    """,
                    row,
                )
            except Exception:
                pass

        # Attempt 3+: click the username cell itself natively as well.
        if attempt >= 3:
            try:
                cell = driver.execute_script(
                    r"""
                    const row = arguments[0];
                    const wanted = String(arguments[1] || "").trim();

                    return Array.from(
                        row.querySelectorAll(
                            "td,span,div,p,a"
                        )
                    ).find((element) => (
                        String(
                            element.innerText ||
                            element.textContent ||
                            ""
                        ).trim() === wanted
                    )) || row.querySelector("td") || row;
                    """,
                    row,
                    wanted,
                )

                ActionChains(driver).move_to_element(
                    cell
                ).click().perform()
            except Exception:
                pass

        time_module.sleep(0.4)

        modify = find_modify_button_any_state()

        if modify is None:
            continue

        disabled = bool(
            modify.get_attribute(
                "disabled"
            )
        )

        aria_disabled = str(
            modify.get_attribute(
                "aria-disabled"
            )
            or ""
        ).strip().lower()

        classes = str(
            modify.get_attribute(
                "class"
            )
            or ""
        ).lower()

        enabled = (
            not disabled
            and aria_disabled not in {
                "true",
                "1",
            }
            and "disabled" not in classes
        )

        print(
            f"[USER MANAGEMENT MODIFY] {username}: row-selection "
            f"attempt {attempt}/{selection_attempts}; "
            f"Modify enabled={enabled}."
        )

        if enabled:
            break

        modify = None

    if modify is None:
        debug_state = driver.execute_script(
            r"""
            const wanted = String(arguments[0] || "").trim();

            const button = Array.from(
                document.querySelectorAll(
                    "button,input[type='button'],input[type='submit']," +
                    "a,[role='button']"
                )
            ).find((element) => {
                const text = String(
                    element.innerText ||
                    element.value ||
                    element.textContent ||
                    ""
                ).trim().toLowerCase();

                return text === "modify";
            });

            const cells = Array.from(
                document.querySelectorAll("td")
            ).filter((element) => (
                String(
                    element.innerText ||
                    element.textContent ||
                    ""
                ).trim() === wanted
            ));

            const row = cells.length
                ? cells[0].closest("tr")
                : null;

            return {
                modifyFound: Boolean(button),
                modifyDisabled: button
                    ? Boolean(button.disabled)
                    : null,
                modifyClass: button
                    ? String(button.className || "")
                    : "",
                rowFound: Boolean(row),
                rowClass: row
                    ? String(row.className || "")
                    : ""
            };
            """,
            wanted,
        )

        raise RuntimeError(
            f"Selected user row for {username}, but the top Modify "
            f"button did not become enabled. Debug={debug_state}"
        )

    try:
        ActionChains(driver).move_to_element(
            modify
        ).click().perform()
    except Exception:
        try:
            modify.click()
        except Exception:
            driver.execute_script(
                "arguments[0].click();",
                modify,
            )

    return WebDriverWait(
        driver,
        USER_MANAGEMENT_PASSWORD_CHANGE_WAIT_SECONDS,
    ).until(
        lambda d: (
            find_user_edit_dialog(
                d,
                need_username=False,
            )
            or False
        )
    )

def change_own_password(
    driver,
    username,
    testing_password,
    actual_password,
):
    dialog = open_modify_own_user_dialog(
        driver,
        username,
    )

    password_inputs = [
        element
        for element in dialog.find_elements(
            By.CSS_SELECTOR,
            'input[type="password"]',
        )
        if element.is_displayed()
        and element.is_enabled()
        and not element.get_attribute("readonly")
    ]

    if len(password_inputs) < 3:
        raise RuntimeError(
            "Modify user dialog did not expose Old Password, "
            "Password and Confirm fields."
        )

    # Confirmed screenshot order:
    # Old Password -> Password -> Confirm
    set_web_input(
        driver,
        password_inputs[0],
        testing_password,
        "Old Password",
    )

    set_web_input(
        driver,
        password_inputs[-2],
        actual_password,
        "New Password",
    )

    set_web_input(
        driver,
        password_inputs[-1],
        actual_password,
        "Confirm New Password",
    )

    click_user_dialog_ok(
        driver,
        dialog,
    )

    wait_user_dialog_gone(
        driver,
        dialog,
        expect_add_user=False,
    )

    return True



def hikvision_security1_encrypt_field(
    value,
    key_hex,
    iv_hex,
):
    """
    Encrypt one Hikvision security=1 XML field.

    The old web UI uses:
        encodeString(value)
        -> Base64
        -> AES-CBC-PKCS7 using oAuthInfo.szAESKey and the request IV

    The resulting ciphertext is lowercase hexadecimal.
    """
    encoded_value = hikvision_xml_text_encode(
        str(value)
    )

    aes_plaintext = base64.b64encode(
        encoded_value.encode("utf-8")
    ).decode("ascii")

    return aes_cbc_pkcs7_encrypt_hex(
        aes_plaintext,
        key_hex,
        iv_hex,
    )


def resolve_user_id_for_rotation(
    admin_row,
    username,
):
    """
    Resolve MM/ME user ID through the administrator's plaintext UserList.

    This is rerun-safe and avoids decrypting the security=1 UserList.
    """
    snapshot = get_isapi_user_snapshot(
        admin_row
    )

    user_id = str(
        snapshot.get(
            "user_ids",
            {},
        ).get(
            username,
            "",
        )
        or ""
    ).strip()

    if user_id:
        return user_id

    raise RuntimeError(
        f"Could not resolve user ID for {username} from "
        "/ISAPI/Security/users using the administrator account. "
        f"Visible usernames={snapshot.get('usernames', [])}"
    )


def build_security1_user_password_change_xml(
    user_id,
    username,
    old_password,
    new_password,
    key_hex,
    iv_hex,
):
    """
    Build the same User XML structure captured from a successful password
    modification request.

    loginPassword = current/testing password
    password      = new/actual password
    """
    encrypted_username = (
        hikvision_security1_encrypt_field(
            username,
            key_hex,
            iv_hex,
        )
    )

    encrypted_login_password = (
        hikvision_security1_encrypt_field(
            old_password,
            key_hex,
            iv_hex,
        )
    )

    encrypted_new_password = (
        hikvision_security1_encrypt_field(
            new_password,
            key_hex,
            iv_hex,
        )
    )

    # Never print or persist this XML because it contains encrypted credential
    # material.
    return (
        '<?xml version="1.0" encoding="UTF-8"?>'
        '<User>'
        f'<id>{xml_escape_text(str(user_id))}</id>'
        f'<userName>{encrypted_username}</userName>'
        f'<loginPassword>{encrypted_login_password}</loginPassword>'
        f'<password>{encrypted_new_password}</password>'
        '<bondIpList>'
        '<bondIp>'
        '<id>1</id>'
        '<ipAddress>0.0.0.0</ipAddress>'
        '<ipv6Address>::</ipv6Address>'
        '</bondIp>'
        '</bondIpList>'
        '<macAddress/>'
        '<userLevel>Operator</userLevel>'
        '<attribute><inherent/></attribute>'
        '</User>'
    )


def rotate_user_password_direct_security1(
    admin_row,
    account,
):
    """
    Direct MM/ME Testing -> Actual password rotation.

    Flow:
      1) Resolve target user ID using admin UserList.
      2) SessionLogin-v4 as MM/ME using Testing password.
      3) GET /ISAPI/Security/capabilities?username=<MM/ME>.
      4) Derive oAuthInfo-compatible AES key from Testing password.
      5) Encrypt userName/loginPassword/password with one fresh IV.
      6) PUT /ISAPI/Security/users/<id>?security=1&iv=<IV>.
      7) Verify Actual password can SessionLogin.

    No Edge window, row selection, or Modify button is required.
    """
    ip = get_value(
        admin_row,
        "Current IP",
    )

    username = account["username"]
    testing_password = account["initial_password"]
    actual_password = account["actual_password"]

    user_id = resolve_user_id_for_rotation(
        admin_row,
        username,
    )

    print(
        f"[USER PASSWORD DIRECT] {ip} / {username}: "
        f"resolved user ID={user_id}."
    )

    # Rerun-safe: if Actual already works, do not attempt Testing again.
    actual_ok, _ = verify_login_credential(
        ip,
        username,
        actual_password,
    )

    if actual_ok:
        print(
            f"[USER PASSWORD DIRECT] {username}: Actual password "
            "already active; no rotation required."
        )

        return (
            True,
            "Actual password already active.",
        )

    session = HikvisionSession(
        ip,
        username,
        testing_password,
    )

    # SessionLogin proves the Testing password is currently valid.  Newly
    # created Operator accounts can be restricted until the first password
    # change, so DeviceInfo is intentionally NOT used as the authentication
    # test here.
    session.login(validate_device_info=False)

    try:
        capabilities = session.get_security_capabilities()
    except Exception as target_cap_error:
        # Some firmware also blocks Security/capabilities for the restricted
        # first-login user.  Ask the administrator session for the target
        # user's security capability values instead; the encryption is still
        # derived from the target user's Testing password.
        print(
            f"[USER PASSWORD DIRECT] {username}: target-user security "
            f"capabilities unavailable ({target_cap_error}); retrying the "
            "same target capability query through the administrator session."
        )
        admin_session = HikvisionSession(
            ip,
            get_value(admin_row, "Username"),
            get_value(admin_row, "Password"),
        )
        admin_session.login()
        cap_endpoint = (
            "/ISAPI/Security/capabilities?"
            + urlencode({"username": username})
        )
        cap_response = admin_session.request(
            "GET",
            cap_endpoint,
            accept="application/xml, text/xml, */*",
        )
        if cap_response.status_code != 200:
            raise RuntimeError(
                "Security capabilities request failed for both target and "
                f"administrator sessions: target={target_cap_error}; "
                f"admin HTTP {cap_response.status_code}; "
                f"response={safe_preview(cap_response.text)}"
            )
        cap_root = parse_xml(cap_response.text, "Security capabilities")
        capabilities = {
            "key_iterate_num": xml_find_int(cap_root, "keyIterateNum", 0),
            "is_irreversible": xml_find_bool(cap_root, "isIrreversible", False),
            "salt": xml_find_text(cap_root, "salt", ""),
        }

    key_hex = derive_hikvision_aes_key_variant(
        testing_password,
        capabilities,
        "capability",
    )

    iv_hex = hashlib.md5(
        str(now_ms()).encode("utf-8")
    ).hexdigest()

    payload = (
        build_security1_user_password_change_xml(
            user_id,
            username,
            testing_password,
            actual_password,
            key_hex,
            iv_hex,
        )
    )

    endpoint = (
        f"/ISAPI/Security/users/{user_id}"
        f"?security=1&iv={iv_hex}"
    )

    print(
        f"[USER PASSWORD DIRECT] {username}: submitting direct "
        f"security=1 password change to user ID {user_id}. "
        "Encrypted credential fields are hidden."
    )

    response = session.request(
        "PUT",
        endpoint,
        data=payload.encode("utf-8"),
        accept="*/*",
        content_type=(
            "application/x-www-form-urlencoded; charset=UTF-8"
        ),
        timeout=(
            HTTP_CONNECT_TIMEOUT_SECONDS,
            HTTP_READ_TIMEOUT_SECONDS,
        ),
    )

    if response.status_code != 200:
        return (
            False,
            (
                f"Direct security=1 password change returned "
                f"HTTP {response.status_code}; "
                f"response={safe_preview(response.text)}"
            ),
        )

    fields = parse_status_fields(
        response.text
    )

    status_code = str(
        fields.get(
            "status_code",
            "",
        )
        or ""
    ).strip()

    sub_status_code = str(
        fields.get(
            "sub_status_code",
            "",
        )
        or ""
    ).strip()

    if status_code and status_code != "1":
        return (
            False,
            (
                "Direct security=1 password change was rejected: "
                f"statusCode={status_code}; "
                f"statusString={fields.get('status_string', '')}; "
                f"subStatusCode={sub_status_code}"
            ),
        )

    # Give the device a brief moment to commit the password change.
    time_module.sleep(0.8)

    actual_ok, actual_error = (
        verify_login_credential(
            ip,
            username,
            actual_password,
        )
    )

    if not actual_ok:
        return (
            False,
            (
                "Direct security=1 PUT returned success, but "
                "Actual-password SessionLogin verification failed: "
                f"{actual_error}"
            ),
        )

    print(
        f"[OK] {username}: Testing -> Actual password changed "
        "through direct /ISAPI/Security/users security=1 request "
        "and verified by SessionLogin."
    )

    return (
        True,
        (
            "Testing -> Actual password rotation verified through "
            "direct security=1 ISAPI."
        ),
    )


def rotate_mm_me_password(
    row,
    account,
):
    if not account["rotate"]:
        return True, "No password rotation required."

    if USER_MANAGEMENT_DIRECT_PASSWORD_ROTATION:
        try:
            ok, detail = (
                rotate_user_password_direct_security1(
                    row,
                    account,
                )
            )

            if ok:
                return ok, detail

            if not USER_MANAGEMENT_UI_PASSWORD_ROTATION_FALLBACK:
                return ok, detail

            print(
                f"[USER PASSWORD DIRECT WARNING] "
                f"{account['username']}: {detail}"
            )
            print(
                "[USER PASSWORD DIRECT WARNING] Falling back to "
                "Selenium User Management Modify workflow."
            )

        except Exception as error:
            if not USER_MANAGEMENT_UI_PASSWORD_ROTATION_FALLBACK:
                return (
                    False,
                    (
                        "Direct security=1 password rotation failed: "
                        f"{error}"
                    ),
                )

            print(
                f"[USER PASSWORD DIRECT WARNING] "
                f"{account['username']}: {error}"
            )
            print(
                "[USER PASSWORD DIRECT WARNING] Falling back to "
                "Selenium User Management Modify workflow."
            )

    # Optional compatibility fallback only.
    ip = get_value(row, "Current IP")
    username = account["username"]

    actual_ok, _ = verify_login_credential(
        ip,
        username,
        account["actual_password"],
    )

    if actual_ok:
        return True, "Actual password already active."

    login_row = dict(row)
    login_row["Username"] = username
    login_row["Password"] = account["initial_password"]

    driver = None

    try:
        driver = create_hikvision_edge_driver()

        open_user_management_page_for_account(
            driver,
            login_row,
        )

        ensure_first_login_session_reaches_configuration(
            driver,
            login_row,
        )

        open_old_ui_user_management_page(
            driver,
            login_row,
            user_management_device_kind(login_row),
        )

        print(
            f"[USER MANAGEMENT] {username}: using UI fallback for "
            "Testing -> Actual password rotation."
        )

        change_own_password(
            driver,
            username,
            account["initial_password"],
            account["actual_password"],
        )

    except Exception as error:
        return (
            False,
            f"Testing -> Actual password UI fallback failed: {error}",
        )

    finally:
        if driver is not None:
            try:
                driver.quit()
            except Exception:
                pass

    actual_ok, actual_error = verify_login_credential(
        ip,
        username,
        account["actual_password"],
    )

    if not actual_ok:
        return (
            False,
            (
                "UI fallback completed, but login with Actual "
                f"password failed: {actual_error}"
            ),
        )

    return True, "Testing -> Actual password UI fallback verified."


def run_account_security_settings_batch(
    rows,
    account_security_configurations,
    results,
    *,
    stage_label="PRE-USER-MANAGEMENT",
):
    """
    Configure Account Security Settings before User Management.

    Returns a set of IPs that are allowed to proceed to User Management.

    Different devices run concurrently for speed. Each worker still waits for
    its own browser workflow to finish, and failures are collected before this
    function returns. Therefore the next stage cannot start early.
    """
    rows = list(
        rows
    )

    if not rows:
        return set()

    print("=" * 100)
    print(
        f"[ACCOUNT SECURITY BATCH] {stage_label}: "
        f"{len(rows)} device(s)."
    )
    print(
        "[ACCOUNT SECURITY BATCH] This stage is a barrier: "
        "User Management will not begin until every selected Account "
        "Security worker has finished."
    )
    print("=" * 100)

    ready_ips = set()
    failed_ips = set()

    def worker(row):
        local_results = []

        ip = get_value(
            row,
            "Current IP",
            "current_ip",
        )

        if ACCOUNT_SECURITY_PARALLEL_START_DELAY_SECONDS > 0:
            time_module.sleep(
                ACCOUNT_SECURITY_PARALLEL_START_DELAY_SECONDS
            )

        try:
            configure_device_account_security_settings_via_ui(
                row,
                account_security_configurations,
                local_results,
            )
        except Exception as error:
            add_result(
                local_results,
                ip,
                "Configure Device Account Security Settings",
                ACCOUNT_SECURITY_SETTINGS_SHEET,
                "",
                "ERROR",
                str(error),
            )

        blocking_failure = any(
            str(
                record.get(
                    "Result",
                    "",
                )
            ).strip().upper()
            in {
                "FAILED",
                "ERROR",
            }
            for record in local_results
        )

        return (
            ip,
            not blocking_failure,
            local_results,
        )

    max_workers = 1

    if (
        ACCOUNT_SECURITY_PARALLEL_DEVICES
        and len(rows) > 1
    ):
        max_workers = min(
            len(rows),
            max(
                1,
                ACCOUNT_SECURITY_PARALLEL_SAFETY_LIMIT,
            ),
        )

    if max_workers > 1:
        print(
            f"[ACCOUNT SECURITY BATCH] Parallel workers: "
            f"{max_workers}"
        )

        with ThreadPoolExecutor(
            max_workers=max_workers
        ) as executor:
            future_map = {
                executor.submit(
                    worker,
                    row,
                ): row
                for row in rows
            }

            for future in as_completed(
                future_map
            ):
                row = future_map[
                    future
                ]

                fallback_ip = get_value(
                    row,
                    "Current IP",
                    "current_ip",
                )

                try:
                    ip, ok, local_results = (
                        future.result()
                    )
                except Exception as error:
                    ip = fallback_ip
                    ok = False
                    local_results = []

                    add_result(
                        local_results,
                        ip,
                        "Configure Device Account Security Settings",
                        ACCOUNT_SECURITY_SETTINGS_SHEET,
                        "",
                        "ERROR",
                        str(error),
                    )

                results.extend(
                    local_results
                )

                if ok:
                    ready_ips.add(
                        ip
                    )

                    print(
                        f"[ACCOUNT SECURITY BATCH] COMPLETE: "
                        f"{ip} -> READY"
                    )
                else:
                    failed_ips.add(
                        ip
                    )

                    print(
                        f"[ACCOUNT SECURITY BATCH] COMPLETE: "
                        f"{ip} -> FAILED"
                    )

    else:
        for row in rows:
            ip, ok, local_results = worker(
                row
            )

            results.extend(
                local_results
            )

            if ok:
                ready_ips.add(
                    ip
                )
            else:
                failed_ips.add(
                    ip
                )

    print("=" * 100)
    print(
        f"[ACCOUNT SECURITY BATCH] Completed: "
        f"ready={len(ready_ips)}; failed={len(failed_ips)}."
    )

    if failed_ips:
        print(
            f"[ACCOUNT SECURITY BATCH] Failed IPs: "
            f"{sorted(failed_ips)}"
        )

    print("=" * 100)

    return ready_ips


def precheck_existing_user_management_accounts(row, applicable_accounts):
    """Check existing configured usernames before opening Edge/Add User."""
    ip = get_value(row, "Current IP")
    snapshot = get_isapi_user_snapshot(row)
    status = snapshot.get("status")
    count = snapshot.get("count")
    usernames = [str(v).strip() for v in snapshot.get("usernames", []) if str(v).strip()]
    by_lower = {v.lower(): v for v in usernames}

    if status != 200:
        print(f"[USER PRECHECK] {ip}: GET /ISAPI/Security/users HTTP {status}; precheck unavailable. Normal per-user detection will be used.")
        return {"snapshot": snapshot, "existing": [], "pending": list(applicable_accounts), "readable": False}

    configured = {str(a.get("username", "")).strip().lower() for a in applicable_accounts if str(a.get("username", "")).strip()}
    matched = configured & set(by_lower)

    # Never guess role existence from count alone. If usernames look protected,
    # let the existing backend/UI checks decide safely later.
    readable = bool(matched or "admin" in by_lower or count in {0, 1})
    if not readable:
        print(f"[USER PRECHECK] {ip}: backend count={count}, but configured usernames are not readable. Will not guess from count.")
        return {"snapshot": snapshot, "existing": [], "pending": list(applicable_accounts), "readable": False}

    existing=[]; pending=[]
    for account in applicable_accounts:
        u=str(account.get("username", "")).strip()
        (existing if u and u.lower() in by_lower else pending).append(account)

    print("="*100)
    print(f"[USER PRECHECK] {ip}: checking existing users BEFORE opening User Management / Add User.")
    print(f"[USER PRECHECK] Backend user count: {count}")
    print(f"[USER PRECHECK] Existing configured roles: {[a['role'] for a in existing]}")
    print(f"[USER PRECHECK] Missing configured roles: {[a['role'] for a in pending]}")
    print("="*100)
    return {"snapshot": snapshot, "existing": existing, "pending": pending, "readable": True}

def configure_user_management_device(
    row,
    accounts,
    nvr_rights_profiles,
    nvr_ui_permission_profiles,
    results,
    *,
    existing_driver=None,
    close_driver=True,
    raise_on_error=False,
):
    """
    Create missing users on one device.

    v107 can reuse an existing authenticated Edge driver.  Options 1/2 pass
    the driver that just completed Account Security Settings, so User
    Management starts without closing/reopening the browser.
    """
    ip = get_value(row, "Current IP")
    source_sheet = get_value(row, "Source Sheet")
    kind = user_management_device_kind(row)

    applicable_accounts = [a for a in accounts if user_role_applies_to_device(a, kind)]
    skipped_accounts = [a for a in accounts if not user_role_applies_to_device(a, kind)]

    for account in skipped_accounts:
        add_result(results, ip, f"Create User {account['role']}", "/ISAPI/Security/users", "", "SKIPPED",
                   f"Role scope={account.get('scope')}; device kind={kind}")
        print(f"[USER MANAGEMENT] {ip}: skipping {account['role']} because scope={account.get('scope')}.")
        if account.get("role") == "L2VA" and kind in {"DISCREET", "DOME"}:
            print(f"[USER MANAGEMENT] {ip}: L2VA is NVR-only and will not be created on this camera.")

    # PRECHECK: before Add User, read current users and ignore configured roles
    # that already exist.  This makes same-session retries idempotent if a
    # previous attempt created one account before a later field/navigation
    # error occurred.
    precheck = precheck_existing_user_management_accounts(row, applicable_accounts)
    existing_accounts = list(precheck.get("existing", []))
    pending_accounts = list(precheck.get("pending", applicable_accounts))

    for account in existing_accounts:
        print(f"[USER PRECHECK] {ip}: {account['role']} ({account['username']}) already exists -> IGNORE.")
        add_result(results, ip, f"Create User {account['role']}", "/ISAPI/Security/users", 200, "SKIPPED",
                   "User existed before this run. Ignored completely: no Add User, no rights change, no password rotation, no login verification.")

    if not pending_accounts:
        print("="*100)
        print(f"[USER MANAGEMENT] {ip}: all configured applicable user accounts already exist.")
        print("[USER MANAGEMENT] Existing accounts are left untouched.")
        print("="*100)
        return True

    print("="*100)
    print(f"[USER MANAGEMENT] {ip} / {kind} / {source_sheet}")
    print(f"[USER MANAGEMENT] Existing roles ignored: {[a['role'] for a in existing_accounts]}")
    print(f"[USER MANAGEMENT] Missing roles to create: {[a['role'] for a in pending_accounts]}")
    print("[USER MANAGEMENT] Only missing accounts will be created. Passwords will not be printed.")
    print("="*100)

    driver = existing_driver
    owns_driver = driver is None
    newly_created_accounts = []

    try:
        if driver is None:
            driver = create_hikvision_edge_driver()

        open_user_management_page_for_account(
            driver,
            row,
            preserve_current_session=(existing_driver is not None),
        )

        for account in pending_accounts:
            state = create_user_account(driver, row, account, nvr_ui_permission_profiles)

            if state == "CREATED":
                newly_created_accounts.append(account)
                result_status = "OK"
                detail = (f"{state}; Level={account.get('level')}; Scope={account.get('scope')}; "
                          "ExcelRightsAppliedBeforeCreate=True")
            elif state == "EXISTS":
                result_status = "SKIPPED"
                detail = ("User already exists; detected during per-account check and ignored. "
                          "No rights/password/login changes will be performed.")
                print(f"[USER MANAGEMENT] {ip}: {account['role']} detected as already existing -> IGNORE.")
            else:
                result_status = "OK"
                detail = str(state)

            add_result(results, ip, f"Create User {account['role']}", "/ISAPI/Security/users", "", result_status, detail)

        if USER_MANAGEMENT_REFRESH_AFTER_ALL_CREATION and newly_created_accounts:
            print(f"[USER MANAGEMENT] {ip}: newly created roles={[a['role'] for a in newly_created_accounts]}. Refreshing User Management once in the current session.")
            refresh_user_management_page(driver, row)

    except Exception as error:
        if driver is not None:
            try:
                save_web_ui_debug(driver, ip, f"user_management_creation_failure_{source_sheet}_v115")
            except Exception:
                pass

        error_detail = str(error).strip() or f"{type(error).__name__}: {repr(error)}"
        print(f"[FAILED] User Management creation for {ip}: {error_detail}")

        if raise_on_error:
            raise

        add_result(results, ip, "Create User Management", "/ISAPI/Security/users", "", "FAILED", error_detail)
        return False

    finally:
        if driver is not None and (owns_driver or close_driver):
            try:
                driver.quit()
            except Exception:
                pass

    if not newly_created_accounts:
        print("="*100)
        print(f"[USER MANAGEMENT] {ip}: no new user account was created in this run.")
        print("[USER MANAGEMENT] Existing accounts remain untouched: no rights, password or login-verification changes.")
        print("="*100)
        return True

    overall_ok = True

    # NVR rights: only users created in this run.
    if kind == "NVR" and USER_MANAGEMENT_NVR_DIRECT_RIGHTS:
        print("="*100)
        print(f"[NVR USER RIGHTS] Applying exact NVR rights only to newly created users on {ip}.")
        print(f"[NVR USER RIGHTS] New roles: {[a['role'] for a in newly_created_accounts]}")
        print("="*100)
        for account in newly_created_accounts:
            ok, detail = apply_nvr_user_permission_profile(row, account, nvr_rights_profiles)
            add_result(results, ip, f"Configure NVR User Rights {account['role']}",
                       "/ISAPI/Security/UserPermission/<id>", "", "OK" if ok else "FAILED", detail)
            if not ok:
                overall_ok = False
                print(f"[FAILED] {ip} NVR rights {account['role']}: {detail}")

    # MM/ME rotation: only users created in this run.
    for account in newly_created_accounts:
        if not account["rotate"]:
            continue
        ok, detail = rotate_mm_me_password(row, account)
        add_result(results, ip, f"Rotate {account['role']} Password", "/ISAPI/Security/users/<self>", "",
                   "OK" if ok else "FAILED", detail)
        if not ok:
            overall_ok = False
            print(f"[FAILED] {ip} {account['role']}: {detail}")

    # Final login verification: only users created in this run.
    for account in newly_created_accounts:
        if not user_account_login_verification_required(row, account):
            add_result(results, ip, f"Verify User Login {account['role']}", "/ISAPI/Security/sessionLogin", "", "SKIPPED",
                       f"{account['role']} final login verification is intentionally disabled by workflow requirement.")
            print(f"[USER MANAGEMENT] {ip} {account['role']}: final login verification skipped.")
            continue

        ok, detail = verify_login_credential(ip, account["username"], account["actual_password"])
        add_result(results, ip, f"Verify User Login {account['role']}", "/ISAPI/Security/sessionLogin", 200 if ok else "",
                   "OK" if ok else "FAILED", "Final password authenticated successfully." if ok else detail)
        if not ok:
            overall_ok = False

    return overall_ok


def run_user_management_only(
    devices,
    results,
    excel_path,
    write_report_when_done=True,
    eligible_device_ips=None,
    *,
    force_all_devices=False,
    stage_label="OPTION 3",
):
    print("=" * 100)
    print(f"{stage_label}: CREATE USER MANAGEMENT")
    if force_all_devices:
        print(
            "[USER MANAGEMENT] All loaded NVR/Discreet/Dome devices are "
            "selected; User Management Creation Yes/No is ignored for this mode."
        )
    print("=" * 100)

    accounts = read_user_management_accounts(
        excel_path
    )

    permission_profiles = (
        read_user_management_permission_profiles(
            excel_path
        )
    )

    accounts = attach_user_management_profiles(
        accounts,
        permission_profiles,
    )

    nvr_rights_profiles = (
        read_nvr_user_rights_profiles(
            excel_path
        )
    )

    nvr_ui_permission_profiles = (
        read_nvr_user_ui_permission_profiles(
            excel_path
        )
    )

    selected = [
        row
        for row in devices
        if (
            (
                force_all_devices
                or user_management_creation_requested(row)
            )
            and (
                eligible_device_ips is None
                or get_value(
                    row,
                    "Current IP",
                    "current_ip",
                )
                in eligible_device_ips
            )
        )
    ]

    blocked_by_account_security = [
        row
        for row in devices
        if (
            (
                force_all_devices
                or user_management_creation_requested(row)
            )
            and eligible_device_ips is not None
            and get_value(
                row,
                "Current IP",
                "current_ip",
            )
            not in eligible_device_ips
        )
    ]

    for blocked_row in blocked_by_account_security:
        blocked_ip = get_value(
            blocked_row,
            "Current IP",
            "current_ip",
        )

        print(
            f"[USER MANAGEMENT BLOCKED] {blocked_ip}: "
            "Account Security Settings did not complete successfully."
        )

        add_result(
            results,
            blocked_ip,
            "Create User Management",
            ACCOUNT_SECURITY_SETTINGS_SHEET,
            "",
            "SKIPPED",
            (
                "Blocked because Account Security Settings returned "
                "FAILED/ERROR earlier in this run."
            ),
        )

    print(
        f"[USER MANAGEMENT] Devices selected: "
        f"{len(selected)}"
    )

    if not selected:
        print(
            "[USER MANAGEMENT] No device selected for User Management."
        )

        if write_report_when_done:
            write_report(results)

        return

    if (
        USER_MANAGEMENT_PARALLEL_DEVICES
        and len(selected) > 1
    ):
        max_workers = min(
            len(selected),
            max(
                1,
                USER_MANAGEMENT_PARALLEL_SAFETY_LIMIT,
            ),
        )

        print(
            f"[USER MANAGEMENT] Parallel device mode: "
            f"{max_workers} Edge windows/workers."
        )

        def worker(row):
            local_results = []
            ip = get_value(
                row,
                "Current IP",
            )

            if (
                USER_MANAGEMENT_PARALLEL_START_DELAY_SECONDS
                > 0
            ):
                time_module.sleep(
                    USER_MANAGEMENT_PARALLEL_START_DELAY_SECONDS
                )

            ok = configure_user_management_device(
                row,
                accounts,
                nvr_rights_profiles,
                nvr_ui_permission_profiles,
                local_results,
            )

            return ip, ok, local_results

        with ThreadPoolExecutor(
            max_workers=max_workers
        ) as executor:
            future_map = {
                executor.submit(
                    worker,
                    row,
                ): row
                for row in selected
            }

            for future in as_completed(
                future_map
            ):
                row = future_map[future]
                ip = get_value(
                    row,
                    "Current IP",
                )

                try:
                    finished_ip, ok, local_results = (
                        future.result()
                    )

                    results.extend(
                        local_results
                    )

                    print(
                        f"[USER MANAGEMENT] Device complete: "
                        f"{finished_ip}; "
                        f"status={'OK' if ok else 'FAILED'}"
                    )

                except Exception as error:
                    add_result(
                        results,
                        ip,
                        "Create User Management",
                        "",
                        "",
                        "ERROR",
                        str(error),
                    )

                    print(
                        f"[ERROR] User Management worker failed for "
                        f"{ip}: {error}"
                    )

    else:
        for index, row in enumerate(
            selected,
            start=1,
        ):
            ip = get_value(
                row,
                "Current IP",
            )

            print("=" * 100)
            print(
                f"[USER MANAGEMENT] DEVICE "
                f"{index}/{len(selected)}: {ip}"
            )
            print("=" * 100)

            try:
                configure_user_management_device(
                    row,
                    accounts,
                    nvr_rights_profiles,
                    nvr_ui_permission_profiles,
                    results,
                )
            except Exception as error:
                add_result(
                    results,
                    ip,
                    "Create User Management",
                    "",
                    "",
                    "ERROR",
                    str(error),
                )

    if write_report_when_done:
        write_report(results)


def configure_old_ui_account_security_in_driver(
    driver,
    row,
    configuration,
    results,
    device_label,
):
    """
    Configure Account Security Settings on the older Hikvision web UI.

    Used by:
      - Discreet camera
      - NVR
    """
    ip = get_value(
        row,
        "Current IP",
        "current_ip",
    )

    task = (
        f"Configure {device_label} "
        "Account Security Settings"
    )

    if not validate_account_security_configuration(
        configuration
    ):
        print(
            f"[SKIP] {ip} {device_label} Account Security "
            "Settings disabled in Excel."
        )

        add_result(
            results,
            ip,
            task,
            ACCOUNT_SECURITY_SETTINGS_SHEET,
            "",
            "SKIPPED",
            "Enabled=No",
        )
        return True

    username = get_value(
        row,
        "Username",
        "username",
    )

    password = get_value(
        row,
        "Password",
        "password",
    )

    # Reach User Management using visible-menu and hidden-DOM fallbacks.
    open_old_ui_user_management_page(
        driver,
        row,
        device_label,
    )

    dialog_context = click_old_ui_account_security_settings(
        driver,
        device_label,
    )

    dialog = dialog_context["dialog"]

    native_selects = driver.execute_script(
        """
        const dialog = arguments[0];

        function visible(element) {
            if (!element) return false;

            const style = window.getComputedStyle(element);
            const rect = element.getBoundingClientRect();

            return (
                !element.disabled &&
                style.display !== "none" &&
                style.visibility !== "hidden" &&
                rect.width > 0 &&
                rect.height > 0
            );
        }

        return Array.from(
            dialog.querySelectorAll("select")
        ).filter(visible).slice(0, 3);
        """,
        dialog,
    )

    if len(native_selects) < 3:
        raise RuntimeError(
            f"{device_label} security-question dropdowns "
            "were not found."
        )

    for index, question in enumerate(
        configuration["questions"],
        start=1,
    ):
        select_old_ui_security_question(
            native_selects[index - 1],
            question,
            device_label,
            index,
        )

        time_module.sleep(0.3)

    editable_inputs = driver.execute_script(
        """
        const dialog = arguments[0];

        function visible(element) {
            if (!element) return false;

            const style = window.getComputedStyle(element);
            const rect = element.getBoundingClientRect();

            return (
                !element.disabled &&
                !element.readOnly &&
                style.display !== "none" &&
                style.visibility !== "hidden" &&
                rect.width > 0 &&
                rect.height > 0
            );
        }

        return Array.from(
            dialog.querySelectorAll("input")
        ).filter((element) => {
            const type = String(element.type || "text")
                .toLowerCase();

            return (
                visible(element) &&
                ![
                    "hidden",
                    "button",
                    "submit",
                    "checkbox",
                    "radio"
                ].includes(type)
            );
        });
        """,
        dialog,
    )

    if len(editable_inputs) < 3:
        raise RuntimeError(
            f"{device_label} security-answer input boxes "
            "were not found."
        )

    for index, question in enumerate(
        configuration["questions"],
        start=1,
    ):
        set_web_input(
            driver,
            editable_inputs[index - 1],
            question["answer"],
            field_name=(
                f"{device_label} security answer {index}"
            ),
        )

    reserved_email = configuration.get(
        "reserved_email",
        "",
    )

    if (
        len(editable_inputs) >= 4
        and not is_blank(reserved_email)
    ):
        set_web_input(
            driver,
            editable_inputs[3],
            reserved_email,
            field_name=(
                f"{device_label} reserved email"
            ),
        )

    ok_button = find_visible_button_in_container(
        driver,
        dialog,
        "OK",
    )

    if ok_button is None:
        raise RuntimeError(
            f"{device_label} Account Security Settings "
            "OK button was not found."
        )

    try:
        ok_button.click()
    except Exception:
        driver.execute_script(
            "arguments[0].click();",
            ok_button,
        )

    print(
        f"[ACCOUNT SECURITY] {device_label} main OK clicked; "
        "waiting for Admin Password confirmation."
    )

    # The security-question form may be inside securityQA.asp. The password
    # confirmation dialog is rendered in the parent config page.
    driver.switch_to.default_content()
    time_module.sleep(1)

    complete_account_security_password_confirmation(
        driver,
        password,
        device_label,
    )

    # The old NVR/Discreet UI confirms this save with a modal Note.
    # Clear it NOW so the same-session handoff to User Management is not
    # blocked by an invisible click interceptor.
    dismissed_success_notes = dismiss_hikvision_success_note(
        driver,
        timeout=4.0,
        label=f"{device_label} Account Security save",
    )

    time_module.sleep(0.5)

    print(
        f"[OK] {device_label} Account Security Settings "
        f"saved for {ip}; successModalDismissed={dismissed_success_notes}"
    )

    if device_label == "NVR":
        print(
            "[ACCOUNT SECURITY] NVR firmware may return "
            "statusCode=1/statusString=OK with "
            "subStatusCode=riskPassword. This indicates the "
            "security-question request was accepted while the "
            "current administrator password is still rated as risky."
        )

    question_ids = ", ".join(
        (
            question.get("id")
            or "N/A"
        )
        for question in configuration["questions"]
    )

    add_result(
        results,
        ip,
        task,
        "/ISAPI/Security/questionConfiguration",
        200,
        "OK",
        (
            f"Question IDs={question_ids}; "
            "questions/answers pulled from Excel; "
            "encrypted request generated by device web UI; "
            "Admin Password confirmed; answers not logged"
        ),
    )

    return True


def configure_discreet_account_security_in_driver(
    driver,
    row,
    configuration,
    results,
):
    return configure_old_ui_account_security_in_driver(
        driver,
        row,
        configuration,
        results,
        "Discreet",
    )


def configure_nvr_account_security_in_driver(
    driver,
    row,
    configuration,
    results,
):
    return configure_old_ui_account_security_in_driver(
        driver,
        row,
        configuration,
        results,
        "NVR",
    )



def configure_device_account_security_settings_via_ui(
    row,
    account_security_configurations,
    results,
):
    """
    Configure Account Security Settings for NVR / Discreet / Dome.

    A transient browser/navigation failure is retried with a completely fresh
    Edge session. A device is marked FAILED only after all attempts fail.
    """
    source_sheet = get_value(
        row,
        "Source Sheet",
    )
    camera_type = get_value(
        row,
        "Camera Type",
    )
    ip = get_value(
        row,
        "Current IP",
        "current_ip",
    )
    username = get_value(
        row,
        "Username",
        "username",
    )
    password = get_value(
        row,
        "Password",
        "password",
    )

    is_nvr = (
        source_sheet == "NVR_Settings"
        or "NVR" in camera_type.upper()
    )

    is_dome = (
        source_sheet == "Dome_Settings"
        or "DOME" in camera_type.upper()
    )

    is_discreet = (
        source_sheet == "Discreet_Settings"
        or "DISCREET" in camera_type.upper()
        or "DIS" in camera_type.upper()
    )

    if not (
        is_nvr
        or is_dome
        or is_discreet
    ):
        return

    task = "Configure Device Account Security Settings"

    if not ENABLE_ACCOUNT_SECURITY_SETTINGS_UI:
        print(
            f"[SKIP] {ip} Account Security Settings UI "
            "automation disabled."
        )

        add_result(
            results,
            ip,
            task,
            ACCOUNT_SECURITY_SETTINGS_SHEET,
            "",
            "SKIPPED",
            "ENABLE_ACCOUNT_SECURITY_SETTINGS_UI=False",
        )
        return

    configuration = get_account_security_settings_for_row(
        row,
        account_security_configurations,
    )

    if not configuration:
        print(
            f"[WARNING] {ip} no Account Security Settings "
            f"configuration found for {source_sheet}."
        )

        add_result(
            results,
            ip,
            task,
            ACCOUNT_SECURITY_SETTINGS_SHEET,
            "",
            "WARNING",
            f"No configuration found for {source_sheet}",
        )
        return

    if not configuration.get("enabled"):
        print(
            f"[SKIP] {ip} Account Security Settings disabled "
            "in Excel."
        )

        add_result(
            results,
            ip,
            task,
            ACCOUNT_SECURITY_SETTINGS_SHEET,
            "",
            "SKIPPED",
            "Enabled=No",
        )
        return

    if DRY_RUN:
        question_ids = ", ".join(
            (
                question.get("id")
                or "N/A"
            )
            for question in configuration["questions"]
        )

        print(
            f"[DRY RUN] Would configure Account Security "
            f"Settings for {ip}; Question IDs={question_ids}"
        )

        add_result(
            results,
            ip,
            task,
            ACCOUNT_SECURITY_SETTINGS_SHEET,
            "",
            "DRY_RUN",
            (
                f"Source Sheet={source_sheet}; "
                f"Question IDs={question_ids}; "
                "answers loaded but not logged"
            ),
        )
        return

    if not SELENIUM_AVAILABLE:
        detail = (
            "Install Selenium first: "
            "python -m pip install selenium"
        )

        print(
            f"[FAILED] {ip} {detail}"
        )

        add_result(
            results,
            ip,
            task,
            ACCOUNT_SECURITY_SETTINGS_SHEET,
            "",
            "FAILED",
            detail,
        )
        return

    # v127: isolate unreachable HTTPS / stale staging IP before launching Edge.
    reachable, diagnostic = account_security_https_preflight(row)
    if not reachable:
        print(f"[ACCOUNT SECURITY NETWORK BLOCKED] {ip}: {diagnostic}")
        add_result(
            results, ip, task, ACCOUNT_SECURITY_SETTINGS_SHEET,
            "", "FAILED", diagnostic,
        )
        return

    last_error = ""

    for attempt in range(
        1,
        ACCOUNT_SECURITY_UI_MAX_ATTEMPTS + 1,
    ):
        driver = None

        try:
            print("=" * 100)
            print(
                f"[ACCOUNT SECURITY] {ip}: UI attempt "
                f"{attempt}/{ACCOUNT_SECURITY_UI_MAX_ATTEMPTS}"
            )
            print("=" * 100)

            driver = create_hikvision_edge_driver()

            if is_dome:
                # Restore the proven method: open the normal Dome web page,
                # complete login, then navigate to User Management inside the
                # authenticated SPA. Do NOT start on the deep-link route.
                start_url = (
                    f"https://{ip}/doc/index.html"
                    f"?t={int(time_module.time() * 1000)}"
                )

            elif is_nvr:
                start_url = (
                    f"https://{ip}{DISCREET_CONFIG_PATH}"
                    f"?t={int(time_module.time() * 1000)}"
                )

            else:
                start_url = (
                    f"https://{ip}{DISCREET_PREVIEW_PATH}"
                    f"?t={int(time_module.time() * 1000)}"
                )

            print(
                f"[ACCOUNT SECURITY] Opening device: {start_url}"
            )

            driver.get(
                start_url
            )

            hikvision_web_login_if_needed(
                driver,
                username,
                password,
            )

            time_module.sleep(
                2
            )

            if is_dome:
                configure_dome_account_security_in_driver(
                    driver,
                    row,
                    configuration,
                    results,
                )

            elif is_nvr:
                configure_nvr_account_security_in_driver(
                    driver,
                    row,
                    configuration,
                    results,
                )

            else:
                configure_discreet_account_security_in_driver(
                    driver,
                    row,
                    configuration,
                    results,
                )

            print(
                f"[ACCOUNT SECURITY] {ip}: completed successfully "
                f"on attempt {attempt}."
            )

            return

        except Exception as error:
            last_error = str(
                error
            )

            print(
                f"[ACCOUNT SECURITY RETRY] {ip}: attempt "
                f"{attempt}/{ACCOUNT_SECURITY_UI_MAX_ATTEMPTS} "
                f"failed: {last_error}"
            )

            if driver is not None:
                try:
                    save_web_ui_debug(
                        driver,
                        ip,
                        (
                            "account_security_settings_failure_"
                            f"attempt_{attempt}"
                        ),
                    )
                except Exception:
                    pass

        finally:
            if driver is not None:
                try:
                    driver.quit()
                except Exception:
                    pass

        # If the browser lost connectivity, check reachability rather than
        # repeating the same doomed navigation several more times.
        if account_security_transport_error(last_error):
            alive, check_detail = account_security_https_preflight(row)
            print(f"[ACCOUNT SECURITY TRANSPORT] {ip}: {check_detail}")
            if not alive:
                last_error = f"{last_error}; {check_detail}"
                break

        if attempt < ACCOUNT_SECURITY_UI_MAX_ATTEMPTS:
            print(
                f"[ACCOUNT SECURITY RETRY] {ip}: opening a fresh "
                "Edge session and retrying the SAME proven Dome "
                "navigation flow."
            )

            time_module.sleep(
                ACCOUNT_SECURITY_UI_RETRY_WAIT_SECONDS
            )

    print(
        f"[FAILED] Account Security Settings automation failed "
        f"for {ip} after {ACCOUNT_SECURITY_UI_MAX_ATTEMPTS} "
        f"attempt(s): {last_error}"
    )

    add_result(
        results,
        ip,
        task,
        ACCOUNT_SECURITY_SETTINGS_SHEET,
        "",
        "FAILED",
        (
            f"Failed after {ACCOUNT_SECURITY_UI_MAX_ATTEMPTS} "
            f"fresh-browser attempt(s): {last_error}"
        ),
    )





def enable_dome_https_browsing_via_ui(
    row,
    results,
    account_security_configurations,
):
    """
    Dome camera only:
    - Log in with the Excel username/password
    - Enable HTTPS Browsing and verify it
    - Open WebSocket(s)
    - Enable the LOWER plural WebSockets option
    - Click Save and verify it
    """
    ip = get_value(row, "Current IP", "current_ip")
    username = get_value(row, "Username", "username")
    password = get_value(row, "Password", "password")
    source_sheet = get_value(row, "Source Sheet")
    camera_type = get_value(row, "Camera Type", "camera_type")

    task = "Enable Dome HTTPS Browsing via Web UI"
    endpoint = DOME_HTTPS_SETTINGS_PATH

    if not (
        source_sheet == "Dome_Settings"
        or "DOME" in camera_type.upper()
    ):
        return

    if not ENABLE_DOME_HTTPS_BROWSING_UI:
        print(f"[SKIP] {ip} Dome HTTPS UI automation disabled")
        add_result(
            results, ip, task, endpoint, "",
            "SKIPPED", "ENABLE_DOME_HTTPS_BROWSING_UI=False"
        )
        return

    if DRY_RUN:
        print(f"[DRY RUN] Would enable HTTPS Browsing via Edge for {ip}")
        add_result(
            results, ip, task, endpoint, "",
            "DRY_RUN", "Would run the tested DevTools Console script"
        )
        return

    if not SELENIUM_AVAILABLE:
        detail = "Install Selenium first: python -m pip install selenium"
        print(f"[FAILED] {ip} {detail}")
        add_result(
            results, ip, task, endpoint, "",
            "FAILED", detail
        )
        return

    driver = None

    base_camera_url = (
        f"https://{ip}/doc/index.html"
        f"?t={int(time_module.time() * 1000)}"
    )

    settings_url = (
        f"https://{ip}{DOME_HTTPS_SETTINGS_PATH}"
        f"?t={int(time_module.time() * 1000)}"
    )

    try:
        print(f"[WEB UI] Opening camera application: {base_camera_url}")

        driver = create_hikvision_edge_driver()

        # First access the normal camera application and complete login.
        # After login, the script clicks Configuration -> Network ->
        # Network Service instead of relying on a pre-login hash route.
        driver.get(base_camera_url)

        hikvision_web_login_if_needed(
            driver,
            username,
            password
        )

        print(
            "[WEB UI] Login stage completed. Starting "
            "Configuration > Network > Network Service navigation."
        )

        # After access succeeds, deliberately open the HTTP(S) page,
        # wait for the HTTPS Browsing switch, then run the tested script.
        open_dome_https_settings_page(
            driver,
            settings_url,
            username,
            password,
            ip
        )

        switch_info = locate_dome_https_browsing_switch(driver)
        print(f"[WEB UI] Current URL: {driver.current_url}")
        print(f"[WEB UI] HTTPS switch detection: {switch_info}")
        print(f"[WEB UI] {ip} enabling HTTPS Browsing now")

        result = run_dome_https_console_script(driver)

        if not isinstance(result, dict) or not result.get("ok"):
            stage = (
                result.get("stage", "unknown")
                if isinstance(result, dict)
                else "unknown"
            )
            detail = (
                result.get("detail", str(result))
                if isinstance(result, dict)
                else str(result)
            )

            print(
                f"[FAILED] {ip} HTTPS Browsing UI step "
                f"{stage}: {detail}"
            )

            add_result(
                results, ip, task, endpoint, "",
                "FAILED", f"Stage={stage}; {detail}"
            )
            return

        print(
            f"[WEB UI] {ip} before={result.get('before')}, "
            f"after={result.get('after')}, Save clicked"
        )

        time_module.sleep(EDGE_SAVE_WAIT_SECONDS)

        # Reload the exact settings route and verify persistence.
        open_dome_https_settings_page(
            driver,
            settings_url,
            username,
            password,
            ip
        )

        verified = read_dome_https_switch_state(driver)

        if verified is True:
            print(
                f"[OK] Dome HTTPS Browsing enabled and verified for {ip}"
            )
            add_result(
                results, ip, task, endpoint, 200,
                "OK",
                (
                    f"Before={result.get('before')}; "
                    f"After={result.get('after')}; "
                    "Verified after reload=True"
                )
            )

            # Continue in the same authenticated Edge session:
            # WebSocket(s) -> enable LOWER plural WebSockets -> Save -> verify.
            websockets_ok = enable_and_verify_dome_websockets(
                driver,
                row,
                results
            )

            if websockets_ok:
                print(
                    "[ACCOUNT SECURITY] Dome Account Security Settings "
                    "deferred to the dedicated pre-User-Management pass."
                )
        else:
            print(
                f"[FAILED] {ip} HTTPS Browsing did not remain enabled"
            )
            add_result(
                results, ip, task, endpoint, "",
                "FAILED",
                (
                    f"Console result={result}; "
                    f"Verified after reload={verified}"
                )
            )

    except Exception as error:
        print(
            f"[FAILED] Dome HTTPS UI automation failed "
            f"for {ip}: {error}"
        )
        add_result(
            results, ip, task, endpoint, "",
            "FAILED", str(error)
        )

    finally:
        if driver is not None:
            try:
                driver.quit()
            except Exception:
                pass



