# NVR CAMERA MANAGEMENT
# =============================================================================

def xml_local_name(tag):
    if "}" in tag:
        return tag.split("}", 1)[1]

    return tag


def xml_find_first_text(root, possible_names):
    names = {
        str(name).strip().lower()
        for name in possible_names
    }

    for element in root.iter():
        local_name = xml_local_name(element.tag).lower()

        if local_name in names:
            return (
                element.text.strip()
                if element.text
                else ""
            )

    return ""


def parse_input_proxy_channels(xml_text):
    """
    Parse either:
    - InputProxyChannel
    - InputProxyChannelList
    - ChannelInfoList

    Returns a list of dictionaries.
    """
    if is_blank(xml_text):
        return []

    try:
        root = ET.fromstring(xml_text)
    except Exception:
        return []

    channel_elements = []

    if xml_local_name(root.tag) in [
        "InputProxyChannel",
        "ChannelInfo",
    ]:
        channel_elements.append(root)

    for element in root.iter():
        local_name = xml_local_name(element.tag)

        if local_name in [
            "InputProxyChannel",
            "ChannelInfo",
        ] and element is not root:
            channel_elements.append(element)

    channels = []
    seen_ids = set()

    for element in channel_elements:
        channel_id = xml_find_first_text(
            element,
            ["id"],
        )

        if not channel_id or channel_id in seen_ids:
            continue

        seen_ids.add(channel_id)

        channel = {
            "id": channel_id,
            "ip_address": xml_find_first_text(
                element,
                ["ipAddress"],
            ),
            "manage_port": xml_find_first_text(
                element,
                ["managePortNo"],
            ),
            "source_channel": xml_find_first_text(
                element,
                ["srcInputPort"],
            ),
            "username": xml_find_first_text(
                element,
                ["userName"],
            ),
            "protocol": xml_find_first_text(
                element,
                ["proxyProtocol", "adminProtocol"],
            ),
            "stream_type": xml_find_first_text(
                element,
                ["streamType"],
            ),
            # v123: these security/port flags are part of the desired
            # InputProxy state and must be observed before a no-op is safe.
            "certificate_validation_enabled": xml_find_first_text(
                element,
                ["certificateValidationEnabled"],
            ),
            "default_admin_port_enabled": xml_find_first_text(
                element,
                ["defaultAdminPortEnabled"],
            ),
            "raw_xml": ET.tostring(
                element,
                encoding="unicode",
            ),
        }

        channels.append(channel)

    return channels


def parse_nvr_input_proxy_runtime_status(status_xml):
    """
    Parse InputProxy runtime status.

    Important: chanDetectResult=netUnreachable is an actionable runtime
    problem. Older logic ignored chanDetectResult and could misclassify the
    channel as an advisory-only online=false condition.
    """
    records = {}

    if is_blank(status_xml):
        return records

    try:
        root = ET.fromstring(status_xml)
    except Exception:
        return records

    candidate_names = {
        "InputProxyChannelStatus",
        "ChannelInfo",
        "InputProxyChannel",
    }

    for element in root.iter():
        if xml_local_name(element.tag) not in candidate_names:
            continue

        channel_id = xml_find_first_text(element, ["id"])
        if not channel_id:
            continue

        online = xml_find_first_text(
            element,
            ["online", "isOnline"],
        )

        detect_result = xml_find_first_text(
            element,
            [
                "chanDetectResult",
                "status",
                "statusString",
                "subStatusCode",
                "errorStatus",
                "errorCode",
            ],
        )

        streaming_ids = []
        for child in element.iter():
            if xml_local_name(child.tag) != "streamingProxyChannelIdList":
                continue
            for item in child.iter():
                if item is child:
                    continue
                value = str(item.text or "").strip()
                if value and value not in streaming_ids:
                    streaming_ids.append(value)

        raw_text = " ".join(
            str(child.text or "").strip()
            for child in element.iter()
            if str(child.text or "").strip()
        )

        records[str(channel_id).strip()] = {
            "id": str(channel_id).strip(),
            "online": str(online or "").strip(),
            "detect_result": str(detect_result or "").strip(),
            "streaming_proxy_ids": streaming_ids,
            "raw_text": raw_text,
        }

    return records


def classify_nvr_input_proxy_runtime_record(record):
    """
    Classify one InputProxy runtime record using one consistent rule.

    Precedence matters:
      1. explicit authentication/connection/certificate failures -> FAILED;
      2. online=true -> READY;
      3. StreamingProxy IDs -> READY only when there is NO explicit failure;
      4. online=false/blank with no explicit failure and no proxy IDs ->
         INCONCLUSIVE (must pass the bounded recovery gate before PASS 6).

    This prevents stale 101/102 IDs from masking errorUserNameOrPasswd while
    still supporting firmware that exposes proxy IDs before updating online.
    """
    if not record:
        return {
            "state": "inconclusive",
            "problem": "statusMissing",
            "explicit_failure": False,
        }

    online = str(record.get("online", "") or "").strip().lower()
    detect = str(record.get("detect_result", "") or "").strip()
    raw_text = str(record.get("raw_text", "") or "").strip()
    combined = f"{detect} {raw_text}".lower()
    compact = re.sub(r"[^a-z0-9]+", "", combined)

    auth_failure_tokens = [
        "errorusernameorpasswd",
        "usernameorpassword",
        "wrongpassword",
        "invalidpassword",
        "authenticationfailed",
        "authfailed",
        "loginfailed",
        "passworderror",
    ]

    connection_failure_tokens = [
        "netunreachable",
        "networkunreachable",
        "hostunreachable",
        "connectionfailed",
        "connectfailed",
        "connectiontimeout",
        "connecttimeout",
        "connectionrefused",
        "networkerror",
        "offline",
    ]

    certificate_failure_tokens = [
        "certificatevalidationfailed",
        "certificateerror",
        "certerror",
        "tlserror",
        "sslerror",
    ]

    matched_failure = next(
        (
            token
            for token in (
                auth_failure_tokens
                + connection_failure_tokens
                + certificate_failure_tokens
            )
            if token in compact
        ),
        "",
    )

    # chanDetectResult itself is authoritative when it contains a non-success
    # value, even if stale StreamingProxy IDs are also present.
    detect_compact = re.sub(r"[^a-z0-9]+", "", detect.lower())
    # DS-E08NI-Q2 V4.30.200 reports chanDetectResult=connect when the
    # NVR camera channel is connected. This is a SUCCESS token (distinct from
    # connectFailed / netUnreachable); v123 incorrectly marked all online
    # channels FAILED because it only recognized the word "connected".
    # NOTE: "connect" alone is not proof of readiness. The check below must
    # still confirm online=true or non-error proxy IDs, and explicit auth,
    # network, or certificate failures still take precedence.
    detect_success_values = {
        "",
        "ok",
        "normal",
        "success",
        "online",
        "connect",
        "connected",
        "noerror",
    }

    explicit_detect_failure = bool(
        detect_compact
        and detect_compact not in detect_success_values
    )

    if matched_failure or explicit_detect_failure:
        return {
            "state": "failed",
            "problem": detect or matched_failure or "runtimeFailure",
            "explicit_failure": True,
        }

    if online in {"true", "1", "yes", "online"}:
        return {
            "state": "ready",
            "problem": "",
            "explicit_failure": False,
        }

    if record.get("streaming_proxy_ids"):
        return {
            "state": "ready",
            "problem": "proxyIdsPresent",
            "explicit_failure": False,
        }

    if online in {"false", "0", "no", "offline"}:
        return {
            "state": "inconclusive",
            "problem": "offlineNoExplicitError",
            "explicit_failure": False,
        }

    return {
        "state": "inconclusive",
        "problem": detect or "runtimeInconclusive",
        "explicit_failure": False,
    }


def nvr_input_proxy_runtime_record_ready(record):
    return (
        classify_nvr_input_proxy_runtime_record(record).get("state")
        == "ready"
    )


def nvr_input_proxy_runtime_record_problem(record):
    return classify_nvr_input_proxy_runtime_record(record).get(
        "problem",
        "runtimeInconclusive",
    )


def channel_id_sort_key(channel_id):
    try:
        return int(str(channel_id))
    except Exception:
        return 9999


def save_nvr_camera_management_backup(
    nvr_ip,
    name,
    content,
    suffix="xml",
):
    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    device_dir = (
        NVR_CAMERA_BACKUP_DIR
        / safe_filename(nvr_ip)
    )
    device_dir.mkdir(parents=True, exist_ok=True)

    file_path = (
        device_dir
        / (
            f"{safe_filename(nvr_ip)}_"
            f"{safe_filename(name)}_"
            f"{timestamp}.{suffix}"
        )
    )

    file_path.write_text(
        content or "",
        encoding="utf-8",
        errors="ignore",
    )

    return file_path


def safe_get_nvr_input_proxy_xml(
    nvr_ip,
    nvr_username,
    nvr_password,
    endpoint,
    *,
    label="InputProxy GET",
):
    """
    Bounded, retrying GET for NVR InputProxy discovery/status reads.

    These endpoints can become temporarily slow while cameras are reconnecting
    or while the NVR refreshes channel state.  They are discovery/validation
    reads, so a single 120-second ReadTimeout should never abort PASS 5.
    """
    last_status = 0
    last_response = ""

    for attempt in range(1, NVR_INPUTPROXY_DISCOVERY_MAX_ATTEMPTS + 1):
        try:
            status, response = get_xml_with_timeout(
                nvr_ip,
                nvr_username,
                nvr_password,
                endpoint,
                NVR_INPUTPROXY_DISCOVERY_READ_TIMEOUT_SECONDS,
            )
            last_status = status
            last_response = response

            if int(status or 0) == 200:
                if attempt > 1:
                    print(
                        f"[NVR CAMERA MGMT RECOVERY] {label} {endpoint} "
                        f"succeeded on attempt {attempt}."
                    )
                return status, response

            # Authentication/unsupported responses are deterministic.  Let the
            # caller try its alternate endpoint rather than wasting retries.
            if int(status or 0) in {400, 401, 403, 404, 405}:
                return status, response

            print(
                f"[NVR CAMERA MGMT RETRY] {label} {endpoint}: "
                f"HTTP {status} on attempt {attempt}/"
                f"{NVR_INPUTPROXY_DISCOVERY_MAX_ATTEMPTS}."
            )

        except requests.exceptions.ReadTimeout as error:
            last_status = 0
            last_response = (
                "ReadTimeout after "
                f"{NVR_INPUTPROXY_DISCOVERY_READ_TIMEOUT_SECONDS:.0f}s: {error}"
            )
            print(
                f"[NVR CAMERA MGMT RETRY] {label} {endpoint}: "
                f"read timeout on attempt {attempt}/"
                f"{NVR_INPUTPROXY_DISCOVERY_MAX_ATTEMPTS}."
            )
        except requests.exceptions.RequestException as error:
            last_status = 0
            last_response = f"RequestException: {error}"
            print(
                f"[NVR CAMERA MGMT RETRY] {label} {endpoint}: "
                f"request error on attempt {attempt}/"
                f"{NVR_INPUTPROXY_DISCOVERY_MAX_ATTEMPTS}: {error}"
            )
        except Exception as error:
            last_status = 0
            last_response = f"Exception: {error}"
            print(
                f"[NVR CAMERA MGMT RETRY] {label} {endpoint}: "
                f"unexpected error on attempt {attempt}/"
                f"{NVR_INPUTPROXY_DISCOVERY_MAX_ATTEMPTS}: {error}"
            )

        if attempt < NVR_INPUTPROXY_DISCOVERY_MAX_ATTEMPTS:
            time_module.sleep(NVR_INPUTPROXY_DISCOVERY_RETRY_WAIT_SECONDS)

    print(
        f"[NVR CAMERA MGMT WARNING] {label} {endpoint} remained unavailable "
        f"after {NVR_INPUTPROXY_DISCOVERY_MAX_ATTEMPTS} bounded attempt(s); "
        "continuing with conservative reconciliation where possible."
    )
    return last_status, last_response


def get_nvr_channel_detail(
    nvr_ip,
    nvr_username,
    nvr_password,
    channel_id,
):
    endpoints = [
        (
            f"/ISAPI/ContentMgmt/InputProxy/"
            f"channels/{channel_id}"
        ),
        (
            f"/ISAPI/ContentMgmt/InputProxy/"
            f"channels/{channel_id}?security=0"
        ),
    ]

    last_status = None
    last_response = ""

    for endpoint in endpoints:
        status, response = safe_get_nvr_input_proxy_xml(
            nvr_ip,
            nvr_username,
            nvr_password,
            endpoint,
        )

        last_status = status
        last_response = response

        if status == 200:
            parsed = parse_input_proxy_channels(response)

            if parsed:
                return {
                    "status": status,
                    "endpoint": endpoint,
                    "channel": parsed[0],
                    "response": response,
                }

    return {
        "status": last_status,
        "endpoint": endpoints[-1],
        "channel": None,
        "response": last_response,
    }


def discover_nvr_camera_channels(
    nvr_ip,
    nvr_username,
    nvr_password,
    expected_channel_count=None,
):
    """
    Return:
      configured_channels
      available_channel_ids
      backup_files
    """
    list_endpoints = [
        "/ISAPI/ContentMgmt/InputProxy/channels",
        "/ISAPI/ContentMgmt/InputProxy/channels?security=0",
    ]

    status_endpoints = [
        "/ISAPI/ContentMgmt/InputProxy/channels/status",
        (
            "/ISAPI/ContentMgmt/InputProxy/"
            "channels/status?security=0"
        ),
    ]

    list_response = ""
    list_status = None
    list_endpoint_used = ""

    for endpoint in list_endpoints:
        status, response = safe_get_nvr_input_proxy_xml(
            nvr_ip,
            nvr_username,
            nvr_password,
            endpoint,
        )

        if status == 200:
            list_status = status
            list_response = response
            list_endpoint_used = endpoint
            break

        list_status = status
        list_response = response
        list_endpoint_used = endpoint

    backup_files = []

    backup_files.append(
        save_nvr_camera_management_backup(
            nvr_ip,
            "channels_list_before",
            list_response,
        )
    )

    listed_channels = parse_input_proxy_channels(
        list_response
    )

    listed_ids = {
        str(channel.get("id", "")).strip()
        for channel in listed_channels
        if str(channel.get("id", "")).strip()
    }

    status_response = ""
    status_endpoint_used = ""
    status_status = None

    for endpoint in status_endpoints:
        status, response = safe_get_nvr_input_proxy_xml(
            nvr_ip,
            nvr_username,
            nvr_password,
            endpoint,
        )

        status_status = status

        if status == 200:
            status_response = response
            status_endpoint_used = endpoint
            break

        status_response = response
        status_endpoint_used = endpoint

    backup_files.append(
        save_nvr_camera_management_backup(
            nvr_ip,
            "channels_status_before",
            status_response,
        )
    )

    status_channels = parse_input_proxy_channels(
        status_response
    )

    runtime_by_id = parse_nvr_input_proxy_runtime_status(
        status_response
    )

    status_ids = {
        str(channel.get("id", "")).strip()
        for channel in status_channels
        if str(channel.get("id", "")).strip()
    }

    candidate_ids = sorted(
        listed_ids | status_ids,
        key=channel_id_sort_key,
    )

    discovery_degraded = (
        int(list_status or 0) != 200
        and int(status_status or 0) != 200
    )

    if not candidate_ids:
        if expected_channel_count is not None:
            # When the collection/status endpoints are temporarily hung, do
            # NOT probe every hardware slot. Probe only the channels Excel
            # expects. This keeps PASS 5 bounded and prevents a single busy
            # NVR from spending minutes on channels 1..8. Extra-channel
            # deletion is intentionally skipped in this degraded-discovery
            # condition because we do not have authoritative inventory data.
            candidate_ids = [
                str(index)
                for index in range(1, int(expected_channel_count) + 1)
            ]
        else:
            candidate_ids = [
                str(index)
                for index in range(
                    1,
                    NVR_CAMERA_MAX_CHANNELS + 1,
                )
            ]

    configured_channels = []

    # Use full data from list response whenever available.
    full_list_data = {
        channel["id"]: channel
        for channel in listed_channels
        if not is_blank(channel.get("ip_address"))
    }

    for channel_id in candidate_ids:
        if channel_id in full_list_data:
            configured_channels.append(
                full_list_data[channel_id]
            )
            continue

        detail = get_nvr_channel_detail(
            nvr_ip,
            nvr_username,
            nvr_password,
            channel_id,
        )

        if detail["status"] == 200:
            backup_files.append(
                save_nvr_camera_management_backup(
                    nvr_ip,
                    f"channel_{channel_id}_before",
                    detail["response"],
                )
            )

        channel = detail.get("channel")

        if (
            channel
            and not is_blank(channel.get("ip_address"))
        ):
            configured_channels.append(channel)

    configured_channels.sort(
        key=lambda channel: channel_id_sort_key(
            channel.get("id")
        )
    )

    return {
        "configured_channels": configured_channels,
        "available_channel_ids": candidate_ids,
        "backup_files": backup_files,
        "list_status": list_status,
        "list_endpoint": list_endpoint_used,
        "status_endpoint": status_endpoint_used,
        "status_status": status_status,
        "status_response": status_response,
        "runtime_by_id": runtime_by_id,
        "discovery_degraded": discovery_degraded,
    }


def build_input_proxy_channel_xml(
    channel_id,
    camera_ip,
    service_username,
    service_password,
):
    service_username = sanitize_credential_boundary(
        service_username,
        "NVR InputProxy ServiceAccount username",
        secret=False,
    )

    service_password = sanitize_credential_boundary(
        service_password,
        "NVR InputProxy ServiceAccount password",
        secret=True,
    )

    """
    Standard ISAPI plaintext XML.

    The script sends this only over HTTPS and uses the NVR admin Digest
    authentication already implemented in isapi_request().
    """
    certificate_validation = (
        "true"
        if NVR_CAMERA_CERTIFICATE_VALIDATION
        else "false"
    )

    default_admin_port = (
        "true"
        if NVR_CAMERA_DEFAULT_ADMIN_PORT
        else "false"
    )

    return f"""<?xml version="1.0" encoding="UTF-8"?>
<InputProxyChannel version="1.0" xmlns="http://www.std-cgi.com/ver20/XMLSchema">
  <id>{xml_escape(str(channel_id))}</id>
  <sourceInputPortDescriptor>
    <proxyProtocol>{xml_escape(NVR_CAMERA_PROTOCOL)}</proxyProtocol>
    <addressingFormatType>ipaddress</addressingFormatType>
    <ipAddress>{xml_escape(camera_ip)}</ipAddress>
    <managePortNo>{xml_escape(NVR_CAMERA_MANAGEMENT_PORT)}</managePortNo>
    <srcInputPort>{xml_escape(NVR_CAMERA_SOURCE_CHANNEL)}</srcInputPort>
    <userName>{xml_escape(service_username)}</userName>
    <password>{xml_escape(service_password)}</password>
    <streamType>{xml_escape(NVR_CAMERA_STREAM_TYPE)}</streamType>
  </sourceInputPortDescriptor>
  <certificateValidationEnabled>{certificate_validation}</certificateValidationEnabled>
  <defaultAdminPortEnabled>{default_admin_port}</defaultAdminPortEnabled>
</InputProxyChannel>"""


def normalize_nvr_input_proxy_bool(value):
    """Normalize observed InputProxy booleans; blank stays unverified."""
    raw = str(value if value is not None else "").strip().lower()

    if raw in {"true", "1", "yes", "on", "enabled"}:
        return "true"
    if raw in {"false", "0", "no", "off", "disabled"}:
        return "false"

    # Missing/unknown is intentionally NOT coerced to False.  A no-op is only
    # safe after the device proves both requested flags.
    return ""


def nvr_input_proxy_static_matches_expected(
    channel,
    camera_ip,
    service_username,
):
    """
    Compare all observable InputProxy settings required by this script.

    certificateValidationEnabled and defaultAdminPortEnabled are security/
    connectivity state, not optional metadata. Missing values are unverified
    and therefore do not qualify for the no-op optimization.
    """
    if not channel:
        return False

    expected = {
        "ip_address": str(camera_ip).strip(),
        "manage_port": str(NVR_CAMERA_MANAGEMENT_PORT).strip(),
        "source_channel": str(NVR_CAMERA_SOURCE_CHANNEL).strip(),
        "username": str(service_username).strip(),
        "protocol": str(NVR_CAMERA_PROTOCOL).strip().upper(),
        "stream_type": str(NVR_CAMERA_STREAM_TYPE).strip().lower(),
        "certificate_validation_enabled": (
            "true" if NVR_CAMERA_CERTIFICATE_VALIDATION else "false"
        ),
        "default_admin_port_enabled": (
            "true" if NVR_CAMERA_DEFAULT_ADMIN_PORT else "false"
        ),
    }

    actual = {
        "ip_address": str(channel.get("ip_address", "") or "").strip(),
        "manage_port": str(channel.get("manage_port", "") or "").strip(),
        "source_channel": str(channel.get("source_channel", "") or "").strip(),
        "username": str(channel.get("username", "") or "").strip(),
        "protocol": str(channel.get("protocol", "") or "").strip().upper(),
        "stream_type": str(channel.get("stream_type", "") or "").strip().lower(),
        "certificate_validation_enabled": normalize_nvr_input_proxy_bool(
            channel.get("certificate_validation_enabled", "")
        ),
        "default_admin_port_enabled": normalize_nvr_input_proxy_bool(
            channel.get("default_admin_port_enabled", "")
        ),
    }

    return actual == expected


def response_indicates_isapi_success(
    status,
    response,
):
    if status in [200, 201, 204]:
        if is_blank(response):
            return True

        response_lower = str(response).lower()

        if (
            "<statuscode>1</statuscode>" in response_lower
            or '"statuscode":1' in response_lower
            or '"statuscode": 1' in response_lower
            or "<statusstring>ok</statusstring>" in response_lower
            or '"statusstring":"ok"' in response_lower
            or '"statusstring": "ok"' in response_lower
        ):
            return True

        # Some firmware returns the updated XML rather than a status body.
        if (
            "<inputproxychannel" in response_lower
            or "<responseStatus" in response
        ):
            return True

        # HTTP 200 without an explicit error is treated as accepted.
        if "error" not in response_lower:
            return True

    return False


def configure_nvr_camera_channel(
    nvr_ip,
    nvr_username,
    nvr_password,
    channel_id,
    camera_ip,
    service_username,
    service_password,
):
    """
    Configure one InputProxy channel using bounded writes.

    A write timeout is not automatically treated as rejection: the function
    performs a bounded read-back because DS-E08NI-Q2 can apply a change while
    delaying/lossing the HTTP response.
    """
    xml_payload = build_input_proxy_channel_xml(
        channel_id,
        camera_ip,
        service_username,
        service_password,
    )

    verify_input_proxy_payload_credentials(
        xml_payload,
        service_username,
        service_password,
    )

    endpoints = [
        f"/ISAPI/ContentMgmt/InputProxy/channels/{channel_id}",
        f"/ISAPI/ContentMgmt/InputProxy/channels/{channel_id}?security=0",
    ]

    attempts = []

    def bounded_readback_matches():
        detail = get_nvr_channel_detail(
            nvr_ip,
            nvr_username,
            nvr_password,
            channel_id,
        )
        return (
            nvr_input_proxy_static_matches_expected(
                detail.get("channel"),
                camera_ip,
                service_username,
            ),
            detail,
        )

    for endpoint in endpoints:
        try:
            status, response = put_xml_with_timeout(
                nvr_ip,
                nvr_username,
                nvr_password,
                endpoint,
                xml_payload,
                NVR_INPUTPROXY_WRITE_READ_TIMEOUT_SECONDS,
                NVR_INPUTPROXY_WRITE_CONNECT_TIMEOUT_SECONDS,
            )
        except Exception as error:
            status = 0
            response = (
                f"{type(error).__name__}: "
                f"{str(error).strip() or repr(error)}"
            )

        attempts.append({
            "method": "PUT",
            "endpoint": endpoint,
            "status": status,
            "response": response,
        })

        if response_indicates_isapi_success(status, response):
            return {
                "ok": True,
                "method": "PUT",
                "endpoint": endpoint,
                "status": status,
                "response": response,
                "payload": xml_payload,
                "attempts": attempts,
            }

        if int(status or 0) == 0:
            matches, detail = bounded_readback_matches()
            if matches:
                return {
                    "ok": True,
                    "method": "PUT-timeout-readback-verified",
                    "endpoint": endpoint,
                    "status": detail.get("status", 200),
                    "response": (
                        "PUT timed out, but bounded InputProxy read-back "
                        "matches the requested static channel."
                    ),
                    "payload": xml_payload,
                    "attempts": attempts,
                }

    # Create-channel fallback for firmware requiring collection POST.
    post_endpoints = [
        "/ISAPI/ContentMgmt/InputProxy/channels",
        "/ISAPI/ContentMgmt/InputProxy/channels?security=0",
    ]

    for endpoint in post_endpoints:
        try:
            status, response = post_xml_with_timeout(
                nvr_ip,
                nvr_username,
                nvr_password,
                endpoint,
                xml_payload,
                NVR_INPUTPROXY_WRITE_READ_TIMEOUT_SECONDS,
                NVR_INPUTPROXY_WRITE_CONNECT_TIMEOUT_SECONDS,
            )
        except Exception as error:
            status = 0
            response = (
                f"{type(error).__name__}: "
                f"{str(error).strip() or repr(error)}"
            )

        attempts.append({
            "method": "POST",
            "endpoint": endpoint,
            "status": status,
            "response": response,
        })

        if response_indicates_isapi_success(status, response):
            return {
                "ok": True,
                "method": "POST",
                "endpoint": endpoint,
                "status": status,
                "response": response,
                "payload": xml_payload,
                "attempts": attempts,
            }

        if int(status or 0) == 0:
            matches, detail = bounded_readback_matches()
            if matches:
                return {
                    "ok": True,
                    "method": "POST-timeout-readback-verified",
                    "endpoint": endpoint,
                    "status": detail.get("status", 200),
                    "response": (
                        "POST timed out, but bounded InputProxy read-back "
                        "matches the requested static channel."
                    ),
                    "payload": xml_payload,
                    "attempts": attempts,
                }

    return {
        "ok": False,
        "method": attempts[-1]["method"] if attempts else "NONE",
        "endpoint": attempts[-1]["endpoint"] if attempts else "",
        "status": attempts[-1]["status"] if attempts else 0,
        "response": attempts[-1]["response"] if attempts else "",
        "payload": xml_payload,
        "attempts": attempts,
    }


def delete_nvr_camera_channel(
    nvr_ip,
    nvr_username,
    nvr_password,
    channel_id,
):
    endpoints = [
        (
            f"/ISAPI/ContentMgmt/InputProxy/"
            f"channels/{channel_id}"
        ),
        (
            f"/ISAPI/ContentMgmt/InputProxy/"
            f"channels/{channel_id}?security=0"
        ),
    ]

    attempts = []

    for endpoint in endpoints:
        status, response = delete_xml(
            nvr_ip,
            nvr_username,
            nvr_password,
            endpoint,
        )

        attempts.append({
            "endpoint": endpoint,
            "status": status,
            "response": response,
        })

        if response_indicates_isapi_success(
            status,
            response,
        ):
            return {
                "ok": True,
                "endpoint": endpoint,
                "status": status,
                "response": response,
                "attempts": attempts,
            }

        response_lower = str(response).lower()

        if (
            status in [400, 404]
            and (
                "not exist" in response_lower
                or "notexist" in response_lower
                or "no channel" in response_lower
            )
        ):
            return {
                "ok": True,
                "endpoint": endpoint,
                "status": status,
                "response": response,
                "attempts": attempts,
                "already_empty": True,
            }

    return {
        "ok": False,
        "endpoint": attempts[-1]["endpoint"],
        "status": attempts[-1]["status"],
        "response": attempts[-1]["response"],
        "attempts": attempts,
    }


def expected_camera_rows_for_nvr(
    nvr_row,
    expected_camera_map,
):
    site = normalize_site_id(
        get_value(nvr_row, "Site ID")
    )

    return (
        site,
        list(expected_camera_map.get(site, [])),
    )



def inspect_nvr_camera_runtime_status(
    nvr_ip,
    nvr_username,
    nvr_password,
    expected_channel_ids,
):
    """
    Final runtime inspection using the SAME classifier as the recovery gate.

    Policy:
      - explicit authentication/connection/certificate failure => blocking;
      - online=true => ready;
      - proxy IDs with no explicit failure => ready;
      - online=false/blank + no error + no proxy IDs => inconclusive advisory;
      - status endpoint unavailable => unchecked; static validation remains
        authoritative, matching the recovery gate's unavailable-status rule.

    Inconclusive records are not independently marked FAILED here because the
    bounded recovery result is included in the final PASS 5 decision. This
    avoids contradictory rules between recovery and final validation.
    """
    snapshot = get_nvr_input_proxy_runtime_snapshot(
        nvr_ip,
        nvr_username,
        nvr_password,
    )

    if not snapshot.get("checked"):
        return {
            "ok": True,
            "checked": False,
            "endpoint": snapshot.get("endpoint", ""),
            "issues": [],
            "advisories": [],
            "detail": (
                "Runtime status endpoint unavailable; static Camera "
                "Management validation remains authoritative."
            ),
        }

    expected_channel_ids = {
        str(value)
        for value in expected_channel_ids
    }

    records = snapshot.get("records", {})
    issues = []
    advisories = []
    ready_ids = []

    for channel_id in sorted(
        expected_channel_ids,
        key=channel_id_sort_key,
    ):
        record = records.get(channel_id)
        classification = classify_nvr_input_proxy_runtime_record(record)
        state = classification.get("state")
        problem = classification.get("problem", "")

        if state == "ready":
            ready_ids.append(channel_id)
            continue

        item = {
            "channel_id": channel_id,
            "online": str((record or {}).get("online", "") or ""),
            "status": str((record or {}).get("detect_result", "") or ""),
            "problem": problem,
            "authentication_error": (
                "username" in problem.lower()
                or "password" in problem.lower()
                or "auth" in problem.lower()
                or "login" in problem.lower()
            ),
        }

        if state == "failed":
            issues.append(item)
        else:
            item["reason"] = (
                "runtime telemetry is inconclusive and must be resolved by "
                "the bounded recovery gate before PASS 6"
            )
            advisories.append(item)

    if issues:
        return {
            "ok": False,
            "checked": True,
            "endpoint": snapshot.get("endpoint", ""),
            "issues": issues,
            "advisories": advisories,
            "ready_ids": ready_ids,
            "detail": (
                "Runtime status shows one or more explicit authentication/"
                "connection/certificate failures."
            ),
        }

    return {
        "ok": True,
        "checked": True,
        "endpoint": snapshot.get("endpoint", ""),
        "issues": [],
        "advisories": advisories,
        "ready_ids": ready_ids,
        "detail": (
            f"Runtime checked for {len(expected_channel_ids)} expected "
            f"channel(s); {len(ready_ids)} ready; "
            f"{len(advisories)} inconclusive record(s). Final PASS 5 gating "
            "also requires the bounded recovery outcome."
        ),
    }


def validate_nvr_camera_management(
    nvr_ip,
    nvr_username,
    nvr_password,
    expected_camera_ips,
):
    discovery = discover_nvr_camera_channels(
        nvr_ip,
        nvr_username,
        nvr_password,
        expected_channel_count=len(expected_camera_ips),
    )

    actual_by_id = {
        str(channel.get("id")): str(
            channel.get(
                "ip_address",
                "",
            )
        ).strip()
        for channel in discovery["configured_channels"]
        if not is_blank(
            channel.get(
                "ip_address"
            )
        )
    }

    expected_by_id = {
        str(index): camera_ip
        for index, camera_ip in enumerate(
            expected_camera_ips,
            start=1,
        )
    }

    missing_or_mismatched = []

    for channel_id, expected_ip in expected_by_id.items():
        actual_ip = actual_by_id.get(
            channel_id,
            "",
        )

        if actual_ip != expected_ip:
            missing_or_mismatched.append({
                "channel_id": channel_id,
                "expected_ip": expected_ip,
                "actual_ip": actual_ip,
            })

    extra_channels = [
        {
            "channel_id": channel_id,
            "actual_ip": actual_ip,
        }
        for channel_id, actual_ip in actual_by_id.items()
        if channel_id not in expected_by_id
    ]

    runtime_status = inspect_nvr_camera_runtime_status(
        nvr_ip,
        nvr_username,
        nvr_password,
        expected_by_id.keys(),
    )

    return {
        "ok": (
            not missing_or_mismatched
            and not extra_channels
            and runtime_status["ok"]
        ),
        "actual_by_id": actual_by_id,
        "expected_by_id": expected_by_id,
        "missing_or_mismatched": missing_or_mismatched,
        "extra_channels": extra_channels,
        "runtime_status": runtime_status,
        "discovery": discovery,
    }


def service_account_dependency_blockers(camera_rows, results):
    """
    Return camera rows whose ServiceAccount creation was requested in this
    run but was not proven ready.

    Camera Management authenticates to each camera with ServiceAccount.  If
    User Management failed first, continuing to InputProxy only creates a
    configured-looking channel that remains offline and later makes
    StreamingProxy 101/102 fail with 403/notSupport.  Block that downstream
    work instead of generating misleading secondary failures.
    """
    blockers = []

    for camera_row in camera_rows:
        if not user_management_creation_requested(camera_row):
            # The workflow did not promise to create/verify this account in
            # this run; it may already exist from the imported configuration.
            continue

        camera_ip = get_value(camera_row, "Current IP", "current_ip")

        matching = [
            record
            for record in results
            if str(record.get("IP", "")).strip() == str(camera_ip).strip()
        ]

        sa_records = [
            record
            for record in matching
            if str(record.get("Task", "")).strip() == "Create User ServiceAccount"
        ]

        sa_ready = any(
            normalize_result_value(record.get("Result")) in {"OK", "SKIPPED"}
            and "blocked" not in str(record.get("Detail", "")).lower()
            for record in sa_records
        )

        if sa_ready:
            continue

        overall_records = [
            record
            for record in matching
            if str(record.get("Task", "")).strip() == "Create User Management"
        ]

        overall_failure = any(
            result_is_failure(record)
            or (
                normalize_result_value(record.get("Result")) == "SKIPPED"
                and "blocked" in str(record.get("Detail", "")).lower()
            )
            for record in overall_records
        )

        if overall_failure or not sa_records:
            blockers.append({
                "ip": camera_ip,
                "hostname": get_value(camera_row, "Hostname"),
                "reason": (
                    "ServiceAccount creation was not proven ready before "
                    "NVR Camera Management"
                ),
            })

    return blockers


def nvr_camera_management_ready_for_streams(results, nvr_ip):
    """Return (ready, detail) from the completed PASS 5 validation result."""
    matching = [
        record
        for record in results
        if str(record.get("IP", "")).strip() == str(nvr_ip).strip()
    ]

    validations = [
        record
        for record in matching
        if str(record.get("Task", "")).strip() == "Validate NVR Camera Management"
    ]

    if validations:
        latest = validations[-1]
        result_value = normalize_result_value(latest.get("Result"))
        if result_value == "OK":
            return True, str(latest.get("Detail", ""))
        return False, (
            f"PASS 5 validation result={result_value}; "
            f"detail={latest.get('Detail', '')}"
        )

    sync_records = [
        record
        for record in matching
        if str(record.get("Task", "")).strip() in {
            "Sync NVR Camera Management",
            "Final NVR Camera Management Sync",
        }
    ]

    if sync_records:
        latest = sync_records[-1]
        if normalize_result_value(latest.get("Result")) in {
            "FAILED", "ERROR", "SKIPPED"
        }:
            return False, (
                f"PASS 5 sync result={latest.get('Result')}; "
                f"task={latest.get('Task')}; "
                f"detail={latest.get('Detail', '')}"
            )

    # Compatibility fallback for workflows where PASS 5 did not create a
    # summary record.  Do not invent a failure.
    return True, "No blocking PASS 5 validation result was found."


def get_nvr_input_proxy_runtime_snapshot(
    nvr_ip,
    nvr_username,
    nvr_password,
):
    endpoints = [
        "/ISAPI/ContentMgmt/InputProxy/channels/status",
        "/ISAPI/ContentMgmt/InputProxy/channels/status?security=0",
    ]

    last_status = 0
    last_response = ""
    last_endpoint = endpoints[-1]

    for endpoint in endpoints:
        status, response = safe_get_nvr_input_proxy_xml(
            nvr_ip,
            nvr_username,
            nvr_password,
            endpoint,
            label="InputProxy runtime status",
        )
        last_status = status
        last_response = response
        last_endpoint = endpoint

        if int(status or 0) == 200:
            return {
                "checked": True,
                "status": status,
                "response": response,
                "endpoint": endpoint,
                "records": parse_nvr_input_proxy_runtime_status(response),
            }

    return {
        "checked": False,
        "status": last_status,
        "response": last_response,
        "endpoint": last_endpoint,
        "records": {},
    }


def wait_for_nvr_input_proxy_runtime_ready(
    nvr_ip,
    nvr_username,
    nvr_password,
    camera_rows,
    service_username,
    service_password,
    results,
):
    """
    Make InputProxy runtime readiness a real gate before StreamingProxy.

    Phase 1: allow a short no-write grace period.
    Phase 2: re-apply ONLY channels still offline once, with bounded writes.
    Phase 3: poll for a bounded recovery interval.

    Persistent netUnreachable/authentication failure is returned as a failure
    so PASS 6 is skipped rather than producing many misleading proxy errors.
    """
    expected = {
        str(index): row
        for index, row in enumerate(camera_rows, start=1)
    }

    def evaluate(snapshot):
        if not snapshot.get("checked"):
            return False, [], []

        records = snapshot.get("records", {})
        pending = []
        ready = []

        for channel_id, camera_row in expected.items():
            record = records.get(channel_id)

            if nvr_input_proxy_runtime_record_ready(record):
                ready.append(channel_id)
            else:
                pending.append({
                    "channel_id": channel_id,
                    "camera_ip": get_value(camera_row, "Current IP"),
                    "problem": nvr_input_proxy_runtime_record_problem(record),
                    "record": record or {},
                })

        return (not pending), ready, pending

    # Phase A: no-write grace period.
    grace_deadline = (
        time_module.monotonic()
        + max(0.0, float(NVR_INPUTPROXY_RUNTIME_INITIAL_GRACE_SECONDS))
    )
    last_snapshot = None
    last_pending = []

    while True:
        snapshot = get_nvr_input_proxy_runtime_snapshot(
            nvr_ip,
            nvr_username,
            nvr_password,
        )
        last_snapshot = snapshot
        all_ready, ready_ids, pending = evaluate(snapshot)
        last_pending = pending

        if all_ready:
            print(
                f"[OK] [NVR CAMERA MGMT RUNTIME] {nvr_ip}: "
                f"all {len(expected)} expected channel(s) are runtime-ready."
            )
            return {
                "ok": True,
                "checked": True,
                "ready_ids": ready_ids,
                "pending": [],
                "detail": "All expected InputProxy channels are runtime-ready.",
            }

        if time_module.monotonic() >= grace_deadline:
            break

        if snapshot.get("checked"):
            summary = ", ".join(
                f"CH{item['channel_id']}={item['problem']}"
                for item in pending
            )
            print(
                f"[NVR CAMERA MGMT RUNTIME] {nvr_ip}: "
                f"waiting for channel binding ({summary})."
            )

        time_module.sleep(NVR_INPUTPROXY_RUNTIME_POLL_SECONDS)

    # If status itself is unavailable, don't invent an offline result.
    if last_snapshot and not last_snapshot.get("checked"):
        return {
            "ok": True,
            "checked": False,
            "ready_ids": [],
            "pending": [],
            "detail": (
                "InputProxy runtime status endpoint unavailable; "
                "static Camera Management validation remains authoritative."
            ),
        }

    # Phase B: one controlled refresh of only the still-offline channels.
    if NVR_INPUTPROXY_RUNTIME_REAPPLY_ONCE and last_pending:
        print(
            f"[NVR CAMERA MGMT RECOVERY] {nvr_ip}: "
            f"{len(last_pending)} channel(s) still not runtime-ready; "
            "re-applying only those InputProxy entries once."
        )

        for item in last_pending:
            channel_id = item["channel_id"]
            camera_ip = item["camera_ip"]

            local_manage_port = False
            local_https = False

            try:
                local_manage_port = _camera_tcp_port_open(
                    camera_ip,
                    int(NVR_CAMERA_MANAGEMENT_PORT),
                    timeout=1.0,
                )
            except Exception:
                pass

            try:
                local_https = _camera_tcp_port_open(
                    camera_ip,
                    443,
                    timeout=1.0,
                )
            except Exception:
                pass

            print(
                f"[NVR CAMERA MGMT RECOVERY] CH{channel_id} {camera_ip}: "
                f"NVR={item['problem']}; "
                f"localTCP/{NVR_CAMERA_MANAGEMENT_PORT}={local_manage_port}; "
                f"localTCP/443={local_https}."
            )

            operation = configure_nvr_camera_channel(
                nvr_ip,
                nvr_username,
                nvr_password,
                channel_id,
                camera_ip,
                service_username,
                service_password,
            )

            add_result(
                results,
                nvr_ip,
                f"Recover NVR Camera Channel {channel_id}",
                operation.get("endpoint", ""),
                operation.get("status", ""),
                "OK" if operation.get("ok") else "FAILED",
                (
                    f"Camera IP={camera_ip}; "
                    f"previousRuntime={item['problem']}; "
                    f"method={operation.get('method')}; "
                    f"localTCP/{NVR_CAMERA_MANAGEMENT_PORT}={local_manage_port}; "
                    f"localTCP/443={local_https}; "
                    f"response={str(operation.get('response', ''))[:300]}"
                ),
            )

    # Phase C: bounded post-refresh recovery.
    recovery_deadline = (
        time_module.monotonic()
        + max(1.0, float(NVR_INPUTPROXY_RUNTIME_RECOVERY_TIMEOUT_SECONDS))
    )

    while time_module.monotonic() < recovery_deadline:
        snapshot = get_nvr_input_proxy_runtime_snapshot(
            nvr_ip,
            nvr_username,
            nvr_password,
        )
        last_snapshot = snapshot
        all_ready, ready_ids, pending = evaluate(snapshot)
        last_pending = pending

        if all_ready:
            print(
                f"[OK] [NVR CAMERA MGMT RUNTIME] {nvr_ip}: "
                "all expected channels recovered; PASS 6 may proceed."
            )
            return {
                "ok": True,
                "checked": True,
                "ready_ids": ready_ids,
                "pending": [],
                "detail": (
                    "All expected InputProxy channels became runtime-ready "
                    "after bounded recovery."
                ),
            }

        if snapshot.get("checked"):
            summary = ", ".join(
                f"CH{item['channel_id']}={item['problem']}"
                for item in pending
            )
            print(
                f"[NVR CAMERA MGMT RUNTIME] {nvr_ip}: "
                f"recovery pending ({summary})."
            )

        time_module.sleep(NVR_INPUTPROXY_RUNTIME_POLL_SECONDS)

    pending_summary = ", ".join(
        f"CH{item['channel_id']}={item['problem']}"
        for item in last_pending
    )

    return {
        "ok": False,
        "checked": bool(last_snapshot and last_snapshot.get("checked")),
        "ready_ids": [],
        "pending": last_pending,
        "detail": (
            "InputProxy runtime did not recover within "
            f"{NVR_INPUTPROXY_RUNTIME_RECOVERY_TIMEOUT_SECONDS:.0f}s; "
            f"{pending_summary or 'runtime state unavailable'}"
        ),
    }


def sync_nvr_camera_management(
    row,
    expected_camera_map,
    account_configuration,
    results,
):
    """
    Reconcile one NVR Camera Management list with Excel.

    Rules:
      - Expected camera count comes from matching Site ID camera rows.
      - Channels are assigned sequentially:
            Discreet camera(s), then Dome camera(s).
      - Existing channels 1..N are updated to expected camera IPs.
      - Missing channels are added/configured.
      - Configured channels beyond N are deleted.
      - ServiceAccount username/password are pulled from
        User Management Account.
    """
    if not is_nvr_device_row(row):
        return

    nvr_ip = get_value(row, "Current IP")
    nvr_username = get_value(row, "Username")
    nvr_password = get_value(row, "Password")

    if not ENABLE_NVR_CAMERA_MANAGEMENT_SYNC:
        print(
            f"[SKIP] {nvr_ip} NVR Camera Management sync disabled."
        )

        add_result(
            results,
            nvr_ip,
            "Sync NVR Camera Management",
            "",
            "",
            "SKIPPED",
            "ENABLE_NVR_CAMERA_MANAGEMENT_SYNC=False",
        )
        return

    site, camera_rows = expected_camera_rows_for_nvr(
        row,
        expected_camera_map,
    )

    if not site:
        print(
            f"[FAILED] {nvr_ip} NVR Site ID is blank."
        )

        add_result(
            results,
            nvr_ip,
            "Sync NVR Camera Management",
            "",
            "",
            "FAILED",
            "NVR Site ID is blank",
        )
        return

    expected_camera_ips = [
        get_value(camera_row, "Current IP")
        for camera_row in camera_rows
        if not is_blank(
            get_value(camera_row, "Current IP")
        )
    ]

    service_account_blockers = service_account_dependency_blockers(
        camera_rows,
        results,
    )

    if service_account_blockers:
        blocker_text = "; ".join(
            f"{item['ip']} ({item.get('hostname') or 'camera'})"
            for item in service_account_blockers
        )
        detail = (
            "NVR Camera Management was blocked because one or more expected "
            "cameras did not complete ServiceAccount creation in the current "
            f"run: {blocker_text}. Fix User Management first; downstream "
            "InputProxy/StreamingProxy work was intentionally skipped to avoid "
            "offline channels and 403/notSupport retries."
        )
        print(f"[NVR CAMERA MGMT BLOCKED] {nvr_ip}: {detail}")
        add_result(
            results,
            nvr_ip,
            "Sync NVR Camera Management",
            "/ISAPI/ContentMgmt/InputProxy/channels",
            "",
            "SKIPPED",
            detail,
        )
        return

    duplicate_ips = sorted({
        camera_ip
        for camera_ip in expected_camera_ips
        if expected_camera_ips.count(camera_ip) > 1
    })

    if duplicate_ips:
        print(
            f"[FAILED] {nvr_ip} duplicate camera IPs in Excel: "
            f"{', '.join(duplicate_ips)}"
        )

        add_result(
            results,
            nvr_ip,
            "Sync NVR Camera Management",
            "",
            "",
            "FAILED",
            (
                "Duplicate expected camera IPs: "
                + ", ".join(duplicate_ips)
            ),
        )
        return

    expected_count = len(expected_camera_ips)

    print("=" * 100)
    print(f"[NVR CAMERA MGMT] NVR IP        : {nvr_ip}")
    print(f"[NVR CAMERA MGMT] Site ID : {site}")
    print(f"[NVR CAMERA MGMT] Expected count: {expected_count}")

    for index, camera_row in enumerate(
        camera_rows,
        start=1,
    ):
        print(
            f"[NVR CAMERA MGMT] Channel {index}: "
            f"{get_value(camera_row, 'Current IP')} "
            f"({get_value(camera_row, 'Hostname')})"
        )

    if (
        NVR_CAMERA_SYNC_REQUIRE_EXPECTED_CAMERAS
        and expected_count == 0
    ):
        print(
            f"[FAILED] No camera rows found for Site {site}. "
            "No NVR channel will be deleted."
        )

        add_result(
            results,
            nvr_ip,
            "Sync NVR Camera Management",
            "",
            "",
            "FAILED",
            (
                f"No camera rows found for Site {site}; "
                "safety stop"
            ),
        )
        return

    if expected_count > NVR_CAMERA_MAX_CHANNELS:
        print(
            f"[FAILED] Expected {expected_count} cameras, "
            f"exceeding configured maximum "
            f"{NVR_CAMERA_MAX_CHANNELS}."
        )

        add_result(
            results,
            nvr_ip,
            "Sync NVR Camera Management",
            "",
            "",
            "FAILED",
            (
                f"Expected camera count {expected_count} "
                f"exceeds maximum {NVR_CAMERA_MAX_CHANNELS}"
            ),
        )
        return

    service_account = get_service_account_for_site(
        account_configuration,
        site,
    )

    if not service_account:
        print(
            "[FAILED] ServiceAccount username/password "
            "not found in Excel."
        )

        add_result(
            results,
            nvr_ip,
            "Sync NVR Camera Management",
            USER_MANAGEMENT_ACCOUNT_SHEET,
            "",
            "FAILED",
            "ServiceAccount username/password not found",
        )
        return

    service_username = sanitize_credential_boundary(
        service_account.get(
            "username",
            "",
        ),
        f"NVR {nvr_ip} Camera Management ServiceAccount username",
        secret=False,
    )

    service_password = sanitize_credential_boundary(
        service_account.get(
            "password",
            "",
        ),
        f"NVR {nvr_ip} Camera Management ServiceAccount password",
        secret=True,
    )

    if (
        is_blank(service_username)
        or is_blank(service_password)
    ):
        add_result(
            results,
            nvr_ip,
            "Sync NVR Camera Management",
            USER_MANAGEMENT_ACCOUNT_SHEET,
            "",
            "FAILED",
            "ServiceAccount username/password became blank after credential sanitization.",
        )

        print(
            f"[FAILED] {nvr_ip} ServiceAccount credential is blank "
            "after sanitization."
        )

        return

    print(
        f"[NVR CAMERA MGMT] Service username: "
        f"{service_username}"
    )
    print(
        "[NVR CAMERA MGMT] Service password: "
        "loaded from Excel"
    )

    discovery_before = discover_nvr_camera_channels(
        nvr_ip,
        nvr_username,
        nvr_password,
        expected_channel_count=expected_count,
    )

    configured_before = (
        discovery_before["configured_channels"]
    )

    configured_before_by_id = {
        str(channel.get("id", "")).strip(): channel
        for channel in configured_before
        if str(channel.get("id", "")).strip()
    }

    runtime_before_by_id = (
        discovery_before.get("runtime_by_id", {})
    )

    available_ids = (
        discovery_before["available_channel_ids"]
    )

    print(
        f"[NVR CAMERA MGMT] Configured before: "
        f"{len(configured_before)}"
    )
    print(
        f"[NVR CAMERA MGMT] Available channel IDs: "
        f"{', '.join(available_ids)}"
    )

    if discovery_before.get("discovery_degraded"):
        print(
            "[NVR CAMERA MGMT DEGRADED DISCOVERY] Collection/status GET "
            "was temporarily unavailable. Only Excel-expected channel IDs "
            "will be probed/configured; extra-channel deletion is disabled "
            "for this run."
        )

    numeric_available_ids = [
        channel_id
        for channel_id in available_ids
        if str(channel_id).isdigit()
    ]

    if len(numeric_available_ids) < expected_count:
        # The list/status endpoint can expose only the currently-created
        # channels. It is not necessarily the hardware capacity. Example:
        # four configured channels may be returned even though this 8-channel
        # NVR can create channel 5.
        desired_channel_ids = [
            str(index)
            for index in range(
                1,
                expected_count + 1,
            )
        ]

        missing_channel_ids = [
            channel_id
            for channel_id in desired_channel_ids
            if channel_id not in numeric_available_ids
        ]

        print(
            f"[NVR CAMERA MGMT] NVR currently exposes "
            f"{len(numeric_available_ids)} channel ID(s), while Excel "
            f"expects {expected_count} camera(s)."
        )

        print(
            f"[NVR CAMERA MGMT] Missing channel ID(s) will be "
            f"created automatically: {', '.join(missing_channel_ids)}"
        )

        print(
            "[NVR CAMERA MGMT] Creation method: PUT /channels/<id>, "
            "then POST /channels fallback if this firmware requires it."
        )

        # Extend the local candidate list so diagnostics/reporting reflect
        # the channels that this run is going to create.
        numeric_available_ids = sorted(
            set(
                numeric_available_ids
            )
            | set(
                desired_channel_ids
            ),
            key=channel_id_sort_key,
        )

    if DRY_RUN:
        print(
            f"[DRY RUN] Would configure channels 1.."
            f"{expected_count} and delete extras."
        )

        add_result(
            results,
            nvr_ip,
            "Sync NVR Camera Management",
            "/ISAPI/ContentMgmt/InputProxy/channels",
            "",
            "DRY_RUN",
            (
                f"Site={site}; "
                f"Expected cameras={expected_count}; "
                f"Configured before={len(configured_before)}"
            ),
        )
        return

    configured_success_count = 0
    failed_operations = []

    # ================================================================
    # Configure/update every expected camera sequentially
    # ================================================================
    for channel_number, camera_row in enumerate(
        camera_rows,
        start=1,
    ):
        camera_ip = get_value(
            camera_row,
            "Current IP",
        )

        camera_hostname = get_value(
            camera_row,
            "Hostname",
        )

        channel_id_text = str(
            channel_number
        )

        if channel_id_text not in available_ids:
            print(
                f"[NVR CAMERA MGMT] Channel {channel_number} does not "
                "exist in the initial NVR list/status response -> "
                "CREATE + CONFIGURE."
            )
        else:
            print(
                f"[NVR CAMERA MGMT] Configuring existing channel "
                f"{channel_number}: {camera_ip}"
            )

        existing_channel = configured_before_by_id.get(
            channel_id_text
        )
        existing_runtime = runtime_before_by_id.get(
            channel_id_text,
            {},
        )

        # v123: collection/list responses on some firmware omit the two
        # security flags. Missing means unverified, not False. Query the
        # per-channel detail once before deciding that the write is a no-op.
        if existing_channel and (
            is_blank(existing_channel.get("certificate_validation_enabled"))
            or is_blank(existing_channel.get("default_admin_port_enabled"))
        ):
            detail_probe = get_nvr_channel_detail(
                nvr_ip,
                nvr_username,
                nvr_password,
                channel_id_text,
            )
            if detail_probe.get("channel"):
                existing_channel = detail_probe.get("channel")

        static_already_correct = (
            nvr_input_proxy_static_matches_expected(
                existing_channel,
                camera_ip,
                service_username,
            )
        )

        if static_already_correct:
            configured_success_count += 1

            if nvr_input_proxy_runtime_record_ready(existing_runtime):
                runtime_note = "runtime-ready"
            else:
                runtime_note = (
                    "static settings already correct; runtime currently "
                    f"{nvr_input_proxy_runtime_record_problem(existing_runtime)}; "
                    "write deferred to bounded recovery gate"
                )

            print(
                f"[NVR CAMERA MGMT NO-OP] Channel {channel_number}: "
                f"{camera_ip}; {runtime_note}."
            )

            add_result(
                results,
                nvr_ip,
                f"Configure NVR Camera Channel {channel_number}",
                f"/ISAPI/ContentMgmt/InputProxy/channels/{channel_number}",
                200,
                "OK",
                (
                    f"Camera IP={camera_ip}; Hostname={camera_hostname}; "
                    f"{runtime_note}; no unnecessary InputProxy PUT sent."
                ),
            )
            continue

        operation = configure_nvr_camera_channel(
            nvr_ip,
            nvr_username,
            nvr_password,
            str(channel_number),
            camera_ip,
            service_username,
            service_password,
        )

        if operation["ok"]:
            configured_success_count += 1

            print(
                f"[OK] NVR channel {channel_number} -> "
                f"{camera_ip}; method={operation.get('method')}"
            )

            add_result(
                results,
                nvr_ip,
                (
                    f"Configure NVR Camera Channel "
                    f"{channel_number}"
                ),
                operation["endpoint"],
                operation["status"],
                "OK",
                (
                    f"Site={site}; "
                    f"Camera IP={camera_ip}; "
                    f"Hostname={camera_hostname}; "
                    f"Service username={service_username}; "
                    "Password loaded from Excel"
                ),
            )
        else:
            response_preview = str(
                operation.get("response", "")
            )[:500]

            failed_operations.append(
                f"Channel {channel_number}: "
                f"status={operation.get('status')}"
            )

            print(
                f"[FAILED] NVR channel {channel_number} "
                f"configuration failed: "
                f"{operation.get('status')}"
            )
            print(response_preview)

            payload_file = (
                save_nvr_camera_management_backup(
                    nvr_ip,
                    (
                        f"channel_{channel_number}_"
                        "failed_payload"
                    ),
                    operation.get("payload", ""),
                )
            )

            add_result(
                results,
                nvr_ip,
                (
                    f"Configure NVR Camera Channel "
                    f"{channel_number}"
                ),
                operation.get("endpoint", ""),
                operation.get("status", ""),
                "FAILED",
                (
                    f"Camera IP={camera_ip}; "
                    f"Response={response_preview}; "
                    f"Payload saved={payload_file}"
                ),
            )

    # ================================================================
    # Delete configured channels beyond expected count
    # ================================================================
    configured_channel_ids = {
        str(channel.get("id"))
        for channel in configured_before
        if not is_blank(channel.get("ip_address"))
    }

    extra_channel_ids = sorted(
        [
            channel_id
            for channel_id in configured_channel_ids
            if (
                str(channel_id).isdigit()
                and int(channel_id) > expected_count
            )
        ],
        key=channel_id_sort_key,
    )

    if (
        DELETE_EXTRA_NVR_CAMERA_CHANNELS
        and extra_channel_ids
        and not discovery_before.get("discovery_degraded")
    ):
        print(
            "[NVR CAMERA MGMT] Extra configured channels "
            f"to delete: {', '.join(extra_channel_ids)}"
        )

        for channel_id in extra_channel_ids:
            operation = delete_nvr_camera_channel(
                nvr_ip,
                nvr_username,
                nvr_password,
                channel_id,
            )

            if operation["ok"]:
                print(
                    f"[OK] Extra NVR channel {channel_id} deleted."
                )

                add_result(
                    results,
                    nvr_ip,
                    (
                        f"Delete Extra NVR Camera Channel "
                        f"{channel_id}"
                    ),
                    operation["endpoint"],
                    operation["status"],
                    "OK",
                    (
                        f"Expected camera count={expected_count}; "
                        f"removed channel={channel_id}"
                    ),
                )
            else:
                response_preview = str(
                    operation.get("response", "")
                )[:500]

                failed_operations.append(
                    f"Delete channel {channel_id}: "
                    f"status={operation.get('status')}"
                )

                print(
                    f"[FAILED] Unable to delete extra "
                    f"NVR channel {channel_id}: "
                    f"{operation.get('status')}"
                )
                print(response_preview)

                add_result(
                    results,
                    nvr_ip,
                    (
                        f"Delete Extra NVR Camera Channel "
                        f"{channel_id}"
                    ),
                    operation.get("endpoint", ""),
                    operation.get("status", ""),
                    "FAILED",
                    response_preview,
                )

    runtime_recovery = wait_for_nvr_input_proxy_runtime_ready(
        nvr_ip,
        nvr_username,
        nvr_password,
        camera_rows,
        service_username,
        service_password,
        results,
    )

    if not runtime_recovery.get("ok"):
        print(
            f"[WARNING] NVR Camera Management runtime did not become ready "
            f"for {nvr_ip}: {runtime_recovery.get('detail', '')}"
        )

    validation = validate_nvr_camera_management(
        nvr_ip,
        nvr_username,
        nvr_password,
        expected_camera_ips,
    )

    # v123: reconcile initial channel-write failures only after BOTH the
    # bounded recovery and final static read-back prove that channel healthy.
    # Deletion failures and unresolved channel failures are retained.
    final_channel_by_id = {
        str(channel.get("id", "")).strip(): channel
        for channel in validation.get("discovery", {}).get(
            "configured_channels",
            [],
        )
        if str(channel.get("id", "")).strip()
    }

    recovery_ready_ids = set(
        str(value)
        for value in runtime_recovery.get("ready_ids", [])
    )

    resolved_channel_ids = set()

    if runtime_recovery.get("ok"):
        for channel_id in recovery_ready_ids:
            try:
                row_index = int(channel_id) - 1
                camera_row = camera_rows[row_index]
            except Exception:
                continue

            final_channel = final_channel_by_id.get(channel_id)
            camera_ip = get_value(camera_row, "Current IP")

            # If the collection response omitted security flags, verify them
            # through the per-channel detail endpoint before clearing failure.
            if final_channel and (
                is_blank(final_channel.get("certificate_validation_enabled"))
                or is_blank(final_channel.get("default_admin_port_enabled"))
            ):
                detail_probe = get_nvr_channel_detail(
                    nvr_ip,
                    nvr_username,
                    nvr_password,
                    channel_id,
                )
                if detail_probe.get("channel"):
                    final_channel = detail_probe.get("channel")

            if nvr_input_proxy_static_matches_expected(
                final_channel,
                camera_ip,
                service_username,
            ):
                resolved_channel_ids.add(channel_id)

    if resolved_channel_ids:
        remaining_failures = []

        for failure in failed_operations:
            match = re.match(r"^Channel\s+(\d+):", str(failure))
            if match and match.group(1) in resolved_channel_ids:
                channel_id = match.group(1)
                print(
                    f"[RECOVERED] NVR Camera Management channel {channel_id}: "
                    "initial configuration failure was cleared by verified "
                    "runtime recovery + final static read-back."
                )

                # Reconcile the report row as well so the final summary does
                # not retain a FAILED task that was proven resolved later.
                task_name = f"Configure NVR Camera Channel {channel_id}"
                for result_record in results:
                    if (
                        str(result_record.get("IP", "")).strip()
                        == str(nvr_ip).strip()
                        and str(result_record.get("Task", "")).strip()
                        == task_name
                        and normalize_result_value(
                            result_record.get("Result")
                        ) in {"FAILED", "ERROR"}
                    ):
                        original_detail = str(
                            result_record.get("Detail", "") or ""
                        )
                        result_record["Result"] = "OK"
                        result_record["Detail"] = (
                            "RECOVERED: initial channel configuration failed, "
                            "but bounded recovery succeeded and final static + "
                            "runtime verification passed. Original detail: "
                            + original_detail
                        )[:1000]
                continue

            remaining_failures.append(failure)

        failed_operations = remaining_failures

    # Recompute the final static success count instead of preserving a stale
    # pre-recovery count.
    final_configured_success_count = 0
    for channel_number, camera_row in enumerate(camera_rows, start=1):
        channel_id = str(channel_number)
        final_channel = final_channel_by_id.get(channel_id)
        camera_ip = get_value(camera_row, "Current IP")

        if final_channel and (
            is_blank(final_channel.get("certificate_validation_enabled"))
            or is_blank(final_channel.get("default_admin_port_enabled"))
        ):
            detail_probe = get_nvr_channel_detail(
                nvr_ip,
                nvr_username,
                nvr_password,
                channel_id,
            )
            if detail_probe.get("channel"):
                final_channel = detail_probe.get("channel")

        if nvr_input_proxy_static_matches_expected(
            final_channel,
            camera_ip,
            service_username,
        ):
            final_configured_success_count += 1

    # MUST-FIX #1: recovery is part of the final PASS 5 truth. A checked
    # runtime status that remained inconclusive/failed after the bounded
    # recovery window can no longer be overwritten by a weaker validation OK.
    final_camera_management_ok = (
        validation["ok"]
        and bool(runtime_recovery.get("ok"))
        and not failed_operations
    )

    if final_camera_management_ok:
        print(
            f"[OK] NVR Camera Management fully synchronised "
            f"for Site {site}."
        )
        print(
            f"[OK] Final configured camera count: "
            f"{expected_count}"
        )

        add_result(
            results,
            nvr_ip,
            "Validate NVR Camera Management",
            "/ISAPI/ContentMgmt/InputProxy/channels",
            200,
            "OK",
            (
                f"Site={site}; "
                f"Expected={expected_count}; "
                f"Configured={final_configured_success_count}; "
                "No extra channels; "
                f"Runtime={validation.get('runtime_status', {}).get('detail', '')}; "
                f"RecoveryOK={runtime_recovery.get('ok')}; "
                f"Recovery={runtime_recovery.get('detail', '')}"
            ),
        )
    else:
        detail = (
            f"Configured success={final_configured_success_count}/"
            f"{expected_count}; "
            f"Mismatches={validation['missing_or_mismatched']}; "
            f"Extras={validation['extra_channels']}; "
            f"Runtime status issues="
            f"{validation.get('runtime_status', {}).get('issues', [])}; "
            f"Operation failures={failed_operations}; "
            f"RecoveryOK={runtime_recovery.get('ok')}; "
            f"Recovery={runtime_recovery.get('detail', '')}"
        )

        print(
            f"[WARNING] NVR Camera Management validation "
            f"did not fully pass for {nvr_ip}."
        )
        print(detail)

        add_result(
            results,
            nvr_ip,
            "Validate NVR Camera Management",
            "/ISAPI/ContentMgmt/InputProxy/channels",
            "",
            "WARNING",
            detail[:1000],
        )


# =============================================================================
# NVR CAMERA STREAM / RESOLUTION CONFIGURATION
# =============================================================================

def save_nvr_camera_stream_backup(
    nvr_ip,
    name,
    content,
):
    timestamp = datetime.now().strftime(
        "%Y%m%d_%H%M%S"
    )

    device_dir = (
        NVR_CAMERA_STREAM_BACKUP_DIR
        / safe_filename(nvr_ip)
    )
    device_dir.mkdir(
        parents=True,
        exist_ok=True,
    )

    file_path = (
        device_dir
        / (
            f"{safe_filename(nvr_ip)}_"
            f"{safe_filename(name)}_"
            f"{timestamp}.xml"
        )
    )

    file_path.write_text(
        content or "",
        encoding="utf-8",
        errors="ignore",
    )

    return file_path


def xml_tag_namespace(tag):
    tag = str(tag or "")

    if tag.startswith("{") and "}" in tag:
        return tag[1:].split("}", 1)[0]

    return ""


def direct_child_by_local_name(parent, local_name):
    wanted = str(local_name).strip().lower()

    for child in list(parent):
        if xml_local_name(child.tag).lower() == wanted:
            return child

    return None


def ensure_direct_xml_child(parent, local_name):
    child = direct_child_by_local_name(
        parent,
        local_name,
    )

    if child is not None:
        return child

    namespace = xml_tag_namespace(parent.tag)

    if namespace:
        tag = f"{{{namespace}}}{local_name}"
    else:
        tag = local_name

    return ET.SubElement(parent, tag)


def set_direct_xml_text(parent, local_name, value):
    child = ensure_direct_xml_child(
        parent,
        local_name,
    )
    child.text = str(value)
    return child


def normalize_nvr_bitrate_type(value):
    value = str(value or "").strip().lower()

    if value in {
        "constant",
        "constant bitrate",
        "cbr",
    }:
        return "cbr"

    if value in {
        "variable",
        "variable bitrate",
        "vbr",
    }:
        return "vbr"

    raise ValueError(
        f"Unsupported Bitrate Type: {value}"
    )


def normalize_h265_plus(value):
    value = str(value or "").strip().lower()

    if value in {
        "on",
        "yes",
        "true",
        "1",
        "enabled",
        "enable",
    }:
        return True

    if value in {
        "off",
        "no",
        "false",
        "0",
        "disabled",
        "disable",
        "",
    }:
        return False

    raise ValueError(
        f"Unsupported H.265+ value: {value}"
    )


def normalized_nvr_stream_profile(profile):
    if not profile:
        raise ValueError(
            "NVR camera stream profile is missing"
        )

    bitrate_type = normalize_nvr_bitrate_type(
        get_value(profile, "Bitrate Type")
    )

    # The user's captured DevTools payload confirms the CBR tag
    # <constantBitRate>. The VBR max-bitrate/quality tags were not captured,
    # so do not guess them and risk applying the wrong settings.
    if bitrate_type != "cbr":
        raise ValueError(
            "Bitrate Type Variable/VBR is not yet supported by the "
            "captured ISAPI payload. Keep Constant/CBR or capture the "
            "DevTools PUT payload after changing to VBR."
        )

    suffix = normalize_stream_channel_suffix(
        get_value(
            profile,
            "Stream Channel Suffix",
        )
    )

    frame_rate = excel_float(
        get_value(profile, "Frame Rate (fps)"),
        "Frame Rate (fps)",
        minimum=0.01,
    )

    api_frame_rate = int(round(
        frame_rate
        * NVR_STREAM_FRAME_RATE_MULTIPLIER
    ))

    smart_codec_enabled = normalize_h265_plus(
        get_value(profile, "H.265+")
    )

    requested_include_smart_codec = yes_no(
        get_value(profile, "Include Smart Codec"),
        default=(suffix == "01"),
    )

    # The successful DS-E08NI-Q2 browser PUT explicitly includes:
    #
    #   <SmartCodec><enabled>false</enabled></SmartCodec>
    #
    # while H.265+ is OFF. Therefore inclusion of the SmartCodec element is
    # independent of whether H.265+ is currently enabled. The Excel
    # "Include Smart Codec" switch remains authoritative.
    include_smart_codec = requested_include_smart_codec

    settings = {
        "profile_name": get_value(
            profile,
            "Profile Name",
        ) or DEFAULT_NVR_CAMERA_STREAM_PROFILE,
        "enabled": yes_no(
            get_value(profile, "Enabled"),
            default=True,
        ),
        "stream_type": get_value(
            profile,
            "Stream Type",
        ),
        "stream_suffix": suffix,
        "video_type": get_value(
            profile,
            "Video Type",
        ),
        "resolution_width": excel_int(
            get_value(profile, "Resolution Width"),
            "Resolution Width",
            minimum=1,
        ),
        "resolution_height": excel_int(
            get_value(profile, "Resolution Height"),
            "Resolution Height",
            minimum=1,
        ),
        "bitrate_type": bitrate_type,
        "video_quality": get_value(
            profile,
            "Video Quality",
        ),
        "frame_rate": frame_rate,
        "api_frame_rate": api_frame_rate,
        "max_bitrate": excel_int(
            get_value(profile, "Max Bitrate (Kbps)"),
            "Max Bitrate (Kbps)",
            minimum=1,
        ),
        "video_encoding": get_value(
            profile,
            "Video Encoding",
        ),
        "video_scan_type": get_value(
            profile,
            "Video Scan Type",
        ),
        "smart_codec_enabled": smart_codec_enabled,
        "include_smart_codec": include_smart_codec,
        "i_frame_interval": excel_int(
            get_value(profile, "I Frame Interval"),
            "I Frame Interval",
            minimum=1,
        ),
        "streaming_transport": get_value(
            profile,
            "Streaming Transport",
        ) or "RTSP",
        "video_enabled": yes_no(
            get_value(profile, "Video Enabled"),
            default=True,
        ),
    }

    if is_blank(settings["video_encoding"]):
        raise ValueError(
            "Video Encoding is blank in Excel"
        )

    return settings


def nvr_stream_input_channel_number(stream_channel_id):
    """
    Convert Hikvision StreamingProxy IDs to their physical camera/input number.

    Examples:
        101 -> 1
        201 -> 2
        301 -> 3
        401 -> 4

    dynVideoInputChannelID is a channel-binding value managed per NVR input.
    Audio is not configured by this automation.
    """
    try:
        stream_id = int(str(stream_channel_id).strip())
    except Exception as error:
        raise ValueError(
            f"Invalid StreamingProxy channel ID: {stream_channel_id}"
        ) from error

    input_channel = stream_id // 100

    if input_channel < 1:
        raise ValueError(
            f"Cannot derive NVR input channel from stream ID "
            f"{stream_channel_id}"
        )

    return input_channel



def is_nvr_stream_get_not_supported(status, response_text):
    """
    The NVR firmware can support PUT on:
        /ISAPI/ContentMgmt/StreamingProxy/channels/<id>
    while rejecting GET on the same endpoint with:

        HTTP 403
        statusString=Invalid Operation
        subStatusCode=notSupport

    Treat that specific response as a firmware limitation, not as a failed
    camera/channel configuration.
    """
    response_lower = str(response_text or "").lower()

    return (
        int(status or 0) in {403, 405}
        and (
            "notsupport" in response_lower
            or "invalid operation" in response_lower
        )
    )


def extract_nvr_stream_channel_from_collection(
    collection_xml,
    stream_channel_id,
):
    """
    Try to extract one <StreamingChannel> entry from a collection response.

    Some NVR firmware rejects GET /channels/<id> but still allows
    GET /channels. If so, we can preserve the current channel structure
    (including any firmware-managed fields) without depending on the
    unsupported per-channel GET.
    """
    if is_blank(collection_xml):
        return ""

    try:
        root = ET.fromstring(collection_xml)
    except Exception:
        return ""

    wanted = str(stream_channel_id).strip()

    for element in root.iter():
        if xml_local_name(element.tag) != "StreamingChannel":
            continue

        channel_id = xml_find_first_text(
            element,
            ["id"],
        )

        if str(channel_id).strip() == wanted:
            try:
                return ET.tostring(
                    element,
                    encoding="unicode",
                )
            except Exception:
                return ""

    return ""



def update_nvr_streaming_channel_xml_preserve_schema(
    current_xml,
    stream_channel_id,
    settings,
):
    """
    Preserve the exact XML structure returned by THIS NVR and mutate only
    values already present in its Video block.

    This is specifically for DS-E08NI-Q2 main-stream cases where the previous
    generic/captured XML template was rejected with HTTP 400 badXmlContent.
    """
    if is_blank(current_xml):
        raise ValueError(
            "Current NVR StreamingChannel XML is blank."
        )

    root = ET.fromstring(
        current_xml
    )

    if xml_local_name(root.tag) != "StreamingChannel":
        raise ValueError(
            "Unexpected StreamingProxy response root: "
            f"{xml_local_name(root.tag)}"
        )

    xml_text = str(
        current_xml
    )

    video_match = re.search(
        r"<(?:[A-Za-z_][\w.\-]*:)?Video\b[^>]*>"
        r".*?"
        r"</(?:[A-Za-z_][\w.\-]*:)?Video>",
        xml_text,
        flags=re.IGNORECASE | re.DOTALL,
    )

    if not video_match:
        raise ValueError(
            "Existing NVR StreamingChannel XML contains no Video block."
        )

    updated_video = video_match.group(0)

    def replace_existing_tag(
        block,
        tag_name,
        new_value,
        *,
        required=True,
    ):
        pattern = re.compile(
            rf"(<(?:[A-Za-z_][\w.\-]*:)?{re.escape(tag_name)}"
            rf"\b[^>]*>)(.*?)(</(?:[A-Za-z_][\w.\-]*:)?"
            rf"{re.escape(tag_name)}>)",
            flags=re.IGNORECASE | re.DOTALL,
        )

        if not pattern.search(
            block
        ):
            if required:
                raise ValueError(
                    f"Existing NVR Video block has no <{tag_name}>."
                )

            return block

        return pattern.sub(
            lambda m: (
                m.group(1)
                + xml_escape(
                    str(
                        new_value
                    )
                )
                + m.group(3)
            ),
            block,
            count=1,
        )

    def remove_existing_tag(block, tag_name):
        pattern = re.compile(
            rf"<(?:[A-Za-z_][\w.\-]*:)?{re.escape(tag_name)}\b[^>]*>"
            rf".*?"
            rf"</(?:[A-Za-z_][\w.\-]*:)?{re.escape(tag_name)}>",
            flags=re.IGNORECASE | re.DOTALL,
        )
        return pattern.sub("", block)

    def set_or_insert_tag(
        block,
        tag_name,
        new_value,
        *,
        insert_before=(),
    ):
        pattern = re.compile(
            rf"(<(?:[A-Za-z_][\w.\-]*:)?{re.escape(tag_name)}"
            rf"\b[^>]*>)(.*?)(</(?:[A-Za-z_][\w.\-]*:)?"
            rf"{re.escape(tag_name)}>)",
            flags=re.IGNORECASE | re.DOTALL,
        )

        if pattern.search(block):
            return pattern.sub(
                lambda m: (
                    m.group(1)
                    + xml_escape(str(new_value))
                    + m.group(3)
                ),
                block,
                count=1,
            )

        # Preserve the current Video namespace style.  An unprefixed child
        # inherits the Video/default namespace when present; inside
        # <Video xmlns=""> it correctly remains no-namespace, matching the
        # successful browser payloads.
        new_tag = (
            f"<{tag_name}>"
            f"{xml_escape(str(new_value))}"
            f"</{tag_name}>"
        )

        for before_tag in insert_before:
            before_pattern = re.compile(
                rf"<(?:[A-Za-z_][\w.\-]*:)?{re.escape(before_tag)}\b",
                flags=re.IGNORECASE,
            )
            match = before_pattern.search(block)
            if match:
                return block[:match.start()] + new_tag + block[match.start():]

        closing = re.search(
            r"</(?:[A-Za-z_][\w.\-]*:)?Video>\s*$",
            block,
            flags=re.IGNORECASE | re.DOTALL,
        )
        if not closing:
            raise ValueError(
                f"Existing NVR Video block cannot accept inserted <{tag_name}>."
            )

        return block[:closing.start()] + new_tag + block[closing.start():]

    updated_video = replace_existing_tag(
        updated_video,
        "enabled",
        (
            "true"
            if settings["video_enabled"]
            else "false"
        ),
    )

    updated_video = replace_existing_tag(
        updated_video,
        "dynVideoInputChannelID",
        nvr_stream_input_channel_number(
            stream_channel_id
        ),
    )

    updated_video = replace_existing_tag(
        updated_video,
        "videoCodecType",
        settings["video_encoding"],
    )

    updated_video = replace_existing_tag(
        updated_video,
        "videoResolutionWidth",
        settings["resolution_width"],
    )

    updated_video = replace_existing_tag(
        updated_video,
        "videoResolutionHeight",
        settings["resolution_height"],
    )

    updated_video = replace_existing_tag(
        updated_video,
        "videoQualityControlType",
        settings["bitrate_type"],
    )

    target_bitrate_type = str(
        settings["bitrate_type"]
    ).strip().lower()

    if target_bitrate_type == "cbr":
        # A newly-bound/placeholder proxy can still be VBR and therefore have
        # no <constantBitRate>.  This was the exact .210 stream-201 failure.
        # Convert it to the browser-proven CBR schema instead of aborting.
        updated_video = remove_existing_tag(
            updated_video,
            "vbrUpperCap",
        )
        updated_video = remove_existing_tag(
            updated_video,
            "vbrLowerCap",
        )

        # v121: Hikvision GET responses can contain readback-only/generated
        # fields such as <fixedQuality> and <snapShotImageType>.  The user's
        # successful F12 PUT for D2/201 omitted both fields.  Sending them back
        # while converting a placeholder VBR profile to CBR can make the NVR
        # reject otherwise valid XML with statusCode=6/badXmlContent
        # ("Tag xx is invalid (two root tags)").  Strip them from the PUT.
        updated_video = remove_existing_tag(
            updated_video,
            "fixedQuality",
        )
        updated_video = remove_existing_tag(
            updated_video,
            "snapShotImageType",
        )

        updated_video = set_or_insert_tag(
            updated_video,
            "constantBitRate",
            settings["max_bitrate"],
            insert_before=(
                "fixedQuality",
                "maxFrameRate",
                "GovLength",
                "SmartCodec",
            ),
        )
    else:
        # Future VBR profiles: use the VBR upper cap as the configured maximum
        # bitrate and remove a stale CBR-only value.
        updated_video = remove_existing_tag(
            updated_video,
            "constantBitRate",
        )
        updated_video = set_or_insert_tag(
            updated_video,
            "vbrUpperCap",
            settings["max_bitrate"],
            insert_before=(
                "vbrLowerCap",
                "fixedQuality",
                "maxFrameRate",
                "GovLength",
                "SmartCodec",
            ),
        )

    # Excel 25 fps = Hikvision raw 2500.
    updated_video = replace_existing_tag(
        updated_video,
        "maxFrameRate",
        settings["api_frame_rate"],
    )

    updated_video = replace_existing_tag(
        updated_video,
        "GovLength",
        settings["i_frame_interval"],
    )

    if not is_blank(
        settings.get(
            "video_scan_type"
        )
    ):
        updated_video = replace_existing_tag(
            updated_video,
            "videoScanType",
            settings["video_scan_type"],
            required=False,
        )

    # SmartCodec/H.265+ only if this NVR firmware already includes the block.
    smart_match = re.search(
        r"<(?:[A-Za-z_][\w.\-]*:)?SmartCodec\b[^>]*>"
        r".*?"
        r"</(?:[A-Za-z_][\w.\-]*:)?SmartCodec>",
        updated_video,
        flags=re.IGNORECASE | re.DOTALL,
    )

    if smart_match:
        smart_block = smart_match.group(0)

        smart_block = replace_existing_tag(
            smart_block,
            "enabled",
            (
                "true"
                if settings["smart_codec_enabled"]
                else "false"
            ),
            required=False,
        )

        updated_video = (
            updated_video[:smart_match.start()]
            + smart_block
            + updated_video[smart_match.end():]
        )

    payload = (
        xml_text[:video_match.start()]
        + updated_video
        + xml_text[video_match.end():]
    )

    payload = payload.lstrip(
        "\ufeff"
    )

    # Must remain exactly one valid XML document.
    ET.fromstring(
        payload
    )

    actual = read_nvr_streaming_channel_values(
        payload
    )

    required_values = {
        "video_encoding": str(
            settings["video_encoding"]
        ),
        "resolution_width": str(
            settings["resolution_width"]
        ),
        "resolution_height": str(
            settings["resolution_height"]
        ),
        "bitrate_type": str(
            settings["bitrate_type"]
        ),
        "max_bitrate": str(
            settings["max_bitrate"]
        ),
        "api_frame_rate": str(
            settings["api_frame_rate"]
        ),
        "i_frame_interval": str(
            settings["i_frame_interval"]
        ),
    }

    mismatches = []

    for key, expected_value in required_values.items():
        actual_value = str(
            actual.get(
                key,
                "",
            )
        ).strip()

        if key in {
            "video_encoding",
            "bitrate_type",
        }:
            same = (
                actual_value.lower()
                == expected_value.lower()
            )
        else:
            same = (
                actual_value
                == expected_value
            )

        if not same:
            mismatches.append({
                "field": key,
                "expected": expected_value,
                "actual": actual_value,
            })

    if mismatches:
        raise ValueError(
            "Preserve-schema payload failed self-validation: "
            f"{mismatches}"
        )

    return payload


def verify_nvr_proxy_stream_exact_values(
    nvr_ip,
    nvr_username,
    nvr_password,
    stream_channel_id,
    settings,
    nvr_stream_web_session=None,
):
    """
    Verify the NVR StreamingProxy itself.

    This is the authoritative check for what the NVR Video/Audio page should
    show. It is separate from the physical-camera check.
    """
    endpoint = (
        f"{NVR_STREAMING_PROXY_ENDPOINT_BASE}/"
        f"{stream_channel_id}"
    )

    status, xml_text = get_nvr_streaming_proxy(
        nvr_stream_web_session,
        nvr_ip,
        nvr_username,
        nvr_password,
        endpoint,
    )

    if status != 200:
        return {
            "ok": False,
            "status": status,
            "endpoint": endpoint,
            "actual": {},
            "mismatches": [{
                "field": "NVR proxy GET",
                "expected": "HTTP 200",
                "actual": str(
                    status
                ),
            }],
        }

    actual = read_nvr_streaming_channel_values(
        xml_text
    )

    mismatches = validate_nvr_streaming_channel_values(
        actual,
        stream_channel_id,
        settings,
        expected_dynamic_video_input_channel_id=None,
    )

    print(
        f"[NVR PROXY AUDIT] Stream {stream_channel_id}: "
        f"Resolution="
        f"{actual.get('resolution_width','?')}x"
        f"{actual.get('resolution_height','?')}; "
        f"FrameRateRaw="
        f"{actual.get('api_frame_rate','?')} "
        f"(ExcelTargetRaw={settings['api_frame_rate']}); "
        f"Bitrate="
        f"{actual.get('max_bitrate','?')} Kbps; "
        f"Codec="
        f"{actual.get('video_encoding','?')}; "
        f"Mismatches={mismatches}"
    )

    return {
        "ok": not mismatches,
        "status": status,
        "endpoint": endpoint,
        "actual": actual,
        "mismatches": mismatches,
    }



def should_use_captured_nvr_main_stream_payload(
    current_xml,
    stream_channel_id,
    settings,
):
    """
    Return True when a readable main-stream proxy is only a placeholder /
    bootstrap profile and should be replaced with the browser-proven minimal
    PUT payload instead of echoing the GET schema back to the NVR.

    Field evidence from the affected DS-E08NI-Q2:
      - D2/201 GET could return 0x0, VBR and maxFrameRate=0;
      - the same channel accepted the user's captured browser PUT with
        1920x1080, cbr, constantBitRate=2048 and maxFrameRate=2500;
      - echoing generated GET-only tags back during VBR->CBR conversion can
        trigger HTTP 400 / statusCode=6 / badXmlContent.

    The fallback remains limited to MAIN streams. Sub-stream handling is left
    unchanged because it already uses its own proven builder.
    """
    try:
        stream_id = int(str(stream_channel_id).strip())
    except Exception:
        return False

    if (stream_id % 100) != 1:
        return False

    actual = read_nvr_streaming_channel_values(
        current_xml
    )

    width = str(actual.get("resolution_width", "") or "").strip()
    height = str(actual.get("resolution_height", "") or "").strip()
    frame = str(actual.get("api_frame_rate", "") or "").strip()
    bitrate_type = str(actual.get("bitrate_type", "") or "").strip().lower()

    target_bitrate_type = str(
        settings.get("bitrate_type", "") or ""
    ).strip().lower()

    zero_or_blank_geometry = (
        width in {"", "0"}
        or height in {"", "0"}
        or frame in {"", "0"}
    )

    vbr_to_cbr_placeholder = (
        target_bitrate_type == "cbr"
        and bitrate_type == "vbr"
    )

    return bool(
        zero_or_blank_geometry
        or vbr_to_cbr_placeholder
    )


def build_captured_nvr_main_stream_xml(
    stream_channel_id,
    settings,
):
    """
    Build the DS-E08NI-Q2 MAIN-stream XML from the latest successful browser
    captures.

    v112 corrections from the affected NVR example NVR address:
        D1 main 101 -> channelName=101, id=101, dynVideoInputChannelID=1
        D2 main 201 -> channelName=201, id=201, dynVideoInputChannelID=2

    Therefore channelName and dynVideoInputChannelID are NOT constants across
    physical NVR inputs. They are derived from the actual StreamingProxy ID.

    The D1 browser payload exposes an Audio block; the D2 browser payload does
    not. The last-resort template includes the captured disabled Audio block
    only for D1 and leaves D2+ audio untouched/omitted.
    """
    stream_channel_id = str(stream_channel_id).strip()
    input_channel = nvr_stream_input_channel_number(
        stream_channel_id
    )

    video_enabled = (
        "true"
        if settings["video_enabled"]
        else "false"
    )

    smart_codec_enabled = (
        "true"
        if settings["smart_codec_enabled"]
        else "false"
    )

    video_scan_type_xml = ""

    if not is_blank(settings.get("video_scan_type")):
        video_scan_type_xml = (
            "<videoScanType>"
            f"{xml_escape(str(settings['video_scan_type']))}"
            "</videoScanType>"
        )

    smart_codec_xml = (
        "<SmartCodec>"
        f"<enabled>{smart_codec_enabled}</enabled>"
        "</SmartCodec>"
    )

    audio_xml = ""
    if input_channel == 1:
        audio_xml = (
            "<Audio>"
            f"<enabled>{NVR_CAPTURED_MAIN_STREAM_AUDIO_ENABLED}</enabled>"
            f"<audioInputChannelID>{input_channel}</audioInputChannelID>"
            f"<audioCompressionType>{xml_escape(NVR_CAPTURED_MAIN_STREAM_AUDIO_CODEC)}</audioCompressionType>"
            "</Audio>"
        )

    return (
        '<?xml version="1.0" encoding="UTF-8"?>'
        '<StreamingChannel xmlns="http://www.isapi.org/ver20/XMLSchema" '
        'version="2.0">'
        f'<channelName>{xml_escape(stream_channel_id)}</channelName>'
        '<enabled>true</enabled>'
        '<Transport>'
        '<ControlProtocolList>'
        '<ControlProtocol>'
        f'<streamingTransport>{xml_escape(str(settings["streaming_transport"]))}</streamingTransport>'
        '</ControlProtocol>'
        '</ControlProtocolList>'
        '</Transport>'
        f'{audio_xml}'
        f'<id xmlns="">{xml_escape(stream_channel_id)}</id>'
        '<Video xmlns="">'
        f'<enabled>{video_enabled}</enabled>'
        f'<dynVideoInputChannelID>{input_channel}</dynVideoInputChannelID>'
        f'<videoCodecType>{xml_escape(str(settings["video_encoding"]))}</videoCodecType>'
        f'<videoResolutionWidth>{xml_escape(str(settings["resolution_width"]))}</videoResolutionWidth>'
        f'{video_scan_type_xml}'
        f'<videoResolutionHeight>{xml_escape(str(settings["resolution_height"]))}</videoResolutionHeight>'
        f'<videoQualityControlType>{xml_escape(str(settings["bitrate_type"]))}</videoQualityControlType>'
        f'<constantBitRate>{xml_escape(str(settings["max_bitrate"]))}</constantBitRate>'
        f'<maxFrameRate>{xml_escape(str(settings["api_frame_rate"]))}</maxFrameRate>'
        f'{smart_codec_xml}'
        f'<GovLength>{xml_escape(str(settings["i_frame_interval"]))}</GovLength>'
        '</Video>'
        '</StreamingChannel>'
    )

def create_nvr_stream_web_session(
    ip,
    username,
    password,
):
    """
    Create one Hikvision SessionLogin-v4 session for NVR StreamingProxy.

    Cookie/session values are held only in memory and are never printed.
    """
    session = HikvisionSession(
        ip,
        username,
        password,
    )

    login_info = session.login()
    # Preserve the model returned by the already-authenticated deviceInfo GET.
    session.device_model = str(login_info.get("model", "") or "").strip()
    session.device_firmware = str(login_info.get("firmware", "") or "").strip()

    cookie_names = sorted(
        {
            cookie.name
            for cookie in session.session.cookies
            if cookie.name
        }
    )

    print(
        f"[NVR STREAM SESSION] {ip} SessionLogin-v4 authenticated. "
        f"Cookie names={cookie_names or ['<none>']}; "
        f"SessionTag={'yes' if session.session_tag else 'no'}."
    )

    return session


def get_nvr_streaming_proxy_via_web_session(
    nvr_session,
    endpoint,
):
    """
    GET StreamingProxy through the same SessionLogin/WebSession path used by
    the Hikvision browser.

    v112: the captured browser requests prove that GET 101/102/201/202 uses
    WebSession cookies + X-Requested-With. Some DS-E08NI-Q2 units returned
    HTTP 403/notSupport to the generic Digest GET while the browser/WebSession
    GET worked immediately. Use the browser-authenticated session for both
    readback and PUT whenever available.
    """
    if nvr_session is None:
        raise RuntimeError(
            "NVR StreamingProxy WebSession is not initialized."
        )

    headers = {
        "Accept": "*/*",
        "Accept-Language": "en-US,en;q=0.9",
        "Cache-Control": "max-age=0",
        "Connection": "keep-alive",
        "If-Modified-Since": "0",
        "Referer": f"https://{nvr_session.ip}/doc/page/config.asp",
        "X-Requested-With": "XMLHttpRequest",
    }

    if nvr_session.session_tag:
        headers["SessionTag"] = nvr_session.session_tag

    response = nvr_session.session.request(
        "GET",
        f"https://{nvr_session.ip}{endpoint}",
        headers=headers,
        timeout=(
            CONNECT_TIMEOUT,
            READ_TIMEOUT_NORMAL,
        ),
        verify=False,
    )

    return response.status_code, response.text


def get_nvr_streaming_proxy(
    nvr_stream_web_session,
    nvr_ip,
    nvr_username,
    nvr_password,
    endpoint,
):
    """Use WebSession GET when available; otherwise retain Digest fallback."""
    if nvr_stream_web_session is not None:
        try:
            return get_nvr_streaming_proxy_via_web_session(
                nvr_stream_web_session,
                endpoint,
            )
        except Exception as error:
            print(
                f"[NVR STREAM SESSION WARNING] WebSession GET {endpoint} "
                f"failed: {error}. Falling back to generic ISAPI GET."
            )

    return get_xml(
        nvr_ip,
        nvr_username,
        nvr_password,
        endpoint,
    )


def put_nvr_streaming_proxy_via_web_session(
    nvr_session,
    endpoint,
    xml_text,
):
    """
    Send raw StreamingProxy XML through the Hikvision SessionLogin WebSession,
    matching the successful NVR browser request headers/authentication path.
    """
    if nvr_session is None:
        raise RuntimeError(
            "NVR StreamingProxy WebSession is not initialized."
        )

    headers = {
        "Accept": "*/*",
        "Accept-Language": "en-US,en;q=0.9",
        "Cache-Control": "max-age=0",
        "Connection": "keep-alive",
        "Content-Type": NVR_STREAM_BROWSER_CONTENT_TYPE,
        "If-Modified-Since": "0",
        "Origin": f"https://{nvr_session.ip}",
        "Referer": f"https://{nvr_session.ip}/doc/page/config.asp",
        "X-Requested-With": "XMLHttpRequest",
    }

    if nvr_session.session_tag:
        headers["SessionTag"] = nvr_session.session_tag

    response = nvr_session.session.request(
        "PUT",
        f"https://{nvr_session.ip}{endpoint}",
        data=(
            xml_text.encode("utf-8")
            if isinstance(xml_text, str)
            else xml_text
        ),
        headers=headers,
        timeout=(
            CONNECT_TIMEOUT,
            READ_TIMEOUT_NORMAL,
        ),
        verify=False,
    )

    return response.status_code, response.text


def nvr_stream_browser_fetch(driver, endpoint, method="GET", body=None):
    """Execute one same-origin StreamingProxy request inside the real Edge page."""
    result = driver.execute_async_script(
        r"""
        const endpoint = arguments[0];
        const method = String(arguments[1] || 'GET').toUpperCase();
        const body = arguments[2];
        const done = arguments[arguments.length - 1];

        const headers = {
            'Accept': '*/*',
            'Accept-Language': 'en-US,en;q=0.9',
            'Cache-Control': 'max-age=0',
            'If-Modified-Since': '0',
            'X-Requested-With': 'XMLHttpRequest'
        };

        if (method !== 'GET' && method !== 'HEAD') {
            headers['Content-Type'] = 'application/x-www-form-urlencoded; charset=UTF-8';
        }

        fetch(endpoint, {
            method: method,
            headers: headers,
            credentials: 'same-origin',
            cache: 'no-store',
            body: (method === 'GET' || method === 'HEAD') ? undefined : body,
            referrer: window.location.href,
            referrerPolicy: 'strict-origin-when-cross-origin'
        })
        .then(async (response) => {
            let text = '';
            try { text = await response.text(); } catch (error) {}
            done({
                ok: Boolean(response.ok),
                status: Number(response.status || 0),
                text: text,
                url: String(response.url || endpoint)
            });
        })
        .catch((error) => {
            done({
                ok: false,
                status: 0,
                text: String(error && error.message ? error.message : error),
                url: endpoint
            });
        });
        """,
        str(endpoint),
        str(method),
        body,
    )

    if not isinstance(result, dict):
        return 0, f"Unexpected browser fetch result: {result}"

    return int(result.get("status") or 0), str(result.get("text") or "")


def normalize_nvr_video_ui_text(value):
    return re.sub(
        r"\s+",
        " ",
        str(value or "")
        .replace("×", "x")
        .replace("*", "x")
        .strip()
        .lower(),
    )


def _nvr_video_visible_selects(driver):
    elements = []
    try:
        for element in driver.find_elements(By.TAG_NAME, "select"):
            try:
                if element.is_displayed() and element.is_enabled():
                    elements.append(element)
            except Exception:
                continue
    except Exception:
        pass
    return elements


def _nvr_select_option_by_predicate(
    driver,
    select_element,
    predicate,
    label,
):
    selector = Select(select_element)
    available = []
    target_text = None

    for option in selector.options:
        text_value = str(option.text or "").strip()
        value_value = str(option.get_attribute("value") or "").strip()
        available.append((text_value, value_value))
        try:
            if predicate(text_value, value_value):
                target_text = text_value
                break
        except Exception:
            continue

    if target_text is None:
        raise RuntimeError(
            f"NVR Video/Audio {label} option was not found. "
            f"Available={available}"
        )

    selector.select_by_visible_text(target_text)
    driver.execute_script(
        """
        const element = arguments[0];
        element.dispatchEvent(new Event('input', {bubbles:true}));
        element.dispatchEvent(new Event('change', {bubbles:true}));
        try { element.blur(); } catch (error) {}
        """,
        select_element,
    )

    return target_text


def _nvr_video_form_present_in_current_context(driver, channel_number):
    marker = f"[D{int(channel_number)}]".lower()

    for select_element in _nvr_video_visible_selects(driver):
        try:
            option_texts = [
                normalize_nvr_video_ui_text(option.text)
                for option in Select(select_element).options
            ]
        except Exception:
            continue

        if any(text.startswith(marker) for text in option_texts):
            return True

    return False


def switch_to_nvr_video_audio_form_context(
    driver,
    channel_number,
    max_depth=5,
):
    """
    Enter the document/frame containing the NVR Video/Audio form.

    v120 does not assume the controls live in the top document.  It identifies
    the correct form by the camera selector containing an option beginning with
    [D<channel>].  The driver remains in the matching context when returned.
    """
    driver.switch_to.default_content()

    def search(depth, path):
        if _nvr_video_form_present_in_current_context(
            driver,
            channel_number,
        ):
            return list(path)

        if depth >= max_depth:
            return None

        try:
            frames = driver.find_elements(By.CSS_SELECTOR, "iframe,frame")
        except Exception:
            frames = []

        for index in range(len(frames)):
            try:
                current_frames = driver.find_elements(
                    By.CSS_SELECTOR,
                    "iframe,frame",
                )
                if index >= len(current_frames):
                    continue
                driver.switch_to.frame(current_frames[index])
            except Exception:
                continue

            found = search(depth + 1, path + [index])
            if found is not None:
                return found

            try:
                driver.switch_to.parent_frame()
            except Exception:
                driver.switch_to.default_content()

        return None

    frame_path = search(0, [])

    if frame_path is None:
        driver.switch_to.default_content()
        raise RuntimeError(
            f"NVR Video/Audio camera selector containing [D{channel_number}] "
            "was not found in the page or nested frames."
        )

    return frame_path


def select_nvr_video_audio_target(
    driver,
    stream_channel_id,
):
    """
    Select the physical D-channel and Main/Sub stream corresponding to a
    StreamingProxy ID before API or UI configuration.

        301 -> D3 / Main Stream
        302 -> D3 / Sub Stream
        401 -> D4 / Main Stream
        402 -> D4 / Sub Stream
    """
    stream_id = int(str(stream_channel_id).strip())
    channel_number = nvr_stream_input_channel_number(stream_id)
    stream_suffix = stream_id % 100

    if stream_suffix not in {1, 2}:
        raise RuntimeError(
            f"Unsupported NVR Video/Audio stream suffix for UI fallback: "
            f"{stream_channel_id}"
        )

    frame_path = switch_to_nvr_video_audio_form_context(
        driver,
        channel_number,
    )

    camera_select = None
    camera_marker = f"[D{channel_number}]".lower()

    for select_element in _nvr_video_visible_selects(driver):
        try:
            options = Select(select_element).options
            if any(
                normalize_nvr_video_ui_text(option.text).startswith(
                    camera_marker
                )
                for option in options
            ):
                camera_select = select_element
                break
        except Exception:
            continue

    if camera_select is None:
        raise RuntimeError(
            f"Camera selector for D{channel_number} disappeared before selection."
        )

    selected_camera = _nvr_select_option_by_predicate(
        driver,
        camera_select,
        lambda text_value, value_value: (
            normalize_nvr_video_ui_text(text_value).startswith(camera_marker)
        ),
        f"Camera D{channel_number}",
    )

    time_module.sleep(NVR_STREAM_BROWSER_UI_TARGET_SETTLE_SECONDS)

    # Camera changes can replace the entire Video pane. Reacquire it before
    # selecting the stream type.
    frame_path = switch_to_nvr_video_audio_form_context(
        driver,
        channel_number,
    )

    stream_select = None
    for select_element in _nvr_video_visible_selects(driver):
        try:
            option_texts = [
                normalize_nvr_video_ui_text(option.text)
                for option in Select(select_element).options
            ]
        except Exception:
            continue

        has_main = any("main stream" in value for value in option_texts)
        has_sub = any(
            "sub stream" in value or "sub-stream" in value
            for value in option_texts
        )

        if has_main and has_sub:
            stream_select = select_element
            break

    if stream_select is None:
        raise RuntimeError(
            "NVR Video/Audio Stream Type selector was not found after "
            f"selecting D{channel_number}."
        )

    if stream_suffix == 1:
        selected_stream = _nvr_select_option_by_predicate(
            driver,
            stream_select,
            lambda text_value, value_value: (
                "main stream" in normalize_nvr_video_ui_text(text_value)
            ),
            "Main Stream",
        )
        stream_role = "main"
    else:
        selected_stream = _nvr_select_option_by_predicate(
            driver,
            stream_select,
            lambda text_value, value_value: (
                "sub stream" in normalize_nvr_video_ui_text(text_value)
                or "sub-stream" in normalize_nvr_video_ui_text(text_value)
            ),
            "Sub Stream",
        )
        stream_role = "sub"

    time_module.sleep(NVR_STREAM_BROWSER_UI_TARGET_SETTLE_SECONDS)
    switch_to_nvr_video_audio_form_context(driver, channel_number)

    return {
        "channel_number": channel_number,
        "stream_role": stream_role,
        "camera_text": selected_camera,
        "stream_text": selected_stream,
        "frame_path": frame_path,
    }


def find_nvr_video_ui_control_by_label(
    driver,
    label_options,
    selector,
):
    """Find the visible form control nearest to a visible Video/Audio label."""
    labels = [
        normalize_nvr_video_ui_text(value)
        for value in label_options
        if str(value or "").strip()
    ]

    return driver.execute_script(
        r"""
        const labels = arguments[0];
        const selector = arguments[1];

        function norm(value) {
            return String(value || "")
                .replace(/×/g, "x")
                .replace(/\*/g, "x")
                .replace(/\s+/g, " ")
                .trim()
                .toLowerCase();
        }

        function directText(element) {
            let value = "";
            for (const node of Array.from(element.childNodes || [])) {
                if (node.nodeType === Node.TEXT_NODE) {
                    value += " " + String(node.nodeValue || "");
                }
            }
            return norm(value);
        }

        function visible(element) {
            if (!element) return false;
            const style = window.getComputedStyle(element);
            const rect = element.getBoundingClientRect();
            return (
                element.isConnected &&
                style.display !== "none" &&
                style.visibility !== "hidden" &&
                Number(style.opacity || "1") !== 0 &&
                rect.width > 0 &&
                rect.height > 0
            );
        }

        const labelElements = Array.from(
            document.querySelectorAll("label,span,td,th,div,p")
        ).filter((element) => {
            if (!visible(element)) return false;
            const full = norm(element.innerText || element.textContent || "");
            const direct = directText(element);
            return labels.includes(full) || labels.includes(direct);
        });

        const controls = Array.from(
            document.querySelectorAll(selector)
        ).filter((element) => visible(element) && !element.disabled);

        let best = null;
        let bestScore = Number.POSITIVE_INFINITY;

        for (const label of labelElements) {
            const lr = label.getBoundingClientRect();
            const ly = lr.top + lr.height / 2;

            for (const control of controls) {
                const cr = control.getBoundingClientRect();
                const cy = cr.top + cr.height / 2;
                const dy = Math.abs(cy - ly);
                const dx = cr.left - lr.right;

                if (dy > 55 || dx < -60) continue;

                const score = dy * 10 + Math.max(dx, 0);
                if (score < bestScore) {
                    bestScore = score;
                    best = control;
                }
            }
        }

        return best;
        """,
        labels,
        selector,
    )


def _nvr_set_input_value(driver, element, value, label):
    if element is None:
        raise RuntimeError(f"NVR Video/Audio input '{label}' was not found.")

    driver.execute_script(
        r"""
        const element = arguments[0];
        const value = String(arguments[1]);
        const descriptor = Object.getOwnPropertyDescriptor(
            HTMLInputElement.prototype,
            "value"
        );
        if (descriptor && descriptor.set) {
            descriptor.set.call(element, value);
        } else {
            element.value = value;
        }
        element.dispatchEvent(new Event("input", {bubbles:true}));
        element.dispatchEvent(new Event("change", {bubbles:true}));
        try { element.blur(); } catch (error) {}
        """,
        element,
        str(value),
    )


def _nvr_choose_settings_select_option(
    driver,
    select_element,
    kind,
    settings,
):
    if select_element is None:
        raise RuntimeError(
            f"NVR Video/Audio select for {kind} was not found."
        )

    if kind == "resolution":
        wanted_width = str(settings["resolution_width"])
        wanted_height = str(settings["resolution_height"])

        def predicate(text_value, value_value):
            normalized = normalize_nvr_video_ui_text(text_value)
            compact = re.sub(r"[^0-9x]", "", normalized)
            return f"{wanted_width}x{wanted_height}" in compact

        label = f"Resolution {wanted_width}x{wanted_height}"

    elif kind == "bitrate_type":
        wanted = str(settings["bitrate_type"]).strip().lower()
        want_cbr = wanted in {"cbr", "constant", "constant bitrate"}

        def predicate(text_value, value_value):
            normalized = normalize_nvr_video_ui_text(text_value)
            value_normalized = normalize_nvr_video_ui_text(value_value)
            if want_cbr:
                return (
                    normalized == "constant"
                    or "constant" in normalized
                    or value_normalized == "cbr"
                )
            return (
                normalized == "variable"
                or "variable" in normalized
                or value_normalized == "vbr"
            )

        label = "Bitrate Type"

    elif kind == "frame_rate":
        wanted = str(settings["frame_rate"]).strip()

        def predicate(text_value, value_value):
            normalized = normalize_nvr_video_ui_text(text_value)
            # Intentionally DO NOT accept "Full Frame Rate" as equivalent to
            # numeric 25.  The project requirement is for the UI to explicitly
            # show 25 fps.
            if "full frame" in normalized:
                return False
            match = re.search(r"(?:^|\D)(\d+(?:\.\d+)?)(?:\D|$)", normalized)
            if match:
                try:
                    if abs(float(match.group(1)) - float(wanted)) < 0.001:
                        return True
                except Exception:
                    pass
            return normalized in {wanted, f"{wanted} fps"}

        label = f"Frame Rate {wanted}"

    elif kind == "encoding":
        wanted = re.sub(
            r"[^a-z0-9]",
            "",
            str(settings["video_encoding"]).lower(),
        )

        def predicate(text_value, value_value):
            normalized = re.sub(
                r"[^a-z0-9]",
                "",
                str(text_value or "").lower(),
            )
            return normalized == wanted

        label = f"Video Encoding {settings['video_encoding']}"

    elif kind == "smart_codec":
        wanted_enabled = bool(settings.get("smart_codec_enabled"))

        def predicate(text_value, value_value):
            normalized = normalize_nvr_video_ui_text(text_value)
            value_normalized = normalize_nvr_video_ui_text(value_value)
            if wanted_enabled:
                return normalized in {"on", "enable", "enabled", "yes"} or value_normalized in {"true", "1", "on"}
            return normalized in {"off", "disable", "disabled", "no"} or value_normalized in {"false", "0", "off"}

        label = "H.265+"

    else:
        raise ValueError(f"Unknown NVR UI select kind: {kind}")

    return _nvr_select_option_by_predicate(
        driver,
        select_element,
        predicate,
        label,
    )


def read_nvr_video_audio_ui_state(
    driver,
    stream_channel_id,
    settings,
):
    target = select_nvr_video_audio_target(
        driver,
        stream_channel_id,
    )

    resolution_select = find_nvr_video_ui_control_by_label(
        driver,
        ["Resolution"],
        "select",
    )
    bitrate_select = find_nvr_video_ui_control_by_label(
        driver,
        ["Bitrate Type"],
        "select",
    )
    frame_rate_select = find_nvr_video_ui_control_by_label(
        driver,
        ["Frame Rate"],
        "select",
    )
    encoding_select = find_nvr_video_ui_control_by_label(
        driver,
        ["Video Encoding"],
        "select",
    )
    smart_select = find_nvr_video_ui_control_by_label(
        driver,
        ["H.265+", "H265+"],
        "select",
    )
    bitrate_input = find_nvr_video_ui_control_by_label(
        driver,
        ["Max. Bitrate", "Max Bitrate"],
        "input:not([type='hidden']):not([type='checkbox']):not([type='radio'])",
    )
    iframe_input = find_nvr_video_ui_control_by_label(
        driver,
        ["I Frame Interval", "I-Frame Interval", "I Frame Interval:"],
        "input:not([type='hidden']):not([type='checkbox']):not([type='radio'])",
    )

    def selected_text(element):
        if element is None:
            return ""
        try:
            return str(Select(element).first_selected_option.text or "").strip()
        except Exception:
            return ""

    def input_value(element):
        if element is None:
            return ""
        try:
            return str(element.get_attribute("value") or "").strip()
        except Exception:
            return ""

    actual = {
        "camera": target.get("camera_text", ""),
        "stream_type": target.get("stream_text", ""),
        "resolution": selected_text(resolution_select),
        "bitrate_type": selected_text(bitrate_select),
        "frame_rate": selected_text(frame_rate_select),
        "max_bitrate": input_value(bitrate_input),
        "video_encoding": selected_text(encoding_select),
        "smart_codec": selected_text(smart_select),
        "i_frame_interval": input_value(iframe_input),
    }

    mismatches = []

    resolution_compact = re.sub(
        r"[^0-9x]",
        "",
        normalize_nvr_video_ui_text(actual["resolution"]),
    )
    wanted_resolution = (
        f"{settings['resolution_width']}x{settings['resolution_height']}"
    )
    if wanted_resolution not in resolution_compact:
        mismatches.append({
            "field": "resolution",
            "expected": wanted_resolution,
            "actual": actual["resolution"],
        })

    bitrate_type_actual = normalize_nvr_video_ui_text(actual["bitrate_type"])
    bitrate_type_wanted = str(settings["bitrate_type"]).strip().lower()
    if bitrate_type_wanted in {"cbr", "constant", "constant bitrate"}:
        bitrate_type_ok = "constant" in bitrate_type_actual or bitrate_type_actual == "cbr"
    else:
        bitrate_type_ok = "variable" in bitrate_type_actual or bitrate_type_actual == "vbr"
    if not bitrate_type_ok:
        mismatches.append({
            "field": "bitrate_type",
            "expected": settings["bitrate_type"],
            "actual": actual["bitrate_type"],
        })

    frame_actual = normalize_nvr_video_ui_text(actual["frame_rate"])
    frame_match = re.search(r"(?:^|\D)(\d+(?:\.\d+)?)(?:\D|$)", frame_actual)
    frame_number = frame_match.group(1) if frame_match else ""
    try:
        frame_number_matches = (
            bool(frame_number)
            and abs(float(frame_number) - float(settings["frame_rate"])) < 0.001
        )
    except Exception:
        frame_number_matches = False

    if (
        "full frame" in frame_actual
        or not frame_number_matches
    ):
        mismatches.append({
            "field": "frame_rate",
            "expected": str(settings["frame_rate"]),
            "actual": actual["frame_rate"],
        })

    if str(actual["max_bitrate"]).strip() != str(settings["max_bitrate"]).strip():
        mismatches.append({
            "field": "max_bitrate",
            "expected": str(settings["max_bitrate"]),
            "actual": actual["max_bitrate"],
        })

    encoding_actual = re.sub(
        r"[^a-z0-9]",
        "",
        str(actual["video_encoding"]).lower(),
    )
    encoding_wanted = re.sub(
        r"[^a-z0-9]",
        "",
        str(settings["video_encoding"]).lower(),
    )
    if encoding_actual != encoding_wanted:
        mismatches.append({
            "field": "video_encoding",
            "expected": settings["video_encoding"],
            "actual": actual["video_encoding"],
        })

    if str(actual["i_frame_interval"]).strip() != str(settings["i_frame_interval"]).strip():
        mismatches.append({
            "field": "i_frame_interval",
            "expected": str(settings["i_frame_interval"]),
            "actual": actual["i_frame_interval"],
        })

    if smart_select is not None and actual["smart_codec"]:
        smart_actual = normalize_nvr_video_ui_text(actual["smart_codec"])
        smart_expected = bool(settings.get("smart_codec_enabled"))
        smart_ok = (
            smart_actual in {"on", "enable", "enabled", "yes"}
            if smart_expected
            else smart_actual in {"off", "disable", "disabled", "no"}
        )
        if not smart_ok:
            mismatches.append({
                "field": "smart_codec",
                "expected": "ON" if smart_expected else "OFF",
                "actual": actual["smart_codec"],
            })

    return actual, mismatches


def _nvr_copy_to_modal_probe(driver):
    """Find visible Copy to... dialog and return its exact checkbox controls.

    Returns a serialisable DOM snapshot plus matching Selenium elements.
    We refuse to guess the checkbox ordering: D<n> and Select All must be
    attributable to visible labels, including the disabled/checked D1 case.
    """
    return driver.execute_script(
        r"""
        function norm(v) { return String(v || '').replace(/\s+/g,' ').trim(); }
        function visible(el) {
            if (!el || !el.isConnected) return false;
            let e=el;
            while(e && e.nodeType===1) {
                const st=getComputedStyle(e);
                if(st.display==='none'||st.visibility==='hidden'||e.getAttribute('aria-hidden')==='true') return false;
                e=e.parentElement;
            }
            const r=el.getBoundingClientRect();
            return r.width>0 && r.height>0;
        }
        const titleCandidates = Array.from(document.querySelectorAll('div,span,h1,h2,h3,b,strong'))
            .filter(e => visible(e) && /^copy to\.{0,3}$/i.test(norm(e.innerText || e.textContent)));
        const modalSelectors = [
          '[role="dialog"]','.el-dialog','.modal','.modal-dialog','.dialog',
          '.aui_dialog','.ui-dialog','.window','.layui-layer','.popbox','.popup'
        ].join(',');
        const candidates = new Set(Array.from(document.querySelectorAll(modalSelectors)).filter(visible));
        for(const title of titleCandidates){
            let parent=title.parentElement;
            for(let depth=0;parent&&depth<12;depth++,parent=parent.parentElement){
                const body=norm(parent.innerText||parent.textContent);
                if(body.includes('Select All') && /\bD1\b/.test(body)) candidates.add(parent);
            }
        }
        const valid = Array.from(candidates).filter(el=>{
            const txt=norm(el.innerText||el.textContent);
            return visible(el) && /copy to/i.test(txt) && txt.includes('Select All') && /\bD1\b/.test(txt);
        }).sort((a,b)=>{
            const ra=a.getBoundingClientRect(),rb=b.getBoundingClientRect();
            return ra.width*ra.height-rb.width*rb.height;
        });
        if(!valid.length) return {found:false,reason:'Copy to dialog not visible'};
        const root=valid[0];
        function locateControl(label) {
            const items=Array.from(root.querySelectorAll('label,span,td,div,li'))
                .filter(el => visible(el) && norm(el.innerText||el.textContent)===label);
            // Prefer the actual label or a small text node, never a whole panel.
            items.sort((a,b)=>{
                const ra=a.getBoundingClientRect(),rb=b.getBoundingClientRect();
                return ra.width*ra.height-rb.width*rb.height;
            });
            for(const item of items) {
                let e=item;
                for(let depth=0;depth<5&&e&&e!==root;depth++,e=e.parentElement){
                    let input=e.matches && e.matches('input[type="checkbox"]')?e:
                        e.querySelector('input[type="checkbox"]');
                    if(!input && e.tagName==='LABEL' && e.htmlFor)
                        input=document.getElementById(e.htmlFor);
                    if(input && root.contains(input)) {
                        const widget=input.closest('label')||e;
                        return {input:input,clickTarget:visible(widget)?widget:(visible(input)?input:item),
                                checked:!!input.checked,disabled:!!input.disabled};
                    }
                }
            }
            return null;
        }
        const labels = Array.from(root.querySelectorAll('label,span,td,div,li'))
            .filter(visible).map(el=>norm(el.innerText||el.textContent));
        const found = [...new Set(labels.filter(v=>/^D\d+$/i.test(v)).map(v=>v.toUpperCase()))]
            .sort((a,b)=>Number(a.slice(1))-Number(b.slice(1)));
        const rows={};
        for(const name of found) rows[name]=locateControl(name);
        return {found:true,root:root,master:locateControl('Select All'),rows:rows,deviceLabels:found};
        """
    )


def _nvr_select_copy_to_all_expected(driver, expected_count):
    """Open Copy to, Select All, OK; verify only expected D channels selected.

    This function does NOT click the main Video/Audio Save button: the caller
    does so after Copy to has closed. It raises if extra channels would be
    affected, a desired box cannot be checked, or the modal stays open.
    """
    expected_count = int(expected_count)
    expected_names = [f'D{n}' for n in range(1, expected_count + 1)]

    # Must already be on the exact source D1/Main or D1/Sub video form.
    switch_to_nvr_video_audio_form_context(driver, 1)
    copy_button=driver.execute_script(
        r"""
        function visible(e) { if(!e||!e.isConnected) return false;
          const s=getComputedStyle(e),r=e.getBoundingClientRect();
          return s.display!=='none' && s.visibility!=='hidden'&&r.width>0&&r.height>0;
        }
        const xs=Array.from(document.querySelectorAll('button,a,input[type=button],div,span'))
          .filter(visible).filter(e=>/^copy to\.{0,3}$/i.test(String(e.tagName==='INPUT'?e.value:(e.innerText||e.textContent)).trim()));
        xs.sort((a,b)=>{
          const ar=a.getBoundingClientRect(),br=b.getBoundingClientRect();
          return ar.width*ar.height-br.width*br.height;
        });
        if(!xs.length) return null;
        const x=xs[0]; return x.closest('button,a,input[type="button"]')||x;
        """
    )
    if copy_button is None:
        raise RuntimeError('NVR Video/Audio Copy to... button is not visible')

    try:
        ActionChains(driver).move_to_element(copy_button).pause(0.10).click(copy_button).perform()
    except Exception:
        copy_button.click()

    deadline=time_module.monotonic()+NVR_STREAM_Q2_COPY_TO_DIALOG_WAIT_SECONDS
    snapshot={}
    while time_module.monotonic()<deadline:
        snapshot=_nvr_copy_to_modal_probe(driver)
        if snapshot.get('found'): break
        time_module.sleep(0.15)
    if not snapshot.get('found'):
        raise RuntimeError('Copy to... dialog did not open: '+str(snapshot.get('reason','')))

    actual_names=snapshot.get('deviceLabels',[])
    if actual_names != expected_names:
        raise RuntimeError(
            'Copy to targets differ from Excel expected cameras; refusing Select All. '
            f'Expected={expected_names}; actual={actual_names}'
        )

    def verify_checked(state):
        rows=state.get('rows',{})
        missing=[name for name in expected_names if not rows.get(name)]
        if missing:
            raise RuntimeError(f'Copy to checkbox rows not found: {missing}')
        return all(rows[name].get('checked') is True for name in expected_names)

    if not verify_checked(snapshot):
        master=snapshot.get('master')
        if not master:
            raise RuntimeError('Copy to Select All checkbox control could not be identified')
        if not master.get('checked'):
            if master.get('disabled'):
                raise RuntimeError('Copy to Select All checkbox is disabled and not checked')
            target=master.get('clickTarget') or master.get('input')
            try:
                ActionChains(driver).move_to_element(target).pause(0.08).click(target).perform()
            except Exception:
                target.click()

    snapshot=_nvr_copy_to_modal_probe(driver)
    if not snapshot.get('found') or not verify_checked(snapshot):
        raise RuntimeError('Copy to Select All did not check all expected camera boxes')
    for name in expected_names:
        if snapshot['rows'][name].get('disabled') and not snapshot['rows'][name].get('checked'):
            raise RuntimeError(f'Copy to {name} is disabled and unchecked')

    # Click the OK button INSIDE the modal (not the underlying page).
    root=snapshot['root']
    ok_button=driver.execute_script(
        r"""
        const root=arguments[0];
        function norm(s){return String(s||'').replace(/\s+/g,' ').trim().toLowerCase()}
        function visible(e){if(!e||!e.isConnected)return false;
          const s=getComputedStyle(e),r=e.getBoundingClientRect();
          return s.display!=='none'&&s.visibility!=='hidden'&&r.width>0&&r.height>0;}
        let matches=Array.from(root.querySelectorAll('button,a,input[type="button"],input[type="submit"],span,div'))
          .filter(visible).filter(e=>norm(e.tagName==='INPUT'?e.value:(e.innerText||e.textContent))==='ok');
        matches.sort((a,b)=>{const x=a.getBoundingClientRect(),y=b.getBoundingClientRect();
          return x.width*x.height-y.width*y.height});
        if(!matches.length)return null;
        return matches[0].closest('button,a,input[type="button"],input[type="submit"]')||matches[0];
        """, root
    )
    if ok_button is None:
        raise RuntimeError('Copy to dialog OK button not found')
    try:
        ActionChains(driver).move_to_element(ok_button).pause(0.08).click(ok_button).perform()
    except Exception:
        ok_button.click()

    time_module.sleep(NVR_STREAM_Q2_COPY_TO_VERIFY_DELAY_SECONDS)
    probe=_nvr_copy_to_modal_probe(driver)
    if probe.get('found'):
        raise RuntimeError('Copy to dialog stayed open after OK; selection was not confirmed')
    print(f'[NVR STREAM COPY ALL] Copy to... Select All → OK confirmed for {expected_names}.')
    return expected_names


def apply_nvr_stream_profile_copy_all_once(
    nvr_ip, nvr_username, nvr_password, expected_count, stream_role, settings
):
    """Single browser login, single Copy to and Save, one reload, N readbacks.

    Returns a dictionary of channel IDs verified on a fresh page. Failures do
    not count as success; the caller may use the original individual workflow
    for any missing channel. Does not perform physical camera audits.
    """
    verified={}
    driver=None
    suffix=int(settings['stream_suffix'])
    source_id=100+suffix
    expected_ids=[str(n*100+suffix) for n in range(1,int(expected_count)+1)]
    result={'verified':verified,'errors':{},'copy_applied':False}
    try:
        if not SELENIUM_AVAILABLE:
            raise RuntimeError('Selenium is unavailable')
        driver=create_hikvision_edge_driver()
        config_url=f'https://{nvr_ip}{DISCREET_CONFIG_PATH}?t={int(time_module.time()*1000)}'
        driver.get(config_url)
        time_module.sleep(0.7)
        hikvision_web_login_if_needed(driver,nvr_username,nvr_password)
        driver.get(config_url)
        time_module.sleep(0.7)
        try:
            dismiss_hikvision_success_note(driver,timeout=1.0,label='bulk stream pre-nav')
        except Exception: pass
        try:
            click_visible_exact_text(driver,['Video/Audio'],'NVR Video/Audio',timeout=8)
        except Exception:
            click_old_ui_menu_item_robust(driver,'Video/Audio','NVR Video/Audio')
        time_module.sleep(NVR_STREAM_BROWSER_UI_TARGET_SETTLE_SECONDS)
        source_target=select_nvr_video_audio_target(driver,source_id)
        if source_target.get('channel_number')!=1:
            raise RuntimeError('Copy to source must be D1, not '+str(source_target))
        print(f'[NVR STREAM COPY ALL] {nvr_ip} {stream_role}: source=D1, targets=D1..D{expected_count}.')
        write=configure_nvr_stream_via_video_audio_ui(
            driver,source_id,settings,copy_to_expected_count=expected_count
        )
        if not write.get('ok') or not write.get('copy_to_all_applied'):
            raise RuntimeError('One-shot Copy to + Save did not complete: '+str(write.get('detail','')))
        result['copy_applied']=True
        # A SINGLE complete page reload, then check every requested D-channel.
        driver.switch_to.default_content()
        driver.get(config_url)
        time_module.sleep(0.8)
        try:
            click_visible_exact_text(driver,['Video/Audio'],'NVR Video/Audio',timeout=8)
        except Exception:
            click_old_ui_menu_item_robust(driver,'Video/Audio','NVR Video/Audio')
        time_module.sleep(NVR_STREAM_BROWSER_UI_TARGET_SETTLE_SECONDS)
        for stream_id in expected_ids:
            try:
                actual,mismatches=read_nvr_video_audio_ui_state(driver,stream_id,settings)
                if mismatches:
                    result['errors'][stream_id]=f'Persisted UI mismatch={mismatches}; actual={actual}'
                    print(f'[NVR STREAM COPY ALL WARNING] Stream {stream_id}: {result["errors"][stream_id]}')
                else:
                    verified[stream_id]=actual
                    print(f'[OK] [NVR STREAM COPY ALL] Stream {stream_id} persisted: '
                          f'FPS={actual.get("frame_rate")}, IFrame={actual.get("i_frame_interval")}, '
                          f'Resolution={actual.get("resolution")}.')
            except Exception as exc:
                result['errors'][stream_id]=f'Post-reload UI readback failed: {type(exc).__name__}: {exc}'
        return result
    except Exception as exc:
        result['error']=f'{type(exc).__name__}: {exc}'
        print(f'[NVR STREAM COPY ALL WARNING] {nvr_ip} {stream_role}: {result["error"]}; '
              'switching to individual configuration/verification for unverified channels.')
        if driver is not None:
            try:save_web_ui_debug(driver,nvr_ip,f'nvr_stream_copy_all_{stream_role}_failure_v126')
            except Exception:pass
        return result
    finally:
        if driver is not None:
            try:driver.quit()
            except Exception:pass


def configure_nvr_stream_via_video_audio_ui(
    driver,
    stream_channel_id,
    settings,
    copy_to_expected_count=None,
):
    """
    Last-resort, technician-equivalent fallback for DS-E08NI-Q2 firmware.

    This path intentionally uses the visible Video/Audio controls and Save
    button instead of synthesising another StreamingProxy request.  It is used
    only after SessionLogin and same-origin browser fetch fail.  The final
    verification is the actual NVR UI state for the requested D-channel and
    stream type, which is exactly what the project needs to enforce.
    """
    try:
        actual_before, mismatches_before = read_nvr_video_audio_ui_state(
            driver,
            stream_channel_id,
            settings,
        )

        if not mismatches_before and copy_to_expected_count is None:
            return {
                "ok": True,
                "status": 200,
                "detail": (
                    "NVR Video/Audio UI already matches Excel after selecting "
                    f"the exact target stream {stream_channel_id}; no Save was required."
                ),
                "actual": actual_before,
                "browser_ui_fallback": True,
            }

        channel_number = nvr_stream_input_channel_number(stream_channel_id)
        switch_to_nvr_video_audio_form_context(driver, channel_number)

        # Re-find each control immediately before editing it. Older Hikvision
        # pages can replace the Video pane after a dropdown change, which makes
        # WebElement references captured in one batch stale.
        for kind, labels in [
            ("resolution", ["Resolution"]),
            ("bitrate_type", ["Bitrate Type"]),
            ("frame_rate", ["Frame Rate"]),
            ("encoding", ["Video Encoding"]),
        ]:
            switch_to_nvr_video_audio_form_context(driver, channel_number)
            control = find_nvr_video_ui_control_by_label(
                driver,
                labels,
                "select",
            )
            _nvr_choose_settings_select_option(
                driver,
                control,
                kind,
                settings,
            )
            time_module.sleep(0.15)

        switch_to_nvr_video_audio_form_context(driver, channel_number)
        smart_control = find_nvr_video_ui_control_by_label(
            driver,
            ["H.265+", "H265+"],
            "select",
        )
        if smart_control is not None:
            _nvr_choose_settings_select_option(
                driver,
                smart_control,
                "smart_codec",
                settings,
            )
            time_module.sleep(0.15)

        switch_to_nvr_video_audio_form_context(driver, channel_number)
        bitrate_input = find_nvr_video_ui_control_by_label(
            driver,
            ["Max. Bitrate", "Max Bitrate"],
            "input:not([type='hidden']):not([type='checkbox']):not([type='radio'])",
        )
        _nvr_set_input_value(
            driver,
            bitrate_input,
            settings["max_bitrate"],
            "Max. Bitrate",
        )

        switch_to_nvr_video_audio_form_context(driver, channel_number)
        iframe_input = find_nvr_video_ui_control_by_label(
            driver,
            ["I Frame Interval", "I-Frame Interval", "I Frame Interval:"],
            "input:not([type='hidden']):not([type='checkbox']):not([type='radio'])",
        )
        _nvr_set_input_value(
            driver,
            iframe_input,
            settings["i_frame_interval"],
            "I Frame Interval",
        )

        # v126: technician workflow: D1 source profile → Copy to...
        # Select All → OK → ONE Save. This is intentionally BEFORE Save.
        # On mismatch/unknown targets, fail closed; never copy to extras.
        copied_targets=[]
        if copy_to_expected_count is not None:
            copied_targets=_nvr_select_copy_to_all_expected(
                driver,int(copy_to_expected_count)
            )

        # Reacquire the form after Copy to (or control edits) as some old
        # Hikvision pages replace the entire Video pane.
        switch_to_nvr_video_audio_form_context(driver, channel_number)

        save_target = driver.execute_script(
            r"""
            function visible(element) {
                if (!element) return false;
                const style = window.getComputedStyle(element);
                const rect = element.getBoundingClientRect();
                return (
                    element.isConnected &&
                    style.display !== "none" &&
                    style.visibility !== "hidden" &&
                    rect.width > 0 &&
                    rect.height > 0
                );
            }
            function norm(value) {
                return String(value || "").replace(/\s+/g, " ").trim().toLowerCase();
            }
            const candidates = Array.from(
                document.querySelectorAll("button,a,input[type='button'],input[type='submit'],div,span")
            ).filter((element) => {
                if (!visible(element)) return false;
                const text = norm(
                    element.tagName === "INPUT"
                    ? element.value
                    : (element.innerText || element.textContent)
                );
                return text === "save";
            });
            candidates.sort((a, b) => {
                const ar = a.getBoundingClientRect();
                const br = b.getBoundingClientRect();
                return (ar.width * ar.height) - (br.width * br.height);
            });
            if (!candidates.length) return null;
            const element = candidates[0];
            return element.closest("button,a,input[type='button'],input[type='submit']") || element;
            """
        )

        if save_target is None:
            raise RuntimeError("NVR Video/Audio Save button was not found.")

        driver.execute_script(
            "arguments[0].scrollIntoView({block:'center', inline:'center'});",
            save_target,
        )

        clicked = False
        try:
            ActionChains(driver).move_to_element(save_target).pause(0.15).click(save_target).perform()
            clicked = True
        except Exception:
            pass

        if not clicked:
            try:
                save_target.click()
                clicked = True
            except Exception:
                pass

        if not clicked:
            driver.execute_script(
                """
                const element = arguments[0];
                for (const eventName of ['mousedown','mouseup','click']) {
                    element.dispatchEvent(new MouseEvent(eventName, {
                        view: window, bubbles: true, cancelable: true, buttons: 1
                    }));
                }
                if (typeof element.click === 'function') element.click();
                """,
                save_target,
            )

        time_module.sleep(NVR_STREAM_BROWSER_UI_SAVE_SETTLE_SECONDS)

        try:
            dismiss_hikvision_success_note(
                driver,
                timeout=2.0,
                label=f"NVR stream {stream_channel_id} UI Save",
            )
        except Exception:
            pass

        last_actual = {}
        last_mismatches = []

        for verify_attempt in range(
            1,
            NVR_STREAM_BROWSER_UI_VERIFY_ATTEMPTS + 1,
        ):
            time_module.sleep(NVR_STREAM_BROWSER_UI_VERIFY_WAIT_SECONDS)
            last_actual, last_mismatches = read_nvr_video_audio_ui_state(
                driver,
                stream_channel_id,
                settings,
            )

            if not last_mismatches:
                return {
                    "ok": True,
                    "status": 200,
                    "detail": (
                        "NVR Video/Audio visible UI Save verified exact Excel "
                        f"values for stream {stream_channel_id}; "
                        f"FrameRate={last_actual.get('frame_rate')}; "
                        f"IFrame={last_actual.get('i_frame_interval')}; "
                        f"Resolution={last_actual.get('resolution')}; "
                        f"Bitrate={last_actual.get('max_bitrate')}."
                    ),
                    "actual": last_actual,
                    "browser_ui_fallback": True,
                    "copy_to_all_applied": bool(copied_targets),
                    "copy_to_targets": copied_targets,
                }

            print(
                f"[NVR STREAM UI VERIFY] Stream {stream_channel_id} "
                f"attempt {verify_attempt}/"
                f"{NVR_STREAM_BROWSER_UI_VERIFY_ATTEMPTS} mismatches="
                f"{last_mismatches}"
            )

        return {
            "ok": False,
            "status": 0,
            "detail": (
                "NVR Video/Audio UI Save completed but exact readback still "
                f"mismatched Excel: {last_mismatches}; actual={last_actual}"
            ),
            "actual": last_actual,
            "mismatches": last_mismatches,
            "browser_ui_fallback": True,
        }

    except Exception as error:
        return {
            "ok": False,
            "status": 0,
            "detail": (
                "NVR Video/Audio UI fallback failed: "
                f"{str(error).strip() or repr(error)}"
            ),
            "browser_ui_fallback": True,
        }


def verify_nvr_video_ui_after_fresh_page_load(
    driver,
    config_url,
    stream_channel_id,
    settings,
):
    """A visible form before reload may be unsaved; demand persisted values."""
    try:
        driver.switch_to.default_content()
        driver.get(config_url)
        time_module.sleep(0.8)
        try:
            click_visible_exact_text(
                driver, ["Video/Audio"], "NVR Video/Audio", timeout=8
            )
        except Exception:
            click_old_ui_menu_item_robust(
                driver, "Video/Audio", "NVR Video/Audio"
            )
        time_module.sleep(NVR_STREAM_BROWSER_UI_TARGET_SETTLE_SECONDS)
        actual, mismatches = read_nvr_video_audio_ui_state(
            driver, stream_channel_id, settings
        )
        if mismatches:
            return {"ok": False, "actual": actual, "mismatches": mismatches,
                    "detail": f"Fresh-page readback mismatches={mismatches}"}
        return {"ok": True, "actual": actual, "mismatches": [],
                "detail": "Persisted exact Excel values after full NVR page reload"}
    except Exception as exc:
        return {"ok": False, "actual": {}, "mismatches": [],
                "detail": f"Fresh-page persistence check unavailable: {type(exc).__name__}: {exc}"}


def repair_nvr_stream_via_real_browser(
    nvr_ip,
    nvr_username,
    nvr_password,
    stream_channel_id,
    settings,
    prefer_ui_form=False,
):
    """
    Last-resort recovery for valid StreamingProxy channels that still return
    403/notSupport through requests/SessionLogin-v4.

    The user's successful F12 captures were made from the old Hikvision web
    page itself.  This fallback reproduces that context exactly enough to
    matter: Edge logs into config.asp, visits Video/Audio (which can initialise
    D1's proxy state), then page JavaScript performs same-origin GET/PUT with
    the real WebSession_* cookie, Origin and Referer generated by the browser.
    """
    if not ENABLE_NVR_STREAM_SELENIUM_BROWSER_FALLBACK:
        return {
            "ok": False,
            "status": "",
            "endpoint": (
                f"{NVR_STREAMING_PROXY_ENDPOINT_BASE}/{stream_channel_id}"
            ),
            "detail": "Selenium browser fallback is disabled.",
        }

    if not SELENIUM_AVAILABLE:
        return {
            "ok": False,
            "status": "",
            "endpoint": (
                f"{NVR_STREAMING_PROXY_ENDPOINT_BASE}/{stream_channel_id}"
            ),
            "detail": "Selenium is unavailable for browser StreamingProxy fallback.",
        }

    endpoint = (
        f"{NVR_STREAMING_PROXY_ENDPOINT_BASE}/{stream_channel_id}"
    )
    stream_id_int = int(str(stream_channel_id).strip())
    is_main_stream = (stream_id_int % 100) == 1
    driver = None
    last_status = ""
    last_response = ""

    try:
        print(
            f"[NVR STREAM BROWSER FALLBACK] {nvr_ip} stream "
            f"{stream_channel_id}: opening real Hikvision Edge session."
        )

        driver = create_hikvision_edge_driver()
        config_url = (
            f"https://{nvr_ip}{DISCREET_CONFIG_PATH}"
            f"?t={int(time_module.time() * 1000)}"
        )
        driver.get(config_url)
        time_module.sleep(0.8)
        hikvision_web_login_if_needed(
            driver,
            nvr_username,
            nvr_password,
        )
        time_module.sleep(0.8)
        driver.get(config_url)
        time_module.sleep(0.8)

        dismiss_hikvision_success_note(
            driver,
            timeout=1.0,
            label="NVR stream browser fallback pre-navigation",
        )

        # Visiting Video/Audio mirrors the successful manual workflow and can
        # cause old NVR firmware to initialise an otherwise 403/notSupport D1
        # StreamingProxy object.
        try:
            click_visible_exact_text(
                driver,
                ["Video/Audio"],
                "NVR Video/Audio",
                timeout=8,
            )
            time_module.sleep(
                NVR_STREAM_BROWSER_FALLBACK_PAGE_WAIT_SECONDS
            )
        except Exception as nav_error:
            try:
                click_old_ui_menu_item_robust(
                    driver,
                    "Video/Audio",
                    "NVR Video/Audio",
                )
                time_module.sleep(
                    NVR_STREAM_BROWSER_FALLBACK_PAGE_WAIT_SECONDS
                )
            except Exception:
                print(
                    f"[NVR STREAM BROWSER FALLBACK WARNING] Video/Audio "
                    f"navigation did not complete cleanly: {nav_error}. "
                    "Continuing with same-origin browser fetch."
                )

        target_select_error = ""

        if NVR_STREAM_BROWSER_SELECT_TARGET_BEFORE_API:
            try:
                target_info = select_nvr_video_audio_target(
                    driver,
                    stream_channel_id,
                )
                print(
                    f"[NVR STREAM BROWSER TARGET] Stream {stream_channel_id}: "
                    f"selected {target_info.get('camera_text')} / "
                    f"{target_info.get('stream_text')}."
                )
                # Run same-origin fetch from the NVR top document. The target
                # selection has already initialised the channel/stream state.
                driver.switch_to.default_content()
            except Exception as target_error:
                target_select_error = (
                    str(target_error).strip() or repr(target_error)
                )
                print(
                    f"[NVR STREAM BROWSER TARGET WARNING] Stream "
                    f"{stream_channel_id}: {target_select_error}"
                )

        if prefer_ui_form:
            if target_select_error:
                return {
                    "ok": False,
                    "status": 0,
                    "endpoint": endpoint,
                    "detail": (
                        "UI-first target selection failed; refusing unverified Save: "
                        + target_select_error
                    ),
                    "browser_ui_fallback": True,
                }

            print(
                f"[NVR STREAM UI FIRST] Stream {stream_channel_id}: "
                "using proven exact D-channel Video/Audio Save path; "
                "skipping rejected StreamingProxy PUT."
            )
            ui_result = configure_nvr_stream_via_video_audio_ui(
                driver, stream_channel_id, settings
            )
            if not ui_result.get("ok"):
                ui_result.setdefault("endpoint", endpoint)
                return ui_result

            if NVR_STREAM_UI_FIRST_REQUIRE_PERSISTED_READBACK:
                saved = verify_nvr_video_ui_after_fresh_page_load(
                    driver, config_url, stream_channel_id, settings
                )
                if not saved.get("ok"):
                    return {
                        "ok": False,
                        "status": 0,
                        "endpoint": endpoint,
                        "browser_ui_fallback": True,
                        "detail": (
                            "Video/Audio form may have shown unsaved values. "
                            + saved.get("detail", "")
                        ),
                    }
                ui_result["detail"] = (
                    ui_result.get("detail", "") + "; " + saved["detail"]
                ).strip("; ")
                ui_result["persisted_ui_verified"] = True
            ui_result.setdefault("endpoint", endpoint)
            print(
                f"[OK] [NVR STREAM UI FIRST] Stream {stream_channel_id}: "
                f"{ui_result.get('detail', '')}"
            )
            return ui_result

        get_status, current_xml = nvr_stream_browser_fetch(
            driver,
            endpoint,
            "GET",
            None,
        )

        if (
            get_status != 200
            and NVR_STREAM_BROWSER_FALLBACK_CAPABILITY_WARMUP
        ):
            # Mirror the page's supporting requests observed in F12.  Their
            # primary purpose here is to let firmware initialise/resolve the
            # stream before one final GET.
            for suffix in ("/capabilities", "/dynamicCap"):
                warm_status, _warm_text = nvr_stream_browser_fetch(
                    driver,
                    endpoint + suffix,
                    "GET",
                    None,
                )
                print(
                    f"[NVR STREAM BROWSER FALLBACK] warm-up "
                    f"{endpoint + suffix} -> HTTP {warm_status}."
                )

            time_module.sleep(0.5)
            get_status, current_xml = nvr_stream_browser_fetch(
                driver,
                endpoint,
                "GET",
                None,
            )

        if get_status == 200:
            try:
                if (
                    is_main_stream
                    and should_use_captured_nvr_main_stream_payload(
                        current_xml,
                        stream_channel_id,
                        settings,
                    )
                ):
                    payload = build_captured_nvr_main_stream_xml(
                        stream_channel_id,
                        settings,
                    )
                    payload_source = (
                        "real browser GET detected placeholder main-stream; "
                        "using captured browser template"
                    )
                else:
                    payload = update_nvr_streaming_channel_xml_preserve_schema(
                        current_xml,
                        stream_channel_id,
                        settings,
                    )
                    payload_source = "real browser GET + preserve-schema"
            except Exception as schema_error:
                print(
                    f"[NVR STREAM BROWSER FALLBACK WARNING] Stream "
                    f"{stream_channel_id}: browser GET succeeded but the "
                    f"returned placeholder/schema could not be mutated "
                    f"directly ({schema_error}). Using the captured browser "
                    "PUT template instead."
                )
                if is_main_stream:
                    payload = build_captured_nvr_main_stream_xml(
                        stream_channel_id,
                        settings,
                    )
                else:
                    payload = build_nvr_streaming_channel_xml_without_get(
                        stream_channel_id,
                        settings,
                    )
                payload_source = (
                    "captured browser template after preserve-schema failure"
                )
        else:
            if is_main_stream:
                payload = build_captured_nvr_main_stream_xml(
                    stream_channel_id,
                    settings,
                )
            else:
                payload = build_nvr_streaming_channel_xml_without_get(
                    stream_channel_id,
                    settings,
                )
            payload_source = (
                f"captured browser template after browser GET HTTP {get_status}"
            )

        validate_nvr_stream_payload_before_put(
            payload,
            stream_channel_id,
        )

        payload_file = save_nvr_camera_stream_backup(
            nvr_ip,
            f"stream_{stream_channel_id}_real_browser_fallback_payload",
            payload,
        )

        print(
            f"[NVR STREAM BROWSER FALLBACK] Stream {stream_channel_id}: "
            f"PUT source={payload_source}; payload={payload_file}"
        )

        put_status, put_response = nvr_stream_browser_fetch(
            driver,
            endpoint,
            "PUT",
            payload,
        )
        last_status = put_status
        last_response = put_response

        if not nvr_stream_put_response_is_success(
            put_status,
            put_response,
        ):
            detail = (
                f"Real-browser StreamingProxy PUT failed: HTTP {put_status}; "
                f"response={str(put_response)[:500]}; payload={payload_file}"
            )
            print(f"[NVR STREAM BROWSER FALLBACK WARNING] {detail}")

            if NVR_STREAM_BROWSER_UI_FORM_FALLBACK:
                ui_result = configure_nvr_stream_via_video_audio_ui(
                    driver,
                    stream_channel_id,
                    settings,
                )

                if ui_result.get("ok"):
                    ui_result.setdefault("endpoint", endpoint)
                    ui_result["detail"] = (
                        f"{ui_result.get('detail', '')} "
                        "Raw same-origin StreamingProxy PUT was unavailable, "
                        "so the visible NVR Video/Audio form was used and "
                        "verified instead."
                    ).strip()
                    print(
                        f"[OK] [NVR STREAM UI FALLBACK] Stream "
                        f"{stream_channel_id}: {ui_result['detail']}"
                    )
                    return ui_result

                detail += (
                    f"; uiFallback={ui_result.get('detail', '')}"
                )

            print(f"[NVR STREAM BROWSER FALLBACK FAILED] {detail}")
            try:
                # v120: save the screenshot only AFTER selecting the requested
                # D-channel/stream and attempting the visible-form fallback.
                # This avoids the old misleading D1/Main screenshots for
                # failures that actually belonged to D3/D4 or Sub Stream.
                try:
                    select_nvr_video_audio_target(
                        driver,
                        stream_channel_id,
                    )
                except Exception:
                    pass
                save_web_ui_debug(
                    driver,
                    nvr_ip,
                    f"stream_{stream_channel_id}_browser_put_failure_v120",
                )
            except Exception:
                pass
            return {
                "ok": False,
                "status": put_status,
                "endpoint": endpoint,
                "detail": detail,
                "response": str(put_response)[:500],
            }

        time_module.sleep(
            NVR_STREAM_BROWSER_FALLBACK_VERIFY_WAIT_SECONDS
        )

        verify_status, verify_xml = nvr_stream_browser_fetch(
            driver,
            endpoint,
            "GET",
            None,
        )

        if verify_status == 200:
            actual = read_nvr_streaming_channel_values(verify_xml)
            mismatches = validate_nvr_streaming_channel_values(
                actual,
                stream_channel_id,
                settings,
                expected_dynamic_video_input_channel_id=None,
            )

            if not mismatches:
                detail = (
                    "Real-browser WebSession PUT + GET verified exact Excel "
                    f"values; FrameRateRaw={actual.get('api_frame_rate')}; "
                    f"Resolution={actual.get('resolution_width')}x"
                    f"{actual.get('resolution_height')}; "
                    f"Bitrate={actual.get('max_bitrate')}"
                )
                print(
                    f"[OK] [NVR STREAM BROWSER FALLBACK] Stream "
                    f"{stream_channel_id}: {detail}"
                )
                return {
                    "ok": True,
                    "status": verify_status,
                    "endpoint": endpoint,
                    "detail": detail,
                    "actual": actual,
                    "browser_fallback": True,
                }

            detail = (
                "Real-browser PUT succeeded but GET readback mismatched Excel: "
                f"{mismatches}"
            )

            if NVR_STREAM_BROWSER_UI_FORM_FALLBACK:
                ui_result = configure_nvr_stream_via_video_audio_ui(
                    driver,
                    stream_channel_id,
                    settings,
                )
                if ui_result.get("ok"):
                    ui_result.setdefault("endpoint", endpoint)
                    ui_result["detail"] = (
                        f"{ui_result.get('detail', '')} "
                        "The raw StreamingProxy GET remained inconsistent, "
                        "but the exact target Video/Audio UI state was "
                        "successfully saved and verified."
                    ).strip()
                    print(
                        f"[OK] [NVR STREAM UI FALLBACK] Stream "
                        f"{stream_channel_id}: {ui_result['detail']}"
                    )
                    return ui_result
                detail += f"; uiFallback={ui_result.get('detail', '')}"

            return {
                "ok": False,
                "status": verify_status,
                "endpoint": endpoint,
                "detail": detail,
                "response": str(verify_xml)[:500],
            }

        # v120: when API readback is unavailable, verify the exact requested
        # D-channel/stream through the visible Video/Audio form before accepting
        # the write.  This catches the previous false-success case where the
        # browser page was still on D1/Main while stream 301/401 was being
        # repaired in the background.
        if NVR_STREAM_BROWSER_UI_FORM_FALLBACK:
            ui_result = configure_nvr_stream_via_video_audio_ui(
                driver,
                stream_channel_id,
                settings,
            )
            if ui_result.get("ok"):
                ui_result.setdefault("endpoint", endpoint)
                ui_result["detail"] = (
                    f"{ui_result.get('detail', '')} "
                    f"StreamingProxy verification GET returned HTTP "
                    f"{verify_status}, so the target UI readback is used as "
                    "the final verification."
                ).strip()
                print(
                    f"[OK] [NVR STREAM UI VERIFY] Stream "
                    f"{stream_channel_id}: {ui_result['detail']}"
                )
                return ui_result

            print(
                f"[NVR STREAM UI VERIFY WARNING] Stream "
                f"{stream_channel_id}: {ui_result.get('detail', '')}"
            )

        detail = (
            "Real-browser StreamingProxy PUT returned an accepted response, "
            f"but verification GET returned HTTP {verify_status} and the "
            "exact requested D-channel/stream could not be verified through "
            "the NVR Video/Audio UI. v120 refuses advisory-only success so a "
            "wrong D-channel or Full Frame Rate state cannot be reported OK."
        )
        print(
            f"[NVR STREAM BROWSER FALLBACK FAILED] Stream "
            f"{stream_channel_id}: {detail}"
        )
        return {
            "ok": False,
            "status": put_status,
            "endpoint": endpoint,
            "detail": detail,
            "browser_fallback": True,
            "verification_advisory": True,
        }

    except Exception as error:
        detail = (
            "Real-browser StreamingProxy fallback exception: "
            f"{str(error).strip() or repr(error)}"
        )
        print(f"[NVR STREAM BROWSER FALLBACK FAILED] {detail}")
        if driver is not None:
            try:
                save_web_ui_debug(
                    driver,
                    nvr_ip,
                    f"stream_{stream_channel_id}_browser_fallback_exception_v120",
                )
            except Exception:
                pass
        return {
            "ok": False,
            "status": last_status,
            "endpoint": endpoint,
            "detail": detail,
            "response": str(last_response)[:500],
        }

    finally:
        if driver is not None:
            try:
                driver.quit()
            except Exception:
                pass


def put_nvr_streaming_proxy_xml(
    ip,
    username,
    password,
    endpoint,
    xml_text,
):
    """
    Send StreamingProxy XML using the same Content-Type used by the successful
    DS-E08NI-Q2 browser request.

    Although the body is raw XML, this firmware's web UI sends:
        application/x-www-form-urlencoded; charset=UTF-8

    Do not URL-encode the XML body.
    """
    status, response, headers = isapi_request(
        "PUT",
        ip,
        username,
        password,
        endpoint,
        data=xml_text,
        extra_headers={
            "Content-Type": (
                "application/x-www-form-urlencoded; charset=UTF-8"
            ),
            "Accept": "*/*",
            "X-Requested-With": "XMLHttpRequest",
            "Cache-Control": "max-age=0",
            "If-Modified-Since": "0",
        },
    )

    return status, response


def build_nvr_streaming_channel_xml_without_get(
    stream_channel_id,
    settings,
):
    """
    Build a confirmed StreamingProxy PUT payload without a preliminary GET.

    This fallback is used only when the NVR firmware explicitly returns
    notSupport for GET /StreamingProxy/channels/<id>.

    Audio is intentionally omitted. This automation only controls VIDEO
    settings, matching the user's requirement not to configure audio.

    Channel binding is derived from the stream ID:
        101/102 -> D1
        201/202 -> D2
        301/302 -> D3
        401/402 -> D4
    """
    input_channel_number = nvr_stream_input_channel_number(
        stream_channel_id
    )

    video_enabled = (
        "true"
        if settings["video_enabled"]
        else "false"
    )

    smart_codec_enabled = (
        "true"
        if settings["smart_codec_enabled"]
        else "false"
    )

    video_scan_type_xml = ""

    if not is_blank(settings.get("video_scan_type")):
        video_scan_type_xml = (
            "\n    <videoScanType>"
            f"{xml_escape(str(settings['video_scan_type']))}"
            "</videoScanType>"
        )

    smart_codec_xml = ""

    if settings.get("include_smart_codec"):
        smart_codec_xml = (
            "\n    <SmartCodec>\n"
            f"      <enabled>{smart_codec_enabled}</enabled>\n"
            "    </SmartCodec>"
        )

    # Latest D1 browser capture includes disabled audio on both 101 and 102.
    # D2 browser captures omit Audio. Match that behavior in the no-GET
    # fallback so video configuration does not invent audio settings on D2+.
    audio_xml = ""
    if input_channel_number == 1:
        audio_xml = (
            "\n  <Audio>\n"
            "    <enabled>false</enabled>\n"
            f"    <audioInputChannelID>{input_channel_number}</audioInputChannelID>\n"
            "    <audioCompressionType>G.711alaw</audioCompressionType>\n"
            "  </Audio>"
        )

    return f"""<?xml version="1.0" encoding="UTF-8"?>
<StreamingChannel xmlns="http://www.isapi.org/ver20/XMLSchema" version="2.0">
  <channelName>{xml_escape(str(stream_channel_id))}</channelName>
  <enabled>true</enabled>
  <Transport>
    <ControlProtocolList>
      <ControlProtocol>
        <streamingTransport>{xml_escape(str(settings["streaming_transport"]))}</streamingTransport>
      </ControlProtocol>
    </ControlProtocolList>
  </Transport>{audio_xml}
  <id xmlns="">{xml_escape(str(stream_channel_id))}</id>
  <Video xmlns="">
    <enabled>{video_enabled}</enabled>
    <dynVideoInputChannelID>{xml_escape(str(input_channel_number))}</dynVideoInputChannelID>
    <videoCodecType>{xml_escape(str(settings["video_encoding"]))}</videoCodecType>
    <videoResolutionWidth>{xml_escape(str(settings["resolution_width"]))}</videoResolutionWidth>{video_scan_type_xml}
    <videoResolutionHeight>{xml_escape(str(settings["resolution_height"]))}</videoResolutionHeight>
    <videoQualityControlType>{xml_escape(str(settings["bitrate_type"]))}</videoQualityControlType>
    <constantBitRate>{xml_escape(str(settings["max_bitrate"]))}</constantBitRate>
    <maxFrameRate>{xml_escape(str(settings["api_frame_rate"]))}</maxFrameRate>{smart_codec_xml}
    <GovLength>{xml_escape(str(settings["i_frame_interval"]))}</GovLength>
  </Video>
</StreamingChannel>"""


def nvr_stream_put_response_is_success(status, response_text):
    """
    Hikvision may return HTTP 200 with statusCode=1/statusString=OK and
    subStatusCode=riskPassword. That is still a successful configuration PUT.
    """
    if int(status or 0) != 200:
        return False

    response_lower = str(response_text or "").lower()

    # Empty-body HTTP 200 is also accepted.
    if not response_lower.strip():
        return True

    return (
        "<statuscode>1</statuscode>" in response_lower
        or "<statusstring>ok</statusstring>" in response_lower
        or '"statuscode":1' in response_lower.replace(" ", "")
        or '"statusstring":"ok"' in response_lower.replace(" ", "")
    )


def update_nvr_streaming_channel_xml(
    current_xml,
    stream_channel_id,
    settings,
):
    """
    Build the StreamingProxy XML from Excel-controlled VIDEO settings.

    Audio is intentionally NOT configured by this automation.

    If the NVR's current StreamingProxy XML contains an <Audio> block, the
    exact existing block is preserved unchanged in the PUT payload. This
    prevents the script from changing audio enable state, audio input channel,
    or audio codec while still sending the full StreamingChannel structure
    expected by this Hikvision firmware.

    Per-channel video binding is derived automatically:
        Stream 101/102 -> dynVideoInputChannelID 1
        Stream 201/202 -> dynVideoInputChannelID 2
        Stream 301/302 -> dynVideoInputChannelID 3
        Stream 401/402 -> dynVideoInputChannelID 4
    """
    root = ET.fromstring(current_xml)

    if xml_local_name(root.tag) != "StreamingChannel":
        raise ValueError(
            "Unexpected StreamingProxy response root: "
            f"{xml_local_name(root.tag)}"
        )

    channel_name = xml_find_first_text(
        root,
        ["channelName"],
    )

    if is_blank(channel_name):
        channel_name = str(stream_channel_id)

    input_channel_number = nvr_stream_input_channel_number(
        stream_channel_id
    )

    video_enabled = (
        "true"
        if settings["video_enabled"]
        else "false"
    )

    smart_codec_enabled = (
        "true"
        if settings["smart_codec_enabled"]
        else "false"
    )

    video_scan_type_xml = ""

    if not is_blank(settings.get("video_scan_type")):
        video_scan_type_xml = (
            "\n    <videoScanType>"
            f"{xml_escape(str(settings['video_scan_type']))}"
            "</videoScanType>"
        )

    smart_codec_xml = ""

    if settings.get("include_smart_codec"):
        smart_codec_xml = (
            "\n    <SmartCodec>\n"
            f"      <enabled>{smart_codec_enabled}</enabled>\n"
            "    </SmartCodec>"
        )

    dynamic_video_input_channel_id = str(
        input_channel_number
    )

    # Preserve the existing NVR Audio block exactly as returned by GET.
    # No Audio values are read from Excel, changed, or validated.
    audio_match = re.search(
        r"<Audio(?:\s[^>]*)?>.*?</Audio>",
        current_xml,
        flags=re.IGNORECASE | re.DOTALL,
    )

    preserved_audio_xml = ""

    if audio_match:
        # Preserve the current Audio block unchanged. These are REAL newline
        # characters, not the literal characters backslash+n.
        preserved_audio_xml = (
            "\n  "
            + audio_match.group(0).strip().replace(
                "\n",
                "\n  ",
            )
        )

    return f"""<?xml version="1.0" encoding="UTF-8"?>
<StreamingChannel xmlns="http://www.isapi.org/ver20/XMLSchema" version="2.0">
  <channelName>{xml_escape(str(channel_name))}</channelName>
  <enabled>true</enabled>
  <Transport>
    <ControlProtocolList>
      <ControlProtocol>
        <streamingTransport>{xml_escape(str(settings["streaming_transport"]))}</streamingTransport>
      </ControlProtocol>
    </ControlProtocolList>
  </Transport>{preserved_audio_xml}
  <id xmlns="">{xml_escape(str(stream_channel_id))}</id>
  <Video xmlns="">
    <enabled>{video_enabled}</enabled>
    <dynVideoInputChannelID>{xml_escape(dynamic_video_input_channel_id)}</dynVideoInputChannelID>
    <videoCodecType>{xml_escape(str(settings["video_encoding"]))}</videoCodecType>
    <videoResolutionWidth>{xml_escape(str(settings["resolution_width"]))}</videoResolutionWidth>{video_scan_type_xml}
    <videoResolutionHeight>{xml_escape(str(settings["resolution_height"]))}</videoResolutionHeight>
    <videoQualityControlType>{xml_escape(str(settings["bitrate_type"]))}</videoQualityControlType>
    <constantBitRate>{xml_escape(str(settings["max_bitrate"]))}</constantBitRate>
    <maxFrameRate>{xml_escape(str(settings["api_frame_rate"]))}</maxFrameRate>{smart_codec_xml}
    <GovLength>{xml_escape(str(settings["i_frame_interval"]))}</GovLength>
  </Video>
</StreamingChannel>"""




def validate_nvr_stream_payload_before_put(
    payload,
    stream_channel_id,
):
    """
    Validate generated XML locally before sending it to the NVR.

    This prevents a malformed payload from being retried three times against
    the device. It also makes XML-generation problems immediately obvious.
    """
    try:
        ET.fromstring(payload)
    except ET.ParseError as error:
        raise ValueError(
            f"Generated stream {stream_channel_id} payload is invalid XML: "
            f"{error}"
        ) from error

    return True


def read_nvr_streaming_channel_values(xml_text):
    try:
        root = ET.fromstring(xml_text)
    except Exception:
        return {}

    video = None
    audio = None
    transport = None

    for child in list(root):
        local_name = xml_local_name(child.tag)

        if local_name == "Video":
            video = child
        elif local_name == "Audio":
            audio = child
        elif local_name == "Transport":
            transport = child

    def direct_text(parent, name):
        if parent is None:
            return ""

        child = direct_child_by_local_name(
            parent,
            name,
        )

        if child is None or child.text is None:
            return ""

        return child.text.strip()

    smart_codec = (
        direct_child_by_local_name(
            video,
            "SmartCodec",
        )
        if video is not None
        else None
    )

    streaming_transport = ""

    if transport is not None:
        streaming_transport = xml_find_first_text(
            transport,
            ["streamingTransport"],
        )

    return {
        "id": direct_text(root, "id"),
        "video_enabled": direct_text(video, "enabled"),
        "dynamic_video_input_channel_id": direct_text(
            video,
            "dynVideoInputChannelID",
        ),
        "video_encoding": direct_text(
            video,
            "videoCodecType",
        ),
        "resolution_width": direct_text(
            video,
            "videoResolutionWidth",
        ),
        "video_scan_type": direct_text(
            video,
            "videoScanType",
        ),
        "resolution_height": direct_text(
            video,
            "videoResolutionHeight",
        ),
        "bitrate_type": direct_text(
            video,
            "videoQualityControlType",
        ),
        "max_bitrate": (
            direct_text(
                video,
                "constantBitRate",
            )
            or direct_text(
                video,
                "vbrUpperCap",
            )
        ),
        "api_frame_rate": direct_text(
            video,
            "maxFrameRate",
        ),
        "smart_codec_enabled": direct_text(
            smart_codec,
            "enabled",
        ),
        "i_frame_interval": direct_text(
            video,
            "GovLength",
        ),
        "audio_enabled": direct_text(
            audio,
            "enabled",
        ),
        "audio_input_channel_id": direct_text(
            audio,
            "audioInputChannelID",
        ),
        "audio_compression_type": direct_text(
            audio,
            "audioCompressionType",
        ),
        "streaming_transport": streaming_transport,
    }


def validate_nvr_streaming_channel_values(
    actual,
    stream_channel_id=None,
    settings=None,
    expected_dynamic_video_input_channel_id=None,
):
    """
    Validate only stream values that this automation actually controls.

    v110 compatibility guard:
    Older call sites used ``(actual, settings)`` while newer call sites use
    ``(actual, stream_channel_id, settings)``.  Accept both forms so a future
    refactor cannot crash the whole stream pass with a missing positional
    argument.  When the stream ID is omitted, use the ID read back from the
    device.


    IMPORTANT:
    dynVideoInputChannelID is deliberately NOT validated by default. It is an
    NVR-managed proxy binding, not an Excel setting. Real DS-E08NI-Q2 readback
    normalizes it per input:
        101 -> 1
        201 -> 2
        301 -> 3
        401 -> 4

    The latest field run proved that streams 201/301/401 had already accepted
    the requested resolution/FPS/bitrate/codec/I-frame settings; they were
    falsely marked FAILED only because the old validator expected binding=1.

    Audio is also excluded from validation because this automation does not
    configure audio.
    """
    # Backward-compatible two-argument form:
    #     validate_nvr_streaming_channel_values(actual, settings)
    # The second positional value is then the settings dictionary.
    if settings is None and isinstance(stream_channel_id, dict):
        settings = stream_channel_id
        stream_channel_id = str(actual.get("id", "") or "").strip()

    if settings is None:
        raise ValueError(
            "validate_nvr_streaming_channel_values requires stream settings."
        )

    if is_blank(stream_channel_id):
        stream_channel_id = str(actual.get("id", "") or "").strip()

    if is_blank(stream_channel_id):
        raise ValueError(
            "Streaming channel ID is unavailable for validation."
        )

    expected = {
        "id": str(stream_channel_id),
        "video_enabled": (
            "true"
            if settings["video_enabled"]
            else "false"
        ),
        "video_encoding": str(
            settings["video_encoding"]
        ),
        "resolution_width": str(
            settings["resolution_width"]
        ),
        "resolution_height": str(
            settings["resolution_height"]
        ),
        "bitrate_type": str(
            settings["bitrate_type"]
        ).lower(),
        "max_bitrate": str(
            settings["max_bitrate"]
        ),
        "api_frame_rate": str(
            settings["api_frame_rate"]
        ),
        "i_frame_interval": str(
            settings["i_frame_interval"]
        ),
        "streaming_transport": str(
            settings["streaming_transport"]
        ),
    }

    if not is_blank(settings.get("video_scan_type")):
        expected["video_scan_type"] = str(
            settings["video_scan_type"]
        )

    if settings.get("include_smart_codec"):
        expected["smart_codec_enabled"] = (
            "true"
            if settings["smart_codec_enabled"]
            else "false"
        )

    # Optional diagnostic mode only. Normal operation must not fail because
    # the NVR rewrote its own proxy binding.
    if (
        NVR_STREAM_VALIDATE_DYNAMIC_BINDING
        and expected_dynamic_video_input_channel_id is not None
    ):
        expected["dynamic_video_input_channel_id"] = str(
            expected_dynamic_video_input_channel_id
        )

    mismatches = []

    for key, expected_value in expected.items():
        actual_value = str(
            actual.get(key, "")
        ).strip()

        if key in {
            "bitrate_type",
            "video_encoding",
            "streaming_transport",
            "video_scan_type",
        }:
            matches = (
                actual_value.lower()
                == expected_value.lower()
            )
        else:
            matches = (
                actual_value
                == expected_value
            )

        if not matches:
            mismatches.append({
                "field": key,
                "expected": expected_value,
                "actual": actual_value,
            })

    return mismatches




def build_direct_camera_stream_xml_from_current(
    current_xml,
    settings,
):
    """
    Preserve the camera's own StreamingChannel document and modify only the
    video settings controlled by the Excel stream profile.

    This is used only when the NVR's StreamingProxy endpoint refuses the
    operation. It avoids guessing a second camera-specific XML schema.
    """
    root = ET.fromstring(current_xml)

    video = direct_child_by_local_name(
        root,
        "Video",
    )

    if video is None:
        raise ValueError(
            "Camera StreamingChannel XML contains no direct <Video> block."
        )

    def set_direct(parent, tag_name, value, create=False):
        child = direct_child_by_local_name(
            parent,
            tag_name,
        )

        if child is None:
            if not create:
                return False

            # Keep new Video children in the same namespace style as the Video
            # element. Older cameras frequently use xmlns="" for Video.
            if "}" in str(parent.tag):
                namespace = str(parent.tag).split("}")[0].lstrip("{")
                child = ET.SubElement(
                    parent,
                    f"{{{namespace}}}{tag_name}",
                )
            else:
                child = ET.SubElement(
                    parent,
                    tag_name,
                )

        child.text = str(value)
        return True

    set_direct(
        video,
        "enabled",
        "true" if settings["video_enabled"] else "false",
    )
    set_direct(
        video,
        "videoCodecType",
        settings["video_encoding"],
    )
    set_direct(
        video,
        "videoResolutionWidth",
        settings["resolution_width"],
    )
    set_direct(
        video,
        "videoResolutionHeight",
        settings["resolution_height"],
    )
    set_direct(
        video,
        "videoQualityControlType",
        settings["bitrate_type"],
    )
    set_direct(
        video,
        "constantBitRate",
        settings["max_bitrate"],
    )
    set_direct(
        video,
        "maxFrameRate",
        settings["api_frame_rate"],
    )
    set_direct(
        video,
        "GovLength",
        settings["i_frame_interval"],
    )

    if not is_blank(settings.get("video_scan_type")):
        set_direct(
            video,
            "videoScanType",
            settings["video_scan_type"],
        )

    smart_codec = direct_child_by_local_name(
        video,
        "SmartCodec",
    )

    if smart_codec is not None:
        smart_enabled = direct_child_by_local_name(
            smart_codec,
            "enabled",
        )

        if smart_enabled is not None:
            smart_enabled.text = (
                "true"
                if settings["smart_codec_enabled"]
                else "false"
            )

    # Preserve the device's namespace structure instead of rebuilding it from
    # scratch.
    return ET.tostring(
        root,
        encoding="unicode",
    )


def configure_camera_stream_direct_fallback(
    camera_row,
    settings,
    stream_role_label,
):
    """
    Configure the camera itself when the NVR StreamingProxy endpoint refuses
    the write.

    Returns:
        (success: bool, detail: str, actual: dict, http_status: int|str)
    """
    camera_ip = get_value(
        camera_row,
        "Current IP",
    )
    camera_username = get_value(
        camera_row,
        "Username",
    )
    camera_password = get_value(
        camera_row,
        "Password",
    )

    suffix_number = int(
        settings["stream_suffix"]
    )

    # Camera stream IDs are 101 (main), 102 (sub), ...
    camera_stream_channel_id = str(
        100 + suffix_number
    )

    endpoint = (
        f"/ISAPI/Streaming/channels/"
        f"{camera_stream_channel_id}"
    )

    print(
        f"[NVR STREAM FALLBACK] {camera_ip} {stream_role_label}: "
        f"using direct camera endpoint {endpoint}."
    )

    get_status, current_xml = get_xml(
        camera_ip,
        camera_username,
        camera_password,
        endpoint,
    )

    if get_status != 200:
        return (
            False,
            (
                f"Direct camera fallback GET failed: "
                f"HTTP {get_status}; response={current_xml[:500]}"
            ),
            {},
            get_status,
        )

    try:
        payload = build_direct_camera_stream_xml_from_current(
            current_xml,
            settings,
        )
        validate_nvr_stream_payload_before_put(
            payload,
            camera_stream_channel_id,
        )
    except Exception as error:
        return (
            False,
            f"Direct camera fallback payload build failed: {error}",
            {},
            "",
        )

    if is_discreet_camera_row(camera_row):
        put_status, put_response = put_xml_with_discreet_retry(
            camera_row,
            endpoint,
            payload,
            f"Direct Camera {stream_role_label} Fallback",
        )
    else:
        put_status, put_response = put_xml(
            camera_ip,
            camera_username,
            camera_password,
            endpoint,
            payload,
        )

    if put_status not in {200, 204}:
        return (
            False,
            (
                f"Direct camera fallback PUT failed: "
                f"HTTP {put_status}; response={put_response[:500]}"
            ),
            {},
            put_status,
        )

    time_module.sleep(
        NVR_STREAM_DIRECT_CAMERA_VERIFY_WAIT_SECONDS
    )

    verify_status, verify_xml = get_xml(
        camera_ip,
        camera_username,
        camera_password,
        endpoint,
    )

    if verify_status != 200:
        return (
            False,
            (
                f"Direct camera fallback PUT succeeded, but verification "
                f"GET failed: HTTP {verify_status}; "
                f"response={verify_xml[:500]}"
            ),
            {},
            verify_status,
        )

    actual = read_nvr_streaming_channel_values(
        verify_xml
    )

    mismatches = validate_nvr_streaming_channel_values(
        actual,
        camera_stream_channel_id,
        settings,
        expected_dynamic_video_input_channel_id=None,
    )

    if mismatches:
        return (
            False,
            (
                f"Direct camera fallback verification mismatch: "
                f"{mismatches}; actual={actual}"
            ),
            actual,
            put_status,
        )

    return (
        True,
        (
            f"Direct camera stream {camera_stream_channel_id} verified: "
            f"{settings['resolution_width']}x"
            f"{settings['resolution_height']}, "
            f"{settings['frame_rate']} fps, "
            f"{settings['max_bitrate']} Kbps, "
            f"{settings['video_encoding']}"
        ),
        actual,
        put_status,
    )




def get_physical_camera_frame_rate_capabilities(
    camera_ip,
    camera_username,
    camera_password,
    stream_id,
):
    """
    Read physical-camera streaming capabilities and return the advertised
    maxFrameRate option values.

    Hikvision maxFrameRate is FPS x 100, e.g. 2500 = 25 fps.
    Some camera web UIs display the highest supported value using the label
    "Full Frame Rate" instead of showing the numeric FPS.
    """
    endpoint = (
        f"/ISAPI/Streaming/channels/"
        f"{stream_id}/capabilities"
    )

    status, xml_text = get_xml(
        camera_ip,
        camera_username,
        camera_password,
        endpoint,
    )

    result = {
        "status": status,
        "endpoint": endpoint,
        "options_raw": [],
        "max_raw": None,
        "max_fps": None,
        "xml_available": status == 200,
    }

    if status != 200:
        return result

    try:
        root = ET.fromstring(
            xml_text
        )
    except Exception:
        return result

    max_frame_element = None

    for element in root.iter():
        if xml_local_name(
            element.tag
        ) == "maxFrameRate":
            max_frame_element = element
            break

    if max_frame_element is None:
        return result

    options_text = str(
        max_frame_element.attrib.get(
            "opt",
            "",
        )
        or ""
    ).strip()

    options = []

    if options_text:
        for token in re.split(
            r"[,;|\s]+",
            options_text,
        ):
            token = token.strip()

            if not token:
                continue

            try:
                numeric = int(
                    float(
                        token
                    )
                )
            except Exception:
                continue

            if numeric not in options:
                options.append(
                    numeric
                )

    current_text = str(
        max_frame_element.text
        or ""
    ).strip()

    if not options and current_text:
        try:
            options = [
                int(
                    float(
                        current_text
                    )
                )
            ]
        except Exception:
            pass

    positive_options = [
        value
        for value in options
        if value > 0
    ]

    max_raw = (
        max(
            positive_options
        )
        if positive_options
        else None
    )

    max_fps = (
        max_raw
        / NVR_STREAM_FRAME_RATE_MULTIPLIER
        if max_raw is not None
        else None
    )

    result.update({
        "options_raw": options,
        "max_raw": max_raw,
        "max_fps": max_fps,
    })

    return result


def describe_hikvision_frame_rate_with_capability(
    raw_value,
    capability_info=None,
):
    """
    Interpret an actual Hikvision maxFrameRate value using the device's own
    advertised capabilities.

    Important:
      - 2500 is 25 fps by ISAPI definition.
      - If 2500 is also the highest supported value, a Dome camera web UI may
        display that same setting as "Full Frame Rate".
      - Therefore "Full Frame Rate" in the UI is not evidence that the camera
        failed to apply 25 fps.
    """
    raw_text = str(
        raw_value
        or ""
    ).strip()

    if not raw_text:
        return {
            "raw": "",
            "fps": None,
            "label": "UNKNOWN",
            "ui_equivalent": "",
            "explicit": False,
        }

    try:
        raw_number = int(
            float(
                raw_text
            )
        )
    except Exception:
        return {
            "raw": raw_text,
            "fps": None,
            "label": f"UNRECOGNIZED({raw_text})",
            "ui_equivalent": "",
            "explicit": False,
        }

    if raw_number == 0:
        return {
            "raw": raw_text,
            "fps": None,
            "label": "Firmware-defined automatic/full frame rate",
            "ui_equivalent": "Full Frame Rate may be firmware-defined",
            "explicit": False,
        }

    fps = (
        raw_number
        / NVR_STREAM_FRAME_RATE_MULTIPLIER
    )

    max_raw = None

    if capability_info:
        max_raw = capability_info.get(
            "max_raw"
        )

    is_max_supported = (
        max_raw is not None
        and raw_number == max_raw
    )

    if is_max_supported:
        label = (
            f"{fps:g} fps "
            "(maximum supported value)"
        )

        ui_equivalent = (
            "Camera UI may display this same value as "
            "'Full Frame Rate'"
        )
    else:
        label = f"{fps:g} fps"
        ui_equivalent = ""

    return {
        "raw": raw_text,
        "fps": fps,
        "label": label,
        "ui_equivalent": ui_equivalent,
        "explicit": True,
        "is_max_supported": is_max_supported,
    }


def describe_hikvision_frame_rate_raw(raw_value):
    """
    Basic ISAPI conversion only.

    The camera web UI label is firmware/model-specific. Use
    describe_hikvision_frame_rate_with_capability() when device capability
    information is available.
    """
    return describe_hikvision_frame_rate_with_capability(
        raw_value,
        capability_info=None,
    )


def validate_physical_camera_video_values(actual, settings):
    expected = {
        "video_enabled": "true" if settings["video_enabled"] else "false",
        "video_encoding": str(settings["video_encoding"]),
        "resolution_width": str(settings["resolution_width"]),
        "resolution_height": str(settings["resolution_height"]),
        "bitrate_type": str(settings["bitrate_type"]).lower(),
        "max_bitrate": str(settings["max_bitrate"]),
        "api_frame_rate": str(settings["api_frame_rate"]),
        "i_frame_interval": str(settings["i_frame_interval"]),
    }
    if not is_blank(settings.get("video_scan_type")):
        expected["video_scan_type"] = str(settings["video_scan_type"])
    if settings.get("include_smart_codec") and str(actual.get("smart_codec_enabled","")).strip():
        expected["smart_codec_enabled"] = "true" if settings["smart_codec_enabled"] else "false"
    mismatches=[]
    for key, exp in expected.items():
        act=str(actual.get(key,"")).strip()
        same = act.lower()==exp.lower() if key in {"bitrate_type","video_encoding","video_scan_type"} else act==exp
        if not same:
            mismatches.append({"field":key,"expected":exp,"actual":act})
    return mismatches


def final_physical_camera_stream_audit_and_repair(
    camera_row,
    settings,
    stream_role_label,
):
    """
    Authoritative final GET/repair/GET against the camera's physical stream.

    The actual ISAPI value is authoritative. The camera UI may label the
    highest supported numerical frame rate as "Full Frame Rate".
    """
    ip = get_value(
        camera_row,
        "Current IP",
    )

    user = get_value(
        camera_row,
        "Username",
    )

    password = get_value(
        camera_row,
        "Password",
    )

    stream_id = str(
        100
        + int(
            settings[
                "stream_suffix"
            ]
        )
    )

    endpoint = (
        f"/ISAPI/Streaming/channels/"
        f"{stream_id}"
    )

    capability_info = (
        get_physical_camera_frame_rate_capabilities(
            ip,
            user,
            password,
            stream_id,
        )
    )

    if capability_info.get(
        "status"
    ) == 200:
        print(
            f"[PHYSICAL STREAM CAPABILITY] {ip} "
            f"{stream_role_label}: maxFrameRate options(raw)="
            f"{capability_info.get('options_raw', [])}; "
            f"maximum="
            f"{capability_info.get('max_fps')} fps "
            f"(raw={capability_info.get('max_raw')})."
        )
    else:
        print(
            f"[PHYSICAL STREAM CAPABILITY WARNING] {ip}: "
            f"capabilities GET returned HTTP "
            f"{capability_info.get('status')}."
        )

    last_actual = {}
    last_status = ""

    for attempt in range(
        1,
        FINAL_CAMERA_STREAM_REPAIR_MAX_ATTEMPTS + 1,
    ):
        status, xml = get_xml(
            ip,
            user,
            password,
            endpoint,
        )

        last_status = status

        if status != 200:
            if (
                attempt
                < FINAL_CAMERA_STREAM_REPAIR_MAX_ATTEMPTS
            ):
                time_module.sleep(
                    FINAL_CAMERA_STREAM_VERIFY_WAIT_SECONDS
                )
                continue

            return (
                False,
                (
                    f"Physical camera GET failed: "
                    f"HTTP {status}; "
                    f"response={str(xml)[:500]}"
                ),
                {},
                status,
            )

        actual = (
            read_nvr_streaming_channel_values(
                xml
            )
        )

        last_actual = actual

        frame = (
            describe_hikvision_frame_rate_with_capability(
                actual.get(
                    "api_frame_rate",
                    "",
                ),
                capability_info,
            )
        )

        mismatches = (
            validate_physical_camera_video_values(
                actual,
                settings,
            )
        )

        ui_note = (
            f"; {frame['ui_equivalent']}"
            if frame.get(
                "ui_equivalent"
            )
            else ""
        )

        print(
            f"[PHYSICAL STREAM AUDIT] {ip} "
            f"{stream_role_label}: "
            f"actual="
            f"{actual.get('resolution_width','?')}x"
            f"{actual.get('resolution_height','?')}; "
            f"FPS={frame['label']} "
            f"(raw={frame['raw'] or 'blank'})"
            f"{ui_note}; "
            f"bitrate="
            f"{actual.get('max_bitrate','?')} Kbps; "
            f"codec="
            f"{actual.get('video_encoding','?')}; "
            f"IFrame="
            f"{actual.get('i_frame_interval','?')}"
        )

        if not mismatches:
            time_module.sleep(
                FINAL_CAMERA_STREAM_SETTLE_VERIFY_SECONDS
            )

            s2, x2 = get_xml(
                ip,
                user,
                password,
                endpoint,
            )

            if s2 == 200:
                a2 = (
                    read_nvr_streaming_channel_values(
                        x2
                    )
                )

                mm2 = (
                    validate_physical_camera_video_values(
                        a2,
                        settings,
                    )
                )

                if not mm2:
                    f2 = (
                        describe_hikvision_frame_rate_with_capability(
                            a2.get(
                                "api_frame_rate",
                                "",
                            ),
                            capability_info,
                        )
                    )

                    ui_note2 = (
                        f"; {f2['ui_equivalent']}"
                        if f2.get(
                            "ui_equivalent"
                        )
                        else ""
                    )

                    detail = (
                        f"PhysicalCamera={ip}; "
                        f"Resolution="
                        f"{a2.get('resolution_width')}x"
                        f"{a2.get('resolution_height')}; "
                        f"FrameRate={f2['label']} "
                        f"(raw={f2['raw']})"
                        f"{ui_note2}; "
                        f"Bitrate="
                        f"{a2.get('max_bitrate')} Kbps; "
                        f"Codec="
                        f"{a2.get('video_encoding')}; "
                        f"IFrame="
                        f"{a2.get('i_frame_interval')}"
                    )

                    print(
                        f"[OK] [PHYSICAL STREAM AUDIT] "
                        f"{detail}"
                    )

                    return (
                        True,
                        detail,
                        a2,
                        s2,
                    )

                mismatches = mm2
                xml = x2
                actual = a2
                last_actual = a2

            else:
                mismatches = [{
                    "field": "settle_get",
                    "expected": "HTTP 200",
                    "actual": str(
                        s2
                    ),
                }]

        print(
            f"[PHYSICAL STREAM REPAIR] {ip}: "
            f"attempt {attempt}; "
            f"mismatches={mismatches}"
        )

        try:
            payload = (
                build_direct_camera_stream_xml_from_current(
                    xml,
                    settings,
                )
            )
        except Exception as e:
            return (
                False,
                (
                    "Physical camera repair payload "
                    f"build failed: {e}"
                ),
                actual,
                status,
            )

        if is_discreet_camera_row(
            camera_row
        ):
            ps, pr = (
                put_xml_with_discreet_retry(
                    camera_row,
                    endpoint,
                    payload,
                    (
                        f"Final Physical Camera "
                        f"{stream_role_label} Repair"
                    ),
                )
            )
        else:
            ps, pr = put_xml(
                ip,
                user,
                password,
                endpoint,
                payload,
            )

        last_status = ps

        if ps not in {
            200,
            204,
        }:
            if (
                attempt
                < FINAL_CAMERA_STREAM_REPAIR_MAX_ATTEMPTS
            ):
                time_module.sleep(
                    FINAL_CAMERA_STREAM_VERIFY_WAIT_SECONDS
                )
                continue

            return (
                False,
                (
                    "Physical camera repair PUT failed: "
                    f"HTTP {ps}; "
                    f"response={str(pr)[:500]}"
                ),
                actual,
                ps,
            )

        time_module.sleep(
            FINAL_CAMERA_STREAM_VERIFY_WAIT_SECONDS
        )

    frame = (
        describe_hikvision_frame_rate_with_capability(
            last_actual.get(
                "api_frame_rate",
                "",
            ),
            capability_info,
        )
    )

    return (
        False,
        (
            "Physical camera did not reach/stay at "
            f"Excel values after "
            f"{FINAL_CAMERA_STREAM_REPAIR_MAX_ATTEMPTS} "
            f"attempts; actualResolution="
            f"{last_actual.get('resolution_width','?')}x"
            f"{last_actual.get('resolution_height','?')}; "
            f"actualFrameRate={frame['label']} "
            f"(raw={frame['raw'] or 'blank'}); "
            f"actualBitrate="
            f"{last_actual.get('max_bitrate','?')}; "
            f"actualCodec="
            f"{last_actual.get('video_encoding','?')}"
        ),
        last_actual,
        last_status,
    )




def repair_nvr_proxy_stream_exact_values(
    nvr_ip,
    nvr_username,
    nvr_password,
    stream_channel_id,
    settings,
    nvr_stream_web_session=None,
):
    """
    Force the NVR StreamingProxy itself to the Excel values.

    v112 is based on the captured browser requests from the affected NVR:
      - D1 Main 101 and Sub 102 are valid/supported endpoints;
      - D2 Main 201 and Sub 202 are valid/supported endpoints;
      - browser GET/PUT uses the Hikvision WebSession path;
      - maxFrameRate=2500 means 25 fps;
      - HTTP 200 + statusCode=1 is success even with riskPassword advisory.

    Therefore a generic Digest GET returning 403/notSupport is no longer
    allowed to block the PUT. WebSession GET is preferred; if readback is
    temporarily unavailable, a browser-compatible direct PUT is attempted.
    """
    endpoint = (
        f"{NVR_STREAMING_PROXY_ENDPOINT_BASE}/"
        f"{stream_channel_id}"
    )

    last_detail = ""
    last_status = ""
    last_response = ""
    last_audit = None

    stream_id_int = int(str(stream_channel_id).strip())
    is_main_stream = (stream_id_int % 100) == 1

    for attempt in range(
        1,
        NVR_PROXY_EXPLICIT_FPS_REPAIR_MAX_ATTEMPTS + 1,
    ):
        print(
            f"[NVR PROXY REPAIR] Stream {stream_channel_id}: "
            f"attempt {attempt}/"
            f"{NVR_PROXY_EXPLICIT_FPS_REPAIR_MAX_ATTEMPTS}."
        )

        get_status, current_xml = get_nvr_streaming_proxy(
            nvr_stream_web_session,
            nvr_ip,
            nvr_username,
            nvr_password,
            endpoint,
        )

        last_status = get_status
        last_response = current_xml
        get_unsupported = is_nvr_stream_get_not_supported(
            get_status,
            current_xml,
        )

        try:
            if get_status == 200:
                if (
                    is_main_stream
                    and should_use_captured_nvr_main_stream_payload(
                        current_xml,
                        stream_channel_id,
                        settings,
                    )
                ):
                    payload = build_captured_nvr_main_stream_xml(
                        stream_channel_id,
                        settings,
                    )
                    payload_source = (
                        "captured browser template because readable GET is a "
                        "placeholder main-stream profile"
                    )
                else:
                    payload = update_nvr_streaming_channel_xml_preserve_schema(
                        current_xml,
                        stream_channel_id,
                        settings,
                    )
                    payload_source = "WebSession/current XML preserve-schema"

            elif get_unsupported:
                # Captured browser evidence proves these endpoints can accept
                # PUT even when a preliminary generic GET reports notSupport.
                if is_main_stream:
                    payload = build_captured_nvr_main_stream_xml(
                        stream_channel_id,
                        settings,
                    )
                else:
                    payload = build_nvr_streaming_channel_xml_without_get(
                        stream_channel_id,
                        settings,
                    )

                payload_source = (
                    "browser-compatible direct PUT because GET returned "
                    f"HTTP {get_status}/notSupport"
                )

                print(
                    f"[NVR PROXY REPAIR] Stream {stream_channel_id}: "
                    "GET is temporarily unavailable; direct PUT will still "
                    "be attempted using the captured browser structure."
                )

            else:
                last_detail = (
                    f"NVR proxy GET failed: HTTP {get_status}; "
                    f"response={str(current_xml)[:500]}"
                )

                if attempt < NVR_PROXY_EXPLICIT_FPS_REPAIR_MAX_ATTEMPTS:
                    time_module.sleep(
                        NVR_PROXY_EXPLICIT_FPS_REPAIR_WAIT_SECONDS
                    )
                    continue

                break

            validate_nvr_stream_payload_before_put(
                payload,
                stream_channel_id,
            )

        except Exception as error:
            last_detail = (
                "Unable to create browser-compatible NVR proxy payload: "
                f"{error}"
            )

            if attempt < NVR_PROXY_EXPLICIT_FPS_REPAIR_MAX_ATTEMPTS:
                time_module.sleep(
                    NVR_PROXY_EXPLICIT_FPS_REPAIR_WAIT_SECONDS
                )
                continue

            break

        payload_file = save_nvr_camera_stream_backup(
            nvr_ip,
            (
                f"stream_{stream_channel_id}_"
                f"explicit_fps_repair_attempt_{attempt}"
            ),
            payload,
        )

        print(
            f"[NVR PROXY REPAIR] Stream {stream_channel_id}: "
            f"forcing Excel FPS={settings['frame_rate']} "
            f"(maxFrameRate raw={settings['api_frame_rate']}); "
            f"source={payload_source}; payload={payload_file}"
        )

        if nvr_stream_web_session is not None:
            put_status, put_response = (
                put_nvr_streaming_proxy_via_web_session(
                    nvr_stream_web_session,
                    endpoint,
                    payload,
                )
            )
        else:
            put_status, put_response = (
                put_nvr_streaming_proxy_xml(
                    nvr_ip,
                    nvr_username,
                    nvr_password,
                    endpoint,
                    payload,
                )
            )

        last_status = put_status
        last_response = put_response

        put_ok = nvr_stream_put_response_is_success(
            put_status,
            put_response,
        )

        if not put_ok:
            last_detail = (
                f"NVR proxy repair PUT failed: HTTP {put_status}; "
                f"response={str(put_response)[:500]}; "
                f"payload={payload_file}"
            )

            print(
                f"[NVR PROXY REPAIR WARNING] {last_detail}"
            )

            if attempt < NVR_PROXY_EXPLICIT_FPS_REPAIR_MAX_ATTEMPTS:
                time_module.sleep(
                    NVR_PROXY_EXPLICIT_FPS_REPAIR_WAIT_SECONDS
                )
                continue

            break

        time_module.sleep(
            NVR_PROXY_EXPLICIT_FPS_REPAIR_WAIT_SECONDS
        )

        last_audit = verify_nvr_proxy_stream_exact_values(
            nvr_ip,
            nvr_username,
            nvr_password,
            stream_channel_id,
            settings,
            nvr_stream_web_session=nvr_stream_web_session,
        )

        if last_audit["ok"]:
            actual = last_audit.get("actual", {})

            detail = (
                f"NVR proxy explicitly verified: "
                f"Resolution={actual.get('resolution_width')}x"
                f"{actual.get('resolution_height')}; "
                f"FrameRateRaw={actual.get('api_frame_rate')} "
                f"(ExcelTargetRaw={settings['api_frame_rate']}); "
                f"Bitrate={actual.get('max_bitrate')} Kbps; "
                f"Codec={actual.get('video_encoding')}; "
                f"IFrame={actual.get('i_frame_interval')}"
            )

            print(
                f"[OK] [NVR PROXY REPAIR] Stream "
                f"{stream_channel_id}: {detail}"
            )

            return {
                "ok": True,
                "status": last_audit["status"],
                "endpoint": endpoint,
                "detail": detail,
                "audit": last_audit,
            }

        audit_status = int(last_audit.get("status") or 0)
        audit_response = str(last_audit.get("response", "") or "")
        audit_get_unsupported = (
            audit_status in {403, 405}
            or any(
                mismatch.get("field") == "NVR proxy GET"
                for mismatch in last_audit.get("mismatches", [])
                if isinstance(mismatch, dict)
            )
        )

        if audit_get_unsupported:
            last_detail = (
                "NVR proxy PUT returned HTTP 200/statusCode=1, but the "
                "readback GET is still temporarily unavailable. "
                "The captured browser behavior confirms statusCode=1 is an "
                "accepted stream update."
            )

            if attempt < NVR_PROXY_EXPLICIT_FPS_REPAIR_MAX_ATTEMPTS:
                print(
                    f"[NVR PROXY REPAIR WARNING] {last_detail} "
                    "Retrying read/write once more."
                )
                time_module.sleep(
                    NVR_PROXY_EXPLICIT_FPS_REPAIR_WAIT_SECONDS
                )
                continue

            print(
                f"[OK] [NVR PROXY REPAIR] Stream {stream_channel_id}: "
                f"{last_detail}"
            )

            return {
                "ok": True,
                "status": put_status,
                "endpoint": endpoint,
                "detail": last_detail,
                "audit": last_audit,
                "verification_advisory": True,
            }

        last_detail = (
            "NVR proxy PUT returned success but readback still "
            f"does not match Excel: {last_audit.get('mismatches', [])}"
        )

        print(
            f"[NVR PROXY REPAIR WARNING] {last_detail}"
        )

        if attempt < NVR_PROXY_EXPLICIT_FPS_REPAIR_MAX_ATTEMPTS:
            time_module.sleep(
                NVR_PROXY_EXPLICIT_FPS_REPAIR_WAIT_SECONDS
            )

    browser_fallback_candidate = (
        ENABLE_NVR_STREAM_SELENIUM_BROWSER_FALLBACK
        and (
            int(last_status or 0) in {400, 403, 405}
            or "notsupport" in str(last_response or "").lower()
            or "not support" in str(last_detail or "").lower()
            or "badxmlcontent" in str(last_response or "").lower()
            or "invalid xml content" in str(last_response or "").lower()
            or "two root tags" in str(last_response or "").lower()
            or "<statuscode>6</statuscode>" in str(last_response or "").lower()
            or "badxmlcontent" in str(last_detail or "").lower()
            or "invalid xml content" in str(last_detail or "").lower()
            or "two root tags" in str(last_detail or "").lower()
            or "unable to create browser-compatible nvr proxy payload" in str(last_detail or "").lower()
            or "preserve-schema" in str(last_detail or "").lower()
            or "existing nvr video block has no" in str(last_detail or "").lower()
        )
    )

    if browser_fallback_candidate:
        print(
            f"[NVR PROXY REPAIR] Stream {stream_channel_id}: requests/"
            "SessionLogin path remains unavailable. Escalating once to the "
            "real Edge/WebSession browser context captured in F12."
        )

        browser_repair = repair_nvr_stream_via_real_browser(
            nvr_ip,
            nvr_username,
            nvr_password,
            stream_channel_id,
            settings,
        )

        if browser_repair.get("ok"):
            return browser_repair

        last_detail = (
            f"{last_detail}; realBrowserFallback={browser_repair.get('detail', '')}"
        )
        last_status = browser_repair.get("status", last_status)
        last_response = browser_repair.get("response", last_response)

    return {
        "ok": False,
        "status": last_status,
        "endpoint": endpoint,
        "detail": last_detail,
        "response": str(last_response or "")[:500],
        "audit": last_audit,
    }

def configure_nvr_camera_stream_settings(
    row,
    expected_camera_map,
    stream_profiles,
    results,
    stream_role="main",
):
    if not is_nvr_device_row(row):
        return

    nvr_ip = get_value(row, "Current IP")
    nvr_username = get_value(row, "Username")
    nvr_password = get_value(row, "Password")

    nvr_stream_web_session = None

    if NVR_STREAM_USE_SESSIONLOGIN_V4 and not DRY_RUN:
        try:
            nvr_stream_web_session = create_nvr_stream_web_session(
                nvr_ip,
                nvr_username,
                nvr_password,
            )
        except Exception as session_error:
            print(
                f"[NVR STREAM SESSION WARNING] {nvr_ip} SessionLogin-v4 "
                f"could not be created: {session_error}"
            )
            print(
                "[NVR STREAM SESSION WARNING] Falling back to the existing "
                "generic authenticated ISAPI PUT path."
            )

    stream_role = str(stream_role or "main").strip().lower()
    is_sub_stream = stream_role in {
        "sub",
        "sub-stream",
        "sub stream",
        "substream",
    }

    task_prefix = (
        "Configure NVR Camera Sub-Stream"
        if is_sub_stream
        else "Configure NVR Camera Stream"
    )

    validation_task = (
        "Validate NVR Camera Sub-Stream Settings"
        if is_sub_stream
        else "Validate NVR Camera Stream Settings"
    )

    stream_role_label = (
        "Sub-Stream"
        if is_sub_stream
        else "Main Stream"
    )

    if not ENABLE_NVR_CAMERA_STREAM_SETTINGS:
        print(
            f"[SKIP] {nvr_ip} NVR camera stream settings disabled."
        )
        add_result(
            results,
            nvr_ip,
            task_prefix,
            NVR_CAMERA_STREAM_SETTINGS_SHEET,
            "",
            "SKIPPED",
            "ENABLE_NVR_CAMERA_STREAM_SETTINGS=False",
        )
        return

    if not DRY_RUN:
        camera_management_ready, dependency_detail = (
            nvr_camera_management_ready_for_streams(
                results,
                nvr_ip,
            )
        )

        if not camera_management_ready:
            print(
                f"[NVR STREAM BLOCKED] {nvr_ip} {stream_role_label}: "
                f"{dependency_detail}"
            )
            add_result(
                results,
                nvr_ip,
                task_prefix,
                NVR_STREAMING_PROXY_ENDPOINT_BASE,
                "",
                "SKIPPED",
                (
                    "Blocked because PASS 5 NVR Camera Management did not "
                    f"complete successfully. {dependency_detail}"
                ),
            )
            return

    if is_sub_stream:
        profile = get_nvr_camera_sub_stream_profile(
            row,
            stream_profiles,
        )
    else:
        profile = get_nvr_camera_stream_profile(
            row,
            stream_profiles,
        )

    if not profile:
        print(
            f"[FAILED] {nvr_ip} stream profile not found in Excel."
        )
        expected_profile_name = (
            DEFAULT_NVR_CAMERA_SUB_STREAM_PROFILE
            if is_sub_stream
            else DEFAULT_NVR_CAMERA_STREAM_PROFILE
        )

        add_result(
            results,
            nvr_ip,
            task_prefix,
            NVR_CAMERA_STREAM_SETTINGS_SHEET,
            "",
            "FAILED",
            (
                f"No NVR camera stream profile found for "
                f"{stream_role_label}. Expected "
                f"'{expected_profile_name}'."
            ),
        )
        return

    try:
        settings = normalized_nvr_stream_profile(
            profile
        )
    except Exception as error:
        print(
            f"[FAILED] {nvr_ip} invalid stream profile: {error}"
        )
        add_result(
            results,
            nvr_ip,
            task_prefix,
            NVR_CAMERA_STREAM_SETTINGS_SHEET,
            "",
            "FAILED",
            str(error),
        )
        return

    if not settings["enabled"]:
        print(
            f"[SKIP] {nvr_ip} stream profile "
            f"{settings['profile_name']} disabled in Excel."
        )
        add_result(
            results,
            nvr_ip,
            task_prefix,
            NVR_CAMERA_STREAM_SETTINGS_SHEET,
            "",
            "SKIPPED",
            (
                f"Profile={settings['profile_name']}; Enabled=No"
            ),
        )
        return

    site, camera_rows = expected_camera_rows_for_nvr(
        row,
        expected_camera_map,
    )

    expected_count = len(camera_rows)

    if expected_count == 0:
        print(
            f"[FAILED] {nvr_ip} no expected cameras found for "
            f"Site {site}."
        )
        add_result(
            results,
            nvr_ip,
            task_prefix,
            NVR_CAMERA_STREAM_SETTINGS_SHEET,
            "",
            "FAILED",
            (
                f"No expected cameras found for Site {site}"
            ),
        )
        return

    suffix_number = int(settings["stream_suffix"])

    print("=" * 100)
    print(
        f"[NVR STREAM] NVR IP          : {nvr_ip}"
    )
    print(
        f"[NVR STREAM] Site ID   : {site}"
    )
    print(
        f"[NVR STREAM] Stream Type     : {stream_role_label}"
    )
    print(
        f"[NVR STREAM] Excel Profile   : "
        f"{settings['profile_name']}"
    )
    print(
        f"[NVR STREAM] Camera Count    : {expected_count}"
    )
    print(
        f"[NVR STREAM] Resolution      : "
        f"{settings['resolution_width']}x"
        f"{settings['resolution_height']}"
    )
    print(
        f"[NVR STREAM] FPS / Bitrate   : "
        f"{settings['frame_rate']} fps / "
        f"{settings['max_bitrate']} Kbps"
    )
    print(
        f"[NVR STREAM] Codec / H.265+  : "
        f"{settings['video_encoding']} / "
        f"{'ON' if settings['smart_codec_enabled'] else 'OFF'}"
    )
    print(
        f"[NVR STREAM] SmartCodec XML   : "
        f"{'INCLUDED' if settings.get('include_smart_codec') else 'OMITTED'}"
    )
    print(
        f"[NVR STREAM] I-Frame Interval: "
        f"{settings['i_frame_interval']}"
    )
    if not is_blank(settings.get("video_scan_type")):
        print(
            f"[NVR STREAM] Scan Type       : "
            f"{settings['video_scan_type']}"
        )

    success_count = 0
    failed_channels = []

    print(
        "[NVR STREAM] PUT authentication : "
        + (
            "SessionLogin v4 / WebSession"
            if nvr_stream_web_session is not None
            else "generic authenticated ISAPI fallback"
        )
    )

    # v126: One UI Save for this Excel profile, with Copy to → Select All.
    # The Main and Sub passes call this once each; per-channel ISAPI remains
    # the fallback only for channels not verified after fresh-page reload.
    bulk_verified_ids=set()
    model_for_bulk=str(
        getattr(nvr_stream_web_session,'device_model','')
        or get_value(row,'Model','Model Number') or ''
    ).upper().strip()
    apply_to_text=normalize_nvr_video_ui_text(get_value(profile,'Apply To'))
    bulk_eligible=(
        NVR_STREAM_Q2_COPY_TO_ALL_ENABLED
        and not DRY_RUN
        and expected_count>1
        and 'DS-E08NI-Q2' in model_for_bulk
        and apply_to_text in {'all expected cameras','all cameras','all'}
    )
    if bulk_eligible:
        print(f'[NVR STREAM COPY ALL] Attempting ONE {stream_role_label} Save '
              f'for D1..D{expected_count}, then verifying every D-channel.')
        bulk=apply_nvr_stream_profile_copy_all_once(
            nvr_ip,nvr_username,nvr_password,expected_count,stream_role_label,settings
        )
        for channel_number,camera_row in enumerate(camera_rows,start=1):
            stream_id=str(channel_number*100+suffix_number)
            if stream_id not in bulk['verified']:
                continue
            phys_detail='disabled'
            if FINAL_CAMERA_STREAM_AUDIT_ENABLED:
                phys_ok,phys_detail,phys_actual,phys_status=(
                    final_physical_camera_stream_audit_and_repair(
                        camera_row,settings,stream_role_label
                    )
                )
                if not phys_ok:
                    print(f'[NVR STREAM COPY ALL WARNING] {stream_id} UI persisted, '
                          f'physical camera audit failed: {phys_detail}. '
                          'Trying individual fallback.')
                    continue
            bulk_verified_ids.add(stream_id)
            success_count+=1
            add_result(
                results,nvr_ip,f'{task_prefix} {stream_id}',
                f'{NVR_STREAMING_PROXY_ENDPOINT_BASE}/{stream_id}',200,'OK',
                (f'Camera D{channel_number}={get_value(camera_row,"Current IP")}; '
                 f'Profile={settings["profile_name"]}; '
                 f'VerificationPath=CopyToSelectAllSingleSave+FullPageReloadPerCamera; '
                 f'UIReadback={bulk["verified"][stream_id]}; '
                 f'PhysicalAudit={phys_detail}')[:1800]
            )
        if len(bulk_verified_ids)==expected_count:
            print(f'[OK] [NVR STREAM COPY ALL] All {expected_count} '
                  f'{stream_role_label} channels persisted after ONE Save.')
            add_result(
                results,nvr_ip,validation_task,
                NVR_STREAMING_PROXY_ENDPOINT_BASE,200,'OK',
                (f'StreamRole={stream_role_label}; Profile={settings["profile_name"]}; '
                 f'Configured={expected_count}/{expected_count}; '
                 'Copy to Select All → OK → Save ONCE; one full page reload; '
                 'all D-channel UI settings persisted and physical audits passed')
            )
            return
        print(f'[NVR STREAM COPY ALL] {len(bulk_verified_ids)}/{expected_count} '
              f'channnels verified. Falling back only for channels not yet verified.')
    elif NVR_STREAM_Q2_COPY_TO_ALL_ENABLED and 'DS-E08NI-Q2' in model_for_bulk:
        print(f'[NVR STREAM COPY ALL SKIPPED] StreamRole={stream_role_label}; '
              f'Apply To={get_value(profile,"Apply To")!r}; Expected={expected_count}. '
              'Bulk requires an explicit All Expected Cameras Excel profile.')

    # v126: successful bulk channels MUST NOT incur duplicate GET/PUT/UI.

    # Some DS-E08NI-Q2 firmware rejects GET on individual StreamingProxy
    # channels while still supporting PUT. Try the collection endpoint once
    # so per-channel XML can still be preserved when available.
    collection_get_status, collection_xml = get_nvr_streaming_proxy(
        nvr_stream_web_session,
        nvr_ip,
        nvr_username,
        nvr_password,
        NVR_STREAMING_PROXY_ENDPOINT_BASE,
    )

    if collection_get_status == 200:
        print(
            "[NVR STREAM] StreamingProxy collection GET is supported; "
            "it will be used as a fallback for individual-channel GET."
        )
    elif is_nvr_stream_get_not_supported(
        collection_get_status,
        collection_xml,
    ):
        print(
            "[NVR STREAM] StreamingProxy collection GET is also unsupported "
            "by this firmware. Direct PUT fallback will be used."
        )
    else:
        print(
            f"[NVR STREAM WARNING] StreamingProxy collection GET returned "
            f"HTTP {collection_get_status}. Direct PUT fallback remains "
            "available if individual GET is not supported."
        )

    stream_channel_rows = list(
        enumerate(
            camera_rows,
            start=1,
        )
    )

    # D1 is commonly the Discreet camera. After Camera Management adds or
    # refreshes the camera, the NVR can briefly restore the camera's previous
    # bitrate. Configure D2..Dn first, then D1 last, and keep the retry logic.
    if (
        NVR_STREAM_CONFIGURE_D1_LAST
        and len(stream_channel_rows) > 1
    ):
        d1_item = stream_channel_rows.pop(0)
        stream_channel_rows.append(d1_item)

        print(
            f"[NVR STREAM] {stream_role_label} apply order: D2..Dn first, "
            "D1 last to allow the Discreet camera/NVR proxy to settle."
        )

    for channel_number, camera_row in stream_channel_rows:
        stream_channel_id = str(
            channel_number * 100
            + suffix_number
        )
        if stream_channel_id in bulk_verified_ids:
            print(f'[NVR STREAM COPY ALL] Stream {stream_channel_id} already '
                  'persisted and audited; skipping redundant configuration.')
            continue

        camera_ip = get_value(
            camera_row,
            "Current IP",
        )

        endpoint = (
            f"{NVR_STREAMING_PROXY_ENDPOINT_BASE}/"
            f"{stream_channel_id}"
        )

        print(
            f"[NVR STREAM] {stream_role_label} / D{channel_number} / "
            f"Stream {stream_channel_id} / Camera {camera_ip}"
        )
        expected_proxy_binding = channel_number

        print(
            f"[NVR STREAM]   NVR-managed proxy binding: "
            f"dynVideoInput={expected_proxy_binding} "
            "(informational only; not an Excel validation field)"
        )

        get_status, current_xml = get_nvr_streaming_proxy(
            nvr_stream_web_session,
            nvr_ip,
            nvr_username,
            nvr_password,
            endpoint,
        )

        individual_get_unsupported = (
            is_nvr_stream_get_not_supported(
                get_status,
                current_xml,
            )
        )

        backup_file = ""
        payload_source = "individual GET"

        if get_status == 200:
            backup_file = save_nvr_camera_stream_backup(
                nvr_ip,
                f"stream_{stream_channel_id}_before",
                current_xml,
            )

        elif individual_get_unsupported:
            print(
                f"[NVR STREAM WARNING] GET stream channel "
                f"{stream_channel_id} is not supported by this NVR firmware "
                f"(HTTP {get_status}/notSupport). This does NOT mean the "
                "stream cannot be configured."
            )

            collection_channel_xml = (
                extract_nvr_stream_channel_from_collection(
                    collection_xml,
                    stream_channel_id,
                )
                if collection_get_status == 200
                else ""
            )

            if collection_channel_xml:
                current_xml = collection_channel_xml
                payload_source = "collection GET"

                backup_file = save_nvr_camera_stream_backup(
                    nvr_ip,
                    f"stream_{stream_channel_id}_before_collection",
                    current_xml,
                )

                print(
                    f"[NVR STREAM] Stream {stream_channel_id} current XML "
                    "recovered from the collection endpoint."
                )
            else:
                current_xml = ""
                payload_source = "direct PUT fallback"

                print(
                    f"[NVR STREAM] Stream {stream_channel_id}: using direct "
                    "PUT payload generated from Excel because readback GET "
                    "is unsupported."
                )

        else:
            detail = (
                f"GET stream channel {stream_channel_id} failed with a "
                f"non-fallback error: HTTP {get_status}; "
                f"response={current_xml[:500]}"
            )
            print(f"[FAILED] {detail}")
            failed_channels.append(stream_channel_id)
            add_result(
                results,
                nvr_ip,
                f"{task_prefix} {stream_channel_id}",
                endpoint,
                get_status,
                "FAILED",
                detail,
            )
            continue

        # v125: Q2 V4.30.200 D2+ returned HTTP 400/badXmlContent for
        # captured StreamingProxy PUT, even when the physical camera and UI
        # could be saved successfully.  Use the proven UI action first for
        # BOTH main/sub streams.  Keep D1 on the established API path.
        model_for_routing = str(
            getattr(nvr_stream_web_session, "device_model", "")
            or get_value(row, "Model", "Model Number")
            or ""
        ).upper().strip()
        use_ui_first = (
            NVR_STREAM_Q2_D2_PLUS_UI_FIRST
            and not DRY_RUN
            and int(channel_number) >= 2
            and "DS-E08NI-Q2" in model_for_routing
        )
        if use_ui_first:
            ui_primary = repair_nvr_stream_via_real_browser(
                nvr_ip,
                nvr_username,
                nvr_password,
                stream_channel_id,
                settings,
                prefer_ui_form=True,
            )
            if ui_primary.get("ok") and ui_primary.get("persisted_ui_verified"):
                # A verified NVR Video/Audio form + verified PHYSICAL camera
                # are both required; a stale proxy FPS=0 is not proof the
                # visible NVR UI remains at Full Frame Rate on this firmware.
                physical_details = "disabled"
                if FINAL_CAMERA_STREAM_AUDIT_ENABLED:
                    phys_ok, physical_details, phys_actual, phys_status = (
                        final_physical_camera_stream_audit_and_repair(
                            camera_row, settings, stream_role_label
                        )
                    )
                    if not phys_ok:
                        detail = (
                            "UI saved and persisted, but physical camera "
                            f"audit failed: {physical_details}"
                        )
                        failed_channels.append(stream_channel_id)
                        add_result(
                            results, nvr_ip,
                            f"{task_prefix} {stream_channel_id}",
                            endpoint, phys_status, "FAILED", detail[:1500],
                        )
                        continue

                success_count += 1
                print(
                    f"[OK] {stream_role_label} stream {stream_channel_id}: "
                    "NVR saved settings persisted after fresh page load; "
                    f"physical camera audit={physical_details}."
                )
                add_result(
                    results, nvr_ip,
                    f"{task_prefix} {stream_channel_id}",
                    endpoint, 200, "OK",
                    (
                        f"Camera D{channel_number}={camera_ip}; "
                        f"Profile={settings['profile_name']}; "
                        f"FPS={settings['frame_rate']}; "
                        f"Resolution={settings['resolution_width']}x"
                        f"{settings['resolution_height']}; "
                        f"Bitrate={settings['max_bitrate']}; "
                        f"Codec={settings['video_encoding']}; "
                        f"IFrame={settings['i_frame_interval']}; "
                        "VerificationPath=Q2 D2+ targeted NVR Video/Audio "
                        "UI fresh-page persisted readback + physical audit; "
                        f"PhysicalCameraAudit={physical_details}; "
                        "Raw NVR proxy PUT intentionally skipped due to "
                        "confirmed firmware badXmlContent response"
                    )[:1800],
                )
                continue
            print(
                f"[NVR STREAM UI FIRST WARNING] Stream {stream_channel_id}: "
                f"{ui_primary.get('detail', 'UI primary path unavailable')}; "
                "trying original ISAPI path without marking UI success."
            )

        try:
            if not is_sub_stream:
                # MAIN STREAM:
                # Use THIS NVR's current XML whenever readable. The previous
                # captured generic template was rejected by some NVRs with
                # HTTP 400, leaving the NVR UI at "Full Frame Rate" even
                # though direct-camera fallback changed the camera itself.
                if current_xml:
                    if should_use_captured_nvr_main_stream_payload(
                        current_xml,
                        stream_channel_id,
                        settings,
                    ):
                        # v121: A newly-bound D2/201 proxy may be readable but
                        # still be a 0x0/VBR/maxFrameRate=0 placeholder.  The
                        # user's successful F12 request proves the minimal
                        # captured payload is the correct initialization form.
                        payload = build_captured_nvr_main_stream_xml(
                            stream_channel_id,
                            settings,
                        )
                        payload_source = (
                            f"{payload_source} + captured browser template "
                            "(placeholder main-stream profile detected)"
                        )
                    else:
                        payload = (
                            update_nvr_streaming_channel_xml_preserve_schema(
                                current_xml,
                                stream_channel_id,
                                settings,
                            )
                        )

                        payload_source = (
                            f"{payload_source} + preserve-schema in-place mutation"
                        )

                else:
                    payload = build_captured_nvr_main_stream_xml(
                        stream_channel_id,
                        settings,
                    )

                    payload_source = (
                        "captured DS-E08NI-Q2 browser main-stream template "
                        "(last-resort; NVR stream XML unreadable)"
                    )

            elif current_xml:
                payload = update_nvr_streaming_channel_xml(
                    current_xml,
                    stream_channel_id,
                    settings,
                )
            else:
                payload = build_nvr_streaming_channel_xml_without_get(
                    stream_channel_id,
                    settings,
                )

            validate_nvr_stream_payload_before_put(
                payload,
                stream_channel_id,
            )
        except Exception as error:
            detail = (
                f"Unable to build/validate stream payload: {error}; "
                f"backup={backup_file}"
            )
            print(f"[FAILED] {detail}")
            failed_channels.append(stream_channel_id)
            add_result(
                results,
                nvr_ip,
                f"{task_prefix} {stream_channel_id}",
                endpoint,
                "",
                "FAILED",
                detail,
            )
            continue

        payload_file = save_nvr_camera_stream_backup(
            nvr_ip,
            f"stream_{stream_channel_id}_payload",
            payload,
        )

        print(
            f"[NVR STREAM] Stream {stream_channel_id} payload source: "
            f"{payload_source}; bytes={len(payload.encode('utf-8'))}."
        )

        if DRY_RUN:
            print(
                f"[DRY RUN] Would PUT stream settings to "
                f"{endpoint}"
            )
            add_result(
                results,
                nvr_ip,
                f"{task_prefix} {stream_channel_id}",
                endpoint,
                "",
                "DRY_RUN",
                (
                    f"Camera={camera_ip}; "
                    f"Profile={settings['profile_name']}; "
                    f"Resolution={settings['resolution_width']}x"
                    f"{settings['resolution_height']}; "
                    f"FPS={settings['frame_rate']}; "
                    f"Bitrate={settings['max_bitrate']}; "
                    f"Payload={payload_file}"
                ),
            )
            continue

        put_status = ""
        put_response = ""
        verify_status = ""
        verify_xml = ""
        actual = {}
        mismatches = []
        applied_successfully = False
        attempt_payload_file = payload_file
        previous_put_was_notsupport = False
        last_apply_attempt = 0

        # Must be defined before any proxy/physical audit. v22 defined this
        # too late, which caused:
        # "cannot access local variable 'verification_path_label'".
        verification_path_label = "NVR StreamingProxy"

        for apply_attempt in range(
            1,
            NVR_STREAM_MAX_APPLY_ATTEMPTS + 1,
        ):
            last_apply_attempt = apply_attempt

            if apply_attempt > 1:
                print(
                    f"[NVR STREAM RETRY] Stream {stream_channel_id} "
                    f"attempt {apply_attempt}/"
                    f"{NVR_STREAM_MAX_APPLY_ATTEMPTS}."
                )

                retry_wait_seconds = (
                    NVR_STREAM_NOTSUPPORT_RETRY_WAIT_SECONDS
                    if previous_put_was_notsupport
                    else NVR_STREAM_RETRY_WAIT_SECONDS
                )

                if previous_put_was_notsupport:
                    print(
                        f"[NVR STREAM RETRY] Previous PUT returned "
                        f"HTTP 403/notSupport. Waiting "
                        f"{retry_wait_seconds:.0f}s for the NVR/camera "
                        "stream binding to settle before retrying."
                    )

                time_module.sleep(
                    retry_wait_seconds
                )

                # Re-read only when this firmware supports the individual
                # GET. If GET is not supported, reuse the already validated
                # direct-PUT payload instead of turning a firmware limitation
                # into a false failure.
                if not individual_get_unsupported:
                    retry_get_status, retry_current_xml = get_nvr_streaming_proxy(
                        nvr_stream_web_session,
                        nvr_ip,
                        nvr_username,
                        nvr_password,
                        endpoint,
                    )

                    if retry_get_status == 200:
                        try:
                            if not is_sub_stream:
                                if should_use_captured_nvr_main_stream_payload(
                                    retry_current_xml,
                                    stream_channel_id,
                                    settings,
                                ):
                                    payload = build_captured_nvr_main_stream_xml(
                                        stream_channel_id,
                                        settings,
                                    )
                                else:
                                    payload = (
                                        update_nvr_streaming_channel_xml_preserve_schema(
                                            retry_current_xml,
                                            stream_channel_id,
                                            settings,
                                        )
                                    )
                            else:
                                payload = update_nvr_streaming_channel_xml(
                                    retry_current_xml,
                                    stream_channel_id,
                                    settings,
                                )

                            validate_nvr_stream_payload_before_put(
                                payload,
                                stream_channel_id,
                            )

                            attempt_payload_file = (
                                save_nvr_camera_stream_backup(
                                    nvr_ip,
                                    (
                                        f"stream_{stream_channel_id}_"
                                        f"retry_{apply_attempt}_payload"
                                    ),
                                    payload,
                                )
                            )
                        except Exception as retry_build_error:
                            print(
                                f"[NVR STREAM RETRY WARNING] "
                                f"Unable to rebuild stream "
                                f"{stream_channel_id} payload: "
                                f"{retry_build_error}. "
                                "Reusing previous payload."
                            )

            if nvr_stream_web_session is not None:
                put_status, put_response = (
                    put_nvr_streaming_proxy_via_web_session(
                        nvr_stream_web_session,
                        endpoint,
                        payload,
                    )
                )
            elif is_sub_stream:
                put_status, put_response = put_xml(
                    nvr_ip,
                    nvr_username,
                    nvr_password,
                    endpoint,
                    payload,
                )
            else:
                put_status, put_response = put_nvr_streaming_proxy_xml(
                    nvr_ip,
                    nvr_username,
                    nvr_password,
                    endpoint,
                    payload,
                )

            if put_status != 200:
                previous_put_was_notsupport = (
                    is_nvr_stream_get_not_supported(
                        put_status,
                        put_response,
                    )
                )

                if previous_put_was_notsupport:
                    print(
                        f"[NVR STREAM RETRY WARNING] Stream "
                        f"{stream_channel_id} PUT attempt "
                        f"{apply_attempt} returned HTTP {put_status}/"
                        "notSupport. The stream endpoint is temporarily "
                        "not ready after Camera Management sync; this is "
                        "treated as a retryable settling condition."
                    )
                else:
                    print(
                        f"[NVR STREAM RETRY WARNING] "
                        f"Stream {stream_channel_id} PUT attempt "
                        f"{apply_attempt} returned HTTP {put_status}."
                    )

                response_lower_for_schema = str(
                    put_response or ""
                ).lower()

                payload_schema_error = (
                    "two root tags" in response_lower_for_schema
                    or (
                        "<substatusstring>tag " in response_lower_for_schema
                        and " is invalid" in response_lower_for_schema
                    )
                    or "badxmlcontent" in response_lower_for_schema
                )

                if payload_schema_error:
                    print(
                        f"[NVR STREAM ERROR] Stream {stream_channel_id} "
                        f"was rejected as payload/schema content on attempt "
                        f"{apply_attempt}. HTTP={put_status}. "
                        f"PayloadSource={payload_source}. "
                        "The script will NOT repeat the identical XML."
                    )
                    previous_put_was_notsupport = False
                    break

                if previous_put_was_notsupport:
                    if apply_attempt < NVR_STREAM_MAX_APPLY_ATTEMPTS:
                        print(
                            f"[NVR STREAM RETRY] Stream {stream_channel_id} "
                            "returned notSupport, but captured D1/D2 browser "
                            "requests prove the endpoint is valid. Retrying the "
                            "NVR proxy before using physical-camera fallback."
                        )
                        continue

                    if NVR_STREAM_ENABLE_DIRECT_CAMERA_FALLBACK:
                        print(
                            f"[NVR STREAM FALLBACK] Stream {stream_channel_id} "
                            f"remained notSupport after {apply_attempt} fast "
                            "NVR proxy attempt(s). Falling back to the physical "
                            "camera, then the explicit NVR proxy repair will "
                            "run again with WebSession GET/PUT."
                        )
                        break

                if apply_attempt < NVR_STREAM_MAX_APPLY_ATTEMPTS:
                    continue

                break

            # Successful PUT: clear transient notSupport state.
            previous_put_was_notsupport = False

            time_module.sleep(
                NVR_STREAM_VERIFY_WAIT_SECONDS
            )

            verify_status, verify_xml = get_nvr_streaming_proxy(
                nvr_stream_web_session,
                nvr_ip,
                nvr_username,
                nvr_password,
                endpoint,
            )

            if verify_status != 200:
                verification_get_unsupported = (
                    is_nvr_stream_get_not_supported(
                        verify_status,
                        verify_xml,
                    )
                )

                if verification_get_unsupported:
                    # Try the collection endpoint once more in case it supports
                    # readback even though /channels/<id> does not.
                    collection_verify_status, collection_verify_xml = get_nvr_streaming_proxy(
                        nvr_stream_web_session,
                        nvr_ip,
                        nvr_username,
                        nvr_password,
                        NVR_STREAMING_PROXY_ENDPOINT_BASE,
                    )

                    collection_channel_xml = (
                        extract_nvr_stream_channel_from_collection(
                            collection_verify_xml,
                            stream_channel_id,
                        )
                        if collection_verify_status == 200
                        else ""
                    )

                    if collection_channel_xml:
                        verify_status = 200
                        verify_xml = collection_channel_xml
                        print(
                            f"[NVR STREAM] Stream {stream_channel_id} "
                            "verification readback obtained from collection "
                            "GET because individual GET is unsupported."
                        )
                    elif nvr_stream_put_response_is_success(
                        put_status,
                        put_response,
                    ):
                        # This exact firmware accepts PUT but rejects GET.
                        # A successful Hikvision statusCode=1/HTTP 200 PUT is
                        # therefore the authoritative result.
                        applied_successfully = True
                        actual = {}
                        mismatches = []

                        print(
                            f"[OK] {stream_role_label} stream "
                            f"{stream_channel_id} PUT accepted by NVR "
                            "(HTTP 200/statusCode=1). Individual verification "
                            "GET is not supported by this firmware, so the "
                            "successful PUT response is used as verification."
                        )
                        break
                    else:
                        print(
                            f"[NVR STREAM RETRY WARNING] Stream "
                            f"{stream_channel_id} GET is unsupported and the "
                            "PUT response did not indicate success."
                        )

                        if (
                            apply_attempt
                            < NVR_STREAM_MAX_APPLY_ATTEMPTS
                        ):
                            continue

                        break
                else:
                    print(
                        f"[NVR STREAM RETRY WARNING] "
                        f"Stream {stream_channel_id} verification "
                        f"GET attempt {apply_attempt} returned "
                        f"HTTP {verify_status}."
                    )

                    if (
                        apply_attempt
                        < NVR_STREAM_MAX_APPLY_ATTEMPTS
                    ):
                        continue

                    break

            actual = read_nvr_streaming_channel_values(
                verify_xml
            )

            mismatches = (
                validate_nvr_streaming_channel_values(
                    actual,
                    stream_channel_id,
                    settings,
                    expected_dynamic_video_input_channel_id=None,
                )
            )

            if not mismatches:
                applied_successfully = True

                if apply_attempt > 1:
                    print(
                        f"[OK] Stream {stream_channel_id} "
                        f"verified after retry attempt "
                        f"{apply_attempt}."
                    )

                break

            print(
                f"[NVR STREAM RETRY WARNING] "
                f"Stream {stream_channel_id} attempt "
                f"{apply_attempt} verification mismatch: "
                f"{mismatches}"
            )

            # A max-bitrate-only mismatch is commonly transient on D1 just
            # after camera synchronisation. Retry instead of immediately
            # marking the channel failed.
            if (
                apply_attempt
                < NVR_STREAM_MAX_APPLY_ATTEMPTS
            ):
                continue

        used_direct_camera_fallback = False
        direct_camera_fallback_detail = ""

        if (
            not applied_successfully
            and NVR_STREAM_ENABLE_DIRECT_CAMERA_FALLBACK
        ):
            fallback_ok, fallback_detail, fallback_actual, fallback_status = (
                configure_camera_stream_direct_fallback(
                    camera_row,
                    settings,
                    stream_role_label,
                )
            )

            direct_camera_fallback_detail = fallback_detail

            if fallback_ok:
                applied_successfully = True
                used_direct_camera_fallback = True
                actual = fallback_actual
                mismatches = []
                put_status = fallback_status

                print(
                    f"[OK] Stream {stream_channel_id} NVR proxy path was "
                    "not usable, but direct camera stream configuration "
                    f"succeeded. {fallback_detail}"
                )
            else:
                print(
                    f"[NVR STREAM FALLBACK FAILED] Stream "
                    f"{stream_channel_id}: {fallback_detail}"
                )

        verification_path_label = (
            "direct camera fallback"
            if used_direct_camera_fallback
            else "NVR StreamingProxy"
        )

        if not applied_successfully:
            if put_status != 200:
                final_notsupport = (
                    is_nvr_stream_get_not_supported(
                        put_status,
                        put_response,
                    )
                )

                if final_notsupport:
                    detail = (
                        f"StreamingProxy remained temporarily unavailable "
                        f"after {last_apply_attempt} attempt(s); "
                        f"last HTTP={put_status}/notSupport. "
                        f"The NVR/camera stream binding did not become ready "
                        f"within the retry window; response={put_response[:500]}; "
                        f"payload={attempt_payload_file}; "
                        f"directCameraFallback={direct_camera_fallback_detail}"
                    )
                else:
                    detail = (
                        f"PUT failed after "
                        f"{NVR_STREAM_MAX_APPLY_ATTEMPTS} attempt(s); "
                        f"last HTTP={put_status}; "
                        f"response={put_response[:500]}; "
                        f"payload={attempt_payload_file}; "
                        f"directCameraFallback={direct_camera_fallback_detail}"
                    )

                result_status = put_status

            elif verify_status != 200:
                detail = (
                    f"PUT succeeded but verification GET failed "
                    f"after {NVR_STREAM_MAX_APPLY_ATTEMPTS} "
                    f"attempt(s); last HTTP={verify_status}; "
                    f"response={verify_xml[:500]}; "
                    f"payload={attempt_payload_file}"
                )
                result_status = verify_status

            else:
                detail = (
                    f"Verification mismatch after "
                    f"{last_apply_attempt} "
                    f"attempt(s): {mismatches}; "
                    f"profile={settings['profile_name']}; "
                    f"actual={actual}; "
                    f"backup={backup_file}; "
                    f"payload={attempt_payload_file}"
                )
                result_status = put_status

            print(
                f"[FAILED] Stream {stream_channel_id}: "
                f"{detail}"
            )

            failed_channels.append(
                stream_channel_id
            )

            add_result(
                results,
                nvr_ip,
                f"{task_prefix} {stream_channel_id}",
                endpoint,
                result_status,
                "FAILED",
                detail[:1500],
            )

            continue

        nvr_proxy_audit_detail = ""

        # Always verify the NVR proxy itself. A successful direct-camera
        # fallback is NOT enough for this project because the NVR Video/Audio
        # page must explicitly store the Excel frame-rate selection too.
        proxy_audit = verify_nvr_proxy_stream_exact_values(
            nvr_ip,
            nvr_username,
            nvr_password,
            stream_channel_id,
            settings,
            nvr_stream_web_session=nvr_stream_web_session,
        )

        if proxy_audit["ok"]:
            nvr_proxy_audit_detail = (
                f"Status={proxy_audit['status']}; "
                "Mismatches=[]"
            )

        elif NVR_PROXY_EXPLICIT_FPS_REPAIR_ENABLED:
            print(
                f"[NVR PROXY AUDIT] Stream {stream_channel_id} "
                "does not match Excel. Running explicit NVR proxy repair."
            )

            proxy_repair = repair_nvr_proxy_stream_exact_values(
                nvr_ip,
                nvr_username,
                nvr_password,
                stream_channel_id,
                settings,
                nvr_stream_web_session=nvr_stream_web_session,
            )

            nvr_proxy_audit_detail = (
                f"RepairOK={proxy_repair['ok']}; "
                f"Detail={proxy_repair['detail']}"
            )

            if not proxy_repair["ok"]:
                detail = (
                    "Physical camera may be configured, but the NVR proxy "
                    "still does not match the Excel stream settings. "
                    "The NVR Video/Audio page can therefore remain on "
                    "'Full Frame Rate'. "
                    f"InitialMismatches={proxy_audit['mismatches']}; "
                    f"RepairDetail={proxy_repair['detail']}"
                )

                print(
                    f"[FAILED] Stream {stream_channel_id}: "
                    f"{detail}"
                )

                failed_channels.append(
                    stream_channel_id
                )

                add_result(
                    results,
                    nvr_ip,
                    f"{task_prefix} {stream_channel_id}",
                    proxy_repair["endpoint"],
                    proxy_repair["status"],
                    "FAILED",
                    detail[:1500],
                )

                continue

            # The repair helper performs final readback verification.
            # When the firmware rejects StreamingProxy GET/PUT for a channel,
            # v120 can repair and verify the exact D-channel/stream directly
            # through the NVR Video/Audio form instead.
            if proxy_repair.get("browser_ui_fallback"):
                verification_path_label = (
                    "NVR Video/Audio UI target verified after "
                    f"{verification_path_label}"
                )
            else:
                verification_path_label = (
                    "NVR StreamingProxy repaired after "
                    f"{verification_path_label}"
                )

        else:
            detail = (
                "NVR proxy readback does not match Excel: "
                f"{proxy_audit['mismatches']}"
            )

            print(
                f"[FAILED] Stream {stream_channel_id}: "
                f"{detail}"
            )

            failed_channels.append(
                stream_channel_id
            )

            add_result(
                results,
                nvr_ip,
                f"{task_prefix} {stream_channel_id}",
                proxy_audit["endpoint"],
                proxy_audit["status"],
                "FAILED",
                detail[:1500],
            )

            continue

        physical_camera_audit_detail = ""

        if FINAL_CAMERA_STREAM_AUDIT_ENABLED:
            physical_ok, physical_camera_audit_detail, physical_actual, physical_status = (
                final_physical_camera_stream_audit_and_repair(
                    camera_row, settings, stream_role_label
                )
            )
            if not physical_ok:
                detail = (
                    f"NVR stream operation completed, but final physical camera audit/repair failed for {camera_ip}: "
                    f"{physical_camera_audit_detail}"
                )
                print(f"[FAILED] Stream {stream_channel_id}: {detail}")
                failed_channels.append(stream_channel_id)
                add_result(
                    results, nvr_ip, f"{task_prefix} {stream_channel_id}",
                    f"/ISAPI/Streaming/channels/{100 + int(settings['stream_suffix'])}",
                    physical_status, "FAILED", detail[:1500],
                )
                continue

        success_count += 1

        smart_codec_log = ""

        if settings.get("include_smart_codec"):
            smart_codec_log = (
                ", H.265+ "
                f"{'ON' if settings['smart_codec_enabled'] else 'OFF'}"
            )

        scan_log = ""

        if not is_blank(settings.get("video_scan_type")):
            scan_log = (
                f", scan={settings['video_scan_type']}"
            )

        print(
            f"[OK] {stream_role_label} stream {stream_channel_id} verified "
            f"via {verification_path_label}: "
            f"{settings['resolution_width']}x"
            f"{settings['resolution_height']}, "
            f"{settings['frame_rate']} fps, "
            f"{settings['max_bitrate']} Kbps, "
            f"{settings['video_encoding']}"
            f"{smart_codec_log}"
            f"{scan_log}, "
            f"I-frame {settings['i_frame_interval']}; "
            f"camera D{channel_number}"
        )


        advisory = ""

        if "riskPassword" in put_response:
            advisory = (
                "; NVR returned riskPassword advisory, "
                "but statusCode=1/HTTP 200 and verification passed"
            )

        add_result(
            results,
            nvr_ip,
            f"{task_prefix} {stream_channel_id}",
            endpoint,
            put_status,
            "OK",
            (
                f"Camera D{channel_number}={camera_ip}; "
                f"Profile={settings['profile_name']}; "
                f"Resolution={settings['resolution_width']}x"
                f"{settings['resolution_height']}; "
                f"Bitrate={settings['bitrate_type']} "
                f"{settings['max_bitrate']} Kbps; "
                f"FPS={settings['frame_rate']}; "
                f"Codec={settings['video_encoding']}; "
                f"ScanType={settings.get('video_scan_type') or 'N/A'}; "
                f"H265Plus="
                f"{('ON' if settings['smart_codec_enabled'] else 'OFF') if settings.get('include_smart_codec') else 'N/A'}; "
                f"IFrame={settings['i_frame_interval']}; "
                f"ApplyAttempts={apply_attempt}; "
                f"PayloadSource={payload_source}; "
                f"VerificationPath={verification_path_label}; "
                f"NVRProxyAudit="
                f"{nvr_proxy_audit_detail or 'direct-camera-fallback'}; "
                f"PhysicalCameraAudit="
                f"{physical_camera_audit_detail or 'disabled'}"
                f"{advisory}"
            ),
        )

    if DRY_RUN:
        return

    if success_count == expected_count and not failed_channels:
        print(
            f"[OK] All {expected_count} NVR camera stream channel(s) "
            f"configured and verified for {nvr_ip}."
        )
        add_result(
            results,
            nvr_ip,
            validation_task,
            NVR_STREAMING_PROXY_ENDPOINT_BASE,
            200,
            "OK",
            (
                f"StreamRole={stream_role_label}; "
                f"Profile={settings['profile_name']}; "
                f"Configured={success_count}/{expected_count}; "
                "all NVR stream operations and physical-camera video/resolution/FPS settings verified"
            ),
        )
    else:
        add_result(
            results,
            nvr_ip,
            validation_task,
            NVR_STREAMING_PROXY_ENDPOINT_BASE,
            "",
            "FAILED",
            (
                f"Configured={success_count}/{expected_count}; "
                f"Failed stream IDs={failed_channels}"
            ),
        )


# =============================================================================
# VALIDATION
# =============================================================================

def validate_after_update(row, results):
    ip = get_value(row, "Current IP", "current_ip")
    source_sheet = get_value(row, "Source Sheet")
    camera_type = get_value(row, "Camera Type")

    validation_endpoints = {
        "deviceInfo_after": "/ISAPI/System/deviceInfo",
        "time_after": "/ISAPI/System/time",
        "ntp_after": "/ISAPI/System/time/ntpServers/1",
    }

    if source_sheet in ["Discreet_Settings", "Dome_Settings"] or "CAM" in camera_type.upper():
        validation_endpoints["video_input_osd_after"] = "/ISAPI/System/Video/inputs/channels/1"
        validation_endpoints["stream_101_after"] = "/ISAPI/Streaming/channels/101"

    for backup_name, endpoint in validation_endpoints.items():
        status, xml_text = backup_endpoint(row, endpoint, backup_name, results)

        if status == 200:
            print(f"[VALIDATE] {ip} {backup_name} OK")
        else:
            print(f"[VALIDATE FAILED] {ip} {backup_name}: {status}")


# =============================================================================
# DEVICE PROCESSING
# =============================================================================

def process_device(
    row,
    results,
    account_security_configurations,
):
    ip = get_value(row, "Current IP", "current_ip")
    source_sheet = get_value(row, "Source Sheet")
    camera_type = get_value(row, "Camera Type", "camera_type")
    hostname = get_value(row, "Hostname", "hostname")
    osd_name = get_value(row, "OSD Name", "osd_name")
    ntp_ip = get_value(row, "NTP IP", "NTP Server IP", "ntp_ip")

    if is_blank(ntp_ip):
        ntp_ip = DEFAULT_NTP_IP

    print("=" * 100)
    print(f"Processing IP     : {ip}")
    print(f"Source Sheet      : {source_sheet}")
    print(f"Camera Type       : {camera_type}")
    print(f"Hostname          : {hostname}")
    print(f"OSD Name          : {osd_name}")
    print(f"NTP IP            : {ntp_ip}")
    print(f"DRY_RUN           : {DRY_RUN}")

    # 1. Hostname for all devices
    update_hostname(row, results)

    # 2. OSD only for Discreet and Dome cameras
    if source_sheet == "NVR_Settings" or "NVR" in camera_type.upper():
        print(f"[SKIP] {ip} NVR detected, skip OSD settings")
        add_result(results, ip, "OSD Update", "", "", "SKIPPED", "NVR device")
    else:
        update_video_input_osd(row, results)
        update_stream_channel_name(row, results)

    # 3. Dome only: read Exposure Time from Dome_Settings and apply it
    # through /ISAPI/Image/channels/1/shutter.
    configure_dome_exposure_time(
        row,
        results
    )

    # 4. Manual time sync first
    manual_sync_enabled = yes_no(
        get_value(row, "Manual Sync With PC Time", "Manual Time Sync", "Manual Time Sync With Computer"),
        default=ENABLE_MANUAL_TIME_SYNC
    )

    if manual_sync_enabled:
        manual_time_sync_with_computer(row, results)
    else:
        print(f"[SKIP] {ip} manual time sync disabled")
        add_result(results, ip, "Manual Time Sync", "", "", "SKIPPED", "Disabled")

    # 5. Update NTP IP
    ntp_enabled = yes_no(
        get_value(row, "Enable NTP", "NTP Enable", "Update NTP"),
        default=ENABLE_NTP_UPDATE
    )

    if ntp_enabled:
        update_ntp_server(row, results)
        switch_back_to_ntp_mode(row, results)
    else:
        print(f"[SKIP] {ip} NTP update disabled")
        add_result(results, ip, "NTP Update", "", "", "SKIPPED", "Disabled")

    # 6. NVR Camera Management is intentionally NOT run here.
    # It is executed in a separate final pass after every NVR and camera has
    # completed hostname, OSD, time, certificate and web-service configuration.

    # Certificate + CSR
    prepare_or_create_self_signed_cert(row, results)
    create_and_download_csr(row, results)

    # Camera only: delete default cert and update Security Audit Log Server
    configure_camera_security_audit_log(row, results)

    # First assign configured certificate to all services
    configure_camera_service_certificates(row, results)

    # Dome only: enable HTTPS Browsing and WebSockets.
    # Account Security Settings is performed later in the dedicated pass.
    enable_dome_https_browsing_via_ui(
        row,
        results,
        account_security_configurations,
    )

    # Discreet only: enable HTTPS Browsing and WebSockets.
    # Account Security Settings is performed later in the dedicated pass.
    enable_discreet_https_and_websockets_via_ui(
        row,
        results,
        account_security_configurations,
    )

    # Account Security Settings for every device type is intentionally
    # deferred to one dedicated pass immediately before User Management.
    # This prevents duplicate browser work and guarantees the requested order.

    # v119 certificate lifecycle safety gate:
    # keep the existing DEVICE_CSR method, but reboot the camera AFTER configured certificate has
    # been assigned to HTTPS/WebSocketS/SDK_OVER_TLS and the web security
    # services have been enabled.  Delete the old default self-signed
    # certificate only when TCP/443, webpage access, authenticated ISAPI and
    # the configured certificate certificate/service bindings all survive that reboot.
    certificate_reboot_ready = (
        reboot_camera_before_default_certificate_delete(
            row,
            results,
        )
    )

    if certificate_reboot_ready:
        delete_default_camera_certificate(row, results)
    elif is_camera_device(row):
        print(
            f"[CERT DELETE BLOCKED] {ip}: pre-delete reboot verification "
            "did not pass. The existing self-signed/default certificate is "
            "being retained intentionally to avoid losing HTTPS access."
        )

        add_result(
            results,
            ip,
            "Delete Default Certificate",
            "",
            "",
            "SKIPPED",
            "Blocked because pre-delete reboot verification did not pass",
        )

    # 6. Validate after actual update
    if not DRY_RUN:
        validate_after_update(row, results)


def get_account_security_address_hints(row):
    """Safe inventory hints only; NEVER automatically choose an alternate IP."""
    hints = []
    for label in (
        "Target IP", "New IP", "Configured IP", "Desired IP",
        "Device Target IP", "IP After Import",
    ):
        value = str(get_value(row, label) or "").strip()
        if value:
            try:
                ipaddress.ip_address(value)
            except ValueError:
                continue
            if value != str(get_value(row, "Current IP", "current_ip") or "").strip():
                hints.append(f"{label}={value}")
    return hints


def account_security_https_preflight(row):
    """
    Fail fast BEFORE creating a WebDriver when HTTPS on Excel Current IP is
    unreachable.  No automatic address rewrites: a reachable alternate IP
    alone does not prove the expected camera's identity.

    Returns (ok, detail).  Port 80/8443 are *diagnostics only*, not
    permission to downgrade to HTTP or switch device-management ports.
    """
    ip = str(get_value(row, "Current IP", "current_ip") or "").strip()

    if not ACCOUNT_SECURITY_NETWORK_PREFLIGHT_ENABLED:
        return True, "HTTPS preflight disabled by operator"

    try:
        ipaddress.ip_address(ip)
    except ValueError:
        return False, f"[NETWORK_PRECHECK] Invalid Excel Current IP: {ip!r}. Correct the workbook."

    port = int(ACCOUNT_SECURITY_NETWORK_PREFLIGHT_PORT)
    attempts = max(1, int(ACCOUNT_SECURITY_NETWORK_PREFLIGHT_ATTEMPTS))
    timeout = max(0.25, float(ACCOUNT_SECURITY_NETWORK_PREFLIGHT_CONNECT_TIMEOUT))
    errors = []

    for attempt in range(1, attempts + 1):
        try:
            with socket.create_connection((ip, port), timeout=timeout):
                if attempt > 1:
                    print(f"[ACCOUNT SECURITY NETWORK] {ip}:{port} reachable on probe {attempt}/{attempts}.")
                return True, f"TCP/{port} accepting connections (probe {attempt}/{attempts})"
        except OSError as exc:
            errors.append(f"{type(exc).__name__}: {str(exc).strip()[:150]}")

        if attempt < attempts:
            time_module.sleep(max(0.0, ACCOUNT_SECURITY_NETWORK_PREFLIGHT_RETRY_WAIT))

    # Diagnostics are bounded and never used to authorize another port.
    other_ports = []
    for other in (80, 8443):
        if other == port:
            continue
        try:
            with socket.create_connection((ip, other), timeout=0.7):
                other_ports.append(f"TCP/{other}=OPEN")
        except OSError:
            other_ports.append(f"TCP/{other}=unreachable")

    local_source_ip = "unavailable"
    try:
        with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as sock:
            sock.connect((ip, port))
            local_source_ip = sock.getsockname()[0]
    except OSError:
        pass

    candidate_hints = get_account_security_address_hints(row)
    hint = ("; Excel possible post-import IP fields: " + ", ".join(candidate_hints)) if candidate_hints else ""

    private_staging_note = ""
    try:
        if ipaddress.ip_address(ip) in ipaddress.ip_network("192.168.0.0/16"):
            private_staging_note = (
                "; A private RFC1918 address may be a staging LAN address: "
                "check the laptop Ethernet/VLAN route and whether config import "
                "moved the device to its final address"
            )
    except ValueError:
        pass

    detail = (
        f"[NETWORK_PRECHECK] HTTPS TCP/{port} unreachable at Excel Current IP={ip} "
        f"after {attempts} bounded probes. "
        f"LastError={errors[-1] if errors else 'unknown'}; "
        f"local route-selected source IP={local_source_ip} "
        "(route hint only); " + "; ".join(other_ports)
        + hint + private_staging_note
        + ". No Edge browser was opened; Account Security was NOT applied. "
        "Do not substitute an alternate IP unless you verify device identity "
        "and update the workbook Current IP for this specific device."
    )
    return False, detail


def account_security_transport_error(error):
    """Classify WebDriver's connection errors, not form/UI logic errors."""
    msg = (str(error) or "").lower()
    return any(token in msg for token in (
        "net::err_connection_timed_out",
        "net::err_address_unreachable",
        "net::err_network_unreachable",
        "net::err_connection_refused",
        "net::err_name_not_resolved",
    ))


def open_account_security_start_page_in_driver(driver, row):
    """Open/login the correct starting page without creating another browser."""
    source_sheet = get_value(row, "Source Sheet")
    camera_type = get_value(row, "Camera Type")
    ip = get_value(row, "Current IP", "current_ip")
    username = get_value(row, "Username", "username")
    password = get_value(row, "Password", "password")

    is_nvr = (
        source_sheet == "NVR_Settings"
        or "NVR" in camera_type.upper()
    )
    is_dome = (
        source_sheet == "Dome_Settings"
        or "DOME" in camera_type.upper()
    )

    if is_dome:
        start_url = (
            f"https://{ip}/doc/index.html"
            f"?t={int(time_module.time() * 1000)}"
        )
    elif is_nvr:
        start_url = (
            f"https://{ip}{DISCREET_CONFIG_PATH}"
            f"?t={int(time_module.time() * 1000)}"
        )
    else:
        start_url = (
            f"https://{ip}{DISCREET_PREVIEW_PATH}"
            f"?t={int(time_module.time() * 1000)}"
        )

    print(
        f"[ACCOUNT SECURITY SAME SESSION] Opening {ip}: {start_url}"
    )
    driver.get(start_url)
    hikvision_web_login_if_needed(
        driver,
        username,
        password,
    )
    time_module.sleep(1.5)
    return True


def configure_account_security_in_existing_driver(
    driver,
    row,
    account_security_configurations,
    results,
):
    """
    Configure Account Security using an already-open driver.

    Returns True for OK/WARNING/SKIPPED states, matching the previous barrier
    semantics.  Actual configuration failures raise to the caller.
    """
    source_sheet = get_value(row, "Source Sheet")
    camera_type = get_value(row, "Camera Type")
    ip = get_value(row, "Current IP", "current_ip")

    task = "Configure Device Account Security Settings"

    if not ENABLE_ACCOUNT_SECURITY_SETTINGS_UI:
        add_result(
            results,
            ip,
            task,
            ACCOUNT_SECURITY_SETTINGS_SHEET,
            "",
            "SKIPPED",
            "ENABLE_ACCOUNT_SECURITY_SETTINGS_UI=False",
        )
        return True

    configuration = get_account_security_settings_for_row(
        row,
        account_security_configurations,
    )

    if not configuration:
        add_result(
            results,
            ip,
            task,
            ACCOUNT_SECURITY_SETTINGS_SHEET,
            "",
            "WARNING",
            f"No configuration found for {source_sheet}",
        )
        print(
            f"[ACCOUNT SECURITY WARNING] {ip}: no configuration found; "
            "continuing to User Management."
        )
        return True

    if not configuration.get("enabled"):
        add_result(
            results,
            ip,
            task,
            ACCOUNT_SECURITY_SETTINGS_SHEET,
            "",
            "SKIPPED",
            "Enabled=No",
        )
        return True

    if DRY_RUN:
        add_result(
            results,
            ip,
            task,
            ACCOUNT_SECURITY_SETTINGS_SHEET,
            "",
            "DRY_RUN",
            "Would configure Account Security Settings in same Edge session.",
        )
        return True

    if source_sheet == "Dome_Settings" or "DOME" in camera_type.upper():
        return configure_dome_account_security_in_driver(
            driver,
            row,
            configuration,
            results,
        )

    if source_sheet == "NVR_Settings" or "NVR" in camera_type.upper():
        return configure_nvr_account_security_in_driver(
            driver,
            row,
            configuration,
            results,
        )

    return configure_discreet_account_security_in_driver(
        driver,
        row,
        configuration,
        results,
    )


def recover_user_management_same_session(driver, row, error_label):
    """Recover User Management without closing/reopening Edge."""
    ip = get_value(row, "Current IP", "current_ip")
    print(
        f"[USER MANAGEMENT SAME SESSION] {ip}: recovering after "
        f"{error_label}; Edge will remain open."
    )

    try:
        driver.switch_to.default_content()
    except Exception:
        pass

    # Refresh is deliberate: it clears a half-open Add dialog while keeping
    # the authenticated browser/WebSession alive.
    try:
        driver.refresh()
        time_module.sleep(0.8)
    except Exception:
        pass

    dismiss_hikvision_success_note(
        driver,
        timeout=1.5,
        label="same-session recovery",
    )

    return open_user_management_page_for_account(
        driver,
        row,
        preserve_current_session=True,
    )


def configure_account_security_then_user_management_device(
    row,
    account_security_configurations,
    accounts,
    nvr_rights_profiles,
    nvr_ui_permission_profiles,
    results,
):
    """
    Options 1/2 per-device workflow:

        open Edge once
          -> Account Security Settings
          -> stay in same authenticated Edge session
          -> Configuration > System > User Management
          -> create missing users
          -> close Edge only after User Management finishes

    Account Security may retry with a fresh browser BEFORE it succeeds.  Once
    it succeeds, User Management recovery never intentionally closes/reopens
    Edge; it refreshes/re-navigates the same session instead.
    """
    ip = get_value(row, "Current IP", "current_ip")

    if not SELENIUM_AVAILABLE:
        detail = "Install Selenium first: python -m pip install selenium"
        add_result(
            results,
            ip,
            "Configure Account Security + User Management",
            "",
            "",
            "FAILED",
            detail,
        )
        return False

    # v127: a TCP failure is a network/address problem, not a Selenium
    # Add User/Account Security problem. Do not launch three doomed Edge windows.
    config = get_account_security_settings_for_row(
        row, account_security_configurations,
    )
    if (ENABLE_ACCOUNT_SECURITY_SETTINGS_UI
            and config and config.get("enabled") and not DRY_RUN):
        reachable, diagnostic = account_security_https_preflight(row)
        if not reachable:
            print(f"[ACCOUNT SECURITY NETWORK BLOCKED] {ip}: {diagnostic}")
            add_result(
                results, ip, "Configure Device Account Security Settings",
                ACCOUNT_SECURITY_SETTINGS_SHEET, "", "FAILED", diagnostic,
            )
            if BLOCK_USER_MANAGEMENT_IF_ACCOUNT_SECURITY_FAILS:
                add_result(
                    results, ip, "Create User Management",
                    "/ISAPI/Security/users", "", "SKIPPED",
                    "Account Security blocked by HTTPS network precheck; "
                    "no account changes attempted.",
                )
                return False
            # Preserve explicitly configured non-blocking semantics.
            return False

    driver = None
    last_security_error = ""

    # Account Security phase.  Fresh browser retries are allowed only until
    # Account Security succeeds.
    security_phase_success = False
    for security_attempt in range(1, ACCOUNT_SECURITY_UI_MAX_ATTEMPTS + 1):
        try:
            print("=" * 100)
            print(
                f"[SAME SESSION] {ip}: Account Security attempt "
                f"{security_attempt}/{ACCOUNT_SECURITY_UI_MAX_ATTEMPTS}"
            )
            print("=" * 100)

            driver = create_hikvision_edge_driver()
            open_account_security_start_page_in_driver(
                driver,
                row,
            )

            configure_account_security_in_existing_driver(
                driver,
                row,
                account_security_configurations,
                results,
            )

            print(
                f"[SAME SESSION] {ip}: Account Security completed. "
                "Checking Edge/WebDriver liveness before User Management."
            )
            if not webdriver_session_is_alive(driver):
                driver = recreate_user_management_driver(
                    row,
                    old_driver=driver,
                    reason="Edge/WebDriver died immediately after Account Security; same-session continuation is impossible",
                )
                add_result(
                    results, ip, "User Management Browser Session Recovery", "Selenium/Edge", "", "WARNING",
                    "Original Edge/WebDriver died after Account Security. Opened one fresh authenticated Edge session for User Management only; Account Security was not repeated.",
                )
            else:
                print(f"[SAME SESSION] {ip}: Edge/WebDriver is alive. Keeping THIS session for User Management.")
            security_phase_success = True
            break

        except Exception as error:
            last_security_error = str(error)
            print(
                f"[ACCOUNT SECURITY RETRY] {ip}: attempt "
                f"{security_attempt}/{ACCOUNT_SECURITY_UI_MAX_ATTEMPTS} "
                f"failed: {last_security_error}"
            )

            if driver is not None:
                try:
                    save_web_ui_debug(
                        driver,
                        ip,
                        f"same_session_account_security_failure_{security_attempt}_v104",
                    )
                except Exception:
                    pass
                try:
                    driver.quit()
                except Exception:
                    pass
                driver = None

            if account_security_transport_error(error):
                alive, check_detail = account_security_https_preflight(row)
                print(f"[ACCOUNT SECURITY TRANSPORT] {ip}: {check_detail}")
                if not alive:
                    last_security_error = (
                        f"{last_security_error}; {check_detail}"
                    )
                    break

            if security_attempt < ACCOUNT_SECURITY_UI_MAX_ATTEMPTS:
                time_module.sleep(
                    ACCOUNT_SECURITY_UI_RETRY_WAIT_SECONDS
                )
    if not security_phase_success:
        add_result(
            results,
            ip,
            "Configure Device Account Security Settings",
            ACCOUNT_SECURITY_SETTINGS_SHEET,
            "",
            "FAILED",
            (
                f"Failed after {ACCOUNT_SECURITY_UI_MAX_ATTEMPTS} "
                f"attempt(s): {last_security_error}"
            ),
        )

        if BLOCK_USER_MANAGEMENT_IF_ACCOUNT_SECURITY_FAILS:
            add_result(
                results,
                ip,
                "Create User Management",
                ACCOUNT_SECURITY_SETTINGS_SHEET,
                "",
                "SKIPPED",
                "Blocked because Account Security Settings failed.",
            )
            return False

    # If failure blocking was disabled and all security attempts failed, open
    # one browser for User Management.  Default project behaviour blocks here.
    if driver is None:
        driver = create_hikvision_edge_driver()
        open_account_security_start_page_in_driver(
            driver,
            row,
        )

    last_user_error = ""

    try:
        for user_attempt in range(1, USER_MANAGEMENT_SAME_SESSION_MAX_ATTEMPTS + 1):
            try:
                print(
                    f"[SAME SESSION] {ip}: User Management attempt "
                    f"{user_attempt}/{USER_MANAGEMENT_SAME_SESSION_MAX_ATTEMPTS} "
                    "using the SAME Edge session."
                )

                ok = configure_user_management_device(
                    row,
                    accounts,
                    nvr_rights_profiles,
                    nvr_ui_permission_profiles,
                    results,
                    existing_driver=driver,
                    close_driver=False,
                    raise_on_error=True,
                )

                if ok:
                    print(
                        f"[SAME SESSION] {ip}: User Management completed "
                        "without reopening Edge after Account Security."
                    )
                    return True

                raise RuntimeError(
                    "User Management returned an unsuccessful status."
                )

            except Exception as error:
                last_user_error = str(error).strip() or f"{type(error).__name__}: {repr(error)}"
                print(
                    f"[USER MANAGEMENT SAME SESSION RETRY] {ip}: attempt "
                    f"{user_attempt}/{USER_MANAGEMENT_SAME_SESSION_MAX_ATTEMPTS} "
                    f"failed: {last_user_error}"
                )

                if is_dead_webdriver_error(error) or not webdriver_session_is_alive(driver):
                    if user_attempt < USER_MANAGEMENT_SAME_SESSION_MAX_ATTEMPTS:
                        try:
                            driver = recreate_user_management_driver(
                                row,
                                old_driver=driver,
                                reason=f"dead WebDriver during User Management attempt {user_attempt}: {last_user_error[:220]}",
                            )
                            add_result(
                                results, ip, "User Management Browser Session Recovery", "Selenium/Edge", "", "WARNING",
                                "Edge/WebDriver died during User Management. Recovered with one fresh authenticated Edge session; backend existing-user precheck keeps the retry idempotent.",
                            )
                            time_module.sleep(0.5)
                            continue
                        except Exception as recovery_error:
                            last_user_error += f"; fresh-session recovery failed: {str(recovery_error).strip() or repr(recovery_error)}"
                    break

                non_retryable_add_user = any(
                    marker in last_user_error.lower()
                    for marker in [
                        "add user validation error",
                        "submitted but creation could not be confirmed",
                    ]
                )

                if non_retryable_add_user:
                    print(
                        f"[USER MANAGEMENT SAME SESSION] {ip}: deterministic "
                        "Add User submission/validation failure detected. "
                        "v118 will NOT blindly refill after a confirmed validation/submission failure."
                    )
                    break

                if user_attempt < USER_MANAGEMENT_SAME_SESSION_MAX_ATTEMPTS:
                    recover_user_management_same_session(
                        driver,
                        row,
                        last_user_error,
                    )
                    time_module.sleep(
                        USER_MANAGEMENT_SAME_SESSION_RETRY_WAIT_SECONDS
                    )

        add_result(
            results,
            ip,
            "Create User Management",
            "/ISAPI/Security/users",
            "",
            "FAILED",
            (
                "Same-session User Management failed after "
                f"{user_attempt} attempt(s): "
                f"{last_user_error}"
            ),
        )
        return False

    finally:
        if driver is not None:
            safe_quit_webdriver(driver)


def run_account_security_then_user_management_batch(
    rows,
    account_security_configurations,
    results,
    excel_path,
    *,
    stage_label="PASS 3",
):
    """Run Options 1/2 Account Security -> User Management same-session flow."""
    rows = list(rows)

    if not rows:
        return

    accounts = read_user_management_accounts(excel_path)
    permission_profiles = read_user_management_permission_profiles(excel_path)
    accounts = attach_user_management_profiles(accounts, permission_profiles)
    nvr_rights_profiles = read_nvr_user_rights_profiles(excel_path)
    nvr_ui_permission_profiles = read_nvr_user_ui_permission_profiles(excel_path)

    max_workers = 1
    if USER_MANAGEMENT_PARALLEL_DEVICES and len(rows) > 1:
        max_workers = min(
            len(rows),
            max(1, USER_MANAGEMENT_PARALLEL_SAFETY_LIMIT),
        )

    print("=" * 100)
    print(
        f"[{stage_label}] SAME-SESSION ACCOUNT SECURITY -> USER MANAGEMENT: "
        f"{len(rows)} device(s); workers={max_workers}."
    )
    print(
        "Each selected device keeps its own Edge window open from the end "
        "of Account Security through User Management."
    )
    print("=" * 100)

    def worker(row):
        local_results = []
        ip = get_value(row, "Current IP", "current_ip")
        ok = configure_account_security_then_user_management_device(
            row,
            account_security_configurations,
            accounts,
            nvr_rights_profiles,
            nvr_ui_permission_profiles,
            local_results,
        )
        return ip, ok, local_results

    if max_workers > 1:
        with ThreadPoolExecutor(max_workers=max_workers) as executor:
            future_map = {
                executor.submit(worker, row): row
                for row in rows
            }

            for future in as_completed(future_map):
                row = future_map[future]
                ip = get_value(row, "Current IP", "current_ip")
                try:
                    finished_ip, ok, local_results = future.result()
                    results.extend(local_results)
                    print(
                        f"[{stage_label}] Same-session device complete: "
                        f"{finished_ip}; status={'OK' if ok else 'FAILED'}"
                    )
                except Exception as error:
                    add_result(
                        results,
                        ip,
                        "Account Security + User Management Worker",
                        "",
                        "",
                        "ERROR",
                        str(error),
                    )
    else:
        for row in rows:
            ip, ok, local_results = worker(row)
            results.extend(local_results)
            print(
                f"[{stage_label}] Same-session device complete: "
                f"{ip}; status={'OK' if ok else 'FAILED'}"
            )

def run_configuration_workflow():
    results = []

    print("=" * 100)
    print("Hikvision Excel Bulk Configuration Script")
    print(f"SCRIPT VERSION : {SCRIPT_VERSION}")
    print(f"RUNNING FILE   : {Path(__file__).resolve()}")
    print(f"Excel File : {DEVICES_EXCEL}")
    print(f"DRY_RUN    : {DRY_RUN}")
    print("=" * 100)

    workflow_start_mode = resolve_workflow_start_mode()

    if workflow_start_mode == "EXIT":
        print(
            "[WORKFLOW] Exit selected. No device changes were attempted."
        )
        return

    run_pass0_config_import = (
        workflow_start_mode == "START_FROM_SCRATCH"
    )

    devices = read_excel_devices(DEVICES_EXCEL)

    if workflow_start_mode == "CREATE_USER_MANAGEMENT":
        if not ENABLE_USER_MANAGEMENT_CREATION:
            raise RuntimeError(
                "ENABLE_USER_MANAGEMENT_CREATION=False"
            )

        print("=" * 100)
        print("OPTION 3: USER MANAGEMENT ONLY")
        print(
            "Account Security Settings is intentionally SKIPPED in Option 3."
        )
        print(
            "All loaded device rows will navigate to "
            "Configuration > System > User Management and create any "
            "missing applicable accounts."
        )
        print("=" * 100)

        run_user_management_only(
            devices,
            results,
            DEVICES_EXCEL,
            write_report_when_done=True,
            eligible_device_ips=None,
            force_all_devices=True,
            stage_label="OPTION 3",
        )

        return

    # Resolve Security Audit Log destinations from matching NVR Current IP.
    nvr_current_ip_map = build_nvr_current_ip_map(
        devices
    )

    attach_resolved_nvr_current_ip(
        devices,
        nvr_current_ip_map,
        results
    )

    account_configuration = (
        read_service_account_configuration(
            DEVICES_EXCEL
        )
    )

    account_security_configurations = (
        read_account_security_settings(
            DEVICES_EXCEL
        )
    )

    nvr_camera_stream_profiles = (
        read_nvr_camera_stream_profiles(
            DEVICES_EXCEL
        )
    )

    expected_camera_map = build_expected_camera_map(
        devices
    )

    camera_rows = [
        row
        for row in devices
        if not is_nvr_device_row(row)
    ]

    nvr_rows = [
        row
        for row in devices
        if is_nvr_device_row(row)
    ]

    print(f"Total devices loaded from Excel: {len(devices)}")
    print(f"Camera rows to configure first  : {len(camera_rows)}")
    print(f"NVR rows to configure afterward : {len(nvr_rows)}")
    print(
        "Sites with expected camera rows: "
        f"{len(expected_camera_map)}"
    )
    print(
        "NVR rows queued for final Camera Management sync: "
        f"{len(nvr_rows)}"
    )

    # =================================================================
    # PASS 0: IMPORT DEVICE PARAMETER CONFIG FOR ALL REQUESTED DEVICES
    # =================================================================
    print("=" * 100)

    if run_pass0_config_import:
        print("PASS 0: IMPORT DEVICE PARAMETER CONFIG - ALL DEVICES")
        print(
            "NVR, Discreet and Dome rows pull their own Device Parameter Config "
            "Path, Device Parameter Config Password, Username and Password from Excel. "
            "PASS 0 uses the confirmed direct encrypted Auth Type 4 GWebPluginService "
            "workflow. Device authentication/AES preparation may run in parallel, but "
            "the local GWebPluginService file-upload transaction is serialized because "
            "the service exposes one reliable async-upload slot. Every requested device "
            "must finish its config-file import "
            "submission first. The processing timer does NOT begin "
            "while any device is still selecting/importing its file. Only after "
            "the final requested device import is submitted successfully will "
            "the shared wait sequence start. After that, all imported "
            "devices are checked in parallel before PASS 1."
        )
    else:
        print("PASS 0: SKIPPED - DEVICE PARAMETER CONFIG IMPORT")
        print(
            "[PASS 0 SKIPPED] User selected SKIP CONFIG FILE IMPORT."
        )
        print(
            "[PASS 0 SKIPPED] No NVR/Discreet/Dome configuration file "
            "will be imported."
        )
        print(
            "[PASS 0 SKIPPED] Shared 150-second processing/reboot wait "
            "and post-import readiness checks are also skipped."
        )
        print(
            "[PASS 0 SKIPPED] Continuing directly to PASS 1: "
            "Configure Settings."
        )

    print("=" * 100)

    config_import_rows = (
        [
            row
            for row in devices
            if device_parameter_config_import_requested(row)
        ]
        if run_pass0_config_import
        else []
    )

    config_import_failures = []
    submitted_import_rows = []

    if config_import_rows:
        print(
            f"[PASS 0] Requested device config imports: "
            f"{len(config_import_rows)}"
        )
        print(
            "[PASS 0] SessionLogin/security preparation can overlap, but "
            "GWebPluginService upload + status polling will run one device "
            "at a time to avoid errorCode=6/errorModule=1."
        )

        def submit_device_config_import(row):
            ok = import_device_parameter_config_direct(
                row,
                results,
                DEVICES_EXCEL,
            )

            return row, ok

        max_import_workers = max(
            1,
            min(
                len(config_import_rows),
                6,
            ),
        )

        with ThreadPoolExecutor(
            max_workers=max_import_workers
        ) as executor:
            futures = [
                executor.submit(
                    submit_device_config_import,
                    row,
                )
                for row in config_import_rows
            ]

            for future in as_completed(futures):
                try:
                    row, import_ok = future.result()
                    ip = get_value(
                        row,
                        "Current IP",
                        "current_ip",
                    )

                    if import_ok:
                        submitted_import_rows.append(row)

                        print(
                            f"[PASS 0 IMPORT COMPLETE] {ip} "
                            f"({get_value(row, 'Source Sheet')}) "
                            "config-file FINAL submission completed successfully."
                        )
                        print(
                            f"[PASS 0 PROGRESS] "
                            f"{len(submitted_import_rows)}/"
                            f"{len(config_import_rows)} device import(s) "
                            "submitted. shared 150-second timer has NOT started yet."
                        )
                    else:
                        config_import_failures.append(ip)

                except Exception as error:
                    print(
                        f"[PASS 0 ERROR] Device config import worker "
                        f"crashed: {error}"
                    )
                    config_import_failures.append(
                        str(error)
                    )

        if config_import_failures:
            print(
                f"[PASS 0 FAILED] Configuration import submission failed "
                f"for: {config_import_failures}"
            )

            if STOP_WORKFLOW_IF_DEVICE_CONFIG_IMPORT_FAILS:
                write_report(results)
                raise RuntimeError(
                    "Stopping before PASS 1 because one or more Device "
                    "Parameter configuration imports could not be submitted."
                )

        if submitted_import_rows:
            requested_import_count = len(config_import_rows)
            submitted_import_count = len(submitted_import_rows)

            if submitted_import_count != requested_import_count:
                raise RuntimeError(
                    "PASS 0 import barrier was not reached: "
                    f"requested={requested_import_count}, "
                    f"submitted={submitted_import_count}. "
                    "The shared processing wait will not start until every "
                    "requested device config import has been submitted."
                )

            print("=" * 100)
            print("[PASS 0 BARRIER] ALL DIRECT CONFIG IMPORTS ACCEPTED")
            print(
                f"[PASS 0 BARRIER] Requested imports : "
                f"{requested_import_count}"
            )
            print(
                f"[PASS 0 BARRIER] Completed imports : "
                f"{submitted_import_count}"
            )
            print(
                "[PASS 0 BARRIER] NVR / Discreet / Dome imports used the "
                "direct GWebPluginService workflow; no PASS 0 Edge browser "
                "is retained."
            )
            print("=" * 100)

            shared_wait_started = time_module.monotonic()
            next_progress = 30

            print(
                f"[PASS 0 WAIT] Starting shared "
                f"{DEVICE_CONFIG_IMPORT_SHARED_WAIT_SECONDS}-second "
                "processing/reboot wait NOW."
            )

            while True:
                elapsed_float = (
                    time_module.monotonic()
                    - shared_wait_started
                )

                if (
                    elapsed_float
                    >= DEVICE_CONFIG_IMPORT_SHARED_WAIT_SECONDS
                ):
                    break

                elapsed = int(elapsed_float)

                if elapsed >= next_progress:
                    remaining = max(
                        0,
                        DEVICE_CONFIG_IMPORT_SHARED_WAIT_SECONDS
                        - elapsed,
                    )

                    print(
                        f"[PASS 0] Shared processing/reboot wait: "
                        f"{elapsed}/"
                        f"{DEVICE_CONFIG_IMPORT_SHARED_WAIT_SECONDS}s, "
                        f"about {remaining}s remaining."
                    )

                    next_progress += 30

                time_module.sleep(0.5)

            print(
                f"[PASS 0] Shared "
                f"{DEVICE_CONFIG_IMPORT_SHARED_WAIT_SECONDS}-second "
                "processing/reboot wait completed."
            )
            print(
                "[PASS 0] Checking all imported devices in parallel now."
            )

            readiness_failures = []

            with ThreadPoolExecutor(
                max_workers=max_import_workers
            ) as executor:
                ready_futures = {
                    executor.submit(
                        wait_for_device_ready_after_shared_config_import,
                        row,
                    ): row
                    for row in submitted_import_rows
                }

                for future in as_completed(ready_futures):
                    row = ready_futures[future]
                    ip = get_value(
                        row,
                        "Current IP",
                        "current_ip",
                    )

                    try:
                        ready, detail = future.result()
                    except Exception as error:
                        ready = False
                        detail = str(error)

                    if ready:
                        print(
                            f"[OK] {ip} is online/authenticated after "
                            "Device Parameter config import."
                        )

                        add_result(
                            results,
                            ip,
                            "Validate Device After Parameter Config Import",
                            "/ISAPI/System/deviceInfo",
                            200,
                            "OK",
                            (
                                "Ready after shared 150-second direct-import "
                                "processing/reboot wait."
                            ),
                        )

                    else:
                        print(
                            f"[FAILED] {ip} post-import readiness: {detail}"
                        )

                        readiness_failures.append(ip)

                        add_result(
                            results,
                            ip,
                            "Validate Device After Parameter Config Import",
                            "/ISAPI/System/deviceInfo",
                            "",
                            "FAILED",
                            detail,
                        )

            if readiness_failures:
                print(
                    f"[PASS 0 FAILED] Devices not ready after import: "
                    f"{readiness_failures}"
                )

                if STOP_WORKFLOW_IF_DEVICE_CONFIG_IMPORT_FAILS:
                    write_report(results)

                    raise RuntimeError(
                        "Stopping before PASS 1 because one or more imported "
                        "devices did not return successfully after the shared "
                        "150-second processing/reboot wait."
                    )

            print(
                "[PASS 0 READY] All imported devices are back online/"
                "authenticated. Proceeding to the next configuration step."
            )
            print(
                "[PASS 0 READY] Direct import stage completed. "
                "Proceeding to PASS 1 / next step."
            )

    else:
        if run_pass0_config_import:
            print(
                "[PASS 0] No rows have Device Parameter Config import enabled "
                "with a file path."
            )
        else:
            print(
                "[PASS 0 SKIPPED] Import process bypassed by workflow selection."
            )

    print("=" * 100)

    if run_pass0_config_import:
        print(
            "PASS 0 COMPLETED: all requested Device Parameter configuration "
            "imports and post-reboot readiness checks are complete."
        )
    else:
        print(
            "PASS 0 SKIPPED: starting directly from PASS 1 "
            "device settings configuration."
        )

    print("=" * 100)

    # =================================================================
    # PASS 1: COMPLETE ALL CAMERA CONFIGURATION FIRST
    # =================================================================
    print("=" * 100)
    print("PASS 1: COMPLETE ALL CAMERA CONFIGURATION")
    print(
        "All Discreet and Dome cameras are fully configured first: "
        "hostname, OSD, stream name, Dome exposure time, time/NTP, "
        "certificates, Security Log Server, HTTPS Browsing, WebSockets, "
        "Account Security Settings and validation."
    )
    print("=" * 100)

    def process_camera_worker(row, worker_index):
        camera_ip = get_value(
            row,
            "Current IP",
            "current_ip",
        )

        camera_started = time_module.perf_counter()

        if PARALLEL_CAMERA_START_DELAY_SECONDS > 0:
            time_module.sleep(
                worker_index
                * PARALLEL_CAMERA_START_DELAY_SECONDS
            )

        print(
            f"[PARALLEL CAMERA] START "
            f"{worker_index + 1}/{len(camera_rows)}: {camera_ip}"
        )

        try:
            process_device(
                row,
                results,
                account_security_configurations,
            )

            device_summary = get_device_result_summary(
                results,
                camera_ip,
            )

            if device_summary["failures"]:
                failure_tasks = "; ".join(
                    record.get("Task", "")
                    for record in device_summary["failures"]
                )

                camera_duration = (
                    time_module.perf_counter()
                    - camera_started
                )

                return (
                    camera_ip,
                    False,
                    failure_tasks,
                    camera_duration,
                )

            camera_duration = (
                time_module.perf_counter()
                - camera_started
            )

            return (
                camera_ip,
                True,
                "",
                camera_duration,
            )

        except Exception as error:
            print(
                f"[ERROR] Camera configuration failed for "
                f"{camera_ip}: {error}"
            )

            add_result(
                results,
                camera_ip,
                "Process Camera Device",
                "",
                "",
                "ERROR",
                str(error),
            )
            camera_duration = (
                time_module.perf_counter()
                - camera_started
            )

            return (
                camera_ip,
                False,
                str(error),
                camera_duration,
            )

    if (
        ENABLE_PARALLEL_CAMERA_CONFIGURATION
        and len(camera_rows) > 1
    ):
        if CONFIGURE_ALL_CAMERAS_AT_ONCE:
            worker_count = len(camera_rows)

            if (
                ALL_CAMERA_PARALLEL_SAFETY_LIMIT
                and worker_count
                > int(ALL_CAMERA_PARALLEL_SAFETY_LIMIT)
            ):
                print(
                    f"[PERFORMANCE WARNING] Workbook contains "
                    f"{worker_count} cameras. Safety limit is "
                    f"{ALL_CAMERA_PARALLEL_SAFETY_LIMIT}; "
                    "cameras will run in parallel batches."
                )

                worker_count = int(
                    ALL_CAMERA_PARALLEL_SAFETY_LIMIT
                )
        else:
            worker_count = min(
                max(
                    1,
                    int(MAX_PARALLEL_CAMERA_WORKERS),
                ),
                len(camera_rows),
            )

        print(
            f"[PERFORMANCE] Camera rows       : "
            f"{len(camera_rows)}"
        )
        print(
            f"[PERFORMANCE] Parallel workers  : "
            f"{worker_count}"
        )

        if (
            CONFIGURE_ALL_CAMERAS_AT_ONCE
            and worker_count == len(camera_rows)
        ):
            print(
                "[PERFORMANCE] ALL CAMERAS AT ONCE enabled. "
                "Every camera gets its own worker and may open "
                "its own Microsoft Edge window."
            )
        else:
            print(
                "[PERFORMANCE] Cameras will run in parallel "
                "batches."
            )

        with ThreadPoolExecutor(
            max_workers=worker_count,
            thread_name_prefix="HikvisionCamera",
        ) as executor:
            future_map = {
                executor.submit(
                    process_camera_worker,
                    row,
                    index,
                ): get_value(row, "Current IP", "current_ip")
                for index, row in enumerate(camera_rows)
            }

            for future in as_completed(future_map):
                camera_ip = future_map[future]

                try:
                    (
                        completed_ip,
                        success,
                        detail,
                        camera_duration,
                    ) = future.result()

                    duration_text, _ = (
                        format_execution_duration(
                            camera_duration
                        )
                    )

                    print(
                        f"[PARALLEL CAMERA] FINISH {completed_ip}; "
                        f"success={success}; "
                        f"duration={duration_text} "
                        f"({camera_duration:.2f}s); "
                        f"detail={detail or 'none'}."
                    )
                except Exception as worker_error:
                    print(
                        f"[ERROR] Camera worker crashed for {camera_ip}: "
                        f"{worker_error}"
                    )

                    add_result(
                        results,
                        camera_ip,
                        "Parallel Camera Worker",
                        "",
                        "",
                        "ERROR",
                        str(worker_error),
                    )

    else:
        print(
            "[PERFORMANCE] Camera configuration is running sequentially."
        )

        for index, row in enumerate(camera_rows):
            process_camera_worker(row, index)

    print("=" * 100)
    print(
        "PASS 1 COMPLETED: Every camera row has finished its "
        "configuration attempt."
    )
    print("=" * 100)

    # =================================================================
    # PASS 2: CONFIGURE NVR DEVICE SETTINGS
    # =================================================================
    print("=" * 100)
    print("PASS 2: CONFIGURE NVR DEVICE SETTINGS")
    print(
        "NVR hostname, time/NTP, certificates and validation are "
        "configured now. Account Security Settings is deferred to PASS 3. "
        "Camera Management is still "
        "deliberately excluded from this pass."
    )
    print("=" * 100)

    for row in nvr_rows:
        nvr_ip = get_value(
            row,
            "Current IP",
            "current_ip",
        )

        try:
            process_device(
                row,
                results,
                account_security_configurations,
            )

        except Exception as error:
            print(
                f"[ERROR] NVR device configuration failed for "
                f"{nvr_ip}: {error}"
            )

            add_result(
                results,
                nvr_ip,
                "Process NVR Device",
                "",
                "",
                "ERROR",
                str(error),
            )

    print("=" * 100)
    print(
        "PASS 2 COMPLETED: NVR device settings have finished. "
        "NVR Camera Management has not run yet."
    )
    print("=" * 100)

    # =================================================================
    # PASS 3 / PASS 4: ACCOUNT SECURITY + USER MANAGEMENT BY OPTION
    # =================================================================
    if workflow_start_mode == "START_FROM_SCRATCH":
        print("=" * 100)
        print("PASS 3: ACCOUNT SECURITY -> USER MANAGEMENT (OPTION 1, SAME EDGE SESSION)")
        print(
            "Option 1 configures BOTH Account Security Settings and User "
            "Management. For every device with User Management Creation = Yes, "
            "the same authenticated Edge window continues directly from Account "
            "Security into Configuration > System > User Management. Edge is not "
            "intentionally closed/reopened between the two operations."
        )
        print("=" * 100)

        selected_user_management_rows = [
            row
            for row in devices
            if user_management_creation_requested(row)
        ]

        account_security_only_rows = [
            row
            for row in devices
            if not user_management_creation_requested(row)
        ]

        print(
            f"[OPTION 1 / PASS 3] Same-session Account Security + User "
            f"Management devices: {len(selected_user_management_rows)}"
        )
        print(
            f"[OPTION 1 / PASS 3] Account Security-only devices "
            f"(User Management Creation != Yes): {len(account_security_only_rows)}"
        )

        run_account_security_then_user_management_batch(
            selected_user_management_rows,
            account_security_configurations,
            results,
            DEVICES_EXCEL,
            stage_label="OPTION 1 / PASS 3",
        )

        if account_security_only_rows:
            run_account_security_settings_batch(
                account_security_only_rows,
                account_security_configurations,
                results,
                stage_label="OPTION 1 / PASS 3 ACCOUNT-SECURITY-ONLY",
            )

        print("=" * 100)
        print("PASS 4: USER MANAGEMENT HANDOFF - COMPLETED IN OPTION 1 PASS 3")
        print(
            "Option 1 User Management has already run immediately after Account "
            "Security in each selected device's same Edge session."
        )
        print("=" * 100)

    elif workflow_start_mode == "SKIP_CONFIG_IMPORT":
        print("=" * 100)
        print("PASS 3: ACCOUNT SECURITY -> USER MANAGEMENT (OPTION 2, SAME EDGE SESSION)")
        print(
            "Option 2 skips only Device Parameter Config import. Account Security "
            "still runs. For every row with User Management Creation = Yes, the "
            "same authenticated Edge session continues directly to Configuration "
            "> System > User Management without closing/reopening Edge."
        )
        print("=" * 100)

        selected_user_management_rows = [
            row
            for row in devices
            if user_management_creation_requested(row)
        ]

        account_security_only_rows = [
            row
            for row in devices
            if not user_management_creation_requested(row)
        ]

        print(
            f"[OPTION 2 / PASS 3] Same-session Account Security + User "
            f"Management devices: {len(selected_user_management_rows)}"
        )
        print(
            f"[OPTION 2 / PASS 3] Account Security-only devices "
            f"(User Management Creation != Yes): {len(account_security_only_rows)}"
        )

        run_account_security_then_user_management_batch(
            selected_user_management_rows,
            account_security_configurations,
            results,
            DEVICES_EXCEL,
            stage_label="OPTION 2 / PASS 3",
        )

        if account_security_only_rows:
            run_account_security_settings_batch(
                account_security_only_rows,
                account_security_configurations,
                results,
                stage_label="OPTION 2 / PASS 3 ACCOUNT-SECURITY-ONLY",
            )

        print("=" * 100)
        print("PASS 4: USER MANAGEMENT HANDOFF - COMPLETED IN OPTION 2 PASS 3")
        print(
            "Option 2 User Management has already run immediately after Account "
            "Security for each selected row, using the same Edge session."
        )
        print("=" * 100)

    # =================================================================
    # PASS 5: FINAL NVR CAMERA MANAGEMENT SYNCHRONISATION
    # =================================================================
    print("=" * 100)
    print("PASS 5: FINAL NVR CAMERA MANAGEMENT SYNC")
    print(
        "All camera configuration has already completed. "
        "The NVR Camera Management list will now be added/updated using "
        "the final camera IPs and ServiceAccount credentials, allowing "
        "the NVR to refresh the completed camera names and OSD information. "
        "Stream/resolution settings from Excel will be applied in Pass 6."
    )
    print("=" * 100)

    if (
        not DRY_RUN
        and NVR_CAMERA_MANAGEMENT_FINAL_WAIT_SECONDS > 0
    ):
        print(
            "[NVR CAMERA MGMT] Waiting "
            f"{NVR_CAMERA_MANAGEMENT_FINAL_WAIT_SECONDS} seconds "
            "before the final Camera Management sync."
        )

        time_module.sleep(
            NVR_CAMERA_MANAGEMENT_FINAL_WAIT_SECONDS
        )

    for row in nvr_rows:
        nvr_ip = get_value(
            row,
            "Current IP",
            "current_ip",
        )

        try:
            print("=" * 100)
            print(
                f"[FINAL STEP] Synchronising NVR Camera Management: "
                f"{nvr_ip}"
            )

            sync_nvr_camera_management(
                row,
                expected_camera_map,
                account_configuration,
                results,
            )

        except Exception as error:
            print(
                f"[ERROR] Final NVR Camera Management sync "
                f"failed for {nvr_ip}: {error}"
            )

            add_result(
                results,
                nvr_ip,
                "Final NVR Camera Management Sync",
                "/ISAPI/ContentMgmt/InputProxy/channels",
                "",
                "ERROR",
                str(error),
            )

    # =================================================================
    # PASS 6: NVR CAMERA STREAM / RESOLUTION SETTINGS FROM EXCEL
    # =================================================================
    print("=" * 100)
    print("PASS 6: NVR MAIN + SUB-STREAM / RESOLUTION SETTINGS")
    print(
        "NVR Camera Management is now complete. The script will first "
        "configure all expected NVR camera Main Stream channels "
        "(101/201/301/401...), then configure all Sub-Stream channels "
        "(102/202/302/402...) using editable Excel profiles."
    )
    print("=" * 100)

    if (
        not DRY_RUN
        and NVR_CAMERA_STREAM_SETTINGS_WAIT_SECONDS > 0
    ):
        print(
            f"[NVR STREAM] Waiting "
            f"{NVR_CAMERA_STREAM_SETTINGS_WAIT_SECONDS} seconds "
            "after Camera Management sync."
        )
        time_module.sleep(
            NVR_CAMERA_STREAM_SETTINGS_WAIT_SECONDS
        )

    print("=" * 100)
    print("PASS 6A: NVR MAIN STREAM SETTINGS")
    print("=" * 100)

    for row in nvr_rows:
        nvr_ip = get_value(
            row,
            "Current IP",
            "current_ip",
        )

        try:
            configure_nvr_camera_stream_settings(
                row,
                expected_camera_map,
                nvr_camera_stream_profiles,
                results,
                stream_role="main",
            )

        except Exception as error:
            print(
                f"[ERROR] NVR Main Stream configuration failed "
                f"for {nvr_ip}: {error}"
            )

            add_result(
                results,
                nvr_ip,
                "Configure NVR Main Stream Settings",
                NVR_STREAMING_PROXY_ENDPOINT_BASE,
                "",
                "ERROR",
                str(error),
            )

    print("=" * 100)
    print("PASS 6B: NVR SUB-STREAM SETTINGS")
    print(
        "Main Stream processing is complete. The script will now apply "
        "the Excel Sub-Stream profile to 102/202/302/402..."
    )
    print("=" * 100)

    for row in nvr_rows:
        nvr_ip = get_value(
            row,
            "Current IP",
            "current_ip",
        )

        try:
            configure_nvr_camera_stream_settings(
                row,
                expected_camera_map,
                nvr_camera_stream_profiles,
                results,
                stream_role="sub",
            )

        except Exception as error:
            print(
                f"[ERROR] NVR Sub-Stream configuration failed "
                f"for {nvr_ip}: {error}"
            )

            add_result(
                results,
                nvr_ip,
                "Configure NVR Sub-Stream Settings",
                NVR_STREAMING_PROXY_ENDPOINT_BASE,
                "",
                "ERROR",
                str(error),
            )


    write_report(results)


def format_execution_duration(total_seconds):
    """
    Return HH:MM:SS and total seconds.
    """
    total_seconds = max(
        0.0,
        float(total_seconds),
    )

    rounded_seconds = int(
        round(total_seconds)
    )

    hours, remainder = divmod(
        rounded_seconds,
        3600,
    )

    minutes, seconds = divmod(
        remainder,
        60,
    )

    return (
        f"{hours:02d}:{minutes:02d}:{seconds:02d}",
        total_seconds,
    )


def main():
    # This tool can modify device accounts, firmware settings, streams, and certificates.
    # Even DRY_RUN has not been independently validated as fully read-only.
    # An operator must explicitly authorize connecting to their own devices.
    if os.getenv("HIKVISION_AUTHORIZE_DEVICE_ACCESS") != "YES":
        print("[SAFETY] Device access is disabled by default.")
        print("[SAFETY] Review the code/workbook and set HIKVISION_AUTHORIZE_DEVICE_ACCESS=YES to opt in.")
        return 2

    script_started_at = datetime.now()
    performance_started_at = (
        time_module.perf_counter()
    )

    print(
        "[EXECUTION TIME] Script started at: "
        f"{script_started_at.strftime('%Y-%m-%d %H:%M:%S')}"
    )

    try:
        return run_configuration_workflow()

    finally:
        script_finished_at = datetime.now()
        total_seconds = (
            time_module.perf_counter()
            - performance_started_at
        )

        formatted_duration, precise_seconds = (
            format_execution_duration(
                total_seconds
            )
        )

        print("=" * 100)
        print(
            "[EXECUTION TIME] Script finished at: "
            f"{script_finished_at.strftime('%Y-%m-%d %H:%M:%S')}"
        )
        print(
            "[EXECUTION TIME] Total duration: "
            f"{formatted_duration} "
            f"({precise_seconds:.2f} seconds)"
        )
        print("=" * 100)


if __name__ == "__main__":
    main()
